	public static class AncientWarHelper
	{
		public static AncientWarRewardConfig GetRewardConfig(int season, int type, int rank)
		{
			int num = season;
			for (int num2 = num; num2 > 0; num2--)
			{
				if (ConfigSingleton<AncientWarRewardConfigCategory>.Instance.Contain(num2 * 1000 + type * 100 + 1))
				{
					num = num2;
					break;
				}
			}
			for (int i = num * 1000 + type * 100 + 1; ConfigSingleton<AncientWarRewardConfigCategory>.Instance.Contain(i); i++)
			{
				AncientWarRewardConfig ancientWarRewardConfig = ConfigSingleton<AncientWarRewardConfigCategory>.Instance.Get(i);
				if (ancientWarRewardConfig.RankLeft <= rank && rank <= ancientWarRewardConfig.RankRight)
				{
					return ancientWarRewardConfig;
				}
			}
			return null;
		}

		public static List<AncientWarRewardConfig> GetRewardConfigs(int season, int type)
		{
			int num = season;
			for (int num2 = num; num2 > 0; num2--)
			{
				if (ConfigSingleton<AncientWarRewardConfigCategory>.Instance.Contain(num2 * 1000 + type * 100 + 1))
				{
					num = num2;
					break;
				}
			}
			List<AncientWarRewardConfig> list = null;
			for (int i = num * 1000 + type * 100 + 1; ConfigSingleton<AncientWarRewardConfigCategory>.Instance.Contain(i); i++)
			{
				AncientWarRewardConfig item = ConfigSingleton<AncientWarRewardConfigCategory>.Instance.Get(i);
				if (list == null)
				{
					list = new List<AncientWarRewardConfig>();
				}
				list.Add(item);
			}
			return list;
		}
