		public static bool IsInDailySettleTime(this BattleGroundModule self)
		{
			long num = TimeHelper.Now();
			long num2 = TimeHelper.EndTimeOfDay(num, 18000000L);
			long num3 = TimeHelper.CommonEndTimeOfDay(num);
			if (num >= num3)
			{
				return num <= num2;
			}
			return false;
		}

