			int freeChallengeCount = ConfigSingleton<BattleGroundGlobalConfigCategory>.Instance.GetOne().FreeChallengeCount;
			return (math.max(0, freeChallengeCount + buyedCount - self.ChallengeCount), freeChallengeCount);
