		private static string ToText(Unit unit)
		{
			if (unit == null)
			{
				return "<n style=\"color: gray\">[NULL]</n>";
			}
			if (unit.GetCamp() == 1)
			{
				return $"<n style=\"color: blue\">[{unit.Config.Name}.Lv{unit.GetLevel()}]</n>";
			}
			return $"<n style=\"color: red\">[{unit.Config.Name}.Lv{unit.GetLevel()}]</n>";
		}

		private static string ToText(this Buff buff)
		{
			BuffConfig config = buff.Config;
			string text = (config.IsDebuff ? "DEBUFF" : "BUFF");
			return string.Format("<n style=\"color: goldenrod\">[{0} {1}:{2}x{3}]</n>", new object[4] { text, config.Name, config.Id, buff.Layer });
		}

		private static string ToSkillText(int skillLevelId)
		{
			if (skillLevelId == 0)
			{
				return "<n style=\"color: orange\">[无技能]</n>";
			}
			ActiveSkillLevelConfig activeSkillLevelConfig = ConfigSingleton<ActiveSkillLevelConfigCategory>.Instance.Get(skillLevelId);
			return $"<n style=\"color: orange\">[{activeSkillLevelConfig.Name}:{skillLevelId}]</n>";
		}

		private static string ToUnitRecoverText(Unit unit, long value)
		{
			long num = ((Entity)unit).GetComponent<NumericComponent>()[NumericType.CurrentHp];
			long num2 = ((Entity)unit).GetComponent<NumericComponent>()[NumericType.CurrentShield];
			return $"(<n style=\"color: green\">{value}</n> <n style=\"color: green\">{num}</n>+{num2})";
		}

		private static string ToHurtUnitText(Unit unit, Damage damage)
		{
			long num = ((Entity)unit).GetComponent<NumericComponent>()[NumericType.CurrentHp];
			long num2 = ((Entity)unit).GetComponent<NumericComponent>()[NumericType.CurrentShield];
			string text = string.Empty;
			if (damage.Type == DamageType.Normal)
			{
				text = "普通";
			}
			if (damage.Type.HasFlag(DamageType.Crit))
			{
				text += "暴击";
			}
			if (damage.Type.HasFlag(DamageType.Bang))
			{
				text += (string.IsNullOrEmpty(text) ? "重击" : "|重击");
			}
			if (damage.Type.HasFlag(DamageType.Block))
			{
				text += (string.IsNullOrEmpty(text) ? "格挡" : "|格挡");
			}
			if (damage.Type.HasFlag(DamageType.Back))
			{
				text += (string.IsNullOrEmpty(text) ? "反伤" : "|反伤");
			}
			return string.Format("(<n style=\"color: red\">{0} {1}</n>+{2} <n style=\"color: green\">{3}</n>+{4})", new object[5]
			{
				text,
				damage.Value - damage.ShieldBlock,
				damage.ShieldBlock,
				num,
				num2
			});
		}
	}
