			{
				BeastModule parent = ((Entity)beast).GetParent<BeastModule>();
				if (parent.PositionBeastMap.GetValueOrDefault(beast.Position) == ((Entity)beast).Id)
				{
					parent.PositionBeastMap.Remove(beast.Position);
				}
				if (position != -1)
				{
					parent.PositionBeastMap[position] = ((Entity)beast).Id;
				}
				beast.Position = position;
			}
		}

		public static bool CanMove(this Beast beast, int targetPosition)
		{
			BeastModule parent = ((Entity)beast).GetParent<BeastModule>();
			if (parent.CheckPositionState(targetPosition) != BeastGridState.Open)
			{
				return false;
			}
			bool item = IsBattlePosition(beast.Position).isBattle;
			bool item2 = IsBattlePosition(targetPosition).isBattle;
			if (item2 && beast.Type == 0)
			{
				return false;
			}
			if (!item2 && parent.GetBeastByPosition(targetPosition) == null)
			{
				return true;
			}
			if (!item && !item2)
			{
				return false;
			}
			Beast beastByPosition = parent.GetBeastByPosition(targetPosition);
			if (beastByPosition != null && beastByPosition.Type == 0 && beast.IsMaxLevel)
			{
				return false;
			}
			HashSetComponent<int> val = HashSetComponent<int>.Create();
			try
			{
				if (item && beastByPosition != null)
				{
					((HashSet<int>)(object)val).Add(beastByPosition.Type);
				}
				if (item2)
				{
					((HashSet<int>)(object)val).Add(beast.Type);
				}
				foreach (BeastBattlePosConfig item3 in ConfigSingleton<BeastBattlePosConfigCategory>.Instance.GetList())
				{
					if (item3.Position != targetPosition && item3.Position != beast.Position)
					{
						Beast beastByPosition2 = parent.GetBeastByPosition(item3.Position);
						if (beastByPosition2 != null && !((HashSet<int>)(object)val).Add(beastByPosition2.Type))
						{
							return false;
						}
					}
				}
				return true;
			}
			finally
			{
				((IDisposable)val)?.Dispose();
			}
		}

