			{
				return 206204;
			}
			if (self.IsLock || target.IsLock)
			{
				return 206240;
			}
			if (self.Grade < 7 || target.Grade < 7)
			{
				return 206221;
			}
			if (self.Config.Type != target.Config.Type)
			{
				return 206222;
			}
			if (self.IsMaxGrade || target.IsMaxGrade)
			{
				return 206224;
			}
			if (self.Grade != target.Grade)
			{
				return 206221;
			}
			return 0;
		}

		public static int CanMerge(this Beast self, Beast target)
		{
			if (target == null)
