		}

		public static long GetTotalExp(this Beast self)
		{
			long num = 0L;
			List<BeastLevelConfig> levelConfigsByType = ConfigSingleton<BeastLevelConfigCategory>.Instance.GetLevelConfigsByType(self.Type);
			if (levelConfigsByType == null || levelConfigsByType.Count <= 0)
			{
				return num;
			}
			int level = self.Level;
			int num2 = 1;
			foreach (BeastLevelConfig item in levelConfigsByType)
			{
				if (level < item.LevelDownValue)
				{
					break;
				}
				long num3 = math.min(item.LevelUpValue - num2, self.Level - num2);
				num += item.Exp * num3;
				num2 = item.LevelUpValue;
			}
			return num;
		}

		public static long GetPower(this Beast self)
		{
			PowerCalc powerCalc = PowerCalc.Create();
			using StatList statList = StatList.Create();
			self.AddStatsToStatList(statList);
			powerCalc.AddStats(statList);
			BeastConfig config = self.Config;
			powerCalc.AddSkill(config.Skill);
			BeastTypeData beastTypeData = ((Entity)self).GetParent<BeastModule>().TypeDataMap?.GetValueOrDefault(config.Type);
			int key;
			int value;
			if (beastTypeData != null && beastTypeData.PassiveSkillMap != null)
			{
				foreach (KeyValuePair<int, int> item in beastTypeData.PassiveSkillMap)
				{
					item.Deconstruct(out key, out value);
					int id = value;
					BeastPassiveSkillConfig beastPassiveSkillConfig = ConfigSingleton<BeastPassiveSkillConfigCategory>.Instance.Get(id);
					if (beastPassiveSkillConfig.SkillLevelId > 0)
					{
						powerCalc.AddSkill(beastPassiveSkillConfig.SkillLevelId);
					}
				}
			}
			if (beastTypeData != null && beastTypeData.SlotSoul != null)
			{
				foreach (KeyValuePair<int, int> item2 in beastTypeData.SlotSoul)
				{
					item2.Deconstruct(out value, out key);
					int id2 = key;
					BeastSoulConfig beastSoulConfig = ConfigSingleton<BeastSoulConfigCategory>.Instance.Get(id2);
					if (beastSoulConfig.SkillLevelId > 0)
					{
						powerCalc.AddSkill(beastSoulConfig.SkillLevelId);
					}
				}
			}
			return powerCalc.Power;
		}

		public static void AddLevelStatsToList(this Beast self, StatList statList)
		{
			List<BeastLevelConfig> levelConfigsByType = ConfigSingleton<BeastLevelConfigCategory>.Instance.GetLevelConfigsByType(self.Type);
			if (levelConfigsByType == null || levelConfigsByType.Count <= 0)
			{
				return;
			}
			int level = self.Level;
			int num = 1;
			foreach (BeastLevelConfig item in levelConfigsByType)
			{
				if (level < item.LevelDownValue)
				{
					break;
				}
				int multiple = math.min(item.LevelUpValue - num, self.Level - num);
				statList.AddRange(item.AddStats, multiple);
				num = item.LevelUpValue;
			}
		}

		public static void AddSkillStatsToList(this Beast self, StatList statList)
		{
			Dictionary<int, int> passiveSkillMap = ((Entity)self).GetParent<BeastModule>().GetPassiveSkillMap(self.Type);
			if (passiveSkillMap == null)
			{
				return;
			}
			foreach (var (_, id) in passiveSkillMap)
			{
				BeastPassiveSkillConfig beastPassiveSkillConfig = ConfigSingleton<BeastPassiveSkillConfigCategory>.Instance.Get(id);
				statList.AddRange(beastPassiveSkillConfig.AddStats);
			}
		}

		public static void AddSoulStatsToList(this Beast self, StatList statList)
		{
			Dictionary<int, BeastTypeData> typeDataMap = ((Entity)self).GetParent<BeastModule>().TypeDataMap;
			if (typeDataMap == null)
			{
				return;
			}
			BeastTypeData valueOrDefault = typeDataMap.GetValueOrDefault(self.Type);
			if (valueOrDefault?.SlotSoul == null)
			{
				return;
			}
			foreach (int value in valueOrDefault.SlotSoul.Values)
			{
				BeastSoulConfig beastSoulConfig = ConfigSingleton<BeastSoulConfigCategory>.Instance.Get(value);
				statList.AddRange(beastSoulConfig.AddStats);
			}
		}

		public static void AddStatsToStatList(this Beast self, StatList statList)
		{
			statList.AddRange(self.Config.Stats);
			self.AddLevelStatsToList(statList);
			self.AddSkillStatsToList(statList);
			self.AddSoulStatsToList(statList);
		}

		public static int CheckCanRaffle(this BeastModule self)
		{
			int num = ((Entity)self).Children.Values.Cast<Beast>().Count((Beast x) => x.IsBattle());
			if (((Entity)self).Children.Count - num >= self.GetBagCount())
