		public static BeastGridState CheckPositionState(this BeastModule self, int position)
		{
			if (position > 10000)
			{
				int num = position - 10000;
				BeastBattlePosConfig beastBattlePosConfig = ConfigSingleton<BeastBattlePosConfigCategory>.Instance.Get(num);
				if (beastBattlePosConfig.Cost != null && !self.IsBuyBattlePosition(num))
				{
					return BeastGridState.Locked_Money;
				}
				if (beastBattlePosConfig.Conds != null && beastBattlePosConfig.Conds.Length != 0 && !((Entity)self).GetParent<Player>().CheckAllConds(beastBattlePosConfig.Conds))
				{
					if (beastBattlePosConfig.Conds[0].Type == 14)
					{
						return BeastGridState.Locked_Privilege;
					}
					return BeastGridState.Locked;
				}
				return BeastGridState.Open;
			}
			position++;
			int bagCount = self.GetBagCount();
			if (position <= bagCount)
			{
				return BeastGridState.Open;
			}
			bagCount += ConfigSingleton<BeastGlobalConfigCategory>.Instance.GetOne().BeastBagBuyCost.Length - self.BagBuyCount;
			if (position <= bagCount)
			{
				return BeastGridState.Locked_Money;
			}
			bagCount += ConfigSingleton<PrivilegeCardConfigCategory>.Instance.Get(1004).GetValue(PrivilegeType.BeastBagUnlockCount) - ((Entity)self.Player).GetComponent<PrivilegeModule>().GetValue(PrivilegeType.BeastBagUnlockCount);
			if (position <= bagCount)
			{
				return BeastGridState.Locked_Privilege;
			}
			return BeastGridState.Locked_Item;
		}

