			BeastTypeData orCreateTypeData = self.GetOrCreateTypeData(beastConfig.Type);
			if (!ConfigSingleton<BeastConfigCategory>.Instance.Contain(orCreateTypeData.BeastId))
			{
				orCreateTypeData.BeastId = beastConfigId;
				return;
			}
			BeastConfig beastConfig2 = ConfigSingleton<BeastConfigCategory>.Instance.Get(orCreateTypeData.BeastId);
			if (beastConfig.Grade > beastConfig2.Grade)
			{
				orCreateTypeData.BeastId = beastConfigId;
			}
		}

