		public static void UpdateSkillList(this BeastModule self)
		{
			if (self.SkillLevelIds == null)
			{
				self.SkillLevelIds = new List<int>();
			}
			self.Power = 0L;
			self.SkillLevelIds.Clear();
			using PowerCalc powerCalc = PowerCalc.Create();
			using SkillList skillList = SkillList.Create();
			foreach (BeastBattlePosConfig item in ConfigSingleton<BeastBattlePosConfigCategory>.Instance.GetList())
			{
				Beast beastByPosition = self.GetBeastByPosition(item.Position);
				if (beastByPosition == null)
				{
					continue;
				}
				BeastConfig config = beastByPosition.Config;
				if (config.Skill > 0)
				{
					skillList.Add(config.Skill);
					powerCalc.AddSkill(config.Skill);
				}
				BeastTypeData beastTypeData = self.TypeDataMap?.GetValueOrDefault(config.Type);
				int key;
				int value;
				if (beastTypeData != null && beastTypeData.PassiveSkillMap != null)
				{
					foreach (KeyValuePair<int, int> item2 in beastTypeData.PassiveSkillMap)
					{
						item2.Deconstruct(out key, out value);
						int id = value;
						BeastPassiveSkillConfig beastPassiveSkillConfig = ConfigSingleton<BeastPassiveSkillConfigCategory>.Instance.Get(id);
						if (beastPassiveSkillConfig.SkillLevelId > 0)
						{
							skillList.Add(beastPassiveSkillConfig.SkillLevelId);
							powerCalc.AddSkill(beastPassiveSkillConfig.SkillLevelId);
						}
					}
				}
				if (beastTypeData == null || beastTypeData.SlotSoul == null)
				{
					continue;
				}
				foreach (KeyValuePair<int, int> item3 in beastTypeData.SlotSoul)
				{
					item3.Deconstruct(out value, out key);
					int id2 = key;
					BeastSoulConfig beastSoulConfig = ConfigSingleton<BeastSoulConfigCategory>.Instance.Get(id2);
					if (beastSoulConfig.SkillLevelId > 0)
					{
						skillList.Add(beastSoulConfig.SkillLevelId);
						powerCalc.AddSkill(beastSoulConfig.SkillLevelId);
					}
				}
			}
			self.Power = powerCalc.Power;
			self.SkillLevelIds.AddRange(skillList);
		}

