		public static (bool, long) CanUpLevel(this BeastModule self, Beast beast, int needLevel, long haveNum, StatList needStat = null)
		{
			List<BeastLevelConfig> levelConfigsByType = ConfigSingleton<BeastLevelConfigCategory>.Instance.GetLevelConfigsByType(beast.Type);
			int num = 1;
			long num2 = 0L;
			long num3 = haveNum;
			BeastLevelConfig beastLevelConfig = null;
			while (true)
			{
				if (beastLevelConfig == null || beast.Level + num > beastLevelConfig.LevelUpValue)
				{
					foreach (BeastLevelConfig item in levelConfigsByType)
					{
						if (item.LevelUpValue >= beast.Level + num)
						{
							beastLevelConfig = item;
							break;
						}
					}
				}
				if (beastLevelConfig == null)
				{
					return (false, 0L);
				}
				if (num3 - beastLevelConfig.Exp < 0)
				{
					return (false, 0L);
				}
				num3 -= beastLevelConfig.Exp;
				num2 += beastLevelConfig.Exp;
				needStat?.AddRange(beastLevelConfig.AddStats);
				if (num == needLevel)
				{
					break;
				}
				num++;
			}
			return (true, num2);
		}

