		{
			if (self.SkillLevelIds != null)
			{
				return self.SkillLevelIds;
			}
			self.UpdateSkillList();
			return self.SkillLevelIds;
		}

		public static BeastCommonInfo GetCommonInfo(this BeastModule self)
		{
			if (self.TypeDataMap == null)
			{
				return null;
			}
			ListComponent<long> val = ListComponent<long>.Create();
			try
			{
				foreach (BeastBattlePosConfig value in ConfigSingleton<BeastBattlePosConfigCategory>.Instance.GetAll().Values)
				{
					long valueOrDefault = self.PositionBeastMap.GetValueOrDefault(value.Position);
					if (valueOrDefault != 0L)
					{
						((List<long>)(object)val).Add(valueOrDefault);
					}
				}
				if (((List<long>)(object)val).Count == 0)
				{
					return null;
				}
				BeastCommonInfo beastCommonInfo = new BeastCommonInfo();
				beastCommonInfo.SkillLevelIds = self.GetSkillLevelIds().Clone();
				beastCommonInfo.Beasts = new List<int>();
				foreach (long item in (List<long>)(object)val)
				{
					beastCommonInfo.Beasts.Add(((Entity)self).GetChild<Beast>(item).ConfigId);
				}
				Hero roleHero = self.Player.GetRoleHero();
				beastCommonInfo.Level = roleHero.GetLevel();
				beastCommonInfo.Stats = roleHero.GetFinalStats()?.Clone();
				return beastCommonInfo;
			}
			finally
			{
				((IDisposable)val)?.Dispose();
			}
		}
	}
