	[BuffHandler(1)]
	public class BuffHandler_Stats : ABuffHandler
	{
		private static void OnMaxHpChange(NumericComponent numericComponent, long oldValue, long newValue)
		{
			long num = newValue - oldValue;
			if (num <= 0)
			{
				if (num < 0)
				{
					long num2 = numericComponent[NumericType.CurrentHp];
					numericComponent[NumericType.CurrentHp] = math.min(num2, newValue);
				}
			}
			else
			{
				long num3 = numericComponent[NumericType.CurrentHp];
				numericComponent[NumericType.CurrentHp] = math.min(num3 + num, newValue);
			}
		}

		public override void ChangeLevel(Buff self, int lastConfigId, long lastEffectValue)
		{
			Unit owner = self.Owner;
			BuffConfig buffConfig = ConfigSingleton<BuffConfigCategory>.Instance.Get(lastConfigId);
			NumericComponent component = ((Entity)owner).GetComponent<NumericComponent>();
			long oldValue = component[NumericType.MaxHpFinal];
			Stat[] addStats = buffConfig.AddStats;
			foreach (Stat stat in addStats)
			{
				component[(NumericType)(stat.Type + 200)] -= self.Layer * stat.Value;
			}
			addStats = self.Config.AddStats;
			foreach (Stat stat2 in addStats)
			{
				component[(NumericType)(stat2.Type + 200)] += self.Layer * stat2.Value;
			}
			OnMaxHpChange(component, oldValue, component[NumericType.MaxHpFinal]);
		}

		public override void ChangeLayer(Buff self, int lastLayer, long lastEffectValue)
		{
			Unit owner = self.Owner;
			BuffConfig config = self.Config;
			NumericComponent component = ((Entity)owner).GetComponent<NumericComponent>();
			long oldValue = component[NumericType.MaxHpFinal];
			if (lastLayer > 0)
			{
				Stat[] addStats = config.AddStats;
				foreach (Stat stat in addStats)
				{
					component[(NumericType)(stat.Type + 200)] -= lastLayer * stat.Value;
				}
			}
			if (self.Layer > 0)
			{
				Stat[] addStats = config.AddStats;
				foreach (Stat stat2 in addStats)
				{
					component[(NumericType)(stat2.Type + 200)] += self.Layer * stat2.Value;
				}
			}
			OnMaxHpChange(component, oldValue, component[NumericType.MaxHpFinal]);
		}
	}
