	[FriendOf(typeof(BuffComponent))]
	[BuffHandler(14)]
	public class BuffHandler_Super : ABuffHandler
	{
		public override void ChangeLevel(Buff self, int lastConfigId, long lastEffectValue)
		{
			BuffComponent parent = ((Entity)self).GetParent<BuffComponent>();
			BuffConfig config = self.Config;
			int[] effectParams = config.EffectParams;
			if (effectParams != null && effectParams.Length > 0)
			{
				effectParams = config.EffectParams;
				foreach (int effectType in effectParams)
				{
					parent.AddRepelDeBuffEffectType(effectType);
				}
			}
			BuffConfig buffConfig = ConfigSingleton<BuffConfigCategory>.Instance.Get(lastConfigId);
			effectParams = buffConfig.EffectParams;
			if (effectParams != null && effectParams.Length > 0)
			{
				effectParams = buffConfig.EffectParams;
				foreach (int effectType2 in effectParams)
				{
					parent.DelRepelDeBuffEffectType(effectType2);
				}
			}
		}

		public override void ChangeLayer(Buff self, int lastLayer, long lastEffectValue)
		{
			if (lastLayer != 0)
			{
				return;
			}
			BuffConfig config = self.Config;
			int[] effectParams = config.EffectParams;
			if (effectParams == null || effectParams.Length <= 0)
			{
				return;
			}
			BuffComponent parent = ((Entity)self).GetParent<BuffComponent>();
			HashSetComponent<int> val = HashSetComponent<int>.Create();
			try
			{
				effectParams = config.EffectParams;
				foreach (int num in effectParams)
				{
					((HashSet<int>)(object)val).Add(num);
					parent.AddRepelDeBuffEffectType(num);
				}
				foreach (long item in parent.UpdateQueue)
				{
					if (item != ((Entity)self).Id && ((Entity)parent).GetChild<Buff>(item) != null)
					{
						BuffConfig config2 = self.Config;
						if (config2.IsDebuff && ((HashSet<int>)(object)val).Contains(config2.EffectType))
						{
							parent.RemoveBuffByGroup(config2.Group);
						}
					}
				}
			}
			finally
			{
				((IDisposable)val)?.Dispose();
			}
		}
	}
