		public static void Load(this CondComponent self)
		{
			if (self.CondHandlers == null)
			{
				self.CondHandlers = new Dictionary<int, ACondHandler>();
			}
			foreach (Type type in Singleton<EventSystem>.Instance.GetTypes(typeof(CondHandlerAttribute)))
			{
				if (Activator.CreateInstance(type) is ACondHandler aCondHandler)
				{
					CondHandlerAttribute customAttribute = ((MemberInfo)type).GetCustomAttribute<CondHandlerAttribute>();
					aCondHandler.Type = customAttribute.Type;
					self.CondHandlers.Add(customAttribute.Type, aCondHandler);
				}
			}
		}

		public static bool IsMeet(this CondComponent self, Player player, int type, int intValue = 0, long longValue = 0L)
		{
			if (!self.CondHandlers.ContainsKey(type))
			{
				Log.Error($"未找到条件类型：{type}，请相关的同学添加~~~");
				return true;
			}
			return self.CondHandlers.GetValue(type).IsMeet(player, intValue, longValue);
		}

		public static bool IsEqual(this CondComponent self, Player player, int type, int intValue = 0, long longValue = 0L)
		{
			if (!self.CondHandlers.ContainsKey(type))
			{
				Log.Error($"未找到条件类型：{type}，请相关的同学添加~~~");
				return true;
			}
			return self.CondHandlers.GetValue(type).IsEqual(player, intValue, longValue);
		}

		public static string GetDesc(this CondComponent self, Player player, int type, int intValue = 0, long longValue = 0L)
		{
			if (!self.CondHandlers.ContainsKey(type))
			{
				Log.Error($"未找到条件类型：{type}，请相关的同学添加~~~");
				return "未知的条件类型";
			}
			return self.CondHandlers.GetValue(type).GetDesc(player, intValue, longValue);
		}

		public static string GetShopDesc(this CondComponent self, Player player, int type, int intValue = 0, long longValue = 0L)
		{
			if (!self.CondHandlers.ContainsKey(type))
			{
				Log.Error($"未找到条件类型：{type}，请相关的同学添加~~~");
				return "未知的条件类型";
			}
			return self.CondHandlers.GetValue(type).GetShopDesc(player, intValue, longValue);
		}
	}
	public static class CondHelper
	{
		public static string GetCondText(this Player player, int funcId)
		{
			if (!ConfigSingleton<FuncConfigCategory>.Instance.Contain(funcId))
			{
				return $"未找到条件Id：{funcId}";
			}
			FuncConfig funcConfig = ConfigSingleton<FuncConfigCategory>.Instance.Get(funcId);
			return player.GetCondText(funcConfig.OpenConds);
		}

		public static string GetCondText(this Player player, Cond cond)
		{
			return ((Entity)SceneHelper.DomainScene((Entity)(object)player)).GetComponent<CondComponent>().GetDesc(player, cond.Type, cond.intValue, cond.longValue);
		}

		public static string GetShopCondText(this Player player, Cond cond)
		{
			return ((Entity)SceneHelper.DomainScene((Entity)(object)player)).GetComponent<CondComponent>().GetShopDesc(player, cond.Type, cond.intValue, cond.longValue);
		}

		public static string GetShopCondText(this Player player, Cond[] conds)
		{
			foreach (Cond cond in conds)
			{
				if (!player.CheckCond(cond))
				{
					return player.GetShopCondText(cond);
				}
			}
			return string.Empty;
		}

		public static string GetCondText(this Player player, Cond[] conds)
		{
			foreach (Cond cond in conds)
			{
				if (!player.CheckCond(cond))
				{
					return player.GetCondText(cond);
				}
			}
			return "条件全部已达成";
		}

		public static bool CheckCond(this Player player, Cond cond)
		{
			return ((player != null) ? ((Entity)SceneHelper.DomainScene((Entity)(object)player)).GetComponent<CondComponent>() : null).IsMeet(player, cond.Type, cond.intValue, cond.longValue);
		}

		public static bool EqualCond(this Player player, Cond cond)
		{
			return ((Entity)SceneHelper.DomainScene((Entity)(object)player)).GetComponent<CondComponent>().IsEqual(player, cond.Type, cond.intValue, cond.longValue);
		}

		public static bool CheckAllConds(this Player player, Cond[] conds)
		{
			if (conds == null || conds.Length == 0)
			{
				return true;
			}
			foreach (Cond cond in conds)
			{
				if (!player.CheckCond(cond))
				{
					return false;
				}
			}
			return true;
		}

		public static bool CheckAllConds(this Player player, List<Cond> conds)
		{
			if (conds == null || conds.Count == 0)
			{
				return true;
			}
			foreach (Cond cond in conds)
			{
				if (!player.CheckCond(cond))
				{
					return false;
				}
			}
			return true;
		}

		public static bool CheckAnyConds(this Player player, Cond[] conds)
		{
			if (conds == null || conds.Length == 0)
			{
				return true;
			}
			foreach (Cond cond in conds)
			{
				if (player.CheckCond(cond))
				{
					return true;
				}
			}
			return false;
		}
	}
