	[CondHandler(25)]
	[FriendOf(typeof(BeastModule))]
	public class Cond_BeastGrade : ACondHandler
	{
		public override bool IsMeet(Player player, int beastType = 0, long targetGrade = 0L)
		{
			BeastModule component = ((Entity)player).GetComponent<BeastModule>();
			int num = 0;
			if (component.TypeDataMap != null)
			{
				if (beastType > 0)
				{
					int num2 = component.TypeDataMap.GetValueOrDefault(beastType)?.BeastId ?? 0;
					if (num2 > 0)
					{
						num = ConfigSingleton<BeastConfigCategory>.Instance.Get(num2).Grade;
					}
				}
				else
				{
					foreach (BeastTypeData value in component.TypeDataMap.Values)
					{
						if (value.BeastId > 0)
						{
							num = math.max(ConfigSingleton<BeastConfigCategory>.Instance.Get(value.BeastId).Grade, num);
						}
					}
				}
			}
			return num >= targetGrade;
		}

		public override string GetDesc(Player player, int beastType = 0, long grade = 0L)
		{
			string text = "任意";
			if (beastType > 0)
			{
				text = ConfigSingleton<BeastTypeConfigCategory>.Instance.Get(beastType)?.Name ?? string.Empty;
			}
			return string.Format(text + "神兽到达" + (ConfigSingleton<BeastGradeConfigCategory>.Instance.Get((int)grade)?.Name ?? string.Empty) + "解锁", Array.Empty<object>());
		}
	}
