			if (intValue == 0)
			{
				foreach (KeyValuePair<long, Entity> child2 in ((Entity)((Entity)player).GetComponent<RaffleModule>()).Children)
				{
					if ((child2.Value as Raffle).TotalCount >= longValue)
					{
						return true;
					}
				}
			}
			if (intValue == -1)
			{
				int num = 0;
				foreach (KeyValuePair<long, Entity> child3 in ((Entity)((Entity)player).GetComponent<RaffleModule>()).Children)
				{
					Raffle raffle = child3.Value as Raffle;
					num += raffle.TotalCount;
				}
				return num >= longValue;
			}
			Raffle child = ((Entity)((Entity)player).GetComponent<RaffleModule>()).GetChild<Raffle>((long)intValue);
			if (child == null)
			{
				return false;
			}
			return child.TotalCount >= longValue;
		}

		public override bool IsEqual(Player player, int intValue = 0, long longValue = 0L)
		{
			if (intValue == 0)
			{
				foreach (KeyValuePair<long, Entity> child in ((Entity)((Entity)player).GetComponent<RaffleModule>()).Children)
				{
					if ((child.Value as Raffle).TotalCount == longValue)
					{
						return true;
					}
				}
			}
			if (intValue == -1)
			{
				int num = 0;
				foreach (KeyValuePair<long, Entity> child2 in ((Entity)((Entity)player).GetComponent<RaffleModule>()).Children)
				{
					Raffle raffle = child2.Value as Raffle;
					num += raffle.TotalCount;
				}
				return num == longValue;
			}
			return ((Entity)((Entity)player).GetComponent<RaffleModule>()).GetChild<Raffle>((long)intValue).TotalCount == longValue;
		}

		public override string GetDesc(Player player, int intValue = 0, long longValue = 0L)
