	[CondHandler(7)]
	public class Cond_Task : ACondHandler
	{
		public override bool IsMeet(Player player, int intValue = 0, long longValue = 0L)
		{
			((Entity)player).GetComponent<TaskModule>().FinishTaskDict.TryGetValue(intValue, out var value);
			return value > 0;
		}

		public override string GetDesc(Player player, int intValue = 0, long longValue = 0L)
		{
			if (!ConfigSingleton<TaskConfigCategory>.Instance.Contain(intValue))
			{
				return "未找到任务";
			}
			TaskModule component = ((Entity)player).GetComponent<TaskModule>();
			List<TaskMainConfig> list = ConfigSingleton<TaskMainConfigCategory>.Instance.GetAll().Values.ToList();
			list.Sort((TaskMainConfig a, TaskMainConfig b) => a.Id - b.Id);
			int num = -1;
			int num2 = -1;
			int num3 = 0;
			for (int num4 = 0; num4 < list.Count; num4++)
			{
				int[] tasks = list[num4].Tasks;
				if (Array.IndexOf(tasks, intValue) != -1)
				{
					num = num3 + Array.IndexOf(tasks, intValue);
				}
				if (Array.IndexOf(tasks, component.MainTaskId) != -1)
				{
					num2 = num3 + Array.IndexOf(tasks, component.MainTaskId);
				}
				num3 += tasks.Length;
			}
			if (num - num2 >= 0)
			{
				return $"再完成<color=#0db64d>{num - num2 + 1}</color>个主线任务解锁";
			}
			return $"完成第<color=#0db64d>{num + 1}</color>个任务解锁";
		}
	}
