	[FriendOf(typeof(DailyDupModule))]
	public static class DailyDupHelper
	{
		public static void CheckAndResetData(this DailyDupModule self)
		{
			long num = TimeHelper.Now();
			if (TimeHelper.IsSameDay(num, self.DailyResetTime, 18000000L))
			{
				return;
			}
			if (self.DailyDupDataMap != null)
			{
				foreach (DailyDupData value in self.DailyDupDataMap.Values)
				{
					value.FightCount = 0;
				}
			}
			self.DailyResetTime = num;
		}

		public static DailyDupData GetOrCreateDailyDupData(this DailyDupModule self, DupType dupType)
		{
			self.CheckAndResetData();
			if (self.DailyDupDataMap == null)
			{
				Dictionary<int, DailyDupData> dictionary = (self.DailyDupDataMap = new Dictionary<int, DailyDupData>());
			}
			if (!self.DailyDupDataMap.TryGetValue((int)dupType, out var value))
			{
				value = new DailyDupData
				{
					Type = (int)dupType
				};
				self.DailyDupDataMap.Add((int)dupType, value);
			}
			return value;
		}

		public static int GetCurrentLevel(this DailyDupModule self, DupType dupType)
		{
			if (self.DailyDupDataMap == null || !self.DailyDupDataMap.TryGetValue((int)dupType, out var value))
			{
				return 0;
			}
			return value.Level;
		}

		public static int GetMaxFightCountForShow(this DailyDupModule self, DupType dupType)
		{
			int maxFightCount = self.GetMaxFightCount(dupType);
			int num = PrivilegeHelper.GetBuyedCount(priceType: ConfigSingleton<DailyDupConfigCategory>.Instance.Get((int)dupType).PriceType, player: self.Player);
			return maxFightCount + num;
		}

		public static int GetMaxFightCount(this DailyDupModule self, DupType dupType)
		{
			int num = 0;
			switch (dupType)
			{
			case DupType.DailyMatDup:
				num = ((Entity)self.Player).GetComponent<PrivilegeModule>().GetValue(PrivilegeType.CLDailyDefaultCount);
				break;
			case DupType.DailyReikiDup:
				num = ((Entity)self.Player).GetComponent<PrivilegeModule>().GetValue(PrivilegeType.LQDailyDefaultCount);
				break;
			case DupType.DailySilverDup:
				num = ((Entity)self.Player).GetComponent<PrivilegeModule>().GetValue(PrivilegeType.YBDailyDefaultCount);
				break;
			}
			return ConfigSingleton<DailyDupConfigCategory>.Instance.Get((int)dupType).FightCount + num;
		}

		public static int GetLeftFightCount(this DailyDupModule self, DupType dupType)
		{
			int num = 0;
			switch (dupType)
			{
			case DupType.DailyMatDup:
				num = ((Entity)self.Player).GetComponent<PrivilegeModule>().GetValue(PrivilegeType.CLDailyDefaultCount);
				break;
			case DupType.DailyReikiDup:
				num = ((Entity)self.Player).GetComponent<PrivilegeModule>().GetValue(PrivilegeType.LQDailyDefaultCount);
				break;
			case DupType.DailySilverDup:
				num = ((Entity)self.Player).GetComponent<PrivilegeModule>().GetValue(PrivilegeType.YBDailyDefaultCount);
				break;
			}
			DailyDupConfig dailyDupConfig = ConfigSingleton<DailyDupConfigCategory>.Instance.Get((int)dupType);
			int buyedCount = PrivilegeHelper.GetBuyedCount(self.Player, dailyDupConfig.PriceType);
			if (self.DailyDupDataMap == null || !self.DailyDupDataMap.TryGetValue((int)dupType, out var value))
			{
				return dailyDupConfig.FightCount + num + buyedCount;
			}
			self.CheckAndResetData();
			return dailyDupConfig.FightCount + num + buyedCount - value.FightCount;
		}

		public static bool HasLevelConfig(this DailyDupModule self, DupType dupType, int level)
		{
			int id = (int)dupType * 10000 + level;
			return ConfigSingleton<DailyDupLevelConfigCategory>.Instance.Contain(id);
		}

		public static bool HasExceedLevelPower(this DailyDupModule self, DupType dupType, int level)
		{
			if (!self.HasLevelConfig(dupType, level))
			{
				return false;
			}
			int id = (int)dupType * 10000 + level;
			DailyDupLevelConfig dailyDupLevelConfig = ConfigSingleton<DailyDupLevelConfigCategory>.Instance.Get(id);
			return ((Entity)(object)self).LocalPlayer().GetPower() >= dailyDupLevelConfig.Power;
		}

		public static bool IsEnoughFightCount(this DailyDupModule self, DupType dupType)
		{
			return self.GetLeftFightCount(dupType) > 0;
		}

		public static int GetPrivilegeTotalCount(this DailyDupModule self, DupType type)
		{
			int result = 0;
			if (self.PrivilegeTypes.TryGetValue(type, out var value))
			{
				result = ((Entity)self.Player).GetComponent<PrivilegeModule>().GetValue(value);
			}
			return result;
		}

		public static void UpdateDailyDupStats(this DailyDupModule self)
		{
			self.DailyDupState.Clear();
			foreach (KeyValuePair<int, DailyDupConfig> item in ConfigSingleton<DailyDupConfigCategory>.Instance.GetAll())
			{
				int key = item.Key;
				DupType dupType = (DupType)key;
				if (((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<DailyDupModule>().GetCurrentLevel(dupType) == 0)
				{
					continue;
				}
				if (self.IsEnoughFightCount(dupType))
				{
					self.DailyDupState.Add(key, 1);
					continue;
				}
				int privilegeTotalCount = self.GetPrivilegeTotalCount(dupType);
				if (privilegeTotalCount <= 0)
				{
					self.DailyDupState.Add(key, 3);
					continue;
				}
				DailyDupConfig dailyDupConfig = ConfigSingleton<DailyDupConfigCategory>.Instance.Get(key);
				if (((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<PrivilegeModule>().GetBuyedCount(dailyDupConfig.PriceType) >= privilegeTotalCount)
				{
					self.DailyDupState.Add(key, 4);
				}
				else
				{
					self.DailyDupState.Add(key, 2);
				}
			}
		}

		public static int GetDailyDupState(this DailyDupModule self, int dupType)
		{
			return self.DailyDupState.GetValueOrDefault(dupType, 0);
		}

		public static bool CheckFightCount(this DailyDupModule self, DupType dupType, int count = 1)
		{
			return self.GetLeftFightCount(dupType) >= count;
		}

		public static bool CheckBuyCount(this DailyDupModule self, DupType dupType, int count = 1)
		{
			DailyDupConfig dailyDupConfig = ConfigSingleton<DailyDupConfigCategory>.Instance.Get((int)dupType);
			int buyedCount = PrivilegeHelper.GetBuyedCount(self.Player, dailyDupConfig.PriceType);
			int privilegeTotalCount = self.GetPrivilegeTotalCount(dupType);
			return buyedCount + count <= privilegeTotalCount;
		}
	}
