	public static class DressHelper
	{
		public static List<FashionConfig> GetConfigsByType(int type, Player player)
		{
			List<FashionConfig> list = ConfigSingleton<FashionConfigCategory>.Instance.GetConfigsByType(type).Clone();
			List<FashionConfig> list2 = new List<FashionConfig>();
			foreach (FashionConfig item in list)
			{
				if (player.CheckAllConds(item.OpenConds))
				{
					list2.Add(item);
				}
			}
			return list2;
		}

		public static bool IsActiveDressSuit(Player player, int suitId)
		{
			FashionSuitConfig fashionSuitConfig = ConfigSingleton<FashionSuitConfigCategory>.Instance.Get(suitId);
			if (fashionSuitConfig == null)
			{
				return false;
			}
			if (!player.CheckAllConds(fashionSuitConfig.OpenConds))
			{
				return false;
			}
			int suitCount = ((Entity)player).GetComponent<DressSuitModule>().GetSuitCount(suitId);
			int suitCountById = ConfigSingleton<FashionConfigCategory>.Instance.GetSuitCountById(suitId);
			return suitCount >= suitCountById;
		}

		public static int GetSuitModelId(List<int> currentDresses, int modelId)
		{
			if (currentDresses == null)
			{
				return modelId;
			}
			using List<int>.Enumerator enumerator = currentDresses.GetEnumerator();
			if (enumerator.MoveNext())
			{
				int current = enumerator.Current;
				FashionConfig fashionConfig = ConfigSingleton<FashionConfigCategory>.Instance.Get(current);
				if (fashionConfig == null)
				{
					return modelId;
				}
				List<int> suitIdList = ConfigSingleton<FashionConfigCategory>.Instance.GetSuitIdList(fashionConfig.SuitId);
				if (suitIdList == null)
				{
					return modelId;
				}
				foreach (int item in suitIdList)
				{
					if (!currentDresses.Contains(item))
					{
						return modelId;
					}
				}
				return ConfigSingleton<FashionSuitConfigCategory>.Instance.Get(fashionConfig.SuitId)?.SuitModelId ?? modelId;
			}
			return modelId;
		}

		public static bool IsCanActiveDress(Player player, int dressId)
		{
			Dress dressById = player.GetDressById(dressId);
			bool flag = dressById?.IsExpired ?? false;
			bool flag2 = dressById?.IsPermanent ?? true;
			if ((((dressById == null) | flag) || !flag2) && GetActiveItem(player, dressId) != null)
			{
				return true;
			}
			return false;
		}

		public static ItemConfig GetActiveItem(Player player, int dressId)
		{
			int[] activeItems = ConfigSingleton<FashionConfigCategory>.Instance.Get(dressId).ActiveItems;
			if (activeItems == null || activeItems.Length == 0)
			{
				return null;
			}
			Dress child = ((Entity)((Entity)player).GetComponent<DressModule>()).GetChild<Dress>((long)dressId);
			ItemConfig result = null;
			int[] array = activeItems;
			foreach (int id in array)
			{
				ItemConfig itemConfig = ConfigSingleton<ItemConfigCategory>.Instance.Get(id);
				if (itemConfig.UseEff != 12)
				{
					continue;
				}
				int[] useEffParams = itemConfig.UseEffParams;
				if (useEffParams.Length < 3)
				{
					continue;
				}
				int num = useEffParams[0];
				int num2 = useEffParams[1];
				int num3 = useEffParams[2];
				if (num == dressId && player.CheckItemNumsIsEnough(itemConfig.Id, num3) && (child == null || !child.IsPermanent || num2 == -1))
				{
					result = itemConfig;
					if (num2 == -1)
					{
						break;
					}
				}
			}
			return result;
		}

