			}
		}

		public static void GetDressInfo(Player player, ShowDressInfo dressInfo)
		{
			DressModule component = ((Entity)player).GetComponent<DressModule>();
			foreach (KeyValuePair<int, int> currentDress in component.CurrentDresses)
			{
				Dress child = ((Entity)component).GetChild<Dress>((long)currentDress.Value);
				switch (child.Type)
				{
				case 1:
					dressInfo.Fashion = child.ConfigId;
					dressInfo.FashionExpiredTime = child.ExpiredTime;
					break;
				case 2:
					dressInfo.HeadId = child.ConfigId;
					dressInfo.HeadIdExpiredTime = child.ExpiredTime;
					break;
				case 3:
					dressInfo.HeadFrameId = child.ConfigId;
					dressInfo.HeadFrameExpiredTime = child.ExpiredTime;
					break;
				case 6:
					dressInfo.Weapon = child.ConfigId;
					dressInfo.WeaponExpiredTime = child.ExpiredTime;
					break;
				case 7:
					dressInfo.Cape = child.ConfigId;
					dressInfo.CapeExpiredTime = child.ExpiredTime;
					break;
				case 4:
					dressInfo.ChatBg = child.ConfigId;
					dressInfo.ChatBgExpiredTime = child.ExpiredTime;
					break;
				case 5:
					dressInfo.ChatFrame = child.ConfigId;
					dressInfo.ChatFrameExpiredTime = child.ExpiredTime;
					break;
				}
			}
		}

