			return fashionConfig.ModelId;
		}

		public static int GetCapeModelId(this ShowDressInfo self, int sex)
		{
			int id = self?.GetDressId(7) ?? GetDefaultId(7);
			FashionConfig fashionConfig = ConfigSingleton<FashionConfigCategory>.Instance.Get(id);
			if (sex != 0)
			{
				return fashionConfig.ModelId;
			}
			return fashionConfig.ModelId;
		}

		public static int GetDressId(this ShowDressInfo self, int dressType)
		{
			long num = TimeHelper.Now();
			switch (dressType)
			{
			case 1:
				if ((self.FashionExpiredTime == -1 || (self.FashionExpiredTime > 0 && num < self.FashionExpiredTime)) && self.Fashion != 0)
