				}
				return GetDefaultId(2);
			case 3:
				if ((self.HeadFrameExpiredTime == -1 || (self.HeadFrameExpiredTime > 0 && num < self.HeadFrameExpiredTime)) && self.HeadFrameId != 0)
				{
