		public static int GetCurrentId(int currentId, int appearanceType, long expiredTime)
		{
			if (currentId == 0)
			{
				return GetDefaultId(appearanceType);
			}
			if (TimeHelper.Now() > expiredTime)
			{
				return GetDefaultId(appearanceType);
			}
			return currentId;
		}

		public static string getAttrInfoBtnIcon(List<DressSyncInfo> infos)
		{
			if (infos == null)
			{
				return ConfigSingleton<FashionShowConfigCategory>.Instance.GetOne().icon;
			}
			int dressShowCount = getDressShowCount(infos);
			if (dressShowCount <= 0)
			{
				return ConfigSingleton<FashionShowConfigCategory>.Instance.GetOne().icon;
			}
			List<FashionShowConfig> list = ConfigSingleton<FashionShowConfigCategory>.Instance.GetList();
			string result = string.Empty;
			for (int i = 0; i < list.Count; i++)
			{
				FashionShowConfig fashionShowConfig = list[i];
				if (dressShowCount >= fashionShowConfig.min)
				{
					result = fashionShowConfig.icon;
				}
			}
			return result;
		}

		private static int getDressShowCount(List<DressSyncInfo> infos)
		{
			if (infos == null)
			{
				return 0;
			}
			int num = infos.Count;
			for (int i = 0; i < infos.Count; i++)
			{
				DressSyncInfo dressSyncInfo = infos[i];
				FashionPowerConfig fashionPowerConfig = ConfigSingleton<FashionPowerConfigCategory>.Instance.Get(dressSyncInfo.FashionId, dressSyncInfo.Star);
				if (fashionPowerConfig != null)
				{
					num += fashionPowerConfig.Number;
				}
			}
			return num;
		}

		public static int GetDefaultId(int dressType)
		{
			switch (dressType)
			{
			case 1:
				return 10000;
			case 2:
				return 20000;
			case 3:
				return 30000;
			case 4:
				return 40000;
			case 5:
				return 50000;
			case 6:
				return 60000;
			case 7:
				return 70000;
			default:
				Log.Warning($"Appearance Type {dressType} is not supported");
				return 0;
			}
		}
	}
	[FriendOf(typeof(Dress))]
	[FriendOf(typeof(DressModule))]
	public static class DressModuleSystem
	{
		public static void ResetExpiredTimeDress(this DressModule self)
		{
			foreach (Dress item in ((Entity)self).Children.Values.Cast<Dress>())
			{
				if (item.IsExpired && item.ConfigId == self.CurrentDresses.GetValueOrDefault(item.Type))
				{
					self.CurrentDresses[item.Type] = DressHelper.GetDefaultId(item.Type);
				}
			}
		}

		public static Dress GetIsOnDress(this DressModule self, int dressType)
		{
			int valueOrDefault = self.CurrentDresses.GetValueOrDefault(dressType);
			Dress child = ((Entity)self).GetChild<Dress>((long)valueOrDefault);
			if (child != null)
			{
				if (!child.IsExpired)
				{
					return child;
				}
				return null;
			}
			return null;
		}

		public static Dress GetDressById(this DressModule self, int dressId)
		{
			return ((Entity)self).GetChild<Dress>((long)dressId);
		}

		public static void UpdateStat(this DressModule self, StatList updateList)
		{
			foreach (Dress item in ((Entity)self).Children.Values.Cast<Dress>())
			{
				item.UpdateStat(updateList);
			}
		}

		public static List<DressSyncInfo> GetSyncInfos(this DressModule self)
		{
			List<DressSyncInfo> list = new List<DressSyncInfo>();
			foreach (Entity value in ((Entity)self).Children.Values)
			{
				Dress dress = value as Dress;
				if (!dress.IsExpired)
				{
					list.Add(new DressSyncInfo
					{
						FashionId = dress.ConfigId,
						Star = dress.Star,
						ExpireTime = dress.ExpiredTime
					});
				}
			}
			return list;
		}
	}
	[FriendOf(typeof(DressSuitModule))]
	public static class DressSuitModuleSystem
	{
		public static void UpdateSuitCount(this DressSuitModule self, int suitId, int dressId)
		{
			self.SuitDicCount.TryAdd(suitId, new List<int>());
			if (self.SuitDicCount[suitId].IndexOf(dressId) == -1)
			{
				self.SuitDicCount[suitId].Add(dressId);
			}
		}

		public static void UpdateSuitCount(this DressSuitModule self, int dressId)
		{
			Dress child = ((Entity)((Entity)self.Player).GetComponent<DressModule>()).GetChild<Dress>((long)dressId);
			if (child != null && child.IsPermanent && ConfigSingleton<FashionSuitConfigCategory>.Instance.Contain(child.Config.SuitId))
			{
				self.UpdateSuitCount(child.Config.SuitId, child.Config.Id);
			}
		}

		public static int GetSuitCount(this DressSuitModule self, int suitId)
		{
			if (!self.SuitDicCount.TryGetValue(suitId, out var value))
			{
				return 0;
			}
			return value.Count;
		}
	}
	[FriendOf(typeof(Dress))]
	public static class DressSystem
	{
		public static void SetExpireTime(this Dress self, long expireTime)
		{
			self.ExpiredTime = expireTime;
		}

		public static void SetStar(this Dress self, int star)
		{
			self.Star = star;
		}

		public static void UpdateStat(this Dress self, StatList updateList)
		{
			if (self.PowerConfig != null && self.PowerConfig.Stats != null)
			{
				updateList.AddRange(self.PowerConfig.Stats);
			}
		}

		public static ET.ConfigBeans.Item GetNextStarCost(this Dress self)
		{
			FashionPowerConfig nextPowerConfig = self.NextPowerConfig;
			if (nextPowerConfig == null)
			{
				return null;
			}
			return ItemHelper.GetAnyItem(((Entity)((Entity)self).GetParent<DressModule>()).GetParent<Player>(), nextPowerConfig.StarCost);
		}

		public static bool IsUse(this Dress self)
		{
			DressModule parent = ((Entity)self).GetParent<DressModule>();
			bool flag = parent.CurrentDresses.GetValueOrDefault(self.Type) == self.ConfigId;
			if (!self.IsExpired)
			{
				return flag;
			}
			if (!flag)
			{
				return false;
			}
			int defaultId = DressHelper.GetDefaultId(self.Type);
			parent.CurrentDresses[self.Type] = defaultId;
			return defaultId == self.ConfigId;
		}

		public static bool CanUpStar(this Dress self)
		{
			if (self.IsMaxStar)
			{
				return false;
			}
			if (!self.IsPermanent)
			{
				return false;
			}
			if (self.NextPowerConfig == null)
			{
				return false;
			}
			if (self.NextPowerConfig.Stats == null)
			{
				return false;
			}
			if (self.NextPowerConfig.Stats.Length == 0)
			{
				return false;
			}
			if (self.GetNextStarCost() == null)
			{
				return false;
			}
			return true;
		}
	}
	public static class CampInfoHelper
	{
		public static string GetName(this CampInfo self)
		{
			if (!string.IsNullOrEmpty(self.Name))
			{
				return self.Name;
			}
			if (self.LeaderMonster > 0)
			{
				MonsterConfig monsterConfig = ConfigSingleton<MonsterConfigCategory>.Instance.Get(self.LeaderMonster);
				if (monsterConfig == null)
				{
					return string.Empty;
				}
				return ConfigSingleton<UnitConfigCategory>.Instance.Get(monsterConfig.UnitId)?.Name;
			}
			if (self.LeaderHero > 0)
			{
				HeroConfig heroConfig = ConfigSingleton<HeroConfigCategory>.Instance.Get(self.LeaderHero);
				if (heroConfig == null)
				{
					return string.Empty;
				}
				return ConfigSingleton<UnitConfigCategory>.Instance.Get(heroConfig.UnitId)?.Name;
			}
			return string.Empty;
		}

		public static (int, int, int) GetModelIds(this CampInfo self)
		{
			if (self.PlayerId > 0)
			{
				return (self.Model, self.Weapon, self.Cape);
			}
			if (self.LeaderMonster > 0)
			{
				return (MonsterHelper.GetShowModelId(self.LeaderMonster), 0, 0);
			}
			if (self.LeaderHero > 0)
			{
				return (ConfigSingleton<HeroConfigCategory>.Instance.Get(self.LeaderHero)?.ModelId ?? 0, 0, 0);
			}
			return default((int, int, int));
		}
	}
