		public static void AddWaveMonsters(this DupInfo self, int formationId, Array<int>[] waveMonsters)
		{
			FormationTemplateConfig formationTemplateConfig = ConfigSingleton<FormationTemplateConfigCategory>.Instance.Get(formationId);
			if (self.WaveInfos == null)
			{
				List<DupWaveInfo> list = (self.WaveInfos = new List<DupWaveInfo>());
			}
			foreach (Array<int> obj in waveMonsters)
			{
				DupWaveInfo dupWaveInfo = new DupWaveInfo
				{
					Monsters = new List<MonsterInfo>(),
					Type = 0
				};
				self.WaveInfos.Add(dupWaveInfo);
				int num = 0;
				int[] values = obj.Values;
				foreach (int num2 in values)
				{
					MonsterConfig monsterConfig = ConfigSingleton<MonsterConfigCategory>.Instance.Get(num2);
					Dictionary<ushort, long> dictionary = new Dictionary<ushort, long>();
					if (ConfigSingleton<StatWrapConfigCategory>.Instance.Contain(monsterConfig.Stat))
					{
						Stat[] stats = ConfigSingleton<StatWrapConfigCategory>.Instance.Get(monsterConfig.Stat).Stats;
						foreach (Stat stat in stats)
						{
							dictionary.Add(stat.Type, stat.Value);
						}
					}
					dupWaveInfo.Monsters.Add(new MonsterInfo
					{
						ConfigId = num2,
						UnitConfigId = monsterConfig.UnitId,
						Level = monsterConfig.Level,
						Stats = dictionary,
						PosId = formationTemplateConfig.PosIds.GetValueOrLast(num)
					});
					num++;
				}
			}
		}
	}
	[FriendOf(typeof(DupManagerComponent))]
	public static class DupManagerComponentSystem
	{
		public static Dup CreateDup(this DupManagerComponent self, long playerId, DupType dupType)
		{
			SceneLayer layer = (SceneLayer)ConfigSingleton<DupConfigCategory>.Instance.Get((int)dupType).Layer;
			Dup dup = default(Dup);
			if (self.PlayerDupMap.TryGetValue(playerId, layer, ref dup))
			{
				self.PlayerDupMap.Remove(playerId, layer);
				((DisposeObject)dup).Dispose();
			}
			dup = ((Entity)self).AddChild<Dup, DupType>(dupType, true);
			dup.PlayerId = playerId;
			dup.Seed = RandomGenerator.RandInt32();
			dup.Info.LimitTime = dup.Config.LimitTime * 1000;
			self.PlayerDupMap.Add(playerId, layer, dup);
			return dup;
		}

		public static Dup CreateDup(this DupManagerComponent self, DupInfo dupInfo)
		{
			SceneLayer layer = (SceneLayer)ConfigSingleton<DupConfigCategory>.Instance.Get(dupInfo.DupType).Layer;
			Dup dup = default(Dup);
			if (self.PlayerDupMap.TryGetValue(dupInfo.PlayerId, layer, ref dup))
			{
				self.PlayerDupMap.Remove(dupInfo.PlayerId, layer);
				((DisposeObject)dup).Dispose();
			}
			dup = ((Entity)self).AddChildWithId<Dup, DupInfo>(dupInfo.DupId, dupInfo, true);
			self.PlayerDupMap.Add(dupInfo.PlayerId, layer, dup);
			return dup;
		}

		public static void Remove(this DupManagerComponent self, Dup dup)
		{
			if (self.PlayerDupMap.Remove(dup.PlayerId, (SceneLayer)dup.Config.Layer))
			{
				((DisposeObject)dup).Dispose();
			}
		}

		public static Dup GetDup(this DupManagerComponent self, long dupId)
		{
			return ((Entity)self).GetChild<Dup>(dupId);
		}
	}
