		private static void Load(this DupProviderComponent self)
		{
			self.DupProviders.Clear();
			foreach (Type type in Singleton<EventSystem>.Instance.GetTypes(typeof(DupProviderAttribute)))
			{
				if (!(Activator.CreateInstance(type) is ADupProvider value))
				{
					Log.Error("Type is not ADupProvider: " + type.Name);
					continue;
				}
				DupProviderAttribute customAttribute = ((MemberInfo)type).GetCustomAttribute<DupProviderAttribute>();
				self.DupProviders.Add(customAttribute.DupType, value);
			}
		}

		public static ADupProvider Get(this DupProviderComponent self, DupType dupType)
		{
			self.DupProviders.TryGetValue(dupType, out var value);
			return value;
		}
	}
