	public static class DupSceneFactory
	{
		public static Scene Create(Scene scene, DupInfo dupInfo, bool isServer = false)
		{
			BattleSceneManagerComponent component = ((Entity)scene).GetComponent<BattleSceneManagerComponent>();
			if (component == null)
			{
				throw new Exception("BattleSceneManagerComponent is not exist!");
			}
			Scene val = EntitySceneFactory.CreateScene(Singleton<IdGenerater>.Instance.GenerateId(), Singleton<IdGenerater>.Instance.GenerateInstanceId(), scene.Zone, (SceneType)(isServer ? 21 : 15), "BattleScene", (Entity)(object)component);
			((Entity)val).AddComponent<SceneEvent>(false);
			SceneTimeInfo sceneTimeInfo = ((Entity)val).AddComponent<SceneTimeInfo>(false);
			((Entity)val).AddComponent<SceneTimerComponent, SceneTimeInfo>(sceneTimeInfo, false);
			((Entity)val).AddComponent<UnitComponent>(false);
			((Entity)val).AddComponent<BattleComponent>(false);
			((Entity)val).AddComponent<SceneFrameUpdateComponent>(false);
			((Entity)val).AddComponent<SceneInfoComponent>(false).SceneId = dupInfo.SceneId;
			((Entity)val).AddComponent<SceneTSRandomComponent>(false).Init(dupInfo.Seed);
			((Entity)val).AddComponent<LimitTimeComponent>(false).RefreshLimitTime(dupInfo.LimitTime);
			Dup dup = ((Entity)val).AddComponent<DupComponent, DupInfo>(dupInfo, false).Dup;
			DupConfig config = dup.Config;
			if (DupModule.BattleLog)
			{
				((Entity)val).AddComponent<BattleLogComponent>(false);
			}
			((Entity)val).GetComponent<SceneTSRandomComponent>().Init(dup.Seed);
			BattleComponent component2 = ((Entity)val).GetComponent<BattleComponent>();
			component2.FightType = (FightType)config.FightType;
			component2.IsSkipSuperSkillCastTime = !config.NoSkipSuperSkillCastTime;
			Entity val2 = val.AddDupSceneComponent();
			if (val2 == null)
			{
				val2 = (Entity)(object)((Entity)val).AddComponent<NormalDupSceneComponent>(false);
			}
			((Entity)val).GetComponent<SceneEvent>().Register(val2);
			if (dupInfo.UnitInfos != null)
			{
				foreach (UnitInfo unitInfo in dupInfo.UnitInfos)
				{
					if (unitInfo.GetStat(NumericType.CurrentHp) > 0)
					{
						UnitFactory.CreateWithUnitInfo(val, unitInfo);
					}
				}
			}
			return val;
		}
	}
	public static class DupSceneHelper
	{
		public static void DisposeScene(Scene battleScene)
		{
			if (battleScene == null)
			{
				return;
			}
			ListComponent<Entity> val = ListComponent<Entity>.Create();
			try
			{
				foreach (Entity value in ((Entity)battleScene).Components.Values)
				{
					if (!(value is SceneTimerComponent) && !(value is SceneTimeInfo))
					{
						((List<Entity>)(object)val).Add(value);
					}
				}
				foreach (Entity item in (List<Entity>)(object)val)
				{
					((DisposeObject)item).Dispose();
				}
				((DisposeObject)battleScene).Dispose();
			}
			finally
			{
				((IDisposable)val)?.Dispose();
			}
		}
	}
