		private static void FinishByPlayType_PVP(this LimitTimeComponent self)
		{
			Scene obj = SceneHelper.DomainScene((Entity)(object)self);
			Dup dup = ((Entity)obj).GetComponent<DupComponent>().Dup;
			UnitComponent component = ((Entity)obj).GetComponent<UnitComponent>();
			int num = 0;
			int num2 = 0;
			foreach (Unit fightUnit in component.FightUnits)
			{
				if (fightUnit.Type == UnitType.Hero && !fightUnit.IsDead())
				{
					if (fightUnit.GetCamp() == 1)
					{
						num++;
					}
					else
					{
						num2++;
					}
				}
			}
			if (num != num2)
			{
				dup.Finish((num > num2) ? 1 : 2);
				return;
			}
			long num3 = dup.GetCampInfo(1)?.Power ?? 0;
			long num4 = dup.GetCampInfo(2)?.Power ?? 0;
			if (num3 != num4)
			{
				dup.Finish((num3 > num4) ? 1 : 2);
			}
			else
			{
				dup.Finish(2);
			}
		}

