	public static class EndlessHelper
	{
		public static List<int> GetBuffs(int buffGroup, int nums)
		{
			List<int> result = new List<int>();
			List<EndlessBuffGroupConfig> configs = ConfigSingleton<EndlessBuffGroupConfigCategory>.Instance.GetConfigs(buffGroup);
			bool isFindVIP = false;
			for (int i = 0; i < nums; i++)
			{
				int num = GetTotalWeight();
				int num2 = RandomGenerator.RandomNumber(1, num);
				int num3 = 0;
				bool flag = false;
				for (int j = 0; j < configs.Count; j++)
				{
					EndlessBuffGroupConfig endlessBuffGroupConfig = configs[j];
					if ((isFindVIP && endlessBuffGroupConfig.VipConds > 0) || result.IndexOf(endlessBuffGroupConfig.Id) >= 0)
					{
						continue;
					}
					num3 += endlessBuffGroupConfig.Weight;
					if (num2 < num3)
					{
						flag = true;
						result.Add(endlessBuffGroupConfig.Id);
						if (endlessBuffGroupConfig.VipConds > 0)
						{
							isFindVIP = true;
						}
						break;
					}
				}
				if (!flag)
				{
					EndlessBuffGroupConfig endlessBuffGroupConfig2 = configs.Last();
					result.Add(endlessBuffGroupConfig2.Id);
					if (endlessBuffGroupConfig2.VipConds > 0)
					{
						isFindVIP = true;
					}
				}
			}
			return result;
			int GetTotalWeight()
			{
				int num4 = 0;
				for (int k = 0; k < configs.Count; k++)
				{
					EndlessBuffGroupConfig endlessBuffGroupConfig3 = configs[k];
					if ((!isFindVIP || endlessBuffGroupConfig3.VipConds <= 0) && result.IndexOf(endlessBuffGroupConfig3.Id) < 0)
					{
						num4 += endlessBuffGroupConfig3.Weight;
					}
				}
				return num4;
			}
		}

		public static string GetText(int id, bool isShowColor = true)
		{
			if (id == 0)
			{
				if (isShowColor)
				{
					return $"<color=#5dfa49>{0}</color>层<color=#5dfa49>{0}</color>关";
				}
				return $"{0}层{0}关";
			}
			int layer = GetLayer(id);
			int level = GetLevel(id);
			if (isShowColor)
			{
				return $"<color=#5dfa49>{layer}</color>层<color=#5dfa49>{level}</color>关";
			}
			return $"{layer}层{level}关";
		}

		public static long GetMonsterPower(int level)
		{
			EndlessPurgatoryDupLevelConfig endlessPurgatoryDupLevelConfig = ConfigSingleton<EndlessPurgatoryDupLevelConfigCategory>.Instance.Get(level);
			long num = 0L;
			for (int i = 0; i < endlessPurgatoryDupLevelConfig.Monsters.Length; i++)
			{
				RobotConfig robotConfig = ConfigSingleton<RobotConfigCategory>.Instance.Get(endlessPurgatoryDupLevelConfig.Monsters[i]);
				num += robotConfig.Power;
			}
			return num;
		}

		public static int GetLayer(int id)
		{
			return ConfigSingleton<EndlessPurgatoryDupLevelConfigCategory>.Instance.Get(id).Layer;
		}

		public static int GetLevel(int id)
		{
			return ConfigSingleton<EndlessPurgatoryDupLevelConfigCategory>.Instance.Get(id).Wave;
		}

		public static EndlessPurgatoryDupLevelConfig GetFirstConfig(int id)
		{
			for (int num = id; num > 0; num--)
			{
				EndlessPurgatoryDupLevelConfig endlessPurgatoryDupLevelConfig = ConfigSingleton<EndlessPurgatoryDupLevelConfigCategory>.Instance.Get(num);
				if (endlessPurgatoryDupLevelConfig.Wave == 1)
				{
					return endlessPurgatoryDupLevelConfig;
				}
			}
			return null;
		}

		public static int GetGapLevel(int id1, int id2)
		{
			int layer = GetLayer(id1);
			int layer2 = GetLayer(id2);
			int level = GetLevel(id1);
			int level2 = GetLevel(id2);
			return (layer2 - layer) * 5 + (level2 - level) + 1;
		}

		public static int IsCanGetDayReward(this EndlessModule self)
		{
			int passId = self.GetPassId();
			if (passId == 0)
			{
				return 202505;
			}
			if (passId <= self.DayRewardId)
			{
				return 202507;
			}
			using ItemList itemList = ItemList.Create();
