			{
				self.ChangeGift[configId] = 0;
			}
			self.ChangeGift[configId] += changeNum;
			ExchangeShopItemConfig exchangeShopItemConfig = ConfigSingleton<ExchangeShopItemConfigCategory>.Instance.Get(configId);
			if (!self.GetItemNum.ContainsKey(exchangeShopItemConfig.CostPrice.Id))
			{
				self.GetItemNum.Add(exchangeShopItemConfig.CostPrice.Id, 0);
			}
			self.GetItemNum[exchangeShopItemConfig.CostPrice.Id] += exchangeShopItemConfig.CostPrice.Nums * changeNum;
		}

