	[FriendOf(typeof(FaBaoModule))]
	public static class FaBaoModuleSystem
	{
		public static int HeroChangeWearingFaBao(this FaBaoModule self, int FaBaoId, int HeroId, int replaceFaBaoId = 0)
		{
			FaBao child = ((Entity)self).GetChild<FaBao>((long)FaBaoId);
			if (child == null)
			{
				return 207602;
			}
			Hero hero = ((Entity)self.Player).GetComponent<HeroModule>().GetHero(HeroId);
			if (HeroId != 0 && hero == null)
			{
				return 200301;
			}
			if (hero != null && !hero.IsActive)
			{
				return 200301;
			}
			Hero hero2 = ((Entity)self.Player).GetComponent<HeroModule>().GetHero(child.Owner);
			FaBao faBao = null;
			if (hero != null && hero.FaBaoList.Contains(replaceFaBaoId))
			{
				faBao = ((Entity)self).GetChild<FaBao>((long)replaceFaBaoId);
			}
			if (faBao == null && hero != null && hero.IsFaBaoMaxCount())
			{
				return 207663;
			}
			if (hero != null)
			{
				hero.RemoveFaBao(replaceFaBaoId);
				hero.AddFaBao(child.ConfigId);
			}
			if (hero2 != null)
			{
				hero2.RemoveFaBao(child.ConfigId);
				hero2.AddFaBao(replaceFaBaoId);
			}
			child.Owner = HeroId;
			if (faBao != null)
			{
				faBao.Owner = hero2?.ConfigId ?? 0;
			}
			if (hero != null)
			{
				self.Player.UpdateHeroStats(hero.ConfigId, StatBagType.FaBao);
				self.Player.GetHero(hero.ConfigId).UpdateSkill();
			}
			if (hero2 != null)
			{
				self.Player.UpdateHeroStats(hero2.ConfigId, StatBagType.FaBao);
				self.Player.GetHero(hero2.ConfigId).UpdateSkill();
			}
			return 0;
		}
	}
