		public static int AddFaBaoSoul(this FaBao self, int position, long soulId)
		{
			if (!self.IsPositionUnlocked(position))
			{
				return 207656;
			}
			long faBaoSoulIdByPosition = self.GetFaBaoSoulIdByPosition(position);
			if (faBaoSoulIdByPosition == soulId)
			{
				return 207655;
			}
			HashSet<int> hashSet = new HashSet<int>();
			if (soulId != 0L)
			{
				FaBaoSoul child = ((Entity)((Entity)self.Player).GetComponent<FaBaoSoulModule>()).GetChild<FaBaoSoul>(soulId);
				if (child == null)
				{
					return 207652;
				}
				if (ConfigSingleton<FaBaoPosUnLockConfigCategory>.Instance.Get(position).LoadType != child.Config.LoadType)
				{
					return 207657;
				}
				hashSet.Add(child.Config.StatType);
			}
			foreach (long soulId2 in self.SoulIds)
			{
				if (faBaoSoulIdByPosition != soulId2)
				{
					FaBaoSoul child2 = ((Entity)((Entity)self.Player).GetComponent<FaBaoSoulModule>()).GetChild<FaBaoSoul>(soulId2);
					if (!hashSet.Add(child2.Config.StatType))
					{
						return 207664;
					}
				}
			}
			if (faBaoSoulIdByPosition != 0L)
			{
				self.SoulIds.Remove(faBaoSoulIdByPosition);
			}
			if (soulId != 0L)
			{
				self.SoulIds.Add(soulId);
			}
			return 0;
		}
	}
