		private static void recordCostNum(this FaBaoSoulModule self, ET.ConfigBeans.Item[] costItem, Dictionary<int, float> itemCount, int DecomposeRate)
		{
			if (costItem != null && costItem.Length != 0)
			{
				foreach (ET.ConfigBeans.Item item in costItem)
				{
					itemCount.TryAdd(item.Id, 0f);
					itemCount[item.Id] += (float)(item.Nums * DecomposeRate) * 1f / 100f;
				}
			}
		}

		public static ItemList GetDecomposeItemList(this FaBaoSoulModule self, List<long> ids, bool IsDecompose)
		{
			ItemList itemList = new ItemList();
			Dictionary<int, float> dictionary = new Dictionary<int, float>();
			foreach (long id in ids)
			{
				FaBaoSoul child = ((Entity)self).GetChild<FaBaoSoul>(id);
				if (child == null)
				{
					continue;
				}
				FaBaoSoulLevelConfig faBaoSoulLevelConfig = null;
				for (int i = 0; i < child.Level; i++)
				{
					faBaoSoulLevelConfig = ConfigSingleton<FaBaoSoulLevelConfigCategory>.Instance.Get(child.ConfigId, i);
					self.recordCostNum(faBaoSoulLevelConfig.CostNum, dictionary, child.Config.DecomposeRate);
					if (i >= faBaoSoulLevelConfig.LevelUpValue)
					{
						faBaoSoulLevelConfig = null;
					}
				}
				int num = 0;
				for (int j = 0; j < child.Star; j++)
				{
					ET.ConfigBeans.Item[] costNum = ConfigSingleton<FaBaoSoulStarConfigCategory>.Instance.Get(child.ConfigId, j).CostNum;
					foreach (ET.ConfigBeans.Item item in costNum)
					{
						num += item.Nums;
					}
				}
				self.recordCostNum(child.Config.DecomposeItem, dictionary, 100 * num);
				if (IsDecompose)
				{
					self.recordCostNum(child.Config.DecomposeItem, dictionary, 100);
				}
			}
			foreach (KeyValuePair<int, float> item2 in dictionary)
			{
				itemList.Add(new ItemStruct
				{
					ConfigId = item2.Key,
					Nums = (long)Math.Floor(item2.Value)
				});
			}
			return itemList;
		}

		public static int GetFreeCount(this FaBaoSoulModule self)
		{
			self.ResetDailyData();
			bool num = !TimeHelper.IsSameDay(TimeHelper.Now(), self.FreeTime, 18000000L);
			int value = ((Entity)self.Player).GetComponent<PrivilegeModule>().GetValue(PrivilegeType.FaBaoFreeCount);
			return (num ? 1 : 0) + Math.Max(value - self.DailyRaffleCount, 0);
		}

		public static void SetFreeCount(this FaBaoSoulModule self)
		{
			int value = ((Entity)self.Player).GetComponent<PrivilegeModule>().GetValue(PrivilegeType.FaBaoFreeCount);
			if (self.DailyRaffleCount < value)
			{
				self.DailyRaffleCount++;
				return;
			}
			long num = TimeHelper.Now();
			if (!TimeHelper.IsSameDay(num, self.FreeTime, 18000000L))
			{
				self.FreeTime = num;
			}
		}

		public static void ResetDailyData(this FaBaoSoulModule self)
		{
			long num = TimeHelper.Now();
			if (!TimeHelper.IsSameDay(num, self.DailyResetTime, 18000000L))
			{
				self.DailyResetTime = num;
				self.DailyRaffleCount = 0;
			}
		}
	}
