		public static void Revive(this Unit unit)
		{
			FightComponent component = ((Entity)unit).GetComponent<FightComponent>();
			if (component.IsDead)
			{
				component.IsDead = false;
				unit.ResetHp();
				((Entity)unit).GetComponent<StateComponent>().SetState(StateType.Idle);
				Singleton<EventSystem>.Instance.Publish<UnitRevive>(SceneHelper.DomainScene((Entity)(object)unit), new UnitRevive
				{
