		public static bool IsEnemyOf(this Unit a, Unit b)
		{
			return a.GetCamp() != b.GetCamp();
		}

		public static bool IsCasting(this Unit unit)
		{
			return ((Entity)unit).GetComponent<SkillComponent>().IsInSkillState();
		}

		public static bool CheckMoveCondition(this Unit unit)
		{
			if (((Entity)unit).GetComponent<FightComponent>().IsDead)
			{
				return false;
			}
			NumericComponent component = ((Entity)unit).GetComponent<NumericComponent>();
			if (component[NumericType.StunState] > 0)
			{
				return false;
			}
			if (component[NumericType.BindState] > 0)
			{
				return false;
			}
			return true;
		}

		public static bool CheckCastCondition(this Unit unit, int skillLevelId)
		{
			if (((Entity)unit).GetComponent<FightComponent>().IsDead)
			{
				return false;
			}
			NumericComponent component = ((Entity)unit).GetComponent<NumericComponent>();
			if (component[NumericType.StunState] > 0)
			{
				return false;
			}
			if (((Entity)unit).GetComponent<SkillComponent>().IsSkillCD(skillLevelId))
			{
				return false;
			}
			ActiveSkillLevelConfig activeSkillLevelConfig = ConfigSingleton<ActiveSkillLevelConfigCategory>.Instance.Get(skillLevelId);
			if (activeSkillLevelConfig.EpCost > component[NumericType.CurrentEp])
			{
				return false;
			}
			SkillTag tags = (SkillTag)activeSkillLevelConfig.Tags;
			if (!tags.HasFlag(SkillTag.Attack) && component[NumericType.SilentState] > 0)
			{
				return false;
			}
			if (tags.HasFlag(SkillTag.Move) && component[NumericType.BindState] > 0)
			{
				return false;
			}
			return true;
		}
	}
	public static class FormationHelper
	{
		public static List<int> GetGroupIds(int formationId, bool includeCurrentId = false)
		{
			FormationConfig formationConfig = ConfigSingleton<FormationConfigCategory>.Instance.Get(formationId);
			if (formationConfig.GroupId == 0)
			{
				if (includeCurrentId)
				{
					return new List<int> { formationId };
				}
				return null;
			}
			List<int> list = new List<int>();
			foreach (FormationConfig value in ConfigSingleton<FormationConfigCategory>.Instance.GetAll().Values)
			{
				if ((value.Id != formationId || includeCurrentId) && value.GroupId == formationConfig.GroupId)
				{
					list.Add(value.Id);
				}
			}
			return list;
		}

		public static Formation GetCommonFormation(this Player player)
		{
			return ((Entity)player).GetComponent<FormationModule>().GetFormation(ConfigSingleton<GlobalConfigCategory>.Instance.GetOne().CommonFormationId);
		}

		public static Dictionary<int, long> AutoFormation(Dictionary<long, FormationHeroStruct> source, int formationId)
		{
			FormationConfig formationConfig = ConfigSingleton<FormationConfigCategory>.Instance.Get(formationId);
			List<FormationHeroStruct> list = source.Values.ToList();
			list.Sort(delegate(FormationHeroStruct a, FormationHeroStruct b)
			{
				int type = a.Config.Type;
				int type2 = b.Config.Type;
				return (type != type2) ? type.CompareTo(type2) : b.Power.CompareTo(a.Power);
			});
			Dictionary<int, int> dictionary = new Dictionary<int, int>(formationConfig.Max);
			Queue<FormationHeroStruct> queue = new Queue<FormationHeroStruct>();
			foreach (FormationHeroStruct item in list)
			{
				if (!item.IsRent || formationConfig.CanRent)
				{
					queue.Enqueue(item);
					dictionary[item.Config.Job] = 1;
				}
			}
			bool flag = true;
			bool flag2 = dictionary.Count == ConfigSingleton<JobConfigCategory>.Instance.GetAll().Count;
			list.Clear();
			dictionary.Clear();
			HashSetComponent<long> val = HashSetComponent<long>.Create();
			try
			{
				HashSetComponent<int> val2 = HashSetComponent<int>.Create();
				try
				{
					int num = 0;
					int num2 = 0;
					while (list.Count < formationConfig.Max && queue.Count > 0)
					{
						if (num-- == 0)
						{
							num = queue.Count;
							num2++;
							if (num2 == 2)
							{
								flag = false;
								flag2 = false;
							}
						}
						FormationHeroStruct formationHeroStruct = queue.Dequeue();
						if (((HashSet<int>)(object)val2).Contains(formationHeroStruct.ConfigId))
						{
							continue;
						}
						HeroConfig config = formationHeroStruct.Config;
						if (config.Type == 1)
						{
							if (formationConfig.RoleDeployType == 1)
							{
								((HashSet<long>)(object)val).Add(formationHeroStruct.Id);
								((HashSet<int>)(object)val2).Add(config.Id);
								list.Add(formationHeroStruct);
								dictionary[config.Job] = dictionary.GetValueOrDefault(config.Job) + 1;
							}
							continue;
						}
						JobConfig jobConfig = ConfigSingleton<JobConfigCategory>.Instance.Get(config.Job);
						int valueOrDefault = dictionary.GetValueOrDefault(config.Job);
						if (flag && jobConfig.AutoFormationLimit > 0 && valueOrDefault >= jobConfig.AutoFormationLimit)
						{
							queue.Enqueue(formationHeroStruct);
							continue;
						}
						int num3 = formationConfig.Max - list.Count;
						int num4 = ConfigSingleton<JobConfigCategory>.Instance.GetAll().Count - dictionary.Count;
						if (flag2 && num3 == num4 && dictionary.ContainsKey(config.Job))
						{
							queue.Enqueue(formationHeroStruct);
							continue;
						}
						((HashSet<long>)(object)val).Add(formationHeroStruct.Id);
						((HashSet<int>)(object)val2).Add(config.Id);
						list.Add(formationHeroStruct);
						dictionary[config.Job] = dictionary.GetValueOrDefault(config.Job) + 1;
					}
					Dictionary<int, long> dictionary2 = new Dictionary<int, long>();
					list.Sort((FormationHeroStruct a, FormationHeroStruct b) => b.Power.CompareTo(a.Power));
					foreach (FormationHeroStruct item2 in list)
					{
						int[] posSort = item2.Config.PosSort;
						foreach (int key in posSort)
						{
							if (!dictionary2.ContainsKey(key))
							{
								dictionary2.Add(key, item2.Id);
								break;
							}
						}
					}
					return dictionary2;
				}
				finally
				{
					((IDisposable)val2)?.Dispose();
				}
			}
			finally
			{
				((IDisposable)val)?.Dispose();
			}
		}
	}
	public static class FormationModuleSystem_Share
	{
		public static long GetFormationPower(this Player player, int formationId)
		{
			return ((Entity)player).GetComponent<FormationModule>().GetFormation(formationId)?.GetPower() ?? 0;
		}

		public static long GetFormationPowers(this Player player, int formationId)
		{
			FormationModule component = ((Entity)player).GetComponent<FormationModule>();
			List<int> groupIds = FormationHelper.GetGroupIds(formationId, includeCurrentId: true);
			long num = 0L;
			foreach (int item in groupIds)
			{
				num += component.GetFormation(item)?.GetPower() ?? 0;
			}
			return num;
		}

		public static Formation GetFormation(this Player player, int formationId)
		{
			return ((Entity)player).GetComponent<FormationModule>().GetFormation(formationId);
		}

		public static Formation GetFormation(this FormationModule self, int formationId)
		{
			Formation formation = ((Entity)self).GetChild<Formation>((long)formationId);
			if (formation == null)
			{
				int num = CalculateFormationNo(formationId);
				formation = ((Entity)self).AddChildWithId<Formation, int, int>((long)formationId, formationId, num, false);
				Formation child = ((Entity)self).GetChild<Formation>((long)ConfigSingleton<GlobalConfigCategory>.Instance.GetOne().CommonFormationId);
				if (child != null)
				{
					foreach (var (key, value) in child.PosHero)
					{
						if (formation.Config.RoleDeployType != 2)
						{
							formation.PosHero[key] = value;
						}
					}
				}
			}
			return formation;
		}

		public static bool CheckValid(this FormationModule self, List<FormationInfo> formationInfos)
		{
			HashSetComponent<long> val = HashSetComponent<long>.Create();
			try
			{
				if (formationInfos == null)
				{
					return false;
				}
				Player player = self.Player;
				foreach (FormationInfo formationInfo in formationInfos)
				{
					if (!ConfigSingleton<FormationConfigCategory>.Instance.Contain(formationInfo.FormationId))
					{
						return false;
					}
					Dictionary<int, long> dictionary = formationInfo.PosHero ?? FormationModule.EmptyFormation;
					FormationConfig formationConfig = ConfigSingleton<FormationConfigCategory>.Instance.Get(formationInfo.FormationId);
					if (dictionary.Count > formationConfig.Max)
					{
						return false;
					}
					HashSetComponent<int> val2 = HashSetComponent<int>.Create();
					try
					{
						int num = 0;
						foreach (var (num4, num5) in dictionary)
						{
							Hero heroByUid = player.GetHeroByUid(num5);
							if (heroByUid == null || !heroByUid.IsActive)
							{
								return false;
							}
							if (!((HashSet<long>)(object)val).Add(num5))
							{
								return false;
							}
							if (heroByUid.IsRentHero() && !formationConfig.CanRent)
							{
								return false;
							}
							if (!((HashSet<int>)(object)val2).Add(heroByUid.ConfigId))
							{
								return false;
							}
							if (ConfigSingleton<HeroConfigCategory>.Instance.Get(heroByUid.ConfigId).Type == 1)
							{
								if (formationConfig.RoleDeployType == 2)
								{
									return false;
								}
								num = num4;
							}
							if (!formationConfig.PosSet.Contains(num4))
							{
								return false;
							}
						}
						if (formationConfig.RoleDeployType == 1 && num == 0)
						{
							return false;
						}
					}
					finally
					{
						((IDisposable)val2)?.Dispose();
					}
				}
				return true;
			}
			finally
			{
				((IDisposable)val)?.Dispose();
			}
		}

		public static bool SwapFormationOrder(this FormationModule self, int formationIdA, int formationIdB)
		{
			FormationConfig formationConfig = ConfigSingleton<FormationConfigCategory>.Instance.Get(formationIdA);
			FormationConfig formationConfig2 = ConfigSingleton<FormationConfigCategory>.Instance.Get(formationIdB);
			if (formationConfig?.GroupId != formationConfig2?.GroupId || formationConfig.GroupId == 0)
			{
				return false;
			}
			Formation formation = self.GetFormation(formationIdA);
			Formation formation2 = self.GetFormation(formationIdB);
			Formation formation3 = formation;
			Formation formation4 = formation2;
			int formationNo = formation2.FormationNo;
			int formationNo2 = formation.FormationNo;
			int num = (formation3.FormationNo = formationNo);
			num = (formation4.FormationNo = formationNo2);
			return true;
		}

		public static List<Formation> GetFormationsByFormationNo(this FormationModule self, int groupId)
		{
			List<Formation> list = new List<Formation>();
			foreach (FormationConfig value in ConfigSingleton<FormationConfigCategory>.Instance.GetAll().Values)
			{
				if (value.GroupId == groupId)
				{
					Formation formation = self.GetFormation(value.Id);
					list.Add(formation);
				}
			}
			list.Sort((Formation a, Formation b) => a.FormationNo.CompareTo(b.FormationNo));
			return list;
		}

		public static int CalculateFormationNo(int formationId)
		{
			FormationConfig formationConfig = ConfigSingleton<FormationConfigCategory>.Instance.Get(formationId);
			if ((formationConfig != null && formationConfig.GroupId == 0) || formationConfig == null)
			{
				return 1;
			}
			int num = 0;
			foreach (FormationConfig item in ConfigSingleton<FormationConfigCategory>.Instance.GetAll().Values.OrderBy((FormationConfig c) => c.Id))
			{
				if (item.GroupId == formationConfig.GroupId)
				{
					if (item.Id == formationId)
					{
						return num + 1;
					}
					num++;
				}
			}
			return 1;
		}
	}
