		public static long GetPower(this Formation self)
		{
			Player player = self.Player;
			long num = 0L;
			foreach (var (_, heroId) in self.PosHero)
			{
				Hero heroByUid = player.GetHeroByUid(heroId);
				if (heroByUid != null && heroByUid.IsActive)
				{
					num += heroByUid.GetPower();
				}
			}
			if (num == 0L)
			{
				return num;
			}
			return num + ((Entity)self.Player).GetComponent<BeastModule>().GetPower();
