		public static FormationCommonInfo GetCommonInfo(this Formation self)
		{
			Player player = self.Player;
			FormationCommonInfo formationCommonInfo = new FormationCommonInfo();
			formationCommonInfo.FormationId = self.ConfigId;
			formationCommonInfo.PlayerId = ((Entity)self).Parent.Id;
			formationCommonInfo.Power = self.GetPower();
			formationCommonInfo.FormationNo = self.FormationNo;
			formationCommonInfo.Heroes = new List<HeroCommonInfo>();
			foreach (var (posId, heroId) in self.PosHero)
			{
				Hero heroByUid = player.GetHeroByUid(heroId);
				if (heroByUid != null && heroByUid.IsActive)
				{
					HeroCommonInfo commonInfo = heroByUid.GetCommonInfo();
					commonInfo.PosId = posId;
					formationCommonInfo.Heroes.Add(commonInfo);
				}
			}
			return formationCommonInfo;
		}
