	public static class FuncHelper
	{
		public static bool IsFuncOpen(this Player player, int funcId, bool isNotice = false)
		{
			return ((Entity)player).GetComponent<FuncModule>().IsFuncOpen(funcId, isNotice);
		}

		private static bool IsFuncOpen(this FuncModule self, int funcId, bool isNotice = false)
		{
			if (self.OpenAll != 0)
			{
				return true;
			}
			if (!ConfigSingleton<FuncConfigCategory>.Instance.Contain(funcId))
			{
				return true;
			}
			if (ConfigSingleton<FuncConfigCategory>.Instance.Get(funcId).Invalid)
			{
				return false;
			}
			if (self.OpenedFuncs.Contains(funcId))
			{
				return true;
			}
			if (self.WaitOpenQueue.Contains(funcId))
			{
				if (isNotice)
				{
					Singleton<EventSystem>.Instance.Publish<FuncOpenLockTips>(SceneHelper.DomainScene((Entity)(object)self), new FuncOpenLockTips
					{
						FuncId = funcId
					});
				}
				return false;
			}
			if (self.CheckFunc(funcId))
			{
				self.OpenedFuncs.Add(funcId);
				return true;
			}
			if (isNotice)
			{
				Singleton<EventSystem>.Instance.Publish<FuncOpenLockTips>(SceneHelper.DomainScene((Entity)(object)self), new FuncOpenLockTips
				{
					FuncId = funcId
				});
			}
			return false;
		}

		public static bool IsPreOpen(this Player player, int funcId)
		{
			return ((Entity)player).GetComponent<FuncModule>().IsPreOpen(funcId);
		}

		public static bool IsFuncClose(this Player player, int funcId)
		{
			return ((Entity)player).GetComponent<FuncModule>().IsClose(funcId);
		}

		public static bool CheckFuncOpen(this Player player, int funcId)
		{
			bool num = player.IsFuncOpen(funcId);
			bool flag = player.IsPreOpen(funcId);
			bool flag2 = player.IsFuncClose(funcId);
			if (num | flag)
			{
				return !flag2;
			}
			return false;
		}

		public static bool CheckFuncOpen(this Player player, int funcId, bool IsCheckParent)
		{
			if (IsCheckParent)
			{
				int num = funcId / 1000;
				if (num > 0 && !player.IsFuncOpen(num))
				{
					return false;
				}
			}
			return player.IsFuncOpen(funcId);
		}

		private static bool IsPreOpen(this FuncModule self, int funcId)
		{
			if (self.OpenAll != 0)
			{
				return true;
			}
			if (!ConfigSingleton<FuncConfigCategory>.Instance.Contain(funcId))
			{
				return true;
			}
			FuncConfig funcConfig = ConfigSingleton<FuncConfigCategory>.Instance.Get(funcId);
			if (funcConfig.Invalid)
			{
				return false;
			}
			Cond[] preOpenConds = funcConfig.PreOpenConds;
			if (preOpenConds == null || preOpenConds.Length == 0)
			{
				return false;
			}
			return ((Entity)(object)self).LocalPlayer().CheckAllConds(preOpenConds);
		}

		public static bool CheckFunc(this FuncModule self, int id)
		{
			if (id == 25 && self.IsFuncOpen(26) && GuideHelper.IsFinish(SceneHelper.DomainScene((Entity)(object)self), 48))
			{
				return false;
			}
			FuncConfig funcConfig = ConfigSingleton<FuncConfigCategory>.Instance.Get(id);
			if (funcConfig.Type != 1)
			{
				return self.Player.CheckAnyConds(funcConfig.OpenConds);
			}
			return self.Player.CheckAllConds(funcConfig.OpenConds);
		}

		public static bool CheckPreFunc(this FuncModule self, int id)
		{
			FuncConfig funcConfig = ConfigSingleton<FuncConfigCategory>.Instance.Get(id);
			if (funcConfig.Type != 1)
			{
				return self.Player.CheckAnyConds(funcConfig.PreOpenConds);
			}
			return self.Player.CheckAllConds(funcConfig.PreOpenConds);
		}

		public static void RemoveOpenFunc(this FuncModule self, int funcId)
		{
			self.OpenedFuncs.Remove(funcId);
			self.WaitOpenQueue.Add(funcId);
		}
	}
	[FriendOf(typeof(FuncModule))]
	public static class FuncModuleSystem
	{
		private class AwakeSystem : AwakeSystem<FuncModule>
		{
			protected override void Awake(FuncModule self)
			{
				self.InitChecker();
			}
		}

		private class DeserializeSystem : DeserializeSystem<FuncModule>
		{
			protected override void Deserialize(FuncModule self)
			{
				self.InitChecker();
			}
		}

		private static void InitChecker(this FuncModule self)
		{
			if (self.FuncCheckers == null)
			{
				self.FuncCheckers = new Dictionary<int, IFuncChecker>();
			}
			foreach (Type type in Singleton<EventSystem>.Instance.GetTypes(typeof(FuncCheckerAttribute)))
			{
				IEnumerable<FuncCheckerAttribute> customAttributes = ((MemberInfo)type).GetCustomAttributes<FuncCheckerAttribute>();
				IFuncChecker value = Activator.CreateInstance(type) as IFuncChecker;
				foreach (FuncCheckerAttribute item in customAttributes)
				{
					self.FuncCheckers[item.FuncId] = value;
				}
			}
		}

		public static bool IsClose(this FuncModule self, int funcId)
		{
			if (self.FuncCheckers.TryGetValue(funcId, out var value))
			{
				return value.IsClose(self.Player);
			}
			return false;
		}
	}
