		public static bool IsSortOutGemStonePlanGifts(this GemStonePlanModule self)
		{
			if (self.ActivityData.BaseInfo == null)
			{
				return false;
			}
			if (self.GiftExchangeNumDict == null)
			{
				return false;
			}
			GemStonePlanBaseConfig gemStonePlanBaseConfig = ConfigSingleton<GemStonePlanBaseConfigCategory>.Instance.Get(self.ActivityData.ActivityId);
			Dictionary<int, GemStonePlanGiftConfig> dictionary = new Dictionary<int, GemStonePlanGiftConfig>();
			int[] gemStonePlanGiftId = gemStonePlanBaseConfig.GemStonePlanGiftId;
			int i;
			for (i = 0; i < gemStonePlanGiftId.Length; i++)
			{
				int num = gemStonePlanGiftId[i];
				dictionary.Add(num, ConfigSingleton<GemStonePlanGiftConfigCategory>.Instance.Get(num));
			}
			foreach (KeyValuePair<int, GemStonePlanGiftConfig> item in dictionary)
			{
				item.Deconstruct(out i, out var value);
				int key = i;
				GemStonePlanGiftConfig gemStonePlanGiftConfig = value;
				if (self.GiftExchangeNumDict.TryGetValue(key, out var value2) && value2 < gemStonePlanGiftConfig.MaxExchangeNum)
				{
					return false;
				}
			}
			return true;
		}

		public static bool IsExchangeOutGiftsWithId(this GemStonePlanModule self, int giftId)
		{
			if (self.ActivityData.BaseInfo == null)
			{
				return false;
			}
			if (self.GiftExchangeNumDict == null)
			{
				return false;
			}
			if (giftId == 0)
			{
				return self.IsSortOutGemStonePlanGifts();
			}
			GemStonePlanBaseConfig gemStonePlanBaseConfig = ConfigSingleton<GemStonePlanBaseConfigCategory>.Instance.Get(self.ActivityData.ActivityId);
			Dictionary<int, GemStonePlanGiftConfig> dictionary = new Dictionary<int, GemStonePlanGiftConfig>();
			int[] gemStonePlanGiftId = gemStonePlanBaseConfig.GemStonePlanGiftId;
			foreach (int num in gemStonePlanGiftId)
			{
				dictionary.Add(num, ConfigSingleton<GemStonePlanGiftConfigCategory>.Instance.Get(num));
			}
			if (dictionary.TryGetValue(giftId, out var value) && self.GiftExchangeNumDict.TryGetValue(giftId, out var value2))
			{
				return value2 >= value.MaxExchangeNum;
			}
			return false;
		}
	}
