		public static int GetGuildDupStarAllLeftCount(this GuildDupModule self)
		{
			PrivilegeModule component = ((Entity)self.Player).GetComponent<PrivilegeModule>();
			int num = ConfigSingleton<GuildGlobalConfigCategory>.Instance.GetOne().GuildDupStarFreeCount + component.GetValue(PrivilegeType.GuildStarDefaultCount);
			int buyedCount = component.GetBuyedCount(10);
