		public static bool DupStarLevelCanFight(this GuildDupModule self, int level)
		{
			if (self.StarLevelPassIds.ContainsKey(level))
			{
				return false;
			}
			int num = level - 1;
			if (!ConfigSingleton<GuildDupStarLevelConfigCategory>.Instance.Contain(num))
			{
				return true;
			}
			if (!self.StarLevelPassIds.ContainsKey(num))
			{
				return false;
			}
			return self.StarLevelPassIds.GetValueOrDefault(num);
		}

