	[DupProvider(DupType.GuildDupStar)]
	[FriendOf(typeof(GuildDupBossComponent))]
	public class GuildDupStarProvider : ADupProvider
	{
		public override int CheckFight(Player player, DupType dupType, DupFightArgs args)
		{
			if (((Entity)player).GetComponent<GuildModule>().GuildId == 0L)
			{
				return 202803;
			}
			if (!((Entity)player).GetComponent<GuildDupModule>().DupStarLevelCanFight(args.Level))
			{
				return 202830;
			}
			return 0;
		}

		public override int CheckMopUp(Player player, DupType dupType, DupMopUpArgs args)
		{
			if (args.Nums <= 0)
			{
				return 200502;
			}
			if (((Entity)player).GetComponent<GuildModule>().GuildId == 0L)
			{
				return 202803;
			}
			GuildDupModule component = ((Entity)player).GetComponent<GuildDupModule>();
			if (!component.DupStarLevelCanSweep(args.Level))
			{
				return 202831;
			}
			int guildDupStarAllLeftCount = component.GetGuildDupStarAllLeftCount();
			int num = args.Nums - guildDupStarAllLeftCount;
			if (num > 0)
			{
				if (num > component.GetGuildDupStarLeftBuyCount())
				{
					return 200512;
				}
				ET.ConfigBeans.Item guildDupStarBuyCost = ConfigSingleton<GuildGlobalConfigCategory>.Instance.GetOne().GuildDupStarBuyCost;
				if (!((Entity)player).GetComponent<ItemModule>().CheckItemNumsIsEnough(guildDupStarBuyCost.Id, guildDupStarBuyCost.Nums * num))
				{
					return 200102;
				}
			}
			else if (guildDupStarAllLeftCount <= 0)
			{
				return 200502;
			}
			return 0;
		}
	}
