		public static bool IsInDailySettleTime(this HeavenFightModule self)
		{
			long num = TimeHelper.Now();
			long num2 = TimeHelper.EndTimeOfDay(num, 18000000L);
			long num3 = TimeHelper.CommonEndTimeOfDay(num);
			if (num >= num3)
			{
				return num <= num2;
			}
			return false;
		}

		public static long GetSettleTime(this HeavenFightModule self)
		{
			return self.ActivityData.EndTime - ConfigSingleton<GlobalConfigCategory>.Instance.GetOne().CommonSettleTime * 1000;
		}

