		{
			if (self.BossDifficultyDic != null && self.BossDifficultyDic.TryGetValue(platformId, out var value))
			{
				return value;
			}
			return 0;
		}

		public static HeavenFightBossConfig GetBossCfg(this HeavenFightModule self, int platformId, int[] DifficultyId)
		{
			int bossDifficulty = self.GetBossDifficulty(platformId);
			int num = DifficultyId[0] + bossDifficulty;
			if (num > DifficultyId[1])
			{
				num = DifficultyId[1];
			}
			return ConfigSingleton<HeavenFightBossConfigCategory>.Instance.Get(num);
		}

		public static HeavenFightRewardConfig GetRewardConfigList(this HeavenFightModule self, int PlatformId)
		{
			Dictionary<int, HeavenFightRewardConfig> dictionary = new Dictionary<int, HeavenFightRewardConfig>();
			int num = self.Season;
			for (int num2 = num; num2 > 0; num2--)
			{
				if (ConfigSingleton<HeavenFightRewardConfigCategory>.Instance.Contain(num2 * 1000 + 100 + 1))
				{
					num = num2;
					break;
				}
			}
			foreach (HeavenFightRewardConfig item in ConfigSingleton<HeavenFightRewardConfigCategory>.Instance.GetList())
			{
				if (num == item.Season && item.Type == 1)
				{
					dictionary.Add(item.PlatformId, item);
				}
			}
			dictionary.TryGetValue(PlatformId, out var value);
			return value;
		}

