		{
			List<HeavenFightConfig> list = new List<HeavenFightConfig>();
			int num = self.Season;
			for (int num2 = num; num2 > 0; num2--)
			{
				if (ConfigSingleton<HeavenFightConfigCategory>.Instance.Contain(num2 * 100 + 1))
				{
					num = num2;
					break;
				}
			}
			foreach (HeavenFightConfig item in ConfigSingleton<HeavenFightConfigCategory>.Instance.GetList())
			{
				if (item.Season == num)
				{
					list.Add(item);
				}
			}
			return list;
		}

		public static HeavenFightConfig GetPlatformCfgData(this HeavenFightModule self, int platformId)
		{
