			HeroSkin child = ((Entity)((Entity)player).GetComponent<HeroSkinModule>()).GetChild<HeroSkin>((long)hero.CurrentSkin);
			int num = ((child != null) ? hero.CurrentSkin : HeroSkinHelper.GetHeroDefaultSkinId(hero.Config.Id));
			if (num == 0)
			{
				return null;
			}
			int skinStar = child?.Star ?? 0;
