		public static long GetPower(this Hero hero)
		{
			HeroRentInfoComponent component = ((Entity)hero).GetComponent<HeroRentInfoComponent>();
			if (component != null)
			{
				return component.Info.HeroInfo.Power;
			}
			if (hero.IsActive)
			{
				return hero.GetSkillBagComponent().GetPower() + hero.GetStatBagComponent().GetPower();
			}
			long num = hero.GetSkillBagComponent().GetPower();
			Stat[] stats = ConfigSingleton<StatWrapConfigCategory>.Instance.Get(hero.Config.StatId).Stats;
			foreach (Stat stat in stats)
			{
				StatStruct statStruct = new StatStruct
				{
					Type = stat.Type,
					Value = stat.Value
				};
				if (statStruct.IsBasStat())
				{
					num += StatHelper.CalcPower(statStruct.Type, statStruct.Value, 0L);
				}
				else if (statStruct.IsPctStat())
				{
					num += StatHelper.CalcPower(statStruct.Type, 0L, statStruct.Value);
				}
			}
			return num;
		}

