		public static List<HeroSkillData> GetSkillDataListById(int configId, int targetStar)
		{
			List<HeroSkillData> list = new List<HeroSkillData>();
			HeroStarConfigCategory instance = ConfigSingleton<HeroStarConfigCategory>.Instance;
			int id = configId * 100 + targetStar;
			HeroStarConfig heroStarConfig = instance.Get(id);
			if (heroStarConfig.SkillIds != null)
			{
				for (int i = 0; i < heroStarConfig.SkillIds.Length; i++)
				{
					int num = heroStarConfig.SkillIds[i];
					if (num != 0)
					{
						HeroSkillData item = new HeroSkillData
						{
							SkillLevel = new SkillLevel(num),
							UnlockStar = targetStar,
							IsUnlocked = true
						};
						list.Add(item);
					}
				}
			}
			return (from x in list
				where x != null
				orderby x.SkillLevel.SkillIndex
				select x).ToList();
		}

		public static List<HeroSkillData> GetSkillDataList(this Hero self, int targetStar = -1)
		{
			List<HeroSkillData> list = new List<HeroSkillData>();
			HeroStarConfigCategory instance = ConfigSingleton<HeroStarConfigCategory>.Instance;
			int num = ((targetStar == -1) ? self.Star : targetStar);
			int num2 = self?.ConfigId ?? 0;
			int num3 = 0;
			while (true)
			{
				int id = num2 * 100 + num3;
				if (!instance.Contain(id))
				{
					break;
				}
				HeroStarConfig heroStarConfig = instance.Get(id);
				if (heroStarConfig.SkillIds != null)
				{
					for (int i = 0; i < heroStarConfig.SkillIds.Length; i++)
					{
						int num4 = heroStarConfig.SkillIds[i];
						if (num4 == 0)
						{
							continue;
						}
						HeroSkillData heroSkillData = new HeroSkillData
						{
							SkillLevel = new SkillLevel(num4),
							UnlockStar = num3,
							IsUnlocked = (num3 <= num)
						};
						if (self == null)
						{
							list.Add(heroSkillData);
							continue;
						}
						while (list.Count <= i)
						{
							list.Add(null);
						}
						if (num3 <= num || list[i] == null)
						{
							list[i] = heroSkillData;
						}
					}
				}
				num3++;
			}
			return (from x in list
				where x != null
				orderby x.SkillLevel.SkillIndex
				select x).ToList();
		}

