		public static HeroCommonInfo GetCommonInfo(this Hero self)
		{
			Player player = self.Player;
			HeroCommonInfo heroCommonInfo = new HeroCommonInfo();
			heroCommonInfo.Id = ((Entity)self).Id;
			heroCommonInfo.ConfigId = self.ConfigId;
			if (self.IsRole())
			{
				heroCommonInfo.Star = player.GetPracticeLevel();
				heroCommonInfo.BodyModelId = player.GetModelId();
				heroCommonInfo.WeaponModelId = player.GetWeaponModelId();
				heroCommonInfo.CapeModelId = player.GetCapeModelId();
			}
			else
			{
				heroCommonInfo.Star = self.Star;
				heroCommonInfo.BodyModelId = self.CurrentSkinModelId;
			}
			heroCommonInfo.Power = self.GetPower();
			heroCommonInfo.Level = self.GetLevel();
			heroCommonInfo.OwnerId = self.GetOwnerPlayerId();
			heroCommonInfo.Stats = self.GetFinalStats()?.Clone();
			heroCommonInfo.SkillLevelIds = self.GetSkills()?.Clone();
			heroCommonInfo.SkinInfo = player.GetSkinInfo(self);
			return heroCommonInfo;
		}

		public static List<JewelryGroupConfig> GetActiveSuitConfigs(this Hero hero, List<JewelryGroupConfig> allConfigs)
		{
			List<JewelryGroupConfig> list = new List<JewelryGroupConfig>();
			foreach (JewelryGroupConfig allConfig in allConfigs)
			{
				bool flag = true;
				int[] jewelyIds = allConfig.JewelyIds;
				foreach (int num in jewelyIds)
				{
					int key = num / 100;
					int num2 = num % 100;
					if (!hero.Jewelrys.TryGetValue(key, out var value) || value < num2)
					{
						flag = false;
						break;
					}
				}
				if (flag)
				{
					list.Add(allConfig);
					continue;
				}
				break;
			}
			return list;
		}

