	public static class HeroJewelryHelper
	{
		public static long GetAllHeroJewelryPower(this Hero self)
		{
			long num = 0L;
			foreach (Hero item in ((Entity)((Entity)self).GetParent<HeroModule>()).Children.Values.Cast<Hero>())
			{
				if (item.Config.Type == 2 && item.Config.JewelryId != null)
				{
					num += item.GetJewelryTotalPower();
				}
			}
			return num;
		}

		public static long GetJewelryTotalPower(this Hero self)
		{
			long num = 0L;
			int[] jewelryId = self.Config.JewelryId;
			foreach (int jewelryId2 in jewelryId)
			{
				long jewelryPower = self.GetJewelryPower(jewelryId2, unActiveIsZero: true);
				num += jewelryPower;
			}
			using PowerCalc powerCalc = PowerCalc.Create();
			foreach (JewelryGroupConfig item in self.GetAllSuit())
			{
				jewelryId = item.JewelySkill;
				foreach (int skillLevelId in jewelryId)
				{
					powerCalc.AddSkill(skillLevelId);
				}
			}
			return num + powerCalc.Power;
		}

		public static long GetJewelryPower(this Hero self, int jewelryId, bool unActiveIsZero = false)
		{
			int value = 0;
			if (unActiveIsZero && !self.Jewelrys.TryGetValue(jewelryId, out value))
			{
				return 0L;
			}
			using PowerCalc powerCalc = PowerCalc.Create();
			JewelryStarConfig jewelryStarConfig = ConfigSingleton<JewelryStarConfigCategory>.Instance.Get(jewelryId * 100 + value);
			Stat[] allStat = jewelryStarConfig.AllStat;
			foreach (Stat stat in allStat)
			{
				powerCalc.AddStat(stat);
			}
			allStat = jewelryStarConfig.Stats;
			if (allStat != null && allStat.Length > 0)
			{
				allStat = jewelryStarConfig.Stats;
				foreach (Stat stat2 in allStat)
				{
					powerCalc.AddStat(stat2);
				}
			}
			int[] skillId = jewelryStarConfig.SkillId;
			if (skillId != null && skillId.Length > 0)
			{
				skillId = jewelryStarConfig.SkillId;
				foreach (int skillLevelId in skillId)
				{
					powerCalc.AddSkill(skillLevelId);
				}
			}
			return powerCalc.Power;
		}

		public static List<Stat> GetActiveJewelryStats(this Hero self, bool unActiveIsZero = false)
		{
			List<Stat> list = new List<Stat>();
			if (self.Jewelrys == null)
			{
				Dictionary<int, int> dictionary = (self.Jewelrys = new Dictionary<int, int>());
			}
			int[] jewelryId = self.Config.JewelryId;
			foreach (int num in jewelryId)
			{
				if (!self.Jewelrys.TryGetValue(num, out var value) & unActiveIsZero)
				{
					int id = num * 100 + 1;
					if (ConfigSingleton<JewelryStarConfigCategory>.Instance.Contain(id))
					{
						Stat[] allStat = ConfigSingleton<JewelryStarConfigCategory>.Instance.Get(id).AllStat;
						foreach (Stat stat in allStat)
						{
							list.Add(new Stat
							{
								Type = stat.Type,
								Value = 0L,
								Scope = stat.Scope
							});
						}
					}
					continue;
				}
				int id2 = num * 100 + value;
				if (ConfigSingleton<JewelryStarConfigCategory>.Instance.Contain(id2))
				{
					JewelryStarConfig jewelryStarConfig = ConfigSingleton<JewelryStarConfigCategory>.Instance.Get(id2);
					list.AddRange(jewelryStarConfig.AllStat);
					Stat[] allStat = jewelryStarConfig.Stats;
					if (allStat != null && allStat.Length > 0)
					{
						list.AddRange(jewelryStarConfig.Stats);
					}
				}
			}
			return list;
		}

		public static JewelryGroupConfig GetActiveSuit(this Hero self)
		{
			return self.GetAllSuit().AsEnumerable().Reverse()
				.FirstOrDefault((JewelryGroupConfig config) => IsJewelrySuitActive(self, config));
		}

		public static List<JewelryGroupConfig> GetAllSuit(this Hero self)
		{
			List<JewelryGroupConfig> list = new List<JewelryGroupConfig>();
			int num = 0;
			while (true)
			{
				int id = self.ConfigId * 100 + num;
				if (!ConfigSingleton<JewelryGroupConfigCategory>.Instance.Contain(id))
				{
					break;
				}
				JewelryGroupConfig jewelryGroupConfig = ConfigSingleton<JewelryGroupConfigCategory>.Instance.Get(id);
				if (jewelryGroupConfig == null || !ConfigSingleton<JewelryGroupConfigCategory>.Instance.Contain(id) || jewelryGroupConfig.JewelyIds.Length == 0)
				{
					break;
				}
				list.Add(jewelryGroupConfig);
				num++;
			}
			return list;
		}

		private static bool IsJewelrySuitActive(Hero self, JewelryGroupConfig config)
		{
			return config.JewelyIds.All(delegate(int jewelryId)
			{
				int num = jewelryId / 100;
				int num2 = jewelryId % 100;
				int key = num;
				int num3 = num2;
				int value;
				return self.Jewelrys.TryGetValue(key, out value) && value >= num3;
			});
		}
	}
	[FriendOf(typeof(HeroModule))]
	public static class HeroModuleSystem
	{
		public static void UpdateTheBestHero(this HeroModule self)
		{
			Player player = self.Player;
			HeroModule heroModule = self;
			(heroModule.Job2TheBestHeroIds ?? (heroModule.Job2TheBestHeroIds = new Dictionary<int, long>(ConfigSingleton<JobConfigCategory>.Instance.GetList().Count + 2))).Clear();
			heroModule = self;
			(heroModule.Job2TheBestHeroPower ?? (heroModule.Job2TheBestHeroPower = new Dictionary<int, long>(ConfigSingleton<JobConfigCategory>.Instance.GetList().Count + 2))).Clear();
			HashSetComponent<int> val = HashSetComponent<int>.Create();
			try
			{
				foreach (Hero item in ((Entity)((Entity)player).GetComponent<HeroModule>()).Children.Values.Cast<Hero>())
				{
					if (!item.IsActive)
					{
						continue;
					}
					HeroConfig config = item.Config;
					if (config.Type != 2 && config.Type != 1)
					{
						continue;
					}
					long power = item.GetPower();
					if (config.Type == 2)
					{
						long valueOrDefault = self.Job2TheBestHeroPower.GetValueOrDefault(0);
						if (power > valueOrDefault)
						{
							((HashSet<int>)(object)val).Add(0);
							self.Job2TheBestHeroIds[0] = ((Entity)item).Id;
							self.Job2TheBestHeroPower[0] = power;
						}
					}
					int num = ((config.Type == 1) ? (-1) : config.Job);
					long valueOrDefault2 = self.Job2TheBestHeroPower.GetValueOrDefault(num);
					if (power > valueOrDefault2)
					{
						((HashSet<int>)(object)val).Add(num);
						self.Job2TheBestHeroIds[num] = ((Entity)item).Id;
						self.Job2TheBestHeroPower[num] = power;
					}
				}
				foreach (int item2 in (HashSet<int>)(object)val)
				{
					Hero theBestHeroByJob = self.GetTheBestHeroByJob(item2);
					long power2 = self.Job2TheBestHeroPower[item2];
					Singleton<EventSystem>.Instance.Publish<BestJobChange>(SceneHelper.DomainScene((Entity)(object)self), new BestJobChange
					{
						Player = player,
						Job = item2,
						HeroConfigId = theBestHeroByJob.ConfigId,
						Star = theBestHeroByJob.Star,
						Power = power2
					});
				}
			}
			finally
			{
				((IDisposable)val)?.Dispose();
			}
		}

		public static Hero GetTheBestHeroByJob(this HeroModule self, int jobId)
		{
			if (self.Job2TheBestHeroIds == null)
			{
				return null;
			}
			long valueOrDefault = self.Job2TheBestHeroIds.GetValueOrDefault(jobId);
			if (valueOrDefault == 0L)
			{
				return null;
			}
			return ((Entity)self).GetChild<Hero>(valueOrDefault);
		}

		public static long GetTheBestPowerByJob(this HeroModule self, int jobId)
		{
			if (self.Job2TheBestHeroPower == null)
			{
				return 0L;
			}
			return self.Job2TheBestHeroPower.GetValueOrDefault(jobId);
		}

		public static Hero GetTheBestHero(this HeroModule self)
		{
			return self.GetTheBestHeroByJob(0);
		}

		public static long GetTheBestPower(this HeroModule self)
		{
			return self.GetTheBestPowerByJob(0);
		}
	}
