	public static class HeroRentInfoComponentSystem
	{
		public static bool IsRentHero(this Hero hero)
		{
			return ((Entity)hero).GetComponent<HeroRentInfoComponent>() != null;
		}

		public static bool IsRentExpired(this Hero hero)
		{
			HeroRentInfoComponent component = ((Entity)hero).GetComponent<HeroRentInfoComponent>();
			if (component == null)
			{
				return false;
			}
			long num = TimeHelper.ClientNow();
			if (num <= component.Info.RentTime)
			{
				return false;
			}
			return ConfigSingleton<GlobalConfigCategory>.Instance.GetOne().HeroRentRecycleType switch
			{
				1 => !TimeHelper.IsSameDay(num, component.Info.RentTime, 18000000L), 
				2 => !TimeHelper.IsSameWeek(num, component.Info.RentTime, 18000000L), 
				_ => false, 
			};
		}
	}
