	[FriendOf(typeof(HeroSkinModule))]
	public static class HeroSkinModuleSystem
	{
		private class DeserializeSystem : DeserializeSystem<HeroSkinModule>
		{
			protected override void Deserialize(HeroSkinModule self)
			{
				self.UpdateHeroSkinDic();
			}
		}

		public static void UpdateHeroSkinDic(this HeroSkinModule self)
		{
			Player player = self.Player;
			if (self.HeroSkinDic == null)
			{
				self.HeroSkinDic = new Dictionary<int, HashSet<int>>();
			}
			self.HeroSkinDic.Clear();
			foreach (HeroSkin item in ((Entity)((Entity)player).GetComponent<HeroSkinModule>()).Children.Values.Cast<HeroSkin>())
			{
				HeroSkinConfig config = item.Config;
				if (!self.HeroSkinDic.ContainsKey(config.HeroId))
				{
					self.HeroSkinDic.Add(config.HeroId, new HashSet<int>());
				}
				self.HeroSkinDic[config.HeroId].Add(item.ConfigId);
			}
		}

		public static void AddHeroSkinDic(this HeroSkinModule self, int configId)
		{
			HeroSkinConfig heroSkinConfig = ConfigSingleton<HeroSkinConfigCategory>.Instance.Get(configId);
			if (heroSkinConfig == null)
			{
				Log.Info($"AddHeroSkinDic Fail:不存在HeroSkinConfig的Id：{configId}");
				return;
			}
			if (!self.HeroSkinDic.ContainsKey(heroSkinConfig.HeroId))
			{
				self.HeroSkinDic.Add(heroSkinConfig.HeroId, new HashSet<int>());
			}
			self.HeroSkinDic[heroSkinConfig.HeroId].Add(heroSkinConfig.Id);
			int heroDefaultSkinId = HeroSkinHelper.GetHeroDefaultSkinId(heroSkinConfig.HeroId);
			if (heroDefaultSkinId != 0)
			{
				self.HeroSkinDic[heroSkinConfig.HeroId].Add(heroDefaultSkinId);
			}
		}

		public static HashSet<int> GetHeroSkinListByHeroId(this HeroSkinModule self, int heroId)
		{
			return self.HeroSkinDic.GetValueOrDefault(heroId);
		}

		public static bool HasHeroSkinByHeroId(this HeroSkinModule self, int heroId, int configId)
		{
			if (self.HeroSkinDic.TryGetValue(heroId, out var value))
			{
				return value.Contains(configId);
			}
			return HeroSkinHelper.GetHeroDefaultSkinId(heroId) == configId;
		}

		public static bool IsMaxStar(this HeroSkinModule self, int configId)
		{
			HeroSkin child = ((Entity)self).GetChild<HeroSkin>((long)configId);
			if (child == null)
			{
				return false;
			}
			int star = child.Star;
			return ConfigSingleton<HeroSkinConfigCategory>.Instance.Contain(star + 1);
		}
	}
