	public static class InvestHelper
	{
		public static int GetLeftCount(this InvestModule self, int cardId)
		{
			InvestCard valueOrDefault = self.InvestCards.GetValueOrDefault(cardId);
			long num = valueOrDefault?.OverTime ?? 0;
			int num2 = ((num > 0) ? (TimeHelper.DaysBetween(num, TimeHelper.Now(), 18000000L) - 1) : 0);
			if (valueOrDefault != null && TimeHelper.IsSameDay(valueOrDefault.GetTime, TimeHelper.Now(), 18000000L))
			{
				num2--;
			}
			return num2;
		}

		public static long GetLeftTime(this InvestModule self, int cardId)
		{
			if (self.InvestCards.TryGetValue(cardId, out var value))
			{
				if (value.OverTime == -1)
				{
					return (int)value.OverTime;
				}
				return value.OverTime - TimeHelper.Now();
			}
			return 0L;
		}

		public static bool IsBuyOver(this InvestModule self, int funcId)
		{
			List<InvestConfig> byFunc = ConfigSingleton<InvestConfigCategory>.Instance.GetByFunc(funcId);
			bool result = true;
			foreach (InvestConfig item in byFunc)
			{
				if (!self.IsBuyCard(item.Id))
				{
					result = false;
					break;
				}
			}
			return result;
		}

		public static bool IsBuyCard(this InvestModule self, int cardId)
		{
			if (!self.InvestCards.TryGetValue(cardId, out var value))
			{
				return false;
			}
			if (value.OverTime != -1)
			{
				if (value.OverTime >= 0)
				{
					return value.OverTime > TimeHelper.Now();
				}
				return false;
			}
			return true;
		}

		public static bool CanGetCardReward(this InvestModule self, int cardId)
		{
			if (self.InvestCards.TryGetValue(cardId, out var value))
			{
				InvestConfig investConfig = ConfigSingleton<InvestConfigCategory>.Instance.Get(cardId);
				if (investConfig.DaliyAwards == null || investConfig.DaliyAwards.Length == 0)
				{
					return false;
				}
				if (self.IsOverTime(investConfig.Id))
				{
					return false;
				}
				if (TimeHelper.IsSameDay(value.GetTime, TimeHelper.Now(), 18000000L))
				{
					return false;
				}
				return true;
			}
			return false;
		}

		public static int CanGetCardRewardRetError(this InvestModule self, int cardId)
		{
			if (!self.InvestCards.TryGetValue(cardId, out var value))
			{
				return 203006;
			}
			InvestConfig investConfig = ConfigSingleton<InvestConfigCategory>.Instance.Get(cardId);
			if (investConfig.DaliyAwards == null || investConfig.DaliyAwards.Length == 0)
			{
				return 203005;
			}
			if (TimeHelper.IsSameDay(value.GetTime, TimeHelper.Now(), 18000000L))
			{
				return 203003;
			}
			return 0;
		}

		public static int GetBuyNum(this InvestModule self, int cardId)
		{
			if (!self.InvestCards.TryGetValue(cardId, out var value))
			{
				return 0;
			}
			return value.BuyNum;
		}

		public static bool IsOverTime(this InvestModule self, int cardId)
		{
			if (!self.InvestCards.TryGetValue(cardId, out var value))
			{
				return false;
			}
			if (value.OverTime > 0)
			{
				return TimeHelper.Now() >= value.OverTime;
			}
			return false;
		}

		public static bool CanRenew(this InvestModule self, int cardId)
		{
			if (!self.InvestCards.TryGetValue(cardId, out var value))
			{
				return false;
			}
			if (value.OverTime <= 0)
			{
				return false;
			}
			InvestConfig investConfig = ConfigSingleton<InvestConfigCategory>.Instance.Get(cardId);
			if (investConfig.LimitNum > 0 && value.BuyNum >= investConfig.LimitNum)
			{
				return false;
			}
			return true;
		}

		public static int PayCheck(Player player, int cardId)
		{
			InvestConfig investConfig = ConfigSingleton<InvestConfigCategory>.Instance.Get(cardId);
			if (investConfig == null)
			{
				return 203300;
			}
			if (!player.IsFuncOpen(investConfig.FunId))
			{
				return 200017;
			}
			if (((Entity)player).GetComponent<InvestModule>() == null)
			{
				return 200017;
			}
			if (investConfig.Condition != null && !player.CheckAllConds(investConfig.Condition))
			{
				return 200017;
			}
			return 0;
		}
	}
