		public static ItemStruct ParseFromString(string itemStr)
		{
			string[] array = itemStr.Split('_');
			if (array.Length < 2)
			{
				return default(ItemStruct);
			}
			int.TryParse(array[0], out var result);
			int.TryParse(array[1], out var result2);
			if (ConfigSingleton<ItemConfigCategory>.Instance.GetFromAll(result) == null || result2 <= 0)
			{
				return default(ItemStruct);
			}
			return new ItemStruct
			{
				ConfigId = result,
				Nums = result2
			};
		}

		public static ItemList ParseListFromString(string itemsStr)
		{
			ItemList itemList = ItemList.Create();
			if (string.IsNullOrEmpty(itemsStr))
			{
				return itemList;
			}
			string[] array = itemsStr.Split(';');
			for (int i = 0; i < array.Length; i++)
			{
				string[] array2 = array[i].Split('_');
				if (array2.Length >= 2)
				{
					int.TryParse(array2[0], out var result);
					int.TryParse(array2[1], out var result2);
					if (GetItemConfig(result) != null && result2 > 0)
					{
						itemList.Add(new ItemStruct
						{
							ConfigId = result,
							Nums = result2
						});
					}
				}
			}
			return itemList;
		}

		public static void ComposeAll(ItemList source, ItemList cost, ItemList result)
		{
			using ItemList itemList = ItemList.Create();
			using ItemList itemList2 = ItemList.Create();
			itemList.AddRange(source);
			int num = 0;
			while (num++ < 20)
			{
				bool flag = false;
				for (int i = 0; i < itemList.Count; i++)
				{
					ItemStruct itemStruct = itemList[i];
					if (itemStruct.Nums <= 0)
					{
						continue;
					}
					ItemConfig itemConfig = GetItemConfig(itemStruct.ConfigId);
					if (itemConfig == null || !itemConfig.IsComposable)
					{
						continue;
					}
					ET.ConfigBeans.Item composeItem = itemConfig.ComposeItem;
					if (composeItem != null && composeItem.Nums > 0)
					{
						long num2 = itemStruct.Nums / itemConfig.ComposeCost;
						if (num2 > 0)
						{
							itemList2.Add(itemConfig.ComposeItem, num2);
							itemList.SetNums(itemStruct.ConfigId, itemStruct.Nums - num2 * itemConfig.ComposeCost);
							flag = true;
						}
					}
				}
				itemList.AddRange(itemList2);
				itemList2.Clear();
				if (!flag)
				{
					break;
				}
			}
			foreach (ItemStruct item3 in source)
			{
				long nums = itemList.GetNums(item3.ConfigId);
				if (nums < item3.Nums)
				{
					ItemStruct item = item3;
					item.Nums -= nums;
					cost.Add(item);
				}
			}
			foreach (ItemStruct item4 in itemList)
			{
				long nums2 = source.GetNums(item4.ConfigId);
				if (nums2 < item4.Nums)
				{
					ItemStruct item2 = item4;
					item2.Nums -= nums2;
					result.Add(item2);
				}
			}
			if (num == 20)
			{
				Log.Warning("Combining item lists failed. 检查配置是否有循环合成道具！");
			}
		}

