		public static long GetItemRefreshCD(this ItemRefreshModule self, int itemId)
		{
			PrivilegeModule component = ((Entity)self.Player).GetComponent<PrivilegeModule>();
			ItemRefreshConfig itemRefreshConfig = ConfigSingleton<ItemRefreshConfigCategory>.Instance.Get(itemId);
			int num = itemRefreshConfig.Interval;
			Array<int>[] privilegeCardIntervalReduce = itemRefreshConfig.PrivilegeCardIntervalReduce;
			if (privilegeCardIntervalReduce != null && privilegeCardIntervalReduce.Length > 0)
			{
				privilegeCardIntervalReduce = itemRefreshConfig.PrivilegeCardIntervalReduce;
				foreach (Array<int> array in privilegeCardIntervalReduce)
				{
					int card = array[0];
					if (component.IsCardValid(card))
					{
						int num2 = array[1];
						num -= num2;
					}
				}
			}
			return (long)num * 1000L;
		}

		public static long GetItemMaxNums(this ItemRefreshModule self, int itemId)
		{
