			ItemRefreshConfig itemRefreshConfig = ConfigSingleton<ItemRefreshConfigCategory>.Instance.Get(itemId);
			int num = itemRefreshConfig.LimitNums;
			Array<int>[] privilegeCardLimitNumsAdd = itemRefreshConfig.PrivilegeCardLimitNumsAdd;
			if (privilegeCardLimitNumsAdd != null && privilegeCardLimitNumsAdd.Length > 0)
			{
				privilegeCardLimitNumsAdd = itemRefreshConfig.PrivilegeCardLimitNumsAdd;
				foreach (Array<int> array in privilegeCardLimitNumsAdd)
				{
					int card = array[0];
					if (component.IsCardValid(card))
					{
						int num2 = array[1];
						num += num2;
					}
				}
			}
			return num;
		}
	}
