		}

		public static long GetLadderRoundTime(this LadderActivityModule self, int roundId)
		{
			if (roundId == 0)
			{
				return 0L;
			}
			long num = self.ActivityData.StartTime;
			List<LadderRoundConfig> list = ConfigSingleton<LadderRoundConfigCategory>.Instance.GetList();
			for (int i = 0; i < list.Count; i++)
			{
				LadderRoundConfig ladderRoundConfig = list[i];
				if (ladderRoundConfig.Id > roundId)
				{
					break;
				}
				num += ladderRoundConfig.RoundTime;
			}
			return num;
		}

		public static int GetLadderRoundId(this LadderActivityModule self)
		{
			ActivityData activityData = self.ActivityData;
			long num = activityData.StartTime;
			long endTime = activityData.EndTime;
			long num2 = TimeHelper.Now();
			if (num2 < num)
			{
				return 0;
			}
			if (endTime < num2)
			{
				return 0;
			}
			List<LadderRoundConfig> list = ConfigSingleton<LadderRoundConfigCategory>.Instance.GetList();
			int result = 0;
			for (int i = 0; i < list.Count; i++)
			{
				LadderRoundConfig ladderRoundConfig = list[i];
				num += ladderRoundConfig.RoundTime;
				if (num > num2)
				{
					result = ladderRoundConfig.Id;
					break;
				}
			}
			return result;
		}

