		public static bool IsAllGet(this LegendShowModule self)
		{
			int currentStage = self.GetCurrentStage();
			List<LegendShowStageConfig> stageConfigs = ConfigSingleton<LegendShowStageConfigCategory>.Instance.GetStageConfigs(self.ActivityData.ActivityId, currentStage);
			for (int i = 0; i < stageConfigs.Count; i++)
			{
				LegendShowStageConfig legendShowStageConfig = stageConfigs[i];
				if (!self.IsGet(legendShowStageConfig.Id))
				{
					return false;
				}
			}
			return true;
		}

		public static int GetCurrentStage(this LegendShowModule self)
		{
			if (TimeHelper.Now() < self.ActivityData.StartTime)
			{
				return -1;
			}
			int num = TimeHelper.DaysBetween(self.ActivityData.StartTime, TimeHelper.Now(), 18000000L);
			List<LegendShowBaseConfig> all = ConfigSingleton<LegendShowBaseConfigCategory>.Instance.GetAll(self.ActivityData.ActivityId);
			if (all == null)
			{
				return -1;
			}
			for (int i = 0; i < all.Count; i++)
			{
				LegendShowBaseConfig legendShowBaseConfig = all[i];
				if (num <= legendShowBaseConfig.Day)
				{
					return legendShowBaseConfig.Stage;
				}
			}
			return -1;
		}

		public static bool IsBetweenActivity(this LegendShowModule self)
		{
			int num = TimeHelper.DaysBetween(self.ActivityData.StartTime, TimeHelper.Now(), 18000000L);
			List<LegendShowBaseConfig> all = ConfigSingleton<LegendShowBaseConfigCategory>.Instance.GetAll(self.ActivityData.ActivityId);
			if (all == null)
			{
				return false;
			}
			all.Sort((LegendShowBaseConfig a, LegendShowBaseConfig b) => a.Id.CompareTo(b.Id));
			if (num <= all[^1].Day)
			{
				return true;
			}
			return false;
		}

