		public static int GetMyRank(this LegendShowModule self, List<RankInfo> rankList, int stage, long id)
		{
			if (rankList == null)
			{
				return -1;
			}
			if (rankList.Count == 0)
			{
				return -1;
			}
			List<RankInfo> rankList2 = self.GetRankList(rankList, stage, id);
			int result = -1;
			for (int i = 0; i < rankList2.Count; i++)
			{
				if (rankList2[i] != null && rankList2[i].Id == id)
				{
					result = i;
				}
			}
			return result;
		}

		public static List<RankInfo> GetRankList(this LegendShowModule self, List<RankInfo> rankList, int stage, long id)
		{
			if (rankList == null && rankList.Count == 0)
			{
				return null;
			}
			List<RankInfo> list = new List<RankInfo>();
			List<LegendShowRankLimitConfig> configs = ConfigSingleton<LegendShowRankLimitConfigCategory>.Instance.GetStageConfigs(self.ActivityData.ActivityId, stage);
			int i;
			for (i = 0; i < configs.Count; i++)
			{
				List<RankInfo> list2 = null;
				if (i > 0)
				{
					Log.Info($"{configs[i].MinScore}   {configs[i - 1].MinScore}");
					list2 = rankList.FindAll((RankInfo x) => x.Value >= configs[i].MinScore && x.Value < configs[i - 1].MinScore);
				}
				else
				{
					list2 = rankList.FindAll((RankInfo x) => x.Value >= configs[i].MinScore);
				}
				if (list2.Count > 0)
				{
					foreach (RankInfo item in list2)
					{
						list.Add(item);
					}
					_ = list2.Count;
				}
				else if (i > list.Count - 1)
				{
					list.Add(null);
				}
			}
			return list;
		}
	}
