	[FriendOf(typeof(Magical))]
	public static class MagicalSystem
	{
		public class DishaAwakeSystem : AwakeSystem<Magical>
		{
			protected override void Awake(Magical self)
			{
				self.ConfigId = (int)((Entity)self).Id;
			}
		}

		public static bool IsTopLevel(this Magical self)
		{
			int maxStage = MagicalHelper.GetMaxStage(self.ConfigId);
			int maxLevel = MagicalHelper.GetMaxLevel(self.ConfigId, self.Stage);
			if (self.Stage >= maxStage && self.Level >= maxLevel)
			{
				return true;
			}
			return false;
		}

		public static bool IsMaxLevel(this Magical self)
		{
			int maxLevel = MagicalHelper.GetMaxLevel(self.ConfigId, self.Stage);
			return self.Level >= maxLevel;
		}

		public static bool IsMaxStage(this Magical self)
		{
			int maxStage = MagicalHelper.GetMaxStage(self.ConfigId);
			return self.Stage >= maxStage;
		}

		public static long GetPower(this Magical self)
		{
			if (!self.IsActive)
			{
				return 0L;
			}
			using PowerCalc powerCalc = PowerCalc.Create();
			powerCalc.AddStats(self.LevelConfig.AddStat);
			int num = self.Stage + (self.IsSuccess ? 1 : 0);
			for (int i = 1; i < num; i++)
			{
				MagicalStageConfig stageConfig = MagicalHelper.GetStageConfig(self.ConfigId, i);
				powerCalc.AddStats(stageConfig.AddStat);
				powerCalc.AddSkill(stageConfig.SkillId);
			}
			return powerCalc.Power;
		}

		public static MagicalLevelConfig GetNextConfig(this Magical self)
		{
			if (self.IsTopLevel())
			{
				return null;
			}
			if (self.IsMaxLevel())
			{
				return ConfigSingleton<MagicalLevelConfigCategory>.Instance.Get(self.ConfigId * 1000 + (self.Stage + 1) * 100);
			}
			return ConfigSingleton<MagicalLevelConfigCategory>.Instance.Get(self.ConfigId * 1000 + self.Stage * 100 + self.Level + 1);
		}

		public static int IsCanUpgrade(this Magical self)
		{
			if (self.GetNextConfig() == null)
			{
				int num = self.ConfigId + 1;
				if (!ConfigSingleton<MagicalLevelConfigCategory>.Instance.Contain(num * 1000 + 100))
				{
					return 200409;
				}
			}
			if (!((Entity)self.Player).GetComponent<ItemModule>().CheckItemNumsIsEnough(self.LevelConfig.Cost))
			{
				return 200102;
			}
			return 0;
		}

		public static void SetUpGrade(this Magical self)
		{
			if (self.IsMaxLevel())
			{
				self.Stage++;
				self.Level = 0;
			}
			else
			{
				self.Level++;
			}
		}
	}
