	public static class PracticeModuleSystem
	{
		public static long GetPracticePower(this PracticeModule self)
		{
			using PowerCalc powerCalc = PowerCalc.Create();
			using StatList statList = StatList.Create();
			int practiceLevel = self.GetPracticeLevel();
			for (int i = 1; i < practiceLevel; i++)
			{
				if (ConfigSingleton<PracticeConfigCategory>.Instance.Contain(i))
				{
					PracticeConfig practiceConfig = ConfigSingleton<PracticeConfigCategory>.Instance.Get(i);
					statList.AddRange(practiceConfig.AddStats, practiceConfig.StatLevel);
					statList.AddRange(practiceConfig.GradeAddStats);
				}
			}
			if (ConfigSingleton<PracticeConfigCategory>.Instance.Contain(practiceLevel))
			{
				Stat[] addStats = ConfigSingleton<PracticeConfigCategory>.Instance.Get(practiceLevel).AddStats;
				foreach (Stat stat in addStats)
				{
					int attrUpTime = self.GetAttrUpTime(stat.Type);
					if (attrUpTime > 0)
					{
						statList.Add(new StatStruct
						{
							Type = stat.Type,
							Value = stat.Value * attrUpTime
						});
					}
				}
			}
			powerCalc.AddStats(statList);
			return powerCalc.Power;
		}

		public static int GetAttrUpTime(this PracticeModule self, int attrType)
		{
			return self.GetOrCreateAttrUpTime(attrType);
		}

		private static int GetOrCreateAttrUpTime(this PracticeModule self, int attrType)
		{
			if (self.AttrLevelDictionary == null)
			{
				Dictionary<int, int> dictionary = (self.AttrLevelDictionary = new Dictionary<int, int>());
			}
			self.AttrLevelDictionary.TryGetValue(attrType, out var value);
			return value;
		}

		public static long GetSkillPower(this PracticeModule self)
		{
			using PowerCalc powerCalc = PowerCalc.Create();
			foreach (var (num3, num4) in self.SkillLevelDict)
			{
				PracticeSkillLevelConfig practiceSkillLevelConfig = ConfigSingleton<PracticeSkillLevelConfigCategory>.Instance.Get(num3 * 10000 + num4);
				powerCalc.AddSkill(practiceSkillLevelConfig.TapSkillId);
				powerCalc.AddStats(practiceSkillLevelConfig.Stats);
			}
			return powerCalc.Power;
		}

		public static bool IsTalentMax(this PracticeModule self, int configId)
		{
			PracticeDestinedTalentConfig practiceDestinedTalentConfig = ConfigSingleton<PracticeDestinedTalentConfigCategory>.Instance.Get(configId);
			self.PracticeTalentDict.TryGetValue(configId, out var value);
			return value >= practiceDestinedTalentConfig.LvMax;
		}

		public static int IsCanActiveTalent(this PracticeModule self, int configId)
		{
			self.PracticeTalentDict.TryGetValue(configId, out var value);
			if (value > 0)
			{
				return 200416;
			}
			PracticeDestinedTalentConfig practiceDestinedTalentConfig = ConfigSingleton<PracticeDestinedTalentConfigCategory>.Instance.Get(configId);
			if (!self.IsCondMeet(practiceDestinedTalentConfig.NodeId, practiceDestinedTalentConfig.Conds))
			{
				return 200415;
			}
			if (self.GetRemaingTalent() < practiceDestinedTalentConfig.Cost)
			{
				return 200414;
			}
			return 0;
		}

		public static int IsCanUpTalent(this PracticeModule self, int configId)
		{
			int remaingTalent = self.GetRemaingTalent();
			PracticeDestinedTalentConfig practiceDestinedTalentConfig = ConfigSingleton<PracticeDestinedTalentConfigCategory>.Instance.Get(configId);
			if (remaingTalent < practiceDestinedTalentConfig.Cost)
			{
				return 200414;
			}
			if (self.GetTalentLevel(configId) >= practiceDestinedTalentConfig.LvMax)
			{
				return 200417;
			}
			if (!self.IsCondMeet(practiceDestinedTalentConfig.NodeId, practiceDestinedTalentConfig.Conds))
			{
				return 200415;
			}
			return 0;
		}

		public static bool IsCondMeet(this PracticeModule self, int nodeId)
