			PracticeDestinedTalentConfig practiceDestinedTalentConfig = ConfigSingleton<PracticeDestinedTalentConfigCategory>.Instance.Get(idByNodeId);
			return self.IsCondMeet(nodeId, practiceDestinedTalentConfig.Conds);
		}

		public static int GetCondNum(this PracticeModule self, int nodeId, int[] conds)
		{
			int num = conds[0];
			_ = conds[1];
			List<int> preIds = PracticeHelper.GetPreIds(nodeId);
			switch (num)
			{
			case 1:
			{
				int num3 = 0;
				for (int j = 0; j < preIds.Count; j++)
				{
					int configId2 = preIds[j];
					int talentLevel2 = self.GetTalentLevel(configId2);
					if (talentLevel2 > num3)
					{
						num3 = talentLevel2;
					}
				}
				return num3;
			}
			case 2:
			{
				int num2 = 0;
				for (int i = 0; i < preIds.Count; i++)
				{
					int configId = preIds[i];
					int talentLevel = self.GetTalentLevel(configId);
					num2 += talentLevel;
				}
				return num2;
			}
			default:
				return 0;
			}
		}

		public static bool IsCondMeet(this PracticeModule self, int nodeId, int[] conds)
		{
			if (conds == null || conds.Length == 0)
			{
				return true;
			}
			List<int> preIds = PracticeHelper.GetPreIds(nodeId);
			int num = conds[0];
			int num2 = conds[1];
			switch (num)
			{
			case 1:
			{
				for (int j = 0; j < preIds.Count; j++)
				{
					int configId2 = preIds[j];
					if (self.GetTalentLevel(configId2) >= num2)
					{
						return true;
					}
				}
				break;
			}
			case 2:
			{
				int num3 = 0;
				for (int i = 0; i < preIds.Count; i++)
				{
					int configId = preIds[i];
					int talentLevel = self.GetTalentLevel(configId);
					num3 += talentLevel;
				}
				if (num3 >= num2)
				{
					return true;
				}
				break;
			}
			default:
				Log.Error("修炼天赋条件配置错误：未找到条件类型{type}");
				break;
			}
			return false;
		}

