		public static int GetRemaingTalent(this PracticeModule self)
		{
			int num = self.GetPracticeGetLevel();
			List<PracticePreviewConfig> list = ConfigSingleton<PracticePreviewConfigCategory>.Instance.GetList();
			list.Sort((PracticePreviewConfig a, PracticePreviewConfig b) => a.Id.CompareTo(b.Id));
			if (num > list[^1].Id)
			{
				num = list[^1].Id;
			}
			PracticePreviewConfig practicePreviewConfig = ConfigSingleton<PracticePreviewConfigCategory>.Instance.Get(num);
			if (practicePreviewConfig != null)
			{
				int talentNum = practicePreviewConfig.TalentNum;
				int usedTalent = self.GetUsedTalent();
				return talentNum - usedTalent;
			}
			return 0;
		}

		public static int GetUsedTalent(this PracticeModule self)
		{
			int num = 0;
			foreach (var (id, num4) in self.PracticeTalentDict)
			{
				PracticeDestinedTalentConfig practiceDestinedTalentConfig = ConfigSingleton<PracticeDestinedTalentConfigCategory>.Instance.Get(id);
				num += practiceDestinedTalentConfig.Cost * num4;
			}
			return num;
		}

		public static int GetPracticeLevel(this PracticeModule self)
		{
			if (self.PracticeLevel == 0)
			{
