		public static int IsCanBreak(this PracticeModule self)
		{
			if (!ConfigSingleton<PracticeConfigCategory>.Instance.Contain(self.GetPracticeLevel()))
			{
				return 200401;
			}
			PracticeConfig practiceConfig = ConfigSingleton<PracticeConfigCategory>.Instance.Get(self.GetPracticeLevel());
			if (self.PracticeUpTotalTime < self.GetMaxUpgradeTime())
			{
				return 200404;
			}
			if (!ConfigSingleton<PracticeConfigCategory>.Instance.Contain(self.GetPracticeLevel() + 1))
			{
				return 200403;
			}
			TaskModule component = ((Entity)((Entity)self).GetParent<Player>()).GetComponent<TaskModule>();
			int[] taskIds = practiceConfig.TaskIds;
			foreach (int id in taskIds)
			{
				TaskData taskData = component.GetTaskData(id);
				if (taskData == null)
				{
					return 200410;
				}
				if (taskData.Status != 3)
				{
					return 200411;
				}
			}
			return 0;
		}
	}
