		public static void RefreshAll(this PrivilegeModule self)
		{
			if (self.Cards == null)
			{
				return;
			}
			self.NearestExpiredTime = 2147483647L;
			self.ValidCards.Clear();
			Array.Clear(self.PrivilegeValues, 0, self.PrivilegeValues.Length);
			foreach (var (card, num3) in self.Cards)
			{
				self.NearestExpiredTime = math.min(self.NearestExpiredTime, num3);
				self.SetCardValid(card);
			}
		}

		public static bool IsCardValid(this PrivilegeModule self, int card)
		{
			return self.GetCardExpiredTime(card) > TimeHelper.Now();
		}

		public static long GetCardExpiredTime(this PrivilegeModule self, int card)
		{
			if (self.Cards == null)
			{
				return 0L;
			}
			return self.Cards.GetValueOrDefault(card);
		}

		public static void UpdateCard(this PrivilegeModule self, int card, long expiredTime)
		{
			self.NearestExpiredTime = math.min(self.NearestExpiredTime, expiredTime);
			if (self.Cards == null)
			{
				self.Cards = new Dictionary<int, long>();
			}
			self.Cards[card] = expiredTime;
			self.SetCardValid(card);
			Singleton<EventSystem>.Instance.Publish<UpdatePrivilegeCard>(SceneHelper.DomainScene((Entity)(object)self), new UpdatePrivilegeCard
			{
				Player = self.Player,
				Id = card,
				ExpiredTime = expiredTime
			});
		}

		public static void UpdateCardWithDuration(this PrivilegeModule self, int card, long duration)
		{
			long cardExpiredTime = self.GetCardExpiredTime(card);
			long num = TimeHelper.Now();
			cardExpiredTime = math.max(cardExpiredTime, num) + duration;
			self.UpdateCard(card, cardExpiredTime);
		}

		public static void RemoveCard(this PrivilegeModule self, int card)
		{
			if (self.Cards != null && self.Cards.Remove(card))
			{
				self.SetCardInvalid(card);
				Singleton<EventSystem>.Instance.Publish<RemovePrivilegeCard>(SceneHelper.DomainScene((Entity)(object)self), new RemovePrivilegeCard
				{
					Player = self.Player,
					Id = card
				});
			}
		}

		private static void SetCardValid(this PrivilegeModule self, int card)
		{
			if (!self.ValidCards.Add(card))
			{
				return;
			}
			PrivilegeCardConfig privilegeCardConfig = ConfigSingleton<PrivilegeCardConfigCategory>.Instance.Get(card);
			if (privilegeCardConfig == null)
			{
				return;
			}
			for (PrivilegeType privilegeType = PrivilegeType.CLDailyCount; privilegeType < PrivilegeType.Max; privilegeType++)
			{
				int num = privilegeCardConfig.Values[(int)privilegeType];
				if (num != 0)
				{
					int oldValue = self.PrivilegeValues[(int)privilegeType];
					self.PrivilegeValues[(int)privilegeType] += num;
					((Entity)self).GetComponent<DataBindComponent>()?.Publish(privilegeType.ToString(), oldValue, self.PrivilegeValues[(int)privilegeType]);
				}
			}
		}

		private static void SetCardInvalid(this PrivilegeModule self, int card)
		{
			if (!self.ValidCards.Remove(card) || !ConfigSingleton<PrivilegeCardConfigCategory>.Instance.Contain(card))
			{
				return;
			}
			PrivilegeCardConfig privilegeCardConfig = ConfigSingleton<PrivilegeCardConfigCategory>.Instance.Get(card);
			for (PrivilegeType privilegeType = PrivilegeType.CLDailyCount; privilegeType < PrivilegeType.Max; privilegeType++)
			{
				int num = privilegeCardConfig.Values[(int)privilegeType];
				if (num != 0)
				{
					int oldValue = self.PrivilegeValues[(int)privilegeType];
					self.PrivilegeValues[(int)privilegeType] -= num;
					((Entity)self).GetComponent<DataBindComponent>()?.Publish(privilegeType.ToString(), oldValue, self.PrivilegeValues[(int)privilegeType]);
				}
			}
		}

		private static void CheckExpired(this PrivilegeModule self)
		{
			if (self.Cards == null)
			{
				return;
			}
			long num = TimeHelper.Now();
			if (num < self.NearestExpiredTime)
			{
				return;
			}
			self.NearestExpiredTime = 2147483647L;
			ListComponent<int> val = ListComponent<int>.Create();
			try
			{
				((List<int>)(object)val).AddRange((IEnumerable<int>)self.ValidCards);
				foreach (int item in (List<int>)(object)val)
				{
					long num2 = self.Cards[item];
					if (num2 > num)
					{
						self.NearestExpiredTime = math.min(num2, self.NearestExpiredTime);
						break;
					}
					self.SetCardInvalid(item);
				}
			}
			finally
			{
				((IDisposable)val)?.Dispose();
			}
		}
	}
