		public static ET.ConfigBeans.Item GetItemCost(this RaffleChoose self)
		{
			if (self.Config.CostItem == null || self.Config.CostItem.Length == 0)
			{
				return null;
			}
			ET.ConfigBeans.Item[] costItem = self.Config.CostItem;
			foreach (ET.ConfigBeans.Item item in costItem)
			{
				if (ConfigSingleton<ItemConfigCategory>.Instance.Get(item.Id).Type == 2)
				{
					return item;
				}
			}
			return null;
		}

		public static ET.ConfigBeans.Item GetCost(this RaffleChoose self)
		{
			ItemModule component = ((Entity)((Entity)((Entity)self).Parent.GetParent<RaffleModule>()).GetParent<Player>()).GetComponent<ItemModule>();
			if (self.Config.CostItem == null || self.Config.CostItem.Length == 0)
			{
				return null;
			}
			if (self.Config.CostItem != null && self.Config.CostItem.Length > 1 && component.GetItemNumsByItemId(self.Config.CostItem[1].Id) > 0)
			{
				return self.Config.CostItem[1];
			}
			for (int num = self.Config.CostItem.Length - 1; num >= 0; num--)
			{
				ET.ConfigBeans.Item item = self.Config.CostItem[num];
				if (component.CheckItemNumsIsEnough(item.Id, item.Nums))
				{
					return item;
				}
			}
			return self.Config.CostItem[0];
		}

		public static bool CheckCost(this RaffleChoose self, bool isCheckQuan = false)
		{
			if (self.IsFree())
			{
				return true;
			}
			ItemModule component = ((Entity)((Entity)((Entity)self).Parent.GetParent<RaffleModule>()).GetParent<Player>()).GetComponent<ItemModule>();
			if (isCheckQuan && self.GetCost() != null && self.GetCost().Id != 99 && !component.CheckItemNumsIsEnough(self.GetCost().Id, self.GetCost().Nums))
			{
				return component.GetItemNumsByItemId(self.GetCost().Id) > 0;
			}
			return component.CheckItemNumsIsEnough(self.GetCost().Id, self.GetCost().Nums);
		}

		public static bool IsHaveRaffleCount(this RaffleChoose self)
		{
			Raffle raffle = ((Entity)self).Parent as Raffle;
			if (raffle.TodayCount >= raffle.Config.LimitNum && !self.IsFree())
			{
				return true;
			}
			return false;
		}

		public static int CanRaffle(this RaffleChoose self, bool isCheckQuan = false)
		{
			Raffle raffle = ((Entity)self).Parent as Raffle;
			if (raffle.Type == 42)
			{
				int num = ((Entity)((Entity)((Entity)self).Parent.GetParent<RaffleModule>()).GetParent<Player>()).GetComponent<BeastModule>().CheckCanRaffle();
				if (num != 0)
				{
					return num;
				}
			}
			if (raffle.TodayCount >= raffle.Config.LimitNum && !self.IsFree())
			{
				return 203103;
			}
			if (!raffle.IsValid())
			{
				return 203105;
			}
			if (self.IsFree())
			{
				if (raffle.GetFreeCDTime() > 0)
				{
					return 203101;
				}
			}
			else if (!self.CheckCost(isCheckQuan))
			{
				return 203100;
			}
			return 0;
		}

