		public static long GetFreeCDTime(this Raffle self)
		{
			if (self.LastFreeTime == 0L)
			{
				return 0L;
			}
			long num = TimeHelper.ServerNow();
			if (self.Config.FreeTime[0] == 1)
			{
				long num2 = self.LastFreeTime + (long)self.Config.FreeTime[1] * 1000L;
				return Math.Max(0L, num2 - num);
			}
			if (self.Config.FreeTime[0] == 3)
			{
				return 0L;
			}
			if (!TimeHelper.IsSameDay(self.LastFreeTime, num, 18000000L))
			{
				return 0L;
			}
			if (self.Config.FreeCount > 0 && self.TodayFreeCount >= self.Config.FreeCount)
			{
				return Math.Max(0L, TimeHelper.EndTimeOfDay(num, 18000000L) - num);
			}
			long num3 = self.LastFreeTime + (long)self.Config.FreeTime[1] * 1000L;
			return Math.Max(0L, num3 - num);
		}

		public static long GetScore(this Raffle self)
		{
			if (self.Config.AddScore == null)
			{
				return 0L;
			}
			return ((Entity)((Entity)((Entity)self).GetParent<RaffleModule>()).GetParent<Player>()).GetComponent<ItemModule>().GetItemNumsByItemId(self.Config.AddScore.Id);
		}

