			{
				if (raffleZwConfig2.ZwTgId == zwId && self.GetOpenCount == raffleZwConfig2.OpenCount)
				{
					return raffleZwConfig2;
				}
			}
			return null;
		}

		public static void CulOpencount(this Raffle self)
		{
			long num = TimeHelper.BeginTimeOfDay(TimeHelper.ServerNow(), 18000000L);
			if (self.Config.Id == 5)
			{
				if (self.CreatePoolTime <= 0)
				{
					self.CreatePoolTime = num;
				}
				if ((num - self.CreatePoolTime) / 86400000 > ConfigSingleton<RaffleGlobalConfigCategory>.Instance.GetOne().RaffleTgDayTime)
				{
					self.OpenCount++;
					self.CreatePoolTime = num;
				}
				if (self.OpenCount > ConfigSingleton<RaffleGlobalConfigCategory>.Instance.GetOne().RaffleTgMaxOpenCount)
				{
					self.OpenCount = ConfigSingleton<RaffleGlobalConfigCategory>.Instance.GetOne().RaffleTgMaxOpenCount;
				}
				Log.Info($"CreatePoolTime ===={self.OpenCount}    {TimeHelper.ToDateTime(num)}    {TimeHelper.ToDateTime(self.CreatePoolTime)}");
			}
			else if (self.Config.Id == 4)
			{
				self.OpenCount = 1;
			}
		}
	}
	public static class RankRewardHelper
	{
		public static long MakeLong(int a, int b)
		{
			return ((long)a << 32) | (uint)b;
		}

		public static (int high, int low) Split(long num)
		{
			int item = (int)(num >> 32);
			int item2 = (int)(num & 0xFFFFFFFFu);
			return (high: item, low: item2);
		}
	}
