	{
		public static long GetNextRefreshTime(this RiverMapModule self)
		{
			int[] refreshTime = ConfigSingleton<RiverMapGlobalConfigCategory>.Instance.GetOne().RefreshTime;
			long num = TimeHelper.Now();
			long num2 = TimeHelper.BeginTimeOfDay(num, 0L);
			long num3 = num - num2;
			long num4 = long.MaxValue;
			int[] array = refreshTime;
			for (int i = 0; i < array.Length; i++)
			{
				long num5 = (long)array[i] * 1000L;
				long num6 = ((num5 <= num3) ? (86400000 - num3 + num5) : (num5 - num3));
				if (num6 < num4)
				{
					num4 = num6;
				}
			}
			return num4;
		}

		public static RiverMapEventData CreateEvent(this RiverMapModule self, int mainType, int configId, long uid = 0L)
		{
			RiverMapEventData riverMapEventData = null;
			riverMapEventData = ((uid == 0L) ? ((Entity)self).AddChild<RiverMapEventData, int, int>(mainType, configId, false) : ((Entity)self).AddChildWithId<RiverMapEventData, int, int>(uid, mainType, configId, false));
			switch (riverMapEventData.EventType)
			{
			case 1:
				((Entity)riverMapEventData).AddComponent<RiverMapEventAnswer>(false);
				break;
			case 2:
				((Entity)riverMapEventData).AddComponent<RiverMapEventStore>(false);
				break;
			case 4:
				((Entity)riverMapEventData).AddComponent<RiverMapEventDupBox>(false);
				break;
			case 3:
				((Entity)riverMapEventData).AddComponent<RiverMapEventDupMonster>(false);
				break;
			case 5:
				((Entity)riverMapEventData).AddComponent<RiverMapEventDupRescue>(false);
				break;
			}
			return riverMapEventData;
		}

		public static bool ShowMopUpBtn(Player player, RiverMapEventData eventData)
		{
			if (eventData.MainType == 4)
			{
				return false;
			}
			if (eventData.EventType != 4 && eventData.EventType != 3)
			{
				return false;
			}
			bool flag = ((Entity)player).GetComponent<PrivilegeModule>().GetValue(PrivilegeType.PassRiverMapDup) > 0;
			bool flag2 = ((Entity)player).GetComponent<ItemModule>().GetItemNumsByItemId(102) > 0;
			long power = player.GetPower();
			long num = ((eventData.EventType == 4) ? ((Entity)eventData).GetComponent<RiverMapEventDupBox>().Config.Power : ((Entity)eventData).GetComponent<RiverMapEventDupMonster>().Config.Power);
			if (power >= num && (flag | flag2))
			{
				return true;
			}
			return false;
		}

		public static int CheckCanMopUp(Player player, RiverMapEventData eventData, int level)
		{
			if (eventData.EventType != 4 && eventData.EventType != 3)
			{
				return 201920;
			}
			bool num = ((Entity)player).GetComponent<PrivilegeModule>().GetValue(PrivilegeType.PassRiverMapDup) > 0;
			bool flag = ((Entity)player).GetComponent<ItemModule>().GetItemNumsByItemId(102) > 0;
			if (!num && !flag)
			{
				return 203801;
			}
			long power = player.GetPower();
			long num2 = ((eventData.EventType == 4) ? ((Entity)eventData).GetComponent<RiverMapEventDupBox>().Config.Power : ((Entity)eventData).GetComponent<RiverMapEventDupMonster>().Config.Power);
			if (power < num2)
			{
				return 201918;
			}
			if (!((Entity)player).GetComponent<ItemModule>().CheckItemNumsIsEnough(25, eventData.Config.Ticket))
			{
				return 201919;
			}
			if (eventData.MainType == 1 && eventData.IsExpired)
			{
				return 201908;
			}
			if (eventData.MainType == 3)
			{
				RiverMapEventPostConfig riverMapEventPostConfig = ConfigSingleton<RiverMapEventPostConfigCategory>.Instance.Get(eventData.PostId);
				if (TimeHelper.Now() - eventData.LastFinishTime < riverMapEventPostConfig.CDTime * 1000)
				{
					return 201915;
				}
				Cond[] conds = riverMapEventPostConfig.Conds;
				if (conds.Length != 0 && !player.CheckAllConds(conds))
				{
					return 201915;
				}
			}
			return 0;
		}
	}
