		public static SevenDayTargetData GetTaskData(this SevenDayTargetModule self, int configId)
		{
			SevenDayTargetConfig sevenDayTargetConfig = ConfigSingleton<SevenDayTargetConfigCategory>.Instance.Get(configId);
			if (sevenDayTargetConfig == null)
			{
				return null;
			}
			int day = sevenDayTargetConfig.Day;
			if (!self.TaskList.TryGetValue(day, out var value))
			{
				return null;
			}
			if (value.Count <= 0)
			{
				return null;
			}
			return value.Find((SevenDayTargetData m) => m != null && m.Id == configId);
		}

		public static int GetTaskGetedCount(this SevenDayTargetModule self)
		{
			int num = 0;
			foreach (KeyValuePair<int, List<SevenDayTargetData>> task in self.TaskList)
			{
				task.Deconstruct(out var _, out var value);
				foreach (SevenDayTargetData item in value)
				{
					if (item.Status == 3)
					{
						num++;
					}
				}
			}
			return num;
		}
	}
