	[FriendOf(typeof(Hero))]
	[FriendOf(typeof(SkillBagComponent))]
	public static class SkillBagComponentSystem
	{
		public class AwakeSystem : AwakeSystem<SkillBagComponent>
		{
			protected override void Awake(SkillBagComponent self)
			{
				self.IsDirty = true;
			}
		}

		private static void CheckAndUpdate(this SkillBagComponent self)
		{
			if (!self.IsDirty)
			{
				return;
			}
			self.IsDirty = false;
			self.Power = 0L;
			self.SkillLevelIds?.Clear();
			Hero hero = self.Hero;
			HeroConfig config = hero.Config;
			using SkillList skillList = SkillList.Create();
			skillList.AddRange(config.SkillLevelIds);
			HeroRentInfoComponent component = ((Entity)hero).GetComponent<HeroRentInfoComponent>();
			if (component != null)
			{
				skillList.AddRange(component.Info.HeroInfo.SkillLevelIds);
			}
			else if (hero.IsRole())
			{
				self.SetRoleSkills(skillList);
			}
			else
			{
				self.SetHeroSkills(skillList);
			}
			if (self.SkillLevelIds == null)
			{
				self.SkillLevelIds = new List<int>();
			}
			foreach (int item in skillList)
			{
				self.SkillLevelIds.Add(item);
				if (new SkillLevel(item).IsActiveSkill)
				{
					ActiveSkillLevelConfig activeSkillLevelConfig = ConfigSingleton<ActiveSkillLevelConfigCategory>.Instance.Get(item);
					if (activeSkillLevelConfig == null)
					{
						Log.Error($"ActiveSkill level config id is null: {item}");
					}
					else
					{
						self.Power += activeSkillLevelConfig.Power;
					}
				}
				else
				{
					PassiveSkillLevelConfig passiveSkillLevelConfig = ConfigSingleton<PassiveSkillLevelConfigCategory>.Instance.Get(item);
					if (passiveSkillLevelConfig == null)
					{
						Log.Error($"PassiveSkill level config id is null: {item}");
					}
					else
					{
						self.Power += passiveSkillLevelConfig.Power;
					}
				}
			}
		}

		private static void SetHeroSkills(this SkillBagComponent self, SkillList skillList)
		{
			Hero hero = self.Hero;
			HeroStarConfig heroStarConfig = ConfigSingleton<HeroStarConfigCategory>.Instance.Get(hero.ConfigId * 100 + hero.Star);
			skillList.AddRange(heroStarConfig.SkillIds);
			int value;
			int key;
			if (hero.ActiveTalentNodes != null)
			{
				foreach (KeyValuePair<int, int> activeTalentNode in hero.ActiveTalentNodes)
				{
					activeTalentNode.Deconstruct(out value, out key);
					int id = key;
					HeroTalentConfig heroTalentConfig = ConfigSingleton<HeroTalentConfigCategory>.Instance.Get(id);
					if (heroTalentConfig.Skill > 0)
					{
						skillList.Add(heroTalentConfig.Skill);
					}
				}
			}
			int[] skillId;
			if (hero.Jewelrys != null)
			{
				foreach (KeyValuePair<int, int> jewelry in hero.Jewelrys)
				{
					jewelry.Deconstruct(out key, out value);
					int num = key;
					int num2 = value;
					int id2 = num * 100 + num2;
					JewelryStarConfig jewelryStarConfig = ConfigSingleton<JewelryStarConfigCategory>.Instance.Get(id2);
					skillId = jewelryStarConfig.SkillId;
					if (skillId != null && skillId.Length > 0)
					{
						skillList.AddRange(jewelryStarConfig.SkillId);
					}
				}
			}
			JewelryGroupConfig activeSuit = hero.GetActiveSuit();
			skillId = activeSuit?.JewelySkill;
			if (skillId != null && skillId.Length > 0)
			{
				skillList.AddRange(activeSuit.JewelySkill);
			}
			int soulSkill = ((Entity)self.Hero.Player).GetComponent<VibesSoulModule>().GetSoulSkill(self.Hero.Config.Job);
			if (soulSkill > 0)
			{
				skillList.Add(soulSkill);
			}
			foreach (int faBao in self.Hero.FaBaoList)
			{
				FaBao child = ((Entity)((Entity)self.Hero.Player).GetComponent<FaBaoModule>()).GetChild<FaBao>((long)faBao);
				if (child == null)
				{
					continue;
				}
				FaBaoStarConfig faBaoStarConfig = ConfigSingleton<FaBaoStarConfigCategory>.Instance.Get(child.ConfigId, child.Star);
				if (SkillHelper.HasSkillConfig(faBaoStarConfig.SkillIds))
				{
					skillList.Add(faBaoStarConfig.SkillIds);
				}
				if (SkillHelper.HasSkillConfig(faBaoStarConfig.MasterSkillId) && child.Config.HeroId == self.Hero.ConfigId)
				{
					skillList.Add(faBaoStarConfig.MasterSkillId);
				}
				foreach (long soulId in child.GetSoulIdList())
				{
					FaBaoSoul child2 = ((Entity)((Entity)self.Hero.Player).GetComponent<FaBaoSoulModule>()).GetChild<FaBaoSoul>(soulId);
					if (child2 == null && child2.Config.SkillLevelId != 0)
					{
						skillList.Add(child2.Config.SkillLevelId);
					}
				}
			}
		}

		private static void SetRoleSkills(this SkillBagComponent self, SkillList skillList)
		{
			Player player = self.Hero.Player;
			PracticeModule component = ((Entity)player).GetComponent<PracticeModule>();
			int value;
			int key;
			if (component != null && component.SkillLevelDict != null)
			{
				foreach (KeyValuePair<int, int> item in component.SkillLevelDict)
				{
					item.Deconstruct(out value, out key);
					int num = value;
					int num2 = key;
					PracticeSkillLevelConfig practiceSkillLevelConfig = ConfigSingleton<PracticeSkillLevelConfigCategory>.Instance.Get(num * 10000 + num2);
					skillList.Add(practiceSkillLevelConfig.SkillId);
				}
			}
			TiangangModule component2 = ((Entity)player).GetComponent<TiangangModule>();
			if (component2 == null)
			{
				return;
