			{
				Tiangang tiangang = value2 as Tiangang;
				if (tiangang.IsLade())
				{
					skillList.Add(tiangang.StageConfig.SkillIds);
				}
			}
			if (component2.ActiveSuitList != null)
			{
				foreach (int activeSuit in component2.ActiveSuitList)
				{
					TianGangSuitConfig tianGangSuitConfig = ConfigSingleton<TianGangSuitConfigCategory>.Instance.Get(activeSuit);
					skillList.Add(tianGangSuitConfig.ElementSkill);
				}
			}
			foreach (Entity value3 in ((Entity)((Entity)player).GetComponent<MagicalModule>()).Children.Values)
			{
				Magical magical = value3 as Magical;
				if (magical.IsActive)
				{
					if (magical.IsSuccess)
					{
						skillList.Add(magical.StageConfig.SkillId);
					}
					else if (ConfigSingleton<MagicalStageConfigCategory>.Instance.Contain(magical.ConfigId * 100 + magical.Stage - 1))
					{
						MagicalStageConfig magicalStageConfig = ConfigSingleton<MagicalStageConfigCategory>.Instance.Get(magical.ConfigId * 100 + magical.Stage - 1);
						skillList.Add(magicalStageConfig.SkillId);
					}
				}
			}
			int soulSkill = ((Entity)player).GetComponent<VibesSoulModule>().GetSoulSkill(self.Hero.Config.Job);
			if (soulSkill > 0)
			{
				skillList.Add(soulSkill);
			}
			foreach (KeyValuePair<int, int> item2 in component.PracticeTalentDict)
			{
				item2.Deconstruct(out key, out value);
				int id = key;
				int num3 = value;
				PracticeDestinedTalentConfig practiceDestinedTalentConfig = ConfigSingleton<PracticeDestinedTalentConfigCategory>.Instance.Get(id);
				if (num3 > 0 && practiceDestinedTalentConfig.Skill > 0)
				{
					skillList.Add(new SkillLevel(practiceDestinedTalentConfig.Skill, num3).SkillLevelId);
				}
			}
			foreach (int faBao in self.Hero.FaBaoList)
			{
				FaBao child = ((Entity)((Entity)self.Hero.Player).GetComponent<FaBaoModule>()).GetChild<FaBao>((long)faBao);
				if (child == null)
				{
					continue;
				}
				FaBaoStarConfig faBaoStarConfig = ConfigSingleton<FaBaoStarConfigCategory>.Instance.Get(child.ConfigId, child.Star);
				if (SkillHelper.HasSkillConfig(faBaoStarConfig.SkillIds))
				{
					skillList.Add(faBaoStarConfig.SkillIds);
				}
				if (SkillHelper.HasSkillConfig(faBaoStarConfig.MasterSkillId) && child.Config.HeroId == self.Hero.ConfigId)
				{
					skillList.Add(faBaoStarConfig.MasterSkillId);
				}
				foreach (long soulId in child.GetSoulIdList())
