					if (child2 == null && child2.Config.SkillLevelId != 0)
					{
						skillList.Add(child2.Config.SkillLevelId);
					}
				}
			}
		}

		public static void SetDirty(this SkillBagComponent self, bool isDirty = true)
		{
			self.IsDirty = isDirty;
		}

		public static long GetPower(this SkillBagComponent self)
		{
			self.CheckAndUpdate();
			return self.Power;
		}

		public static SkillBagComponent GetSkillBagComponent(this Hero hero)
		{
			return ((Entity)hero).GetComponent<SkillBagComponent>() ?? ((Entity)hero).AddComponent<SkillBagComponent>(false);
		}

		public static List<int> GetSkills(this Hero hero)
		{
			SkillBagComponent skillBagComponent = hero.GetSkillBagComponent();
			skillBagComponent.CheckAndUpdate();
			return skillBagComponent.SkillLevelIds;
		}

		public static void UpdateSkill(this Hero hero)
		{
			((Entity)hero).GetComponent<SkillBagComponent>()?.SetDirty();
			Singleton<EventSystem>.Instance.Publish<HeroSkillChange>(SceneHelper.DomainScene((Entity)(object)hero), new HeroSkillChange
			{
				Hero = hero
			});
			if (hero.IsRole())
			{
				hero.Player.UpdateRoleStats(StatBagType.Skill);
			}
			else
			{
				hero.Player.UpdateHeroStats(hero.ConfigId, StatBagType.Skill);
			}
		}

		public static void UpdateJobSkill(this Player player, int job)
		{
			List<Hero> heroes = ((Entity)player).GetComponent<HeroModule>().GetHeroes(new HeroSearch
			{
				Job = job,
				OnlyActive = true,
				Includes = HeroInclude.All
			});
			for (int i = 0; i < heroes.Count; i++)
			{
				heroes[i].UpdateSkill();
			}
		}

		public static void AddHeroStarSkills(this SkillList skillList, int heroConfigId, int star)
		{
			int id = heroConfigId * 100 + star;
			if (ConfigSingleton<HeroStarConfigCategory>.Instance.Contain(id))
			{
				HeroStarConfig heroStarConfig = ConfigSingleton<HeroStarConfigCategory>.Instance.Get(id);
				if (heroStarConfig.SkillIds != null)
				{
					skillList.AddRange(heroStarConfig.SkillIds);
				}
			}
		}
	}
	public static class SkillHelper
	{
		private static int HigherCurrentHp(Unit a, Unit b)
		{
			return b.GetCurrentHpPct() - a.GetCurrentHpPct();
		}

		private static int LowerCurrentHp(Unit a, Unit b)
		{
			return a.GetCurrentHpPct() - b.GetCurrentHpPct();
		}

		private static int HigherAttack(Unit a, Unit b)
		{
