					break;
				}
				int multiple = math.min(level - vibesLevelConfig.StartLv + 1, vibesLevelConfig.EndLv - vibesLevelConfig.StartLv + 1);
				statList.AddRange(vibesLevelConfig.AddStats, multiple);
			}
			VibesLevelBreakConfig vibesLevelBreakConfig = (VibesHelper.IsNeedBreak(player, jobId) ? VibesHelper.GetLevelBreakConfig(jobId, level - 1) : VibesHelper.GetLevelBreakConfig(jobId, level));
			if (vibesLevelBreakConfig != null)
			{
				statList.AddRange(vibesLevelBreakConfig.AddStats);
			}
		}

		protected override void UpdateTeam(Player player, StatList updateList)
		{
		}
	}
	[FriendOf(typeof(VibesLevelModule))]
