	public class ModuleStatBagUpdater_PracticeLevel : AStatBagUpdater
	{
		public override void UpdateHero(Player player, StatList updateList, int heroId)
		{
			HeroConfig heroConfig = ConfigSingleton<HeroConfigCategory>.Instance.Get(heroId);
			if (heroConfig == null || heroConfig.Type != 1)
			{
				return;
			}
			PracticeModule component = ((Entity)player).GetComponent<PracticeModule>();
			if (component == null)
			{
				return;
			}
			int practiceLevel = component.GetPracticeLevel();
			for (int i = 1; i < practiceLevel; i++)
			{
				if (ConfigSingleton<PracticeConfigCategory>.Instance.Contain(i))
				{
					PracticeConfig practiceConfig = ConfigSingleton<PracticeConfigCategory>.Instance.Get(i);
					updateList.AddRange(practiceConfig.AddStats, practiceConfig.StatLevel);
					updateList.AddRange(practiceConfig.GradeAddStats);
				}
			}
			if (!ConfigSingleton<PracticeConfigCategory>.Instance.Contain(practiceLevel))
			{
				return;
			}
			Stat[] addStats = ConfigSingleton<PracticeConfigCategory>.Instance.Get(practiceLevel).AddStats;
			foreach (Stat stat in addStats)
			{
				int attrUpTime = component.GetAttrUpTime(stat.Type);
				if (attrUpTime > 0)
				{
					updateList.Add(new StatStruct
					{
						Type = stat.Type,
						Value = stat.Value * attrUpTime
					});
				}
			}
		}

