	[FriendOf(typeof(VibesSoulModule))]
	[StatBagUpdater(StatBagType.Soul)]
	public class ModuleStatBagUpdater_Soul : AStatBagUpdater
	{
		public override void UpdateHero(Player player, StatList updateList, int heroId)
		{
		}

		protected override void UpdateJob(Player player, StatList updateList, int job)
		{
			if (((Entity)player).GetComponent<VibesSoulModule>() == null)
			{
				return;
			}
			VibesSoulData soulData = ((Entity)player).GetComponent<VibesSoulModule>().GetSoulData(job);
			int stage = soulData.Stage;
			for (int i = 0; i <= stage; i++)
			{
				VibesSoulStageConfig vibesSoulStageConfig = ConfigSingleton<VibesSoulStageConfigCategory>.Instance.Get(job * 1000 + i);
				if (vibesSoulStageConfig.Stats != null)
				{
					updateList.AddRange(vibesSoulStageConfig.Stats);
				}
				if (i == stage)
				{
					int num = soulData.UpCount;
					List<VibesSoulConfig> soulConfigs = VibesHelper.GetSoulConfigs(job, stage, soulData.UpCount);
					for (int j = 0; j < soulConfigs.Count; j++)
					{
						VibesSoulConfig vibesSoulConfig = soulConfigs[j];
						int num2 = Math.Min(num, vibesSoulConfig.Count);
						for (int k = 0; k < num2; k++)
						{
							updateList.AddRange(vibesSoulConfig.Stats);
						}
						num -= vibesSoulConfig.Count;
					}
					continue;
				}
				List<VibesSoulConfig> soulConfigs2 = VibesHelper.GetSoulConfigs(job, i);
				for (int l = 0; l < soulConfigs2.Count; l++)
				{
					VibesSoulConfig vibesSoulConfig2 = soulConfigs2[l];
					for (int m = 0; m < vibesSoulConfig2.Count; m++)
					{
						updateList.AddRange(vibesSoulConfig2.Stats);
					}
				}
			}
		}

		protected override void UpdateTeam(Player player, StatList updateList)
		{
		}
	}
