	[FriendOf(typeof(StatBagComponent))]
	public static class StatBagComponentSystem
	{
		public static Dictionary<ushort, long> GetFinalStats(this Hero hero)
		{
			HeroRentInfoComponent component = ((Entity)hero).GetComponent<HeroRentInfoComponent>();
			if (component != null)
			{
				return component.Info.HeroInfo.Stats;
			}
			return hero.GetStatBagComponent().GetFinalMap();
		}

		public static Dictionary<ushort, long> GetRawStats(this Hero hero)
		{
			HeroRentInfoComponent component = ((Entity)hero).GetComponent<HeroRentInfoComponent>();
			if (component != null)
			{
				return component.Info.HeroInfo.Stats;
			}
			return hero.GetStatBagComponent().GetBasAndPctMap();
		}

		public static StatBagComponent GetStatBagComponent(this Hero hero)
		{
			return ((Entity)hero).GetComponent<StatBagComponent>() ?? ((Entity)hero).AddComponent<StatBagComponent>(false);
		}

		public static long GetPower(this StatBagComponent self)
		{
			self.CheckAndUpdate();
			return self.Power;
		}

		public static Dictionary<ushort, long> GetFinalMap(this StatBagComponent self)
		{
			self.CheckAndUpdate();
			return self.FinalMap;
		}

		public static Dictionary<ushort, long> GetBasAndPctMap(this StatBagComponent self)
		{
			self.CheckAndUpdate();
			return self.BasAndPctMap;
		}

		private static void UpdateFromSubBagStats(Dictionary<ushort, long> mainBagDic, Dictionary<ushort, long> subBagDic, StatList outBasStatList)
		{
			foreach (var (num3, num4) in subBagDic)
			{
				ushort basType = StatHelper.GetBasType(num3);
				if (basType == num3)
				{
					outBasStatList.Add(new StatStruct
					{
						Type = basType,
						Value = num4
					});
				}
				else
				{
					long value = StatHelper.CalcPctAddValue(mainBagDic?.GetValueOrDefault(basType) ?? 0, num4);
					StatStruct stat = new StatStruct
					{
						Type = basType,
						Value = value
					};
					outBasStatList.Add(stat);
				}
			}
		}

		private static void UpdateFromMainBagStats(Dictionary<ushort, long> mainBagDic, StatList outBasStatList, StatList outPctStatList)
		{
			foreach (var (type, value) in mainBagDic)
			{
				StatStruct statStruct = new StatStruct
				{
					Type = type,
					Value = value
				};
				if (statStruct.IsBasStat())
				{
					outBasStatList.Add(statStruct);
				}
				else
				{
					outPctStatList.Add(statStruct);
				}
			}
		}

		private static void CheckAndUpdate(this StatBagComponent self)
		{
			Hero hero = self.Hero;
			StatModule component = ((Entity)hero.Player).GetComponent<StatModule>();
			bool flag = false;
			foreach (StatBagConfig item in ConfigSingleton<StatBagConfigCategory>.Instance.GetList())
			{
				StatBag statBag = component.GetStatBag(item.StatBagType);
				if (self.BagVersions.GetValueOrDefault(statBag.Type) == statBag.Version)
				{
					continue;
				}
				self.BagVersions[statBag.Type] = statBag.Version;
				flag = true;
				using StatList statList = StatList.Create();
				statBag.ReadHeroStats(statList, hero.ConfigId);
				if (self.BagStats.TryGetValue(statBag.Type, out var value))
				{
					value.Clear();
				}
				if (statList.Count == 0)
				{
					continue;
				}
				if (value == null)
				{
					value = (self.BagStats[statBag.Type] = new Dictionary<ushort, long>());
				}
				foreach (StatStruct item2 in statList)
				{
					value[item2.Type] = item2.Value;
				}
			}
			if (!flag)
			{
				return;
			}
			self.Power = 0L;
			self.FinalMap.Clear();
			self.BasAndPctMap.Clear();
			using StatList statList2 = StatList.Create();
			using StatList statList3 = StatList.Create();
			foreach (var (statBagType2, mainBagDic) in self.BagStats)
			{
				StatBagConfig statBagConfig = ConfigSingleton<StatBagConfigCategory>.Instance.Get(statBagType2);
				if (!statBagConfig.IsMain)
				{
					continue;
				}
				UpdateFromMainBagStats(mainBagDic, statList2, statList3);
				List<StatBagType> subStatBagTypes = statBagConfig.SubStatBagTypes;
				if (subStatBagTypes == null || subStatBagTypes.Count <= 0)
				{
					continue;
				}
				foreach (StatBagType subStatBagType in statBagConfig.SubStatBagTypes)
				{
					Dictionary<ushort, long> valueOrDefault = self.BagStats.GetValueOrDefault(subStatBagType);
					if (valueOrDefault != null && valueOrDefault.Count > 0)
					{
						UpdateFromSubBagStats(mainBagDic, valueOrDefault, statList2);
					}
				}
			}
			foreach (StatStruct item3 in statList2)
			{
				long value2 = item3.Value;
				long value3 = statList3.GetValue(item3.GetPctType());
				long num = StatHelper.CalcFinalValue(value2, value3);
				self.FinalMap.Add(item3.Type, num);
				self.BasAndPctMap.Add(item3.Type, value2);
				if (value3 != 0L)
				{
					self.BasAndPctMap.Add(item3.GetPctType(), value3);
				}
				self.Power += ConfigSingleton<StatConfigCategory>.Instance.Get(item3.Type).PowerFactor * num / 100;
			}
		}

		public static void GetStatsByStatBags(this StatBagComponent self, StatList result, params StatBagType[] types)
		{
			self.CheckAndUpdate();
			foreach (StatBagType type in types)
			{
				self.GetStatsByStatBagInternal(result, type);
			}
		}

		public static void GetStatsByStatBag(this StatBagComponent self, StatList result, StatBagType type)
		{
			self.CheckAndUpdate();
			self.GetStatsByStatBagInternal(result, type);
		}

		private static void GetStatsByStatBagInternal(this StatBagComponent self, StatList result, StatBagType type)
		{
			Dictionary<ushort, long> valueOrDefault = self.BagStats.GetValueOrDefault(type);
			if (valueOrDefault == null)
			{
				return;
			}
			StatBagConfig statBagConfig = ConfigSingleton<StatBagConfigCategory>.Instance.Get(type);
			if (statBagConfig.IsMain)
			{
				using (StatList statList = StatList.Create())
				{
					using StatList statList2 = StatList.Create();
					UpdateFromMainBagStats(valueOrDefault, statList, statList2);
					List<StatBagType> subStatBagTypes = statBagConfig.SubStatBagTypes;
					if (subStatBagTypes != null && subStatBagTypes.Count > 0)
					{
						foreach (StatBagType subStatBagType in statBagConfig.SubStatBagTypes)
						{
							Dictionary<ushort, long> valueOrDefault2 = self.BagStats.GetValueOrDefault(subStatBagType);
							if (valueOrDefault2 != null && valueOrDefault2.Count > 0)
							{
								UpdateFromSubBagStats(valueOrDefault, valueOrDefault2, statList);
							}
						}
					}
					foreach (StatStruct item in statList)
					{
						result.Add(item);
					}
					foreach (StatStruct item2 in statList2)
					{
						ushort basType = item2.GetBasType();
						long value = StatHelper.CalcPctAddValue(self.BasAndPctMap.GetValueOrDefault(basType), item2.Value);
						StatStruct stat = new StatStruct
						{
							Type = basType,
							Value = value
						};
						result.Add(stat);
					}
					return;
				}
			}
			UpdateFromSubBagStats(self.BagStats.GetValueOrDefault(statBagConfig.BelongStatBagType), valueOrDefault, result);
		}
	}
	[FriendOf(typeof(StatBag))]
	public static class ModuleStatBagSystem
	{
		public class AwakeSystem : AwakeSystem<StatBag, StatBagType>
		{
			protected override void Awake(StatBag self, StatBagType moduleType)
			{
				self.Type = moduleType;
			}
		}

		public class DestroySystem : DestroySystem<StatBag>
		{
			protected override void Destroy(StatBag self)
			{
				self.ScopeStatsMap.Clear();
				self.RawStatsMap.Clear();
				self.Version = 0;
			}
		}

		public static void UpdateHeroStat(this StatBag self, int heroConfigId)
		{
			try
			{
				self.Version++;
				(int, byte) key = (heroConfigId, 0);
				List<StatStruct> list = self.RawStatsMap.GetValueOrDefault(key);
				if (list != null)
				{
					foreach (StatStruct item in list)
					{
						if (item.Scope != 0)
						{
							self.ScopeStatsMap[item.Scope][item.Type] -= item.Value;
						}
					}
				}
				list?.Clear();
				using StatList statList = StatList.Create();
				StatBagUpdaterComponent.Instance.Get(self.Type).UpdateHero(self.Player, statList, heroConfigId);
				if (statList.Count == 0)
				{
					return;
				}
				if (list == null)
				{
					list = (self.RawStatsMap[key] = new List<StatStruct>());
				}
				foreach (StatStruct item2 in statList)
				{
					list.Add(item2);
					if (item2.Scope != 0)
					{
						Dictionary<ushort, long> dictionary = self.ScopeStatsMap.GetValueOrDefault(item2.Scope);
						if (dictionary == null)
						{
							dictionary = (self.ScopeStatsMap[item2.Scope] = new Dictionary<ushort, long>());
						}
						dictionary[item2.Type] = dictionary.GetValueOrDefault(item2.Type) + item2.Value;
					}
				}
			}
			catch (Exception arg)
			{
				Log.Error($"StatBag update hero stat error: {self.Type} hero: {heroConfigId}\n{arg}");
			}
		}

		public static void UpdateScopeStat(this StatBag self, byte scope)
		{
			try
			{
				self.Version++;
				(int, byte) key = (0, scope);
				List<StatStruct> list = self.RawStatsMap.GetValueOrDefault(key);
				if (list != null)
				{
					foreach (StatStruct item in list)
					{
						byte key2 = ((item.Scope == 0) ? scope : item.Scope);
						self.ScopeStatsMap[key2][item.Type] -= item.Value;
					}
					list.Clear();
				}
				using StatList statList = StatList.Create();
				StatBagUpdaterComponent.Instance.Get(self.Type).UpdateScope(self.Player, statList, scope);
				if (statList.Count == 0)
				{
					return;
				}
				if (list == null)
				{
					list = (self.RawStatsMap[key] = new List<StatStruct>());
				}
				foreach (StatStruct item2 in statList)
				{
					list.Add(item2);
					byte key3 = ((item2.Scope == 0) ? scope : item2.Scope);
					Dictionary<ushort, long> dictionary = self.ScopeStatsMap.GetValueOrDefault(key3);
					if (dictionary == null)
					{
						dictionary = (self.ScopeStatsMap[key3] = new Dictionary<ushort, long>());
					}
					dictionary[item2.Type] = dictionary.GetValueOrDefault(item2.Type) + item2.Value;
				}
			}
			catch (Exception arg)
			{
				Log.Error($"StatBag update scope stat error: {self.Type} scope: {scope}\n{arg}");
			}
		}

		private static void ReadFromScope(this StatBag self, StatList statList, byte scope)
		{
			Dictionary<ushort, long> valueOrDefault = self.ScopeStatsMap.GetValueOrDefault(scope);
			if (valueOrDefault == null)
			{
				return;
			}
			foreach (var (type, value) in valueOrDefault)
			{
				statList.Add(new StatStruct
				{
					Type = type,
					Value = value
				});
			}
		}

		public static void ReadHeroStats(this StatBag self, StatList statList, int heroConfigId)
		{
			HeroConfig heroConfig = ConfigSingleton<HeroConfigCategory>.Instance.Get(heroConfigId);
			self.ReadFromScope(statList, 10);
			self.ReadFromScope(statList, (byte)heroConfig.Job);
			List<StatStruct> valueOrDefault = self.RawStatsMap.GetValueOrDefault<(int, byte), List<StatStruct>>((heroConfigId, 0));
			if (valueOrDefault == null || valueOrDefault.Count <= 0)
			{
				return;
			}
			foreach (StatStruct item in valueOrDefault)
			{
				if (item.Scope == 0)
				{
					statList.Add(item);
				}
			}
		}
	}
	[FriendOf(typeof(StatBagUpdaterComponent))]
	public static class StatBagUpdaterComponentSystem
	{
		public class AwakeSystem : AwakeSystem<StatBagUpdaterComponent>
		{
			protected override void Awake(StatBagUpdaterComponent self)
			{
				StatBagUpdaterComponent.Instance = self;
				self.Load();
			}
		}

		public class LoadSystem : LoadSystem<StatBagUpdaterComponent>
		{
			public override void Load(StatBagUpdaterComponent self)
			{
				self.Load();
			}
		}

		private static void Load(this StatBagUpdaterComponent self)
		{
			self.Updaters.Clear();
			foreach (Type type in Singleton<EventSystem>.Instance.GetTypes(typeof(StatBagUpdaterAttribute)))
			{
				if (!(Activator.CreateInstance(type) is AStatBagUpdater value))
				{
					Log.Error("Type is not AStatBagUpdater: " + type.Name);
					continue;
				}
				StatBagUpdaterAttribute customAttribute = ((MemberInfo)type).GetCustomAttribute<StatBagUpdaterAttribute>();
				self.Updaters.Add(customAttribute.StatBagType, value);
			}
		}

		public static AStatBagUpdater Get(this StatBagUpdaterComponent self, StatBagType moduleType)
		{
			if (!self.Updaters.TryGetValue(moduleType, out var value))
			{
				Log.Error(string.Format("{0} not found! {1}", "AStatBagUpdater", moduleType));
			}
			return value;
		}
	}
	public static class StatHelper
	{
		public static Dictionary<ushort, long> GetStatDicByStatWrapId(int statWrapId)
		{
			if (statWrapId == 0)
			{
				return null;
			}
			StatWrapConfig statWrapConfig = ConfigSingleton<StatWrapConfigCategory>.Instance.Get(statWrapId);
			if (statWrapConfig == null)
			{
				return null;
			}
			Dictionary<ushort, long> dictionary = new Dictionary<ushort, long>();
			Stat[] stats = statWrapConfig.Stats;
			foreach (Stat stat in stats)
			{
				dictionary.Add(stat.Type, stat.Value);
			}
			return dictionary;
		}

		public static StatStruct ToStruct(this Stat stat)
		{
			return new StatStruct
			{
				Type = stat.Type,
				Value = stat.Value,
				Scope = stat.Scope
			};
		}

		public static Dictionary<ushort, long> ToDic(this StatList statList)
		{
			Dictionary<ushort, long> dictionary = new Dictionary<ushort, long>();
			foreach (StatStruct stat in statList)
			{
				dictionary[stat.Type] = dictionary.GetValueOrDefault(stat.Type) + stat.Value;
			}
			return dictionary;
		}

		public static long GetPower(this StatList statList)
		{
			using PowerCalc powerCalc = PowerCalc.Create();
			powerCalc.AddStats(statList);
			return powerCalc.Power;
		}

		public static ushort GetBasType(ushort statType)
		{
			return (ushort)(statType % 100);
		}

		public static ushort GetPctType(ushort statType)
		{
			return (ushort)(GetBasType(statType) + 100);
		}

		public static int GetStatOrder(ushort statType)
		{
			int basType = GetBasType(statType);
			if (!ConfigSingleton<StatConfigCategory>.Instance.Contain(basType))
			{
				return 0;
			}
			return ConfigSingleton<StatConfigCategory>.Instance.Get(basType).Order;
		}

		public static bool IsSpecialStat(ushort statType)
		{
			return GetStatOrder(statType) > 100;
		}

		public static bool IsSpecialStat(this StatStruct statStruct)
		{
			return IsSpecialStat(statStruct.Type);
		}

		public static bool IsBasStat(int type)
		{
			return type < 100;
		}

		public static bool IsPctStat(int type)
		{
			return type / 100 == 1;
		}

		public static bool IsFinalAddStat(int type)
		{
			return type / 100 == 2;
		}

		public static bool IsFinalAddPctStat(int type)
		{
			return type / 100 == 3;
		}

		public static bool IsBasStat(this StatStruct statStruct)
		{
			return statStruct.Type < 100;
		}

		public static bool IsPctStat(this StatStruct statStruct)
		{
			return statStruct.Type / 100 == 1;
		}

		public static ushort GetBasType(this StatStruct statStruct)
		{
			return (ushort)(statStruct.Type % 100);
		}

		public static ushort GetPctType(this StatStruct statStruct)
		{
			return (ushort)(statStruct.GetBasType() + 100);
		}

		public static StatStruct AddPct(this StatStruct statStruct, long value)
		{
			StatStruct result = statStruct;
			result.Value = CalcFinalValue(statStruct.Value, value);
			return result;
		}

		public static StatStruct AddValue(this StatStruct statStruct, long value)
		{
			StatStruct result = statStruct;
			result.Value += value;
			return result;
		}

		public static long CalcPctAddValue(long basValue, long pctValue)
		{
			return basValue * pctValue / 10000;
		}

		public static long CalcFinalValue(long basValue, long pctValue)
		{
			return basValue + basValue * pctValue / 10000;
		}

		public static long GetFinalValueFromDic(Dictionary<ushort, long> dic, ushort type)
		{
			ushort basType = GetBasType(type);
			ushort pctType = GetPctType(type);
			long valueOrDefault = dic.GetValueOrDefault(basType);
			long valueOrDefault2 = dic.GetValueOrDefault(pctType);
			return CalcFinalValue(valueOrDefault, valueOrDefault2);
		}

		public static long CalcStatDicPower(Dictionary<ushort, long> statDic)
		{
			long num = 0L;
			foreach (KeyValuePair<ushort, long> item in statDic)
			{
				StatStruct statStruct = new StatStruct
				{
					Type = item.Key,
					Value = item.Value
				};
				if (statStruct.IsBasStat())
				{
					statDic.TryGetValue(statStruct.Type, out var value);
					statDic.TryGetValue(statStruct.GetPctType(), out var value2);
					num += CalcPower(statStruct.Type, value, value2);
				}
			}
			return num;
		}

		public static long CalcPower(ushort type, long basValue, long pctValue)
		{
			ushort basType = GetBasType(type);
			return ConfigSingleton<StatConfigCategory>.Instance.Get(basType).PowerFactor * CalcFinalValue(basValue, pctValue) / 100;
		}

		public static void PrintStats(this Stat[] stats, string with = null)
		{
			string text = "[Stat]: ";
			foreach (Stat stat in stats)
			{
				text += $"stat: {stat.Type}: {stat.Value}  ";
			}
			Log.Info(text + (with ?? string.Empty));
		}

		public static void PrintStats(StatList stats, string tag = null)
		{
			string text = (string.IsNullOrEmpty(tag) ? "[Stat]----------------\n" : ("[" + tag + "]----------------\n"));
			foreach (StatStruct stat in stats)
			{
				text += $"----- [{stat.Type}] : [{stat.Value}] \n";
			}
			Log.Info(text);
		}

		public static void PrintStats(Dictionary<ushort, long> stats, string tag = null)
		{
			string text = (string.IsNullOrEmpty(tag) ? "[Stat]----------------\n" : ("[" + tag + "]----------------\n"));
			foreach (KeyValuePair<ushort, long> stat in stats)
			{
				text += $"----- [{stat.Key}] : [{stat.Value}] \n";
			}
			Log.Info(text);
		}

		public static void AppendPracticeLevelStat(StatList updateList, int practiceLevel)
		{
			for (int i = 1; i < practiceLevel; i++)
			{
				if (ConfigSingleton<PracticeConfigCategory>.Instance.Contain(i))
				{
					PracticeConfig practiceConfig = ConfigSingleton<PracticeConfigCategory>.Instance.Get(i);
					updateList.AddRange(practiceConfig.AddStats, practiceConfig.StatLevel);
					updateList.AddRange(practiceConfig.GradeAddStats);
				}
			}
		}

		public static int CompareByOrder(StatStruct a, StatStruct b)
		{
			ushort basType = GetBasType(a.Type);
			ushort basType2 = GetBasType(b.Type);
			StatConfig statConfig = ConfigSingleton<StatConfigCategory>.Instance.Get(basType);
			StatConfig statConfig2 = ConfigSingleton<StatConfigCategory>.Instance.Get(basType2);
			int num = statConfig.Order * 1000 + a.Type;
			int value = statConfig2.Order * 1000 + b.Type;
			return num.CompareTo(value);
		}

		public static void SortByOrder(this List<StatStruct> statList)
		{
			statList.Sort(CompareByOrder);
		}
	}
	[FriendOf(typeof(StatBag))]
	[FriendOf(typeof(StatModule))]
	public static class StatModuleSystem
	{
		public class AwakeSystem : AwakeSystem<StatModule>
		{
			protected override void Awake(StatModule self)
			{
				self.Init();
			}
		}

		private static void Init(this StatModule self)
		{
			HeroModule component = ((Entity)self.Player).GetComponent<HeroModule>();
			foreach (StatBagConfig item in ConfigSingleton<StatBagConfigCategory>.Instance.GetList())
			{
				StatBag self2 = ((Entity)self).AddChildWithId<StatBag, StatBagType>((long)item.StatBagType, item.StatBagType, false);
				foreach (Hero item2 in ((Entity)component).Children.Values.Cast<Hero>())
				{
					if (item2 != null && item2.IsActive)
					{
						self2.UpdateHeroStat(item2.ConfigId);
					}
				}
				foreach (int key in ConfigSingleton<JobConfigCategory>.Instance.GetAll().Keys)
				{
					self2.UpdateScopeStat((byte)key);
				}
				self2.UpdateScopeStat(10);
			}
		}

		public static StatBag GetStatBag(this StatModule self, StatBagType statBagType)
		{
			return ((Entity)self).GetChild<StatBag>((long)statBagType);
		}

		public static void UpdateHeroStats(this Player player, int heroConfigId, StatBagType type)
		{
			Hero hero = player.GetHero(heroConfigId);
			if (hero != null && hero.IsActive)
			{
				((Entity)player).GetComponent<StatModule>().GetStatBag(type).UpdateHeroStat(heroConfigId);
				Singleton<EventSystem>.Instance.Publish<StatChange>(SceneHelper.DomainScene((Entity)(object)player), new StatChange
				{
					Player = player
				});
			}
		}

		public static void UpdateRoleStats(this Player player, StatBagType type)
		{
			player.UpdateHeroStats(((Entity)player).GetComponent<RoleInfoModule>().Role, type);
		}

		public static void UpdateTeamStats(this Player player, StatBagType type)
		{
			((Entity)player).GetComponent<StatModule>().GetStatBag(type).UpdateScopeStat(10);
			Singleton<EventSystem>.Instance.Publish<StatChange>(SceneHelper.DomainScene((Entity)(object)player), new StatChange
			{
				Player = player
			});
		}

		public static void UpdateJobStats(this Player player, int jobId, StatBagType type)
		{
			((Entity)player).GetComponent<StatModule>().GetStatBag(type).UpdateScopeStat((byte)jobId);
			Singleton<EventSystem>.Instance.Publish<StatChange>(SceneHelper.DomainScene((Entity)(object)player), new StatChange
			{
				Player = player
			});
		}
	}
