	public static class TaskHelper
	{
		public static bool IsActivityTask(TaskFinishType taskFinishType)
		{
			if (taskFinishType != TaskFinishType.FinishType_1057)
			{
				return taskFinishType == TaskFinishType.FinishType_1055;
			}
			return true;
		}

		public static ActivityType GetActivityType(TaskFinishType taskFinishType)
		{
			return taskFinishType switch
			{
				TaskFinishType.FinishType_1057 => ActivityType.OnLineReward, 
				TaskFinishType.FinishType_1055 => ActivityType.SevenDayTarget, 
				_ => ActivityType.None, 
			};
		}

		public static int[] GetCondParam(this TaskData self)
		{
			Array<int>[] condParam = (self.Config as TaskConfig).CondParam1;
			if (condParam == null)
			{
				return null;
			}
			return condParam.GetValueOrLast(self.Stage);
		}

		public static int IsCanGet(this TaskData self)
		{
			if (self.Status == 2)
			{
				return 201401;
			}
			if (self.Status == 3)
			{
				return 201402;
			}
			return 0;
		}

		public static int IsCanFinish(this TaskData self)
		{
			if (self.Status == 3)
			{
				return 201402;
			}
			if ((self.Config as TaskConfig).FinishType == 102)
			{
				return 0;
			}
			if (self.Status == 2)
			{
				return 201401;
			}
			return 0;
		}
	}
	[FriendOf(typeof(TaskModule))]
	public static class TaskModuleSystem
	{
		public static int GetChatperId(this TaskModule self)
		{
			if (self.ChapterId == 0)
			{
				self.ChapterId = 1;
			}
			return self.ChapterId;
		}

		public static bool IsGetTask(this TaskModule self, int taskId)
		{
			if (self.FinishTaskDict == null)
			{
				return false;
			}
			return self.FinishTaskDict.ContainsKey(taskId);
		}

		public static TaskTypeData GetTaskTypeData(this TaskModule self, int type)
		{
			if (!self.TaskDataDictByType.ContainsKey(type))
			{
				self.TaskDataDictByType.Add(type, new TaskTypeData
				{
					Type = type
				});
			}
			return self.TaskDataDictByType.GetValue(type);
		}

		public static TaskData GetTaskData(this TaskModule self, int id, bool isCreate = false)
		{
			if (!ConfigSingleton<TaskConfigCategory>.Instance.Contain(id))
			{
				return null;
			}
			int type = ConfigSingleton<TaskConfigCategory>.Instance.Get(id).Type;
			TaskTypeData taskTypeData = self.GetTaskTypeData(type);
			if (isCreate && !taskTypeData.TaskDataDict.ContainsKey(id))
			{
				taskTypeData.TaskDataDict.Add(id, new TaskData
				{
					Id = id
				});
			}
			if (taskTypeData.TaskDataDict.TryGetValue(id, out var value))
			{
				return value;
			}
			return null;
		}
	}
	public static class TeamDupModuleSystem
	{
		public static bool IsInBattleHelp(this TeamDupModule self)
		{
			if (self.HelpBattleTime <= 0)
			{
				return false;
			}
			int teamDupHelpTime = ConfigSingleton<GlobalConfigCategory>.Instance.GetOne().TeamDupHelpTime;
			return TimeHelper.Now() <= self.HelpBattleTime + teamDupHelpTime * 3600000;
		}

		public static int GetLeftCount(this TeamDupModule self)
		{
			int buyedCount = ((Entity)self.Player).GetComponent<PrivilegeModule>().GetBuyedCount(3);
			return self.GetMaxCount() + buyedCount - self.ChallengeCount;
		}

		public static int GetDaiylyLeftCount(this TeamDupModule self)
		{
			int buyedCount = ((Entity)self.Player).GetComponent<PrivilegeModule>().GetBuyedCount(3);
			return self.GetMaxCount() - buyedCount;
		}

		public static int GetMaxCount(this TeamDupModule self)
		{
			return ConfigSingleton<GlobalConfigCategory>.Instance.GetOne().TeamDupCount;
		}

		public static int GetMaxCountForShow(this TeamDupModule self)
		{
			int maxCount = self.GetMaxCount();
			int buyedCount = ((Entity)self.Player).GetComponent<PrivilegeModule>().GetBuyedCount(3);
			return maxCount + buyedCount;
		}

		public static bool IsMember(this TeamDupModule self, long playerId)
		{
			foreach (TeamMemberInfo memberInfo in self.MemberInfos)
			{
				if (memberInfo.PlayerCommonInfo.Id == playerId)
				{
					return true;
				}
			}
			return false;
		}

		public static int IsCanGetBox(this TeamDupModule self)
		{
			if (ConfigSingleton<DupTXCMBoxConfigCategory>.Instance.Get(self.BoxId).BattleCount > self.HelpBattleCount)
			{
				return 204406;
			}
			return 0;
		}

		public static int GetLeftHelpCount(this TeamDupModule self)
		{
			int teamDupHelpCount = ConfigSingleton<GlobalConfigCategory>.Instance.GetOne().TeamDupHelpCount;
			if (!TimeHelper.IsSameDay(TimeHelper.Now(), self.DayHelpTime, 18000000L))
			{
				return teamDupHelpCount;
			}
			return teamDupHelpCount - self.DayHelpCount;
		}

		public static TeamMemberInfo GetMemberInfo(this TeamDupModule self, long id)
		{
			return self.MemberInfos.Find((TeamMemberInfo m) => m.PlayerCommonInfo.Id == id);
		}
	}
