	public static class TiangangSystem
	{
		public static long GetPower(this Tiangang self)
		{
			using PowerCalc powerCalc = PowerCalc.Create();
			powerCalc.AddStats(self.StageConfig.BaseStats);
			using StatList statList = StatList.Create();
			int level = self.Level;
			for (int i = self.ConfigId * 1000; ConfigSingleton<TianGangLevelConfigCategory>.Instance.Contain(i); i++)
			{
				TianGangLevelConfig tianGangLevelConfig = ConfigSingleton<TianGangLevelConfigCategory>.Instance.Get(i);
				if (level < tianGangLevelConfig.MinLevel)
				{
