		private static Unit CreateWithId(Scene battleScene, long id, UnitType unitType, int configId)
		{
			UnitComponent component = ((Entity)battleScene).GetComponent<UnitComponent>();
			Unit unit = ((Entity)component).AddChildWithId<Unit, int>(id, configId, false);
			unit.Type = unitType;
			switch (unitType)
			{
			case UnitType.WarUnit:
				((Entity)unit).AddComponent<MoveComponent>(false);
				break;
			case UnitType.Head:
				((Entity)unit).AddComponent<MoveComponent>(false);
				((Entity)unit).AddComponent<StateComponent>(false);
				break;
			case UnitType.Hero:
				((Entity)unit).AddComponent<MoveComponent>(false);
				((Entity)unit).AddComponent<BuffComponent>(false);
				((Entity)unit).AddComponent<AIComponent, int>((int)unit.Config.AI, false);
				((Entity)unit).AddComponent<FightComponent>(false);
				((Entity)unit).AddComponent<SkillTriggerComponent>(false);
				((Entity)unit).AddComponent<StateComponent>(false);
				((Entity)unit).AddComponent<SkillComponent>(false);
				((Entity)unit).AddComponent<UnitHeroInfoComponent>(true);
				((Entity)unit).AddComponent<UnitInfoComponent>(true);
				((Entity)unit).AddComponent<NumericComponent>(true);
				component.AddFightUnit(unit);
				break;
			case UnitType.Build:
				((Entity)unit).AddComponent<StateComponent>(false);
				((Entity)unit).AddComponent<UnitInfoComponent>(true);
				((Entity)unit).AddComponent<NumericComponent>(true);
				break;
			case UnitType.Monster:
			case UnitType.DJMonster:
			case UnitType.KingWarMonster:
			case UnitType.BeastToken:
			{
				UnitConfig unitConfig = ConfigSingleton<UnitConfigCategory>.Instance.Get(configId);
				((Entity)unit).AddComponent<MoveComponent>(false);
				((Entity)unit).AddComponent<BuffComponent>(false);
				((Entity)unit).AddComponent<AIComponent, int>((int)unit.Config.AI, false);
				((Entity)unit).AddComponent<FightComponent>(false);
				((Entity)unit).AddComponent<SkillTriggerComponent>(false);
				((Entity)unit).AddComponent<StateComponent>(false);
				((Entity)unit).AddComponent<UnitInfoComponent>(true);
				((Entity)unit).AddComponent<NumericComponent>(true);
				((Entity)unit).AddComponent<SkillComponent>(false).AddSkillList(unitConfig.Skills);
				component.AddFightUnit(unit);
				break;
			}
			}
			return unit;
		}
	}
