		public static UnitInfo CreateHeroUnitInfo(this Player player, long heroId, int campId)
		{
			try
			{
				Hero heroByUid = player.GetHeroByUid(heroId);
				if (heroByUid == null || !heroByUid.IsActive)
				{
					throw new Exception($"Hero is not active! {heroId}");
				}
				HeroConfig heroConfig = ConfigSingleton<HeroConfigCategory>.Instance.Get(heroByUid.ConfigId);
				UnitInfo unitInfo = new UnitInfo();
				unitInfo.Id = Singleton<IdGenerater>.Instance.GenerateUnitId(0);
				unitInfo.ConfigId = heroConfig.UnitId;
				unitInfo.UnitType = 1;
				unitInfo.CampId = campId;
				unitInfo.TypeConfigId = heroByUid.ConfigId;
				bool flag = heroByUid.IsRole();
				if (flag)
				{
					unitInfo.BodyModelId = player.GetModelId();
					unitInfo.WeaponModelId = player.GetWeaponModelId();
					unitInfo.CapeModelId = player.GetCapeModelId();
				}
				else
				{
					unitInfo.BodyModelId = heroByUid.CurrentSkinModelId;
				}
				unitInfo.Level = player.GetHeroLvById(heroByUid.ConfigId);
				unitInfo.Stats = heroByUid.GetFinalStats()?.Clone();
				UnitInfo unitInfo2 = unitInfo;
				if (unitInfo2.Stats == null)
				{
					Dictionary<ushort, long> dictionary = (unitInfo2.Stats = new Dictionary<ushort, long>());
				}
				unitInfo.SetStat(NumericType.MaxEp, 100L);
				unitInfo.SkillLevelIds = heroByUid.GetSkills()?.Clone();
				UnitHeroInfo unitHeroInfo = (unitInfo.HeroInfo = new UnitHeroInfo());
				unitHeroInfo.HeroId = heroId;
				unitHeroInfo.Star = (flag ? ((Entity)player).GetComponent<PracticeModule>().GetPracticeLevel() : heroByUid.Star);
				unitHeroInfo.OwnerId = heroByUid.GetOwnerPlayerId();
				unitHeroInfo.HeroSkin = heroByUid.CurrentSkin;
				return unitInfo;
			}
			catch (Exception ex)
			{
				Log.Error("Create hero info error! \n" + ex);
				return null;
			}
		}

