		public static long GetStat(this Dictionary<ushort, long> self, NumericType numericType)
		{
			if ((int)numericType / 100 == 9)
			{
				int num = (int)numericType % 100;
				int num2 = (int)numericType % 100 + 100;
				return StatHelper.CalcFinalValue(self.GetValueOrDefault((ushort)num), self.GetValueOrDefault((ushort)num2));
			}
			return self.GetValueOrDefault((ushort)numericType);
		}

