		{
			if (unitInfo.Stats == null)
			{
				Dictionary<ushort, long> dictionary = (unitInfo.Stats = new Dictionary<ushort, long>());
			}
			unitInfo.Stats[(ushort)numericType] = value;
		}
	}
	public static class BitHelper
	{
		public static bool IsBitSet(int value, int position)
		{
			return (value & (1 << position)) != 0;
		}

		public static void SetBit(ref int value, int position)
		{
			value |= 1 << position;
		}

		public static int SetBit(int value, int position)
		{
			return value | (1 << position);
		}

		public static int ClearBit(int value, int position)
		{
			return value & ~(1 << position);
		}
	}
