	public static class VibesEquipModuleSystem
	{
		public static int GetPowerLevel(this VibesEquipModule self, int job, int part)
		{
			int enhanceKey = VibesHelper.GetEnhanceKey(job, part);
			return self.GetEnhanceLevelByKey(enhanceKey);
		}

		private static int GetEnhanceLevelByKey(this VibesEquipModule self, int wearId)
		{
			if (self.VibesEquipPowerDic == null)
			{
				Dictionary<int, int> dictionary = (self.VibesEquipPowerDic = new Dictionary<int, int>());
			}
			self.VibesEquipPowerDic.TryGetValue(wearId, out var value);
			return value;
		}

		public static int GetEquipId(this VibesEquipModule self, int job, int part)
		{
			int equipKey = VibesHelper.GetEquipKey(job, part);
			return self.GetEquipIdByKey(equipKey);
		}

		private static int GetEquipIdByKey(this VibesEquipModule self, int wearId)
		{
			if (self.VibesEquipDic == null)
			{
				Dictionary<int, int> dictionary = (self.VibesEquipDic = new Dictionary<int, int>());
			}
			self.VibesEquipDic.TryGetValue(wearId, out var value);
			return value;
		}

		public static (int, int) GetMinPowerLevel(this VibesEquipModule self, int job)
		{
			int num = int.MaxValue;
			bool flag = false;
			int item = 0;
			for (int i = 1; i < 7; i++)
			{
				if (self.GetEquipId(job, i) > 0)
				{
					flag = true;
					int powerLevel = self.GetPowerLevel(job, i);
					if (powerLevel < num)
					{
						num = powerLevel;
						item = i;
					}
				}
			}
			if (!flag)
			{
				return (0, 0);
			}
			return (item, num);
		}

		public static int IsCanEnhanceByPart(this VibesEquipModule self, int job, int part)
		{
			Player parent = ((Entity)self).GetParent<Player>();
			if (self.GetEquipId(job, part) == 0)
			{
				return 200706;
			}
			int powerLevel = self.GetPowerLevel(job, part);
			int maxLevel = ConfigSingleton<EquipPowerConfigCategory>.Instance.GetMaxLevel(job, part);
			if (powerLevel >= maxLevel)
			{
				return 200707;
			}
			EquipPowerConfig enhanceConfig = ConfigSingleton<EquipPowerConfigCategory>.Instance.GetEnhanceConfig(job, part, powerLevel);
			if (!parent.CheckItemNumsIsEnough(enhanceConfig.Cost))
			{
				return 200102;
			}
			return 0;
		}
	}
