	public static class VibesHelper
	{
		public static void SetStatZero(StatList statList, StatList copyStatList)
		{
			if (statList != null && copyStatList != null)
			{
				for (int i = 0; i < copyStatList.Count; i++)
				{
					StatStruct statStruct = copyStatList[i];
					statList.Add(new StatStruct
					{
						Type = statStruct.Type,
						Value = 0L
					});
				}
			}
		}

		public static Stat[] MergeArray(Stat[] stats1, Stat[] stats2)
		{
			if (stats1 != null && stats1.Length != 0 && stats2 != null && stats2.Length != 0 && stats1.Length == stats2.Length)
			{
				Stat[] array = new Stat[stats1.Length];
				for (int i = 0; i < stats1.Length; i++)
				{
					array[i] = new Stat
					{
						Type = stats1[i].Type,
						Value = stats1[i].Value - stats2[i].Value,
						Scope = stats1[i].Scope
					};
				}
				return array;
			}
			return null;
		}

