		public static void SetEnhanceStat(StatList statList, int job, int part, int level)
		{
			if (level == 0)
			{
				return;
			}
			for (int i = job * 10000 + part * 1000 + 1; ConfigSingleton<EquipPowerConfigCategory>.Instance.Contain(i); i++)
			{
				EquipPowerConfig equipPowerConfig = ConfigSingleton<EquipPowerConfigCategory>.Instance.Get(i);
				int num = 0;
				if (ConfigSingleton<EquipPowerConfigCategory>.Instance.Contain(i - 1))
				{
					num = ConfigSingleton<EquipPowerConfigCategory>.Instance.Get(i - 1).PowerLevel;
				}
				if (level > equipPowerConfig.PowerLevel)
				{
					statList.AddRange(equipPowerConfig.PowerStat, equipPowerConfig.PowerLevel - num);
				}
				else
				{
					statList.AddRange(equipPowerConfig.PowerStat, level - num);
				}
				if (equipPowerConfig.PowerLevel >= level)
				{
					break;
				}
			}
		}

