		public static int GetBreakLevelCount(Player player, int job)
		{
			VibesLevelModule component = ((Entity)player).GetComponent<VibesLevelModule>();
			int num = 0;
			int level = GetLevel(player, job);
			int num2 = job * 10000;
			int num3 = num2 + level;
			while (num3 > num2)
			{
				if (!ConfigSingleton<VibesLevelBreakConfigCategory>.Instance.Contain(num3))
				{
					num3--;
					continue;
				}
				if (ConfigSingleton<VibesLevelBreakConfigCategory>.Instance.Get(num3).Level == level)
				{
					if (BitHelper.IsBitSet(component.LevelBreak, job))
					{
						num++;
					}
