		public static Dictionary<int, MultiDictionary<int, int, int>> GetTempGemDict(this VibesGemModule self)
		{
			Dictionary<int, MultiDictionary<int, int, int>> dictionary = new Dictionary<int, MultiDictionary<int, int, int>>();
			foreach (var (num2, _) in ConfigSingleton<JobConfigCategory>.Instance.GetAll())
			{
				MultiDictionary<int, int, int> val = new MultiDictionary<int, int, int>();
				dictionary.Add(num2, val);
				for (int i = 1; i < 7; i++)
				{
					List<int> gemPositions = GetGemPositions(num2, i);
					for (int j = 0; j < gemPositions.Count; j++)
					{
						int num3 = gemPositions[j];
						int gemLevel = self.GetGemLevel(num2, i, num3);
						val.Add(i, num3, gemLevel);
					}
				}
			}
			return dictionary;
		}

