	public static class VibesLevelModuleSystem
	{
		public static long GetPower(this VibesLevelModule self)
		{
			long num = 0L;
			foreach (int key in ConfigSingleton<JobConfigCategory>.Instance.GetAll().Keys)
			{
				num += self.GetPower(key);
			}
			return num;
		}

		public static long GetPower(this VibesLevelModule self, int job)
		{
			int level = self.GetLevel(job);
			if (level == 0)
			{
				return 0L;
			}
			using PowerCalc powerCalc = PowerCalc.Create();
			using StatList statList = StatList.Create();
			int num = job * 1000;
			while (ConfigSingleton<VibesLevelConfigCategory>.Instance.Contain(++num))
			{
				VibesLevelConfig vibesLevelConfig = ConfigSingleton<VibesLevelConfigCategory>.Instance.Get(num);
				if (level < vibesLevelConfig.StartLv)
				{
					break;
				}
				int multiple = math.min(level - vibesLevelConfig.StartLv + 1, vibesLevelConfig.EndLv - vibesLevelConfig.StartLv + 1);
				statList.AddRange(vibesLevelConfig.AddStats, multiple);
			}
			VibesLevelBreakConfig vibesLevelBreakConfig = (VibesHelper.IsNeedBreak(((Entity)self).GetParent<Player>(), job) ? VibesHelper.GetLevelBreakConfig(job, level - 1) : VibesHelper.GetLevelBreakConfig(job, level));
			if (vibesLevelBreakConfig != null)
			{
				statList.AddRange(vibesLevelBreakConfig.AddStats);
			}
			powerCalc.AddStats(statList);
			return powerCalc.Power;
		}

		public static int GetCanLevelCount(this VibesLevelModule self, int job, ItemList resultCost = null)
		{
			int num = 0;
			int num2 = self.GetLevel(job);
			int num3 = num2;
			Player player = self.Player;
			int num4 = Math.Min(self.GetMaxLevelCount(job), 50);
			using ItemList itemList = ItemList.Create();
			for (int i = 0; i < num4; i++)
			{
				VibesLevelConfig levelConfig = self.GetLevelConfig(job, num2);
				if (levelConfig == null || ((num3 == num2) ? VibesHelper.IsNeedBreak(self.Player, job) : VibesHelper.IsNeedBreak(job, num2)))
				{
					break;
				}
				itemList.Add(levelConfig.Cost);
				if (!player.CheckItemNumsIsEnough(itemList))
				{
					break;
				}
				num++;
				resultCost?.Add(levelConfig.Cost);
				num2++;
			}
			return num;
		}

		public static int GetMaxLevelCount(this VibesLevelModule self, int job)
		{
			int level = self.GetLevel(job);
			Dictionary<int, JobConfig> all = ConfigSingleton<JobConfigCategory>.Instance.GetAll();
			int levelDiff = ConfigSingleton<GlobalConfigCategory>.Instance.GetOne().LevelDiff;
			int num = 0;
			foreach (var (num3, _) in all)
			{
				if (num3 != job)
				{
					int level2 = self.GetLevel(num3);
					int num4 = level - level2;
					if (num4 > num)
					{
						num = num4;
					}
				}
			}
			return levelDiff - num;
		}

