		public static VibesLevelConfig GetLevelConfig(this VibesLevelModule self, int job, int level)
		{
			Dictionary<int, VibesLevelConfig> all = ConfigSingleton<VibesLevelConfigCategory>.Instance.GetAll();
			int i = VibesHelper.GetVibesLevelConfigBeginId(job);
			VibesLevelConfig result = null;
			for (; all.ContainsKey(i); i++)
			{
				VibesLevelConfig value = all.GetValue(i);
				if (value.StartLv <= level && level <= value.EndLv)
				{
					result = value;
					break;
				}
			}
			return result;
		}

		public static bool IsMax(this VibesLevelModule self, int job)
		{
			int level = self.GetLevel(job);
			if (VibesHelper.IsNeedBreak(self.Player, job))
			{
				return false;
			}
			if (self.GetLevelConfig(job, level + 1) != null)
			{
				return false;
			}
			return true;
		}

		public static int IsCanUp(this VibesLevelModule self, int job)
		{
			int level = self.GetLevel(job);
			if (VibesHelper.IsNeedBreak(self.Player, job))
			{
				VibesLevelBreakConfig levelBreakConfig = VibesHelper.GetLevelBreakConfig(job, level);
				if (!((Entity)((Entity)self).GetParent<Player>()).GetComponent<ItemModule>().CheckItemNumsIsEnough(levelBreakConfig.Cost.Id, levelBreakConfig.Cost.Nums))
				{
					return 200102;
				}
				return 0;
			}
			foreach (var (num2, _) in ConfigSingleton<JobConfigCategory>.Instance.GetAll())
			{
				if (num2 != job)
				{
					int level2 = self.GetLevel(num2);
					if (level - level2 >= ConfigSingleton<GlobalConfigCategory>.Instance.GetOne().LevelDiff)
					{
						return 200731;
					}
				}
			}
			if (self.GetLevelConfig(job, level + 1) == null)
			{
				return 200702;
			}
			VibesLevelConfig levelConfig = self.GetLevelConfig(job, level);
			if (!((Entity)((Entity)self).GetParent<Player>()).GetComponent<ItemModule>().CheckItemNumsIsEnough(levelConfig.Cost.Id, levelConfig.Cost.Nums))
			{
				return 200102;
			}
			return 0;
		}
	}
