		public static int GetExpByLoginDays(int days)
		{
			int num = 0;
			if (ConfigSingleton<VipExpConfigCategory>.Instance.Contain(days))
			{
				return ConfigSingleton<VipExpConfigCategory>.Instance.Get(days).Exp;
			}
			return ConfigSingleton<VipExpConfigCategory>.Instance.GetList().Last().Exp;
		}

		public static (long, long) CalculateNeedExp(long currentExp)
		{
			List<VipConfig> list = ConfigSingleton<VipConfigCategory>.Instance.GetList();
			long num = 0L;
			foreach (VipConfig item in list)
			{
				if (num + item.NeedExp > currentExp)
				{
					return (currentExp - num, item.NeedExp);
				}
				num += item.NeedExp;
			}
			VipConfig vipConfig = list.Last();
			return (vipConfig.NeedExp, vipConfig.NeedExp);
		}

		public static int CalculateLevel(long currentExp)
		{
			List<VipConfig> list = ConfigSingleton<VipConfigCategory>.Instance.GetList();
			int result = 0;
			long num = 0L;
			foreach (VipConfig item in list)
			{
				num += item.NeedExp;
				if (num > currentExp)
				{
					break;
				}
				result = item.Level;
			}
			return result;
		}
	}
