		public static VipGiftInfo GetOrCreateVipGiftInfo(this VipModule self, int level)
		{
			if (!self.GiftBuyInfos.TryGetValue(level, out var value))
			{
				value = new VipGiftInfo();
				self.GiftBuyInfos[level] = value;
			}
			if (value != null)
			{
				long num = TimeHelper.ServerNow();
				VipConfig vipConfig = ConfigSingleton<VipConfigCategory>.Instance.Get(level);
				if (value.JadeGiftBuyTimes > 0)
				{
					VipGift vipGift = ConfigSingleton<VipGiftCategory>.Instance.Get(vipConfig.JadeGift);
					if (vipGift.Mark != null)
					{
						long num2 = TimeHelper.ToTime(vipGift.Mark.Year, vipGift.Mark.Month, vipGift.Mark.Day, vipGift.Mark.Hour);
						if (num >= num2 && num2 > value.JadeGiftMark)
						{
							value.JadeGiftMark = 0L;
							value.JadeGiftBuyTimes = 0;
						}
					}
				}
				if (value.CashGiftBuyTimes > 0)
				{
					VipGift vipGift2 = ConfigSingleton<VipGiftCategory>.Instance.Get(vipConfig.CashGift);
					if (vipGift2.Mark != null)
					{
						long num3 = TimeHelper.ToTime(vipGift2.Mark.Year, vipGift2.Mark.Month, vipGift2.Mark.Day, vipGift2.Mark.Hour);
						if (num >= num3 && num3 > value.CashGiftMark)
						{
							value.CashGiftMark = 0L;
							value.CashGiftBuyTimes = 0;
						}
					}
				}
			}
			return value;
		}
	}
