		public static void AddBuff(this BuffComponent self, int configId, Unit bringer = null, int skillLevelId = 0)
		{
			if (!ConfigSingleton<BuffConfigCategory>.Instance.Contain(configId))
			{
				Log.Error($"Buff config Not Exist! {configId}");
				return;
			}
			BuffConfig buffConfig = ConfigSingleton<BuffConfigCategory>.Instance.Get(configId);
			if (buffConfig.IsDebuff && self.RepelDeBuffEffectTypes.ContainsKey(buffConfig.EffectType))
			{
				return;
			}
			ABuffHandler aBuffHandler = BuffHandlerComponent.Instance.Get(buffConfig.EffectType);
			if (aBuffHandler == null)
			{
				Log.Error($"Buff handler Not Exist! {buffConfig.EffectType}");
				return;
			}
			Unit unit = self.Unit;
			Buff buff = self.GetBuffByGroup(buffConfig.Group);
			if (buff == null)
			{
				buff = ((Entity)self).AddChildWithId<Buff, int, ABuffHandler>((long)(++self.BuffIdGenerator), configId, aBuffHandler, true);
				self.GroupBuff.Add(buffConfig.Group, buff);
				self.UpdateQueue.Enqueue(((Entity)buff).Id);
			}
			if (bringer == null)
			{
				bringer = self.Unit;
			}
			buff.AddLayerLevel(buffConfig, bringer, skillLevelId);
			Singleton<EventSystem>.Instance.Publish<AddBuff>(SceneHelper.DomainScene((Entity)(object)self), new AddBuff
			{
				Buff = buff
			});
			if (skillLevelId > 0)
			{
				SkillTriggerArgs args = new SkillTriggerArgs
				{
					Type = 14,
					Target = unit,
					Caster = bringer,
					SkillLevelId = skillLevelId,
					Buff = buff
				};
				SkillTriggerHelper.Trigger(SceneHelper.DomainScene((Entity)(object)self), args);
			}
			long frameTime = ((Entity)SceneHelper.DomainScene((Entity)(object)self)).GetComponent<SceneTimeInfo>().FrameTime;
			if (buff.Update(frameTime))
			{
				self.RemoveInternal(((Entity)buff).Id);
			}
		}

		public static void RemoveAll(this BuffComponent self)
		{
			while (self.UpdateQueue.Count > 0)
			{
				self.RemoveInternal(self.UpdateQueue.Dequeue());
			}
		}

		public static void Foreach(this BuffComponent self, Action<Buff> action)
		{
			if (action == null)
			{
				return;
			}
			foreach (long item in self.UpdateQueue)
			{
				Buff child = ((Entity)self).GetChild<Buff>(item);
				if (child != null)
				{
					action(child);
				}
			}
		}

		public static void RemoveBuffByGroup(this BuffComponent self, int groupId)
		{
			Buff buffByGroup = self.GetBuffByGroup(groupId);
			if (buffByGroup != null)
			{
				self.RemoveInternal(((Entity)buffByGroup).Id);
			}
		}

		public static Buff GetBuffByGroup(this BuffComponent self, int groupId)
		{
			return self.GroupBuff.GetValueOrDefault(groupId);
		}

		public static void AddRepelDeBuffEffectType(this BuffComponent self, int effectType)
		{
			int valueOrDefault = self.RepelDeBuffEffectTypes.GetValueOrDefault(effectType);
			self.RepelDeBuffEffectTypes[effectType] = valueOrDefault + 1;
		}

		public static void DelRepelDeBuffEffectType(this BuffComponent self, int effectType)
		{
			int valueOrDefault = self.RepelDeBuffEffectTypes.GetValueOrDefault(effectType);
			if (--valueOrDefault <= 0)
			{
				self.RepelDeBuffEffectTypes.Remove(effectType);
			}
			else
			{
				self.RepelDeBuffEffectTypes[effectType] = valueOrDefault;
			}
		}
	}
