		private static void Awake(this PlayerModuleInfoComponent self)
		{
			self.All.Clear();
			self.Key2Infos.Clear();
			self.Type2Infos.Clear();
			self.AllSave.Clear();
			foreach (Type type in Singleton<EventSystem>.Instance.GetTypes(typeof(PlayerModuleAttribute)))
			{
				PlayerModuleAttribute customAttribute = ((MemberInfo)type).GetCustomAttribute<PlayerModuleAttribute>();
				PlayerModuleInfo playerModuleInfo = new PlayerModuleInfo
				{
					Type = type,
					Save = customAttribute.Save,
					Offline = customAttribute.Offline
				};
				if (customAttribute.Save)
				{
					self.AllSave.Add(playerModuleInfo);
				}
				self.Key2Infos.Add(type.Name, playerModuleInfo);
				self.Type2Infos.Add(type, playerModuleInfo);
				self.All.Add(playerModuleInfo);
			}
		}

