				component.TriggerPassive(args);
			}
			args.Type += 100;
			if (target != null && !((Entity)target).IsDisposed && !target.IsDead())
			{
				((Entity)target).GetComponent<SkillTriggerComponent>().TriggerPassive(args);
			}
			args.Type += 100;
			foreach (Unit fightUnit in ((Entity)battleScene).GetComponent<UnitComponent>().FightUnits)
			{
				if (!fightUnit.IsDead())
				{
					((Entity)fightUnit).GetComponent<SkillTriggerComponent>().TriggerPassive(args);
				}
			}
		}
	}
