	[FriendOf(typeof(ActivityData))]
	public static class ActivityDataSystem
	{
		public static bool IsClose(this ActivityData self)
		{
			bool num = TimeHelper.Now() >= self.EndTime;
			bool flag = true;
			List<Cond> condition = self.Condition;
			if (condition != null && condition.Count > 0)
			{
				flag = ((self.CondType == 1) ? ((Entity)(object)self).LocalPlayer().CheckAnyConds(self.Condition?.ToArray()) : ((Entity)(object)self).LocalPlayer().CheckAllConds(self.Condition?.ToArray()));
			}
			if (num)
			{
				return !flag;
			}
			return false;
		}

		public static bool IsHide(this ActivityData self)
		{
			return !((Entity)(object)self).LocalPlayer().CheckAllConds(self.Condition?.ToArray());
		}

		public static string GetIcon(this ActivityData self)
		{
			if (string.IsNullOrEmpty(self.Icon))
			{
				return string.Empty;
			}
			return self.Icon.Split(',')[0];
		}

		public static string GetIconEffect(this ActivityData self)
		{
			return self.IconEffect;
		}

		public static bool IsShow(this ActivityData self, ActivityCenterType activityCenterType)
		{
			if ((self.ActivityCenterType & activityCenterType) == 0)
			{
				return false;
			}
			if (TimeHelper.Now() > self.EndTime)
			{
				return false;
			}
			bool flag = true;
			List<Cond> condition = self.Condition;
			if (condition != null && condition.Count > 0)
			{
				flag = ((self.CondType == 1) ? ((Entity)(object)self).LocalPlayer().CheckAnyConds(self.Condition?.ToArray()) : ((Entity)(object)self).LocalPlayer().CheckAllConds(self.Condition?.ToArray()));
			}
			if (self.ActivityType == ActivityType.TotalExpense)
			{
				return ((Entity)self).GetComponent<TotalExpenseModule>().IsShow(activityCenterType);
			}
			if (self.ActivityType == ActivityType.SevenDaySign)
			{
				return ((Entity)self).GetComponent<SevenDaySignModule>().IsShow(activityCenterType);
			}
			if (self.ActivityType == ActivityType.Ladder)
			{
				return ((Entity)self).GetComponent<LadderActivityModule>().IsShow(activityCenterType, flag);
			}
			if (self.ActivityType == ActivityType.LadderTop)
			{
				return ((Entity)self).GetComponent<LadderTopActivityModule>().IsShow(activityCenterType, flag);
			}
			if (self.ActivityType == ActivityType.KingWar)
			{
				return ((Entity)self).GetComponent<KingWarActivityModule>().IsShow(activityCenterType, flag);
			}
			if (self.ActivityType == ActivityType.AncientWar)
			{
				return ((Entity)self).GetComponent<AncientWarActivityModule>().IsShow(activityCenterType, flag);
			}
			return flag;
		}

		public static void OnSpanDay(this ActivityData self)
		{
			switch (self.ActivityType)
			{
			case ActivityType.SevenDaySign:
				((Entity)self).GetComponent<SevenDaySignModule>().OnSpanDay();
				break;
			case ActivityType.DirectBuyEveryDayGift:
				((Entity)self).GetComponent<DirectBuyEveryDayGiftModule>().OnSpanDay();
				break;
			case ActivityType.ExchangeShop:
				((Entity)self).GetComponent<ExchangeShopModule>().OnSpanDay();
				break;
			case ActivityType.DirectBuySelectGift:
				((Entity)self).GetComponent<DirectBuySelectGiftModule>().OnSpanDay();
				break;
			}
		}

		public static void SetBaseInfo(this ActivityData self, L2C_SyncActivityModule msg)
		{
			self.BaseInfo = msg.BaseInfo;
			if (self.BaseInfo.ActivityType == 2)
			{
				self.BaseInfo.ActivityCenterType = 128;
			}
		}

		public static Cond[] ReadCond(List<ActivityCond> src)
		{
			if (src == null)
			{
				return null;
			}
			Cond[] array = new Cond[src.Count];
			for (int i = 0; i < src.Count; i++)
			{
				array[i] = new Cond
				{
					Type = src[i].Type,
					intValue = src[i].intValue,
					longValue = src[i].longValue
				};
			}
			return array;
		}
	}
