		public static List<ActivityData> GetAllActivity(this PlayerActivityComponent self, ActivityType activityType)
		{
			List<ActivityData> list = new List<ActivityData>();
			foreach (Entity value in ((Entity)self).Children.Values)
			{
				ActivityData activityData = value as ActivityData;
				if (activityData.ActivityType == activityType && !activityData.IsClose())
				{
					list.Add(activityData);
				}
			}
			return list;
		}

		public static List<ActivityData> GetAllActivity(this PlayerActivityComponent self, ActivityCenterType activityCenterType)
		{
			List<ActivityData> list = new List<ActivityData>();
			foreach (Entity value in ((Entity)self).Children.Values)
			{
				ActivityData activityData = value as ActivityData;
				if (activityData.IsShow(activityCenterType) && (activityCenterType == ActivityCenterType.None || (activityCenterType & activityData.ActivityCenterType) != ActivityCenterType.None))
				{
					list.Add(activityData);
				}
			}
			return list;
		}

		public static (Dictionary<int, List<ActivityData>> _res, List<ActivityCalendarConfig> cs) GetAllActivity(this PlayerActivityComponent self)
		{
