				if (list2 == null)
				{
					list2 = new List<ActivityData>();
					dictionary[activityData.ActivityCalendarType] = list2;
				}
				list2.Add(activityData);
			}
			foreach (KeyValuePair<int, List<ActivityData>> item2 in dictionary)
			{
				ActivityCalendarConfig item = ConfigSingleton<ActivityCalendarConfigCategory>.Instance.Get(item2.Key);
				list.Add(item);
			}
			list.Sort((ActivityCalendarConfig a, ActivityCalendarConfig b) => a.Id - b.Id);
			return (_res: dictionary, cs: list);
		}

