				{
					Log.Error("TimedStateComponent: timeIntervals is null or empty");
					return;
				}
				self.StartTimestamp = startTimestamp;
				self.TimeIntervals = timeIntervals;
				self.TotalStates = timeIntervals.Length + 1;
				self.TotalDuration = 0L;
				for (int i = 0; i < timeIntervals.Length; i++)
				{
					self.TotalDuration += timeIntervals[i];
				}
				self.CalculateCurrentState();
			}
		}

		public static int GetCurrentState(this ActivityRoundTime self)
		{
			self.CalculateCurrentState();
			return self.CurrentState + 1;
		}

		public static void CalculateCurrentState(this ActivityRoundTime self)
		{
			long num = TimeHelper.Now();
			if (num < self.StartTimestamp)
			{
				self.CurrentState = 0;
				return;
			}
			long num2 = num - self.StartTimestamp;
			if (num2 >= self.TotalDuration)
			{
				self.CurrentState = self.TotalStates - 1;
				return;
			}
			long num3 = 0L;
			for (int i = 0; i < self.TimeIntervals.Length; i++)
			{
				if (num2 < num3 + self.TimeIntervals[i])
				{
					self.CurrentState = i;
					return;
				}
				num3 += self.TimeIntervals[i];
			}
			self.CurrentState = self.TotalStates - 1;
		}
	}
