		public static IPEndPoint GetAddress(this RouterAddressComponent self)
		{
			if (self.Info.Routers.Count == 0)
			{
				return null;
			}
			string[] array = self.Info.Routers[self.RouterIndex++ % self.Info.Routers.Count].Split(':');
			IPAddress iPAddress = IPAddress.Parse(array[0]);
			if (self.RouterManagerIPAddress.AddressFamily == AddressFamily.InterNetworkV6)
			{
				iPAddress = iPAddress.MapToIPv6();
			}
			return new IPEndPoint(iPAddress, int.Parse(array[1]));
		}

		public static IPEndPoint GetRealmAddress(this RouterAddressComponent self, string account)
		{
			int index = StringHashHelper.Mode(account, self.Info.Realms.Count);
			string[] array = self.Info.Realms[index].Split(':');
			return new IPEndPoint(IPAddress.Parse(array[0]), int.Parse(array[1]));
		}
	}
