			foreach (WarBuildInfo build in warInfo.Builds)
			{
				((Entity)self).AddChildWithId<AncientWarBuild, WarBuildInfo>((long)build.ConfigId, build, false);
			}
			foreach (WarZoneInfo zone in warInfo.Zones)
