				item.ShowUnit();
			}
			foreach (AncientWarZone item2 in ((Entity)self).Children.Values.Where((Entity e) => e is AncientWarZone).Cast<AncientWarZone>())
			{
				item2.ShowUnit();
			}
		}

		public static int GetPlayerNum(this AncientWarComponent self, int configId, int camp)
		{
