		public static List<AncientWarUnit> GetPlayerUnits(this AncientWarComponent self, int configId, int camp)
		{
			AncientWarBuild ancientWarBuild = self.GetAncientWarBuild(configId);
			List<long> unitIds = ancientWarBuild.UnitIds;
			if (unitIds == null || unitIds.Count <= 0)
			{
				return null;
			}
