				AncientWarUnit ancientWarUnitByUnitId = self.GetAncientWarUnitByUnitId(kingWarUnitId);
				if (ancientWarUnitByUnitId.CampId == camp)
				{
					list.Add(ancientWarUnitByUnitId);
				}
			}
			return list;
		}
