				{
					worldList.Add(chatInfo);
				}
				else
				{
					worldList.Add(chatInfo);
				}
			}
			else if (chatInfo.Channel == 7)
			{
				if (self.CrossList == null)
				{
					self.CrossList = new List<ChatInfo>();
				}
				self.CrossList.Add(chatInfo);
			}
			else if (chatInfo.Channel == 2)
			{
				if (self.ClanList == null)
				{
					self.ClanList = new List<ChatInfo>();
				}
				self.ClanList.Add(chatInfo);
			}
			else
			{
				channel = chatInfo.Channel;
				if (channel == 3 || channel == 6)
				{
					PlayerCommonInfo playerCommonInfo = ((chatInfo.Sender.Id == ((Entity)self.Player).Id) ? chatInfo.Receiver : chatInfo.Sender);
					if (!self.GetPersonDict().ContainsKey(playerCommonInfo.Id))
					{
						self.GetPersonDict().Add(playerCommonInfo.Id, new ChatPersonData
						{
							Sender = playerCommonInfo
						});
					}
					self.ChatPersonDict[playerCommonInfo.Id].IsNew = !isLook;
					self.ChatPersonDict[playerCommonInfo.Id].PrivateDatas.Add(chatInfo);
				}
				else if (chatInfo.Channel == 5)
				{
					if (self.KingWarList == null)
					{
						self.KingWarList = new List<ChatInfo>();
					}
					self.KingWarList.Add(chatInfo);
				}
				else if (chatInfo.Channel == 9)
				{
					if (self.AncientWarList == null)
					{
						self.AncientWarList = new List<ChatInfo>();
					}
					self.AncientWarList.Add(chatInfo);
				}
