				return;
			}
			Singleton<EventSystem>.Instance.Publish<ChatChange>(SceneHelper.DomainScene((Entity)(object)self), new ChatChange
			{
				Channel = chatInfo.Channel,
				SenderId = (chatInfo.Sender?.Id ?? 0)
			});
			if (chatInfo.IsBroad)
			{
				string text = chatInfo.Text;
				if (chatInfo.Sender != null && chatInfo.Sender.Name != null)
				{
					text = $"{chatInfo.Sender.Name}:{chatInfo.Text}";
				}
				Singleton<EventSystem>.Instance.Publish<BroadMessage>(SceneHelper.DomainScene((Entity)(object)self), new BroadMessage
				{
					Text = text
				});
			}
