			if (!self.GiftState.ContainsKey(_giftId))
			{
				self.GiftState.Add(_giftId, 1);
			}
			else
			{
				self.GiftState[_giftId]++;
			}
			self.RewardGift = _giftId;
			Singleton<EventSystem>.Instance.Publish<ET.EventType.UIGiftPanelBuyEvent>(SceneHelper.DomainScene((Entity)(object)self), default(ET.EventType.UIGiftPanelBuyEvent));
		}

		public static int GetRewardGift(this DirectBuyThemeGiftModule self)
		{
			return self.RewardGift;
		}

