			}
		}

		public static bool GiftCanGetReward(this DirectBuyThemeGiftModule self, int configId)
		{
			if (self.RewardGift == configId)
			{
				return true;
			}
			return false;
		}

		public static bool IsGiftCanBuy(this DirectBuyThemeGiftModule self, int configId)
		{
			DirectBuyGiftConfig directBuyGiftConfig = ConfigSingleton<DirectBuyGiftConfigCategory>.Instance.Get(configId);
			if (self.RewardGift == directBuyGiftConfig.Id)
			{
				return true;
			}
			if (self.GiftState.ContainsKey(configId) && self.GiftState[configId] >= directBuyGiftConfig.LimitNum)
			{
				return false;
			}
			return true;
		}

		public static bool IsBuyOver(this DirectBuyThemeGiftModule self, int PayId = 0)
		{
			Dictionary<int, DirectBuyGiftActivityConfig> all = ConfigSingleton<DirectBuyGiftActivityConfigCategory>.Instance.GetAll();
			List<int> list = new List<int>();
			foreach (DirectBuyGiftActivityConfig value in all.Values)
			{
				if (value.ActId == self.ActivityData.ActivityId)
				{
					list.Add(value.Id);
				}
			}
			if (PayId > 0)
			{
				foreach (int item in list)
				{
					foreach (DirectBuyGiftConfig value2 in ConfigSingleton<DirectBuyGiftConfigCategory>.Instance.GetDictionary(item).Values)
					{
						if (value2.PayId == PayId)
						{
							return self.GiftState.ContainsKey(value2.Id) && self.GiftState[value2.Id] >= value2.LimitNum;
						}
					}
				}
			}
			else
			{
				foreach (int item2 in list)
				{
					foreach (DirectBuyGiftConfig value3 in ConfigSingleton<DirectBuyGiftConfigCategory>.Instance.GetDictionary(item2).Values)
					{
						if (self.GiftState.ContainsKey(value3.Id) && self.GiftState[value3.Id] < value3.LimitNum)
						{
							return false;
						}
						if (!self.GiftState.ContainsKey(value3.Id))
						{
							return false;
						}
					}
				}
			}
			return true;
		}
	}
	[FriendOf(typeof(GiftModule))]
	public static class GiftModuleSystem
	{
		public static void RegisterGift(this GiftModule self, int itemId, int cost, GiftType giftType, int configId, int activityId, int priority = 0)
		{
			if (self.GiftDates == null)
			{
				self.GiftDates = new Dictionary<int, SortedDictionary<int, GiftItemDate>>();
			}
			if (!self.GiftDates.ContainsKey(itemId))
			{
				self.GiftDates.Add(itemId, new SortedDictionary<int, GiftItemDate>());
			}
			if (!self.GiftDates.TryGetValue(itemId, out var value))
			{
				self.GiftDates.Add(itemId, value = new SortedDictionary<int, GiftItemDate>());
			}
			if (priority == 0)
			{
				priority = cost;
			}
			if (!value.TryGetValue(priority, out var value2))
			{
				value2 = new GiftItemDate();
				value2.cost = cost;
				value2.activityId = activityId;
				value2.giftType = giftType;
				value2.configId = configId;
				value.Add(priority, value2);
			}
		}

		public static void RegisterGift(this GiftModule self, ET.ConfigBeans.Item item, int cost, GiftType giftType, int configId, int activityId, int priority = 0)
		{
			self.RegisterGift(item.Id, cost, giftType, configId, activityId);
		}

		public static void RegisterGift(this GiftModule self, ET.ConfigBeans.Item[] items, int cost, GiftType giftType, int configId, int activityId, int priority = 0)
		{
			foreach (ET.ConfigBeans.Item item in items)
			{
				self.RegisterGift(item, cost, giftType, configId, activityId);
			}
		}

		public static void UnRegisterGift(this GiftModule self, int itemId, int activityId)
		{
			if (self.GiftDates.ContainsKey(itemId))
			{
				self.GiftDates.Remove(itemId);
			}
		}

		public static void UnRegisterGift(this GiftModule self, ET.ConfigBeans.Item item, int activityId)
		{
			self.UnRegisterGift(item.Id, activityId);
		}

		public static void UnRegisterGift(this GiftModule self, ET.ConfigBeans.Item[] items, int activityId)
		{
			foreach (ET.ConfigBeans.Item item in items)
			{
				self.UnRegisterGift(item, activityId);
			}
		}

		public static void UnRegisterGift(this GiftModule self, GiftType giftType, int activityId)
		{
			Dictionary<int, int> dictionary = new Dictionary<int, int>();
			foreach (int key in self.GiftDates.Keys)
			{
				if (self.GiftDates[key].Count <= 0)
				{
					continue;
				}
				foreach (int key2 in self.GiftDates[key].Keys)
				{
					if (self.GiftDates[key][key2].giftType == giftType && self.GiftDates[key][key2].activityId == activityId)
					{
						dictionary.Add(key, key2);
					}
				}
			}
			foreach (int key3 in dictionary.Keys)
			{
				self.GiftDates[key3].Remove(dictionary[key3]);
			}
		}

		public static void ClearGift(this GiftModule self)
		{
			self.GiftDates.Clear();
			self.GiftDates = null;
		}

		public static SortedDictionary<int, GiftItemDate> GetGiftItemDate(this GiftModule self, int itemId)
		{
			if (!self.GiftDates.ContainsKey(itemId))
			{
				return null;
			}
			return self.GiftDates[itemId];
		}

		public static GiftItemDate GetGiftItemDate(this GiftModule self, int itemId, int cost)
		{
			if (!self.GiftDates.ContainsKey(itemId))
			{
				return null;
			}
			return self.GiftDates[itemId][cost];
		}
	}
