		public static bool IsEveryDaySignTabRedDot(this EveryDaySignModule self)
		{
			int mark = self.GetMark();
			if (!self.IsRewardDayFlag(mark))
			{
				return true;
			}
			if (self.IsPrivilege())
			{
				int loop = self.GetLoop();
				foreach (EveryDaySignConfig item in ConfigSingleton<EveryDaySignConfigCategory>.Instance.GetAll(self.ActivityData.ActivityId))
				{
					if (item.Round == loop && mark >= item.Day)
					{
						if (!self.IsRewardDayFlag(item.Day))
						{
							return true;
						}
						if (!self.IsRewardDayPrivilegeFlag(item.Day))
						{
							return true;
						}
					}
				}
			}
			foreach (EveryDaySignLoopConfig value in ConfigSingleton<EveryDaySignLoopConfigCategory>.Instance.GetAll().Values)
			{
				if (value.ActId == self.ActivityData.ActivityId)
				{
					if (value.Id > self.Total && self.Count >= value.Day)
					{
						return true;
					}
					if (self.Count < value.Day)
					{
						break;
					}
				}
			}
			return false;
		}
	}
