		public static void AddHero(this FormationData self, int pos, long heroId, bool addUnit = true)
		{
			Player player = ((Entity)(object)self).LocalPlayer();
			Hero heroByUid = player.GetHeroByUid(heroId);
			if (heroByUid != null)
			{
				self.PosHeroMap.Add(pos, heroId);
				self.HeroSet.Add(heroByUid.ConfigId);
				if (addUnit)
				{
					int offsetPosId = SceneInfoHelper.GetOffsetPosId(pos, self.PosOffsetIndex);
					self.HeroUnitMap.Add(heroId, UnitFactory.CreateFormationUnit(SceneHelper.DomainScene((Entity)(object)self), player, heroId, offsetPosId));
				}
			}
		}

		public static void RemoveHero(this FormationData self, long heroId, bool removeUnit = true)
		{
			if (self.PosHeroMap.RemoveByValue(heroId))
			{
				Hero heroByUid = ((Entity)(object)self).LocalPlayer().GetHeroByUid(heroId);
				self.HeroSet.Remove(heroByUid.ConfigId);
				if (removeUnit && self.HeroUnitMap.Remove(heroId, out var value))
				{
					((DisposeObject)value).Dispose();
				}
			}
		}

		public static bool IsHeroSet(this FormationData self, int configId)
		{
			return self.HeroSet.Contains(configId);
		}

		public static bool ContainsHero(this FormationData self, long heroId)
		{
			return self.PosHeroMap.ContainsValue(heroId);
		}

		public static bool IsFull(this FormationData self)
		{
			return self.Count >= self.Config.Max;
		}

		public static bool IsPosEmpty(this FormationData self, int pos)
		{
			return !self.PosHeroMap.ContainsKey(pos);
		}

		public static Dictionary<int, long> ToDictionary(this FormationData self)
		{
			Dictionary<int, long> dictionary = new Dictionary<int, long>();
			self.PosHeroMap.ForEach((Action<int, long>)dictionary.Add);
			return dictionary;
		}
	}
