		public static Dictionary<int, List<long>> GetFormationGroupBestComb(this Player player, List<FormationInfo> formationInfos, int formationId = 0)
		{
			HashSetComponent<long> used = HashSetComponent<long>.Create();
			try
			{
				Dictionary<int, List<long>> dictionary = new Dictionary<int, List<long>>();
				foreach (FormationInfo formationInfo in formationInfos)
				{
					if (formationId <= 0 || formationId == formationInfo.FormationId)
					{
						continue;
					}
					foreach (var (_, item) in formationInfo.PosHero)
					{
						((HashSet<long>)(object)used).Add(item);
					}
				}
				foreach (FormationInfo formationInfo2 in formationInfos)
				{
					FormationConfig formationConfig = ConfigSingleton<FormationConfigCategory>.Instance.Get(formationInfo2.FormationId);
					HeroInclude includes = ((formationConfig.RoleDeployType == 0) ? HeroInclude.All : HeroInclude.Hero);
					if (formationId > 0 && formationId != formationInfo2.FormationId)
					{
						continue;
					}
					List<Hero> heroes = player.GetHeroes(new HeroSearch
					{
						OnlyActive = true,
						Includes = includes,
						Filter = (long heroId) => !((HashSet<long>)(object)used).Contains(heroId)
					});
					if (formationConfig.CanRent)
					{
						foreach (Hero allHero in ((Entity)player).GetComponent<HeroRentModule>().GetAllHeroes())
						{
							heroes.Add(allHero);
						}
					}
					heroes.Sort(PowerHighToLow);
					List<long> result = new List<long>();
					HashSet<int> jobHit = new HashSet<int>();
					HashSet<int> heroHit = new HashSet<int>();
					int slotLeft = formationConfig.Max;
					Action<Hero> action = delegate(Hero hero3)
					{
						result.Add(((Entity)hero3).Id);
						slotLeft--;
						heroHit.Add(hero3.ConfigId);
						jobHit.Add(hero3.Config.Job);
						((HashSet<long>)(object)used).Add(((Entity)hero3).Id);
					};
					if (formationConfig.RoleDeployType == 1)
					{
						action(player.GetRoleHero());
					}
					int count = ConfigSingleton<JobConfigCategory>.Instance.GetAll().Count;
					int num3 = count - jobHit.Count;
					int num4 = -1;
					if (num3 > 0 && slotLeft >= num3)
					{
						while (slotLeft > 0 && jobHit.Count < count && ++num4 < heroes.Count)
						{
							Hero hero = heroes[num4];
							HeroConfig config = hero.Config;
							if (!jobHit.Contains(config.Job) && !heroHit.Contains(hero.ConfigId) && !result.Contains(((Entity)hero).Id))
							{
								action(hero);
							}
						}
					}
					num4 = -1;
					while (slotLeft > 0 && ++num4 < heroes.Count)
					{
						Hero hero2 = heroes[num4];
						if (!heroHit.Contains(hero2.ConfigId) && !result.Contains(((Entity)hero2).Id))
						{
							action(hero2);
						}
					}
					result.Sort(delegate(long a, long b)
					{
						Hero heroByUid = player.GetHeroByUid(a);
						Hero heroByUid2 = player.GetHeroByUid(b);
						int job = heroByUid.Config.Job;
						int job2 = heroByUid2.Config.Job;
						return (job != job2) ? (ConfigSingleton<JobConfigCategory>.Instance.Get(job).FormationOrder - ConfigSingleton<JobConfigCategory>.Instance.Get(job2).FormationOrder) : heroByUid2.GetPower().CompareTo(heroByUid.GetPower());
					});
					dictionary.Add(formationInfo2.FormationId, result);
				}
				return dictionary;
			}
			finally
			{
				if (used != null)
				{
					((IDisposable)used).Dispose();
				}
			}
		}

		private static int PowerHighToLow(Hero a, Hero b)
		{
			return b.GetPower().CompareTo(a.GetPower());
		}

		public static bool IsAnyVacantPosition(Player player, int formationId)
		{
			List<int> groupIds = ET.FormationHelper.GetGroupIds(formationId, includeCurrentId: true);
			FormationModule component = ((Entity)player).GetComponent<FormationModule>();
			bool flag = true;
			int num = 0;
			foreach (int item in groupIds)
			{
				Formation formation = component.GetFormation(item);
				num += formation.PosHero.Count;
				if (formation.PosHero.Count < formation.Config.Max)
				{
					flag = false;
				}
			}
			if (flag)
			{
				return false;
			}
			return num < player.GetHeroes(new HeroSearch
			{
				OnlyActive = true,
				Includes = HeroInclude.All
			}).Count;
		}
	}
