		public static void UpdateSevenDayTarget(this GodWillAssemblyModule self, Dictionary<int, GodWillAssemblyInfo> taskList)
		{
			if (taskList == null)
			{
				return;
			}
			foreach (KeyValuePair<int, GodWillAssemblyInfo> task in taskList)
			{
				var (configId, godWillAssemblyInfo2) = task;
				GodWillAssemblyConfig godWillAssemblyConfig = ConfigSingleton<GodWillAssemblyConfigCategory>.Instance.Get(configId);
				if (godWillAssemblyConfig != null)
				{
					int actId = godWillAssemblyConfig.ActId;
					if (!self.TaskList.TryGetValue(actId, out var value))
					{
						value = new List<GodWillAssemblyData>();
						self.TaskList.Add(actId, value);
					}
					GodWillAssemblyData godWillAssemblyData = self.TaskList[actId].Find((GodWillAssemblyData m) => m.Id == configId);
					if (godWillAssemblyData == null)
					{
						godWillAssemblyData = new GodWillAssemblyData
						{
							Id = configId
						};
						self.TaskList[actId].Add(godWillAssemblyData);
					}
					godWillAssemblyData.Count = godWillAssemblyInfo2.Count;
					godWillAssemblyData.Status = godWillAssemblyInfo2.Status;
					godWillAssemblyData.Stage = godWillAssemblyInfo2.Stage;
					Singleton<EventSystem>.Instance.Publish<GodWillAssembly_Success>(SceneHelper.DomainScene((Entity)(object)self), default(GodWillAssembly_Success));
				}
			}
		}

		public static void UpdateSevenDayTargetTask(this GodWillAssemblyModule self, List<GodWillAssemblyInfo> infoList)
		{
			for (int i = 0; i < infoList.Count; i++)
			{
				GodWillAssemblyInfo godWillAssemblyInfo = infoList[i];
				GodWillAssemblyData taskData = self.GetTaskData(godWillAssemblyInfo.ConfigId);
				if (taskData != null)
				{
					taskData.Count = godWillAssemblyInfo.Count;
					taskData.Status = godWillAssemblyInfo.Status;
					taskData.Stage = godWillAssemblyInfo.Stage;
					Singleton<EventSystem>.Instance.Publish<GodWillAssembly_Success>(SceneHelper.DomainScene((Entity)(object)self), default(GodWillAssembly_Success));
				}
			}
		}

		public static bool IsShowRed(this GodWillAssemblyModule self)
		{
			List<GodWillAssemblyConfig> all = ConfigSingleton<GodWillAssemblyConfigCategory>.Instance.GetAll(self.ActivityData.ActivityId);
			if (all == null)
			{
				return false;
			}
			foreach (GodWillAssemblyConfig item in all)
			{
				GodWillAssemblyData taskData = self.GetTaskData(item.Id);
				if (taskData != null && taskData.Count != 0 && taskData.Status == 1)
				{
					return true;
				}
			}
			List<GodWillAssemblyStageConfig> all2 = ConfigSingleton<GodWillAssemblyStageConfigCategory>.Instance.GetAll(self.ActivityData.ActivityId);
			if (all2 == null)
			{
				return false;
			}
			foreach (GodWillAssemblyStageConfig item2 in all2)
			{
				if (!BitHelper.IsBitSet(self.ScoreData, item2.Sort) && self.Score >= item2.Nums)
				{
					return true;
				}
			}
			return false;
		}

		public static bool IsShowFreeRed(this GodWillAssemblyModule self)
		{
			return !TimeHelper.IsSameDay(TimeHelper.ServerNow(), self.GetTime, 18000000L);
		}
	}
