		private static void OnGetFree(this GodWillStraightModule self)
		{
			self.GetFreeTime = TimeHelper.ServerNow();
		}

		private static void OnSelectGift(this GodWillStraightModule self, int day, int dayIndex, int itemIndex)
		{
			GodWillStraightSelectGiftData selectGift = self.GetSelectGift(day);
			Dictionary<int, GodWillStraightConfig> dictionary = ConfigSingleton<GodWillStraightConfigCategory>.Instance.GetDictionary(self.ActivityData.ActivityId);
			if (dictionary.ContainsKey(day))
			{
				if (dictionary[day].SelectType == 0)
				{
					selectGift.SelectGiftData[day * 100 + dayIndex] = itemIndex;
				}
				if (dictionary[day].SelectType == 1)
				{
					selectGift.SelectGiftData[day] = dayIndex;
				}
			}
		}

		private static void OnGetReward(this GodWillStraightModule self, int day)
		{
			Dictionary<int, GodWillStraightConfig> dictionary = ConfigSingleton<GodWillStraightConfigCategory>.Instance.GetDictionary(self.ActivityData.ActivityId);
			if (dictionary == null)
			{
				Log.Error("配置不存在GodWillStraightActConfig");
			}
			else if (!dictionary.ContainsKey(day))
			{
				Log.Error("配置不存在GodWillStraightActConfig");
			}
			else if (!self.GetStatus.ContainsKey(day))
			{
				self.GetStatus.Add(day, 1);
				if (self.GetStatus[day] >= dictionary[day].Count)
				{
					self.Get(day);
				}
				else
				{
					self.Buy2(day);
				}
			}
			else if (self.GetStatus[day] + 1 >= dictionary[day].Count)
			{
				self.GetStatus[day] = dictionary[day].Count;
				self.Get(day);
			}
			else
			{
				self.GetStatus[day]++;
				self.Buy2(day);
			}
		}

		public static int GetCount(this GodWillStraightModule self, int day)
		{
			if (self.GetStatus.ContainsKey(day))
			{
				return self.GetStatus[day];
			}
			return 0;
		}

		public static void BuySuccess(this GodWillStraightModule self, int day)
		{
			self.BuyCount |= 1 << day;
		}

		public static bool IsBuy(this GodWillStraightModule self, int day)
		{
			return (self.BuyCount & (1 << day)) != 0;
		}

		private static void Buy2(this GodWillStraightModule self, int day)
		{
			self.BuyCount &= ~(1 << day);
		}

		private static void Get2(this GodWillStraightModule self, int day)
		{
			self.GetCount &= ~(1 << day);
		}

		public static bool IsGet(this GodWillStraightModule self, int day)
		{
			return (self.GetCount & (1 << day)) != 0;
		}

		private static void Get(this GodWillStraightModule self, int day)
		{
			self.GetCount |= 1 << day;
		}

		public static GodWillStraightSelectGiftData GetSelectGift(this GodWillStraightModule self, int day)
		{
			if (self.SelectGifts == null)
			{
				self.SelectGifts = new Dictionary<int, GodWillStraightSelectGiftData>();
			}
			if (!self.SelectGifts.ContainsKey(day))
			{
				self.SelectGifts[day] = new GodWillStraightSelectGiftData();
			}
			if (self.SelectGifts[day].SelectGiftData == null)
			{
				self.SelectGifts[day].SelectGiftData = new Dictionary<int, int>();
			}
			return self.SelectGifts[day];
		}

		public static bool IsGetFree(this GodWillStraightModule self)
		{
			return TimeHelper.IsSameDay(TimeHelper.ServerNow(), self.GetFreeTime, 18000000L);
		}

		public static bool MianRed(this GodWillStraightModule self)
		{
			Dictionary<int, GodWillStraightConfig> dictionary = ConfigSingleton<GodWillStraightConfigCategory>.Instance.GetDictionary(self.ActivityData.ActivityId);
			if (dictionary == null)
			{
				Log.Error("为嘛不配置GodWillStraightConfig？？？？？");
				return true;
			}
			if (!self.IsGetFree())
			{
				return false;
			}
			foreach (GodWillStraightConfig value in dictionary.Values)
			{
				if (self.IsBuy(value.Day) && !self.IsGet(value.Day))
				{
					return false;
				}
			}
			return true;
		}

		public static int GetDayCanBuy(this GodWillStraightModule self)
		{
			int result = 0;
			Dictionary<int, GodWillStraightConfig> dictionary = ConfigSingleton<GodWillStraightConfigCategory>.Instance.GetDictionary(self.ActivityData.ActivityId);
			if (dictionary == null)
			{
				Log.Error("为嘛不配置GodWillStraightConfig？？？？？");
				return result;
			}
			foreach (GodWillStraightConfig value in dictionary.Values)
			{
				if (!self.GetStatus.ContainsKey(value.Day))
				{
					return value.Day;
				}
				if (self.GetStatus.ContainsKey(value.Day) && self.GetStatus[value.Day] < value.Count)
				{
					return value.Day;
				}
				if (self.IsBuy(value.Day) && !self.IsGet(value.Day))
				{
					return value.Day;
				}
			}
			return result;
		}

		public static bool IsBuyOver(this GodWillStraightModule self, int gift = 0)
		{
			int num = TimeHelper.DaysBetween(TimeHelper.ServerNow(), self.ActivityData.StartTime, 18000000L);
			if (ConfigSingleton<GodWillStraightConfigCategory>.Instance.GetDictionary(self.ActivityData.ActivityId) == null)
			{
				return false;
			}
			if (gift > 0)
			{
				return self.IsBuy(gift);
			}
			for (int i = 1; i <= num; i++)
			{
				if (!self.GetStatus.ContainsKey(i))
				{
					return false;
				}
				if (!self.IsBuy(i))
				{
					return false;
				}
			}
			return true;
		}
	}
