		public static void OnScoreChange(this GrowthFundGameplayModule self, Dictionary<int, GrowthFundTaskInfo> taskList, int score)
		{
			self.Score = score;
			if (taskList == null)
			{
				return;
			}
			foreach (KeyValuePair<int, GrowthFundTaskInfo> task in taskList)
			{
				var (configId, growthFundTaskInfo2) = task;
				GrowthFundWeekGameplayTaskConfig growthFundWeekGameplayTaskConfig = ConfigSingleton<GrowthFundWeekGameplayTaskConfigCategory>.Instance.Get(configId);
				if (growthFundWeekGameplayTaskConfig != null)
				{
					int actId = growthFundWeekGameplayTaskConfig.ActId;
					if (!self.TaskList.TryGetValue(actId, out var value))
					{
						value = new List<GrowthFundTaskData>();
						self.TaskList.Add(actId, value);
					}
					GrowthFundTaskData growthFundTaskData = self.TaskList[actId].Find((GrowthFundTaskData m) => m.Id == configId);
					if (growthFundTaskData == null)
					{
						growthFundTaskData = new GrowthFundTaskData
						{
							Id = configId
						};
						self.TaskList[actId].Add(growthFundTaskData);
					}
					growthFundTaskData.Count = growthFundTaskInfo2.Count;
					growthFundTaskData.Status = growthFundTaskInfo2.Status;
					growthFundTaskData.Stage = growthFundTaskInfo2.Stage;
				}
			}
			Singleton<EventSystem>.Instance.Publish<GrowthFundGameplayScoreChange_Success>(SceneHelper.DomainScene((Entity)(object)self), default(GrowthFundGameplayScoreChange_Success));
		}

