		private static int OnGetScoreRewardList(this GrowthFundGameplayModule self, Dictionary<int, GrowthFundWeekCardConfig> weekCardConfig, Dictionary<int, GrowthFundGameplayConfig> gameplayConfig)
		{
			int result = 0;
			GrowthFundGameplayConfig growthFundGameplayConfig = ConfigSingleton<GrowthFundGameplayConfigCategory>.Instance.Get(self.GetConfigId);
			foreach (GrowthFundWeekCardConfig value in weekCardConfig.Values)
			{
				if (value.Id > self.GetVipConfigId && growthFundGameplayConfig.Level >= value.Level && self.WeekCardId == value.CardId)
				{
					result = value.Id;
				}
			}
			return result;
		}

		private static int OnGetRewardList(this GrowthFundGameplayModule self, Dictionary<int, GrowthFundGameplayConfig> gameplayConfig)
		{
			int result = 0;
			for (int i = 1; i <= gameplayConfig.Count; i++)
			{
				GrowthFundGameplayConfig growthFundGameplayConfig = gameplayConfig[i];
				if (growthFundGameplayConfig != null)
				{
					if (growthFundGameplayConfig.Id > self.GetConfigId && self.Score >= growthFundGameplayConfig.Need)
					{
						result = growthFundGameplayConfig.Id;
					}
					if (self.Score < growthFundGameplayConfig.Need)
					{
						break;
					}
				}
			}
			return result;
		}

		public static bool MainRed(this GrowthFundGameplayModule self)
		{
			if (self.WeekCardId > 0 && !TimeHelper.IsSameDay(self.GetFreeTime, TimeHelper.ServerNow(), 18000000L))
			{
				return true;
			}
			if (self.Score == 0)
			{
				return false;
			}
			Dictionary<int, GrowthFundGameplayConfig> dictionary = ConfigSingleton<GrowthFundGameplayConfigCategory>.Instance.GetDictionary(self.ActivityData.ActivityId);
			if (dictionary == null)
			{
				return false;
			}
			Dictionary<int, GrowthFundWeekCardConfig> dictionary2 = ConfigSingleton<GrowthFundWeekCardConfigCategory>.Instance.GetDictionary(self.ActivityData.ActivityId);
			if (dictionary2 == null)
			{
				return false;
			}
			int num = self.OnGetRewardList(dictionary);
			if (num > 0)
			{
				return true;
			}
			if (num == 0 && self.WeekCardId > 0 && !self.Buy)
			{
				return false;
			}
			if (self.WeekCardId > 0 && self.Buy)
			{
				if (self.OnGetScoreRewardList(dictionary2, dictionary) == 0)
				{
					return false;
				}
				return true;
			}
			return false;
		}

		public static bool IsBuyCard(this GrowthFundGameplayModule self)
		{
			if (self.WeekCardId > 0)
			{
				return self.Buy;
			}
			return false;
		}
