		public static void OnBuyLevelSuccess(this GrowthFundLevelModule self, int level)
		{
			Dictionary<int, GrowthFundLevelAllConfig> dictionary = ConfigSingleton<GrowthFundLevelAllConfigCategory>.Instance.GetDictionary(self.ActivityData.ActivityId);
			if (dictionary == null)
			{
				Log.Error("配置有问题哦");
				return;
			}
			if (!dictionary.ContainsKey(level))
			{
				Log.Error("配置有问题哦");
				return;
			}
			Dictionary<int, GrowthFundBuyLevelConfig> dictionary2 = ConfigSingleton<GrowthFundBuyLevelConfigCategory>.Instance.GetDictionary(self.ActivityData.ActivityId);
			if (dictionary2 == null)
			{
				Log.Error("GrowthFundBuyLevelConfig中缺少该活动的配置");
				return;
			}
			int num = 0;
			int num2 = self.Score;
			foreach (GrowthFundLevelAllConfig value in dictionary.Values)
			{
				if (num2 >= value.Score)
				{
					num = value.Id;
					num2 -= value.Score;
					continue;
				}
				break;
			}
			int num3 = 0;
			foreach (GrowthFundBuyLevelConfig value2 in dictionary2.Values)
			{
				if (value2.cfgId > level)
				{
					break;
				}
				GrowthFundLevelAllConfig growthFundLevelAllConfig = ConfigSingleton<GrowthFundLevelAllConfigCategory>.Instance.Get(value2.cfgId);
				if (growthFundLevelAllConfig == null)
				{
					return;
				}
				if (growthFundLevelAllConfig.Level > level)
				{
					break;
				}
				if (value2.cfgId > num && growthFundLevelAllConfig.Level <= level)
				{
					num3 += growthFundLevelAllConfig.Score;
				}
			}
			self.Score += num3;
		}

