	[FriendOf(typeof(GuideModule))]
	public static class GuideModuleSystem
	{
		public static void ReqSaveGuide(this GuideModule self, int guideId)
		{
			if (self.FinishList.IndexOf(guideId) < 0)
			{
				self.Player.Send(new C2L_RequestSaveGuide
				{
					GuideId = guideId
				});
				self.FinishList.Add(guideId);
			}
		}

		public static void ReqStartGuide(this GuideModule self, int guideId, int guideStepId)
		{
			if (self.GuideId != guideId || self.GuideStepId != guideStepId)
			{
				self.Player.Send(new C2L_RequestStartGuide
				{
					GuideId = guideId,
					GuideStepId = guideStepId
				});
				self.GuideId = guideId;
				self.GuideStepId = guideStepId;
			}
		}
	}
