		public static List<Stat> GetViewShowSkill(this GuildModule self, int job)
		{
			var (flag, num, _) = self.GetSkillLvByJob(job);
			if (flag)
			{
				return GuildHelper.GetGuildSkillConfig(job, num).Stats.ToList();
			}
