				GuildSkillConfig guildSkillConfig2 = GuildHelper.GetGuildSkillConfig(job, i - 1);
				if (guildSkillConfig2 == null)
				{
					Stat stat = guildSkillConfig.Stats.FirstOrDefault((Stat x) => x.Value > 0);
					if (stat != null)
					{
