					List<Stat> list2 = (from stat2 in guildSkillConfig.Stats.Join(guildSkillConfig2.Stats, (Stat stat2) => stat2.Type, (Stat stat2) => stat2.Type, (Stat stat2, Stat stat3) => new Stat
