					}
				}
			}
			return list;
		}

		public static List<Stat> GetStatsDiff(this GuildModule self, int job, int curLv, int targetLv)
		{
			GuildSkillConfig guildSkillConfig = GuildHelper.GetGuildSkillConfig(job, targetLv);
			if (guildSkillConfig == null)
			{
				return null;
			}
			List<Stat> guildSkillStats = GuildHelper.GetGuildSkillStats(job, curLv);
			List<Stat> list = new List<Stat>();
			foreach (Stat stat in guildSkillStats)
			{
				Stat stat2 = guildSkillConfig.Stats.FirstOrDefault((Stat x) => x.Type == stat.Type);
				if (stat2 != null)
				{
					long num = stat2.Value - stat.Value;
					if (num > 0)
					{
						list.Add(new Stat
						{
							Type = stat.Type,
							Value = num
						});
					}
				}
			}
			return list;
		}

		public static (int err, int newLv, List<ItemStruct> itemList) CanAdvanceSkill(this GuildModule self, int job)
		{
			var (flag, num, _) = self.GetSkillLvByJob(job);
			if (flag)
			{
				return (err: 202825, newLv: 0, itemList: null);
			}
			int nextStageSkillLv = self.GetNextStageSkillLv(job);
			if (nextStageSkillLv <= 0)
			{
				return (err: 202837, newLv: 0, itemList: null);
			}
			int num2 = num + 1;
			int num3 = num2 + nextStageSkillLv - 1;
			ItemModule component = ((Entity)((Entity)self).GetParent<Player>()).GetComponent<ItemModule>();
			List<ItemStruct> list = new List<ItemStruct>();
			for (int i = num2; i <= num3; i++)
			{
				GuildSkillConfig guildSkillConfig = GuildHelper.GetGuildSkillConfig(job, i);
				list.Add(new ItemStruct
				{
					ConfigId = guildSkillConfig.Cost.Id,
					Nums = guildSkillConfig.Cost.Nums
				});
			}
			ItemList itemList = ItemList.Create();
			foreach (ItemStruct item in list)
			{
				itemList.Add(item);
			}
			if (!component.CheckItemNumsIsEnough(itemList))
			{
				return (err: 200102, newLv: 0, itemList: null);
			}
			return (err: 0, newLv: num3, itemList: list);
		}

		public static void UpdateFashion(this GuildModule self, Dictionary<int, int> dressIds)
		{
			if (self.GuildInfo == null)
			{
				return;
			}
			GuildMemberInfo guildMemberInfo = self.GuildInfo.Members.FirstOrDefault((GuildMemberInfo x) => x.PlayerInfo.Id == ((Entity)((Entity)(object)self).LocalPlayer()).Id && x.IsWarGod);
			if (guildMemberInfo == null)
			{
				return;
			}
			foreach (KeyValuePair<int, int> dressId in dressIds)
			{
				int key = dressId.Key;
				int value = dressId.Value;
				DressHelper.SetDress(guildMemberInfo.PlayerInfo.DressInfo, key, value);
			}
		}

