			{
				Singleton<EventSystem>.Instance.Publish<HeavenFightShowTipsEvent>(SceneHelper.DomainScene((Entity)(object)self), new HeavenFightShowTipsEvent
				{
					ActivityId = self.GetActivityId(),
					OpponentName = self.OpponentName,
					IsLogin = isLogin
				});
			}
		}

		private static void NoticeOpenSeason(this HeavenFightModule self)
		{
			long num = TimeHelper.Now();
			if (TimeHelper.IsSameDay(num, self.ActivityData.StartTime, 18000000L) && !TimeHelper.IsSameDay(num, self.LastNoticeTime, 18000000L))
			{
				self.LastNoticeTime = num;
				Singleton<EventSystem>.Instance.Publish<HeavenFightNewSeasonEvent>(SceneHelper.DomainScene((Entity)(object)self), new HeavenFightNewSeasonEvent
				{
					ActivityModule = self
				});
			}
		}

		public static HeavenFightPlatformInfo GetPlatformInfo(this HeavenFightModule self, int platformId)
		{
			self.Platforms.TryGetValue(platformId, out var value);
			return value;
		}

		public static bool IsPlatfomeWinner(this HeavenFightModule self, int platformId)
		{
			if (self.Platforms.TryGetValue(platformId, out var value) && value.OpponentInfo.PlayerId == ((Entity)((Entity)(object)self).LocalPlayer()).Id)
			{
				return true;
			}
			return false;
		}

		public static bool CheckOtherPlatform(this HeavenFightModule self, int platformId, long playerId)
		{
			foreach (KeyValuePair<int, HeavenFightPlatformInfo> platform in self.Platforms)
			{
				if (platform.Value.PlatformId != platformId && platform.Value.OpponentInfo.PlayerId == playerId)
				{
					return true;
				}
			}
			return false;
		}

		public static bool IsBossMaxDiffcult(this HeavenFightModule self, int platformId)
		{
			int bossDifficulty = self.GetBossDifficulty(platformId);
			HeavenFightConfig platformCfgData = self.GetPlatformCfgData(platformId);
			if (platformCfgData != null && platformCfgData.DifficultyId[0] + bossDifficulty > platformCfgData.DifficultyId[1])
			{
				return true;
			}
			return false;
		}

		public static Dictionary<int, HeavenFightShowRewardData> GetShowRewardCfgList(this HeavenFightModule self)
		{
			List<HeavenFightConfig> list = ConfigSingleton<HeavenFightConfigCategory>.Instance.GetList();
			Dictionary<int, HeavenFightShowRewardData> dictionary = new Dictionary<int, HeavenFightShowRewardData>();
			int num = self.Season;
			for (int num2 = num; num2 > 0; num2--)
			{
				if (ConfigSingleton<HeavenFightConfigCategory>.Instance.Contain(num2 * 100 + 1))
				{
					num = num2;
					break;
				}
			}
			foreach (HeavenFightConfig item in list)
			{
				if (item.Season == num && !dictionary.ContainsKey(item.TitleId))
				{
					HeavenFightBossConfig bossCfg = self.GetBossCfg(item.PlatformId, item.DifficultyId);
					if (bossCfg != null)
					{
						HeavenFightShowRewardData value = new HeavenFightShowRewardData
						{
							RewardId = item.ShowRewardId,
							Stats = bossCfg.AddStat
						};
						dictionary.TryAdd(item.TitleId, value);
					}
				}
			}
			return dictionary;
		}

		public static List<HeavenFightHarmConfig> GetHarmCfgList(this HeavenFightModule self)
		{
			List<HeavenFightHarmConfig> list = new List<HeavenFightHarmConfig>();
			int num = self.Season;
			for (int num2 = num; num2 > 0; num2--)
			{
				if (ConfigSingleton<HeavenFightHarmConfigCategory>.Instance.Contain(num2 * 100 + 1))
				{
					num = num2;
					break;
				}
			}
			foreach (HeavenFightHarmConfig item in ConfigSingleton<HeavenFightHarmConfigCategory>.Instance.GetList())
			{
				if (item.Season == num)
				{
					list.Add(item);
				}
			}
			return list;
		}

		public static bool HasGetHurtReward(this HeavenFightModule self, int rewardId)
		{
			if (self.MaxDamageRewardIdList == null)
			{
				return false;
			}
			return self.MaxDamageRewardIdList.Contains(rewardId);
		}

		public static bool HasTitle(this HeavenFightModule self, int titleId)
		{
			List<HeavenFightConfig> platformCfgDataList = self.GetPlatformCfgDataList();
			long id = ((Entity)((Entity)(object)self).LocalPlayer()).Id;
			foreach (HeavenFightConfig item in platformCfgDataList)
			{
				if (item.TitleId == titleId)
				{
					HeavenFightPlatformInfo platformInfo = self.GetPlatformInfo(item.PlatformId);
					if (platformInfo != null && id == platformInfo.OpponentInfo.PlayerId)
					{
						return true;
					}
				}
			}
			return false;
		}
	}
