		public static int GetWeaponId(this Hero self)
		{
			int result = 0;
			int[] jewelryId = self.Config.JewelryId;
			foreach (int num in jewelryId)
			{
				if (ConfigSingleton<ItemConfigCategory>.Instance.Get(num).Type == 9)
				{
					result = num;
					break;
