				{
					return true;
				}
			}
			return false;
		}

		private static bool CheckSingleJewelry(Hero self, int jewelryId)
		{
			bool num = self.IsActiveJewelry(jewelryId);
			self.Jewelrys.TryGetValue(jewelryId, out var value);
			int id = (num ? (jewelryId * 100 + value + 1) : (jewelryId * 100 + value));
			if (!ConfigSingleton<JewelryStarConfigCategory>.Instance.Contain(id) || !ConfigSingleton<ItemConfigCategory>.Instance.Contain(jewelryId))
			{
				return false;
			}
			ItemModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>();
			ET.ConfigBeans.Item[] needItem = ConfigSingleton<JewelryStarConfigCategory>.Instance.Get(id).NeedItem;
			foreach (ET.ConfigBeans.Item item in needItem)
			{
				if (component.CheckItemNumsIsEnough(item.Id, item.Nums))
				{
					return true;
				}
			}
			return false;
		}

		public static (int costItemId, bool hasEnough, long hasCount, int needCount) CheckItemEnough(this Hero self, int jewelryId)
		{
			int jewelryNextStar = self.GetJewelryNextStar(jewelryId);
			int id = jewelryId * 100 + jewelryNextStar;
			if (!ConfigSingleton<JewelryStarConfigCategory>.Instance.Contain(id))
			{
				return (costItemId: 0, hasEnough: false, hasCount: 0L, needCount: 0);
			}
			int item = 0;
			long num = 0L;
			int num2 = 0;
			ET.ConfigBeans.Item[] needItem = ConfigSingleton<JewelryStarConfigCategory>.Instance.Get(id).NeedItem;
			ET.ConfigBeans.Item[] array = needItem;
			foreach (ET.ConfigBeans.Item item2 in array)
			{
				item = item2.Id;
				num = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().GetItemNumsByItemId(item2.Id);
				num2 = item2.Nums;
				if (num >= num2)
				{
					return (costItemId: item, hasEnough: true, hasCount: num, needCount: num2);
				}
			}
			if (needItem != null && needItem.Length > 0)
			{
				item = needItem[0].Id;
			}
			return (costItemId: item, hasEnough: false, hasCount: num, needCount: num2);
		}

