		public static bool CanUpStar(this Hero self, int universalNum = 0)
		{
			int id = self.ConfigId * 100 + self.Star + 1;
			if (!ConfigSingleton<HeroStarConfigCategory>.Instance.Contain(id))
			{
				return false;
			}
			HeroStarConfig heroStarConfig = ConfigSingleton<HeroStarConfigCategory>.Instance.Get(id);
			long itemNumsByItemId = ((Entity)((Entity)SceneHelper.DomainScene((Entity)(object)self)).GetComponent<LocalPlayerComponent>().Player).GetComponent<ItemModule>().GetItemNumsByItemId(self.Config.ItemId);
			if (itemNumsByItemId >= heroStarConfig.CostNum)
			{
				return true;
			}
			if (universalNum > 0)
			{
				int universal = self.Config.Universal;
				if (((Entity)((Entity)((Entity)self).GetParent<HeroModule>()).GetParent<Player>()).GetComponent<ItemModule>().GetItemNumsByItemId(universal) < universalNum)
				{
