		public static void LearnTalent(this Hero self, int talentId, int talentPoint, bool update = true)
		{
			HeroTalentConfig heroTalentConfig = ConfigSingleton<HeroTalentConfigCategory>.Instance.Get(talentId);
			if (self.ActiveTalentNodes == null)
			{
				Dictionary<int, int> dictionary = (self.ActiveTalentNodes = new Dictionary<int, int>());
			}
			self.ActiveTalentNodes[heroTalentConfig.NodeId / 100] = talentId;
			self.TalentPoint = talentPoint;
			if (update)
			{
				((Entity)(object)self).LocalPlayer().UpdateHeroStats(self.ConfigId, StatBagType.Talent);
				self.UpdateSkill();
			}
		}

		public static void ResetTalent(this Hero self, int point, bool update = true)
		{
			self.TalentPoint = point;
			self.ActiveTalentNodes?.Clear();
			if (update)
			{
				((Entity)(object)self).LocalPlayer().UpdateHeroStats(self.ConfigId, StatBagType.Talent);
				self.UpdateSkill();
			}
		}

		public static List<int> UseTalentTemplate(this Hero self, int templateId, int talentPoint)
		{
			HeroTalentTemplateConfig heroTalentTemplateConfig = ConfigSingleton<HeroTalentTemplateConfigCategory>.Instance.Get(templateId);
			if (heroTalentTemplateConfig == null)
			{
				return null;
			}
			if (self.TotalTalentPoint <= 0)
			{
				return null;
			}
			List<int> list = new List<int>();
			self.ResetTalent(talentPoint, update: false);
			int[] nodes = heroTalentTemplateConfig.Nodes;
			foreach (int num in nodes)
			{
				HeroTalentConfig heroTalentConfig = ConfigSingleton<HeroTalentConfigCategory>.Instance.Get(num);
				if (heroTalentConfig == null || self.TalentPoint < heroTalentConfig.Cost)
				{
					break;
				}
				self.TalentPoint -= heroTalentConfig.Cost;
				self.LearnTalent(num, self.TalentPoint, update: false);
				list.Add(num);
			}
			((Entity)(object)self).LocalPlayer().UpdateHeroStats(self.ConfigId, StatBagType.Talent);
			self.UpdateSkill();
			return list;
		}

		public static bool HasActiveTalentInLayer(this Hero self, int layer)
		{
			return self.ActiveTalentNodes?.ContainsKey(layer) ?? false;
		}

		public static bool CanActiveTalent(this Hero self, int talentId)
		{
			if (self.TalentIsActive(talentId) || self.TalentPoint <= 0)
			{
				return false;
			}
			TalentNodeInfo talentNodeInfo = self.GetTalentData().Item1.FirstOrDefault((TalentNodeInfo x) => x.TalentData.NodeId == talentId);
			if (talentNodeInfo == null || self.HasActiveTalentInLayer(talentId / 100))
			{
				return false;
			}
			if (talentNodeInfo.Layer == 1)
			{
				return true;
			}
			return talentNodeInfo.ParentNodes?.Any(self.TalentIsActive) ?? false;
		}

		public static bool TalentParentIsActive(this Hero self, int talentId)
		{
			if (!ConfigSingleton<HeroTalentConfigCategory>.Instance.Contain(talentId))
			{
				return false;
			}
			HeroTalentConfig heroTalentConfig = ConfigSingleton<HeroTalentConfigCategory>.Instance.Get(talentId);
			int num = heroTalentConfig.NodeId / 100;
			if (num == 1)
			{
				return true;
			}
			if (!self.HasActiveTalentInLayer(num - 1))
			{
				return false;
			}
			int id = self.ActiveTalentNodes[num - 1];
			return ConfigSingleton<HeroTalentConfigCategory>.Instance.Get(id).Nodes?.Contains(heroTalentConfig.NodeId) ?? false;
		}

		public static bool TalentIsActive(this Hero self, int nodeId)
		{
			if (self.ActiveTalentNodes == null)
			{
				return false;
			}
			int key = nodeId / 100;
			if (!self.ActiveTalentNodes.TryGetValue(key, out var value))
			{
				return false;
			}
			return ConfigSingleton<HeroTalentConfigCategory>.Instance.Get(value).NodeId == nodeId;
		}

		public static (List<TalentNodeInfo>, Dictionary<int, HashSet<int>>) GetTalentData(this Hero self)
		{
			List<TalentNodeInfo> list = new List<TalentNodeInfo>();
			Dictionary<int, HashSet<int>> dictionary = new Dictionary<int, HashSet<int>>();
			Dictionary<int, List<int>> dictionary2 = new Dictionary<int, List<int>>();
			int num = 1;
			while (true)
			{
				int id = self.ConfigId * 1000 + num;
				if (!ConfigSingleton<HeroTalentConfigCategory>.Instance.Contain(id))
				{
					break;
				}
				HeroTalentConfig heroTalentConfig = ConfigSingleton<HeroTalentConfigCategory>.Instance.Get(id);
				int num2 = heroTalentConfig.NodeId / 100;
				int num3 = heroTalentConfig.NodeId % 100;
				if (heroTalentConfig.Nodes != null)
				{
					int[] nodes = heroTalentConfig.Nodes;
					foreach (int key in nodes)
					{
						if (!dictionary2.TryGetValue(key, out var value))
						{
							value = (dictionary2[key] = new List<int>());
						}
						value.Add(heroTalentConfig.NodeId);
					}
				}
				if (!dictionary.TryGetValue(num2, out var value2))
				{
					value2 = (dictionary[num2] = new HashSet<int>());
				}
				value2.Add(num3);
				list.Add(new TalentNodeInfo
				{
					TalentData = heroTalentConfig,
					Layer = num2,
					Position = num3,
					Hero = self,
					ParentNodes = dictionary2.GetValueOrDefault(heroTalentConfig.NodeId)
				});
				num++;
			}
			return (list, dictionary);
		}

		public static HeroStarConfig GetNextTalentConfig(this Hero self)
		{
			for (int i = self.StarConfig.Id + 1; ConfigSingleton<HeroStarConfigCategory>.Instance.Contain(i); i++)
			{
				HeroStarConfig heroStarConfig = ConfigSingleton<HeroStarConfigCategory>.Instance.Get(i);
				if (heroStarConfig.AddTalentPoint > 0)
				{
					return heroStarConfig;
				}
			}
			return null;
		}
	}
