		public static List<Stat> GetManualStats(this HeroModule self)
		{
			List<Stat> list = new List<Stat>();
			foreach (Hero item in from h in ((Entity)self).Children.Values.OfType<Hero>()
				where h.ManualIsActive
				select h)
			{
				ManualHeroConfig manualHeroConfig = ConfigSingleton<ManualHeroConfigCategory>.Instance.Get(item.ConfigId * 100 + item.ManualLv);
				if (manualHeroConfig?.Stats != null)
				{
					list.AddRange(manualHeroConfig.Stats);
				}
			}
			if (self.ManualRewardMap == null)
			{
				return list;
			}
			int manualTotalLv = self.ManualTotalLv;
			if (manualTotalLv == 0)
			{
				return list;
			}
			for (int num = 0; num <= manualTotalLv; num++)
			{
				if (ConfigSingleton<ManualLevelConfigCategory>.Instance.Contain(num))
				{
					ManualLevelConfig manualLevelConfig = ConfigSingleton<ManualLevelConfigCategory>.Instance.Get(num);
					if (manualLevelConfig?.Stats != null && self.ManualRewardMap.ContainsKey(num))
					{
						list.AddRange(manualLevelConfig.Stats);
					}
				}
			}
			return list;
		}

		public static void AddHeroes(this HeroModule self, L2C_SyncAddHero message)
		{
			if (message.Heroes != null && message.Heroes.Count > 0)
			{
				foreach (HeroInfo hero2 in message.Heroes)
				{
					if (!ConfigSingleton<HeroConfigCategory>.Instance.Contain(hero2.ConfigId))
					{
						Log.Error($"hero config not exist: {hero2.ConfigId}");
						continue;
					}
					Hero hero = ((Entity)self).GetParent<Player>().GetHero(hero2.ConfigId);
					if (self.ConfigIdToHeroId.ContainsKey(hero2.ConfigId))
					{
						((DisposeObject)hero).Dispose();
						self.ConfigIdToHeroId.Remove(hero2.ConfigId);
					}
					((Entity)self).GetParent<Player>().CreateHero(hero2.ConfigId, hero2.Id)?.Active(hero2);
				}
				self.RelatesDirty = true;
			}
			Singleton<EventSystem>.Instance.Publish<EventSyncAddHero>(SceneHelper.DomainScene((Entity)(object)self), new EventSyncAddHero
			{
				Heroes = message.Heroes,
				Fragments = message.Fragments,
				Reason = message.Reason
			});
		}

		public static List<Hero> GetHeroes(this Player player, HeroSearch? search = null)
		{
			return ((Entity)player).GetComponent<HeroModule>().GetHeroes(search);
		}

		public static List<Hero> GetHeroes(this HeroModule self, HeroSearch? search = null)
		{
			if (!self.IsInit)
			{
				foreach (KeyValuePair<int, HeroConfig> item in ConfigSingleton<HeroConfigCategory>.Instance.GetAll())
				{
					((Entity)self).GetParent<Player>().GetHero(item.Value.Id, createEntity: true);
				}
				self.IsInit = true;
			}
			List<Hero> list = new List<Hero>();
			Dictionary<long, Entity>.ValueCollection values = ((Entity)self).Children.Values;
			if (!search.HasValue)
			{
				search = new HeroSearch
				{
					Includes = HeroInclude.Hero
				};
			}
			else if (search.Value.Includes == HeroInclude.Default)
			{
				search = new HeroSearch
				{
					Includes = HeroInclude.Hero,
					Job = search.Value.Job,
					SortType = search.Value.SortType,
					OnlyActive = search.Value.OnlyActive,
					Filter = search.Value.Filter
				};
			}
			foreach (Hero item2 in values)
			{
				if (search.Value.Includes.HasFlag((HeroInclude)(1 << item2.Config.Type - 1)) && (search.Value.Job == 0 || item2.Config.Job == search.Value.Job) && (!search.Value.OnlyActive || item2.IsActive) && (search.Value.Filter == null || search.Value.Filter(((Entity)item2).Id)))
				{
					list.Add(item2);
				}
			}
			list.Sort(delegate(Hero a, Hero b)
			{
				switch (search.Value.SortType)
				{
				case HeroSortType.HeroList:
				{
					bool flag = a.CanActive() && !a.IsActive;
					bool flag2 = b.CanActive() && !b.IsActive;
					if (flag != flag2)
					{
						return flag2.CompareTo(flag);
					}
					if (a.IsActive != b.IsActive)
					{
						return b.IsActive.CompareTo(a.IsActive);
					}
					if (a.GetPower() != b.GetPower())
					{
						return b.GetPower().CompareTo(a.GetPower());
					}
					if (a.Config.HeroQuality != b.Config.HeroQuality)
					{
						return b.Config.HeroQuality.CompareTo(a.Config.HeroQuality);
					}
					if (a.Star != b.Star)
					{
						return b.Star.CompareTo(a.Star);
					}
					return a.Config.Id.CompareTo(b.Config.Id);
				}
				case HeroSortType.VibesHeroList:
					if (a.ConfigId == 1 != (b.ConfigId == 1))
					{
						return (b.ConfigId == 1).CompareTo(a.ConfigId == 1);
					}
					if (a.IsFormation() != b.IsFormation())
					{
						return b.IsFormation().CompareTo(a.IsFormation());
					}
					if (a.IsActive != b.IsActive)
					{
						return b.IsActive.CompareTo(a.IsActive);
					}
					if (a.Config.HeroQuality != b.Config.HeroQuality)
					{
						return b.Config.HeroQuality.CompareTo(a.Config.HeroQuality);
					}
					return a.Config.Id.CompareTo(b.Config.Id);
				case HeroSortType.Manual:
					if (a.Config.HeroQuality != b.Config.HeroQuality)
					{
						return b.Config.HeroQuality.CompareTo(a.Config.HeroQuality);
					}
					if (a.Config.IsCore != b.Config.IsCore)
					{
						return b.Config.IsCore.CompareTo(a.Config.IsCore);
					}
					return a.Config.Id.CompareTo(b.Config.Id);
				default:
					return a.Config.Id.CompareTo(b.Config.Id);
				}
			});
			return list;
		}

		public static int CanOneKeyUpStar(this HeroModule self)
		{
			if (((Entity)((Entity)self).GetParent<Player>()).GetComponent<PrivilegeModule>().GetValue(PrivilegeType.HeroOneKeyUpStar) == 0)
			{
				return 200349;
			}
			bool flag = false;
			foreach (Hero item in ((Entity)self).Children.Values.Cast<Hero>())
			{
				if (item.IsActive && item.CanUpStar())
				{
					flag = true;
					break;
				}
			}
			if (flag)
			{
				return 0;
			}
			return 200346;
		}

		public static List<RelateInfo> GetRelateInfos(this HeroModule self)
		{
			if (self.RelateInfos == null)
			{
				self.InitAllRelates();
			}
			List<RelateInfo> list = self.RelateInfos.Values.ToList();
			list.Sort(delegate(RelateInfo a, RelateInfo b)
			{
				bool flag = self.RelateHasAward(a.RelateId);
				bool flag2 = self.RelateHasAward(b.RelateId);
				if (flag != flag2)
				{
					if (!flag)
					{
						return 1;
					}
					return -1;
				}
				return (!a.IsActive != !b.IsActive) ? (a.IsActive ? 1 : (-1)) : 0;
			});
			return list;
		}

		private static void InitAllRelates(this HeroModule self)
		{
			self.RelateInfos = new Dictionary<int, RelateInfo>();
			foreach (KeyValuePair<int, RelateConfig> item in ConfigSingleton<RelateConfigCategory>.Instance.GetAll())
			{
				RelateStarConfig relateStarConfig = ConfigSingleton<RelateStarConfigCategory>.Instance.Get(item.Value.Id * 100 + 2);
				self.RelateInfos[item.Value.Id] = new RelateInfo
				{
					RelateId = item.Value.Id,
					IsActive = false,
					ActiveHeroes = new Dictionary<int, int>(),
					Star = 0,
					NextStarNeedCount = item.Value.Heros.Length,
					NextStarNeedStar = (relateStarConfig?.NeedStar ?? 0)
				};
			}
			foreach (Hero item2 in from h in ((Entity)self).Children.Values.OfType<Hero>()
				where h.IsActive && h.Config.RelateId != null
				select h)
			{
				self.UpdateHeroRelates(item2, isInit: true);
			}
		}

		public static void UpdateHeroRelates(this HeroModule self, Hero hero, bool isInit = false)
		{
			if (hero.Config.RelateId == null)
			{
				return;
			}
			if (self.RelateInfos == null)
			{
				self.InitAllRelates();
			}
			int[] relateId = hero.Config.RelateId;
			foreach (int num in relateId)
			{
				RelateConfig relateConfig = ConfigSingleton<RelateConfigCategory>.Instance.Get(num);
				if (relateConfig == null || !self.RelateInfos.TryGetValue(num, out var value))
				{
					continue;
				}
				int valueOrDefault = value.ActiveHeroes.GetValueOrDefault(hero.ConfigId);
				value.ActiveHeroes[hero.ConfigId] = hero.Star;
				if (!relateConfig.Heros.All((int id) => self.GetHero(id)?.IsActive ?? false))
				{
					ResetRelateInfo(value, relateConfig.Heros.Length);
					continue;
				}
				bool isActive = value.IsActive;
				value.IsActive = true;
				int minHeroStar = value.ActiveHeroes.Values.Min();
				int num2 = CalculateMaxAchievableStar(num, minHeroStar);
				if (!isActive || num2 != value.Star || (hero.Star > valueOrDefault && hero.Star >= value.NextStarNeedStar))
				{
					UpdateRelateInfoStar(value, num, num2);
					if (!isInit)
					{
						self.Player.UpdateTeamStats(StatBagType.Relate);
					}
				}
			}
		}

		public static bool RelateHasAward(this HeroModule self, int relateId)
		{
			if (!self.RelateInfos.TryGetValue(relateId, out var value) || !value.IsActive)
			{
				return false;
			}
			int num = self.RelateRewardStatus?.GetValueOrDefault(relateId, 0) ?? 0;
			for (int i = 1; ConfigSingleton<RelateStarConfigCategory>.Instance.Contain(relateId * 100 + i); i++)
			{
				if (value.Star >= i && (num & (1 << i - 1)) == 0)
				{
					return true;
				}
			}
			return false;
		}

		public static void GetRelateStat(this HeroModule self, StatList statList)
		{
			if (self.RelateInfos == null)
			{
				self.InitAllRelates();
			}
			foreach (RelateInfo item in self.RelateInfos.Values.Where((RelateInfo r) => r.IsActive))
			{
				if (item.Star == 0)
				{
					Log.Error($"羁绊{item.RelateId}星级为0，请检查");
				}
				RelateStarConfig relateStarConfig = ConfigSingleton<RelateStarConfigCategory>.Instance.Get(item.RelateId * 100 + item.Star);
				if (relateStarConfig?.Stats != null)
				{
					statList.AddRange(relateStarConfig.Stats);
				}
			}
		}

		public static List<Stat> GetRelateStatViewInfos(this HeroModule self)
		{
			if (self.RelateInfos == null)
			{
				self.InitAllRelates();
			}
			List<Stat> list = new List<Stat>();
			foreach (RelateInfo item in self.RelateInfos.Values.Where((RelateInfo r) => r.IsActive))
			{
				RelateStarConfig relateStarConfig = ConfigSingleton<RelateStarConfigCategory>.Instance.Get(item.RelateId * 100 + item.Star);
				if (relateStarConfig?.Stats != null)
				{
					list.AddRange(relateStarConfig.Stats);
				}
			}
			return list;
		}

		private static void ResetRelateInfo(RelateInfo info, int heroCount)
		{
			info.IsActive = false;
			info.Star = 0;
			info.NextStarNeedCount = heroCount;
		}

		private static void UpdateRelateInfoStar(RelateInfo info, int relateId, int newStar)
		{
			info.Star = newStar;
			if (!info.IsMaxStar)
			{
				RelateStarConfig nextStarConfig = ConfigSingleton<RelateStarConfigCategory>.Instance.Get(relateId * 100 + (newStar + 1));
				info.NextStarNeedStar = nextStarConfig?.NeedStar ?? 0;
				info.NextStarNeedCount = ((nextStarConfig != null) ? info.ActiveHeroes.Count((KeyValuePair<int, int> x) => x.Value < nextStarConfig.NeedStar) : 0);
			}
			else
			{
				info.NextStarNeedStar = 0;
				info.NextStarNeedCount = 0;
			}
		}

		private static int CalculateMaxAchievableStar(int relateId, int minHeroStar)
		{
			int i;
			for (i = 1; ConfigSingleton<RelateStarConfigCategory>.Instance.Contain(relateId * 100 + (i + 1)); i++)
			{
				RelateStarConfig relateStarConfig = ConfigSingleton<RelateStarConfigCategory>.Instance.Get(relateId * 100 + (i + 1));
				if (minHeroStar < relateStarConfig.NeedStar)
				{
					break;
				}
			}
			return i;
		}

		public static bool IsGetAllAward(this HeroModule self, int recId)
		{
			HeroRecFormationConfig heroRecFormationConfig = ConfigSingleton<HeroRecFormationConfigCategory>.Instance.Get(recId);
			if (heroRecFormationConfig == null)
			{
				return false;
			}
			if (self.RecommendFormStatus == null)
			{
				return false;
			}
			if (self.RecommendFormStatus.TryGetValue(recId, out var value) && value >= heroRecFormationConfig.HeroIds.Length - 1)
			{
				return true;
			}
			return false;
		}

		public static bool RecommendFormHasAwardWithId(this HeroModule self, int recId)
		{
			HeroRecFormationConfig heroRecFormationConfig = ConfigSingleton<HeroRecFormationConfigCategory>.Instance.Get(recId);
			if (heroRecFormationConfig == null)
			{
				return false;
			}
			int num = 0;
			new List<int>();
			foreach (int item in heroRecFormationConfig.HeroIds.Skip(1).ToList())
			{
				Hero hero = self.GetHero(item);
				if (hero != null && hero.IsActive)
				{
					num++;
				}
			}
			if (self.RecommendFormStatus == null)
			{
				return num > 0;
			}
			if (self.RecommendFormStatus.TryGetValue(recId, out var value))
			{
				if (num > value)
				{
					return true;
				}
				return false;
			}
			return num > 0;
		}

		public static int GetActiveHeroCount(this HeroModule self, int recId)
		{
			if (self.RecommendFormStatus == null)
			{
				return 0;
			}
			if (!self.RecommendFormStatus.TryGetValue(recId, out var value))
			{
				return 0;
			}
			return value;
		}

		public static bool RecommendFormHasAward(this HeroModule self)
		{
			foreach (var (recId, _) in ConfigSingleton<HeroRecFormationConfigCategory>.Instance.GetAll())
			{
				if (self.RecommendFormHasAwardWithId(recId))
				{
					return true;
				}
			}
			return false;
		}
	}
