		public static bool IsShow(this ImmortalOfficialModule self)
		{
			if (!((Entity)(object)self).LocalPlayer().CheckAllConds(self.ActivityData.Condition?.ToArray()))
			{
				return false;
			}
			long startTime = self.ActivityData.StartTime;
			long endTime = self.ActivityData.EndTime;
			long num = TimeHelper.Now();
			if (startTime <= num)
			{
				return endTime >= num;
			}
			return false;
		}

