		}

		public static int GetPlayerState(this ImmortalOfficialModule self, long playerId)
		{
			return self.PlayerState.GetValueOrDefault(playerId, -1);
		}

		public static void UpdatePlayerState(this ImmortalOfficialModule self, List<RankInfo> rankInfos)
		{
			if (rankInfos == null)
			{
				return;
			}
			self.PlayerState.Clear();
			ImmortalOfficialConfig curStageConfig = self.GetCurStageConfig();
			ImmortalOfficialConfig immortalOfficialConfig = ConfigSingleton<ImmortalOfficialConfigCategory>.Instance.Get(curStageConfig.Id + 1);
			int num = curStageConfig.Promoted;
			int downRank = ImmortalOfficialHelper.GetDownRank(rankInfos.Count, curStageConfig, self.CrossStagePlayerIdList.Count);
			foreach (RankInfo rankInfo in rankInfos)
			{
				long id = rankInfo.Id;
				if (self.CrossStagePlayerIdList.Contains(id))
				{
					self.PlayerState[id] = 1;
					if (immortalOfficialConfig == null)
					{
						self.PlayerState[id] = 3;
					}
				}
				else if (num > 0)
				{
					self.PlayerState[id] = 2;
					if (immortalOfficialConfig == null)
					{
						self.PlayerState[id] = 3;
					}
					num--;
				}
				else if (rankInfo.RankNo >= downRank)
				{
					self.PlayerState[id] = 4;
				}
				else
				{
					self.PlayerState[id] = 3;
				}
			}
		}
	}
