				Hero hero2 = ((Entity)(object)self).LocalPlayer().GetHero(heroByGear[1]);
				if (num == 0)
				{
					flag2 = hero2.IsActive;
					flag = hero.IsActive;
					if (flag2 & flag)
					{
						return self.CurrentGear <= num;
					}
					return false;
				}
				if (num > id)
				{
					return true;
				}
				KismetFetterGearConfig kismetFetterGearConfig = ((maxConfig.Id == num) ? maxConfig : ConfigSingleton<KismetFetterGearConfigCategory>.Instance.GetConfigByGear(self.GetActivityId(), num));
				flag = hero.Star >= kismetFetterGearConfig.Gear;
				flag2 = hero2.Star >= kismetFetterGearConfig.Gear;
				bool flag3 = flag & flag2;
				if ((id <= num) & flag3)
				{
					return self.CurrentGear < num;
				}
				return false;
			}
			return false;
		}

