					6 => (startIndex: 0, endIndex: 1), 
					5 => (startIndex: 0, endIndex: 3), 
					4 => (startIndex: 0, endIndex: 7), 
					_ => (startIndex: 0, endIndex: -1), 
				};
			}
			switch (schedule)
			{
			case 1:
			{
				int num3 = groupIndex * 8;
				return (startIndex: num3, endIndex: num3 + 7);
			}
			case 2:
			{
				int num2 = groupIndex * 4;
				return (startIndex: num2, endIndex: num2 + 3);
			}
			case 3:
			{
				int num = groupIndex * 2;
				return (startIndex: num, endIndex: num + 1);
