		public static bool IsActivityRankShowMoreOneDay(this LegendShowModule self)
		{
			LegendShowBaseConfig config = ConfigSingleton<LegendShowBaseConfigCategory>.Instance.GetConfig(self.ActivityData.ActivityId, 0);
			if (config == null)
			{
				return false;
			}
			if (config.IsShowRankOneDay && self.ActivityData.EndTime - TimeHelper.Now() <= 86400000)
			{
				return true;
			}
			return false;
		}

		public static int RedCount(this LegendShowModule self)
		{
			return 0 + self.GetPersonRedPoint() + (self.GetAllZoneRedPoint() ? 1 : 0) + (self.GetItemRewardCount() ? 1 : 0);
		}

		private static int GetPersonRedPoint(this LegendShowModule self)
		{
			if (self.StageScoreDict == null)
			{
				return 0;
			}
			int currentStage = self.GetCurrentStage();
			for (int i = 1; i <= currentStage; i++)
			{
				List<LegendShowStageConfig> stageConfigs = ConfigSingleton<LegendShowStageConfigCategory>.Instance.GetStageConfigs(self.ActivityData.ActivityId, i);
				stageConfigs = stageConfigs.FindAll((LegendShowStageConfig c) => c.Zone != 2);
				self.StageScoreDict.TryGetValue(i, out var value);
				if (value == 0L)
				{
					continue;
				}
				foreach (LegendShowStageConfig item in stageConfigs)
				{
					if (!self.IsGet(item.Id) && item.Score <= value)
					{
						return 1;
					}
				}
			}
			return 0;
		}

		private static bool GetAllZoneRedPoint(this LegendShowModule self)
		{
			if (self.ActivityData.BaseInfo.SubType >= 20000)
			{
				return false;
			}
			if (self.ActivityData.BaseInfo.CrossType == 0)
			{
				return false;
			}
