		public static int GetMailMax(this MailModule self)
		{
			return ConfigSingleton<GlobalConfigCategory>.Instance.GetOne().MailMaxCount;
		}

		public static Dictionary<long, MailInfo> GetMails(this MailModule self)
		{
			return self.Mails;
		}

		public static void AddNewMail(this MailModule self, L2C_AddMail message)
		{
			MailInfo mail = message.Mail;
			if (mail != null)
			{
				self.AddMail(mail);
				self.IsExistNewMail = true;
			}
		}

		public static void ResMailList(this MailModule self, L2C_MailList message)
		{
			if (message.IsNew)
			{
				self.IsExistNewMail = true;
			}
			if (self.Mails == null)
			{
				self.Mails = new Dictionary<long, MailInfo>();
			}
			else
			{
				self.Mails.Clear();
			}
			if (message.Mails == null)
			{
				return;
			}
			foreach (var (_, mailInfo2) in message.Mails)
			{
				self.AddMail(mailInfo2);
			}
		}

		private static void AddMail(this MailModule self, MailInfo mailInfo)
		{
