		private static void OnGetReward(this MusicMovementModule self, int configId)
		{
			Dictionary<int, MusicMovementRewardConfig> dictionary = ConfigSingleton<MusicMovementRewardConfigCategory>.Instance.GetDictionary(self.ActivityData.ActivityId);
			if (dictionary == null)
