				return;
			}
			if (!dictionary.ContainsKey(configId))
			{
				Log.Error("没有配置MusicMovementRewardConfig？？" + configId);
				return;
			}
			if (dictionary[configId].Type == 1)
			{
				self.LineGetStatus |= 1L << configId;
			}
			if (dictionary[configId].Type == 2)
			{
				self.ColumnStatus |= 1L << configId;
			}
		}

