		public static void OnTaskChange(this MusicMovementModule self, Dictionary<int, MusicMovementTaskInfo> taskList)
		{
			if (taskList == null)
			{
				return;
			}
			foreach (KeyValuePair<int, MusicMovementTaskInfo> task in taskList)
			{
				var (configId, musicMovementTaskInfo2) = task;
				MusicMovementTaskConfig musicMovementTaskConfig = ConfigSingleton<MusicMovementTaskConfigCategory>.Instance.Get(configId);
				if (musicMovementTaskConfig != null)
				{
					int actId = musicMovementTaskConfig.ActId;
					if (!self.TaskList.TryGetValue(actId, out var value))
					{
						value = new List<MusicMovementTaskData>();
						self.TaskList.Add(actId, value);
					}
					MusicMovementTaskData musicMovementTaskData = self.TaskList[actId].Find((MusicMovementTaskData m) => m.Id == configId);
					if (musicMovementTaskData == null)
					{
						musicMovementTaskData = new MusicMovementTaskData
						{
							Id = configId
						};
						self.TaskList[actId].Add(musicMovementTaskData);
					}
					musicMovementTaskData.Count = musicMovementTaskInfo2.Count;
					musicMovementTaskData.Status = musicMovementTaskInfo2.Status;
					musicMovementTaskData.Stage = musicMovementTaskInfo2.Stage;
					if (musicMovementTaskData.Status == 1)
					{
						self.CardTaskStatus |= 1L << configId;
						Singleton<EventSystem>.Instance.Publish<MusicMovementChange_Success>(SceneHelper.DomainScene((Entity)(object)self), new MusicMovementChange_Success
						{
							ActId = self.ActivityData.ActivityId
						});
					}
				}
			}
		}

		public static void UpdateTask(this MusicMovementModule self, List<MusicMovementTaskInfo> infoList)
		{
			for (int i = 0; i < infoList.Count; i++)
			{
				MusicMovementTaskInfo musicMovementTaskInfo = infoList[i];
				MusicMovementTaskData taskData = self.GetTaskData(musicMovementTaskInfo.ConfigId);
				if (taskData != null)
				{
					taskData.Count = musicMovementTaskInfo.Count;
					taskData.Status = musicMovementTaskInfo.Status;
					taskData.Stage = musicMovementTaskInfo.Stage;
					if (taskData.Status == 1)
					{
						self.CardTaskStatus |= 1L << musicMovementTaskInfo.ConfigId;
						Singleton<EventSystem>.Instance.Publish<MusicMovementChange_Success>(SceneHelper.DomainScene((Entity)(object)self), new MusicMovementChange_Success
						{
							ActId = self.ActivityData.ActivityId
						});
						Singleton<EventSystem>.Instance.Publish<MusicMovementChange_TaskOver>(SceneHelper.DomainScene((Entity)(object)self), new MusicMovementChange_TaskOver
						{
							ActId = self.ActivityData.ActivityId,
							ConfigId = musicMovementTaskInfo.ConfigId
						});
					}
				}
			}
		}

