		public static bool IsCompleteAllTask(this MusicMovementModule self, int musicId)
		{
			Dictionary<int, MusicMovementCardConfig> dictionary = ConfigSingleton<MusicMovementCardConfigCategory>.Instance.GetDictionary(self.ActivityData.ActivityId);
			if (dictionary == null)
			{
				Log.Error("没有MusicMovementCardConfig");
				return false;
			}
			foreach (MusicMovementCardConfig value in dictionary.Values)
			{
				if (value.MusicId == musicId && !self.IsCompleteTask(value.TaskID))
				{
					return false;
				}
			}
			return true;
		}

		public static bool IsShowRed(this MusicMovementModule self, int musicId)
		{
			Dictionary<int, MusicMovementActConfig> dictionary = ConfigSingleton<MusicMovementActConfigCategory>.Instance.GetDictionary(self.ActivityData.ActivityId);
			if (dictionary == null)
			{
				Log.Error("没有配 MusicMovementActConfig？");
				return false;
			}
			if (!dictionary.ContainsKey(musicId))
			{
				Log.Error("没有配 MusicMovementActConfig？");
				return false;
			}
			Dictionary<int, MusicMovementRewardConfig> dictionary2 = ConfigSingleton<MusicMovementRewardConfigCategory>.Instance.GetDictionary(self.ActivityData.ActivityId);
			if (dictionary2 == null)
			{
