				return false;
			}
			Dictionary<int, MusicMovementCardConfig> dictionary3 = ConfigSingleton<MusicMovementCardConfigCategory>.Instance.GetDictionary(self.ActivityData.ActivityId);
			if (dictionary3 == null)
			{
				Log.Error("没有配 MusicMovementCardConfig？");
				return false;
			}
			foreach (MusicMovementCardConfig value in dictionary3.Values)
			{
				if (value.MusicId == musicId && self.IsCompleteTask(value.TaskID) && !self.IsGetThisCard(value.TaskID))
				{
					return true;
				}
			}
			foreach (MusicMovementRewardConfig value2 in dictionary2.Values)
			{
				if (value2.MusicId != musicId)
				{
					continue;
				}
				int num = value2.Tap[0];
				if (value2.Type == 1)
				{
					int num2 = dictionary[musicId].Count;
					foreach (MusicMovementCardConfig value3 in dictionary3.Values)
					{
						if (value2.MusicId == value3.MusicId && value2.ActId == value3.ActId && value3.Id == num && self.IsCompleteTask(value3.TaskID))
						{
							num++;
							if (!self.IsGetThisCard(value3.TaskID))
							{
								return true;
							}
							num2--;
						}
						if (num2 == 0 && !self.IsGetBigReward(value2.Id))
						{
							return true;
						}
					}
				}
				if (value2.Type != 2)
				{
