			{
				((Entity)unit2).GetComponent<UnitInfoComponent>();
				if (unit2.GetCamp() == 1 && ((Entity)unit2).GetComponent<AIComponent>() == null)
				{
					((Entity)unit2).GetComponent<BuffComponent>().RemoveBuffByGroup(buffConfig.Group);
					((Entity)unit2).AddComponent<AIComponent, int>((int)unit2.Config.AI, false);
				}
			}
			Unit unit = self.GetUnit(newbieDupScriptConfig.MonsterId);
