			{
				if (unit.GetMonsterId() == monsterId)
				{
					return unit;
				}
			}
			return null;
		}

		public static Unit GetUnit(this NewbieSpawnComponent self)
		{
			if (self.Units.Count == 0)
			{
				return null;
			}
			return self.Units[0];
		}

