		private static void OnGetReward(this OnLineRewardModule self, int day)
		{
			self.DayGet |= 1 << day;
		}

		private static void ReSetData(this OnLineRewardModule self)
		{
			self.DayGet = 0;
			self.OnlineTime = 0L;
		}

		public static bool IsGetReward(this OnLineRewardModule self, int day)
		{
			return (self.DayGet & (1 << day)) != 0;
		}

		public static int GetReward(this OnLineRewardModule self)
		{
			return self.DayGet;
		}

		public static bool GetTimerStatus(this OnLineRewardModule self)
		{
			return self.SetTimer;
		}

		public static long GetOnlineTime(this OnLineRewardModule self)
		{
			return self.OnlineTime;
		}

		public static void SetTimerStatus(this OnLineRewardModule self, bool value)
		{
			self.SetTimer = value;
		}

		public static long GetLongTimer(this OnLineRewardModule self)
		{
			Dictionary<int, OnLineRewardConfig> dictionary = ConfigSingleton<OnLineRewardConfigCategory>.Instance.GetDictionary(self.ActivityData.ActivityId);
			if (dictionary == null)
			{
				Log.Error("没有配置OnLineRewardConfig");
				return 0L;
			}
			int num = TimeHelper.DaysBetween(self.ActivityData.StartTime, TimeHelper.ServerNow(), 18000000L);
			long result = 0L;
			foreach (OnLineRewardConfig value in dictionary.Values)
			{
				if (value.Day == num && self.OnlineTime < value.Time && !self.IsGetReward(value.Index))
				{
					result = value.Time - self.OnlineTime;
				}
			}
			return result;
		}

		public static bool IsShowRed(this OnLineRewardModule self)
		{
			Dictionary<int, OnLineRewardConfig> dictionary = ConfigSingleton<OnLineRewardConfigCategory>.Instance.GetDictionary(self.ActivityData.ActivityId);
			if (dictionary == null)
			{
				Log.Error("没有配置OnLineRewardConfig");
				return false;
			}
			int num = TimeHelper.DaysBetween(self.ActivityData.StartTime, TimeHelper.ServerNow(), 18000000L);
			foreach (OnLineRewardConfig value in dictionary.Values)
			{
				if (value.Day == num && self.OnlineTime >= value.Time && !self.IsGetReward(value.Index))
				{
					return true;
				}
			}
			return false;
		}
	}
