		public static bool IsClose(this PushGiftModule self)
		{
			List<PushGiftData> pushGiftList = self.GetPushGiftList();
			if (pushGiftList != null)
			{
				return pushGiftList.Count == 0;
			}
			return true;
		}

		public static List<PushGiftData> GetPushGiftList(this PushGiftModule self)
		{
			if (self.GiftDataDict == null)
			{
				return null;
			}
			List<PushGiftData> list = new List<PushGiftData>();
			foreach (PushGiftData value in self.GiftDataDict.Values)
			{
				if (value.EndTime >= TimeHelper.Now() && ConfigSingleton<PushGiftConfigCategory>.Instance.Get(value.Id) != null)
				{
					list.Add(value);
				}
			}
			list.Sort(delegate(PushGiftData a, PushGiftData b)
			{
				int num = a.SortOrder.CompareTo(b.SortOrder);
				return (num != 0) ? num : a.EndTime.CompareTo(b.EndTime);
			});
			return list;
		}

		public static void OnReward(this PushGiftModule self, int giftId)
		{
			int key = giftId / 100;
			PushGiftData valueOrDefault = self.GiftDataDict.GetValueOrDefault(key);
			if (valueOrDefault != null)
			{
				if (valueOrDefault.Id == giftId)
				{
					self.GiftDataDict.Remove(key);
				}
				Singleton<EventSystem>.Instance.Publish<OnPushGiftReward>(SceneHelper.DomainScene((Entity)(object)self), new OnPushGiftReward
				{
					GiftId = giftId
				});
			}
		}

		public static long GetShowTime(this PushGiftModule self)
		{
			if (self.GiftDataDict == null || self.GiftDataDict.Count == 0)
			{
				return 0L;
			}
			Dictionary<int, PushGiftData> dictionary = new Dictionary<int, PushGiftData>();
			foreach (var (key, pushGiftData2) in self.GiftDataDict)
			{
				if (ConfigSingleton<PushGiftConfigCategory>.Instance.Get(pushGiftData2.Id) != null)
				{
					dictionary.Add(key, pushGiftData2);
				}
			}
			return dictionary.Values.Min((PushGiftData gift) => gift.EndTime);
		}

		public static void OnSyncPushGift(this PushGiftModule self, L2C_SyncPushGift message)
		{
			if (message == null)
			{
				return;
			}
			int num = 0;
			if (self.GiftDataDict == null)
			{
				Dictionary<int, PushGiftData> dictionary = (self.GiftDataDict = new Dictionary<int, PushGiftData>());
			}
			if (message.PushGifts != null)
			{
				foreach (PushGiftData pushGift in message.PushGifts)
				{
					int num2 = pushGift.Id / 100;
					if (self.GiftDataDict.ContainsKey(num2))
					{
						self.GiftDataDict[num2] = pushGift;
						continue;
					}
					self.GiftDataDict.TryAdd(num2, pushGift);
					Log.Info($"OnSyncPushGift == {num2}");
					num = num2;
				}
			}
			if (message.ExpiredPushGifts != null)
			{
				foreach (int expiredPushGift in message.ExpiredPushGifts)
				{
					self.GiftDataDict.Remove(expiredPushGift);
				}
			}
			self.NewPushGift = num;
			Singleton<EventSystem>.Instance.Publish<OnPushGiftRefresh>(SceneHelper.DomainScene((Entity)(object)self), new OnPushGiftRefresh
			{
				PushGiftTypeId = num
			});
		}

		public static void OnSyncPushGiftShow(this PushGiftModule self, int pushGiftTypeId)
		{
			self.NewPushGift = pushGiftTypeId;
			Singleton<EventSystem>.Instance.Publish<OnPushGiftShow>(SceneHelper.DomainScene((Entity)(object)self), new OnPushGiftShow
			{
				PushGiftTypeId = pushGiftTypeId
			});
		}

		public static bool IsNewGiftWithinDisplayLimit(this PushGiftModule self, int pushGiftTypeId)
		{
			List<PushGiftData> pushGiftList = self.GetPushGiftList();
			if (pushGiftList == null || pushGiftList.Count == 0)
			{
				return false;
			}
			int pushGiftMaxCount = ConfigSingleton<GlobalConfigCategory>.Instance.GetOne().PushGiftMaxCount;
			for (int i = 0; i < pushGiftList.Count && i < pushGiftMaxCount; i++)
			{
				if (pushGiftList[i].Id / 100 == pushGiftTypeId)
				{
					return true;
				}
			}
			return false;
		}
	}
