			Singleton<EventSystem>.Instance.Publish<RedHeroUpStar_Success>(SceneHelper.DomainScene((Entity)(object)self), default(RedHeroUpStar_Success));
		}

		private static void OnGetAllRewardSuccess(this RedHeroUpStarModule self)
		{
			Dictionary<int, RedHeroUpStarConfig> dictionary = ConfigSingleton<RedHeroUpStarConfigCategory>.Instance.GetDictionary(self.ActivityData.ActivityId);
			if (dictionary == null)
			{
				Log.Error("没有RedHeroUpStarConfig检查一下配置");
				return;
			}
			foreach (RedHeroUpStarConfig value in dictionary.Values)
			{
				if (self.CanGetReward(value.Id))
				{
					self.OnGetReward(value.Id);
				}
			}
		}

		private static void OnGetRewardSuccesee(this RedHeroUpStarModule self, int configId)
		{
			Dictionary<int, RedHeroUpStarConfig> dictionary = ConfigSingleton<RedHeroUpStarConfigCategory>.Instance.GetDictionary(self.ActivityData.ActivityId);
			if (dictionary == null)
			{
				Log.Error("没有RedHeroUpStarConfig检查一下配置");
			}
			else if (!dictionary.ContainsKey(configId))
			{
				Log.Error("没有RedHeroUpStarConfig检查一下配置");
			}
			else
			{
				self.OnGetReward(configId);
			}
		}

		private static void OnGetFreeRewardSuccess(this RedHeroUpStarModule self)
		{
			Dictionary<int, RedHeroUpStarConfig> dictionary = ConfigSingleton<RedHeroUpStarConfigCategory>.Instance.GetDictionary(self.ActivityData.ActivityId);
			if (dictionary == null)
			{
				Log.Error("没有RedHeroUpStarConfig检查一下配置");
				return;
			}
			int myHeroStarCountByQuality = ((Entity)(object)self).LocalPlayer().GetMyHeroStarCountByQuality(6);
			foreach (RedHeroUpStarConfig value in dictionary.Values)
			{
				if (myHeroStarCountByQuality >= value.Need)
				{
					self.OnGetFree(value.Id);
				}
			}
		}

		private static void OnGetFree(this RedHeroUpStarModule self, int configId)
		{
			self.FreeGet = configId;
		}

		private static void OnCanGetReward(this RedHeroUpStarModule self, int configId)
		{
			self.RewardGet |= 1L << configId;
		}

		private static void OnGetReward(this RedHeroUpStarModule self, int configId)
		{
			self.RewardGet &= ~(1L << configId);
		}

		private static void OnBuySuccess(this RedHeroUpStarModule self, int configId)
		{
			if (!self.GiftState.ContainsKey(configId))
			{
				self.GiftState.Add(configId, 0);
			}
			self.GiftState[configId]++;
		}

		public static bool CanGetReward(this RedHeroUpStarModule self, int configId)
		{
			return (self.RewardGet & (1L << configId)) != 0;
		}

		private static bool CanGetFreeReward(this RedHeroUpStarModule self, int configId)
		{
			return (self.FreeGet & (1L << configId)) == 0;
		}

		public static int GetBuyCount(this RedHeroUpStarModule self, int configId)
		{
			if (self.GiftState.ContainsKey(configId))
			{
				return self.GiftState[configId];
			}
			return 0;
		}

		public static bool CanGet(this RedHeroUpStarModule self)
		{
			Dictionary<int, RedHeroUpStarConfig> dictionary = ConfigSingleton<RedHeroUpStarConfigCategory>.Instance.GetDictionary(self.ActivityData.ActivityId);
			if (dictionary == null)
			{
				return false;
			}
			int myHeroStarCountByQuality = ((Entity)(object)self).LocalPlayer().GetMyHeroStarCountByQuality(6);
			long itemNumsByItemId = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().GetItemNumsByItemId(99);
			foreach (RedHeroUpStarConfig value in dictionary.Values)
			{
				if (myHeroStarCountByQuality >= value.Need)
				{
					if (self.CanGetReward(value.Id))
					{
						return true;
					}
					if (value.Id > self.FreeGet)
					{
						return true;
					}
					if (value.JadePrize > 0 && itemNumsByItemId >= value.JadePrize && self.CanGetReward(value.Id))
					{
						return true;
					}
				}
			}
			return false;
		}

		public static bool Red(this RedHeroUpStarModule self)
		{
			Dictionary<int, RedHeroUpStarConfig> dictionary = ConfigSingleton<RedHeroUpStarConfigCategory>.Instance.GetDictionary(self.ActivityData.ActivityId);
			if (dictionary == null)
			{
				return false;
			}
			int myHeroStarCountByQuality = ((Entity)(object)self).LocalPlayer().GetMyHeroStarCountByQuality(6);
			long itemNumsByItemId = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().GetItemNumsByItemId(99);
			foreach (RedHeroUpStarConfig value in dictionary.Values)
			{
				if (myHeroStarCountByQuality >= value.Need)
				{
					if (self.CanGetReward(value.Id))
					{
						return true;
					}
					if (value.Id > self.FreeGet)
					{
						return true;
					}
					if (value.JadePrize > 0 && itemNumsByItemId >= value.JadePrize && self.GetBuyCount(value.Id) < value.LimitNum)
					{
						return true;
					}
				}
			}
			return false;
		}

		public static bool IsBuyOver(this RedHeroUpStarModule self, int gift = 0)
		{
			if (gift > 0)
			{
				return self.GiftState.ContainsKey(gift);
			}
			Dictionary<int, RedHeroUpStarConfig> dictionary = ConfigSingleton<RedHeroUpStarConfigCategory>.Instance.GetDictionary(self.ActivityData.ActivityId);
			if (dictionary == null)
			{
				return false;
			}
			int myHeroStarCountByQuality = ((Entity)(object)self).LocalPlayer().GetMyHeroStarCountByQuality(6);
			if (myHeroStarCountByQuality == 0)
			{
				return false;
			}
			foreach (RedHeroUpStarConfig value in dictionary.Values)
			{
				if (myHeroStarCountByQuality < value.Need)
				{
					return false;
				}
				if (myHeroStarCountByQuality >= value.Need && self.GetBuyCount(value.Id) < value.LimitNum)
				{
					return false;
				}
				if (myHeroStarCountByQuality >= value.Need && (self.RewardGet < value.Id || self.FreeGet < value.Id))
				{
					return false;
				}
			}
			return true;
		}
	}
