		public static void OnDisabledChange(this RedPointNode self, RedPointNode dependentNode, bool oldValue, bool newValue)
		{
			if (oldValue && !newValue)
			{
				self.Count += dependentNode.Count;
			}
			if (!oldValue && newValue)
			{
				self.Count -= dependentNode.Count;
			}
		}

		public static void OnCountChange(this RedPointNode self, RedPointNode dependentNode, int oldValue, int newValue)
		{
			if (!dependentNode.Disabled)
			{
				self.Count += newValue - oldValue;
			}
		}
	}
