				RedPointNode node2 = self.GetNode(redPointNodeType2);
				if (node2 != null && !node2.Disabled)
				{
					num += node2.Count;
				}
			}
			node.Count += num;
		}

		public static void RemoveDependents(this RedPointTreeComponent self, RedPointNodeType redPointNodeType, bool refresh, params RedPointNodeType[] dependents)
