			{
				Log.Error($"重复添加RedPointNode RedPointNodeType = {redPointNodeType}");
				return null;
			}
			RedPointNode node = ((Entity)self).AddChildWithId<RedPointNode>((long)(int)redPointNodeType, false);
			node.RedPointNodeType = redPointNodeType;
			self.AddDependents(redPointNodeType, refresh: false, dependents);
			((Entity)(object)node).EnableDataBind();
			((Entity)(object)node).BindData("Count", delegate(int oldValue, int newValue)
			{
				if (self.DependentDict.TryGetValue(redPointNodeType, out var value))
				{
					foreach (RedPointNodeType item in value)
					{
						((Entity)self).GetChild<RedPointNode>((long)(int)item)?.OnCountChange(node, oldValue, newValue);
					}
