			}
			if (message.NewEvents != null)
			{
				foreach (RiverMapEventPBData newEvent in message.NewEvents)
				{
					RiverMapEventData riverMapEventData = self.CreateEvent(newEvent.MainType, newEvent.ConfigId, newEvent.Uid);
					riverMapEventData.SetParam(newEvent);
					riverMapEventData.Level = newEvent.Level;
					riverMapEventData.CreateTime = newEvent.CreateTime;
					riverMapEventData.LastFinishTime = newEvent.LastFinishTime;
					riverMapEventData.PostId = newEvent.PostId;
					if (message.RefreshType == 2)
					{
						self.TimeRefreshSuggestTips = true;
					}
				}
			}
			Singleton<EventSystem>.Instance.Publish<RiverMapEventRefresh>(SceneHelper.DomainScene((Entity)(object)self), new RiverMapEventRefresh
			{
				RefreshType = message.RefreshType
			});
		}

		public static void OnEventFinish(this RiverMapModule self, L2C_RiverMapEventFinish message)
		{
			if (message != null)
			{
				self.FinishEventNum++;
				self.IsNewLevel = self.Level < message.Level;
				self.Level = message.Level;
				self.Exp = message.Exp;
				RiverMapEventData child = ((Entity)self).GetChild<RiverMapEventData>(message.Uid);
				self.TicketRefreshEndTime = message.TicketRefreshEndTime;
				bool showNewLevel = child.EventType == 1 || child.EventType == 2;
				int quality = child.Quality;
				int eventType = child.EventType;
				int mainType = child.MainType;
				if (child != null)
				{
					((DisposeObject)child).Dispose();
				}
				Singleton<EventSystem>.Instance.Publish<RiverMapEventFinish>(SceneHelper.DomainScene((Entity)(object)self), new RiverMapEventFinish
				{
					Player = ((Entity)(object)self).LocalPlayer(),
					Uid = message.Uid,
					ShowNewLevel = showNewLevel,
					Quality = quality,
					EventType = eventType,
					MainType = mainType
				});
			}
		}

		public static void OnSyncInfo(this RiverMapModule self, L2C_SyncRiverMapInfo message)
		{
			self.TicketRefreshEndTime = message.TicketRefreshEndTime;
			self.Level = message.Level;
			self.Exp = message.Exp;
			Singleton<EventSystem>.Instance.Publish<RiverMapInfoRefresh>(SceneHelper.DomainScene((Entity)(object)self), default(RiverMapInfoRefresh));
		}

		public static void SetParam(this RiverMapEventData self, RiverMapEventPBData eventData)
		{
			switch (self.EventType)
			{
			case 1:
				((Entity)self).GetComponent<RiverMapEventAnswer>().QuestionId = eventData.AnswerParam.QuestionId;
				break;
			case 2:
				((Entity)self).GetComponent<RiverMapEventStore>().Goods = eventData.StoreParam.Goods.Select((RiverMapShopData g) => new ShopBuyData
				{
					Id = g.GoodsId,
					BuyCount = g.GoodsNum
				}).ToList();
				break;
			case 4:
				((Entity)self).GetComponent<RiverMapEventDupBox>().DupId = eventData.DupParam.DupId;
				break;
			case 3:
				((Entity)self).GetComponent<RiverMapEventDupMonster>().DupId = eventData.DupParam.DupId;
				break;
			case 5:
				((Entity)self).GetComponent<RiverMapEventDupRescue>().DupId = eventData.DupParam.DupId;
				break;
			}
		}

		public static List<RiverMapEventData> GetEvents(this RiverMapModule self)
		{
			List<RiverMapEventData> list = new List<RiverMapEventData>();
			foreach (Entity value in ((Entity)self).Children.Values)
			{
				RiverMapEventData riverMapEventData = value as RiverMapEventData;
				if (!riverMapEventData.IsExpired)
				{
					list.Add(riverMapEventData);
				}
			}
			return list;
		}

		public static long GetTicketRefreshTime(this RiverMapModule self)
		{
			return self.TicketRefreshEndTime - TimeHelper.Now();
		}

		public static void CheckExpirationEvents(this RiverMapModule self)
		{
			foreach (Entity value in ((Entity)self).Children.Values)
			{
				RiverMapEventData riverMapEventData = value as RiverMapEventData;
				if (riverMapEventData.IsExpired)
				{
					((DisposeObject)riverMapEventData).Dispose();
				}
			}
			Singleton<EventSystem>.Instance.Publish<RiverMapEventRefresh>(SceneHelper.DomainScene((Entity)(object)self), default(RiverMapEventRefresh));
		}
	}
