		public static bool IsShow(this SevenDaySignModule self, ActivityCenterType activityCenterType)
		{
			if (activityCenterType == ActivityCenterType.MainPanelRight || activityCenterType == ActivityCenterType.MainPanel)
			{
				if (!((Entity)(object)self).LocalPlayer().CheckAllConds(self.ActivityData.Condition))
				{
					return false;
				}
				bool flag = self.IsGetAllReward();
				if (!flag)
				{
					return TimeHelper.IsSameDay(TimeHelper.ServerNow(), self.GetRewardTime, 18000000L);
				}
				return flag;
			}
			return true;
		}

		public static int GetLoginDay(this SevenDaySignModule self)
		{
			return self.LoginDay;
		}

		public static bool IsItemRewardFlag(this SevenDaySignModule self, int day)
		{
			return (self.ItemRewardFlag & (1L << day)) != 0;
		}

		public static bool IsGetAllReward(this SevenDaySignModule self)
		{
			foreach (SevenDaySignConfig item in ConfigSingleton<SevenDaySignConfigCategory>.Instance.GetAll(self.GetActivityId()))
			{
				if (!self.IsItemRewardFlag(item.Day))
				{
					return true;
				}
			}
			return false;
		}

		public static bool IsLoginDay(this SevenDaySignModule self, int day)
		{
			return self.LoginDay >= day;
		}

		public static void UpdateSevenDaySign(this SevenDaySignModule self, int day, long itemReward, long time)
		{
			self.LoginDay_C = day;
			self.ItemRewardFlag_C = itemReward;
			self.LastLoginDayTime = time;
			Singleton<EventSystem>.Instance.Publish<ActivitySevenDaySignUpdate>(SceneHelper.DomainScene((Entity)(object)((Entity)(object)self).LocalPlayer()), new ActivitySevenDaySignUpdate
			{
				ActivityId = self.GetActivityId()
			});
		}

		public static void OnSpanDay(this SevenDaySignModule self)
		{
			((Entity)(object)self).LocalPlayer().Send(new C2L_SevenDaySignSpanDay
			{
				ActivityId = self.GetActivityId()
			});
		}

