		public static int GetRewardCount(this SevenDaySignModule self)
		{
			int num = 0;
			foreach (SevenDaySignConfig item in ConfigSingleton<SevenDaySignConfigCategory>.Instance.GetAll(self.GetActivityId()))
			{
				if (self.IsLoginDay(item.Day) && !self.IsItemRewardFlag(item.Day))
