			foreach (ShopGoodsConfig value in ConfigSingleton<ShopGoodsConfigCategory>.Instance.GetAll().Values)
			{
				if (self.IsShopItemOpenShow(value.Id, checkShopTypeOpen: false) && value.ShopType == shopType)
