		public static void RefreshGoodsIds(this SubShop self, List<int> goodsIds, int refreshCount, long refreshTime, bool newList)
		{
			self.RefreshCount = refreshCount;
			self.LastRefreshTime = refreshTime;
			self.GoodsIds = goodsIds;
			if (!((goodsIds != null) & newList))
			{
				return;
			}
			foreach (int goodsId in goodsIds)
			{
				if (ConfigSingleton<ShopGoodsConfigCategory>.Instance.Get(goodsId).LimitType == 2 && self.ShopBuyDatas.TryGetValue(goodsId, out var value))
				{
					int buyCount = value.BuyCount;
					value.BuyCount = 0;
					if (buyCount != value.BuyCount)
					{
						((Entity)self).GetComponent<DataBindComponent>()?.Publish(string.Format("{0}{1}", "EventBuyCount_", goodsId), buyCount, value.BuyCount);
						((Entity)self).GetComponent<DataBindComponent>()?.Publish("EventBuyCount_Any", buyCount, value.BuyCount);
					}
				}
			}
		}

		public static void RefreshBuyData(this SubShop self, int goodsId, int buyCount, long buyTime)
		{
			ShopBuyData orCreateBuyData = self.GetOrCreateBuyData(goodsId, check: false);
			orCreateBuyData.LastBuyTime = buyTime;
			int buyCount2 = orCreateBuyData.BuyCount;
			orCreateBuyData.BuyCount = buyCount;
			if (buyCount2 != orCreateBuyData.BuyCount)
			{
				((Entity)self).GetComponent<DataBindComponent>()?.Publish(string.Format("{0}{1}", "EventBuyCount_", goodsId), buyCount2, orCreateBuyData.BuyCount);
				((Entity)self).GetComponent<DataBindComponent>()?.Publish("EventBuyCount_Any", buyCount2, orCreateBuyData.BuyCount);
			}
		}

		public static ShopBuyData GetOrCreateBuyData(this SubShop self, int goodsId, bool check = true)
		{
			if (!self.ShopBuyDatas.TryGetValue(goodsId, out var value))
			{
				value = new ShopBuyData
				{
					Id = goodsId
				};
				self.ShopBuyDatas.Add(goodsId, value);
			}
			if (check)
			{
				switch ((ShopLimitType)ConfigSingleton<ShopGoodsConfigCategory>.Instance.Get(goodsId).LimitType)
				{
				case ShopLimitType.Day:
					if (!TimeHelper.IsSameDay(value.LastBuyTime, TimeHelper.Now(), 18000000L))
					{
						int buyCount2 = value.BuyCount;
						value.BuyCount = 0;
						if (buyCount2 != value.BuyCount)
						{
							((Entity)self).GetComponent<DataBindComponent>()?.Publish(string.Format("{0}{1}", "EventBuyCount_", goodsId), buyCount2, value.BuyCount);
							((Entity)self).GetComponent<DataBindComponent>()?.Publish("EventBuyCount_Any", buyCount2, value.BuyCount);
						}
					}
					break;
				case ShopLimitType.Refresh:
					if (value.LastBuyTime < self.LastRefreshTime)
					{
						int buyCount = value.BuyCount;
						value.BuyCount = 0;
						if (buyCount != value.BuyCount)
						{
							((Entity)self).GetComponent<DataBindComponent>()?.Publish(string.Format("{0}{1}", "EventBuyCount_", goodsId), buyCount, value.BuyCount);
							((Entity)self).GetComponent<DataBindComponent>()?.Publish("EventBuyCount_Any", buyCount, value.BuyCount);
						}
					}
					break;
				}
			}
			return value;
		}
	}
	public static class SkillHelper
	{
		public static string Name(this SkillLevel skillLevel)
		{
			if (!skillLevel.IsPassiveSkill)
			{
				return ConfigSingleton<ActiveSkillLevelConfigCategory>.Instance.Get(skillLevel.SkillLevelId)?.Name ?? string.Empty;
			}
			return ConfigSingleton<PassiveSkillLevelConfigCategory>.Instance.Get(skillLevel.SkillLevelId)?.Name ?? string.Empty;
		}

		public static string Icon(this SkillLevel skillLevel)
		{
			if (skillLevel.IsPassiveSkill)
			{
				PassiveSkillLevelConfig passiveSkillLevelConfig = ConfigSingleton<PassiveSkillLevelConfigCategory>.Instance.Get(skillLevel.SkillLevelId);
				return $"uitex_icon_skill_{passiveSkillLevelConfig.Icon}";
			}
			ActiveSkillLevelConfig activeSkillLevelConfig = ConfigSingleton<ActiveSkillLevelConfigCategory>.Instance.Get(skillLevel.SkillLevelId);
			return $"uitex_icon_skill_{activeSkillLevelConfig.Icon}";
		}

		public static string Description(this SkillLevel skillLevel)
		{
			if (!skillLevel.IsPassiveSkill)
			{
				return ConfigSingleton<ActiveSkillLevelConfigCategory>.Instance.Get(skillLevel.SkillLevelId)?.Desc ?? string.Empty;
			}
			return ConfigSingleton<PassiveSkillLevelConfigCategory>.Instance.Get(skillLevel.SkillLevelId)?.Desc ?? string.Empty;
		}

		public static string SimpleDesc(this SkillLevel skillLevel)
		{
			if (!skillLevel.IsPassiveSkill)
			{
				return ConfigSingleton<ActiveSkillLevelConfigCategory>.Instance.Get(skillLevel.SkillLevelId)?.SimpleDesc ?? string.Empty;
			}
			return ConfigSingleton<PassiveSkillLevelConfigCategory>.Instance.Get(skillLevel.SkillLevelId)?.SimpleDesc ?? string.Empty;
		}

		public static float CoolDown(this SkillLevel skillLevel)
		{
			if (!skillLevel.IsActiveSkill)
			{
				return 0f;
			}
			return ((float?)ConfigSingleton<ActiveSkillLevelConfigCategory>.Instance.Get(skillLevel.SkillLevelId)?.CD / 1000f).GetValueOrDefault();
		}

		public static string GetSpriteBySkillTag(int tagType)
		{
			return tagType switch
			{
				1 => "ui_hero_frame_23", 
				2 => "ui_hero_frame_22", 
				3 => "ui_hero_frame_21", 
				4 => "ui_hero_frame_20", 
				5 => "ui_hero_frame_19", 
				_ => "", 
			};
		}

		public static SkillTagConfig[] SkillTags(this SkillLevel skillLevel)
		{
			int[] source = ((!skillLevel.IsPassiveSkill) ? (ConfigSingleton<ActiveSkillLevelConfigCategory>.Instance.Get(skillLevel.SkillLevelId)?.SkillTag ?? Array.Empty<int>()) : (ConfigSingleton<PassiveSkillLevelConfigCategory>.Instance.Get(skillLevel.SkillLevelId)?.SkillTag ?? Array.Empty<int>()));
			return source.Select((int id) => ConfigSingleton<SkillTagConfigCategory>.Instance.Get(id)).ToArray();
		}

		public static SkillIconTag IconTag(this SkillLevel skillLevel)
		{
			if (!skillLevel.IsActiveSkill)
			{
				return SkillIconTag.None;
			}
			if (skillLevel.SkillIndex == 1)
			{
				return SkillIconTag.NormalTag;
			}
			ActiveSkillLevelConfig activeSkillLevelConfig = ConfigSingleton<ActiveSkillLevelConfigCategory>.Instance.Get(skillLevel.SkillLevelId);
			if (activeSkillLevelConfig != null)
			{
				_ = activeSkillLevelConfig.Tags;
				SkillTag value = (SkillTag)(activeSkillLevelConfig?.Tags).Value;
				if (value.HasFlag(SkillTag.Super))
				{
					return SkillIconTag.UltimateTag;
				}
			}
			return SkillIconTag.None;
		}
	}
