	public static class StrongHelper
	{
		public static string GetPayName(Player player, int configId)
		{
			PayWayConfig payWayConfig = ConfigSingleton<PayWayConfigCategory>.Instance.Get(configId);
			if (payWayConfig.FuncId == 31001)
			{
				int level = ((Entity)player).GetComponent<VipModule>().GetLevel();
				if (level >= payWayConfig.Stages.Last())
				{
					return $"{payWayConfig.ObtainName}{payWayConfig.Stages.Last()}";
				}
				int[] stages = payWayConfig.Stages;
				foreach (int num in stages)
				{
					if (num > level)
					{
						return $"{payWayConfig.ObtainName}{num}";
					}
				}
			}
			return payWayConfig.ObtainName;
		}

		public static bool IsOpen(Player player, int configId)
		{
			PayWayConfig payWayConfig = ConfigSingleton<PayWayConfigCategory>.Instance.Get(configId);
			if (payWayConfig.FuncId > 0)
			{
				return player.IsFuncOpen(payWayConfig.FuncId);
			}
			int activityType = payWayConfig.ActivityType;
			int activitySubType = payWayConfig.ActivitySubType;
			ActivityData activityByType = ((Entity)player).GetComponent<PlayerActivityComponent>().GetActivityByType((ActivityType)activityType, (ActivitySubType)activitySubType);
			if (activityByType != null && player.CheckAllConds(activityByType.BaseInfo.Cond))
			{
				return true;
			}
			return false;
		}

		public static long GetNums(Scene scene, int type, int subType)
		{
			return ((Entity)scene).GetComponent<StrongComponent>().GetNums(type, subType);
		}

		public static bool IsMeet(Player player, int configId)
		{
			PayWayConfig payWayConfig = ConfigSingleton<PayWayConfigCategory>.Instance.Get(configId);
			if (payWayConfig.FuncId > 0)
			{
				return IsMeetFunc(player, payWayConfig.FuncId, payWayConfig);
			}
			int activityType = payWayConfig.ActivityType;
			int activitySubType = payWayConfig.ActivitySubType;
			return IsMeetActivity(player, (ActivityType)activityType, (ActivitySubType)activitySubType, payWayConfig.Param);
		}

		public static bool IsMeetFunc(Player player, int funcId, PayWayConfig config)
		{
			if (!player.IsFuncOpen(funcId))
			{
				return false;
			}
			switch (funcId)
			{
			case 14:
				return ((Entity)player).GetComponent<FirstRechargeModule>().IsAllBuy(config.Param);
			case 48:
			{
				InvestModule component3 = ((Entity)player).GetComponent<InvestModule>();
				int cardId = 48000 + config.Param;
				return component3.IsBuyCard(cardId);
			}
			case 46:
			{
				InvestModule component2 = ((Entity)player).GetComponent<InvestModule>();
				int param = config.Param;
				return component2.IsBuyCard(param);
			}
			case 31001:
			{
				VipModule component = ((Entity)player).GetComponent<VipModule>();
				if (config.Param == 0)
				{
					return component.GetLevel() >= config.Stages.Last();
				}
				VipGiftInfo orCreateVipGiftInfo = component.GetOrCreateVipGiftInfo(config.Param);
				if (orCreateVipGiftInfo.CashGiftBuyTimes <= 0)
				{
