		public static bool IsMeetActivity(Player player, ActivityType activityType, ActivitySubType activitySubType = (ActivitySubType)0, int giftId = 0)
		{
			ActivityData activityByType = ((Entity)player).GetComponent<PlayerActivityComponent>().GetActivityByType(activityType, activitySubType);
			if (activityByType != null)
			{
				switch (activityType)
				{
				case ActivityType.WeekCard:
					return ((Entity)activityByType).GetComponent<WeekCardModule>().IsBuy();
				case ActivityType.GemStonePlan:
					return ((Entity)activityByType).GetComponent<GemStonePlanModule>().IsExchangeOutGiftsWithId(giftId);
				case ActivityType.GemStoneThemeGift:
					return ((Entity)activityByType).GetComponent<GemStoneThemeGiftModule>().IsSortOut(giftId);
				case ActivityType.DirectBuyGift:
					return ((Entity)activityByType).GetComponent<DirectBuyGiftModule>().IsBuyOver(giftId);
				case ActivityType.GrowthFund:
					return ((Entity)activityByType).GetComponent<GrowthFundModule>().IsOver();
				case ActivityType.TaskFund:
					return ((Entity)activityByType).GetComponent<GrowthFundGameplayModule>().IsBuyCard();
				case ActivityType.DirectBuyThemeGift:
					return ((Entity)activityByType).GetComponent<DirectBuyThemeGiftModule>().IsBuyOver(giftId);
				case ActivityType.DirectBuyEveryDayGift:
					return ((Entity)activityByType).GetComponent<DirectBuyEveryDayGiftModule>().IsBuyOver(giftId);
				case ActivityType.LoginGift:
					return ((Entity)activityByType).GetComponent<LoginGiftModule>().IsBuy();
				case ActivityType.DirectBuySelectGift:
					return ((Entity)activityByType).GetComponent<DirectBuySelectGiftModule>().IsBuyOver();
				case ActivityType.GrowthFundLevel:
					return ((Entity)activityByType).GetComponent<GrowthFundLevelModule>().LiberalStatus;
				case ActivityType.GodWillStraight:
					return ((Entity)activityByType).GetComponent<GodWillStraightModule>().IsBuyOver(giftId);
				case ActivityType.RedHeroUpStar:
					return ((Entity)activityByType).GetComponent<RedHeroUpStarModule>().IsBuyOver(giftId);
				case ActivityType.EveryDaySign:
					return false;
				case ActivityType.KismetFetter:
					return ((Entity)activityByType).GetComponent<KismetFetterModule>().IsOver();
				case ActivityType.ZeroMoneyBuy:
					return ((Entity)activityByType).GetComponent<ZeroMoneyBuyModule>().IsSortOutGiftWithId(giftId);
				case ActivityType.FreePrizeDraw:
					return ((Entity)activityByType).GetComponent<FreePrizeDrawModule>().IsGetAllReward();
				case ActivityType.OrderWarGodAnimals:
					return ((Entity)activityByType).GetComponent<OrderWarGodAnimalsModule>().Buy;
				}
			}
			return false;
		}
	}
