			Player player = ((Entity)scene).GetComponent<LocalPlayerComponent>().Player;
			if (player == null)
			{
				return 0L;
			}
			return subType switch
			{
				1 => GetLevelPower(player), 
				2 => GetEquipPower(player), 
				3 => GetEnhancePower(player), 
				4 => GetGemPower(player), 
				5 => GetSoulPower(player), 
				_ => 0L, 
			};
		}

		private long GetLevelPower(Player player)
		{
			List<Hero> formationHeroes = player.GetFormationHeroes(ConfigSingleton<GlobalConfigCategory>.Instance.GetOne().CommonFormationId);
			long num = 0L;
			using StatList statList = StatList.Create();
			foreach (Hero item in formationHeroes)
			{
				item.GetStatBagComponent().GetStatsByStatBag(statList, StatBagType.Level);
				num += statList.GetPower();
				statList.Clear();
			}
			return num;
		}

