		public static void OnAddMoney(this SuccessiveExpenseModule self, int payId)
		{
			PayConfig payConfig = ConfigSingleton<PayConfigCategory>.Instance.Get(payId);
			if (payConfig == null)
			{
				return;
			}
			((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<RechargeModule>();
			int num = payConfig.Price / 10;
			List<SuccessiveExpenseConfig> all = ConfigSingleton<SuccessiveExpenseConfigCategory>.Instance.GetAll(self.GetActivityId());
			int num2 = TimeHelper.DaysBetween(self.ActivityData.StartTime, TimeHelper.ServerNow(), 18000000L);
			List<int> gears = ConfigSingleton<SuccessiveExpenseConfigCategory>.Instance.GetGears(self.GetActivityId());
			long num3 = TimeHelper.Now();
			foreach (int item in gears)
			{
				int num4 = num;
				foreach (SuccessiveExpenseConfig item2 in all)
				{
					if (item2.Price != item || num2 < item2.Gear || self.PayStatus.Contains(item2.Id))
					{
						continue;
					}
					if (num4 <= 0)
					{
						break;
					}
					self.PayDic.TryGetValue(item2.Id, out var value);
					if (value >= item2.Price)
					{
						continue;
					}
					self.Supplement.TryGetValue(item2.Price.ToString(), out var value2);
					if (TimeHelper.IsSameDay(num3, value2, 18000000L) && !item2.Supplement)
					{
						break;
					}
					self.PayDic[item2.Id] = math.min(item2.Price, value + num4);
					num4 -= self.PayDic[item2.Id] - value;
					if (self.PayDic[item2.Id] < item2.Price)
					{
						continue;
					}
					if (item2.Supplement)
					{
						if (num2 >= item2.Gear)
						{
							self.Supplement[item2.Price.ToString()] = num3;
						}
					}
					else
					{
						self.Supplement[item2.Price.ToString()] = num3;
					}
				}
			}
			self.PayNumber += num;
			Singleton<EventSystem>.Instance.Publish<SuccessiveExpenseGetReward_Success>(SceneHelper.DomainScene((Entity)(object)self), default(SuccessiveExpenseGetReward_Success));
		}

		public static bool IsGetSuccExpReward(this SuccessiveExpenseModule self, int configId)
		{
			if (self.PayStatus == null)
			{
				return false;
			}
			return self.PayStatus.Contains(configId);
		}

		public static long GetSupplementTime(this SuccessiveExpenseModule self, int price)
		{
			if (!self.Supplement.ContainsKey(price.ToString()))
			{
				return 0L;
			}
			return self.Supplement[price.ToString()];
		}

		public static bool IsSuccExpDic(this SuccessiveExpenseModule self, int configId)
		{
			if (self.PayDic == null)
			{
				return false;
			}
			return self.PayDic.ContainsKey(configId);
		}

		public static int GetPayNumber(this SuccessiveExpenseModule self, int configId)
		{
			if (!self.PayDic.ContainsKey(configId))
			{
				return 0;
			}
			return self.PayDic[configId];
		}

		public static bool IsHaveRed(this SuccessiveExpenseModule self, int price)
		{
			foreach (int key in self.PayDic.Keys)
			{
				SuccessiveExpenseConfig successiveExpenseConfig = ConfigSingleton<SuccessiveExpenseConfigCategory>.Instance.Get(key);
				if (successiveExpenseConfig != null && self.PayDic[key] >= successiveExpenseConfig.Price && !self.PayStatus.Contains(successiveExpenseConfig.Id) && successiveExpenseConfig.Price == price)
				{
					return true;
				}
			}
			return false;
		}

		public static bool MainRed(this SuccessiveExpenseModule self)
		{
			if (!TimeHelper.IsSameDay(TimeHelper.ServerNow(), self.GetTime, 18000000L))
			{
				return true;
			}
			foreach (int key in self.PayDic.Keys)
			{
				SuccessiveExpenseConfig successiveExpenseConfig = ConfigSingleton<SuccessiveExpenseConfigCategory>.Instance.Get(key);
				if (successiveExpenseConfig != null && self.PayDic.ContainsKey(key) && self.PayDic[key] >= successiveExpenseConfig.Price && !self.PayStatus.Contains(successiveExpenseConfig.Id))
				{
					return true;
				}
			}
			return false;
		}
	}
