			self.HelpBattleCount = message.BattleCount;
			self.BoxId = message.BoxId;
			self.DayHelpCount = message.DayHelpCount;
			self.DayHelpTime = message.DayHelpTime;
			Singleton<EventSystem>.Instance.Publish<TeamDupUpdate>(SceneHelper.DomainScene((Entity)(object)self), default(TeamDupUpdate));
		}

