		public static long GetPower(this TiangangModule self)
		{
			long num = 0L;
			List<Tiangang> tiangangs = self.GetTiangangs();
			using PowerCalc powerCalc = PowerCalc.Create();
			foreach (Tiangang item in tiangangs)
			{
				if (item.IsActive)
				{
					num += item.GetPower();
				}
			}
			if (self.ActiveSuitList != null)
			{
				foreach (int activeSuit in self.ActiveSuitList)
				{
					TianGangSuitConfig tianGangSuitConfig = ConfigSingleton<TianGangSuitConfigCategory>.Instance.Get(activeSuit);
					powerCalc.AddSkill(tianGangSuitConfig.ElementSkill);
				}
			}
			return num + powerCalc.Power;
		}

		public static List<Tiangang> GetTiangangs(this TiangangModule self, bool onlyActive = false)
		{
			if (!self.IsInit)
			{
				foreach (KeyValuePair<int, TianGangBaseConfig> item in ConfigSingleton<TianGangBaseConfigCategory>.Instance.GetAll())
				{
					self.GetTiangang(item.Value.Id);
				}
				self.IsInit = true;
			}
			List<Tiangang> list = new List<Tiangang>();
			foreach (Tiangang value in ((Entity)self).Children.Values)
			{
				if (!onlyActive || (value.IsActive && !value.IsLade()))
				{
					list.Add(value);
				}
			}
			return list;
		}

