		public static void UpdateTiangangSuit(this TiangangModule self)
		{
			if (self.ElementDict == null)
			{
				self.ElementDict = new Dictionary<int, int>();
			}
			self.ElementDict.Clear();
			for (int i = 0; i < self.LadeList.Count; i++)
