				int element = ConfigSingleton<TianGangBaseConfigCategory>.Instance.Get(id).Element;
				if (self.ElementDict.ContainsKey(element))
				{
					self.ElementDict[element] = self.ElementDict[element] + 1;
				}
				else
				{
					self.ElementDict.Add(element, 1);
				}
			}
			if (self.ActiveSuitList == null)
			{
				self.ActiveSuitList = new List<int>();
			}
			self.ActiveSuitList.Clear();
			foreach (var (num3, num4) in self.ElementDict)
			{
				for (int j = num3 * 10 + 1; ConfigSingleton<TianGangSuitConfigCategory>.Instance.Contain(j); j++)
				{
