					if (num4 < tianGangSuitConfig.ElementCount)
					{
						break;
					}
					self.ActiveSuitList.Add(tianGangSuitConfig.Id);
				}
			}
			self.ActiveSuitList.Sort((int eId1, int eId2) => ConfigSingleton<TianGangSuitConfigCategory>.Instance.Get(eId2).ElementCount - ConfigSingleton<TianGangSuitConfigCategory>.Instance.Get(eId1).ElementCount);
		}
