		public static long GetPieceeNums(this Tiangang self)
		{
			ET.ConfigBeans.Item[] cost = self.BaseConfig.Cost;
			ItemModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>();
			long num = 0L;
			foreach (ET.ConfigBeans.Item item in cost)
			{
				if (item.Nums > 1)
				{
					long itemNumsByItemId = component.GetItemNumsByItemId(item.Id);
					num += itemNumsByItemId;
				}
			}
			return num;
		}

		public static int GetSort(this Tiangang self, bool IsCheckActive = true)
		{
			int num = 0;
			bool flag = self.IsCanActive(((Entity)(object)self).LocalPlayer()) == 0;
			if (IsCheckActive & flag)
			{
				num += 100000000;
			}
			if (self.IsActive)
			{
				num += 20000000;
			}
			else if (!flag && self.GetPieceeNums() > 0)
			{
				num += 10000000;
			}
			num += self.BaseConfig.Quality * 1000000;
			num += self.Stage * 100000;
			num += self.Level * 100;
			return num + self.ConfigId;
		}

		public static List<TianGangStageConfig> GetSkillLevelList(this Tiangang self)
		{
			List<TianGangStageConfig> list = new List<TianGangStageConfig>();
			if (self.IsActive)
			{
				if (self.IsMaxStage)
				{
					list.Add(self.StageConfig);
				}
				else
				{
					list.Add(self.StageConfig);
					list.Add(self.NextStageConfig);
				}
			}
			else
			{
				list.Add(self.StageConfig);
			}
			return list;
		}
	}
