		public static bool IsShow(this TotalExpenseModule self, ActivityCenterType activityCenterType)
		{
			if (!((Entity)(object)self).LocalPlayer().CheckAllConds(self.ActivityData.Condition))
			{
				return false;
			}
			if (!ConfigSingleton<TotalExpenseCondConfigCategory>.Instance.Contain(self.GetActivityId()))
			{
				return false;
			}
			int num = ConfigSingleton<TotalExpenseCondConfigCategory>.Instance.Get(self.GetActivityId()).Conditions[0];
			FirstRechargeModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FirstRechargeModule>();
			if (component == null)
			{
				return true;
			}
			bool flag = false;
			if (component.IsAllClose())
			{
				RechargeModule component2 = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<RechargeModule>();
				if (component2 == null)
				{
					return true;
				}
				long time = TimeHelper.ServerNow();
				long lastPayTime = component2.GetLastPayTime();
				flag = TimeHelper.DaysBetween((lastPayTime == 0L) ? self.ActivityData.StartTime : lastPayTime, time, 18000000L) <= num;
			}
			if (activityCenterType == ActivityCenterType.MainPanelRight || activityCenterType == ActivityCenterType.MainPanel)
			{
				if (flag && self.IsGetAll())
				{
					return false;
				}
				return flag;
			}
			return !self.IsGetAll();
		}

