	public static class UnitHelper
	{
		public static int GetQuality(this Unit unit)
		{
			if (unit.Type == UnitType.Hero)
			{
				if (unit.IsRole())
				{
					int heroStar = unit.GetHeroStar();
					return ConfigSingleton<PracticeConfigCategory>.Instance.Get(heroStar).Quality;
				}
				return ConfigSingleton<HeroConfigCategory>.Instance.Get(unit.GetHeroConfigId()).HeroQuality;
			}
			return 4;
		}

		public static bool IsMainUnit(this Unit unit)
		{
			int heroConfigId = unit.GetHeroConfigId();
			if (heroConfigId > 0 && ConfigSingleton<HeroConfigCategory>.Instance.Get(heroConfigId).Type == 1)
			{
				return true;
			}
			return false;
		}

		public static bool IsLocalMainUnit(this Unit unit)
		{
			Player player = ((Entity)(object)unit).LocalPlayer();
			if (player == null)
			{
				return false;
			}
			if (((Entity)player).Id != unit.GetPlayerId())
			{
				return false;
			}
			return unit.IsMainUnit();
		}

		public static bool IsLocalUnit(this Unit unit)
		{
			Player player = ((Entity)(object)unit).LocalPlayer();
			if (player == null)
			{
				return false;
			}
			return unit.GetPlayerId() == ((Entity)player).Id;
		}
	}
