				powerCalc.AddStats(statList);
				num += powerCalc.Power;
			}
			return num;
		}

		public static long GetEnhancePlusPower(this VibesEquipModule self, int job)
		{
			int enhancePlusLevel = self.GetEnhancePlusLevel(job);
			if (enhancePlusLevel == 0)
			{
				return 0L;
			}
			VibesEquipPowerExcellentConfig vibesEquipPowerExcellentConfig = ConfigSingleton<VibesEquipPowerExcellentConfigCategory>.Instance.Get(job * 100 + enhancePlusLevel);
			using PowerCalc powerCalc = PowerCalc.Create();
			powerCalc.AddStats(vibesEquipPowerExcellentConfig?.AddStat);
			return powerCalc.Power;
		}

		public static bool IsExistEquipSplit(this VibesEquipModule self)
		{
			if (!((Entity)(object)self).LocalPlayer().IsFuncOpen(3006))
			{
				return false;
			}
			foreach (ItemStruct item in self.GetAllUnWearEquipItem())
			{
				EquipConfig equipConfig = ConfigSingleton<EquipConfigCategory>.Instance.Get(item.ConfigId);
				int equipId = self.GetEquipId(equipConfig.Job, equipConfig.Part);
				if (equipId > 0 && !self.IsBest(item.ConfigId, equipId))
				{
					return true;
				}
			}
			return false;
		}
	}
