		public static int GetBestGem(this VibesGemModule self, int job, int part, int position)
		{
			if (!VibesHelper.IsGemOpen(((Entity)self).GetParent<Player>(), job, part, position))
			{
				return 0;
			}
			Item[] allItems = ((Entity)((Entity)self).GetParent<Player>()).GetComponent<ItemModule>().GetAllItems();
			int result = 0;
			int num = 0;
			int gemLevel = self.GetGemLevel(job, part, position);
			Item[] array = allItems;
			foreach (Item item in array)
			{
				int itemGemLevel = VibesHelper.GetItemGemLevel(item.ConfigId, job, part, position);
				if (itemGemLevel > num)
				{
					result = item.ConfigId;
					num = itemGemLevel;
				}
			}
			if (num <= gemLevel)
			{
				return 0;
			}
			return result;
		}

