		public static bool IsCanGemInlay(this VibesGemModule self, int job, int part, int position)
		{
			Player player = ((Entity)(object)self).LocalPlayer();
			VibesGemStonePositionOpenConfig gemOpenConfig = VibesHelper.GetGemOpenConfig(job, part, position);
			if (!player.CheckCond(gemOpenConfig.Cond))
			{
				return false;
			}
			return self.GetBestGem(job, part, position) > 0;
		}

		public static bool IsCanGemLevel(this VibesGemModule self, int job, int part, int position)
		{
			Player player = ((Entity)(object)self).LocalPlayer();
			VibesGemStonePositionOpenConfig gemOpenConfig = VibesHelper.GetGemOpenConfig(job, part, position);
			if (!player.CheckCond(gemOpenConfig.Cond))
			{
				return false;
			}
			int gemLevel = self.GetGemLevel(job, part, position);
			if (VibesHelper.GetGemConfig(job, VibesHelper.GetGemPositionType(job, part, position), gemLevel + 1) == null)
			{
				return false;
			}
			GemStoneConfig gemConfig = VibesHelper.GetGemConfig(job, VibesHelper.GetGemPositionType(job, part, position), gemLevel);
			return ((Entity)player).GetComponent<ItemModule>().CheckItemNumsIsEnough(gemConfig.Cost);
		}

		public static bool IsExistGemSplit(this VibesGemModule self)
		{
			if (!((Entity)(object)self).LocalPlayer().IsFuncOpen(3007))
			{
				return false;
			}
			List<ItemStruct> bagGemItems = self.GetBagGemItems();
			if (bagGemItems == null || bagGemItems.Count <= 0)
			{
				return false;
			}
			for (int i = 0; i < bagGemItems.Count; i++)
			{
				if (self.IsDefalutSelected(bagGemItems[i].ConfigId))
				{
					return true;
				}
			}
			return false;
		}

		public static bool IsDefalutSelected(this VibesGemModule self, int gemId)
		{
			VibesGemModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesGemModule>();
			GemStoneConfig gemStoneConfig = ConfigSingleton<GemStoneConfigCategory>.Instance.Get(gemId);
			int job = gemStoneConfig.Job;
			for (int i = 1; i < 7; i++)
			{
				foreach (int gemPosition in VibesHelper.GetGemPositions(job, i))
				{
					if (VibesHelper.GetGemPositionType(job, i, gemPosition) == gemStoneConfig.PositionType)
					{
						int gemLevel = component.GetGemLevel(job, i, gemPosition);
						if (gemLevel == 0 && VibesHelper.IsGemLock(((Entity)(object)self).LocalPlayer(), job, i, gemPosition))
						{
							break;
						}
						if (gemStoneConfig.Level > gemLevel)
						{
							return false;
						}
					}
				}
			}
			return true;
		}

		public static bool IsSuggestInlay(this VibesGemModule self, int configId, bool isEquip = false, bool isLock = false)
		{
			if (!ConfigSingleton<GemStoneConfigCategory>.Instance.Contain(configId))
			{
				return false;
			}
			GemStoneConfig gemStoneConfig = ConfigSingleton<GemStoneConfigCategory>.Instance.Get(configId);
			int job = gemStoneConfig.Job;
			for (int i = 1; i < 7; i++)
			{
				foreach (int gemPosition in VibesHelper.GetGemPositions(job, i))
				{
					if (isLock)
					{
						VibesGemStonePositionOpenConfig gemOpenConfig = VibesHelper.GetGemOpenConfig(job, i, gemPosition);
						if (!((Entity)(object)self).LocalPlayer().CheckCond(gemOpenConfig.Cond))
						{
							continue;
						}
					}
					if (VibesHelper.GetGemPositionType(job, i, gemPosition) == gemStoneConfig.PositionType)
					{
						int gemLevel = self.GetGemLevel(job, i, gemPosition);
						if (gemStoneConfig.Level > gemLevel)
						{
							return true;
						}
					}
				}
			}
			return false;
		}
	}
