		}

		public static int GetRewardCount(this WeekCardModule self)
		{
			if (!self.IsBuy())
			{
				return 0;
			}
			int num = 0;
			List<WeekCardSubConfig> configsByActivityId = ConfigSingleton<WeekCardSubConfigCategory>.Instance.GetConfigsByActivityId(self.GetActivityId());
			if (configsByActivityId == null)
			{
				return 0;
			}
			int num2 = TimeHelper.DaysBetween(TimeHelper.Now(), self.GetActivityStartTime(), 18000000L);
			foreach (WeekCardSubConfig item in configsByActivityId)
			{
				if (item.Day <= num2 && !self.IsItemRewardFlag(item.Day))
				{
					num++;
				}
			}
			return num;
		}

		public static bool CanGet(this WeekCardModule self, int currentDay)
		{
			if (!self.IsBuy())
			{
				return false;
			}
			int num = TimeHelper.DaysBetween(TimeHelper.Now(), self.GetActivityStartTime(), 18000000L);
			if (currentDay > num)
			{
				return false;
			}
			return !self.IsItemRewardFlag(currentDay);
		}

		public static long CanGetTime(this WeekCardModule self)
		{
			if (!self.IsBuy())
			{
				return 0L;
			}
			if (self.IsGetAll())
			{
				return 0L;
			}
			long num = TimeHelper.Now();
			int day = TimeHelper.DaysBetween(num, self.GetActivityStartTime(), 18000000L);
			if (self.IsItemRewardFlag(day))
			{
				return TimeHelper.EndTimeOfDay(num, 18000000L) - num;
			}
			return 0L;
		}
