	public static class UIActivityHelper
	{
		private static string GetCountDownText(long SettleTime)
		{
			long val = SettleTime - TimeHelper.Now();
			val = Math.Max(val, 0L);
			TimeSpan timeSpan = TimeSpan.FromSeconds((double)(val / 1000));
			if (val < 3600000)
			{
				return string.Format("<color=#FF0000>" + timeSpan.ToString(ConfigSingleton<Lang2Category>.Instance.Get(515).Text) + "</color>", Array.Empty<object>());
			}
			string text = ((val < 86400000) ? timeSpan.ToString(ConfigSingleton<Lang2Category>.Instance.Get(515).Text) : timeSpan.ToString(ConfigSingleton<Lang2Category>.Instance.Get(304).Text));
			return string.Format("<color=#5BF947>" + text + "</color>", Array.Empty<object>());
		}

		public static string GetCountDownText(ActivityData activityData)
		{
			if (activityData == null)
			{
				return string.Empty;
			}
			if (activityData.ActivityType == ActivityType.BattleGround)
			{
				BattleGroundModule component = ((Entity)activityData).GetComponent<BattleGroundModule>();
				if (component.GetSettleTime() - TimeHelper.Now() <= 0)
				{
					return string.Format("<color=#5BF947>" + ConfigSingleton<Lang2Category>.Instance.Get(293)?.Text + "</color>", Array.Empty<object>());
				}
				return GetCountDownText(component.GetSettleTime());
			}
			if (activityData.ActivityType == ActivityType.HeavenFight)
			{
				HeavenFightModule component2 = ((Entity)activityData).GetComponent<HeavenFightModule>();
				if (component2.GetSettleTime() - TimeHelper.Now() <= 0)
				{
					return string.Format("<color=#5BF947>" + ConfigSingleton<Lang2Category>.Instance.Get(293)?.Text + "</color>", Array.Empty<object>());
				}
				return GetCountDownText(component2.GetSettleTime());
			}
			if (activityData.ActivityType == ActivityType.ImmortalOfficial)
			{
				ImmortalOfficialModule component3 = ((Entity)activityData).GetComponent<ImmortalOfficialModule>();
				int currRoundState = component3.GetCurrRoundState();
				string text = string.Empty;
				switch (currRoundState)
				{
				case 1:
					text = ConfigSingleton<Lang2Category>.Instance.Get(650).Text;
					break;
				case 2:
					return GetCountDownText(component3.GetSettleTime());
				case 3:
					text = "结算中";
					break;
				}
				if (text != string.Empty)
				{
					text = string.Format("<color=#5BF947>" + text + "</color>", Array.Empty<object>());
				}
				return text;
			}
			if (activityData.ActivityType == ActivityType.LadderTop)
			{
				return UILadderTopHelper.GetActivityTimeDesc(SceneHelper.DomainScene((Entity)(object)activityData)).Item2;
			}
			return GetCountDownText(activityData.EndTime);
		}
	}
	public static class NoticeHelper
	{
		public static string Parse(NoticeParam param)
		{
			switch (param.Type)
			{
			case NoticeParamType.Raw:
				return param.Content;
			case NoticeParamType.PlayerName:
				return param.Content;
			case NoticeParamType.PracticeName:
			{
				int.TryParse(param.Content, out var result);
				return ConfigSingleton<PracticeConfigCategory>.Instance.Get(result)?.Name ?? "";
			}
			case NoticeParamType.ItemList:
				return ParseItemList(param.Content);
			case NoticeParamType.Hero:
				return ParseHero(param.Content);
			case NoticeParamType.VipLevel:
				return ParseVipLevel(param.Content);
			case NoticeParamType.HeroSkin:
				return ParseHeroSkin(param.Content);
			case NoticeParamType.DressSuit:
				return ParseDressSuit(param.Content);
			case NoticeParamType.Beast:
				return ParseBeast(param.Content);
			case NoticeParamType.PlayerZone:
				return ParseZone(param.Content);
			case NoticeParamType.ImmortalOfficialStage:
				return ParseImmortalOfficialStage(param.Content);
			default:
				return "";
			}
		}

		private static string ParseItem(string itemStr)
		{
			string[] array = itemStr.Split('_');
			int.TryParse(array.GetValueOrDefault(0), out var result);
			int.TryParse(array.GetValueOrDefault(1), out var result2);
			ItemConfig itemConfig = ET.ItemHelper.GetItemConfig(result);
			if (itemConfig == null)
			{
				return string.Empty;
			}
			string text = ConfigSingleton<QualityConfigCategory>.Instance.Get(itemConfig.Quality)?.Hex ?? "ffffff";
			if (result2 >= 1)
			{
				return $"<color=#{text}>【{itemConfig.Name}x{result2}】</color>";
			}
			return "<color=#" + text + ">【" + itemConfig.Name + "】</color>";
		}

		private static string ParseItemList(string itemListStr)
		{
			StringBuilder stringBuilder = new StringBuilder();
			string[] array = itemListStr.Split("|");
			foreach (string itemStr in array)
			{
				stringBuilder.Append(ParseItem(itemStr));
			}
			return stringBuilder.ToString();
		}

		private static string ParseHero(string heroStr)
		{
			int.TryParse(heroStr, out var result);
			HeroConfig heroConfig = ConfigSingleton<HeroConfigCategory>.Instance.Get(result);
			if (heroConfig == null)
			{
				return "";
			}
			string text = ConfigSingleton<QualityConfigCategory>.Instance.Get(heroConfig.HeroQuality)?.Hex ?? "ffffff";
			return "<color=#" + text + ">【" + heroConfig.HeroName + "】</color>";
		}

		private static string ParseDressSuit(string dressSuitStr)
		{
			if (!int.TryParse(dressSuitStr, out var result))
			{
				return string.Empty;
			}
			return ConfigSingleton<FashionSuitConfigCategory>.Instance.Get(result)?.Name ?? string.Empty;
		}

		private static string ParseHeroSkin(string heroSkinStr)
		{
			if (!int.TryParse(heroSkinStr, out var result))
			{
				return string.Empty;
			}
			HeroSkinConfig heroSkinConfig = ConfigSingleton<HeroSkinConfigCategory>.Instance.Get(result);
			if (heroSkinConfig == null)
			{
				return string.Empty;
			}
			return TextHelper.FormatQuality(heroSkinConfig.SkinName, heroSkinConfig.SkinQuality, null);
		}

		private static string ParseVipLevel(string vipStr)
		{
			if (!int.TryParse(vipStr, out var result))
			{
				return "";
			}
			VipConfig vipConfig = ConfigSingleton<VipConfigCategory>.Instance.Get(result);
			if (vipConfig == null)
			{
				return "";
			}
			return vipConfig.Name;
		}

		private static string ParseImmortalOfficialStage(string immortalOfficialStr)
		{
			if (!int.TryParse(immortalOfficialStr, out var result))
			{
				return "";
			}
			if (!ConfigSingleton<ImmortalOfficialConfigCategory>.Instance.Contain(result))
			{
				return "";
			}
			return ConfigSingleton<ImmortalOfficialConfigCategory>.Instance.Get(result).Government;
		}

		private static string ParseZone(string PlayerIdStr)
		{
			//IL_0012: Unknown result type (might be due to invalid IL or missing references)
			if (!int.TryParse(PlayerIdStr, out var result))
			{
				return "";
			}
			return TextHelper.FormatZone(new UIDStruct((long)result).Zone);
		}

		private static string ParseBeast(string beastIdStr)
		{
			if (!int.TryParse(beastIdStr, out var result))
			{
				return "";
			}
			BeastConfig beastConfig = ConfigSingleton<BeastConfigCategory>.Instance.Get(result);
			if (beastConfig == null)
			{
				return "";
			}
			return TextHelper.FormatQuality(beastConfig.Name, beastConfig.Quality, null);
		}
	}
	public static class UIChatHelper
	{
		public static int GetUnReadChatInfoCountByPersonId(ChatModule chatModule, long id)
		{
			long id2 = ((Entity)((Entity)(object)chatModule).LocalPlayer()).Id;
			if (id2 == id)
			{
				return 0;
			}
			ChatPersonData personData = chatModule.GetPersonData(id);
			if (personData == null)
			{
				return 0;
			}
			LocalData_ReadChatInfo localData = ((Entity)(object)chatModule).LocalPlayer().GetLocalData<LocalData_ReadChatInfo>();
			if (localData.ReadChatInfo == null)
			{
				return 0;
			}
			localData.ReadChatInfo.TryGetValue(id, out var value);
			if (value == null)
			{
				value = new List<long>();
			}
			int num = 0;
			foreach (ChatInfo privateData in personData.PrivateDatas)
			{
				if (privateData.Sender.Id != id2 && !value.Contains(privateData.SendTime))
				{
					num++;
				}
			}
			((Entity)(object)chatModule).LocalPlayer().SetLocalData(localData);
			return num;
		}

		public static void AutoReadChatInfoByPersonId(ChatModule chatModule, long id)
		{
			long id2 = ((Entity)((Entity)(object)chatModule).LocalPlayer()).Id;
			if (id2 == id || !chatModule.GetPersonDict().TryGetValue(id, out var value))
			{
				return;
			}
			LocalData_ReadChatInfo localData = ((Entity)(object)chatModule).LocalPlayer().GetLocalData<LocalData_ReadChatInfo>();
			if (!localData.ReadChatInfo.ContainsKey(id))
			{
				localData.ReadChatInfo[id] = new List<long>();
			}
			List<long> list = localData.ReadChatInfo[id];
			if (value.PrivateDatas.Count >= 10)
			{
				list.Clear();
			}
			foreach (ChatInfo privateData in value.PrivateDatas)
			{
				if (privateData.Sender.Id != id2 && !list.Contains(privateData.SendTime))
				{
					list.Add(privateData.SendTime);
				}
			}
			((Entity)(object)chatModule).LocalPlayer().SetLocalData(localData);
		}

		public static void SetReadChatInfoByPersonId(Player player, long id, long sendTime)
		{
			if (id != 0L && ((Entity)player).Id != id)
			{
				LocalData_ReadChatInfo localData = player.GetLocalData<LocalData_ReadChatInfo>();
				if (!localData.ReadChatInfo.ContainsKey(id))
				{
					localData.ReadChatInfo[id] = new List<long>();
				}
				List<long> list = localData.ReadChatInfo[id];
				if (!list.Contains(sendTime))
				{
					list.Add(sendTime);
					player.SetLocalData(localData);
				}
			}
		}

		public static void SetPersonalTop(Player player, long id)
		{
			if (((Entity)player).Id != id && id != 0L)
			{
				LocalData_SavePersonChatTopInfo localData = player.GetLocalData<LocalData_SavePersonChatTopInfo>();
				if (!localData.TopIdList.Contains(id))
				{
					localData.TopIdList.Add(id);
				}
				player.SetLocalData(localData);
			}
		}

		public static void CancelPersonalTop(Player player, long id)
		{
			LocalData_SavePersonChatTopInfo localData = player.GetLocalData<LocalData_SavePersonChatTopInfo>();
			localData.TopIdList.Remove(id);
			player.SetLocalData(localData);
		}

		public static bool ContainsPersonalTop(Player player, long id)
		{
			return player.GetLocalData<LocalData_SavePersonChatTopInfo>().TopIdList.Contains(id);
		}

		public static List<long> GetReadChatInfoListByPersonId(Player player, long id)
		{
			if (((Entity)player).Id == id)
			{
				return null;
			}
			return player.GetLocalData<LocalData_ReadChatInfo>().ReadChatInfo.GetValueOrDefault(id);
		}

		public static string GetRandomChatText(Player player)
		{
			int serverOpenDays = ((Entity)player).GetComponent<RoleInfoModule>().ServerOpenDays;
			ChatTaskConfig chatTaskConfig = null;
			List<ChatTaskConfig> list = ConfigSingleton<ChatTaskConfigCategory>.Instance.GetList();
			list.Sort((ChatTaskConfig a, ChatTaskConfig b) => a.Id.CompareTo(b.Id));
			foreach (ChatTaskConfig item in list)
			{
				if (item.Id > serverOpenDays)
				{
					break;
				}
				chatTaskConfig = item;
			}
			if (chatTaskConfig == null)
			{
				chatTaskConfig = list.Last();
			}
			int num = RandomGenerator.RandomNumber(0, chatTaskConfig.Text.Length);
			return chatTaskConfig.Text[num];
		}
	}
