	[ObjectSystem]
	public class GlobalComponentAwakeSystem : AwakeSystem<GlobalComponent>
	{
		protected override void Awake(GlobalComponent self)
		{
			GlobalComponent.Instance = self;
			Object.DontDestroyOnLoad((Object)(object)GameObject.Find("Global"));
			self.Unit = GameObject.Find("Global/Unit").transform;
			self.Bullet = GameObject.Find("Global/Bullet").transform;
			self.UI = GameObject.Find("Global/UI").transform;
			self.Effect = GameObject.Find("Global/Effect").transform;
			self.UISceneRoot = ((Component)self.UI.Find("UISceneRoot")).transform;
			self.CloseUpMask = GameObject.Find("Global/CloseUpMask/Mask").GetComponent<SuperImage>();
			self.CloseUpCamera = GameObject.Find("Global/CloseUpCamera").GetComponent<Camera>();
			((Component)self.CloseUpCamera).gameObject.SetActive(false);
		}
