	[FriendOf(typeof(GMCommandComponent))]
	public static class GMCommandComponentSystem
	{
		public class AwakeSystem : AwakeSystem<GMCommandComponent>
		{
			protected override void Awake(GMCommandComponent self)
			{
				GMCommandComponent.Instance = self;
				self.OnLoad();
			}
		}

		public class LoadSystem : LoadSystem<GMCommandComponent>
		{
			public override void Load(GMCommandComponent self)
			{
				self.OnLoad();
			}
		}

		private static void OnLoad(this GMCommandComponent self)
		{
			self.Commands.Clear();
			foreach (Type type in Singleton<EventSystem>.Instance.GetTypes(typeof(GMCommandAttribute)))
			{
				if (!(Activator.CreateInstance(type) is AGMCommand value))
				{
					Log.Error("Type is not a AGMCommand: " + type.Name);
				}
				else
				{
					self.Commands.Add(type.Name.ToLower(), value);
				}
			}
		}

		public static bool Execute(this GMCommandComponent self, Player player, string message)
		{
			Match match = Regex.Match(message, "^![a-zA-Z]+");
			if (!match.Success)
			{
				return false;
			}
			string key = match.Value.Remove(0, 1);
			string[] parameters = message.Replace(match.Value, "").Trim().Split(",");
			if (self.Commands.TryGetValue(key, out var value))
			{
				value.Execute(player, new GMCommandParams(parameters));
			}
			return true;
		}
	}
	public static class GMCommandHelper
	{
		public static void HandleSetTimeCommand(string command)
		{
			try
			{
				string[] array = command.Split(' ', StringSplitOptions.RemoveEmptyEntries);
				if (array.Length < 2)
				{
					return;
				}
				string text = array[1];
				if (text.StartsWith("+") || text.StartsWith("-"))
				{
					if (long.TryParse(text, out var _))
					{
						TimeHelper.ClientNow();
					}
				}
				else
				{
					long.TryParse(text, out var _);
				}
			}
			catch (Exception arg)
			{
				Log.Error($"处理settime命令时出错: {arg}");
			}
		}
	}
