	public class jump : AGMCommand
	{
		public override void Execute(Player player, GMCommandParams ps)
		{
			int num = ps.PopInt();
			int num2 = ps.PopInt();
			int num3 = ps.PopInt();
			if (num != 0)
			{
				if (num2 == 0 && num3 == 0)
				{
					UIJumpHelper.To(num).Coroutine();
				}
				else if (num3 != 0)
				{
					UIJumpHelper.To(num, num2, num3).Coroutine();
				}
				else
				{
					UIJumpHelper.To(num, num2).Coroutine();
				}
			}
		}
	}
