	public class DelData : AGMCommand
	{
		public override void Execute(Player player, GMCommandParams ps)
		{
			string text = ps.PopString();
			if (text == "all")
			{
				PlayerPrefs.DeleteAll();
			}
			else
			{
				PlayerPrefs.DeleteKey(text);
			}
		}
	}
