				int CheckRedPoint()
				{
					KismetFetterGearConfig configByGear = ConfigSingleton<KismetFetterGearConfigCategory>.Instance.GetConfigByGear(self.GetActivityId(), 0);
					if (configByGear == null)
					{
						return 0;
					}
					if (configByGear.Day >= TimeHelper.DaysBetween(TimeHelper.ServerNow(), self.ActivityData.StartTime, 18000000L))
					{
						return 0;
					}
					int[] heroByGear = ConfigSingleton<KismetFetterGearConfigCategory>.Instance.GetHeroByGear(args.ActivityId, 0);
					if (heroByGear == null)
					{
						return 0;
					}
					Hero hero = ((Entity)(object)self).LocalPlayer().GetHero(heroByGear[0]);
					Hero hero2 = ((Entity)(object)self).LocalPlayer().GetHero(heroByGear[1]);
					hero = ((Entity)(object)self).LocalPlayer().GetHero(heroByGear[0]);
					hero2 = ((Entity)(object)self).LocalPlayer().GetHero(heroByGear[1]);
					if (hero == null || hero2 == null)
					{
						return 0;
					}
					KismetFetterGearConfig maxConfig = ConfigSingleton<KismetFetterGearConfigCategory>.Instance.GetMaxConfig(self.GetActivityId());
					if (maxConfig == null)
					{
						return 0;
					}
					int id = maxConfig.Id;
					int currGear = self.GetCurrGear(args.ActivityId);
					if (currGear < id)
					{
						if (currGear == 0)
						{
							if (!hero.IsActive || !hero2.IsActive)
							{
								return 0;
							}
							return 1;
						}
						KismetFetterGearConfig configByGear2 = ConfigSingleton<KismetFetterGearConfigCategory>.Instance.GetConfigByGear(self.GetActivityId(), currGear);
						if (hero.Star < configByGear2.Gear || hero2.Star < configByGear2.Gear)
						{
							return 0;
						}
						return 1;
					}
					return 0;
				}
			}
		}

