		public static void ShowGiftsView(this UIActiveRankingGiftPanel self)
		{
			if (self.GiftConfigDict.Count <= 1)
			{
				return;
			}
			ActiveRankingModule component = ((Entity)self.ActivityData).GetComponent<ActiveRankingModule>();
			List<int> list = self.GiftConfigDict.Keys.ToList();
			list.Sort((int a, int b) => a.CompareTo(b));
			self.LevelKeys?.Clear();
			foreach (int item in list)
			{
				if (component.IsGiftStart(item) && !component.IsGiftOVer(item))
				{
					self.LevelKeys.Add(item);
				}
			}
			self.SetCountDown();
			self._BoxList.SetData(self.LevelKeys.Count);
			int index = self.LevelKeys.FindIndex((int x) => x == self.CurrentSelectLevel);
			self._BoxList.SetSelectIndex(index);
		}

		private static void SetCountDown(this UIActiveRankingGiftPanel self)
		{
			List<ActiveRankingGiftConfig> list = self.GiftConfigDict[self.CurrentSelectLevel];
			list.Sort((ActiveRankingGiftConfig a, ActiveRankingGiftConfig b) => a.Id.CompareTo(b.Id));
			self._TimeCountDownBox.SetCountDown(self.ActivityData.StartTime + (long)list[0].GiftStartTime * 86400000L + (long)list[0].GittExistTime * 86400000L, null, 86400000L);
		}

