					if (!valueOrDefault && ((giftConfig.ResetType == 3 && valueOrDefault2 >= giftConfig.BuyCountLimit) || (giftConfig.ResetType == 2 && valueOrDefault2 >= giftConfig.BuyCountLimit) || (giftConfig.ResetType == 1 && valueOrDefault3 >= giftConfig.AcvtityMaxBuyCount)))
					{
