					}
				}
			}
			if (list.Count != 0)
			{
				foreach (ActiveRankingGiftConfig item in list)
				{
					self.GiftConfigs.Remove(item);
				}
				list.Sort((ActiveRankingGiftConfig x, ActiveRankingGiftConfig y) => x.BuyCountLimit.CompareTo(y.BuyCountLimit));
				self.GiftConfigs.AddRange(list);
			}
			self._ObtainList.SetData(self.GiftConfigs.Count);
			ActivityThemeConfig activityThemeConfig = ConfigSingleton<ActivityThemeConfigCategory>.Instance.Get(self.ActivityData.ActivityId);
			int num = ((activityThemeConfig.Type == 1) ? 2 : 3);
			if (activityThemeConfig.Type == 4)
			{
				num = 4;
			}
			RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.Activity, self.ActId, num);
			if (self.LevelKeys == null || self.LevelKeys.Count <= 0)
			{
				return;
			}
			foreach (int levelKey in self.LevelKeys)
			{
				RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.Activity, self.ActivityData.ActivityId, 2, levelKey);
			}
		}

		private static void OnGiftCellUpdate(this UIActiveRankingGiftPanel self, UIScrollListCell cell)
		{
			((Entity)cell.UIObject).GetComponent<UIActiveRankingGiftItem>().SetGiftData(self.GiftConfigs[cell.Index], self.ActId);
		}

		public static void OnLevelCellCreate(this UIActiveRankingGiftPanel self, UIScrollListCell cell)
		{
			((Entity)cell.UIObject).GetComponent<UIActiveRankingGiftLevel>().SetRefresh(self.OnInitList);
		}

		private static void OnLevelCellUpdate(this UIActiveRankingGiftPanel self, UIScrollListCell cell)
		{
			int index = cell.Index;
			if (index < self.LevelKeys.Count)
			{
				UIActiveRankingGiftLevel component = ((Entity)cell.UIObject).GetComponent<UIActiveRankingGiftLevel>();
				int key = self.LevelKeys[index];
				List<ActiveRankingGiftConfig> list = self.GiftConfigDict[key];
				list.Sort((ActiveRankingGiftConfig a, ActiveRankingGiftConfig b) => a.Id.CompareTo(b.Id));
				ActiveRankingGiftConfig activeRankingGiftConfig = list[0];
				Log.Info("cell update " + activeRankingGiftConfig.LevelName);
				component.SetData(activeRankingGiftConfig.LevelName, cell.Index, self.LevelKeys[index], self.ActivityData);
				component.SetSelect(cell.IsSelected);
			}
		}

		private static void OnInitList(this UIActiveRankingGiftPanel self, int index)
		{
			self.OnClickItem(index);
			self.RefreshData();
		}

		private static void OnClickItem(this UIActiveRankingGiftPanel self, int index, bool isSelected = false)
		{
			if (!((self.CurrentSelectLevel == index) & isSelected))
			{
				self.CurrentSelectLevel = self.LevelKeys[index];
				self.SetCountDown();
				self._BoxList.SetSelectIndex(index);
				UIScrollListCell cell = self._BoxList.GetCell(index);
				if (cell != null)
				{
					((Entity)cell.UIObject).GetComponent<UIActiveRankingGiftLevel>().SetSelect(cell.IsSelected);
				}
			}
		}
	}
