		[UIMethod]
		public static void OnShow(this UIActiveRankingPanel self, (int, UIShowArgs) args)
		{
			Log.Info($"UIActiveRankingPanel.OnShow.param ==  {args.Item1},{args.Item2.Param}");
			(self.ActId, _) = args;
			self.SetTabs(args.Item2.Param - 1);
		}

		[UIMethod]
		public static void OnShow(this UIActiveRankingPanel self, int actid)
		{
			self.ActId = actid;
			self.RefreshView();
		}

		public static void RefreshView(this UIActiveRankingPanel self)
		{
			self.TabIndex = 0;
			self.ActivityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId);
			ActivityThemeConfig activityThemeConfig = ConfigSingleton<ActivityThemeConfigCategory>.Instance.Get(self.ActId);
			if (self.ActivityData.State == ActivityState.Wait && activityThemeConfig.Type == 1)
			{
				LocalData_Confirm localData = ((Entity)(object)self).LocalPlayer().GetLocalData<LocalData_Confirm>();
				localData.Confirms["ActiveRankingPoint"] = TimeHelper.Now();
				((Entity)(object)self).LocalPlayer().SetLocalData(localData);
				if (activityThemeConfig.ActivityIds != null && activityThemeConfig.ActivityIds.Length != 0)
				{
					self.OnActivityOpen(activityThemeConfig.ActivityIds[0]);
				}
				self.SetTabs(0);
				RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.Activity, self.ActivityData.ActivityId);
			}
			else
			{
				self.LoadAllActiveActData();
			}
		}

		public static void RefreshActView(this UIActiveRankingPanel self)
		{
			self.TabIndex = 0;
			self.SetBottomViewActive(active: true);
			self.LoadAllActiveActData();
		}

		private static void OnTabClick(this UIActiveRankingPanel self, int index, UIObject uiObject)
		{
		}

		public static void LoadAllActiveActData(this UIActiveRankingPanel self)
		{
			self.TabInfos?.Clear();
			ActivityThemeConfig activityThemeConfig = ConfigSingleton<ActivityThemeConfigCategory>.Instance.Get(self.ActId);
			if (activityThemeConfig.FuncIds != null && activityThemeConfig.FuncIds.Length != 0)
			{
				for (int i = 0; i < activityThemeConfig.FuncIds.Length; i++)
				{
					self.OnFuncOpen(activityThemeConfig.FuncIds[i]);
					self.TabIndex++;
				}
			}
			if (activityThemeConfig.ActivityIds != null && activityThemeConfig.ActivityIds.Length != 0)
			{
				for (int j = 0; j < activityThemeConfig.ActivityIds.Length; j++)
				{
					self.OnActivityOpen(activityThemeConfig.ActivityIds[j]);
					self.TabIndex++;
				}
			}
			if (activityThemeConfig.OtherPanels != null && activityThemeConfig.OtherPanels.Length != 0)
			{
				for (int k = 0; k < activityThemeConfig.OtherPanels.Length; k++)
				{
					self.OnOtherPanelsOpen(activityThemeConfig.OtherPanels[k], k);
					self.TabIndex++;
				}
			}
			ActiveRankingModule component = ((Entity)ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId)).GetComponent<ActiveRankingModule>();
			int tabIndex = 0;
			switch (ConfigSingleton<ActivityThemeConfigCategory>.Instance.Get(self.ActId).Type)
			{
			case 1:
				((Entity)(object)self).LocalPlayer().SetLocalBool("ActivityRankingOpenState", value: true);
				self.SetTabs(tabIndex);
				break;
			case 2:
			{
				tabIndex = (component.IsHaveGiftRewardCanGet() ? 2 : 0);
				int[] activityIds = activityThemeConfig.ActivityIds;
				foreach (int num in activityIds)
				{
					if (RedPointHelper.GetCount(SceneHelper.DomainScene((Entity)(object)self), RedPointType.Activity, num) >= 1)
					{
						tabIndex = 0;
						break;
					}
				}
				self.SetTabs(tabIndex);
				break;
			}
			case 3:
				self.SetTabs(tabIndex);
				break;
			case 4:
				self.SetTabs(tabIndex);
				break;
			}
		}

		public static void SetTabs(this UIActiveRankingPanel self, int tabIndex)
		{
			self._UICommonPanelBottom.SetTabs(self.TabInfos.ToArray(), tabIndex);
		}

		public static void SetTabsWithActivityType(this UIActiveRankingPanel self, int actId)
		{
			foreach (UITabInfo tabInfo in self.TabInfos)
			{
				if (tabInfo.GetArgs() is UIActivityShowArgs uIActivityShowArgs && uIActivityShowArgs.SubActId == actId)
				{
					int num = tabInfo.Sort();
					self._UICommonPanelBottom.SetTabs(self.TabInfos.ToArray(), num - 1);
				}
			}
		}

		private static void OnFuncOpen(this UIActiveRankingPanel self, int funcId)
		{
			if (ConfigSingleton<FuncConfigCategory>.Instance.Get(funcId) != null && ((Entity)(object)self).LocalPlayer().IsFuncOpen(funcId))
			{
				ActivityThemeConfig activityThemeConfig = ConfigSingleton<ActivityThemeConfigCategory>.Instance.Get(self.ActId);
				UITabInfo uITabInfo = UITabInfo.CreateWithFunc(funcId).SetText(activityThemeConfig.TabName.Split("_")[self.TabIndex]);
				int num = activityThemeConfig.TabSort[self.TabIndex];
				_ = activityThemeConfig.TabName.Split("_")[num - 1];
				uITabInfo.SetSort(num);
				self.TabInfos.Add(uITabInfo);
			}
		}

		private static void OnOtherPanelsOpen(this UIActiveRankingPanel self, string panelName, int index)
		{
			ActivityThemeConfig activityThemeConfig = ConfigSingleton<ActivityThemeConfigCategory>.Instance.Get(self.ActId);
			long num = self.ActivityData.EndTime - TimeHelper.Now();
			if (num <= 0 || num > 86400000 || !activityThemeConfig.IsShowRankOneDay || ActiveRankingHelper.IsShowActiveRankingPanel(panelName))
			{
				int num2 = activityThemeConfig.TabSort[self.TabIndex];
				UITabInfo uITabInfo = UITabInfo.Create(activityThemeConfig.TabName.Split("_")[num2 - 1], panelName);
				uITabInfo.SetSort(num2);
				uITabInfo.SetArgs(ActiveRankingHelper.GetPanelName(panelName, self.ActId));
				if (panelName == "UIGodWillGuidePanel")
				{
					uITabInfo.SetTipsConfigId(22);
				}
				uITabInfo.SetRedPoint(RedPointType.Activity, self.ActId, activityThemeConfig.TabSort[self.TabIndex]);
				self.TabInfos.Add(uITabInfo);
			}
		}

		private static void OnActivityOpen(this UIActiveRankingPanel self, int activityId)
		{
			ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), activityId);
			if (activityData != null)
			{
				ActivityThemeConfig activityThemeConfig = ConfigSingleton<ActivityThemeConfigCategory>.Instance.Get(self.ActId);
				Type uI = ActivityMainUIComponent.Instance.GetUI(activityData.ActivityType, activityData.BaseInfo.SubType, isSubView: false);
				if (uI == null)
				{
					uI = ActivityMainUIComponent.Instance.GetUI(activityData.ActivityType, activityData.BaseInfo.SubType, isSubView: true);
				}
				int num = activityThemeConfig.TabSort[self.TabIndex];
				UITabInfo uITabInfo = UITabInfo.Create(activityThemeConfig.TabName.Split("_")[num - 1], uI.Name);
				uITabInfo.SetSort(num);
				uITabInfo.SetArgs(new UIActivityShowArgs
				{
					MainActId = self.ActId,
					SubActId = activityData.ActivityId
				});
				uITabInfo.SetRedPoint(RedPointType.Activity, activityData.ActivityId);
				self.TabInfos.Add(uITabInfo);
			}
		}

		public static void SetBottomViewActive(this UIActiveRankingPanel self, bool active)
		{
			self._UICommonPanelBottom.UIObject.SetActive(active);
		}

		public static void SetSubViewSize(this UIActiveRankingPanel self, int size)
		{
		}
	}
