		private static void UpdateView(this UIActiveRankingCarnivalObtainPanel self)
		{
			self.IsLock = false;
			ActiveRankingCarnivalBaseConfig config = ConfigSingleton<ActiveRankingCarnivalBaseConfigCategory>.Instance.GetConfig(self.ActivityData.ActivityId, self.Stage);
			ActiveRankingCarnivalModule component = ((Entity)self.ActivityData).GetComponent<ActiveRankingCarnivalModule>();
			int currentStage = ((Entity)self.ActivityData).GetComponent<ActiveRankingCarnivalModule>().GetCurrentStage();
			if (currentStage > self.Stage || currentStage == -1)
			{
				self._TimeText.SetText("阶段已结束");
			}
			else
			{
				long startTime = self.ActivityData.StartTime;
				if (currentStage == self.Stage)
				{
					self.TargetTime = startTime + (long)config.CycleStage * 86400000L;
				}
				else
				{
					self.TargetTime = startTime + (long)(config.CycleStage - 1) * 86400000L;
					self.IsLock = true;
				}
				self.StartTime();
			}
			self._CommonPopup.SetTitle(((component.GetStageCount() > 1) ? Language.Format(3, 253, config.Stage) : "") + config.StageDesc);
			self.Configs = ConfigSingleton<ActiveRankingCarnivalShowTaskConfigCategory>.Instance.GetConfigs(self.ActivityData.ActivityId, self.Stage);
			if (self.Configs == null || self.Configs.Count == 0)
			{
				self.Configs = ConfigSingleton<ActiveRankingCarnivalShowTaskConfigCategory>.Instance.GetConfigs(self.ActivityData.ActivityId, config.CycleStage);
			}
			self._List.SetData(self.Configs.Count);
		}

