		private static void StartTime(this UIActiveRankingCarnivalObtainPanel self)
		{
			if (self.TimeId <= 0)
			{
				self.TimeId = self.NewTimer(1000L, self.OnTimeUpdate, repeat: true);
			}
			self.OnTimeUpdate();
		}

		private static void OnTimeUpdate(this UIActiveRankingCarnivalObtainPanel self)
		{
