		private static void UpdateBigStageReward(this UIActiveRankingCarnivalPanel self)
		{
			self.SetTextShow(show: false);
			ActiveRankingCarnivalModule component = ((Entity)self.ActivityData).GetComponent<ActiveRankingCarnivalModule>();
			foreach (ActiveRankingCarnivalBaseConfig baseConfig in self.BaseConfigs)
			{
				if (baseConfig.StageBigRewards == null || component.IsGetStageBigReward(baseConfig.Stage))
				{
					continue;
				}
				self._BigRewardStageText.SetText($"{component.EndlessStage}/{baseConfig.Stage}");
				if (baseConfig.CycleStage != 0)
				{
					int num = self.BaseConfigs.Count - 2 + baseConfig.CycleInterval;
					if (component.EndlessRewardStage != 0)
					{
						num = component.EndlessRewardStage;
					}
					self._BigRewardStageText.SetText($"{component.EndlessStage}/{num}");
					self.SetTextShow(show: false, 2);
				}
				self._RewardList.SetData(baseConfig.StageBigRewards);
				self.BigRewardStage = baseConfig.Stage;
				if (baseConfig.CycleStage == 0 && component.BigRewardStatusDict.GetValueOrDefault(self.BaseConfigs[self.BigRewardStage].Stage) == 2)
				{
					self.SetTextShow(show: true);
				}
				break;
			}
			foreach (var (num4, num5) in component.BigRewardStatusDict)
			{
				if (num5 != 0 && num5 != 1 && num4 > self.BaseConfigs.Count - 2)
				{
					ActiveRankingCarnivalBaseConfig activeRankingCarnivalBaseConfig = self.BaseConfigs[^1];
					self._RewardList.SetData(activeRankingCarnivalBaseConfig.StageBigRewards);
					self.BigRewardStage = num4;
					self._BigRewardStageText.SetText($"{component.EndlessStage}/{num4}");
					self.SetTextShow(show: true, 2);
					break;
				}
			}
		}

