		private static void RefreshData(this UIActiveRankingCarnivalScoreRewardPanel self)
		{
			List<ActiveRankingCarnivalBaseConfig> all = ConfigSingleton<ActiveRankingCarnivalBaseConfigCategory>.Instance.GetAll(self.ActivityData.ActivityId);
			ActiveRankingCarnivalModule component = ((Entity)self.ActivityData).GetComponent<ActiveRankingCarnivalModule>();
			self.BaseConfigs?.Clear();
			List<ActiveRankingCarnivalBaseConfig> list = new List<ActiveRankingCarnivalBaseConfig>();
			foreach (ActiveRankingCarnivalBaseConfig item in all)
			{
				if (item.StageBigRewards != null)
				{
					if (component.IsGetStageBigReward(item.Stage))
					{
						list.Add(item);
					}
					else
					{
						self.BaseConfigs.Add(item);
					}
				}
			}
			self.BaseConfigs.AddRange(list);
			self._RewardList.SetData(self.BaseConfigs.Count);
		}

		private static void OnCellUpdate(this UIActiveRankingCarnivalScoreRewardPanel self, UIScrollListCell cell)
		{
			int index = cell.Index;
			int index2 = index + 1;
			if (index + 1 >= self.BaseConfigs.Count - 1)
			{
				index2 = self.BaseConfigs.Count - 1;
			}
			((Entity)cell.UIObject).GetComponent<UIActiveRankingCarnivalScoreRewardItem>().SetData(self.ActivityData, self.BaseConfigs[index], self.BaseConfigs[index2]);
		}
	}
