		private static void SelectStage(this UIActiveRankingCrossPanel self, int index)
		{
			LegendShowModule component = ((Entity)self.ActivityData).GetComponent<LegendShowModule>();
			int stageCount = component.GetStageCount();
			int currentStage = component.GetCurrentStage();
			if (stageCount > 1 && index > currentStage && index != 0 && component.IsBetweenActivity())
			{
				UIManager.Instance.Show<UILegendShowObtainPanel, (int, int)>((self.ActivityData.ActivityId, self.BaseConfigs[index].Stage)).Coroutine();
				return;
			}
			self._DateTextAllRank.SetActive(index != 0 && stageCount > 1);
			self._AllRankDes.SetText(Language.Get(3, 269));
			self._AllRankDes.SetActive(index == 0 && stageCount > 1);
			self.RankButtonIndex = 0;
			self.StageIndex = index;
			LegendShowBaseConfig legendShowBaseConfig = self.BaseConfigs[self.StageIndex];
			self._TitleTextAllRank.SetText(legendShowBaseConfig.StageDesc);
			self._DateText.SetText($"第{legendShowBaseConfig.Stage}天");
			if (!string.IsNullOrEmpty(legendShowBaseConfig.StageBg))
			{
				self._Bg.SetRawTexture(legendShowBaseConfig.StageBg).Coroutine();
			}
			int key;
			UIObject value;
			foreach (KeyValuePair<int, UIObject> item in self.StageObjectDict)
			{
				item.Deconstruct(out key, out value);
				int i = key;
				((Entity)value).GetComponent<UIStageCrossItem>().SetSelected(i, self.StageIndex, currentStage, self.ActivityData);
			}
			foreach (KeyValuePair<int, UIObject> item2 in self.RankButtonObjectDict)
			{
				item2.Deconstruct(out key, out value);
				int num = key;
				((Entity)value).GetComponent<RankButton>().SetSelected(num == self.RankButtonIndex);
			}
			self.UpdateButtonView();
			self.RankButtonOldIndex = -1;
			self.StageOldIndex = self.StageIndex;
			self.UpdateView();
		}

