			int myRank = component.GetMyRank(item, self.Stage, ((Entity)((Entity)(object)self).LocalPlayer()).Id);
			if (item2.RankNo == 0 && self.Stage != 0)
			{
				self._SelfRankItem.SetSelfData(myRank, component.GetStageScore(self.Stage), self.Stage, self.ActivityData.ActivityId);
