		private static void SetZoneRank(this UIActiveRankingCrossShowRankPanel self)
		{
			int zoneCount = self.GetZoneCount();
			if (!self.RankListZoneDict.ContainsKey(LegendShowHelper.GetCrossRankType(self.Stage)))
			{
				for (int i = 0; i < zoneCount; i++)
				{
					self.RankInfoItems.Add(new ActiveRankInfoItem
					{
						Type = 2,
						Zone = 0,
						RankInfo = null
					});
				}
				return;
			}
			List<RankInfo> item = self.RankListZoneDict[LegendShowHelper.GetCrossRankType(self.Stage)].Item1;
			for (int j = 0; j < item.Count; j++)
			{
				if (j + 1 <= zoneCount)
				{
					self.RankInfoItems.Add(new ActiveRankInfoItem
					{
						Type = 2,
						Zone = (int)item[j].Id,
						RankInfo = item[j]
					});
				}
			}
			if (zoneCount > item.Count)
			{
				for (int k = 0; k < zoneCount - item.Count; k++)
				{
					self.RankInfoItems.Add(new ActiveRankInfoItem
					{
						Type = 2,
						Zone = 0,
						RankInfo = null
					});
				}
			}
		}

		private static void SetPersonRank(this UIActiveRankingCrossShowRankPanel self)
		{
			int zoneCount = self.GetZoneCount();
			List<LegendShowRankLimitConfig> configs = ConfigSingleton<LegendShowRankLimitConfigCategory>.Instance.GetStageConfigs(self.ActivityData.ActivityId, self.Stage);
			if (!self.RankListDict.ContainsKey(LegendShowHelper.GetRankType(self.Stage)))
			{
				foreach (LegendShowRankLimitConfig item2 in configs)
				{
					self.RankInfoItems.Add(new ActiveRankInfoItem
					{
						Type = 1,
						LimitConfig = item2,
						RankInfo = null
					});
				}
				return;
			}
			List<RankInfo> item = self.RankListDict[LegendShowHelper.GetRankType(self.Stage)].Item1;
			int i;
			for (i = 0; i < configs.Count; i++)
			{
				List<RankInfo> list = null;
				if (i > 0)
				{
					Log.Info($"{configs[i].MinScore}   {configs[i - 1].MinScore}");
					list = item.FindAll((RankInfo x) => x.Value >= configs[i].MinScore && x.Value < configs[i - 1].MinScore);
				}
				else
				{
					list = item.FindAll((RankInfo x) => x.Value >= configs[i].MinScore);
				}
				if (list.Count > 0)
				{
					foreach (RankInfo item3 in list)
					{
						self.RankInfoItems.Add(new ActiveRankInfoItem
						{
							Type = 1,
							LimitConfig = null,
							RankInfo = item3
						});
					}
					_ = list.Count;
				}
				else if (i > self.RankInfoItems.Count - 1 - zoneCount - 2)
				{
					self.RankInfoItems.Add(new ActiveRankInfoItem
					{
						Type = 1,
						LimitConfig = configs[i],
						RankInfo = null
					});
				}
			}
		}

		private static int GetZoneCount(this UIActiveRankingCrossShowRankPanel self)
		{
			int result = 0;
			if (self.ActivityData.BaseInfo.CrossType == 3)
			{
				result = 2;
			}
			if (self.ActivityData.BaseInfo.CrossType == 4)
			{
				result = 4;
			}
			if (!self.isOpen)
			{
				result = 2;
			}
			return result;
		}

		private static void StartTime(this UIActiveRankingCrossShowRankPanel self)
		{
			if (self.TimeId <= 0)
			{
				self.TimeId = self.NewTimer(1000L, self.OnTimeUpdate, repeat: true);
			}
			self.OnTimeUpdate();
		}

		private static void StopTime(this UIActiveRankingCrossShowRankPanel self)
		{
			if (self.TimeId > 0)
			{
				self.RemoveTimer(ref self.TimeId);
			}
		}

		private static void OnTimeUpdate(this UIActiveRankingCrossShowRankPanel self)
		{
			long num = TimeHelper.Now();
			long num2 = math.abs(self.TargetTime - num);
			TimeSpan timeSpan = TimeSpan.FromSeconds((double)(num2 / 1000));
			if (num2 >= 86400000)
			{
				timeSpan.ToString(Language.Get(2, 312));
			}
			else
			{
				timeSpan.ToString("hh\\:mm\\:ss");
			}
			_ = self.IsLock;
		}

		private static void OnCellUpdate(this UIActiveRankingCrossShowRankPanel self, UIScrollListCell cell)
		{
			int index = cell.Index;
			ActiveRankInfoItem activeRankInfoItem = self.RankInfoItems[index];
			Log.Info($"OnCellUpdate == {index}  type == {activeRankInfoItem.Type}");
			switch (activeRankInfoItem.Type)
			{
			case 0:
				((Entity)cell.UIObject).GetComponent<UIActiveRankingCrossTitleItem>().SetData(activeRankInfoItem.Title, index, isRank: true, self.ActivityData.CrossType == CrossType.BigLink);
				((Entity)cell.UIObject).GetComponent<UIActiveRankingCrossTitleItem>().SetArrowRotation(self.isOpen);
				break;
			case 1:
			{
				int num = 2;
				if (self.ActivityData.BaseInfo.CrossType == 3)
				{
					num += 2;
				}
				if (self.ActivityData.BaseInfo.CrossType == 4)
				{
					num += (self.isOpen ? 4 : 2);
				}
				((Entity)cell.UIObject).GetComponent<UIActiveRankingCrossShowRankItem>().SetData(activeRankInfoItem, index - num, self.ActivityData.ActivityId, self.Stage);
				break;
			}
			case 2:
				((Entity)cell.UIObject).GetComponent<UIActiveRankingCrossRankZoneItem>().SetData(activeRankInfoItem, index - 1, self.ActivityData.ActivityId, self.Stage);
				break;
			}
		}
	}
