			long startTime = self.ActivityData.StartTime;
			long endTime = self.ActivityData.EndTime;
			self._WaitTimeText.SetText(TimeHelper.ToDateTime(startTime).ToString("yyyy/MM/dd") + " - " + TimeHelper.ToDateTime(endTime).ToString("yyyy/MM/dd"));
