		private static void OnWaitTimeUpdate(this UIActiveRankingCrossWaitPanel self)
		{
			long num = TimeHelper.Now();
			if (self.WaitTargetTime <= num)
			{
				ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActivityId);
				if (activityData.State != ActivityState.Wait)
				{
					self.StopTime();
					UIObject.FindUIObjectOfType<UIActiveRankingPanel>()?.RefreshActView();
					UIObject.FindUIObjectOfType<UIActiveRankingCrossPanel>()?.SetActiveData(self.ActivityId);
					UIObject.FindUIObjectOfType<UIActiveRankingCrossPanel>()?.ShowOpen();
					self.ActivityData = activityData;
					self.UIObject.SetActive(active: false);
				}
			}
			else
			{
				long num2 = self.WaitTargetTime - num;
				TimeSpan timeSpan = TimeSpan.FromSeconds((double)(num2 / 1000));
				string text = ((num2 < 86400000) ? timeSpan.ToString("hh\\:mm\\:ss") : timeSpan.ToString(Language.Get(2, 312)));
				self._TimeText.SetText(text ?? "");
			}
		}

