		private static void ShowPersonContent(this UIActiveRankingCrossWaitReward self)
		{
			self._PersonContent.SetActive(active: true);
			self._ZoneContent.SetActive(active: false);
			self.RankConfigs = ConfigSingleton<LegendShowRankConfigCategory>.Instance.GetStageConfigs(self.ActivityData.ActivityId, 0);
			self.RankConfigs = self.RankConfigs.FindAll((LegendShowRankConfig x) => x.Zone.Equals(0));
			self._UIPersonRewardScroll.SetData(self.RankConfigs.Count);
			LegendShowBaseConfig legendShowBaseConfig = self.BaseConfigs[0];
			self._FirstBigModel.ShowHighModel(new UIModelInfo(legendShowBaseConfig.ModelIdFisrt)
			{
				AnimName = "ShowIdle"
			}).Coroutine();
			self._SceondBigModel.ShowHighModel(new UIModelInfo(legendShowBaseConfig.ModelIdSceond)
			{
				AnimName = "ShowIdle"
			}).Coroutine();
			self._ThirdBigModel.ShowHighModel(new UIModelInfo(legendShowBaseConfig.ModelIdThird)
			{
				AnimName = "ShowIdle"
			}).Coroutine();
			string[] array = new string[3];
			array = legendShowBaseConfig.PreviewRewradName.Split("_");
			self._FirstBigModelName.SetText((array.Length != 0) ? array[0] : "");
			self._SceondBigModelName.SetText((array.Length > 1) ? array[1] : "");
			self._ThirdBigModelName.SetText((array.Length > 2) ? array[2] : "");
		}

