			{
				UIActiveRankingCrossWaitRewardItem component = ((Entity)cell.UIObject).GetComponent<UIActiveRankingCrossWaitRewardItem>();
				ActiveRewardInfoItem item = new ActiveRewardInfoItem
				{
					Id = self.RankConfigs[index].Id,
					RankConfig = self.RankConfigs[index],
					Zone = self.RankConfigs[index].Zone
				};
				component.SetData(item);
			}
		}

