		public static void SetData(this UIActiveRankingPreviewItem self, int index, ActiveRankingPreviewConfig config, int actId, Action _callback = null)
		{
			//IL_00f4: Unknown result type (might be due to invalid IL or missing references)
			//IL_00de: Unknown result type (might be due to invalid IL or missing references)
			//IL_0131: Unknown result type (might be due to invalid IL or missing references)
			//IL_011b: Unknown result type (might be due to invalid IL or missing references)
			self.ActId = actId;
			self.ActivityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), config.Id);
			self._callback = _callback;
			self.Config = config;
			self._RewardImg.SetRawTexture(config.GiftBgImg, nativeSize: true).Coroutine();
			self._TitleText.SetText(self.ActivityData.Name);
			self._RewardList.SetData(self.Config.RewadItems);
			self.isOpening = TimeHelper.Now() >= self.ActivityData.StartTime;
			self._BgImg.SetRawTexture(self.isOpening ? "ui_xbdyg_frame_03" : config.BgImg).Coroutine();
			((Component)self._TitleText.Transform).GetComponent<SuperOutline>().effectColor = (self.isOpening ? new Color(0.6392157f, 1f / 3f, 0.18039216f) : new Color(0.20784314f, 23f / 51f, 0.6039216f));
			self._RewardDesText.SetColor(self.isOpening ? new Color(61f / 85f, 0.56078434f, 0.41960785f) : new Color(20f / 51f, 49f / 85f, 58f / 85f));
			self._TimeCountDownText.SetText(self.isOpening ? "进行中" : "00:00:00");
			if (self.ActivityData.StartTime > TimeHelper.Now())
			{
				if (self.CountDownTimer <= 0)
				{
					self.SetCountDown(self.ActivityData.StartTime, 86400000L, self.EndTimer);
				}
			}
			else if (self.CountDownTimer > 0)
			{
				self.RemoveTimer(ref self.CountDownTimer);
			}
		}

		private static void EndTimer(this UIActiveRankingPreviewItem self)
		{
			Log.Info("UIActiveRankingPreviewItem EndTimer ...");
		}

		private static void SetCountDown(this UIActiveRankingPreviewItem self, long endTime, long changeColorTime = 0L, Action closeCallBack = null)
		{
			if (self.CountDownTimer > 0)
			{
				self.RemoveTimer(ref self.CountDownTimer);
			}
			self.CountDownTimer = self.NewTimer(1000L, RefreshTime, repeat: true);
			RefreshTime();
			void RefreshTime()
			{
				long num = TimeHelper.Now();
				long num2 = endTime - num;
				if (num2 < 0)
				{
					num2 = 0L;
				}
				string text = null;
				if (changeColorTime > 0)
				{
					text = ((num2 < changeColorTime) ? "#ff3232" : "#5dfa49");
				}
				TimeSpan timeSpan = TimeSpan.FromSeconds((float)num2 / 1000f);
				string text2 = ((num2 < 86400000) ? timeSpan.ToString("hh\\:mm\\:ss") : timeSpan.ToString(Language.Get(2, 312)));
				if (text != null)
				{
					text2 = "<color=" + text + ">" + text2 + "</color>";
				}
				self._TimeCountDownText.SetText(text2);
				if (num2 == 0L)
				{
					text = "#ff3232";
					text2 = "<color=" + text + ">" + Language.Get(3, 242) + "</color>";
					self._TimeCountDownText.SetText(text2);
					closeCallBack?.Invoke();
					self.RemoveTimer(ref self.CountDownTimer);
				}
			}
		}

		private static void CountDown(this UIActiveRankingPreviewItem self)
		{
			string str = TimeSpan.FromSeconds((double)(self.ActivityData.EndTime / 1000)).ToString("hh\\:mm\\:ss");
			self._TimeCountDownText.SetText(str);
		}

		[UIMethod]
		public static void OnDestroy(this UIActiveRankingPreviewItem self)
		{
			if (self.CountDownTimer > 0)
			{
				self.RemoveTimer(ref self.CountDownTimer);
			}
		}
	}
