		[UIMethod]
		public static void OnShow(this UIActiveRankingPreviewPanel self, int _actID)
		{
			//IL_00ad: Unknown result type (might be due to invalid IL or missing references)
			self.ActId = _actID;
			self.ActivityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), _actID);
			ActiveRankingPreviewBaseConfig activeRankingPreviewBaseConfig = ConfigSingleton<ActiveRankingPreviewBaseConfigCategory>.Instance.Get(self.ActId);
			if (activeRankingPreviewBaseConfig != null)
			{
				self._FrameBg.SetRawTexture(activeRankingPreviewBaseConfig.BannerPic).Coroutine();
				self._TtitleImg.SetRawTexture(activeRankingPreviewBaseConfig.TitleImg, nativeSize: true).Coroutine();
			}
			self._UICommonPanelBottom.UIObject.SetActive(self.ActivityData.SubType < (ActivitySubType)20000);
			if (self.ActivityData.SubType < (ActivitySubType)20000)
			{
				((Component)self._SubView.Transform).GetComponent<RectTransform>().sizeDelta = new Vector2(0f, -126f);
			}
			self.RefreshData();
		}

		private static void RefreshData(this UIActiveRankingPreviewPanel self)
		{
			self.Configs?.Clear();
			List<ActiveRankingPreviewConfig> list = new List<ActiveRankingPreviewConfig>();
			foreach (var (activityId, item) in ConfigSingleton<ActiveRankingPreviewConfigCategory>.Instance.GetAll())
			{
				ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), activityId);
				if (activityData != null && TimeHelper.Now() < activityData.EndTime)
				{
					Log.Info($"starttime === {TimeHelper.ToDateTime(activityData.StartTime)}     endtime === {TimeHelper.ToDateTime(activityData.EndTime)}");
					list.Add(item);
				}
			}
			list.Sort((ActiveRankingPreviewConfig a, ActiveRankingPreviewConfig b) => ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), a.Id).StartTime.CompareTo(ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), b.Id).StartTime));
			self.Configs = list.Skip(0).Take(ConfigSingleton<ActiveRankingPreviewBaseConfigCategory>.Instance.Get(self.ActId).MaxCount).ToList();
			self._ActivityList.SetData(self.Configs.Count);
		}

		private static void OnCellUpdate(this UIActiveRankingPreviewPanel self, UIScrollListCell cell)
		{
			if (cell.Index < self.Configs.Count)
			{
				((Entity)cell.UIObject).GetComponent<UIActiveRankingPreviewItem>().SetData(cell.Index, self.Configs[cell.Index], self.ActId);
			}
		}

		public static void RefreshList(this UIActiveRankingPreviewPanel self)
		{
		}
	}
