	[RedPointHandler(RedPointType.ActivityCenter)]
	public class ActivityCenterRedPointHandler : ARedPointHandler
	{
		public override int GetCount(Scene scene, params int[] parameters)
		{
			int num = 0;
			Player player = ((Entity)(object)scene).LocalPlayer();
			PlayerActivityComponent component = ((Entity)player).GetComponent<PlayerActivityComponent>();
			if (component == null)
			{
				return 0;
			}
			int num2 = ((parameters != null && parameters.Length != 0) ? parameters[0] : 0);
			int funcId = ((parameters != null && parameters.Length > 1) ? parameters[1] : 0);
			if (num2 == 0)
			{
				return 0;
			}
			foreach (int item in ((Entity)player).GetComponent<FuncModule>().GetFuncListByView(funcId))
			{
				if (player.CheckFuncOpen(item) && Enum.TryParse<RedPointType>(ConfigSingleton<FuncConfigCategory>.Instance.Get(item).RedPointType, out var result))
				{
					num = RedPointHelper.GetCount(scene, result);
					if (num > 0)
					{
						return num;
					}
				}
			}
			foreach (ActivityData item2 in ((Entity)component).Children.Values.Cast<ActivityData>())
			{
				if (item2.IsClose() || !item2.IsShow((ActivityCenterType)num2))
				{
					continue;
				}
				Entity val = ((Entity)item2).Components.Values.FirstOrDefault();
				if (item2.BaseInfo.HideMainRed <= 0 || (item2.BaseInfo.HideMainRed & num2) == 0)
				{
					Singleton<EventSystem>.Instance.InvokeEntityMethod<ActivityEvent_RedPoint, int>(val, new ActivityEvent_RedPoint
					{
						ActivityId = item2.ActivityId
					}, ref num, (SceneType)(-1));
					if (num > 0)
					{
						return num;
					}
				}
			}
			return num;
		}
	}
