			});
		}

		[UIMethod]
		public static void OnShow(this UIActivityInfoPanel self, (UIObject diffRect, ActivityBaseInfo info) showArgs)
		{
			self.DiffRect = showArgs.diffRect;
			self.ActivityBaseInfo = showArgs.info;
			if (((Entity)self).GetComponent<UICommonAdapter>() == null)
			{
				((Entity)self).AddComponent<UICommonAdapter, UIObject, UIObject, UIObject>(self.DiffRect, self.UIObject, self._BackGroup, false);
			}
			if (self.ActivityBaseInfo.EndTime - self.ActivityBaseInfo.StartTime > 315360000000L)
			{
				self._TxtTime.SetText("常驻活动");
			}
			else
			{
				self._TxtTime.SetText(TimeHelper.ToDateTime(self.ActivityBaseInfo.StartTime).ToString("yyyy-MM-dd HH:mm") + " - " + TimeHelper.ToDateTime(self.ActivityBaseInfo.EndTime).ToString("yyyy-MM-dd HH:mm"));
			}
			self._TxtName.SetText(self.ActivityBaseInfo.Name);
			self._TxtDesc.SetText(self.ActivityBaseInfo.Description);
			self._ImgIcon.SetRawTexture(self.ActivityBaseInfo.Icon, nativeSize: true).Coroutine();
			if (self.ActivityBaseInfo.Items != null)
			{
				self.Items.Clear();
				self._UIScrollList.SetData(self.ActivityBaseInfo.Items.Count);
			}
			long num = TimeHelper.ServerNow();
			if (self.ActivityBaseInfo.EndTime < num)
			{
				self._BtnGoTo.SetActive(active: false);
				self._TxtStartTime.SetActive(active: true);
				self._TxtStartTime.SetText("已结束");
				return;
			}
			if (self.ActivityBaseInfo.StartTime <= num)
			{
				self._BtnGoTo.SetActive(active: true);
				self._TxtStartTime.SetActive(active: false);
				return;
			}
			self._TxtStartTime.SetActive(active: true);
			self._BtnGoTo.SetActive(active: false);
			UpdateCountdownText(self);
			self.Timer = self.NewTimer(1000L, delegate
			{
				self.ShowTime = self.ActivityBaseInfo.StartTime - TimeHelper.ServerNow();
				if (self.ShowTime <= 0)
				{
					self.RemoveTimer(ref self.Timer);
					self.Timer = 0L;
					self._BtnGoTo.SetActive(active: true);
					self._TxtStartTime.SetActive(active: false);
				}
				else
				{
					UpdateCountdownText(self);
				}
			}, repeat: true);
		}

		private static void UpdateCountdownText(UIActivityInfoPanel self)
		{
			self.ShowTime = self.ActivityBaseInfo.StartTime - TimeHelper.ServerNow();
			long num = self.ShowTime / 1000;
			long num2 = num / 86400;
			long num3 = num % 86400 / 3600;
			long num4 = num % 3600 / 60;
			long num5 = num % 60;
			string str = ((num2 > 0) ? string.Format("距离活动开启：{0}天 {1:D2}:{2:D2}:{3:D2}", new object[4] { num2, num3, num4, num5 }) : $"距离活动开启：{num3:D2}:{num4:D2}:{num5:D2}");
			self._TxtStartTime.SetText(str);
		}

