		private static void OnFuncOpen(this UIActivityPanel self, int funcId)
		{
			if (self.SubFuncIds.Contains(funcId))
			{
				UITabInfo uITabInfo = UITabInfo.CreateWithFunc(funcId);
				FuncConfig funcConfig = ConfigSingleton<FuncConfigCategory>.Instance.Get(funcId);
				if (Enum.TryParse<RedPointType>(funcConfig.RedPointType, out var result))
				{
					uITabInfo.SetRedPoint(result);
				}
				uITabInfo.SetSort(funcConfig.Sort);
				self.Tabs.Add(uITabInfo);
				self.SortTabs();
				self.SetTabs().Coroutine();
			}
		}

		private static void OnFuncClose(this UIActivityPanel self, int funcId)
		{
			if (!self.SubFuncIds.Contains(funcId))
			{
				return;
			}
			for (int i = 0; i < self.Tabs.Count; i++)
			{
				UITabInfo uITabInfo = self.Tabs[i];
				if (uITabInfo.TabIdType == UITabIdType.Func && uITabInfo.FuncId == funcId)
				{
					self.Tabs.RemoveAt(i);
					if (Enum.TryParse<RedPointNodeType>(ConfigSingleton<FuncConfigCategory>.Instance.Get(funcId).RedPointType, out var result))
					{
						RedPointTreeComponent.Instance.RemoveDependents(self.RedPointNodeType, true, result);
					}
					break;
				}
			}
			self.SetTabs().Coroutine();
		}

		private static void OnActivityAdd(this UIActivityPanel self, int activityId)
		{
			self.Tabs.RemoveAll((UITabInfo tab) => tab.FuncId == activityId);
			ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), activityId);
			UITabInfo uITabInfo = UITabInfo.CreateWithActivity(activityId);
			uITabInfo.SetIcon(activityData.GetIcon(), activityData.GetIconEffect());
			uITabInfo.Text = activityData.Name;
			uITabInfo.SetSort(activityData.Sort);
			Type uI = ActivityMainUIComponent.Instance.GetUI(activityData.ActivityType, activityData.BaseInfo.ActivityType, isSubView: true);
			if (uI != null)
			{
				uITabInfo.SetUIName(uI.Name);
			}
			uITabInfo.SetRedPoint(RedPointType.Activity, activityId);
			self.Tabs.Add(uITabInfo);
			self.SortTabs();
			self.SetTabs().Coroutine();
		}

		private static void SortTabs(this UIActivityPanel self)
		{
			self.Tabs.Sort(UITabInfoSystem.CompareTo);
		}

		private static void OnActivityRemove(this UIActivityPanel self, int activityId)
		{
			for (int i = 0; i < self.Tabs.Count; i++)
			{
				if (self.Tabs[i].TabIdType == UITabIdType.Activity && self.Tabs[i].FuncId == activityId)
				{
					self.Tabs.RemoveAt(i);
					break;
				}
			}
			self.SetTabs().Coroutine();
		}

		private static void InitRecharge(this UIActivityPanel self)
		{
			self.ActivityCenterType = ActivityCenterType.RechargePanel;
		}

		private static void InitPrivilege(this UIActivityPanel self)
		{
			self.ActivityCenterType = ActivityCenterType.ActivityPrivilegeCenter;
		}

		private static void InitGreatActivity(this UIActivityPanel self)
		{
			self.ActivityCenterType = ActivityCenterType.GreatActivity;
		}

		private static void InitWonderfulActivity(this UIActivityPanel self)
		{
			self.ActivityCenterType = ActivityCenterType.WonderfulCenter;
		}

		private static void InitSelectGiftActivity(this UIActivityPanel self)
		{
			self.ActivityCenterType = ActivityCenterType.ActivitySelectGift;
		}

		private static void InitNormalActivity(this UIActivityPanel self)
		{
			self.ActivityCenterType = ActivityCenterType.NormalActivity;
		}

		private static void AddAllFunc(this UIActivityPanel self)
		{
			Player player = ((Entity)(object)self).LocalPlayer();
			self.SubFuncIds = ((Entity)player).GetComponent<FuncModule>().GetFuncListByView(self.PanelFuncId);
			foreach (int subFuncId in self.SubFuncIds)
			{
				if (player.CheckFuncOpen(subFuncId))
				{
					FuncConfig funcConfig = ConfigSingleton<FuncConfigCategory>.Instance.Get(subFuncId);
					UITabInfo uITabInfo = UITabInfo.CreateWithFunc(subFuncId);
					uITabInfo.SetSort(funcConfig.Sort);
					if (Enum.TryParse<RedPointType>(funcConfig.RedPointType, out var result))
					{
						uITabInfo.SetRedPoint(result);
					}
					self.Tabs.Add(uITabInfo);
				}
			}
		}

		private static void AddAllActivity(this UIActivityPanel self)
		{
			long num = TimeHelper.ServerNow();
			foreach (ActivityData item in ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<PlayerActivityComponent>().GetAllActivity(self.ActivityCenterType))
			{
				if (!item.IsClose() && num < item.EndTime && (item.ActivityType != ActivityType.FreePrizeDraw || ((Entity)item).GetComponent<FreePrizeDrawModule>().IsShow()))
				{
					UITabInfo uITabInfo = UITabInfo.CreateWithActivity(item.ActivityId);
					uITabInfo.SetIcon(item.GetIcon(), item.GetIconEffect());
					uITabInfo.SetSort(item.Sort);
					uITabInfo.Text = item.Name;
					Type uI = ActivityMainUIComponent.Instance.GetUI(item.ActivityType, item.BaseInfo.ActivityType, isSubView: true);
					if (uI != null)
					{
						uITabInfo.SetUIName(uI.Name);
					}
					uITabInfo.SetRedPoint(RedPointType.Activity, item.ActivityId);
					self.Tabs.Add(uITabInfo);
				}
			}
		}

		private static void SetTopData(this UIActivityPanel self, int index)
		{
			if (index != -1)
			{
				UITabInfo uITabInfo = self.Tabs[index];
				switch (uITabInfo.TabIdType)
				{
				case UITabIdType.Activity:
					self._UICommonPanelTop.SetActivityData(uITabInfo.FuncId, setTitle: false);
					break;
				case UITabIdType.Func:
					self._UICommonPanelTop.SetData(uITabInfo.FuncId, setTitle: false);
					break;
				}
			}
		}

		private static void OnTabClick(this UIActivityPanel self, int index, UIObject showPanel)
		{
			if (index < self.Tabs.Count)
			{
				self.SetTopData(index);
			}
		}

		public static void OnClickClose(this UIActivityPanel self)
		{
			UIManager.Instance.Remove(typeof(UIActivityPanel));
		}
	}
