				num = ((moneyAllNum >= self.nextBuyConfig.AllCostNum) ? self.nextBuyConfig.AllCostNum : moneyAllNum);
				num2 = self.nextBuyConfig.AllCostNum;
			}
			if (moneyAllNum >= self.Configs.Last().Value.AllCostNum)
