		[UIMethod]
		private static void OnShow(this UIAdvanceLadderDupResultContent self, Cross2C_AdvanceLadderDupResult result)
		{
			Player player = ((Entity)(object)self).LocalPlayer();
			if (player == null)
			{
				return;
			}
			self._ContinueButton.SetToggleWithoutNotify(UIAdvanceLadderHelper.IsContinueMatch(player));
			self._FinalScore.SetText($"{result.RoundWinner.Count((long p) => p == ((Entity)player).Id)}:{result.RoundWinner.Count((long p) => p != ((Entity)player).Id)}");
			foreach (var (num2, advanceLadderMatchPlayerInfo2) in result.PlayerInfos)
			{
				int num3 = ((num2 == ((Entity)player).Id) ? 1 : 2);
