			int preLevelScore = configByScore.GetPreLevelScore();
			float value = (float)(score - preLevelScore) / (float)(configByScore.Score - preLevelScore);
			self._ExpProText.SetText($"{score - preLevelScore}/{configByScore.Score - preLevelScore}");
			((Slider)self._ScorePro.GameObject.GetComponent<SuperSlider>()).value = value;
		}

		private static void SetLevel(this UIAdvanceLadderDupResultContent self, int score)
		{
			AdvanceLadderLevelConfig configByScore = AdvanceLadderHelper.GetConfigByScore(score);
			DanStarConfig danStarConfig = ConfigSingleton<DanStarConfigCategory>.Instance.Get(configByScore.DanId);
			if (self.LastDan == 0)
			{
				self.LastDan = danStarConfig.Dan;
			}
			self._UICommonLevel.ShowDanAni(configByScore.DanId, self.LastDan);
			self._DanName.SetText(danStarConfig.Name);
			self.LastDan = danStarConfig.Dan;
		}

