				int num4 = advanceLadderMatchPlayerInfo2.RoundPick[roundIndex];
				int key = AdvanceLadderDefine.FormationIds[num4];
				FormationCommonInfo formationInfo = advanceLadderMatchPlayerInfo2.FormationInfos[key];
				self._Bg.Find($"FormationNo{num3}").SetText(Language.Format(1, 310 + num3, num4 + 1));
				((Entity)self._Bg.Find($"Power{num3}")).GetComponent<UICommonPower>().SetPower(formationInfo.Power);
