	public static class UIAdvanceLadderHelper
	{
		public static bool IsContinueMatch(Player player)
		{
			bool localBool = player.GetLocalBool("AdvanceLadderContinueMatch");
			bool flag = ((Entity)player).GetComponent<PrivilegeModule>().GetLadder1AutoPlayCount() > 0;
			return localBool & flag;
		}

		public static void OnContinueButtonClick(UIObject toggleUIObject)
		{
			Player player = ((Entity)(object)toggleUIObject).LocalPlayer();
			if (((Entity)player).GetComponent<PrivilegeModule>().GetLadder1AutoPlayCount() <= 0)
			{
				((Toggle)toggleUIObject.GameObject.GetComponent<SuperToggle>()).isOn = false;
				UICommonHelper.ShowConfirmPanel(new ConfirmPanelOptions
				{
					Title = Language.Get(4, 718),
					Message = "开通月卡后激活此功能",
					NoConfirmTillNextLogin = false,
					OkAction = delegate
					{
						UIGameMsgHelper.FloatMsg("解锁月卡后可享受连续匹配");
						if (player.IsFuncOpen(46))
						{
							UIJumpHelper.To(46).Coroutine();
						}
					}
				});
			}
			else
			{
				bool flag = !IsContinueMatch(player);
				player.SetLocalBool("AdvanceLadderContinueMatch", flag);
				toggleUIObject.SetToggle(flag);
			}
		}
	}
