		public static void RefreshView(this UIAdvanceLadderPanel self)
		{
			Player player = ((Entity)(object)self).LocalPlayer();
			if (player == null)
			{
				return;
			}
			self.RefreshContinueButton();
			self.RefreshTop3().Coroutine();
			AdvanceLadderModule component = ((Entity)player).GetComponent<AdvanceLadderModule>();
			int score = component.Score;
			AdvanceLadderLevelConfig configByScore = AdvanceLadderHelper.GetConfigByScore(score);
			DanStarConfig danStarConfig = ConfigSingleton<DanStarConfigCategory>.Instance.Get(configByScore.DanId);
			self._UICommonLevel.ShowDanAni(configByScore.DanId, self.GetLastDan());
			self.UpdateLastDan(danStarConfig.Dan);
			self._LevelText.SetText(danStarConfig.Name);
			int preLevelScore = configByScore.GetPreLevelScore();
			self._ExpPro.SetProBar((float)(score - preLevelScore) / (float)(configByScore.Score - preLevelScore));
			self._ExpProText.SetText($"{score - preLevelScore}/{configByScore.Score - preLevelScore}");
			var (num, num2) = component.GetBoxReward();
			if (ConfigSingleton<AdvanceLadderBoxRewardConfigCategory>.Instance.GetList()[^1].Id == num2)
			{
				self._RewardGroup.SetActive(active: false);
			}
			AdvanceLadderBoxRewardConfig currentBoxConfig = null;
			foreach (AdvanceLadderBoxRewardConfig item in ConfigSingleton<AdvanceLadderBoxRewardConfigCategory>.Instance.GetList())
			{
				AdvanceLadderBoxRewardConfig advanceLadderBoxRewardConfig = (currentBoxConfig = item);
				if ((num >= advanceLadderBoxRewardConfig.WinCount && num2 < advanceLadderBoxRewardConfig.Id) || num2 < advanceLadderBoxRewardConfig.Id)
				{
					break;
				}
			}
			self._RewardItem.UIObject.CloneAll(currentBoxConfig.Reward.Length, delegate(int index, UIObject uiObject)
			{
				((Entity)uiObject).GetComponent<UICommonItem>().SetItem(currentBoxConfig.Reward[index]);
			}).Coroutine();
			self._BattleNumsText.SetText($"{num}/{currentBoxConfig.WinCount}");
		}

