			self.SetBg(config);
		}

		private static void SetBg(this UIAdvanceLadderRewardItem self, AdvanceLadderRewardConfig config)
		{
			if (config.LeftRank == config.RightRank && config.LeftRank <= 3)
			{
				self._Bg.SetSprite($"ui_rank_frame_0{config.LeftRank + 3}_gv").Coroutine();
			}
			else
			{
				self._Bg.SetSprite("ui_rank_frame_05_gv").Coroutine();
			}
		}

		private static void ShowNormal(this UIAdvanceLadderRewardItem self, AdvanceLadderRewardConfig config)
		{
			self._Level.UIObject.SetActive(active: false);
			if (config.LeftRank == config.RightRank)
			{
				int leftRank = config.LeftRank;
				if (leftRank <= 3)
				{
					self._RankImage.SetActive(active: true);
					self._RankText.SetActive(active: false);
					self._RankImage.SetSprite($"ui_jjc2_sign_0{leftRank}", nativeSize: true).Coroutine();
				}
				else
				{
					self._RankImage.SetActive(active: false);
					self._RankText.SetActive(active: true);
					self._RankText.SetText($"{config.LeftRank}-{config.RightRank}");
				}
			}
			else
			{
				self._RankImage.SetActive(active: false);
				self._RankText.SetActive(active: true);
				self._RankText.SetText($"{config.LeftRank}-{config.RightRank}");
			}
		}

		private static void ShowStage(this UIAdvanceLadderRewardItem self, AdvanceLadderRewardConfig config)
		{
			self._RankImage.SetActive(active: false);
			self._RankText.SetActive(active: false);
			self._Level.UIObject.SetActive(active: true);
			LadderlevelConfig ladderlevelConfig = ConfigSingleton<LadderlevelConfigCategory>.Instance.Get(config.LeftRank);
			self._Level.SetDataSamll(ladderlevelConfig.DanId);
			ConfigSingleton<DanStarConfigCategory>.Instance.Get(ladderlevelConfig.DanId);
		}
	}
