			self._RewardList.SetData(activityData.BaseInfo.Items.ToArray());
			self.UpdateView();
		}

		private static void UpdateView(this UIAncientWarActivityPanel self)
		{
			ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActivityId);
			(int state, long time) round = ((Entity)activityData).GetComponent<AncientWarActivityModule>().GetRound();
			int item = round.state;
			long item2 = round.time;
			self.TargetTime = item2;
			self.StopTime();
			if (((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<AncientWarModule>().Stage == 2)
			{
				self._DescText.SetText("");
				self._TimeText.SetText("活动已结束");
				return;
			}
			switch (item)
			{
			case 1:
				self._TimeText.SetText("敬请期待:");
				break;
			case 2:
				self._TimeText.SetText("活动进行中");
				break;
			case 3:
				self._TimeText.SetText("活动已结束");
				self._DescText.SetText("");
				return;
			}
			self.StartTime();
			switch (TimeHelper.DaysBetween(TimeHelper.Now(), activityData.StartTime, 0L))
			{
			case 1:
				self._DescText.SetText("今天 " + Language.Get(5, 1709));
				break;
			case 2:
				self._DescText.SetText("明天 " + Language.Get(5, 1709));
				break;
			default:
			{
				DateTime dateTime = TimeHelper.ToDateTime(activityData.StartTime);
				self._DescText.SetText(dateTime.ToString("MM月dd日 ") + Language.Get(5, 1709));
				break;
			}
			}
		}

