		public static void UpdateCoolTime(this UIAncientWarHandleItem self)
		{
			if (self.FormationId == 0)
			{
				return;
			}
			Player player = ((Entity)(object)self).LocalPlayer();
			AncientWarComponent component = ((Entity)((Entity)(object)self).GetCurrentScene()).GetComponent<AncientWarComponent>();
			if (component != null)
			{
				AncientWarUnit ancientWarUnit = component.GetAncientWarUnit(((Entity)player).Id, self.FormationId);
				if (ancientWarUnit != null)
				{
					long num = TimeHelper.Now();
					self.TargetTime = ancientWarUnit.CoolTime;
					self._TimeText.SetActive(ancientWarUnit.CoolTime > num);
					self.StartTime();
				}
			}
		}

		public static void SetData(this UIAncientWarHandleItem self, AncientWarUnit ancientWarUnit)
		{
			if (ancientWarUnit == null)
			{
				self.Clear();
				return;
			}
			self.AncientWarUnitId = ((Entity)ancientWarUnit).Id;
			self.FormationId = ancientWarUnit.FormationId;
			Player player = ((Entity)(object)self).LocalPlayer();
			long power = player.GetFormation(self.FormationId).GetPower();
			self._Power.SetPower(power);
			self._GoButton.SetActive(ancientWarUnit.State != StateType.Run);
			self._StateText.SetActive(ancientWarUnit.State == StateType.Run);
			long num = TimeHelper.Now();
			self.TargetTime = ancientWarUnit.CoolTime;
			self._TimeText.SetActive(ancientWarUnit.CoolTime > num);
			Formation formation = ((Entity)player).GetComponent<FormationModule>().GetFormation(self.FormationId);
			List<long> list = formation.PosHero.Values.ToList();
			for (int i = 0; i < self.HeroList.Count; i++)
			{
				UIKingWarHeroHeadItem self2 = self.HeroList[i];
				long num2 = ((list.Count > i) ? list[i] : 0);
				if (num2 == 0L)
				{
					self2.Clear();
					continue;
				}
				Hero heroByUid = player.GetHeroByUid(num2);
				self2.SetData(heroByUid.ConfigId);
			}
			UIObject goButton = self._GoButton;
			SortedDictionary<int, long> posHero = formation.PosHero;
			goButton.SetActive(posHero != null && posHero.Count > 0);
			UIObject formationButton = self._FormationButton;
			posHero = formation.PosHero;
			formationButton.SetActive(posHero == null || posHero.Count <= 0);
			self.UpdateHpPro();
			self.UpdateCoolTime();
			self.UpdateSelected();
			self.UpdateSelected();
		}

