		private static void OnTimeUpdate(this UIAncientWarHandleItem self)
		{
			long num = TimeHelper.Now();
			if (num > self.TargetTime)
			{
				self._TimeText.SetActive(active: false);
				return;
			}
			self._TimeText.SetActive(active: true);
			string str = TimeSpan.FromSeconds((double)((self.TargetTime - num) / 1000)).ToString("hh\\:mm\\:ss");
			self._TimeText.SetText(str);
		}

		private static void UpdateHpPro(this UIAncientWarHandleItem self)
		{
			AncientWarComponent component = ((Entity)((Entity)(object)self).GetCurrentScene()).GetComponent<AncientWarComponent>();
			if (component != null)
			{
				Player player = ((Entity)(object)self).LocalPlayer();
				AncientWarUnit ancientWarUnit = component.GetAncientWarUnit(((Entity)player).Id, self.FormationId);
				SortedDictionary<int, long> posHero = ((Entity)player).GetComponent<FormationModule>().GetFormation(self.FormationId).PosHero;
				if (posHero == null || posHero.Count <= 0)
				{
					((Slider)self._HpPro.GameObject.GetComponent<SuperSlider>()).value = 0f;
					self._HpProText.SetText("0%");
					return;
				}
				if (ancientWarUnit.MaxHp == 0L)
				{
					((Slider)self._HpPro.GameObject.GetComponent<SuperSlider>()).value = 1f;
					self._HpProText.SetText("100%");
					return;
				}
				long maxHp = ancientWarUnit.MaxHp;
				float num = (float)ancientWarUnit.Hp * 1f / (float)maxHp;
				((Slider)self._HpPro.GameObject.GetComponent<SuperSlider>()).value = num;
				self._HpProText.SetText($"{(int)(num * 100f)}%");
			}
		}

