		private static void OnGoClick(this UIAncientWarHandleItem self)
		{
			Player player = ((Entity)(object)self).LocalPlayer();
			AncientWarModule component = ((Entity)player).GetComponent<AncientWarModule>();
			AncientWarComponent component2 = ((Entity)((Entity)(object)self).GetCurrentScene()).GetComponent<AncientWarComponent>();
			if (component2 == null)
			{
				return;
			}
			AncientWarUnit ancientWarUnit = component2.GetAncientWarUnit(((Entity)player).Id, self.AncientWarUnitId);
			long num = TimeHelper.Now();
			if (ancientWarUnit.CoolTime > num)
			{
				UIGameMsgHelper.FloatMsg("队伍调整中，无法出征");
				return;
			}
			if (ancientWarUnit.BuildId == self.TargetId)
			{
				int playerNum = component2.GetPlayerNum(self.TargetId, (ancientWarUnit.CampId != 1) ? 1 : 2);
				AncientWarBuild ancientWarBuild = component2.GetAncientWarBuild(self.TargetId);
				if (ancientWarUnit.CampId == 1)
				{
					if (playerNum <= 0 && ancientWarBuild.Hp <= 0)
					{
						UIGameMsgHelper.FloatMsg("已在当前位置");
						return;
					}
				}
				else if (playerNum <= 0)
				{
					UIGameMsgHelper.FloatMsg("已在当前位置");
					return;
				}
			}
			component.ReqMoveTo(self.FormationId, self.TargetId).Coroutine();
			self._StateText.SetActive(active: true);
			self._GoButton.SetActive(active: false);
		}
	}
