				self.StartTime();
			}
		}

		private static void UpdateView(this UIAncientWarPanel self)
		{
			_ = self.ActivityData.BaseInfo.CrossType;
			CrossGroupInfo groupInfo = CrossHelper.GetGroupInfo(SceneHelper.DomainScene((Entity)(object)self), CrossType.BigLink);
			for (int i = 0; i < self.ZoneItemList.Count; i++)
