		private static void UpdateTime(this UIAncientWarPanel self)
		{
			if (((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<AncientWarModule>().Stage == 2)
			{
				self.StopTime();
				self._DescText.SetText("");
				self._TimeText.SetText("活动已结束");
				return;
			}
			long num = TimeHelper.Now();
			(int state, long time) round = ((Entity)self.ActivityData).GetComponent<AncientWarActivityModule>().GetRound();
			int item = round.state;
			long item2 = round.time;
			string text = "";
			if (item2 > num)
			{
				long num2 = item2 - num;
				TimeSpan timeSpan = TimeSpan.FromSeconds((float)num2 / 1000f);
				text = ((num2 < 86400000) ? timeSpan.ToString("hh\\:mm\\:ss") : timeSpan.ToString(Language.Get(2, 312)));
			}
			switch (item)
			{
			case 1:
				self._TimeText.SetText("敬请期待:" + text);
				break;
			case 2:
				self._TimeText.SetText("活动进行中:" + text);
				break;
			case 3:
				self._DescText.SetText("");
				self._TimeText.SetText("活动已结束");
				self.StopTime();
				break;
			}
		}

