		private static void UpdateView(this UIAncientWarResultPanel self)
		{
			List<AncientWarZoneResult> list = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<AncientWarModule>().AncientWarResult.ZoneResultDict.Values.ToList();
			list.Sort((AncientWarZoneResult a, AncientWarZoneResult b) => (int)(b.Hurt - a.Hurt));
			for (int num = 0; num < self.Items.Count; num++)
			{
				self.Items[num].SetData(list[num], num + 1);
