		public static void SetSelfData(this UIAncientWarRewardItem self, AncientWarRewardConfig config)
		{
			self.ShowNormal(config);
			self._RewardList.ShowDrop(config.DayReward);
		}

		public static void SetData(this UIAncientWarRewardItem self, AncientWarRewardConfig config)
		{
			self.ShowNormal(config);
			self._RewardList.ShowDrop(config.DayReward);
			self.SetBg(config);
		}

		private static void SetBg(this UIAncientWarRewardItem self, AncientWarRewardConfig config)
		{
			if (config.RankLeft == config.RankRight && config.RankLeft <= 3)
			{
				self._Bg.SetSprite($"ui_rank_frame_0{config.RankLeft + 3}_gv").Coroutine();
			}
			else
			{
				self._Bg.SetSprite("ui_rank_frame_05_gv").Coroutine();
			}
		}

		private static void ShowNormal(this UIAncientWarRewardItem self, AncientWarRewardConfig config)
		{
			if (config.RankLeft == config.RankRight)
			{
				int rankLeft = config.RankLeft;
				if (rankLeft <= 3)
				{
					self._RankImage.SetActive(active: true);
					self._RankText.SetActive(active: false);
					self._RankImage.SetSprite($"ui_jjc2_sign_0{rankLeft}", nativeSize: true).Coroutine();
				}
				else
				{
					self._RankImage.SetActive(active: false);
					self._RankText.SetActive(active: true);
					self._RankText.SetText($"{config.RankLeft}-{config.RankRight}");
				}
			}
			else
			{
				self._RankImage.SetActive(active: false);
				self._RankText.SetActive(active: true);
				self._RankText.SetText($"{config.RankLeft}-{config.RankRight}");
			}
		}
	}
