		[UIMethod]
		public static void OnAwake(this UIBagPanel self)
		{
			self._EmptyImage.SetActive(active: true);
			self._SelectItemInfoPanel.UIObject.SetActive(active: false);
			self._AllItemButton.AddClickHandler(delegate
			{
				self.OnClickTab(0);
			});
			self._GoodsItemButton.AddClickHandler(delegate
			{
				self.OnClickTab(1);
			});
			self._EquipItemButton.AddClickHandler(delegate
			{
				self.OnClickTab(2);
			});
			self._HeroItemButton.AddClickHandler(delegate
			{
				self.OnClickTab(3);
			});
			self._CostItemButton.AddClickHandler(delegate
			{
				self.OnClickTab(4);
			});
			self._CostItemButton.SetRedPoint(RedPointType.Interactive_Bag).Coroutine();
			self._ItemScrollView.Handler.onCreate += self.OnCellCreate;
			self._ItemScrollView.Handler.onUpdate += self.OnCellUpdate;
			self._ItemScrollView.SpaceX = 12f;
			self._ItemScrollView.SpaceY = 12f;
			self._EmptyText.SetText(Language.Get(2, 237));
			self._CapacityText.SetActive(active: false);
			ItemModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>();
			int num = 0;
			Item[] allItems = component.GetAllItems();
			foreach (Item item in allItems)
			{
				if (item.Config != null && item.Config.IsRedPoint && item.Red)
				{
					num++;
				}
			}
			if (num > 0)
			{
				self.OnClickTab(4);
			}
			else
			{
				self.OnClickTab(0);
			}
			self._UICommonPanelTop.SetData(7);
		}

		public static void UpdateCapacityText(this UIBagPanel self)
		{
			self._CapacityText.SetActive(self.CurrentSelectTab != 0 && self.BagItemInfos.Count > 0);
			GlobalConfig one = ConfigSingleton<GlobalConfigCategory>.Instance.GetOne();
			ItemModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>();
			switch (self.CurrentSelectTab)
			{
			case 1:
				self._CapacityText.SetText(Language.Format(2, 296, component.UsedPropSlotNums, one.BagItemCapacity));
				break;
			case 2:
				self._CapacityText.SetText(Language.Format(2, 296, component.UsedEquipSlotNums, one.BagEquipCapacity));
				break;
			case 3:
				self._CapacityText.SetText(Language.Format(2, 296, component.UsedHeroSlotNums, one.BagHeroCapacity));
				break;
			}
		}

		public static void UpdateView(this UIBagPanel self)
		{
			self.UpdateItemView();
			self.UpdateSelectItemView();
			self.UpdateCapacityText();
		}

		public static void UpdateSelectItemView(this UIBagPanel self)
		{
			if (self.CurrentSelectIndex < 0)
			{
				self.OnClickItem(0);
				return;
			}
			bool flag = self.BagItemInfos.Count > 0;
			self._SelectItemInfoPanel.UIObject.SetActive(flag);
			if (flag)
			{
				if (self.CurrentSelectIndex < 0 || self.CurrentSelectIndex >= self.BagItemInfos.Count)
				{
					self.CurrentSelectIndex = 0;
				}
				BagItemInfo itemInfo = self.BagItemInfos[self.CurrentSelectIndex];
				self._SelectItemInfoPanel.SetData(itemInfo);
			}
		}

		public static void UpdateItemView(this UIBagPanel self)
		{
			ItemModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>();
			self.BagItemInfos.Clear();
			Item[] allItems = component.GetAllItems();
			foreach (Item item in allItems)
			{
				if (item.Nums != 0L && (self.CurrentSelectTab <= 0 || self.CurrentSelectTab == UIItemHelper.GetItemTabTypeByItemId(item.ConfigId)))
				{
					int itemMaxStackedByItemId = ItemHelper.GetItemMaxStackedByItemId(item.ConfigId);
					long num = item.Nums;
					int num2 = (int)math.ceil((float)num / (float)itemMaxStackedByItemId);
					while (num2 > 0)
					{
						self.BagItemInfos.Add(new BagItemInfo
						{
							ConfigId = item.ConfigId,
							Nums = (int)math.min(num, (long)itemMaxStackedByItemId)
						});
						num2--;
						num -= itemMaxStackedByItemId;
					}
				}
			}
			self.SortAllItem();
			self._ItemScrollView.SetData(self.BagItemInfos.Count);
			self._EmptyImage.SetActive(self.BagItemInfos.Count == 0);
		}

		public static void SortHeroList(this UIBagPanel self, List<BagItemInfo> ItemList)
		{
			foreach (BagItemInfo item in from o in ItemList
				orderby ItemHelper.GetItemTypeOderByItemId(o.ConfigId) descending, ItemHelper.GetItemQualityByItemId(o.ConfigId) descending, o.ConfigId
				select o)
			{
				self.BagItemInfos.Add(item);
			}
		}

		public static void SortEquipList(this UIBagPanel self, List<BagItemInfo> ItemList)
		{
			foreach (BagItemInfo item in from o in ItemList
				orderby ItemHelper.GetItemTypeOderByItemId(o.ConfigId) descending, ItemHelper.GetEquipItemLevelByItemId(o.ConfigId) descending, ItemHelper.GetItemQualityByItemId(o.ConfigId) descending, o.ConfigId
				select o)
			{
				self.BagItemInfos.Add(item);
			}
		}

		public static void SortItemList(this UIBagPanel self, List<BagItemInfo> ItemList)
		{
			foreach (BagItemInfo item in from o in ItemList
				orderby ItemHelper.GetItemTypeOderByItemId(o.ConfigId) descending, ItemHelper.GetItemQualityByItemId(o.ConfigId) descending, o.ConfigId
				select o)
			{
				self.BagItemInfos.Add(item);
			}
		}

		public static void SortCostList(this UIBagPanel self, List<BagItemInfo> ItemList)
		{
			foreach (BagItemInfo item in from o in ItemList
				orderby ItemHelper.GetItemTypeOderByItemId(o.ConfigId) descending, ItemHelper.GetItemQualityByItemId(o.ConfigId) descending, o.ConfigId
				select o)
			{
				self.BagItemInfos.Add(item);
			}
		}

		private static void AddBagItemInfo(this UIBagPanel self, List<BagItemInfo> PreItemList, List<BagItemInfo> ItemList, BagItemInfo ItemInfo)
		{
			if (UIItemHelper.CanComposable(ItemInfo))
			{
				PreItemList.Add(ItemInfo);
			}
			else
			{
				ItemList.Add(ItemInfo);
			}
		}

		public static void SortAllItem(this UIBagPanel self)
		{
			self.PreSortItemList.Clear();
			self.PreSortEquipList.Clear();
			self.PreSortHeroList.Clear();
			self.PreSortCostList.Clear();
			self.SortItemList.Clear();
			self.SortEquipList.Clear();
			self.SortHeroList.Clear();
			self.SortCostList.Clear();
			foreach (BagItemInfo bagItemInfo in self.BagItemInfos)
			{
				switch (UIItemHelper.GetItemTabTypeByItemId(bagItemInfo.ConfigId))
				{
				case 1:
					self.AddBagItemInfo(self.PreSortItemList, self.SortItemList, bagItemInfo);
					break;
				case 2:
					self.AddBagItemInfo(self.PreSortEquipList, self.SortEquipList, bagItemInfo);
					break;
				case 3:
					self.AddBagItemInfo(self.PreSortHeroList, self.SortHeroList, bagItemInfo);
					break;
				case 4:
					self.AddBagItemInfo(self.PreSortCostList, self.SortCostList, bagItemInfo);
					break;
				}
			}
			self.BagItemInfos.Clear();
			switch (self.CurrentSelectTab)
			{
			case 0:
				self.SortItemList(self.PreSortItemList);
				self.SortHeroList(self.PreSortHeroList);
				self.SortEquipList(self.PreSortEquipList);
				self.SortItemList(self.SortItemList);
				self.SortHeroList(self.SortHeroList);
				self.SortEquipList(self.SortEquipList);
				break;
			case 1:
				self.SortItemList(self.PreSortItemList);
				self.SortItemList(self.SortItemList);
				break;
			case 2:
				self.SortEquipList(self.PreSortEquipList);
				self.SortEquipList(self.SortEquipList);
				break;
			case 3:
				self.SortHeroList(self.PreSortHeroList);
				self.SortHeroList(self.SortHeroList);
				break;
			case 4:
				self.SortCostList(self.PreSortCostList);
				self.SortCostList(self.SortCostList);
				break;
			}
		}

		public static void OnCellUpdate(this UIBagPanel self, UIScrollListCell cell)
		{
			int index = cell.Index;
			if (self.BagItemInfos.Count > index)
			{
				BagItemInfo bagItemInfo = self.BagItemInfos[index];
				UICommonItem component = ((Entity)cell.UIObject).GetComponent<UICommonItem>();
				component.SetItem(bagItemInfo.ConfigId, bagItemInfo.Nums);
				component.SetSelect(cell.IsSelected);
				Item child = ((Entity)((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>()).GetChild<Item>((long)bagItemInfo.ConfigId);
				bool show = child != null && child.Config.IsRedPoint && child.Red;
				component.SetRedIcon(show);
			}
		}

		public static void OnCellCreate(this UIBagPanel self, UIScrollListCell cell)
		{
			((Entity)cell.UIObject).GetComponent<UICommonItem>().AddClickHandler(delegate
			{
				self.OnClickItem(cell.Index);
			});
		}

		public static BagItemInfo GetCurrentSelectItemInfo(this UIBagPanel self)
		{
			if (self.CurrentSelectIndex < 0 || self.CurrentSelectIndex >= self.BagItemInfos.Count)
			{
				return null;
			}
			return self.BagItemInfos[self.CurrentSelectIndex];
		}

		private static void OnClickItem(this UIBagPanel self, int index)
		{
			if (self.CurrentSelectIndex != index)
			{
				self.CurrentSelectIndex = index;
