		public static void UpdateView(this UIBagSelectedPanel self)
		{
			if (self.ItemInfo != null && ItemHelper.CheckEquipConfigContainKey(self.ItemInfo.ConfigId))
			{
				self.ShowEquip();
			}
		}

		public static void SetData(this UIBagSelectedPanel self, BagItemInfo itemInfo)
		{
			self.ItemInfo = itemInfo;
			self._SelectItem.SetItem(itemInfo.ConfigId, itemInfo.Nums);
			self._UseButton.SetGray(isGray: false);
			self._UseBtnText.SetText("使用");
			self._ItemNameText.SetQuantityName(itemInfo.ConfigId, null);
			self.HideAllButton();
			if (ItemHelper.CheckItemConfigContainKey(itemInfo.ConfigId))
			{
				self.ShowItem();
			}
			else if (ItemHelper.CheckEquipConfigContainKey(itemInfo.ConfigId))
			{
				self.ShowEquip();
			}
			else if (ItemHelper.CheckGemStoneConfigContainKey(itemInfo.ConfigId))
			{
				self.ShowGemStone();
			}
		}

		public static void ShowItem(this UIBagSelectedPanel self)
		{
			BagItemInfo itemInfo = self.ItemInfo;
			self._SelectItemDescText.SetActive(active: true);
			self._SelectItemDescText.SetText(ItemHelper.GetItemDescByItemId(itemInfo.ConfigId));
			int[] itemObtainWaysByItemId = ItemHelper.GetItemObtainWaysByItemId(itemInfo.ConfigId);
			self._ObtainWayButton.SetActive(itemObtainWaysByItemId != null && itemObtainWaysByItemId.Length != 0);
			ItemConfig itemConfig = ConfigSingleton<ItemConfigCategory>.Instance.Get(itemInfo.ConfigId);
			self._UseButton.SetActive(itemConfig.UseEff > 0 && itemConfig.UseEff != 12 && itemConfig.UseEff != 8);
			self._SellButton.SetActive(itemConfig.UseEff == 0 && itemConfig.IsSellable);
			self._ComposeButton.SetActive(itemConfig.IsComposable);
			self._GotoButton.SetActive(itemConfig.JumpParam != null);
			if (itemConfig.Id > 8000)
			{
				_ = itemConfig.Id;
				_ = 9000;
			}
		}

		public static void ShowGemStone(this UIBagSelectedPanel self)
		{
			self._ObtainWayButton.SetActive(active: true);
			BagItemInfo itemInfo = self.ItemInfo;
			GemStoneConfig gemStoneConfig = ConfigSingleton<GemStoneConfigCategory>.Instance.Get(itemInfo.ConfigId);
			bool flag = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesGemModule>().IsSuggestInlay(itemInfo.ConfigId);
			self._UseButton.SetActive(flag);
			self._DecomposeButton.SetActive(!flag);
			self.Stats = gemStoneConfig.AddStats;
			self.UpdateAttrs();
		}

		public static void ShowEquip(this UIBagSelectedPanel self)
		{
			self._ObtainWayButton.SetActive(active: true);
			BagItemInfo itemInfo = self.ItemInfo;
			EquipConfig equipConfig = ConfigSingleton<EquipConfigCategory>.Instance.Get(itemInfo.ConfigId);
			int level = equipConfig.Level;
			int level2 = VibesHelper.GetLevel(((Entity)(object)self).LocalPlayer(), equipConfig.Job);
			if (level > level2)
			{
				self._UseButton.SetActive(active: true);
				self._UseBtnText.SetText($"LV.{level}级可穿戴");
				self._UseButton.SetGray();
			}
			else
			{
				int equipId = ((Entity)(object)self).LocalPlayer().GetEquipId(equipConfig.Job, equipConfig.Part);
				if (equipId == 0)
				{
					self._UseButton.SetActive(active: true);
				}
				else
				{
					long num = VibesHelper.EquipPowerDiff(itemInfo.ConfigId, equipId);
					self._UseButton.SetActive(num > 0);
					self._DecomposeButton.SetActive(num <= 0);
				}
			}
			self.Stats = equipConfig.EquipStat;
			self.UpdateAttrs();
		}

		public static void UpdateAttrs(this UIBagSelectedPanel self)
		{
			self._AttrsList.UIObject.SetActive(active: false);
			if (self.Stats != null)
			{
				self._SelectItemDescText.SetActive(active: false);
				self._AttrsList.UIObject.SetActive(active: true);
				self._AttrsList.SetData(self.Stats.Length);
			}
		}

		public static void OnCellUpdate(this UIBagSelectedPanel self, UIScrollListCell cell)
		{
			((Entity)cell.UIObject).GetComponent<UIBagAttrItem>().SetData(self.Stats[cell.Index]);
		}

