		private static void OnGotoButton(this UIBagSelectedPanel self)
		{
			((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<HeroModule>();
			UIManager.Instance.Remove(typeof(UIBagPanel));
			BagItemInfo itemInfo = self.ItemInfo;
			ItemConfig itemConfig = ConfigSingleton<ItemConfigCategory>.Instance.Get(itemInfo.ConfigId);
			if (itemConfig.Type == 3)
			{
				int param = ((itemConfig.UseEffParams != null && itemConfig.UseEffParams.Length != 0) ? itemConfig.UseEffParams[0] : 0);
				UIJumpHelper.To(itemConfig.JumpParam.Id, param).Coroutine();
				UIManager.Instance.Remove(typeof(UIMainDrawerPanel));
			}
			else if (itemConfig.JumpParam.Param1 != 0 || itemConfig.JumpParam.Param2 != 0)
			{
				UIJumpHelper.To(itemConfig.JumpParam.Id, itemConfig.JumpParam.Param1, itemConfig.JumpParam.Param2).Coroutine();
			}
			else
			{
				UIJumpHelper.To(itemConfig.JumpParam.Id).Coroutine();
			}
		}

		private static void OnObtainWayClick(this UIBagSelectedPanel self)
		{
			BagItemInfo itemInfo = self.ItemInfo;
			if (itemInfo.ConfigId > 0)
			{
				UIObtainWayHelper.ShowPanelAsync(itemInfo.ConfigId).Coroutine();
			}
		}

		private static void OnDecomposeClick(this UIBagSelectedPanel self)
		{
			if (ItemHelper.CheckEquipConfigContainKey(self.ItemInfo.ConfigId))
			{
				UIManager.Instance.Show<UIVibesSplitPanel, int>(1).Coroutine();
			}
			else if (ItemHelper.CheckGemStoneConfigContainKey(self.ItemInfo.ConfigId))
			{
				UIManager.Instance.Show<UIVibesSplitPanel, int>(2).Coroutine();
			}
		}

