			self._ComposeButton.SetActive(active: false);
			self._GotoButton.SetActive(active: false);
			self._DecomposeButton.SetActive(active: false);
			self._AttrsList.UIObject.SetActive(active: false);
			self._SelectItemDescText.SetActive(active: false);
		}
	}
