		[UIMethod]
		public static void OnAwake(this UIBoxDetaPanel self)
		{
			self._CloseButton.AddClickHandler(self.OnCloseButtonClick);
			self._UIScrollList.SpaceY = 10f;
			self._UIScrollList.Handler.onUpdate += self.OnCellUpdate;
		}

		public static void ShowItemInfo(this UIBoxDetaPanel self, int configId)
		{
			self.BoxItemId = configId;
			self.BoxType = ConfigSingleton<ItemConfigCategory>.Instance.Get(configId).UseEff;
			switch (self.BoxType)
			{
			case 3:
				self._TitleText.SetText(ConfigSingleton<Lang4Category>.Instance.Get(401).Text);
				self._DescText.SetText(ConfigSingleton<Lang4Category>.Instance.Get(402).Text);
				break;
			case 1:
				self._TitleText.SetText(ConfigSingleton<Lang4Category>.Instance.Get(403).Text);
				self._DescText.SetText(ConfigSingleton<Lang4Category>.Instance.Get(404).Text);
				break;
			}
			self.UpdateItemView();
		}

		public static void UpdateItemView(this UIBoxDetaPanel self)
		{
			self.BoxItemInfos.Clear();
			self.boxDropIds.Clear();
			if (ConfigSingleton<ItemConfigCategory>.Instance.Get(self.BoxItemId).UseEffParams.Length == 0)
			{
				return;
			}
			for (int i = 0; i < ConfigSingleton<ItemConfigCategory>.Instance.Get(self.BoxItemId).UseEffParams.Length; i++)
			{
				self.boxDropIds.Add(ConfigSingleton<ItemConfigCategory>.Instance.Get(self.BoxItemId).UseEffParams[i]);
			}
			foreach (int boxDropId in self.boxDropIds)
			{
				DropItem[] items = ConfigSingleton<DropShowConfigCategory>.Instance.Get(boxDropId).Items;
				foreach (DropItem dropItem in items)
				{
					self.BoxItemInfos.Add(new UIBoxItem
					{
						ItemId = dropItem.Id,
						ItemNums = dropItem.Nums,
						ItemOdds = dropItem.Odds
					});
				}
			}
			self._UIScrollList.SetData(self.BoxItemInfos.Count);
		}

		public static void OnCloseButtonClick(this UIBoxDetaPanel self)
		{
			UIManager.Instance.Remove(typeof(UIBoxDetaPanel));
		}

		private static void OnCellUpdate(this UIBoxDetaPanel self, UIScrollListCell cell)
		{
			int index = cell.Index;
			if (self.BoxItemInfos.Count > index)
			{
				UIBoxItem uIBoxItem = self.BoxItemInfos[index];
				UIBoxItem component = ((Entity)cell.UIObject).GetComponent<UIBoxItem>();
				switch (self.BoxType)
				{
				case 3:
					component.SetItem(uIBoxItem.ItemId, uIBoxItem.ItemNums, isShowProb: false);
					break;
				case 1:
					component.SetItem(uIBoxItem.ItemId, uIBoxItem.ItemNums, isShowProb: true, uIBoxItem.ItemOdds);
					break;
				}
			}
		}
	}
