		[UIMethod]
		public static void OnAwake(this UIBoxItem self)
		{
			self._SelectButton.AddClickHandler(self.OnClick);
		}

		public static void OnClick(this UIBoxItem self)
		{
			UIScrollList scrollList = ((Entity)self.UIObject).GetComponent<UIScrollListCell>().ScrollList;
			scrollList.SetSelectIndex((scrollList.CurrentSelectIndex == self.CurIndex) ? (-1) : self.CurIndex);
			self.ParentView?.RefreshView();
		}

		public static void SetItem(this UIBoxItem self, int configId, int nums, bool isShowProb, int prob = 0)
		{
			Init(self, configId, nums);
			if (isShowProb)
			{
				ShowProb(self, configId, nums, prob);
			}
			else
			{
				ShowNormal(self, configId, nums);
			}
		}

		public static void SetParentView(this UIBoxItem self, UISelfSelectBoxPanel parentView)
		{
			self.ParentView = parentView;
		}

		public static void SetSelfItem(this UIBoxItem self, int configId, int nums)
		{
			Init(self, configId, nums);
			self._SelectButton.SetActive(active: true);
			ShowNormal(self, configId, nums);
		}

		private static void Init(UIBoxItem self, int configId, int nums)
		{
			self._Item.SetItem(configId, nums);
			self._Item.UIObject.AddClickHandler(delegate
			{
				UICommonHelper.ShowItemTip(new ItemStruct
				{
					ConfigId = configId,
					Nums = nums
				});
			});
			self._ItemProbText.SetActive(active: false);
		}

		private static void ShowProb(UIBoxItem self, int configId, int nums, int prob)
		{
			self._SelectButton.SetActive(active: false);
			self._ProbDes.SetActive(active: true);
			self._SelfSelectDes.SetActive(active: false);
			self._ProbItemNameAndNumText.SetQuantityName(configId, "{0} x{1}", nums);
			self._ProbItemAddText.SetText("");
			self.ShowAddText(configId, nums);
			self._ItemProbText.SetActive(active: true);
			float num = (float)prob / 100f;
			self._ItemProbText.SetText($"{num}%");
		}

		private static void ShowNormal(UIBoxItem self, int configId, int nums)
		{
			if (ItemHelper.CheckEquipConfigContainKey(configId))
			{
				ShowEquip(self, configId, nums);
			}
			else
			{
				ShowItem(self, configId, nums);
			}
		}

		private static void ShowEquip(UIBoxItem self, int configId, int nums)
		{
			self._SelfSelectDes.SetActive(active: true);
			self._ProbDes.SetActive(active: false);
			self._PowItemNameAndNumText.SetQuantityName(configId, "{0} x{1}", nums);
			EquipConfig equipConfig = ConfigSingleton<EquipConfigCategory>.Instance.Get(configId);
			int equipId = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesEquipModule>().GetEquipId(equipConfig.Job, equipConfig.Part);
			long num = VibesHelper.EquipPowerDiff(configId, equipId);
			if (num > 0)
			{
				self._PowIcon.SetSprite("ui_common_sign_05").Coroutine();
				self._PowBg.SetSprite("ui_common_frame_32_gv").Coroutine();
				self._PowImage.SetSprite("ui_common_sign_03").Coroutine();
			}
			else
			{
				self._PowIcon.SetSprite("ui_common_sign_06").Coroutine();
				self._PowBg.SetSprite("ui_common_frame_33_gv").Coroutine();
				self._PowImage.SetSprite("ui_common_sign_04").Coroutine();
			}
			self._PowText.SetText(string.Format("<color=#{0}>{1}</color>", (num > 0) ? "448168" : "84604b", math.abs(num)));
		}

		private static void ShowItem(UIBoxItem self, int configId, int nums)
		{
			self._ProbDes.SetActive(active: true);
			self._SelfSelectDes.SetActive(active: false);
			self._ProbItemNameAndNumText.SetQuantityName(configId, "{0} x{1}", nums);
			self._ProbItemAddText.SetText("");
			self.ShowAddText(configId, nums);
		}

		private static void ShowAddText(this UIBoxItem self, int configId, int nums)
		{
			ItemConfig fromAll = ConfigSingleton<ItemConfigCategory>.Instance.GetFromAll(configId);
			if (fromAll.UseEff == 7)
			{
				int heroId = fromAll.UseEffParams[0];
				Hero hero = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<HeroModule>().GetHero(heroId);
				if (hero.IsActive)
				{
					self._ProbItemAddText.SetText($"(当前:<color=#0db64d>{hero.Star}星</color>)");
					self._ProbItemAddText.SetGray(isGray: false);
				}
				else
				{
					self._ProbItemAddText.SetText("(当前:未激活)");
					self._ProbItemAddText.SetGray();
				}
			}
			if (fromAll.Type == 9 || fromAll.Type == 8)
			{
				int heroId2 = fromAll.UseEffParams[0];
				Hero hero2 = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<HeroModule>().GetHero(heroId2);
				if (hero2.IsActiveJewelry(configId))
				{
					self._ProbItemAddText.SetText($"(当前:<color=#0db64d>{hero2.Jewelrys?.GetValueOrDefault(configId) ?? 0}星</color>)");
					self._ProbItemAddText.SetGray(isGray: false);
				}
				else
				{
					self._ProbItemAddText.SetText("(当前:未激活)");
					self._ProbItemAddText.SetGray();
				}
			}
		}
	}
