			self._Item._TextNums.SetText(self.AllNums + "/" + itemConfig.ComposeCost);
			self._Item._TextNums.SetText($"<color=#ff402b>{self.AllNums}</color>/{itemConfig.ComposeCost}");
			ConfigSingleton<ItemConfigCategory>.Instance.Get(itemConfig.ComposeItem.Id);
			self._ComposeItem.SetItem(itemConfig.ComposeItem.Id, 0L);
			self._ComposeItemName.SetText(UIItemHelper.GetItemNameWithColor(itemConfig.ComposeItem.Id));
			Slider component = self._Slider.GameObject.GetComponent<Slider>();
			component.minValue = 0f;
			component.maxValue = self.MaxNums;
			self.SetNums(self.MaxNums);
