		public static void OnSlideValueChange(this UIComposeItemPanel self, float value)
		{
			if (value < 1f)
			{
				self.SetNums(1);
				return;
			}
			self.CurNums = (int)math.ceil(value);
			self._Item.SetNums(self.CurNums * ConfigSingleton<ItemConfigCategory>.Instance.Get(self.ItemId).ComposeCost);
			self._Item._TextNums.SetText(self.AllNums + "/" + self.CurNums * ConfigSingleton<ItemConfigCategory>.Instance.Get(self.ItemId).ComposeCost);
			self._ItemNumber.SetText($"{self.CurNums}");
			self._ComposeItem.SetNums(self.CurNums * ConfigSingleton<ItemConfigCategory>.Instance.Get(self.ItemId).ComposeItem.Nums);
			self.SetChangeValueButtonImage();
		}

		private static void SetNums(this UIComposeItemPanel self, int nums)
		{
			self.CurNums = nums;
			self._ComposeItem.SetNums(self.CurNums * ConfigSingleton<ItemConfigCategory>.Instance.Get(self.ItemId).ComposeItem.Nums);
			self._ItemNumber.SetText($"{self.CurNums}");
			self._Slider.GameObject.GetComponent<Slider>().value = nums;
			if (!self.IsCompose)
			{
				self._Item._TextNums.SetText($"<color=#ff402b>{self.AllNums}</color>/{ConfigSingleton<ItemConfigCategory>.Instance.Get(self.ItemId).ComposeCost}");
				return;
			}
			self._Item.SetNums(ConfigSingleton<ItemConfigCategory>.Instance.Get(self.ItemId).ComposeCost * self.CurNums);
			self._Item._TextNums.SetText(self.AllNums + "/" + self.CurNums * ConfigSingleton<ItemConfigCategory>.Instance.Get(self.ItemId).ComposeCost);
		}

