			self._Item.SetClickDisabled();
		}

		private static void SetData(this UIGemTipsPanel self, ItemStruct item)
		{
			//IL_00bd: Unknown result type (might be due to invalid IL or missing references)
			//IL_00c3: Unknown result type (might be due to invalid IL or missing references)
			//IL_00c7: Unknown result type (might be due to invalid IL or missing references)
			//IL_00cd: Unknown result type (might be due to invalid IL or missing references)
			int configId = item.ConfigId;
			GemStoneConfig gemStoneConfig = ConfigSingleton<GemStoneConfigCategory>.Instance.Get(item.ConfigId);
			self._Item.SetItem(configId, item.Nums);
			self._CountText.SetText($"数量：{item.Nums}");
			self._ItemDesPanel.SetRawTexture($"ui_tips_frame_{gemStoneConfig.Quality:00}").Coroutine();
			self._NameText.SetText(gemStoneConfig.Name);
			string text = gemStoneConfig.Quality switch
			{
				6 => "ui_fx_zhuangbei_hong", 
				7 => "ui_fx_zhuangbei_cai", 
				_ => null, 
			};
			if (text != null)
			{
				self._ItemDesEffect.PlayEffect(text);
			}
			using PowerCalc powerCalc = PowerCalc.Create();
			powerCalc.AddStats(gemStoneConfig.AddStats);
			self._Power.SetPower(powerCalc.Power);
			int gemMaxLevel = VibesHelper.GetGemMaxLevel(gemStoneConfig.Job, gemStoneConfig.PositionType);
			int num = 0;
			StringBuilder stringBuilder = new StringBuilder();
			for (int i = 1; i <= gemMaxLevel; i++)
			{
				if (i == gemStoneConfig.Level)
				{
					num = i;
				}
				Stat stat = ConfigSingleton<GemStoneConfigCategory>.Instance.Get(gemStoneConfig.Job * 10000 + gemStoneConfig.PositionType * 1000 + i).AddStats[0];
				string valueText = new StatStruct
				{
					Type = stat.Type,
					Value = stat.Value
				}.GetValueText();
				stringBuilder.Append(string.Format("<color=#{0}>[{1}级] {2} +{3}</color>{4}", new object[5]
				{
					(i == gemStoneConfig.Level) ? "0db64d" : "566458",
					i,
					stat.GetName(),
					valueText,
					(i == gemMaxLevel) ? "" : "\n"
				}));
			}
			self._Desc.SetText(stringBuilder.ToString());
			LayoutRebuilder.ForceRebuildLayoutImmediate(self._Desc.Transform);
			self._Desc.GameObject.GetComponentInParent<ScrollRect>().MoveToPositionY((num - 1) * 33);
			self._UIItemTipsPowerProvideArea.SetGem(gemStoneConfig);
		}
	}
