		private static void OnClickOwnerNode(this UIItemTipsFaBaoSkillItem self)
		{
			if (FaBaoHelper.GetStarConfig(((Entity)(object)self).LocalPlayer(), self.FaBaoId).MasterSkillId == self.SkillLevelId)
			{
				UIGameMsgHelper.FloatMsg(UIHeroHelper.GetHeroName(ConfigSingleton<FaBaoConfigCategory>.Instance.Get(self.FaBaoId).HeroId) + "专属法宝");
			}
		}

		public static void SetData(this UIItemTipsFaBaoSkillItem self, ItemConfig config, int skillLevelId, FaBaoInfo faBaoInfo)
		{
			self._UIItemTipsSkillItem.SetData(skillLevelId, config.Quality);
			SkillLevel skillLevel = new SkillLevel(skillLevelId);
			self._SkillLevel.SetText($"{skillLevel.Level}级");
			int num = faBaoInfo?.ConfigId ?? config.UseEffParams.GetValueOrDefault(0, 0);
			self.SkillLevelId = skillLevelId;
			self.FaBaoId = num;
			FaBaoConfig faBaoConfig = ConfigSingleton<FaBaoConfigCategory>.Instance.Get(num);
			int star = faBaoInfo?.Star ?? 0;
			FaBaoStarConfig faBaoStarConfig = ConfigSingleton<FaBaoStarConfigCategory>.Instance.Get(num, star);
			self._OwnerNode.SetActive(faBaoStarConfig.MasterSkillId == skillLevelId);
			self._MasterFlag.SetActive(faBaoStarConfig.MasterSkillId == skillLevelId);
			if (faBaoConfig.HeroId != 0)
			{
				int num2 = faBaoInfo?.Owner ?? 0;
				if (faBaoConfig.HeroId == num2)
				{
					self._OwnerNode.SetSprite("ui_fb_wp_02").Coroutine();
					self._OwnerText.SetText("已激活");
				}
				else
				{
					self._OwnerNode.SetSprite("ui_fab_frame05").Coroutine();
					HeroConfig heroConfig = ConfigSingleton<HeroConfigCategory>.Instance.Get(faBaoConfig.HeroId);
					self._OwnerText.SetText("专属：" + heroConfig.HeroName);
				}
			}
		}
	}
