					break;
				case 4:
				{
					ActivityData activityData = ActivityHelper.GetActivityData(player, itemObtainWayConfig.Param[0]);
					if (activityData != null && !activityData.IsHide())
					{
						self.ObtainWayConfigs.Add(new ItemObtainWayConfig
						{
							Type = 4,
							Param = new int[1] { activityData.ActivityId },
							Sort = itemObtainWayConfig.Sort
						});
					}
					if (activityData == null && !flag)
					{
						flag = true;
						self.ObtainWayConfigs.Add(ConfigSingleton<ItemObtainWayConfigCategory>.Instance.Get(6));
					}
					break;
				}
				case 5:
					self.ObtainWayConfigs.Add(itemObtainWayConfig);
					break;
				case 7:
					if (component.GetItemNumsByItemId(itemObtainWayConfig.Param[0]) > 0)
