					long itemNumsByItemId = component.GetItemNumsByItemId(itemObtainWayConfig.Param[0]);
					ItemConfig itemConfig2 = ET.ItemHelper.GetItemConfig(itemObtainWayConfig.Param[0]);
					if (itemConfig2 != null)
					{
