						{
							self.ObtainWayConfigs.Add(new ItemObtainWayConfig
							{
								Type = itemObtainWayConfig.Type,
								Param = itemObtainWayConfig.Param,
								Sort = itemObtainWayConfig.Sort - 1000
							});
						}
						else
						{
							self.ObtainWayConfigs.Add(itemObtainWayConfig);
						}
					}
					break;
				}
				case 8:
				{
					long itemNumsByItemId2 = component.GetItemNumsByItemId(itemObtainWayConfig.Param[0]);
					Hero hero = HeroHelper.GetHero(configId: ConfigSingleton<ItemConfigCategory>.Instance.Get(self.NeedItemId).UseEffParams[0], player: ((Entity)(object)self).LocalPlayer());
					if (itemNumsByItemId2 > 0 && hero != null && hero.IsActive)
