					}
					break;
				}
				case 10:
					if (itemObtainWayConfig.Param.Length != 0)
					{
						ActivityData activityDataByType = player.GetActivityDataByType((ActivityType)itemObtainWayConfig.Param[0]);
						if (activityDataByType != null && !activityDataByType.IsHide())
						{
							self.ObtainWayConfigs.Add(new ItemObtainWayConfig
							{
								Type = 4,
								Param = new int[1] { activityDataByType.ActivityId },
								Sort = itemObtainWayConfig.Sort
							});
						}
						if (activityDataByType == null && !flag)
