					foreach (int item in list)
					{
						SortedDictionary<int, GiftItemDate> giftItemDate = component2.GetGiftItemDate(item);
						if (giftItemDate != null)
						{
							GiftItemDate giftItemDate2 = self.GetGiftItemDate(giftItemDate);
							if (giftItemDate2 != null)
							{
								self.ObtainWayConfigs.Add(new ItemObtainWayConfig
								{
									Type = 11,
									Id = itemObtainWayConfig.Id,
									Param = new int[2] { giftItemDate2.cost, item },
