			}).Coroutine();
		}

		public static int GetShowCount(this UIItemTipsObtainWayArea self)
		{
			return self.ObtainWayConfigs.Count;
		}

		public static void SetData(this UIItemTipsObtainWayArea self, int itemConfigId)
		{
			self.NeedItemId = itemConfigId;
			self.NeedNums = 0;
			self.RefreshView();
		}

		private static GiftItemDate GetGiftItemDate(this UIItemTipsObtainWayArea self, SortedDictionary<int, GiftItemDate> gifts)
		{
			foreach (GiftItemDate item in gifts.Values.Reverse())
			{
				ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), item.activityId);
				if (activityData == null)
				{
					continue;
				}
				switch (item.giftType)
				{
				case GiftType.DirectBuyGift:
				{
					DirectBuyGiftModule component3 = ((Entity)activityData).GetComponent<DirectBuyGiftModule>();
					if (component3 != null && component3.IsGiftCanBuy(item.configId))
					{
						return item;
					}
					break;
				}
				case GiftType.DirectBuyThemeGift:
				{
					DirectBuyThemeGiftModule component2 = ((Entity)activityData).GetComponent<DirectBuyThemeGiftModule>();
					if (component2 != null && !component2.IsGiftCanBuy(item.configId))
					{
						return item;
					}
					break;
				}
				case GiftType.DirectBuyEveryDayGift:
				{
					DirectBuyEveryDayGiftModule component = ((Entity)activityData).GetComponent<DirectBuyEveryDayGiftModule>();
					if (component != null && !component.IsBuyOver())
					{
						return item;
					}
					break;
				}
				}
			}
			return null;
		}
	}
