		private static int GetStatsCount(this UIItemTipsPanel self, ItemConfig config)
		{
			switch (config.Type)
			{
			case 4:
			case 10:
			case 12:
			case 13:
				return 1;
			case 8:
			case 9:
				return 2;
			case 15:
			{
				if (self.FaBaoInfo == null)
				{
					return 1;
				}
				List<long> soulIds = self.FaBaoInfo.SoulIds;
				if (soulIds != null && soulIds.Count > 0)
				{
					return 3;
				}
				return 2;
			}
			case 16:
				return 1;
			default:
				return 0;
			}
		}

		private static void GetStatByIndex(this UIItemTipsPanel self, ItemConfig config, int index, StatList statList)
		{
			switch (config.Type)
			{
			case 4:
				statList.AddRange((config as EquipConfig).EquipStat);
				break;
			case 13:
			{
				int valueOrDefault = config.UseEffParams.GetValueOrDefault(0, 0);
				statList.AddRange(ConfigSingleton<FashionPowerConfigCategory>.Instance.Get(valueOrDefault * 10)?.Stats);
				break;
			}
			case 10:
			{
				BeastConfig beastConfig = ConfigSingleton<BeastConfigCategory>.Instance.Get(config.UseEffParams.GetValueOrDefault(0, 0));
				statList.AddRange(beastConfig.Stats);
				break;
			}
			case 12:
				statList.AddRange((config as BeastSoulConfig).AddStats);
				break;
			case 8:
			case 9:
				if (index == 0)
				{
					int id = config.Id * 100;
					JewelryStarConfig jewelryStarConfig = ConfigSingleton<JewelryStarConfigCategory>.Instance.Get(id);
					statList.AddRange(jewelryStarConfig.AllStat);
				}
				else
				{
					int id2 = config.Id * 100;
					JewelryStarConfig jewelryStarConfig2 = ConfigSingleton<JewelryStarConfigCategory>.Instance.Get(id2);
					statList.AddRange(jewelryStarConfig2.Stats);
				}
				break;
			case 15:
			{
				int num = self.FaBaoInfo?.ConfigId ?? config.UseEffParams.GetValueOrDefault(0, 0);
				switch (index)
				{
				case 0:
				{
					int level = self.FaBaoInfo?.Level ?? 1;
					ConfigSingleton<FaBaoLevelConfigCategory>.Instance.GetLevelStat(num, level, statList);
					break;
				}
				case 1:
				{
					int star = self.FaBaoInfo?.Star ?? 0;
					FaBaoStarConfig faBaoStarConfig = ConfigSingleton<FaBaoStarConfigCategory>.Instance.Get(num, star);
					statList.AddRange(faBaoStarConfig.BaseStats);
					break;
				}
				case 2:
					((Entity)((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FaBaoModule>()).GetChild<FaBao>((long)num)?.GetSoulStatList(statList);
					break;
				}
				break;
			}
			case 16:
				if (index == 0)
				{
					ConfigSingleton<FaBaoSoulLevelConfigCategory>.Instance.GetLevelStat(config.Id, 0, statList);
				}
				break;
			case 5:
			case 6:
			case 7:
			case 11:
			case 14:
				break;
			}
		}

		private static string GetStateTitleByIndex(this UIItemTipsPanel self, ItemConfig config, int index)
		{
			switch (config.Type)
			{
			case 4:
			case 10:
			case 12:
			case 13:
			case 16:
				return "基础属性";
			case 8:
			case 9:
				if (index == 0)
				{
					return "基础属性";
				}
				return "专属属性";
			case 15:
				return index switch
				{
					0 => "基础属性", 
					1 => "升星属性", 
					2 => "附魂属性", 
					_ => string.Empty, 
				};
			default:
				return string.Empty;
			}
		}

