	public static class UIObtainWayHelper
	{
		public static ETTask ShowPanelAsync(ET.ConfigBeans.Item item, Action callback = null)
		{
			return ShowPanelAsync(item.Id, item.Nums, callback);
		}

		public static ETTask ShowPanelAsync(int itemId, int nums = 0, Action callback = null)
		{
			ETTask result = ETTask.Create(false);
			int[] itemObtainWaysByItemId = ItemHelper.GetItemObtainWaysByItemId(itemId);
			if (itemObtainWaysByItemId.Length >= 1)
			{
				ItemObtainWayConfig config = ConfigSingleton<ItemObtainWayConfigCategory>.Instance.Get(itemObtainWaysByItemId[0]);
				if (config.Type == 6)
				{
					ItemConfig itemConfig = ConfigSingleton<ItemConfigCategory>.Instance.Get(itemId);
					UICommonHelper.ShowConfirmPanel(new ConfirmPanelOptions
					{
						Message = Language.Format(2, 319, itemConfig.Name),
						ConfirmKey = "ObtainWayTips",
						NoConfirmTillTime = TimeHelper.EndTimeOfDay(TimeHelper.Now(), 18000000L),
						OkAction = delegate
						{
							callback?.Invoke();
							UIJumpHelper.To(config.Param[0]).Coroutine();
							result.SetResult();
						},
						CancelAction = delegate
						{
							result.SetResult();
						}
					});
					return result;
				}
			}
			UIManager.Instance.Show<UIObtainWayPanel, UIShowArgs>(new UIObtainWayPanelShowArgs
			{
				ItemId = itemId,
				ItemNums = nums,
				Callback = delegate
				{
					result.SetResult();
				}
			}).Coroutine();
			return result;
		}

		public static ETTask ShowPanelAsync(int[] obtainWayIds)
		{
			ETTask result = ETTask.Create(false);
			UIManager.Instance.Show<UIObtainWayPanel, UIShowArgs>(new UIObtainWayPanelShowArgs
			{
				ObtainWayIds = obtainWayIds,
				Callback = delegate
				{
					result.SetResult();
				}
			}).Coroutine();
			return result;
		}

		public static List<ItemObtainWayConfig> ProcessShopConfig(Player player, ItemObtainWayConfig config, int itemId, out HashSet<int> moneyTypes)
		{
			ShopModule component = ((Entity)player).GetComponent<ShopModule>();
			moneyTypes = new HashSet<int>();
			List<ItemObtainWayConfig> list = new List<ItemObtainWayConfig>();
			int num = ((config.Param != null && config.Param.Length != 0) ? config.Param[0] : (-1));
			if (!player.IsFuncOpen(num))
			{
				return list;
			}
			foreach (ShopGoodsConfig value in ConfigSingleton<ShopGoodsConfigCategory>.Instance.GetAll().Values)
			{
				if (value.ShopType == num && value.Item.Id == itemId && player.CheckAllConds(value.ShowConds) && player.CheckAllConds(value.OpenConds))
				{
					bool flag = component.CheckBuyCond(value.Id, 1) != 0;
					moneyTypes.Add(value.MoneyType);
					list.Add(new ItemObtainWayConfig
					{
						Type = 1,
						Param = new int[1] { value.Id },
						Sort = (flag ? (config.Sort - 1000) : config.Sort)
					});
				}
			}
			return list;
		}
	}
