		private static void RefreshList(this UIObtainWayPanel self)
		{
			Player player = ((Entity)(object)self).LocalPlayer();
			ItemModule component = ((Entity)player).GetComponent<ItemModule>();
			((Entity)player).GetComponent<PlayerActivityComponent>();
			int[] obj = self.Args.ObtainWayIds ?? ItemHelper.GetItemObtainWaysByItemId(self.Args.ItemId);
			self.ObtainWayConfigs.Clear();
			HashSet<int> hashSet = new HashSet<int>();
			bool flag = false;
			int[] array = obj;
			foreach (int id in array)
			{
				ItemObtainWayConfig itemObtainWayConfig = ConfigSingleton<ItemObtainWayConfigCategory>.Instance.Get(id);
				switch (itemObtainWayConfig.Type)
				{
				case 1:
				{
					List<ItemObtainWayConfig> collection = UIObtainWayHelper.ProcessShopConfig(player, itemObtainWayConfig, self.Args.ItemId, out var moneyTypes);
					hashSet.UnionWith(moneyTypes);
					self.ObtainWayConfigs.AddRange(collection);
					break;
				}
				case 2:
				case 3:
					if (component.GetItemNumsByItemId(itemObtainWayConfig.Param[0]) > 0)
					{
						self.ObtainWayConfigs.Add(itemObtainWayConfig);
					}
					break;
				case 4:
				{
					ActivityData activityData = ActivityHelper.GetActivityData(player, itemObtainWayConfig.Param[0]);
					if (activityData != null && !activityData.IsHide())
					{
						self.ObtainWayConfigs.Add(new ItemObtainWayConfig
						{
							Type = 4,
							Param = new int[1] { activityData.ActivityId },
							Sort = itemObtainWayConfig.Sort
						});
					}
					if (activityData == null && !flag)
					{
						flag = true;
						self.ObtainWayConfigs.Add(ConfigSingleton<ItemObtainWayConfigCategory>.Instance.Get(6));
					}
					break;
				}
				case 5:
					if (player.IsFuncOpen(itemObtainWayConfig.Param[0]))
					{
						self.ObtainWayConfigs.Add(itemObtainWayConfig);
						break;
					}
					self.ObtainWayConfigs.Add(new ItemObtainWayConfig
					{
						Type = itemObtainWayConfig.Type,
						Param = itemObtainWayConfig.Param,
						Sort = itemObtainWayConfig.Sort - 1000
					});
					break;
				case 9:
				{
					long itemNumsByItemId = component.GetItemNumsByItemId(itemObtainWayConfig.Param[0]);
					ItemConfig itemConfig = ConfigSingleton<ItemConfigCategory>.Instance.Get(itemObtainWayConfig.Id);
					if (itemConfig != null)
					{
						if (itemConfig.ComposeCost > itemNumsByItemId)
						{
							self.ObtainWayConfigs.Add(new ItemObtainWayConfig
							{
								Type = itemObtainWayConfig.Type,
								Param = itemObtainWayConfig.Param,
								Sort = itemObtainWayConfig.Sort - 1000
							});
						}
						else
						{
							self.ObtainWayConfigs.Add(itemObtainWayConfig);
						}
					}
					break;
				}
				case 7:
					if (component.GetItemNumsByItemId(itemObtainWayConfig.Param[0]) > 0)
					{
						self.ObtainWayConfigs.Add(itemObtainWayConfig);
					}
					break;
				case 8:
				{
					long itemNumsByItemId2 = component.GetItemNumsByItemId(itemObtainWayConfig.Param[0]);
					Hero hero = HeroHelper.GetHero(configId: ConfigSingleton<ItemConfigCategory>.Instance.Get(self.Args.ItemId).UseEffParams[0], player: ((Entity)(object)self).LocalPlayer());
					if (itemNumsByItemId2 > 0 && hero != null && hero.IsActive)
					{
						self.ObtainWayConfigs.Add(itemObtainWayConfig);
					}
					break;
				}
				case 10:
					if (itemObtainWayConfig.Param.Length != 0)
					{
						ActivityData activityDataByType = player.GetActivityDataByType((ActivityType)itemObtainWayConfig.Param[0]);
						if (activityDataByType != null && !activityDataByType.IsHide())
						{
							self.ObtainWayConfigs.Add(new ItemObtainWayConfig
							{
								Type = 4,
								Param = new int[1] { activityDataByType.ActivityId },
								Sort = itemObtainWayConfig.Sort
							});
						}
						if (activityDataByType == null && !flag)
						{
							flag = true;
							self.ObtainWayConfigs.Add(ConfigSingleton<ItemObtainWayConfigCategory>.Instance.Get(6));
						}
					}
					if (itemObtainWayConfig.Param.Length == 0)
					{
						flag = true;
						self.ObtainWayConfigs.Add(ConfigSingleton<ItemObtainWayConfigCategory>.Instance.Get(6));
					}
					break;
				case 11:
				{
					List<int> list = new List<int>();
					list.Add(self.Args.ItemId);
					if (itemObtainWayConfig.Param != null && itemObtainWayConfig.Param.Length != 0)
					{
						list.AddRange(itemObtainWayConfig.Param);
					}
					foreach (int item in list)
					{
						SortedDictionary<int, GiftItemDate> giftItemDate = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<GiftModule>().GetGiftItemDate(item);
						if (giftItemDate != null)
						{
							GiftItemDate giftItemDate2 = self.GetGiftItemDate(giftItemDate);
							if (giftItemDate2 != null)
							{
								self.ObtainWayConfigs.Add(new ItemObtainWayConfig
								{
									Type = 11,
									Id = itemObtainWayConfig.Id,
									Param = new int[2] { giftItemDate2.cost, item },
									Sort = itemObtainWayConfig.Sort
								});
								break;
							}
						}
					}
					break;
				}
				default:
					Log.Error($"获取途径遇到无法处理的类型 type = {itemObtainWayConfig.Type} id = {itemObtainWayConfig.Id}");
					break;
				}
			}
			self.ObtainWayConfigs.Sort((ItemObtainWayConfig a, ItemObtainWayConfig b) => b.Sort - a.Sort);
			self._WayScrollList.SetData(self.ObtainWayConfigs.Count);
		}

		private static void OnClose(this UIObtainWayPanel self)
		{
			UIManager.Instance.Remove(((object)self).GetType());
		}

		private static string GetPrefabName(this UIObtainWayPanel self, int index)
		{
			if (index >= self.ObtainWayConfigs.Count)
			{
				return "UIObtainWayFuncItem";
			}
			switch (self.ObtainWayConfigs[index].Type)
			{
			case 1:
				return "UIObtainWayShopGoodsItem";
			case 2:
			case 3:
			case 7:
			case 8:
			case 9:
				return "UIObtainWayGiftItem";
			case 4:
			case 5:
				return "UIObtainWayFuncItem";
			case 11:
				return "UIObtainWayDirectGiftItem";
			default:
				return "UIObtainWayFuncItem";
			}
		}

		private static void OnItemUpdate(this UIObtainWayPanel self, UIScrollListCell cell)
		{
			int index = cell.Index;
			if (index < self.ObtainWayConfigs.Count)
			{
				ItemObtainWayConfig itemObtainWayConfig = self.ObtainWayConfigs[index];
				switch (itemObtainWayConfig.Type)
				{
				case 1:
					((Entity)cell.UIObject).GetComponent<UIObtainWayShopGoodsItem>().SetData(itemObtainWayConfig, self.Args.ItemId, self.Args.ItemNums);
					break;
				case 2:
				case 3:
				case 7:
				case 8:
				case 9:
					((Entity)cell.UIObject).GetComponent<UIObtainWayGiftItem>().SetData(itemObtainWayConfig, self.Args.ItemId, self.Args.ItemNums, self.RefreshList);
					break;
				case 4:
				case 5:
					((Entity)cell.UIObject).GetComponent<UIObtainWayFuncItem>().SetData(itemObtainWayConfig, self.OnClose);
					break;
				case 11:
					((Entity)cell.UIObject).GetComponent<UIObtainWayDirectGiftItem>().SetData(itemObtainWayConfig, self.Args.ItemId);
					break;
				case 6:
				case 10:
					break;
				}
			}
		}

		private static GiftItemDate GetGiftItemDate(this UIObtainWayPanel self, SortedDictionary<int, GiftItemDate> gifts)
		{
			foreach (GiftItemDate item in gifts.Values.Reverse())
			{
				ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), item.activityId);
				if (activityData == null)
				{
					continue;
				}
				switch (item.giftType)
				{
				case GiftType.DirectBuyGift:
				{
					DirectBuyGiftModule component3 = ((Entity)activityData).GetComponent<DirectBuyGiftModule>();
					if (component3 != null && component3.IsGiftCanBuy(item.configId))
					{
						return item;
					}
					break;
				}
				case GiftType.DirectBuyThemeGift:
				{
					DirectBuyThemeGiftModule component2 = ((Entity)activityData).GetComponent<DirectBuyThemeGiftModule>();
					if (component2 != null && !component2.IsGiftCanBuy(item.configId))
					{
						return item;
					}
					break;
				}
				case GiftType.DirectBuyEveryDayGift:
				{
					DirectBuyEveryDayGiftModule component = ((Entity)activityData).GetComponent<DirectBuyEveryDayGiftModule>();
					if (component != null && !component.IsBuyOver())
					{
						return item;
					}
					break;
				}
				}
			}
			return null;
		}
	}
