		public static void InitPanel(this UISelfSelectBoxPanel self, BagItemInfo bagItemInfo, int targetItemId = 0, int needNums = 0)
		{
			if (bagItemInfo.ConfigId <= 0 || bagItemInfo.Nums <= 0)
			{
				return;
			}
			ItemConfig itemConfig = ConfigSingleton<ItemConfigCategory>.Instance.Get(bagItemInfo.ConfigId);
			self._TitleText.SetText(itemConfig.Name);
			self.BoxId = bagItemInfo.ConfigId;
			self.MaxNums = bagItemInfo.Nums;
			self.TargetItemId = targetItemId;
			Slider component = self._Slider.GameObject.GetComponent<Slider>();
			component.minValue = 0f;
			component.maxValue = self.MaxNums;
			self.UpdateItemView();
			self.RefreshView();
			int nums = self.MaxNums;
			if (targetItemId != 0 && needNums != 0)
			{
				int num = (int)((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().GetItemNumsByItemId(targetItemId);
				int num2 = 0;
				int[] useEffParams = ConfigSingleton<ItemConfigCategory>.Instance.Get(self.BoxId).UseEffParams;
				if (useEffParams.Length != 0)
				{
					int[] array = useEffParams;
					foreach (int id in array)
					{
						DropShowConfig dropShowConfig = ConfigSingleton<DropShowConfigCategory>.Instance.Get(id);
						for (int j = 0; j < dropShowConfig.Items.Length; j++)
						{
							DropItem dropItem = dropShowConfig.Items[j];
							if (dropItem.Id == targetItemId)
							{
								num2 += dropItem.Nums;
							}
						}
						if (num2 > 0)
						{
							break;
						}
					}
				}
				if (num2 > 0)
				{
					nums = (needNums - num + num2 - 1) / num2;
					nums = Math.Min(nums, self.MaxNums);
				}
			}
			if (itemConfig.Type == 6 && needNums == 0)
			{
				nums = 1;
			}
			self.SetNum(nums);
		}

		public static void RefreshView(this UISelfSelectBoxPanel self)
		{
			self._UseButton.SetGray(self._UIScrollList.CurrentSelectIndex < 0);
		}

		private static void UpdateItemView(this UISelfSelectBoxPanel self)
		{
			self.BoxItemInfos.Clear();
			self.boxDropIds.Clear();
			int[] useEffParams = ConfigSingleton<ItemConfigCategory>.Instance.Get(self.BoxId).UseEffParams;
			if (useEffParams.Length == 0)
			{
				return;
			}
			self.boxDropIds.AddRange(useEffParams);
			foreach (int boxDropId in self.boxDropIds)
			{
				DropShowConfig dropShowConfig = ConfigSingleton<DropShowConfigCategory>.Instance.Get(boxDropId);
				for (int i = 0; i < dropShowConfig.Items.Length; i++)
				{
					DropItem dropItem = dropShowConfig.Items[i];
					self.BoxItemInfos.Add(new UIBoxItem
					{
						ItemId = dropItem.Id,
						ItemNums = dropItem.Nums,
						ItemOdds = dropItem.Odds,
						DropIndex = i
					});
				}
			}
			self.BoxItemInfos.Sort(delegate(UIBoxItem a, UIBoxItem b)
			{
				if (a.ItemId == b.ItemId)
				{
					return 0;
				}
				if (a.ItemId == self.TargetItemId)
				{
					return -1;
				}
				return (b.ItemId == self.TargetItemId) ? 1 : (a.ItemId - b.ItemId);
			});
			self._UIScrollList.SetData(self.BoxItemInfos.Count);
			self._UIScrollList.SetSelectIndex(0);
		}

		private static void OnClickCloseButton(this UISelfSelectBoxPanel self)
		{
			UIManager.Instance.Remove(typeof(UISelfSelectBoxPanel));
		}

		private static void OnCellUpdate(this UISelfSelectBoxPanel self, UIScrollListCell cell)
		{
			int index = cell.Index;
			UIBoxItem uIBoxItem = self.BoxItemInfos[index];
			UIBoxItem component = ((Entity)cell.UIObject).GetComponent<UIBoxItem>();
			component.CurIndex = index;
			component.SetParentView(self);
			component.SetSelfItem(uIBoxItem.ItemId, uIBoxItem.ItemNums);
			component._SelectImage.SetActive(index == self._UIScrollList.CurrentSelectIndex);
			component._TargetTips.SetActive(uIBoxItem.ItemId == self.TargetItemId);
		}

		private static void SetNum(this UISelfSelectBoxPanel self, int nums)
		{
			self.CurNums = nums;
			self._Slider.GameObject.GetComponent<Slider>().value = nums;
			self._ItemNumber.SetText(nums.ToString());
			string spriteName = ((nums <= 1) ? "ui_bag_btn_06" : "ui_bag_btn_07");
			string spriteName2 = ((nums >= self.MaxNums) ? "ui_bag_btn_06" : "ui_bag_btn_07");
			self._SubButton.SetSprite(spriteName).Coroutine();
			self._AddButton.SetSprite(spriteName2).Coroutine();
		}

		private static void ChangeSliderValue(this UISelfSelectBoxPanel self, float value)
		{
			self.SetNum((int)math.max(1f, math.ceil(value)));
		}

		public static void AddNum(this UISelfSelectBoxPanel self, BaseEventData eventData)
		{
			if (self.Timer != 0L)
			{
				return;
			}
			self.Timer = self.NewTimer(500L, delegate
			{
				if (self.CurNums >= self.MaxNums)
				{
					UIGameMsgHelper.FloatMsg(Language.Get(4, 704));
					self.RemoveTimer(ref self.Timer);
				}
				else
				{
					self.SetNum(self.CurNums + 1);
				}
			}, repeat: true);
		}

		public static void AddNum1(this UISelfSelectBoxPanel self, BaseEventData eventData)
		{
			if (self.Timer != 0L)
			{
				self.RemoveTimer(ref self.Timer);
			}
		}

		public static void SubNum(this UISelfSelectBoxPanel self, BaseEventData eventData)
		{
			if (self.Timer != 0L)
			{
				return;
			}
			self.Timer = self.NewTimer(500L, delegate
			{
				if (self.CurNums <= 1)
				{
					UIGameMsgHelper.FloatMsg(Language.Get(4, 705));
					self.RemoveTimer(ref self.Timer);
				}
				else
				{
					self.SetNum(self.CurNums - 1);
				}
			}, repeat: true);
		}

		public static void SubNum1(this UISelfSelectBoxPanel self, BaseEventData eventData)
		{
			if (self.Timer != 0L)
			{
				self.RemoveTimer(ref self.Timer);
			}
		}

		private static void OnSubButtonClick(this UISelfSelectBoxPanel self)
		{
			if (self.CurNums <= 1)
			{
				UIGameMsgHelper.FloatMsg(Language.Get(4, 705));
			}
			else
			{
				self.SetNum(self.CurNums - 1);
			}
		}

		private static void OnAddButtonClick(this UISelfSelectBoxPanel self)
		{
			if (self.CurNums >= self.MaxNums)
			{
				UIGameMsgHelper.FloatMsg(Language.Get(4, 704));
			}
			else
			{
				self.SetNum(self.CurNums + 1);
			}
		}

		private static async void OnUseButtonClick(this UISelfSelectBoxPanel self)
		{
			if (self._UIScrollList.CurrentSelectIndex < 0)
			{
				UIGameMsgHelper.FloatMsg("请点击选择上方道具");
				return;
			}
			UIBoxItem uIBoxItem = self.BoxItemInfos[self._UIScrollList.CurrentSelectIndex];
			UIGameMsgHelper.FloatMsgByError(await ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().ReqUseItem(self.BoxId, self.CurNums, uIBoxItem.DropIndex));
			UIManager.Instance.Remove(typeof(UISelfSelectBoxPanel));
		}

		public static UIBoxItem GetCurrentSelectItemInfo(this UISelfSelectBoxPanel self)
		{
			if (self._UIScrollList.CurrentSelectIndex >= 0)
			{
				return self.BoxItemInfos[self._UIScrollList.CurrentSelectIndex];
			}
			return null;
		}
	}
