		public static void UpdateSellRewardNum(this UISellItemPanel self)
		{
			ItemConfig itemConfig = ConfigSingleton<ItemConfigCategory>.Instance.Get(self.ItemId);
			if (itemConfig.SellReward == null)
			{
				self._RewardIcon.SetRawTexture("ui_main_sign_22").Coroutine();
				self._RewardText.SetText("0");
				return;
			}
			string str = TextHelper.FormatItemNums(itemConfig.SellReward.Nums * self.CurNums);
			self._RewardIcon.SetRawTexture($"uitex_icon_item_{itemConfig.SellReward.Id}").Coroutine();
			self._RewardText.SetText(str);
			self._RewardText.Transform.SetSizeWithCurrentAnchors((Axis)0, ((Text)self._RewardText.GameObject.GetComponent<SuperText>()).preferredWidth);
		}

