			((Image)((Component)self._MonsterHpNext.Transform).GetComponent<SuperImage>()).fillAmount = num;
			int num2 = unit.ConfigId % 10000 - 1 + wave;
			self._MonsterIcon.SetSprite($"ui_sht_box_{num2}", nativeSize: true).Coroutine();
		}

