		public static int GetDiff(this UIBattleBubbleGroup self, Dup dup)
		{
			foreach (DJHeroLevelConfig item in ConfigSingleton<DJHeroLevelConfigCategory>.Instance.GetList())
			{
				if (item.Id > dup.Level - 1 && item.HangupReward != null)
				{
					return item.Id - dup.Level + 1;
				}
			}
			return 0;
		}

		public static int GetDiff(this UIBattleBubbleGroup self, int level)
		{
			foreach (DJHeroLevelConfig item in ConfigSingleton<DJHeroLevelConfigCategory>.Instance.GetList())
			{
