		{
			List<DJHeroLevelConfig> list = ConfigSingleton<DJHeroLevelConfigCategory>.Instance.GetList();
			DJHeroLevelConfig dJHeroLevelConfig = null;
			foreach (DJHeroLevelConfig item in list)
			{
				if (item.Id > dup.Level - 1 && item.HangupReward != null)
				{
					dJHeroLevelConfig = item;
					break;
				}
			}
			if (dJHeroLevelConfig == null)
			{
				self.UIObject.SetActive(active: false);
				return;
			}
			self.UIObject.SetActive(active: true);
			self._Tips.SetText(Language.Format(4, 813, dJHeroLevelConfig.Id - dup.Level + 1));
			self._Icon.SetActive(active: false);
			self._Icon.SetRawTexture($"uitex_icon_item_{dJHeroLevelConfig.HangupReward[0].Id}").Coroutine();
			self._Icon.SetActive(active: true);
			self._Num.SetText($"x{dJHeroLevelConfig.HangupReward[0].Nums}");
		}

