		public static void SetData(this UIBattleBuildBar self, AncientWarBuild ancientWarBuild)
		{
			self.ConfigId = ancientWarBuild.ConfigId;
			AncientWarMonsterConfig ancientWarMonsterConfig = ConfigSingleton<AncientWarMonsterConfigCategory>.Instance.Get(ancientWarBuild.ConfigId);
			self._HpBar.Transform.SetSizeWithCurrentAnchors((Axis)0, (float)ancientWarMonsterConfig.HpWidth);
			float num = (float)ancientWarBuild.Hp * 1f / (float)ancientWarBuild.MaxHp;
			((Slider)self._HpBar.GameObject.GetComponent<SuperSlider>()).value = num;
			self._HpText.SetText($"{(int)(num * 100f)}%");
			self.Update();
		}

		private static void OnGotoClick(this UIBattleBuildBar self)
		{
			UIObject.FindUIObjectOfType<UIAncientWarMainPanel>()?.SetAttackTo(self.ConfigId);
		}

		public static void UpdateButton(this UIBattleBuildBar self)
		{
			int configId = self.ConfigId;
			AncientWarComponent component = ((Entity)((Entity)(object)self).GetSceneByLayer(SceneLayer.War)).GetComponent<AncientWarComponent>();
			AncientWarMonsterConfig ancientWarMonsterConfig = ConfigSingleton<AncientWarMonsterConfigCategory>.Instance.Get(configId);
			self._GotoBtn.SetActive(component.Stage >= ancientWarMonsterConfig.Stage);
		}

		public static void Update(this UIBattleBuildBar self)
		{
			self.UpdateButton();
			int configId = self.ConfigId;
			AncientWarComponent component = ((Entity)((Entity)(object)self).GetSceneByLayer(SceneLayer.War)).GetComponent<AncientWarComponent>();
			int playerNum = component.GetPlayerNum(configId, 1);
			if (playerNum > 0)
			{
				List<AncientWarUnit> playerUnits = component.GetPlayerUnits(configId, 1);
				for (int i = 0; i < self.AttackUnits.Count; i++)
				{
					UIKingWarHeadBar uIKingWarHeadBar = self.AttackUnits[i];
					AncientWarUnit ancientWarUnit = ((playerUnits.Count > i) ? playerUnits[i] : null);
					uIKingWarHeadBar.UIObject.SetActive(ancientWarUnit != null);
					if (ancientWarUnit != null)
					{
						uIKingWarHeadBar.SetData(ancientWarUnit);
					}
				}
				self._AttackAddImage.SetActive(playerNum > self.AttackUnits.Count);
				self._AttackNumText.SetText($"{playerNum}");
				self._AttackContent.SetActive(active: true);
			}
			else
			{
				self._AttackContent.SetActive(active: false);
			}
			int playerNum2 = component.GetPlayerNum(configId, 2);
			if (playerNum2 > 0)
			{
				List<AncientWarUnit> playerUnits2 = component.GetPlayerUnits(configId, 2);
				for (int j = 0; j < self.DefendUnits.Count; j++)
				{
					UIKingWarHeadBar uIKingWarHeadBar2 = self.DefendUnits[j];
					AncientWarUnit ancientWarUnit2 = ((playerUnits2.Count > j) ? playerUnits2[j] : null);
					uIKingWarHeadBar2.UIObject.SetActive(ancientWarUnit2 != null);
					if (ancientWarUnit2 != null)
					{
						uIKingWarHeadBar2.SetData(ancientWarUnit2);
					}
				}
				self._DefendAddImage.SetActive(playerNum2 > self.DefendUnits.Count);
				self._DefendContent.SetActive(active: true);
				self._DefendNumText.SetText($"{playerNum2}");
			}
			else
			{
				self._DefendContent.SetActive(active: false);
			}
		}
	}
