			{
				LocalData_Confirm localData = ((Entity)(object)self).LocalPlayer().GetLocalData<LocalData_Confirm>();
				localData.Confirms[self.Options.ConfirmKey] = self.Options.NoConfirmTillTime;
				((Entity)(object)self).LocalPlayer().SetLocalData(localData);
			}
			self.Options.OkAction?.Invoke();
			self.Options = default(ConfirmPanelOptions);
