		public static void UpdateDupInfo(this UIBattleDJHeroDupTop self, Scene battleScene)
		{
			Dup dup = ((Entity)battleScene).GetComponent<DupComponent>().Dup;
			DJHeroDupSceneComponent component = ((Entity)battleScene).GetComponent<DJHeroDupSceneComponent>();
			bool isHangUp = component.IsHangUp;
			int nextLevel = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<DJHeroModule>().GetNextLevel();
			self._ChallengeButtonRoot.SetActive(isHangUp);
			self._RollOverBtn.SetActive(active: false);
			if (isHangUp)
			{
				self.StartGuideTime();
			}
			else
			{
				self.StopGuideTime();
				if (ConfigSingleton<DJHeroLevelConfigCategory>.Instance.Contain(nextLevel))
				{
					DJHeroLevelConfig dJHeroLevelConfig = ConfigSingleton<DJHeroLevelConfigCategory>.Instance.Get(nextLevel);
					self._RollOverBtn.SetActive(((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<RoleInfoModule>().Power >= dJHeroLevelConfig.OverPower && dJHeroLevelConfig.OverPower > 0 && ((Entity)(object)self).LocalPlayer().IsFuncOpen(49));
					if (self._RollOverBtn.IsActive())
					{
						int dJLevelRollOverLimit = ConfigSingleton<DJHeroGlobalConfigCategory>.Instance.GetOne().DJLevelRollOverLimit;
						int id = nextLevel + dJLevelRollOverLimit - 1;
						bool flag = false;
						RoleInfoModule component2 = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<RoleInfoModule>();
						if (ConfigSingleton<DJHeroLevelConfigCategory>.Instance.Contain(id) && ConfigSingleton<DJHeroLevelConfigCategory>.Instance.Get(id).OverPower <= component2.Power)
						{
							self._RollText.SetText(Language.Format(4, 824, dJLevelRollOverLimit));
							flag = true;
						}
						if (!flag)
						{
							for (int i = 1; i <= dJLevelRollOverLimit; i++)
							{
								if (ConfigSingleton<DJHeroLevelConfigCategory>.Instance.Contain(nextLevel - 1 + i) && ConfigSingleton<DJHeroLevelConfigCategory>.Instance.Get(nextLevel - 1 + i).OverPower > component2.Power)
								{
									self._RollText.SetText(Language.Format(4, 824, i - 1));
									return;
								}
							}
						}
					}
				}
			}
			int waveCount = component.WaveCount;
			for (int j = 0; j < 8; j++)
			{
				((Component)((Transform)self._WaveNodeBgGroup.Transform).GetChild(j)).gameObject.SetActive(j < waveCount);
				GameObject gameObject = ((Component)((Transform)self._WaveNodeActiveGroup.Transform).GetChild(j)).gameObject;
				gameObject.gameObject.SetActive(j < waveCount);
				((Behaviour)gameObject.GetComponent<SuperImage>()).enabled = j <= dup.DupState.PassWave;
			}
			self._CurLevelActive.SetActive(dup.DupState.PassWave > waveCount - 1);
			((Image)self._ProgressBar.GameObject.GetComponent<SuperImage>()).fillAmount = (float)dup.DupState.PassWave / (float)waveCount;
			int diff = self._BattleBubbleGroup.GetDiff(nextLevel);
			self._BattleBubbleGroup.UIObject.SetActive(((Entity)(object)self).LocalPlayer().IsFuncOpen(33) && diff <= ConfigSingleton<DJHeroGlobalConfigCategory>.Instance.GetOne().HangupMainShow);
			if (self._BattleBubbleGroup.UIObject.IsActive())
			{
				self._BattleBubbleGroup.SetData(nextLevel);
			}
		}

