				monsterType++;
			}
			int num = 0;
			if (unitInfo.UnitType == 1)
			{
				num = ConfigSingleton<HeroConfigCategory>.Instance.Get(unitInfo.TypeConfigId).Job;
			}
			if (num == 0)
			{
				self._Job.SetActive(active: false);
			}
			else
			{
				self._Job.SetActive(active: true);
				self._Job.SetSprite($"ui_common_job_s_{num}").Coroutine();
			}
			string str = Language.Format(1, 109, unitInfo.Level);
			self._LevelText.SetText(str);
		}

		public static void SetData(this UIBattleHudInfoBar self, Unit unit)
		{
			MonsterType monsterType = MonsterType.Goblin;
			while ((int)monsterType < 4)
			{
				self.UIObject.Find($"MonsterType{(int)monsterType}").SetActive(monsterType == unit.MonsterType);
				monsterType++;
			}
			int job = unit.GetJob();
			if (job == 0)
			{
				self._Job.SetActive(active: false);
			}
			else
			{
				self._Job.SetActive(active: true);
				self._Job.SetSprite($"ui_common_job_s_{job}").Coroutine();
			}
			string str = Language.Format(1, 109, unit.GetLevel());
			self._LevelText.SetText(str);
		}
	}
