		[UIMethod]
		private static void OnDestroy(this UIBattleInfoPanel self)
		{
			self.Dup = null;
			self.UnitDamageItems.Clear();
			self.UnitStateItems.Clear();
		}

		[UIMethod]
		private static void OnShow(this UIBattleInfoPanel self, Dup dup)
		{
			self.InitPanel(dup, isSettlePanel: true);
		}

		[UIMethod]
		private static void OnShow(this UIBattleInfoPanel self)
		{
			Scene currentScene = ((Entity)(object)self).GetCurrentScene();
			Dup dup = ((currentScene == null) ? null : ((Entity)currentScene).GetComponent<DupComponent>()?.Dup);
			if (dup != null)
			{
				self.InitPanel(dup);
			}
		}

		private static void InitPanel(this UIBattleInfoPanel self, Dup dup, bool isSettlePanel = false)
		{
			self.Dup = dup;
			self.IsSettlePanel = isSettlePanel;
			self._StateInfoTab.SetActive(!isSettlePanel);
			self.InitView(isSettlePanel);
			if (self.CurrentTab == 0)
			{
				self.OnTabClick(2);
			}
			self._Tab.SetActive(!isSettlePanel);
			self._DamageCampInfo.SetActive(isSettlePanel);
			if (!isSettlePanel)
			{
				return;
			}
			for (int i = 1; i <= 2; i++)
			{
				CampInfo campInfo = self.GetCampInfo(i);
				if (campInfo != null)
				{
					((Entity)self._DamageCampInfo.Find($"Head{i}")).GetComponent<UICommonHead>().SetData(campInfo, isEasyLook: true);
					self._DamageCampInfo.Find($"Name{i}").SetText(campInfo.GetName());
				}
			}
			self._Content.SetHeight(1075f);
		}

		private static CampInfo GetCampInfo(this UIBattleInfoPanel self, int camp)
		{
			Player player = ((Entity)(object)self).LocalPlayer();
			int playerCampId = self.Dup.GetPlayerCampId(((Entity)player).Id);
			if (playerCampId == 0)
			{
				return self.Dup.GetCampInfo(camp);
			}
			return self.Dup.GetCampInfo((playerCampId == camp) ? 1 : 2);
		}

		private static void InitView(this UIBattleInfoPanel self, bool onlyDamage)
		{
			self.UnitDamageItems.Clear();
			self.UnitStateItems.Clear();
			for (int i = 1; i <= 2; i++)
			{
				UIObject self2 = self._DamageContent.Find($"CampDamage{i}");
				UIObject self3 = self._StateContent.Find($"CampState{i}");
				int showCamp = ((Entity)(object)self).LocalPlayer().GetShowCampId(self.Dup, i);
				if (self.Dup.GetCampInfo(showCamp) == null)
				{
					self2.SetActive(active: false);
					self3.SetActive(active: false);
					continue;
				}
				List<UnitInfo> list = new List<UnitInfo>();
				foreach (UnitInfo unitInfo in self.Dup.UnitInfos)
				{
					if (unitInfo.CampId == showCamp)
					{
						UnitType unitType = (UnitType)unitInfo.UnitType;
						if (unitType == UnitType.Hero || unitType == UnitType.Monster)
						{
							list.Add(unitInfo);
						}
					}
				}
				list.Sort(delegate(UnitInfo a, UnitInfo b)
				{
					if (a.IsRole())
					{
						return -1;
					}
					return b.IsRole() ? 1 : (a.PosId - b.PosId);
				});
				bool isPlayerCamp = self.Dup.GetCampPlayerId(showCamp) > 0;
				self2.SetActive(list.Count > 0);
				self2.Find("UIBattleInfoDamageItem").CloneAll(list, delegate(int num, UnitInfo info, UIObject uiObject)
				{
					bool isMvp = false;
					if (isPlayerCamp && self.IsSettlePanel)
					{
						isMvp = (self.Dup.GetCampMVPInfo(showCamp)?.Id ?? 0) == info.Id;
					}
					UIBattleInfoDamageItem component = ((Entity)uiObject).GetComponent<UIBattleInfoDamageItem>();
					component.SetUnitInfo(info, isMvp);
					self.UnitDamageItems.Add(component);
				}).Coroutine();
				self3.SetActive(list.Count > 0);
				self3.Find("UIBattleInfoStateItem").CloneAll(list, delegate(int num, UnitInfo info, UIObject uiObject)
				{
					UIBattleInfoStateItem component = ((Entity)uiObject).GetComponent<UIBattleInfoStateItem>();
					component.SetUnitInfo(info);
					self.UnitStateItems.Add(info.Id, component);
				}).Coroutine();
			}
			self.UpdateDamageView();
			if (!onlyDamage)
			{
				self.UpdateStateView();
			}
		}

		public static void UpdateDamageView(this UIBattleInfoPanel self)
		{
			if (self.Dup == null)
			{
				return;
			}
			foreach (UIBattleInfoDamageItem unitDamageItem in self.UnitDamageItems)
			{
				unitDamageItem.SetData(self.Dup.GetCampData(unitDamageItem.CampId), self.Dup.GetUnitData(unitDamageItem.UnitId));
			}
			foreach (UIBattleInfoStateItem value in self.UnitStateItems.Values)
			{
				value.UpdateData(self.Dup.GetUnitData(value.UnitId));
			}
		}

		public static void UpdateStateView(this UIBattleInfoPanel self)
		{
			if (self.Dup == null)
			{
				return;
			}
			Scene val = SceneHelper.DomainScene((Entity)(object)self.Dup);
			if (val == null)
			{
				return;
			}
			UnitComponent component = ((Entity)val).GetComponent<UnitComponent>();
			if (component == null)
			{
				return;
			}
			foreach (UIBattleInfoStateItem value in self.UnitStateItems.Values)
			{
				Unit child = ((Entity)component).GetChild<Unit>(value.UnitId);
				value.SetData(child);
			}
		}

		public static void AddBuff(this UIBattleInfoPanel self, Buff buff)
		{
			if (self.UnitStateItems.TryGetValue(((Entity)buff.Owner).Id, out var value))
			{
				value.AddBuff(buff);
			}
		}

		public static void RemoveBuff(this UIBattleInfoPanel self, Buff buff)
		{
			if (self.UnitStateItems.TryGetValue(((Entity)buff.Owner).Id, out var value))
			{
				value.RemoveBuff(buff);
			}
		}

		private static void OnTabClick(this UIBattleInfoPanel self, int tab)
		{
			if (self.CurrentTab != tab)
			{
				self._StateInfoPanel.SetActive(tab == 1);
				self._StateInfoSelect.SetActive(tab == 1);
				self._DamageInfoPanel.SetActive(tab == 2);
				self._DamageInfoSelect.SetActive(tab == 2);
			}
		}
	}
