	{
		private class __AwakeSystem : AwakeSystem<UIBattleInfoStateBuffItem>
		{
			protected override void Awake(UIBattleInfoStateBuffItem self)
			{
				UIObject uIObject = self.UIObject;
				_ = self.UIObject.Transform;
				self._IconBg = uIObject.Find("_IconBg");
				self._Icon = uIObject.Find("_Icon");
				self._LeftTime = uIObject.Find("_LeftTime");
				UIEventDispatcherComponent.Instance.Register(self);
			}
		}

		private class __DestroySystem : DestroySystem<UIBattleInfoStateBuffItem>
		{
			protected override void Destroy(UIBattleInfoStateBuffItem self)
			{
				UIEventDispatcherComponent.Instance.UnRegister(self);
				self._IconBg = null;
				self._Icon = null;
				self._LeftTime = null;
				((DisposeObject)self.UIObject).Dispose();
			}
		}

		[UIMethod]
		private static void OnDisable(this UIBattleInfoStateBuffItem self)
		{
			self.RemoveTimer(ref self.CountDownTimer);
		}

		private static void CountDown(this UIBattleInfoStateBuffItem self)
		{
			long nowTime = BattleSceneHelper.GetNowTime(((Entity)(object)self).GetCurrentScene());
			long num = math.max(0L, self.DisappearTime - nowTime);
			string text = ((self.DisappearTime == -1) ? "永久" : ((float)num / 1000f).ToString("0.0s"));
			if (ConfigSingleton<BuffConfigCategory>.Instance.Get(self.BuffId).IsDebuff)
			{
				text = "<color=#ff2e2e>" + text + "</color>";
			}
			self._LeftTime.SetText(text);
		}

		public static void SetData(this UIBattleInfoStateBuffItem self, Buff buff)
		{
			BuffConfig config = buff.Config;
			self._Icon.SetRawTexture("uitex_buff_" + config.Icon).Coroutine();
			if (config.IsDebuff)
			{
				self._IconBg.SetRawTexture("ui_fight_bar_12_GV").Coroutine();
			}
			else
			{
				self._IconBg.SetRawTexture("ui_fight_bar_13_GV").Coroutine();
			}
			self.BuffId = buff.ConfigId;
			self.Layer = buff.Layer;
			self.DisappearTime = buff.DisappearTime;
			self.RemoveTimer(ref self.CountDownTimer);
			self.CountDownTimer = self.NewTimer(100L, self.CountDown, repeat: true);
		}
	}
