				_ = self.UIObject.Transform;
				UIHeroHead uIHeroHead = ((Entity)uIObject.Find("_UIHeroHead")).AddComponent<UIHeroHead>(false);
				UIBattleInfoStateBuffItem uIBattleInfoStateBuffItem = ((Entity)uIObject.Find("_Content/_UIBattleInfoStateBuffItem")).AddComponent<UIBattleInfoStateBuffItem>(false);
				self._UIHeroHead = uIHeroHead;
				self._Content = uIObject.Find("_Content");
				self._UIBattleInfoStateBuffItem = uIBattleInfoStateBuffItem;
				UIEventDispatcherComponent.Instance.Register(self);
			}
		}

		private class __DestroySystem : DestroySystem<UIBattleInfoStateItem>
		{
			protected override void Destroy(UIBattleInfoStateItem self)
			{
				UIEventDispatcherComponent.Instance.UnRegister(self);
				self._UIHeroHead = null;
				self._Content = null;
				self._UIBattleInfoStateBuffItem = null;
				((DisposeObject)self.UIObject).Dispose();
			}
		}

		public static void SetUnitInfo(this UIBattleInfoStateItem self, UnitInfo unitInfo)
		{
			self.UnitId = unitInfo.Id;
			self._UIHeroHead.SetData(unitInfo);
		}

		public static void UpdateData(this UIBattleInfoStateItem self, DupUnitData dupUnitData)
		{
			if (dupUnitData != null && !self.IsDead && dupUnitData.CurrentHp == 0L)
			{
				self._UIHeroHead.UIObject.SetGray();
				self.IsDead = true;
			}
		}

		private static void RefreshAllBuffs(this UIBattleInfoStateItem self)
		{
			int count = math.min(8, self.Buffs.Count);
			self._UIBattleInfoStateBuffItem.UIObject.CloneAll(count, delegate(int i, UIObject uiObject)
			{
				((Entity)uiObject).GetComponent<UIBattleInfoStateBuffItem>().SetData(self.Buffs[i]);
			}).Coroutine();
		}

		public static void RemoveBuff(this UIBattleInfoStateItem self, Buff buff)
		{
			for (int i = 0; i < self.Buffs.Count; i++)
			{
				if (self.Buffs[i].ConfigId == buff.ConfigId)
				{
					self.Buffs.RemoveAt(i);
					break;
				}
			}
			self.RefreshAllBuffs();
		}

		public static void AddBuff(this UIBattleInfoStateItem self, Buff newBuff)
		{
			for (int i = 0; i < self.Buffs.Count; i++)
			{
				if (self.Buffs[i].ConfigId == newBuff.ConfigId)
				{
					UIObject cloneObject = self._UIBattleInfoStateBuffItem.UIObject.GetCloneObject(i);
					if (cloneObject != null)
					{
						((Entity)cloneObject).GetComponent<UIBattleInfoStateBuffItem>().SetData(newBuff);
					}
					return;
				}
			}
			self.Buffs.Add(newBuff);
			self.RefreshAllBuffs();
		}

		public static void SetData(this UIBattleInfoStateItem self, Unit unit)
		{
			self.Buffs.Clear();
			if (unit != null)
			{
				((Entity)unit).GetComponent<BuffComponent>().Foreach(self.Buffs.Add);
				self.RefreshAllBuffs();
			}
		}
	}
