			{
				((Entity)self).RemoveComponent(typeof(BattlePanelKingWarComponent));
			}
			if (((Entity)self).GetComponent<BattlePanelAncientWarComponent>() != null)
			{
				((Entity)self).RemoveComponent(typeof(BattlePanelAncientWarComponent));
			}
			Type[] array = ((Entity)self).Components.Keys.ToArray();
			foreach (Type type in array)
			{
