			{
				((Entity)self).AddComponent(typeof(BattlePanelKingWarComponent), false);
				return;
			}
			if (((Entity)self.Scene).GetComponent<SceneInfoComponent>().SceneId == 1001)
			{
				((Entity)self).AddComponent(typeof(BattlePanelAncientWarComponent), false);
				return;
			}
			foreach (Type type in Singleton<EventSystem>.Instance.GetTypes(typeof(BattlePanelComponentAttribute)))
			{
				foreach (BattlePanelComponentAttribute customAttribute in ((MemberInfo)type).GetCustomAttributes<BattlePanelComponentAttribute>())
				{
					if (customAttribute.DupType == dupType)
					{
						((Entity)self).AddComponent(type, false);
						break;
					}
				}
			}
		}

