		private static void OnDJTapBoardClick(this UIBattlePanel self)
		{
			if (self.Scene != null)
			{
				Unit localMainUnit = BattleSceneHelper.GetLocalMainUnit(self.Scene);
				if (localMainUnit != null)
				{
					((Entity)localMainUnit).GetComponent<TapFightComponent>()?.TapAttack();
