		private static void OnQuitButtonClick(this UIBattlePanel self)
		{
			Dup dup = ((Entity)self.Scene).GetComponent<DupComponent>()?.Dup;
			if (dup == null || ((Entity)self.Scene).GetComponent<BattleComponent>().IsTenTimesSpeedPlay)
			{
				return;
			}
			if (dup.IsReplay())
			{
				UIManager.Instance.Show<UIBattleConfirmPanel, ConfirmPanelOptions>(new ConfirmPanelOptions
				{
					Message = Language.Get(1, 42),
					OkAction = delegate
					{
						((Entity)(object)self).ChangeSceneToLayer(SceneLayer.Main).Coroutine();
					}
				}).Coroutine();
				return;
			}
			DupConfig config = dup.Config;
			UIManager.Instance.Show<UIBattleConfirmPanel, ConfirmPanelOptions>(new ConfirmPanelOptions
			{
				Message = config.QuitTips,
				OkAction = delegate
				{
					((Entity)(object)self).ChangeSceneToLayer(SceneLayer.Main).Coroutine();
				}
			}).Coroutine();
		}

		private static void OnAutoSkillButtonClick(this UIBattlePanel self)
		{
			if (((Entity)self.Scene).GetComponent<BattleComponent>().IsTenTimesSpeedPlay)
			{
				return;
			}
			Player player = ((Entity)(object)self).LocalPlayer();
			bool flag = !player.GetLocalBool("DupAutoSuperSkill");
			player.SetLocalBool("DupAutoSuperSkill", flag);
			self._AutoFightActive.SetActive(flag);
			if (!flag)
			{
				return;
			}
			foreach (UIHeroCardBattleItem value in self.HeroCardItems.Values)
			{
				value.OnClick();
			}
		}

		private static void UpdateAutoSuperSkillState(this UIBattlePanel self)
		{
			Scene scene = self.Scene;
			if (((scene != null) ? ((Entity)scene).GetComponent<DupComponent>() : null) != null)
			{
				bool localBool = ((Entity)(object)self).LocalPlayer().GetLocalBool("DupAutoSuperSkill");
				self._AutoFightActive.SetActive(localBool);
			}
		}

		private static void OnFastPlayButtonClick(this UIBattlePanel self)
		{
			Scene scene = self.Scene;
			DupComponent dupComponent = ((scene != null) ? ((Entity)scene).GetComponent<DupComponent>() : null);
			if (dupComponent != null && !((Entity)self.Scene).GetComponent<BattleComponent>().IsTenTimesSpeedPlay)
			{
				SceneFrameUpdateComponent component = ((Entity)self.Scene).GetComponent<SceneFrameUpdateComponent>();
				bool flag = component.TimeScale > 1;
				if (dupComponent.Dup.Config.Can2Times)
				{
					component.TimeScale = (flag ? 1 : 2);
					((Entity)(object)self).LocalPlayer().SetLocalBool("Dup2TimesFight", !flag);
					self.UpdateFastPlayState();
				}
			}
		}

		private static void UpdateFastPlayState(this UIBattlePanel self)
		{
			SceneFrameUpdateComponent component = ((Entity)self.Scene).GetComponent<SceneFrameUpdateComponent>();
			bool active = component != null && component.TimeScale > 1;
			self._FastPlayActive.SetActive(active);
		}

		private static void OnLimitTimeTick(this UIBattlePanel self)
		{
			Scene scene = self.Scene;
			LimitTimeComponent limitTimeComponent = ((scene != null) ? ((Entity)scene).GetComponent<LimitTimeComponent>() : null);
			if (limitTimeComponent == null)
			{
				self.RemoveTimer(ref self.LimitTimeUpdateTimer);
				return;
			}
			long nowTime = BattleSceneHelper.GetNowTime(self.Scene);
			long num = limitTimeComponent.LimitTillTime - nowTime;
			Dup dup = ((Entity)self.Scene).GetComponent<DupComponent>()?.Dup;
			if (dup != null && dup.IsFinish)
			{
				num = limitTimeComponent.LimitTillTime - dup.DupState.FinishTime;
			}
			if (num >= 0)
			{
				self._TimeSlider.GameObject.GetComponent<Slider>().value = (float)num / (float)limitTimeComponent.LimitTime;
				self._TimeText.SetText(TextHelper.TimeFormatHourMinSec(num));
			}
		}

		public static void RefreshLimitTime(this UIBattlePanel self)
		{
			self.RemoveTimer(ref self.LimitTimeUpdateTimer);
			LimitTimeComponent component = ((Entity)self.Scene).GetComponent<LimitTimeComponent>();
			if (component.IsLimitTime())
			{
				self.LimitTimeUpdateTimer = self.NewTimer(0L, self.OnLimitTimeTick, repeat: true);
			}
			self._TimePanel.SetActive(component.IsLimitTime());
		}

		public static void PassBattleButtonClick(this UIBattlePanel self)
		{
			if (!((Entity)(object)self).LocalPlayer().IsFuncOpen(34))
			{
				FuncConfig funcConfig = ConfigSingleton<FuncConfigCategory>.Instance.Get(34);
				if (funcConfig != null && funcConfig.OpenConds.Length == 2)
				{
					StringBuilder stringBuilder = new StringBuilder();
					stringBuilder.Append(((Entity)(object)self).LocalPlayer().GetCondText(funcConfig.OpenConds[0]));
					stringBuilder.AppendFormat((funcConfig.Type == 1) ? "且" : "或", Array.Empty<object>());
					stringBuilder.Append("完成首充后解锁");
					UIGameMsgHelper.FloatMsg(stringBuilder.ToString());
				}
			}
			else
			{
				if (self.Scene == null)
				{
					return;
				}
				Dup dup = ((Entity)self.Scene).GetComponent<DupComponent>()?.Dup;
				if (((Entity)self.Scene).GetComponent<BattleComponent>().IsTenTimesSpeedPlay)
				{
					return;
				}
				if (self.CountDownCanPassSec > 0)
				{
					UIGameMsgHelper.FloatMsg(Language.Format(1, 26, self.CountDownCanPassSec));
					return;
				}
				DupConfig dupConfig = dup?.Config;
				if (dupConfig != null && dupConfig.CanPass)
				{
					self.PassDup();
				}
			}
		}

		private static void PassDup(this UIBattlePanel self)
		{
			((Entity)self.Scene).GetComponent<BattleComponent>().IsTenTimesSpeedPlay = true;
			self._QuitButton.SetActive(active: false);
			BattleSceneHelper.SetTimeScale(self.Scene, 10);
			foreach (Unit fightUnit in ((Entity)self.Scene).GetComponent<UnitComponent>().FightUnits)
			{
				((Entity)fightUnit).GetComponent<FightComponent>().AutoCastSuperSkill = true;
			}
		}

