		{
			//IL_0021: Unknown result type (might be due to invalid IL or missing references)
			//IL_0022: Unknown result type (might be due to invalid IL or missing references)
			int layer = 0;
			switch (options.PlayMode)
			{
			case UIBattleTextOptions.Mode.Bang:
				layer = 2;
				break;
			case UIBattleTextOptions.Mode.FloatUp:
			case UIBattleTextOptions.Mode.FallDown:
			case UIBattleTextOptions.Mode.PingPong:
				layer = 1;
				break;
			}
			self.CreateBattleText(options, layer).Play(position, source, options);
		}

