		private static void OnClickSkill(this UIBattleSkillPart self)
		{
			Unit localMainUnit = BattleSceneHelper.GetLocalMainUnit(((Entity)(object)self).GetCurrentScene());
			if (localMainUnit != null)
			{
				((Entity)localMainUnit).GetComponent<TapFightComponent>()?.TryCastSuperSkill();
			}
		}

		private static void UpdateAutoTapButton(this UIBattleSkillPart self)
		{
			Player player = ((Entity)(object)self).LocalPlayer();
			if (player != null)
			{
				self._AutoTapLock.SetActive(!player.IsFuncOpen(20));
			}
		}

		private static void OnAutoTapButtonClick(this UIBattleSkillPart self)
		{
			Player player = ((Entity)(object)self).LocalPlayer();
			if (player != null && player.IsFuncOpen(20, isNotice: true))
			{
				UIManager.Instance.Show<UIDJHeroUseItemPanel>().Coroutine();
			}
		}

