	public static class BattleGroundRedPoint
	{
		public static int GetCount(Player player)
		{
			if (player == null)
			{
				return 0;
			}
			int num = GetChallengeCount(player);
			if (num > 0)
			{
				return num;
			}
			if (num == 0)
			{
				BattleGroundModule activityModule = ActivityHelper.GetActivityModule<BattleGroundModule>(player, 201);
				if (activityModule != null)
				{
					num = activityModule.GetBoxScoreRedPoint();
				}
				if (num > 0)
				{
					return num;
				}
			}
			return GetFormationCount(player);
		}

		public static int GetChallengeCount(Player player)
		{
			if (player == null)
			{
				return 0;
			}
			BattleGroundModule activityModule = ActivityHelper.GetActivityModule<BattleGroundModule>(player, 201);
			if (activityModule == null)
			{
				return 0;
			}
			if (!((Entity)player).GetComponent<BattleGroundDupModule>().CheckActivityState(out var _, out var _))
			{
				return 0;
			}
			return activityModule.GetChallengeCount(player).Item1;
		}

		public static int GetFormationCount(Player player)
		{
			if (player == null)
			{
				return 0;
			}
			if (ActivityHelper.GetActivityModule<BattleGroundModule>(player, 201) == null)
			{
				return 0;
			}
