	[RedPointHandler(RedPointType.BattleGroundEnter)]
	public class BattleGroundEnterRedPointHandler : ARedPointHandler
	{
		public override int GetCount(Scene scene, params int[] parameters)
		{
			int num = 0;
			if (scene == null)
			{
				return num;
			}
			num += BattleGroundRedPoint.GetCount(((Entity)(object)scene).LocalPlayer());
			if (num > 0)
			{
				return num;
			}
			ActivityData activityByType = ((Entity)((Entity)(object)scene).LocalPlayer()).GetComponent<PlayerActivityComponent>().GetActivityByType(ActivityType.ImmortalOfficial, ActivityState.Open);
			if (activityByType != null)
			{
				num += RedPointHelper.GetCount(scene, RedPointType.Activity, activityByType.ActivityId);
			}
			if (num > 0)
			{
				return num;
			}
			UIRedPointComponent component = ((Entity)scene).GetComponent<UIRedPointComponent>();
			if (component.Handlers.TryGetValue(RedPointType.Ladder, out var value) && value.GetCount(scene) > 0)
			{
				return 1;
			}
			if (component.Handlers.TryGetValue(RedPointType.LadderTop, out var value2) && value2.GetCount(scene) > 0)
			{
				return 1;
			}
			if (component.Handlers.TryGetValue(RedPointType.HeavenFight_Enter, out var value3) && value3.GetCount(scene) > 0)
			{
				return 1;
			}
			return num;
		}
	}
