		{
			BattleGroundModule activityModuleByType = ((Entity)(object)self).LocalPlayer().GetActivityModuleByType<BattleGroundModule>(ActivityType.BattleGround);
			if (activityModuleByType != null)
			{
				int refreshCount = activityModuleByType.GetRefreshCount(((Entity)(object)self).LocalPlayer());
				ItemModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>();
				PriceConfig priceConfig = ConfigSingleton<PriceConfigCategory>.Instance.Get(1, refreshCount + 1);
				if (priceConfig.Price != null)
				{
					self._RefreshButtonText.SetActive(active: false);
					self._NeedPrice.SetActive(active: true);
					self._PriceItemIcon.SetRawTexture($"uitex_icon_item_{priceConfig.Price.Id}").Coroutine();
					self._PriceNum.SetText(priceConfig.Price.Nums.ToString());
					long itemNumsByItemId = component.GetItemNumsByItemId(priceConfig.Price.Id);
					self._RefreshButton.SetGray(itemNumsByItemId < priceConfig.Price.Nums);
				}
				else
				{
					self._RefreshButton.SetGray(isGray: false);
					self._RefreshButtonText.SetActive(active: true);
					self._NeedPrice.SetActive(active: false);
