		[UIMethod]
		public static void OnShow(this UIBattleGroundDupFinishContent self, UIShowArgs args)
		{
			UIBattleGroundDupFinishContentArgs uIBattleGroundDupFinishContentArgs = args as UIBattleGroundDupFinishContentArgs;
			DupResponseResult dupResult = uIBattleGroundDupFinishContentArgs.DupResult;
			self.ParentPanel = uIBattleGroundDupFinishContentArgs.Parent;
			BattleGroundDupResult battleGroundDupResult = dupResult.Dup.DupResult.BattleGroundDupResult;
			self._OldRank.SetText((battleGroundDupResult.OldRank == 0) ? Language.Get(2, 204) : battleGroundDupResult.OldRank.ToString());
			Player player = ((Entity)(object)self).LocalPlayer();
			self._LeftHead.SetData(player, showPracticeLevel: false);
			self._LeftHead.SetDisableClick(disable: true);
			self._RightHead.SetData(battleGroundDupResult.OpponentHead, battleGroundDupResult.OpponentHeadFrame, battleGroundDupResult.OpponentId);
			self._RightHead.SetDisableClick(disable: true);
			self._LeftPlayerName.SetText(player.GetName());
			self._RightPlayerName.SetText(battleGroundDupResult.OpponentName);
			if (dupResult.Dup.IsAttackerWin())
			{
				self._RankFlag.SetSprite("ui_hero1_sign_01").Coroutine();
				self._NewRank.SetText("<color=#3dd853>" + battleGroundDupResult.NewRank + "</color>");
				self._LeftPlayerScore.SetText($"<color=#ae9566>{battleGroundDupResult.PlayerOldScore}</color><color=#3dd853>+{Math.Abs(battleGroundDupResult.PlayerScoreInc)}</color>");
			}
			else
			{
				self._RankFlag.SetSprite("ui_jjc2_sign_15").Coroutine();
				self._NewRank.SetText("<color=#e34745>" + battleGroundDupResult.NewRank + "</color>");
				self._LeftPlayerScore.SetText($"<color=#ae9566>{battleGroundDupResult.PlayerOldScore}</color><color=#e34745>-{Math.Abs(battleGroundDupResult.PlayerScoreInc)}</color>");
			}
			if (!dupResult.Dup.IsAttackerWin())
			{
				self._RightPlayerScore.SetText($"<color=#ae9566>{battleGroundDupResult.OpponentOldScore}</color><color=#3dd853>+{Math.Abs(battleGroundDupResult.OpponentScoreInc)}</color>");
			}
			else
			{
				self._RightPlayerScore.SetText($"<color=#ae9566>{battleGroundDupResult.OpponentOldScore}</color><color=#e34745>-{Math.Abs(battleGroundDupResult.OpponentScoreInc)}</color>");
			}
			self._UICommonHorizontalReward.SetData(dupResult.Dup.DupResult.Rewards, isPlayAnim: true);
		}

		[UIMethod]
		public static void OnDestroy(this UIBattleGroundDupFinishContent self)
		{
		}

