		}

		[UIMethod]
		public static void OnShow(this UIBattleGroundPanel self, int funcId)
		{
			self.InitPanel(funcId);
		}

		private static void InitPanel(this UIBattleGroundPanel self, int funcId)
		{
			self.UITabInfos = self.GetUITabInfos();
			self.UITabInfos.Sort(delegate(UITabInfo a, UITabInfo b)
			{
				FuncConfig funcConfig = ConfigSingleton<FuncConfigCategory>.Instance.Get(a.FuncId);
				FuncConfig funcConfig2 = ConfigSingleton<FuncConfigCategory>.Instance.Get(b.FuncId);
				return funcConfig.Sort.CompareTo(funcConfig2.Sort);
			});
			self._UICommonPanelBottom.SetTabs(self.UITabInfos.ToArray(), funcId);
			self._UICommonPanelBottom.SetClickCallback(self.OnTabClick);
			UIGuideHelper.TryGuide(SceneHelper.DomainScene((Entity)(object)self), "UIBattleGroundPanel");
		}

		private static void OnTabClick(this UIBattleGroundPanel self, int index, UIObject uiObject)
		{
			if (index < self.UITabInfos.Count)
			{
				self._UICommonPanelTop.SetData(self.UITabInfos[index].FuncId);
			}
		}
	}
