		public static void SetData(this UIBattleGroundRankItem self, RankInfo rankInfo, bool crossServer = false)
		{
			self.ShowRankImageAndText(rankInfo.RankNo);
			int headId = rankInfo.DressInfo.GetHeadId((byte)rankInfo.Sex);
			int headFrameId = rankInfo.DressInfo.GetHeadFrameId((byte)rankInfo.Sex);
			self._UICommonHead.SetData(headId, headFrameId, rankInfo.Id, isEasyLook: false);
			self._Name.SetText(rankInfo.Name);
			self._PowerText.SetText(TextHelper.FormatPower(rankInfo.Power));
			self._Score.SetText(rankInfo.Value.ToString());
			Player player = ((Entity)(object)self).LocalPlayer();
			self._SelfIcon.SetActive(((Entity)player).Id == rankInfo.Id);
		}

		private static void ShowRankImageAndText(this UIBattleGroundRankItem self, int randNo)
		{
			switch (randNo)
			{
			case 1:
				self._RankImage.SetActive(active: true);
				self._RankText.SetActive(active: false);
				self._RankImage.SetSprite("ui_jjc2_sign_01", nativeSize: true).Coroutine();
				self._RankImageBg.SetSprite("ui_jjc2_frame_09", nativeSize: true).Coroutine();
				break;
			case 2:
				self._RankImage.SetActive(active: true);
				self._RankText.SetActive(active: false);
				self._RankImage.SetSprite("ui_jjc2_sign_02", nativeSize: true).Coroutine();
				self._RankImageBg.SetSprite("ui_jjc2_frame_08", nativeSize: true).Coroutine();
				break;
			case 3:
				self._RankImage.SetActive(active: true);
				self._RankText.SetActive(active: false);
				self._RankImage.SetSprite("ui_jjc2_sign_03", nativeSize: true).Coroutine();
				self._RankImageBg.SetSprite("ui_jjc2_frame_07", nativeSize: true).Coroutine();
				break;
			default:
				self._RankImage.SetActive(active: false);
				self._RankText.SetActive(active: true);
				self._RankText.SetText(randNo.ToString());
				self._RankImageBg.SetSprite("ui_jjc2_frame_06", nativeSize: true).Coroutine();
				break;
			}
		}
	}
