		public static void SetData(this UIBattleGroundRecordItem self, BattleGroundRecordInfo info, int index, bool crossServer = false)
		{
			//IL_0155: Unknown result type (might be due to invalid IL or missing references)
			self.RecordGUID = info.GUID;
			self._BattleSign.SetSprite(info.IsAttacker ? "ui_jjc2_sign_10" : "ui_jjc2_sign_11").Coroutine();
			self._BattleTime.SetText(UIHelper.GetTimeString(info.UpdateTime, TimeHelper.Now()));
			int headId = info.OpponentInfo.DressInfo.GetHeadId((byte)info.OpponentInfo.Sex);
			int headFrameId = info.OpponentInfo.DressInfo.GetHeadFrameId((byte)info.OpponentInfo.Sex);
			self._UICommonHead.SetData(headId, headFrameId, info.OpponentInfo.PlayerId);
			long power = info.OpponentInfo.Power;
			bool num = ((Entity)(object)self).LocalPlayer().GetPower() < power;
			self._Power.SetText(TextHelper.FormatPower(power));
			if (!num)
			{
				self._Power.SetText(Language.Format(2, 163, Language.Format(2, 158, TextHelper.FormatPower(power))));
			}
			else
			{
				self._Power.SetText(Language.Format(2, 164, Language.Format(2, 158, TextHelper.FormatPower(power))));
			}
			if (crossServer)
			{
				self._Name.SetText(TextHelper.FormatZone(new UIDStruct(info.OpponentInfo.PlayerId).Zone) + info.OpponentInfo.PlayerName);
			}
			else
			{
				self._Name.SetText(info.OpponentInfo.PlayerName);
			}
			if (info.ScoreInc > 0)
			{
				self._Score.SetText($"<color=#0db64d>+{info.ScoreInc}</color>");
			}
			else
			{
				self._Score.SetText($"<color=#ff3232>-{Math.Abs(info.ScoreInc)}</color>");
			}
			self._PlaybackButton.SetActive(active: true);
			self._BattleButton.SetActive(!info.IsAttacker && !info.Success && !info.Revenged);
		}

