		private static void SetSelfReward(this UIBattleGroundRewardPanel self, int dropItemId, int rank)
		{
			switch (rank)
			{
			case 1:
				self._RankImage.SetActive(active: true);
				self._RankText.SetActive(active: false);
				self._RankImage.SetSprite("ui_jjc2_sign_01", nativeSize: true).Coroutine();
				break;
			case 2:
				self._RankImage.SetActive(active: true);
				self._RankText.SetActive(active: false);
				self._RankImage.SetSprite("ui_jjc2_sign_02", nativeSize: true).Coroutine();
				break;
			case 3:
				self._RankImage.SetActive(active: true);
				self._RankText.SetActive(active: false);
				self._RankImage.SetSprite("ui_jjc2_sign_03", nativeSize: true).Coroutine();
				break;
			default:
				self._RankImage.SetActive(active: false);
				self._RankText.SetActive(active: true);
				self._RankText.SetText(rank.ToString());
				break;
			}
			if (!ConfigSingleton<DropShowConfigCategory>.Instance.Contain(dropItemId))
			{
				return;
			}
			DropShowConfig dropShowConfig = ConfigSingleton<DropShowConfigCategory>.Instance.Get(dropItemId);
