		private static void OnMyRankChange(this UIBattleGroundRewardPanel self, int oldValue, int newValue)
		{
			if (newValue == -1)
			{
				self._PlayerRewardItem.SetActive(active: false);
				return;
			}
			self._PlayerRewardItem.SetActive(active: true);
			ActivityHelper.GetActivityModule<BattleGroundModule>(((Entity)(object)self).LocalPlayer(), 201);
			BattleGroundRewardConfig battleGroundRewardConfig = null;
			foreach (BattleGroundRewardConfig rewardConfig in self.RewardConfigs)
			{
				if (newValue >= rewardConfig.RankLeft && newValue <= rewardConfig.RankRight)
				{
					battleGroundRewardConfig = rewardConfig;
					break;
				}
			}
			if (battleGroundRewardConfig != null)
			{
				switch (self.Tag)
				{
				case 0:
					self.SetSelfReward(battleGroundRewardConfig.DayReward, newValue);
					break;
				case 1:
					self.SetSelfReward(battleGroundRewardConfig.SeasonReward, newValue);
					break;
				case 2:
					self.SetSelfReward(battleGroundRewardConfig.WinReward, newValue);
					break;
				case 3:
					self.SetSelfReward(battleGroundRewardConfig.FailReward, newValue);
					break;
				}
			}
			else
			{
				self._RankImage.SetActive(active: false);
				self._RankText.SetActive(active: true);
				self._RankText.SetText(Language.Get(2, 159));
			}
		}

		private static void InitConfigInfo(this UIBattleGroundRewardPanel self)
		{
			self.RewardConfigs.Clear();
			BattleGroundModule activityModule = ActivityHelper.GetActivityModule<BattleGroundModule>(((Entity)(object)self).LocalPlayer(), 201);
			foreach (var (_, item) in ConfigSingleton<BattleGroundRewardConfigCategory>.Instance.GetSeason(activityModule.Season))
			{
				self.RewardConfigs.Add(item);
			}
			self.RewardConfigs.Sort((BattleGroundRewardConfig a, BattleGroundRewardConfig b) => a.RankLeft - b.RankLeft);
		}

		private static void LoadTextInfo(this UIBattleGroundRewardPanel self)
		{
			self._CommonBg.SetTitle(Language.Get(2, 173));
		}

		private static void UpdateDayLeftTimer(this UIBattleGroundRewardPanel self)
		{
			if (self.DayLeftTimer == 0L)
			{
				self.DayLeftTimer = self.NewTimer(1000L, self.AddDayLeftTimer, repeat: true);
				self.AddDayLeftTimer();
			}
		}

		private static void AddDayLeftTimer(this UIBattleGroundRewardPanel self)
		{
			BattleGroundModule activityModule = ActivityHelper.GetActivityModule<BattleGroundModule>(((Entity)(object)self).LocalPlayer(), 201);
			if (activityModule != null)
			{
				if (activityModule.IsInDailySettleTime())
				{
					self._DayLeftTime.SetText(Language.Get(2, 617));
					return;
				}
				string str = TimeSpan.FromSeconds((double)((TimeHelper.CommonEndTimeOfDay(TimeHelper.Now()) - TimeHelper.Now()) / 1000)).ToString(Language.Get(2, 507));
				self._DayLeftTime.SetText(str);
			}
		}

		private static void UpdateSeasonLeftTimer(this UIBattleGroundRewardPanel self)
		{
			if (self.SeasonLeftTimer == 0L)
			{
				self.SeasonLeftTimer = self.NewTimer(1000L, self.AddSeasonLeftText, repeat: true);
				self.AddSeasonLeftText();
			}
		}

		private static void AddSeasonLeftText(this UIBattleGroundRewardPanel self)
		{
			BattleGroundModule activityModule = ActivityHelper.GetActivityModule<BattleGroundModule>(((Entity)(object)self).LocalPlayer(), 201);
			if (activityModule != null)
			{
				long num = activityModule.GetSettleTime() - TimeHelper.Now();
				if (num <= 0)
				{
					self._SeasonLeftTime.SetText(Language.Get(2, 293));
					return;
				}
				TimeSpan timeSpan = TimeSpan.FromSeconds((double)(num / 1000));
				string str = ((num < 86400000) ? timeSpan.ToString(Language.Get(2, 515)) : timeSpan.ToString(Language.Get(2, 304)));
				self._SeasonLeftTime.SetText(str);
			}
		}

