		{
			self.Tag = index;
		}

		private static void OnCellUpdate(this UIBattleGroundRewardPanel self, UIScrollListCell cell)
		{
			int index = cell.Index;
			if (index < self.RewardConfigs.Count)
			{
				UIBattleGroundRewardItem component = ((Entity)cell.UIObject).GetComponent<UIBattleGroundRewardItem>();
				BattleGroundRewardConfig battleGroundRewardConfig = self.RewardConfigs[index];
				switch (self.Tag)
				{
				case 0:
					component.SetData(battleGroundRewardConfig.DayReward, battleGroundRewardConfig.RankLeft, battleGroundRewardConfig.RankRight);
					break;
				case 1:
					component.SetData(battleGroundRewardConfig.SeasonReward, battleGroundRewardConfig.RankLeft, battleGroundRewardConfig.RankRight);
					break;
				case 2:
					component.SetData(battleGroundRewardConfig.WinReward, battleGroundRewardConfig.RankLeft, battleGroundRewardConfig.RankRight);
