		[UIMethod]
		public static void OnAwake(this UIBattleGroundSubPanel self)
		{
			((Entity)(object)self).EnableDataBind();
			self._ShopButton.AddClickHandler(self.OnCLickShopButton);
			self._RankButton.AddClickHandler(self.OnCLickRankButton);
			self._RewardButton.AddClickHandler(self.OnCLickRewardButton);
			self._ChallengeButton.AddClickHandler(self.OnClickChallengeButton);
			self._DefenseButton.AddClickHandler(self.OnClickDefenseButton);
			self._RecordButton.AddClickHandler(self.OnClickRecordButton);
			self._ItemAddButton.AddClickHandler(self.OnClickItemAddButton);
