		public static void RefreshView(this UIBattleGroundSubPanel self)
		{
			Player player = ((Entity)(object)self).LocalPlayer();
			if (player != null)
			{
				BattleGroundModule activityModule = ActivityHelper.GetActivityModule<BattleGroundModule>(player, 201);
				if (activityModule != null)
				{
					self.StartLeftTime();
					self.RefreshView_ChallengeCount();
					self._PlayerScoreText.SetText(activityModule.Score.ToString());
					self._ScoreText.SetText(activityModule.Score.ToString());
					self._PlayerName.SetText(player.GetName());
					self.RefreshView_Rank().Coroutine();
					self.RefreshView_Score();
					self._UIBattleChallengeBoxGroup.RefreshBoxPos();
				}
			}
		}

		public static void RefreshView_Score(this UIBattleGroundSubPanel self)
		{
			self.ScoreRewardList?.Clear();
			self._UIScoreScrollList.SetData(0);
			BattleGroundScoreInfo battleGroundScoreInfo = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<BattleGroundDupModule>().GetBattleGroundScoreInfo();
			Dictionary<int, bool> scoreRewardGet = battleGroundScoreInfo.ScoreRewardGet;
			int num = 0;
			List<BattleGroundScoreRewardConfig> list = ConfigSingleton<BattleGroundScoreRewardConfigCategory>.Instance.GetAll().Values.ToList();
			self.ScoreRewardList.AddRange(list);
			for (int i = 0; i < list.Count; i++)
			{
				if (battleGroundScoreInfo.AllScore >= list[i].AllScore)
				{
					if (scoreRewardGet == null || !scoreRewardGet.ContainsKey(list[i].Id))
					{
						num = i;
						break;
					}
				}
				else if (i != 0 && battleGroundScoreInfo.AllScore >= list[i - 1].AllScore && battleGroundScoreInfo.AllScore <= list[i].AllScore)
				{
					num = i;
					break;
				}
			}
			Log.Info($"RefreshView_Score :{num}");
			self._UIScoreScrollList.SetData(self.ScoreRewardList.Count);
			self._UIScoreScrollList.MovePanelToItemIndex(num - 1);
		}

		public static void RefreshView_ChallengeCount(this UIBattleGroundSubPanel self)
		{
			Player player = ((Entity)(object)self).LocalPlayer();
			if (player == null)
			{
				return;
			}
			BattleGroundModule activityModule = ActivityHelper.GetActivityModule<BattleGroundModule>(player, 201);
			if (activityModule != null)
			{
				(int, int) challengeCount = activityModule.GetChallengeCount(player);
				int item = challengeCount.Item1;
				int item2 = challengeCount.Item2;
				item2 = activityModule.GetChallengeMaxCountForShow(player);
				if (item > 0)
				{
					self._ItemNumsText.SetText(Language.Format(2, 156, item, item2));
				}
				else
				{
					self._ItemNumsText.SetText(Language.Format(2, 157, item, item2));
				}
				self._ChallengeCountText.SetText($"{activityModule.ChallengeAllCount}/{ConfigSingleton<BattleGroundBoxRewardConfigCategory>.Instance.GetAll().Last().Value.ChanllengeCount}");
			}
		}

