		public static void OnClick(this UIBeastBagItem self)
		{
			if (self.State == BeastGridState.Open)
			{
				Beast beast = self.GetBeast();
				if (beast != null && beast.Config.Type != 0)
				{
					UIManager.Instance.Show<UIBeastDetailsPanel, Beast>(beast).Coroutine();
				}
			}
			else if (self.State == BeastGridState.Locked_Money)
			{
				int bagBuyCount = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<BeastModule>().BagBuyCount;
				ET.ConfigBeans.Item item = ConfigSingleton<BeastGlobalConfigCategory>.Instance.GetOne().BeastBagBuyCost[bagBuyCount];
				ItemConfig itemConfig = ConfigSingleton<ItemConfigCategory>.Instance.Get(item.Id);
				UICommonHelper.ShowConfirmPanel(new ConfirmPanelOptions
				{
					Message = Language.Format(6, 4009, item.Nums + itemConfig.Name),
					ConfirmKey = "beast_buy_battle",
					NoConfirmTillTime = TimeHelper.EndTimeOfDay(TimeHelper.Now(), 18000000L),
					OkAction = delegate
					{
						self.OnBuy().Coroutine();
					}
				});
			}
			else if (self.State == BeastGridState.Locked_Privilege)
			{
				UIManager.Instance.Show<UIRaffleGiftPanel, int>(42005).Coroutine();
			}
			else if (self.State == BeastGridState.Locked_Item)
			{
				UIGameMsgHelper.FloatLanguage(6, 4013);
			}
			else
			{
				UIGameMsgHelper.FloatLanguage(6, 4008);
			}
		}

