		public static void SetData(this UIBeastBagItem self, int position)
		{
			//IL_0057: Unknown result type (might be due to invalid IL or missing references)
			//IL_0182: Unknown result type (might be due to invalid IL or missing references)
			//IL_0188: Unknown result type (might be due to invalid IL or missing references)
			//IL_018c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0192: Unknown result type (might be due to invalid IL or missing references)
			if (self.Top == null)
			{
				UIBeastBagPanel uIBeastBagPanel = UIObject.FindUIObjectOfType<UIBeastBagPanel>();
				self.Top = ((Entity)uIBeastBagPanel._UIBeastBagItemTop.UIObject.Clone()).GetComponent<UIBeastBagItemTop>();
				self.Top.UIObject.SetActive(active: true);
				self.Top.UIObject.Transform.anchoredPosition = self.UIObject.Transform.anchoredPosition;
			}
			BeastModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<BeastModule>();
			Beast beastByPosition = component.GetBeastByPosition(position);
			self.BeastId = ((beastByPosition != null) ? ((Entity)beastByPosition).Id : 0);
			self.Position = position;
			BeastGridState beastGridState = component.CheckPositionState(position);
			if (beastGridState == BeastGridState.Open && self.State != BeastGridState.Open)
			{
				self.PlayUnlockEffect();
			}
			self.State = beastGridState;
			bool flag = self.BeastId != 0;
			self._ImgQuality.SetActive(flag);
			self.Top._GoExp.SetActive(flag && beastByPosition.Config.Type == 0);
			self.Top._GoLock.SetActive(flag && beastByPosition.IsLock);
			self.Top._Level.SetActive(flag);
			self._GoUnActive.SetActive(self.Position >= component.GetBagCount() - 1);
			self._TxtPrivilege.SetActive(self.State == BeastGridState.Locked_Privilege);
			self._ImgQuality.ClearAllEffects();
			if (beastByPosition != null && beastByPosition.Quality >= 7 && beastByPosition.Type > 0)
			{
				self._ImgQuality.SetActive(active: true);
				self._ImgQuality.PlayEffect("ui_fx_shenshou_zhufu_pinzhi");
			}
			self.Top._TxtLevel.SetText(flag ? beastByPosition.Level.ToString() : "");
			string spriteName = (flag ? ("ui_ss_dz_0" + beastByPosition.Quality) : "");
			self._ImgQuality.SetSprite(spriteName).Coroutine();
			self.Top._UIHeroStar.UIObject.SetActive(flag && beastByPosition.Star > 0);
			self.Top._UIHeroStar.SetStar(flag ? beastByPosition.Star : 0);
			BeastGridState beastGridState2 = component.CheckPositionState(self.Position);
			self._GoMask.SetActive(beastGridState2 != BeastGridState.Open);
			self._GoUnActive.SetActive(beastGridState2 != BeastGridState.Open);
			self._Cost.SetActive(beastGridState2 == BeastGridState.Locked_Money);
			if (beastGridState2 == BeastGridState.Locked_Money)
			{
				ET.ConfigBeans.Item valueOrLast = ConfigSingleton<BeastGlobalConfigCategory>.Instance.GetOne().BeastBagBuyCost.GetValueOrLast(component.BagBuyCount);
				self._CostNum.SetText(valueOrLast.Nums.ToString());
			}
		}

