		public static void OnClick(this UIBeastBattleItem self)
		{
			if (self.State == BeastGridState.Open)
			{
				if (self.Beast != null)
				{
					UIManager.Instance.Show<UIBeastDetailsPanel, Beast>(self.Beast).Coroutine();
				}
				return;
			}
			int item = BeastHelper.IsBattlePosition(self.Position).position;
			BeastBattlePosConfig beastBattlePosConfig = ConfigSingleton<BeastBattlePosConfigCategory>.Instance.Get(item);
			if (self.State == BeastGridState.Locked_Money)
			{
				ItemConfig itemConfig = ConfigSingleton<ItemConfigCategory>.Instance.Get(beastBattlePosConfig.Cost.Id);
				UICommonHelper.ShowConfirmPanel(new ConfirmPanelOptions
				{
					Message = Language.Format(6, 4009, beastBattlePosConfig.Cost.Nums + itemConfig.Name),
					ConfirmKey = "beast_buy_bag",
					NoConfirmTillTime = TimeHelper.EndTimeOfDay(TimeHelper.Now(), 18000000L),
					OkAction = delegate
					{
						self.OnBuy().Coroutine();
					}
				});
			}
			else if (self.State == BeastGridState.Locked_Privilege)
			{
				UIManager.Instance.Show<UIRaffleGiftPanel, int>(42005).Coroutine();
			}
			else
			{
				string condText = ((Entity)(object)self).LocalPlayer().GetCondText(beastBattlePosConfig.Conds);
				if (!string.IsNullOrEmpty(condText))
				{
					UIGameMsgHelper.FloatMsg(condText);
				}
				else
				{
					UIGameMsgHelper.FloatLanguage(6, 4008);
				}
			}
		}

