		public static void RefreshView(this UIBeastLevelPanel self)
		{
			Beast beast = self.GetBeast();
			if (beast == null)
			{
				return;
			}
			self._UICommonPower.SetPower(beast.GetPower());
			self._UICommonHeroQuality.SetData(beast.Quality);
			self._TxtName.SetText(beast.Name);
			self._UIHeroSkillItem.SetSkillIcon(new SkillLevel(beast.Config.Skill));
			self._UIRolesPart.UIObject.SetActive(beast.Config.Roles == null || beast.Config.Roles.Length != 0);
			self._UIRolesPart.SetData(beast.Config.Roles);
			BeastLevelConfig nextLevelConfig = beast.NextLevelConfig;
			StatList totalStats = StatList.Create();
			try
			{
				beast.AddStatsToStatList(totalStats);
				StatList levelStats = StatList.Create();
				try
				{
					beast.AddLevelStatsToList(levelStats);
					bool flag = true;
					if (nextLevelConfig != null)
					{
						self._UICommonCost.SetData(new ItemStruct
						{
							ConfigId = 36,
							Nums = nextLevelConfig.Exp
						});
						self._UICommonCost.UIObject.SetActive(active: true);
						flag = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().CheckItemNumsIsEnough(36, nextLevelConfig.Exp);
					}
					if (beast.IsMaxLevel)
					{
						self._TxtAttrItem.CloneAll(levelStats.Count, levelStats.Count, delegate(int index, UIObject uiObject)
						{
							StatStruct stat = levelStats[index];
							stat.Value = totalStats.GetValue(stat.Type, stat.Scope);
							uiObject.SetText(TextHelper.FormatStat(stat));
						}).Coroutine();
					}
					else
					{
						StatList addStats = StatList.Create();
						try
						{
							List<int> obj = new List<int> { 50, 10 };
							int num = 1;
							foreach (int item in obj)
							{
								(bool, long) tuple = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<BeastModule>().CanUpLevel(beast, item, ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().GetItemNumsByItemId(36));
								if (beast.Config.MaxLevel - beast.Level - item >= 0 && tuple.Item1)
								{
									num = item;
									break;
								}
							}
							(bool, long) tuple2 = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<BeastModule>().CanUpLevel(beast, num, ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().GetItemNumsByItemId(36));
							if (tuple2.Item1)
							{
								self._TxtNextLevel.SetText($"{beast.Level + num}");
								self._UICommonCost.SetData(new ItemStruct
								{
									ConfigId = 36,
									Nums = tuple2.Item2
								});
							}
							else
							{
								self._TxtNextLevel.SetText((beast.Level + 1).ToString());
								addStats.AddRange(nextLevelConfig.AddStats);
							}
							self._TxtAttrItem.CloneAll(levelStats.Count, levelStats.Count, delegate(int index, UIObject uiObject)
							{
								StatStruct stat = levelStats[index];
								stat.Value = totalStats.GetValue(stat.Type, stat.Scope);
								long value = addStats.GetValue(stat.Type, stat.Scope);
								if (value > 0)
								{
									uiObject.SetText(TextHelper.FormatStat(stat) + "<color=#5dfa49>+" + TextHelper.FormatStatValue(stat.Type, value) + "</color>");
								}
								else
								{
									uiObject.SetText(TextHelper.FormatStat(stat));
								}
							}).Coroutine();
							if (num > 1)
							{
								self._Label.SetText($"升{num}级");
							}
							else
							{
								self._Label.SetText("升级");
							}
						}
						finally
						{
							if (addStats != null)
							{
								((IDisposable)addStats).Dispose();
							}
						}
					}
					self._TxtNextLevel.SetActive(!beast.IsMaxLevel);
					self._NextArrow.SetActive(!beast.IsMaxLevel);
					self._TxtCurLevel.SetText(beast.Level.ToString());
					self._BtnLevel.SetActive(!beast.IsMaxLevel);
					if (beast.IsMaxLevel)
					{
						self._BtnLevel.BreakLongPress();
					}
					self._BtnLevel.SetGray(!flag);
					self._UICommonCost.UIObject.SetActive(!beast.IsMaxLevel);
					self._MaxLevel.SetActive(beast.IsMaxLevel);
					self._StarWidget.SetActive(beast.Star > 0);
					self._UIHeroStarVer.SetStar(beast.Star);
					self._UICommonModelPanel.ShowHighModel(beast.Config.ModelId).Coroutine();
					self.SetLock(beast.IsLock);
