		public static void OnItemExpandClick(this UIBeastSkillPercentPanel self, UIBeastSkillPercentItem clickedItem)
		{
			if (self.CurrentExpandedItem == clickedItem)
			{
				self.ScrollTo(0);
				self.CurrentExpandedItem.SetExpand(isExpand: false);
				self.CurrentExpandedItem = null;
				return;
			}
			self.CurrentExpandedItem?.SetExpand(isExpand: false, isAnim: false);
			self.CurrentExpandedItem = clickedItem;
			ScrollRect scrollRect = self._ScrollView.GameObject.GetComponent<ScrollRect>();
			((Behaviour)scrollRect).enabled = false;
			clickedItem.SetExpand(isExpand: true, isAnim: true, delegate
			{
				self.ScrollTo(clickedItem.Index);
				((Behaviour)scrollRect).enabled = true;
			});
		}
	}
