		[UIMethod]
		private static void OnShow(this UIBeastSoulBookItemList self, UIShowArgs args)
		{
			int selectTypeItemIndex = ((self.CurrentTypeItemIndex != -1) ? self.CurrentTypeItemIndex : 0);
			self.Tab = args.Param;
			self.TypeData.Clear();
			switch (self.Tab)
			{
			case 1:
				self.TypeData.Add(0);
				foreach (BeastSoulTypeConfig item in ConfigSingleton<BeastSoulTypeConfigCategory>.Instance.GetList())
				{
					if (item.BeastType <= 0)
					{
						self.TypeData.Add(item.Id);
					}
				}
				break;
			case 2:
			{
				self.TypeData.Add(0);
				foreach (BeastTypeConfig item2 in ConfigSingleton<BeastTypeConfigCategory>.Instance.GetList())
				{
					self.TypeData.Add(item2.Id);
				}
				if (self.CurrentTypeItemIndex != -1)
				{
					break;
				}
				UIBeastSoulPanel uIBeastSoulPanel = UIObject.FindUIObjectOfType<UIBeastSoulPanel>();
				if (uIBeastSoulPanel != null)
				{
					Beast beast = uIBeastSoulPanel.GetBeast();
					if (beast != null)
					{
						selectTypeItemIndex = self.TypeData.IndexOf(beast.Type);
					}
				}
				break;
			}
			}
			self._SoulTypeTab.CloneAll(self.TypeData.Count, delegate(int i, UIObject o)
			{
				if (self.CurrentTypeItem == null && i == selectTypeItemIndex)
				{
					self.OnTypeTabClick(i, o);
				}
				o.AddClickHandler(delegate
				{
					self.OnTypeTabClick(i, o);
				});
				int num = self.TypeData[i];
				if (self.Tab == 1)
				{
					SetSoulTypeTab(o, num, self.CurrentTypeItemIndex == i);
				}
				else
				{
					SetBeastTypeTab(o, num, self.CurrentTypeItemIndex == i);
				}
			}).Coroutine();
		}

		private static void SetSoulTypeTab(UIObject tabObject, int soulType, bool isSelect)
		{
			tabObject.Find("Select").SetActive(isSelect);
			tabObject.Find("Icon").SetSprite($"ui_ss_sign_st_{soulType}").Coroutine();
			if (soulType == 0)
			{
				tabObject.Find("Text").SetText("全部");
				return;
			}
			BeastSoulTypeConfig beastSoulTypeConfig = ConfigSingleton<BeastSoulTypeConfigCategory>.Instance.Get(soulType);
			tabObject.Find("Text").SetText(beastSoulTypeConfig.Name);
		}

		private static void SetBeastTypeTab(UIObject tabObject, int beastType, bool isSelect)
		{
			tabObject.Find("Select").SetActive(isSelect);
			tabObject.Find("Icon").SetSprite($"ui_ss_sign_bt_{beastType}").Coroutine();
			if (beastType == 0)
			{
				tabObject.Find("Text").SetText("全部");
				return;
			}
			BeastTypeConfig beastTypeConfig = ConfigSingleton<BeastTypeConfigCategory>.Instance.Get(beastType);
			tabObject.Find("Text").SetText(beastTypeConfig.Name);
		}

		private static void OnTypeTabClick(this UIBeastSoulBookItemList self, int currentIndex, UIObject typeItem)
		{
			if (self.CurrentTypeItemIndex != currentIndex)
			{
				self.CurrentTypeItemIndex = currentIndex;
				if (self.CurrentTypeItem != null)
				{
					self.CurrentTypeItem.Find("Select").SetActive(active: false);
				}
				self.CurrentTypeItem = typeItem;
				self.CurrentTypeItem.Find("Select").SetActive(active: true);
				self.RefreshView_List();
			}
		}

		private static void OnUpdateItem(this UIBeastSoulBookItemList self, UIScrollListCell cell)
		{
			BeastSoulConfig beastSoulConfig = self.BookList[cell.Index];
			UIBeastSoulBookItem component = ((Entity)cell.UIObject).GetComponent<UIBeastSoulBookItem>();
			component._UICommonItem.SetItem(beastSoulConfig.Id, 0L);
			component._Name.SetText(beastSoulConfig.Name);
		}

		private static void RefreshView_List(this UIBeastSoulBookItemList self)
		{
			if (self.CurrentTypeItem == null)
			{
				return;
			}
			self.BookList.Clear();
			if (self.Tab == 1)
			{
				int num = self.TypeData[self.CurrentTypeItemIndex];
				if (num == 0)
				{
					self.BookList.AddRange(ConfigSingleton<BeastSoulConfigCategory>.Instance.GetAllNormal());
				}
				else
				{
					self.BookList.AddRange(ConfigSingleton<BeastSoulConfigCategory>.Instance.GetAllBySoulType(num));
				}
			}
			else
			{
				int num2 = self.TypeData[self.CurrentTypeItemIndex];
				if (num2 == 0)
				{
					self.BookList.AddRange(ConfigSingleton<BeastSoulConfigCategory>.Instance.GetAllExclusive());
				}
				else
				{
					self.BookList.AddRange(ConfigSingleton<BeastSoulConfigCategory>.Instance.GetAllExclusiveByBeastType(num2));
				}
			}
			self.BookList.Sort((BeastSoulConfig a, BeastSoulConfig b) => BeastHelper.CompareBeastSoul(b.Id, a.Id));
			self._UIScrollList.SetData(self.BookList.Count);
		}
	}
