		private static void RefreshView(this UIBeastSoulEquipPanel self)
		{
			self.Data.Clear();
			Player player = ((Entity)(object)self).LocalPlayer();
			int equippedSoul = ((Entity)player).GetComponent<BeastModule>().GetEquippedSoul(self.BeastType, self.SlotId);
			int id = self.BeastType * 100 + self.SlotId;
			BeastSoulSlotConfig beastSoulSlotConfig = ConfigSingleton<BeastSoulSlotConfigCategory>.Instance.Get(id);
			foreach (Item item in ((Entity)((Entity)player).GetComponent<ItemModule>()).Children.Values.Cast<Item>())
			{
				ItemConfig config = item.Config;
				if (config.Type == 12 && (config as BeastSoulConfig).SoulType == beastSoulSlotConfig.BeastSoulType && item.ConfigId != equippedSoul)
				{
					self.Data.Add((item.ConfigId, false));
				}
			}
			self.Data.Sort(((int, bool) a, (int, bool) b) => BeastHelper.CompareBeastSoul(a.Item1, b.Item1));
			if (equippedSoul > 0)
			{
				self.Data.Add((equippedSoul, true));
			}
			self.Data.Reverse();
			self._UIScrollList.SetData(self.Data.Count);
			self._ListEmpty.SetActive(self.Data.Count == 0);
		}

