					finally
					{
						((IDisposable)val)?.Dispose();
					}
				}
				if (item.Id == beastSoulConfig.Id)
				{
					num = stringBuilder.Length;
					stringBuilder.Append("<color=#0db64d>【" + TextHelper.GetQualityNameWithStar(item.Quality, item.StarLv) + "】 " + text2 + "</color>\n");
				}
				else
				{
					stringBuilder.Append("【" + TextHelper.GetQualityNameWithStar(item.Quality, item.StarLv) + "】 " + text2 + "\n");
				}
			}
			stringBuilder.Remove(stringBuilder.Length - 1, 1);
