		public static void RefreshView(this UIBeastSoulSplitPanel self)
		{
			self.SoulList.Clear();
			self.SelectIndexes.Clear();
			Item[] allItems = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().GetAllItems();
			foreach (Item item in allItems)
			{
				if (item.Config.Type == 12 && ConfigSingleton<BeastSoulConfigCategory>.Instance.GetSplitConfig(item.ConfigId) != null)
				{
					for (int j = 0; j < item.Nums; j++)
					{
						self.SoulList.Add(new ItemStruct
						{
							ConfigId = item.ConfigId,
							Nums = 1L
						});
					}
				}
			}
			self.SoulList.Sort((ItemStruct a, ItemStruct b) => BeastHelper.CompareBeastSoul(a.ConfigId, b.ConfigId));
			self._UIScrollList.SetData(self.SoulList.Count);
			self._ListEmpty.SetActive(self.SoulList.Count == 0);
			self._ItemListContent.SetActive(self.SoulList.Count > 0);
			self.RefreshSplitReward();
		}

		public static void RefreshSplitReward(this UIBeastSoulSplitPanel self)
		{
			using ItemList itemList = ItemList.Create();
			foreach (int selectIndex in self.SelectIndexes)
			{
				ItemStruct itemStruct = self.SoulList[selectIndex];
				BeastSoulConfig splitConfig = ConfigSingleton<BeastSoulConfigCategory>.Instance.GetSplitConfig(itemStruct.ConfigId);
				itemList.Add(new ItemStruct
				{
					ConfigId = splitConfig.Id,
					Nums = splitConfig.ComposeCost
				});
			}
			self._UICommonHorizontalReward.SetData(itemList);
			self._EmptyReward.SetActive(itemList.Count == 0);
		}

