			if (flag)
			{
				self.SelectIndexes.Remove(cell.Index);
			}
			else
			{
				self.SelectIndexes.Add(cell.Index);
			}
			((Entity)cell.UIObject).GetComponent<UICommonItem>().SetCheck(!flag);
			self.RefreshSplitReward();
		}

