		public static void SetData(this UIChatBeastPart self, ChatInfo chatInfo)
		{
			self.ChatInfo = chatInfo;
			string[] array = chatInfo.Text.Split("|");
			if (array.Length == 0)
			{
				return;
			}
			int id = int.Parse(array[0]);
			int id2 = int.Parse(array[1]);
			if (!ConfigSingleton<ChatNoticeConfigCategory>.Instance.Contain(id))
			{
				return;
			}
			self.Config = ConfigSingleton<ChatNoticeConfigCategory>.Instance.Get(id);
			BeastConfig beastConfig = ConfigSingleton<BeastConfigCategory>.Instance.Get(id2);
			bool flag = beastConfig.Grade == 6;
			self._Beast.SetRawTexture(self.GetBeastRawTexture(beastConfig.Grade, beastConfig.Type)).Coroutine();
			self._Bubble.SetSprite(flag ? "ui_ss2_frame_10" : "ui_ss2_frame_09").Coroutine();
			if (flag)
			{
				self._Channgle.SetActive(active: false);
				self._ChanngleText.SetText(beastConfig.Name);
				self._ChanngleImg.SetActive(active: false);
				return;
			}
			self._ChanngleText.SetText(string.Empty);
			self._Channgle.SetActive(active: true);
			self._ChanngleImg.SetActive(beastConfig.Grade > 7);
			self._Channgle.SetSprite(self.GetUpGodImage(beastConfig.Type)).Coroutine();
			if (self._ChanngleImg.IsActive())
			{
				self._Channgle.SetScale(0.85f);
				self._ChanngleImg.SetTexture($"ui_ss2_front_1{beastConfig.Grade - 7}").Coroutine();
			}
			else
			{
				self._Channgle.SetScale(1f);
			}
		}

		private static string GetUpGodImage(this UIChatBeastPart self, int type)
		{
			return type switch
			{
				1 => "ui_ss2_front_02", 
				2 => "ui_ss2_front_03", 
				3 => "ui_ss2_front_04", 
				4 => "ui_ss2_front_05", 
				_ => string.Empty, 
			};
		}

		private static string GetBeastRawTexture(this UIChatBeastPart self, int pinzhi, int type)
		{
			if (pinzhi == 6)
			{
				return $"ui_ss2_frame_10_{type}";
			}
			if (pinzhi >= 7)
			{
				return $"ui_ss2_frame_09_{type}";
			}
			return string.Empty;
		}

