		public static void UpdateFace(this UIChatInput self, int selectTabIndex)
		{
			int num = selectTabIndex + 1;
			self.Emotes.Clear();
			foreach (var (_, emoteConfig2) in ConfigSingleton<EmoteConfigCategory>.Instance.GetAll())
			{
				if (emoteConfig2.EmoteType == num)
