		public static void OnSendClick(this UIChatInput self)
		{
			string text = self._InputField.GameObject.GetComponent<InputField>().text;
			if (string.IsNullOrEmpty(text))
			{
				UIGameMsgHelper.FloatMsgByError(202904);
				return;
			}
			Player player = ((Entity)(object)self).LocalPlayer();
			ChatModule component = ((Entity)player).GetComponent<ChatModule>();
			self._InputField.GameObject.GetComponent<InputField>().text = string.Empty;
			if (text.StartsWith("$"))
			{
				if (text.ToLower().StartsWith("$settime"))
				{
					GMCommandHelper.HandleSetTimeCommand(text);
				}
				component.Send(text);
			}
			else if (!text.StartsWith("!") || !GMCommandComponent.Instance.Execute(player, text))
			{
				bool isOn = self._BroadToggle.GameObject.GetComponent<Toggle>().isOn;
				UIObject.FindUIObjectOfType<UIChatPanel>()?.ChatSendToServer(text, 0, isOn);
				UIObject.FindUIObjectOfType<UIKingWarChatPanel>()?.ChatSendToServer(text, 0, isOn);
				if (self.Callback != null)
				{
					self.Callback(text, 0, isOn);
				}
			}
		}
	}
