			self.UpdateCommonUI(chatInfo);
			self._Content.SetActive(active: false);
			self._BroadContent.SetActive(active: false);
			self._FaceImage.SetActive(active: false);
			self._UIChatGuildPart.UIObject.SetActive(active: false);
			self._UIChatServerPart.UIObject.SetActive(active: false);
			self._UIChatBeastPart.UIObject.SetActive(active: false);
			self._UIChatRawPart.UIObject.SetActive(active: false);
			self._UIChatImperialPart.UIObject.SetActive(active: false);
			self._UIChatGuildWarPart.UIObject.SetActive(active: false);
			switch (chatInfo.ChatType)
			{
			case 1:
				if (chatInfo.IsBroad)
				{
					self.ShowBroadNormal(chatInfo);
				}
				else
				{
					self.ShowNormal(chatInfo);
				}
				break;
			case 2:
				if (chatInfo.IsBroad)
				{
					self.ShowBroadFace(chatInfo);
				}
				else
				{
					self.ShowFace(chatInfo);
				}
				break;
			case 3:
			case 6:
			case 7:
				self.ShowGuildRecruit(chatInfo);
				break;
			case 8:
				self.OnSetNoticeType(chatInfo);
				break;
			case 4:
			case 5:
				break;
			}
		}

		private static void OnSetNoticeType(this UIChatItem self, ChatInfo chatInfo)
		{
			string[] array = chatInfo.Text.Split("|");
			if (array.Length == 0)
			{
				return;
			}
			int num = int.Parse(array[0]);
			if (!ConfigSingleton<ChatNoticeConfigCategory>.Instance.Contain(num))
			{
				return;
			}
			switch (ConfigSingleton<ChatNoticeConfigCategory>.Instance.Get(num).PrefabType)
			{
			case 1:
			{
				string level = string.Empty;
				if (array.Length == 2)
				{
					level = array[1];
				}
				self.ShowPrivilegeRecruit(num, level);
				break;
			}
			case 2:
				self.ShowGuildWarRecruit(chatInfo);
				break;
			case 3:
				self.ShowImperialPowerRecruit(chatInfo);
				break;
			case 4:
				self.ShowImperiallyConferRecruit(chatInfo);
				break;
			case 5:
				self.ShowBeastRecruit(chatInfo);
				break;
			case 6:
				self.ShowGuildRecruit(chatInfo);
				break;
			case 7:
				self.ShowGuildRecruit(chatInfo);
				break;
			default:
				self.ShowBroadNormal(chatInfo);
				break;
			}
		}

