		private static void SetChatFrame(this UIChatItem self, ChatInfo chatInfo)
		{
			int chatFrame = chatInfo.Sender.DressInfo.ChatFrame;
			if (chatFrame % 10 == 0)
			{
				self._Content.SetSprite("ui_talk_frame_08_gv").Coroutine();
				self._ContentText.SetText("<color=#323232>" + chatInfo.Text + "</color>");
				return;
			}
			self._Content.SetSprite($"uit_chat_fashion_{chatFrame}").Coroutine();
			string textColor = ConfigSingleton<FashionChatConfigCategory>.Instance.Get(chatFrame).TextColor;
			self._ContentText.SetText("<color=" + textColor + ">" + chatInfo.Text + "</color>");
		}

		private static void SetBroadChatFrame(this UIChatItem self, ChatInfo chatInfo)
