		public static void ChatSendToServer(this UIChatPanel self, string content, int faceId, bool isBroad)
		{
			Player player = ((Entity)(object)self).LocalPlayer();
			ChatModule component = ((Entity)player).GetComponent<ChatModule>();
			if (self.CurrentTabIndex == 2 && ((Entity)player).GetComponent<GuildModule>().GuildId == 0L)
			{
				UIGameMsgHelper.FloatMsg("当前未加入仙盟！");
				return;
			}
			int practiceLevel = ((Entity)player).GetComponent<PracticeModule>().GetPracticeLevel();
			if (ConfigSingleton<GlobalConfigCategory>.Instance.GetOne().ChatLevel > practiceLevel)
			{
				UIGameMsgHelper.FloatMsgByError(202901);
				return;
			}
			if (isBroad)
			{
				if (component.GetNextBroadSendTime() > TimeHelper.Now())
				{
					UIGameMsgHelper.FloatMsgByError(202903);
					return;
				}
				component.NextBroadSendTime = TimeHelper.Now() + ConfigSingleton<GlobalConfigCategory>.Instance.GetOne().ChatBroadCD;
				ItemModule component2 = ((Entity)player).GetComponent<ItemModule>();
				int chatHornId = ConfigSingleton<GlobalConfigCategory>.Instance.GetOne().ChatHornId;
				if (component2.GetItemNumsByItemId(chatHornId) <= 0)
				{
					UIManager.Instance.Show<UIChatBuyPanel, Action>(delegate
					{
						self.ChatSendAction(content, faceId, isBroad: true).Coroutine();
					}).Coroutine();
					return;
				}
			}
			else
			{
				if (component.GetNextSendTime(self.CurrentTabIndex) > TimeHelper.Now())
				{
					UIGameMsgHelper.FloatMsgByError(202902);
					return;
				}
				long time = self.CurrentTabIndex switch
				{
					1 => TimeHelper.Now() + ConfigSingleton<GlobalConfigCategory>.Instance.GetOne().ChatCD, 
					2 => TimeHelper.Now() + ConfigSingleton<GlobalConfigCategory>.Instance.GetOne().ChatGuildCD, 
					3 => TimeHelper.Now() + ConfigSingleton<GlobalConfigCategory>.Instance.GetOne().ChatPersonCD, 
					_ => 0L, 
				};
				component.SetNextSendTime(self.CurrentTabIndex, time);
			}
			self.ChatSendAction(content, faceId, isBroad).Coroutine();
		}

