		private static void UpdateView(this UIChatPanel self)
		{
			ChatModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ChatModule>();
			if (self.CurrentTabIndex == 3)
			{
				self._ChatPersonPanel.UIObject.SetActive(active: true);
				self._ChatWorldPanel.ShowPanel(isShow: false);
				if (self.CurrentPlayer == null)
				{
					self._ChatPersonPanel.UpdateView();
				}
				else
				{
					self._ChatPersonPanel.SetData(self.CurrentPlayer).Coroutine();
				}
				self._ChatBottom.UIObject.SetActive(self.CurrentPlayer != null);
				self._ChatBottom.SetBroadShowOrHide(isShow: false);
				component.UnReadCountOfPerson = 0;
			}
			else
			{
				self._ChatBottom.SetBroadShowOrHide(isShow: true);
				self._ChatPersonPanel.UIObject.SetActive(active: false);
				self._ChatWorldPanel.ShowPanel(isShow: true);
				self._ChatWorldPanel.UpdatePanel(self.CurrentTabIndex);
				self._ChatBottom.UIObject.SetActive(active: true);
				if (self.CurrentTabIndex == 1)
				{
					component.UnReadCountOfWorld = 0;
				}
				else if (self.CurrentTabIndex == 2)
				{
					component.UnReadCountOfGuild = 0;
					self._ChatBottom.SetBroadShowOrHide(isShow: false);
				}
				else if (self.CurrentTabIndex == 7)
				{
					component.UnReadCountOfCrossChat = 0;
				}
			}
			UIObject.FindUIObjectOfType<UIMainChatPart>()?.UpdateView();
			self.UpdateRedPoint();
			self._ChatBottom.StartCD(self.CurrentTabIndex);
		}

		public static void UpdateRedPoint(this UIChatPanel self)
		{
			RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.Interactive_Chat);
			RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.Interactive_Chat, 1);
			RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.Interactive_Chat, 2);
			RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.Interactive_Chat, 3);
			RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.Interactive_Chat, 7);
		}

