		[UIMethod]
		public static void OnDestroy(this UICommonConfirmSliderPanel self)
		{
			self.Options.CancelAction = null;
			self.Options.OkAction = null;
			self.Options = default(ConfirmSliderPanelOptions);
		}

		[UIMethod]
		public static void OnShow(this UICommonConfirmSliderPanel self, ConfirmSliderPanelOptions options)
		{
			if (options.Title != null)
			{
				self._CommonBg.SetTitle(options.Title);
			}
			if (options.Message != null)
			{
				self._MessageText.SetText(options.Message);
			}
			if (options.OkButtonText != null)
			{
				self._OkText.SetText(options.OkButtonText);
			}
			if (options.CancelButtonText != null)
			{
				self._CancelText.SetText(options.CancelButtonText);
			}
			self.Options = options;
			self.Options.MinValue = ((options.MinValue != 0) ? options.MinValue : 0);
			self.Options.MaxValue = ((options.MaxValue == 0) ? 1 : options.MaxValue);
			self.Options.StartValue = ((options.StartValue == 0) ? 1 : options.StartValue);
			if (self.Options.MinValue == self.Options.MaxValue && self.Options.MinValue == 1)
			{
				self.Options.MinValue = 0;
			}
			((Slider)self.SuperSlider).minValue = self.Options.MinValue;
			((Slider)self.SuperSlider).maxValue = self.Options.MaxValue;
			((Slider)self.SuperSlider).value = self.Options.StartValue;
			self.isGray = true;
			self.UpdateObtainWay();
		}

		private static void UpdateObtainWay(this UICommonConfirmSliderPanel self)
		{
			int priceType = self.Options.PriceType;
			if (priceType == 0)
			{
				self.UIObject.Find("Content").Transform.SetSizeWithCurrentAnchors((Axis)1, 450f);
				self._ObtainGroup.SetActive(active: false);
				return;
			}
			PrivilegeObtainWayConfig privilegeObtainWayConfig = ConfigSingleton<PrivilegeObtainWayConfigCategory>.Instance.Get(priceType);
			if (privilegeObtainWayConfig.ObtainId == null)
			{
				self.UIObject.Find("Content").Transform.SetSizeWithCurrentAnchors((Axis)1, 450f);
				self._ObtainGroup.SetActive(active: false);
				return;
			}
			self._ObtainGroup.SetActive(active: true);
			self._ObtainList.SetData(privilegeObtainWayConfig.ObtainId.Length);
			self._ObtainGroup.Transform.SetSizeWithCurrentAnchors((Axis)1, (float)((privilegeObtainWayConfig.ObtainId.Length > 1) ? 340 : 188));
			self.UIObject.Find("Content").Transform.SetSizeWithCurrentAnchors((Axis)1, (float)((privilegeObtainWayConfig.ObtainId.Length > 1) ? 800 : 650));
		}

		private static void OnOkButtonClick(this UICommonConfirmSliderPanel self)
		{
			self.Options.OkAction?.Invoke();
			((DisposeObject)self.UIObject).Dispose();
		}

		private static void OnCancelButtonClick(this UICommonConfirmSliderPanel self)
		{
			self.Options.CancelAction?.Invoke();
			((DisposeObject)self.UIObject).Dispose();
		}

		private static void OnSliderValueChanged(this UICommonConfirmSliderPanel self, float value)
		{
			int num = (int)value;
			if (value <= 0f)
			{
				if (self.CurrentValue == 1)
				{
					((Slider)self.SuperSlider).SetValueWithoutNotify(1f);
					return;
				}
				num = 1;
				self.CurrentValue = 1;
				self.Options.SliderAction?.Invoke(self, num);
				((InputField)self.SuperInputField).SetTextWithoutNotify(num.ToString());
				((Slider)self.SuperSlider).SetValueWithoutNotify((float)num);
				self.UpdateUI();
			}
			else
			{
				self.CurrentValue = num;
				self.Options.SliderAction?.Invoke(self, num);
				((InputField)self.SuperInputField).SetTextWithoutNotify(num.ToString());
				self.UpdateUI();
			}
		}

		private static void OnClickMaxButton(this UICommonConfirmSliderPanel self)
		{
			self.CurrentValue = self.Options.MaxValue;
			((Slider)self.SuperSlider).value = self.CurrentValue;
		}

		private static void OnClickChange(this UICommonConfirmSliderPanel self, int value)
		{
			if (self.CurrentValue + value < self.Options.MinValue)
			{
				self.CurrentValue = self.Options.MinValue;
			}
			else if (self.CurrentValue + value > self.Options.MaxValue)
			{
				self.CurrentValue = self.Options.MaxValue;
			}
			self.CurrentValue += value;
			((Slider)self.SuperSlider).value = self.CurrentValue;
		}

		private static void OnInputNumChanged(this UICommonConfirmSliderPanel self, string value)
		{
			if (int.TryParse(value, out var result))
			{
				if (result <= 0)
				{
					result = 1;
				}
				if (result < self.Options.MinValue)
				{
					self.CurrentValue = self.Options.MinValue;
				}
				else if (result > self.Options.MaxValue)
				{
					self.CurrentValue = self.Options.MaxValue;
				}
				else
				{
					self.CurrentValue = result;
				}
			}
			else
			{
				self.CurrentValue = self.Options.MinValue;
			}
			((InputField)self.SuperInputField).SetTextWithoutNotify(self.CurrentValue.ToString());
			((Slider)self.SuperSlider).value = self.CurrentValue;
		}

		public static void SetOKText(this UICommonConfirmSliderPanel self, string text)
		{
			self._OkText.SetText(text);
		}

		public static void SetCancelText(this UICommonConfirmSliderPanel self, string text)
		{
			self._CancelText.SetText(text);
		}

		public static void SetMessage(this UICommonConfirmSliderPanel self, string text)
		{
			self._MessageText.SetText(text);
		}

		public static void ShowNotEnough(this UICommonConfirmSliderPanel self)
		{
			self._MessageText.SetText("购买次数不足");
			self._OkButton.SetGray();
			((InputField)self.SuperInputField).SetTextWithoutNotify("0");
		}

		public static void SetCost(this UICommonConfirmSliderPanel self, ItemStruct costItem)
		{
			if (costItem.ConfigId == 0)
			{
				self._Cost.SetActive(active: false);
				self.SetOkGray(isGray: false);
				return;
			}
			self._Cost.SetActive(active: true);
			ItemConfig itemConfig = ConfigSingleton<ItemConfigCategory>.Instance.Get(costItem.ConfigId);
			self._RawCostIcon.SetRawTexture($"uitex_icon_item_{itemConfig.Icon}").Coroutine();
			self._TxtCost.SetText(costItem.Nums.ToString());
			self.isGray = ((Entity)(object)self).LocalPlayer().CheckItemNumsIsEnough(costItem);
			self.SetOkGray(!self.isGray);
		}

		public static void SetOkGray(this UICommonConfirmSliderPanel self, bool isGray)
		{
			self._OkButton.SetGray(isGray);
		}

		private static void UpdateUI(this UICommonConfirmSliderPanel self)
		{
			self._AddButton.SetSprite((self.CurrentValue >= self.Options.MaxValue) ? "ui_bag_btn_06" : "ui_bag_btn_07", nativeSize: true).Coroutine();
			self._SubButton.SetSprite((self.CurrentValue <= self.Options.MinValue || (self.Options.MinValue == 0 && self.CurrentValue == 1)) ? "ui_bag_btn_06" : "ui_bag_btn_07", nativeSize: true).Coroutine();
		}

		private static void OnCellUpdate(this UICommonConfirmSliderPanel self, UIScrollListCell cell)
		{
			int index = cell.Index;
			UIStrongPayWayItem1 component = ((Entity)cell.UIObject).GetComponent<UIStrongPayWayItem1>();
			int priceType = self.Options.PriceType;
			PrivilegeObtainWayConfig privilegeObtainWayConfig = ConfigSingleton<PrivilegeObtainWayConfigCategory>.Instance.Get(priceType);
			component.SetData(ConfigSingleton<PayWayConfigCategory>.Instance.Get(privilegeObtainWayConfig.ObtainId[index]));
		}
	}
