		}

		public static void SetData(this UICommonEquipItemSelect self, int job, int part, int configId)
		{
			if (self.Job == job && self.Part == part)
			{
				self.IsShowEnhanceEffect = true;
			}
			self.Job = job;
			self.Part = part;
			self.ConfigId = configId;
			self._GemIcon.SetSprite($"ui_gm_part_0{part}", nativeSize: true).Coroutine();
			self._LockImage.SetActive(active: false);
			self._AddButton.SetActive(active: false);
			if (!((Entity)(object)self).LocalPlayer().IsPartOpen(job, part))
			{
				self._LockImage.SetActive(active: true);
				EquipPartConfig partOpenConfig = VibesHelper.GetPartOpenConfig(job, part);
				self._LockText.SetText(partOpenConfig.CondDesc);
				self.ClearItem();
				return;
			}
			self._AddButton.SetActive(configId == 0);
			if (configId == 0)
			{
				self.ClearItem();
				self.StartIdleEffect();
			}
			else
			{
				self.KillIdleEffect();
				self._EquipItem.SetItem(configId, 1L);
			}
		}

		private static void ClearItem(this UICommonEquipItemSelect self)
		{
			self._EquipItem.Clear();
		}

		public static void StartIdleEffect(this UICommonEquipItemSelect self)
		{
			//IL_002d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0052: Unknown result type (might be due to invalid IL or missing references)
			if (!self.IsStart)
			{
				self.IsStart = true;
				ShortcutExtensions.DOKill((Component)(object)self._AddButton.Transform, false);
				((Transform)self._AddButton.Transform).localScale = Vector3.one;
				self.Tween = TweenSettingsExtensions.SetLoops<TweenerCore<Vector3, Vector3, VectorOptions>>(ShortcutExtensions.DOScale((Transform)(object)self._AddButton.Transform, new Vector3(1.5f, 1.5f, 1.5f), 1f), -1, (LoopType)1);
			}
		}

		public static void KillIdleEffect(this UICommonEquipItemSelect self)
		{
			if (self.IsStart)
			{
				TweenExtensions.Kill((Tween)(object)self.Tween, false);
				self.IsStart = false;
				self.Tween = null;
			}
		}

		public static void SetShowTab(this UICommonEquipItemSelect self, int tabIndex)
		{
			//IL_0062: Unknown result type (might be due to invalid IL or missing references)
			//IL_0081: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a5: Unknown result type (might be due to invalid IL or missing references)
			//IL_013d: Unknown result type (might be due to invalid IL or missing references)
			//IL_015c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0180: Unknown result type (might be due to invalid IL or missing references)
			self.UIObject.SetActive(active: true);
			self._LevelText.SetActive(active: false);
			self._PowerText.SetActive(active: false);
			self._DemonText.SetActive(active: false);
			self._GemContent.SetActive(active: false);
			self._EquipItem.UIObject.SetActive(active: true);
			self._Select.Transform.sizeDelta = new Vector2(180f, 180f);
			self.UIObject.Transform.sizeDelta = new Vector2(160f, 160f);
			((Transform)self.UIObject.Transform).localScale = new Vector3(0.8f, 0.8f, 0.8f);
			if (!((Entity)(object)self).LocalPlayer().IsPartOpen(self.Job, self.Part))
			{
				self._LockImage.SetActive(active: true);
				EquipPartConfig partOpenConfig = VibesHelper.GetPartOpenConfig(self.Job, self.Part);
				self._LockText.SetText(partOpenConfig.CondDesc);
				return;
			}
			switch (tabIndex)
			{
			case 1:
				if (self.ConfigId == 0)
				{
					return;
				}
				self.ShowLevel();
				self.ShowPower();
				break;
			case 2:
				self._Select.Transform.sizeDelta = new Vector2(160f, 193f);
				self.UIObject.Transform.sizeDelta = new Vector2(117f, 150f);
				((Transform)self.UIObject.Transform).localScale = new Vector3(1f, 1f, 1f);
				self.ShowGem();
				break;
			case 3:
				self.UIObject.SetActive(active: false);
				break;
			}
			self.IsShowEnhanceEffect = false;
		}

		private static void ShowLevel(this UICommonEquipItemSelect self)
		{
			EquipConfig equipConfig = ConfigSingleton<EquipConfigCategory>.Instance.Get(self.ConfigId);
			self._LevelText.SetText($"{equipConfig.Level}级");
		}

		private static void ShowPower(this UICommonEquipItemSelect self)
		{
			self._PowerText.SetActive(active: true);
			int powerLevel = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesEquipModule>().GetPowerLevel(self.Job, self.Part);
			self._PowerText.SetText($"+{powerLevel}");
			if (self.IsShowEnhanceEffect && powerLevel > self.EnhanceLevel)
			{
				self.PlayEnhanceEffect();
			}
