		public static bool IsVailTodayLocalData(string key)
		{
			if (string.IsNullOrEmpty(key))
			{
				return false;
			}
			((Entity)(object)UIManager.Instance).LocalPlayer().GetLocalData<LocalData_Confirm>().Confirms.TryGetValue(key, out var value);
			long num = TimeHelper.Now();
			return value >= num;
		}

		public static void ShowConfirmPanel(ConfirmPanelOptions options)
		{
			Player player = ((Entity)(object)UIManager.Instance).LocalPlayer();
			if (!string.IsNullOrEmpty(options.ConfirmKey))
			{
				if (options.NoConfirmTillNextLogin)
				{
					if (((Entity)player).GetComponent<PlayerTempDataModule>().CheckConfirmKey(options.ConfirmKey))
					{
						options.OkAction?.Invoke();
						return;
					}
				}
				else
				{
					player.GetLocalData<LocalData_Confirm>().Confirms.TryGetValue(options.ConfirmKey, out var value);
					long num = TimeHelper.Now();
					if (value > num)
					{
						options.OkAction?.Invoke();
						return;
					}
				}
			}
			UIManager.Instance.Show<UICommonConfirmPanel, ConfirmPanelOptions>(options).Coroutine();
		}

