		{
			ItemConfig itemConfig = ET.ItemHelper.GetItemConfig(item.ConfigId);
			if (itemConfig == null)
			{
				return;
			}
			if (itemConfig.Type == 14)
			{
				ShowHeroSkinTips(item);
				return;
			}
			if (itemConfig.Type == 13)
			{
				FashionConfig fashionConfig = ConfigSingleton<FashionConfigCategory>.Instance.Get(itemConfig.UseEffParams.GetValueOrDefault(0, 0));
				if (fashionConfig == null)
				{
					return;
				}
				int type = fashionConfig.Type;
				if (type == 1 || type == 6 || type == 7)
				{
					UIManager.Instance.Show<UIDressSuitItemTipsPanel, int>(item.ConfigId).Coroutine();
					return;
				}
			}
			if (itemConfig.Type == 5)
			{
				ShowGemTips(item);
			}
			else
			{
				UIManager.Instance.Show<UIItemTipsPanel, ItemStruct>(item).Coroutine();
			}
		}

