		public static void ShowPlayerJewelryInfo(this UIManager uiManager, int jewelryId)
		{
			Player player = ((Entity)(object)uiManager).LocalPlayer();
			ItemConfig itemConfig = ET.ItemHelper.GetItemConfig(jewelryId);
			Hero hero = HeroHelper.GetHero(heroId: itemConfig.UseEffParams[0], self: ((Entity)player).GetComponent<HeroModule>(), createEntity: true);
