					if (jewelryStarConfig == null)
					{
						break;
					}
					if (jewelryStarConfig.SkillId == null)
					{
						num3++;
						continue;
					}
					for (int i = 0; i < jewelryStarConfig.SkillId.Length; i++)
					{
