				foreach (JewelryGroupConfig item3 in allSuit)
				{
					int num4 = 0;
					for (int j = 0; j < item3.JewelySkill.Length; j++)
					{
						int num5 = item3.JewelyIds[0] % 100;
						SkillLevel item2 = new SkillLevel(item3.JewelySkill[j]);
						if (dictionary.TryGetValue(num5, out var value2))
						{
							value2.Add(item2);
						}
						else
						{
							dictionary.Add(num5, new List<SkillLevel> { item2 });
						}
						for (int k = 0; k < item3.JewelyIds.Length; k++)
						{
							int jewelryId2 = item3.JewelyIds[k] / 100;
							bool flag = hero.IsJewelryActive(jewelryId2);
							if ((hero.GetJewelryStar(jewelryId2) >= num5) & flag)
							{
