							}
						}
						dictionary2.Add(num5, new int[2]
						{
							num4,
							item3.JewelyIds.Length
						});
					}
				}
				List<JewelryGroupConfig> activeSuitConfigs = GetActiveSuitConfigs(hero, allSuit);
				num2 = ((activeSuitConfigs.Count > 0) ? (activeSuitConfigs[^1].JewelyIds[0] % 100) : (-1));
			}
			List<int> list = new List<int>();
			HashSet<int> hashSet = new HashSet<int>();
			foreach (KeyValuePair<int, List<SkillLevel>> kvp1 in dictionary.OrderBy((KeyValuePair<int, List<SkillLevel>> x) => x.Key))
			{
				if (hashSet.Contains(kvp1.Key))
				{
					continue;
				}
				foreach (KeyValuePair<int, List<SkillLevel>> item4 in dictionary.Where((KeyValuePair<int, List<SkillLevel>> x) => x.Key > kvp1.Key))
				{
					if (kvp1.Value.Count == item4.Value.Count && kvp1.Value.OrderBy((SkillLevel s) => s.SkillLevelId).SequenceEqual(item4.Value.OrderBy((SkillLevel s) => s.SkillLevelId)))
					{
