		[UIMethod]
		private static void OnAwake(this UICommonHeroCard self)
		{
			self._BgImg.AddClickHandler(self.OnBgClick);
		}

		public static void IsActive(this UICommonHeroCard self, bool state)
		{
			self._NoActive.SetActive(!state);
		}

		private static void OnBgClick(this UICommonHeroCard self)
		{
			if (self.HeroCommonInfo != null)
			{
				UIManager.Instance.Show<UIHeroMaxAttrPanel, HeroCommonInfo>(self.HeroCommonInfo).Coroutine();
			}
		}

		public static void SetData(this UICommonHeroCard self, HeroCommonInfo heroCommonInfo, string roleName)
		{
			self.UIObject.ClearAllEffects();
			self.HeroCommonInfo = heroCommonInfo;
			self.SetHeroBaseUI(heroCommonInfo, roleName);
			self._HeroStarArea.SetStar(heroCommonInfo.Star, showBackground: true);
			self.IsActive(state: true);
			self._OnFight.SetActive(active: false);
		}

		public static void SetData(this UICommonHeroCard self, Hero hero)
		{
			self.UIObject.ClearAllEffects();
			if (hero != null && hero.Config != null)
			{
				self.Hero = hero;
				SetHeroBaseUI(self, hero);
				self._HeroStarArea.SetStar(hero.Star, showBackground: true);
				SetHeroProgressUI(self, hero);
				self.IsActive(hero.IsActive);
				self._OnFight.SetActive(hero.IsActive && hero.CanUpStar());
			}
		}

		public static void OnSetFight(this UICommonHeroCard self, bool isFight = false)
		{
			self._OnFight.SetActive((self.Hero.IsActive && self.Hero.CanUpStar()) & isFight);
		}

		private static void SetHeroBaseUI(this UICommonHeroCard self, HeroCommonInfo info, string roleName)
		{
			HeroConfig heroConfig = ConfigSingleton<HeroConfigCategory>.Instance.Get(info.ConfigId);
			self._RawIcon.SetRawTexture(UIHeroHelper.GetSmallIcon(info)).Coroutine();
			self._ImgTag.SetSprite($"hero_frame_job_{heroConfig.Job}").Coroutine();
			self._BgImg.SetRawTexture($"ui_common_card_bg_big_{heroConfig.HeroQuality}").Coroutine();
			self._RawBottom.SetRawTexture($"ui_common_card_mask_big_{heroConfig.HeroQuality}").Coroutine();
			self._ImgTagBg.SetSprite($"ui_common_card_job_line_{heroConfig.HeroQuality}").Coroutine();
			self._TxtValue.SetText((heroConfig.Type == 1) ? roleName : heroConfig.HeroName);
		}

		private static void SetHeroBaseUI(UICommonHeroCard self, Hero hero)
		{
			HeroConfig config = hero.Config;
			self._RawIcon.SetRawTexture($"uitex_hero_image_{hero.ConfigId}").Coroutine();
