		public static void SetItem(this UICommonIcon self, int configId, long nums = 0L)
		{
			self.SetSimpleItem(configId, nums);
			self.ShowEffect();
		}

		public static void SetSimpleItem(this UICommonIcon self, int configId, long nums = 0L)
		{
			//IL_0088: Unknown result type (might be due to invalid IL or missing references)
			ItemConfig itemConfig = ET.ItemHelper.GetItemConfig(configId);
			if (itemConfig == null)
			{
				Log.Error($"物品配置不存在！{configId}");
				return;
			}
			if (self.ConfigId != configId)
			{
				self.ConfigId = configId;
				self.SetIcon($"uitex_icon_item_{itemConfig.Icon}");
				self._ImageBg.SetSprite($"ui_common_frame_0{itemConfig.Quality}").Coroutine();
			}
			self._TextNums.GameObject.GetComponent<SuperOutline>().effectColor = UIHelper.GetQualityColor(itemConfig.Quality);
			self.Nums = nums;
			UIObject textNums = self._TextNums;
			string str = ((nums >= 10000) ? ((nums < 100000000) ? $"{(double)nums / 10000.0:0.##}万" : $"{(double)nums / 100000000.0:0.##}亿") : ((nums > 1) ? nums.ToString() : ""));
			textNums.SetText(str);
			self.SetEquipType();
			self.SetHeroType();
			self.SetJewelryType();
		}

		private static void ShowEffect(this UICommonIcon self)
		{
			//IL_002a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0030: Unknown result type (might be due to invalid IL or missing references)
			//IL_0033: Unknown result type (might be due to invalid IL or missing references)
			//IL_0039: Unknown result type (might be due to invalid IL or missing references)
			string qualityEffect = UIEffectHelper.GetQualityEffect(ET.ItemHelper.GetItemConfig(self.ConfigId).Quality);
			self._EffectRoot.ClearAllEffects();
			self._EffectRoot.PlayEffect(qualityEffect);
		}

		private static void SetEquipType(this UICommonIcon self)
		{
			if (ET.ItemHelper.GetItemConfig(self.ConfigId) is EquipConfig equipConfig)
			{
				self._JobImage.SetActive(active: true);
				self._LevelText.SetActive(active: true);
				self._JobImage.SetSprite($"ui_herocard_job_{equipConfig.Job}").Coroutine();
				self._LevelText.SetText($"{equipConfig.Level}级");
			}
			else
			{
				self._JobImage.SetActive(active: false);
				self._LevelText.SetActive(active: false);
			}
		}

		private static void SetHeroType(this UICommonIcon self)
		{
			ItemConfig itemConfig = ET.ItemHelper.GetItemConfig(self.ConfigId);
			if (itemConfig.Type != 3)
			{
				self._ImageHeroQuality.SetActive(active: false);
			}
			self._IsCore.SetActive(active: false);
			if (itemConfig.UseEff == 7)
			{
				HeroConfig heroConfig = ConfigSingleton<HeroConfigCategory>.Instance.Get(itemConfig.Id);
				self._IsCore.SetActive(heroConfig.IsCore);
			}
			self._ImageHeroQuality.SetActive(active: true);
			self._ImageHeroQuality.SetSprite($"hero_frame_frags_bg_{itemConfig.Quality}").Coroutine();
		}

		public static void SetJewelry(this UICommonIcon self, int jewelryId, int showType = 0)
		{
			self.SetItem(jewelryId, 1L);
			UIObject self2 = ((ET.ItemHelper.GetItemConfig(self.ConfigId).Type == 9) ? self._WeaponJewelry : self._NormalJewelry);
			self2.Find("JewelryBg1").SetActive(showType == 1);
			self2.Find("JewelryBg2").SetActive(showType == 2);
		}

		private static void SetJewelryType(this UICommonIcon self)
		{
			ItemConfig itemConfig = ET.ItemHelper.GetItemConfig(self.ConfigId);
			UIObject jewelry = self._Jewelry;
			int type = itemConfig.Type;
			jewelry.SetActive(type == 8 || type == 9);
			self._WeaponJewelry.SetActive(itemConfig.Type == 9);
			self._NormalJewelry.SetActive(itemConfig.Type == 8);
		}

		public static void SetIcon(this UICommonIcon self, string icon)
		{
			self._ImageIcon.SetActive(active: true);
			self._ImageIcon.SetTexture(icon, nativeSize: true, show: false).Coroutine();
		}

		public static void SetNums(this UICommonIcon self, int nums)
		{
			self.Nums = nums;
			self._TextNums.SetText((self.Nums > 1) ? self.Nums.ToString() : string.Empty);
		}

		public static void SetGrayBg(this UICommonIcon self, bool show)
		{
			self._ImageGrayBg.SetActive(show);
		}

		public static void Clear(this UICommonIcon self)
		{
			self.ConfigId = 0;
			self.Nums = 0L;
			self._JobImage.SetActive(active: false);
			self._LevelText.SetActive(active: false);
			self._TextNums.SetText("");
			self._ImageBg.SetSprite("ui_common_frame_01").Coroutine();
			self._ImageIcon.SetActive(active: false);
			self._EffectRoot.ClearAllEffects();
		}
	}
