		public static void SetData(this UICommonItemLayout self, ET.ConfigBeans.Item[] rewards)
		{
			using ItemList itemList = ItemList.Create();
			foreach (ET.ConfigBeans.Item item in rewards)
			{
				itemList.Add(new ItemStruct
				{
					ConfigId = item.Id,
					Nums = item.Nums
				});
			}
			self.SetData(itemList);
		}

		public static void ShowDrop(this UICommonItemLayout self, int dropId)
		{
			using ItemList itemList = ItemList.Create();
			if (ConfigSingleton<DropShowConfigCategory>.Instance.Contain(dropId))
			{
				DropItem[] items = ConfigSingleton<DropShowConfigCategory>.Instance.Get(dropId).Items;
				foreach (DropItem dropItem in items)
				{
					itemList.Add(new ItemStruct
					{
						ConfigId = dropItem.Id,
						Nums = dropItem.Nums
					});
				}
			}
			self.SetData(itemList);
		}

		public static void SetData(this UICommonItemLayout self, Dictionary<int, long> rewards)
		{
			using ItemList itemList = ItemList.Create();
			foreach (KeyValuePair<int, long> reward in rewards)
			{
				itemList.Add(new ItemStruct
				{
					ConfigId = reward.Key,
					Nums = reward.Value
				});
			}
			self.SetData(itemList);
		}

		public static void SetData(this UICommonItemLayout self, ItemList itemList)
		{
			self._UICommonItem.UIObject.CloneAll(itemList.Count, delegate(int i, UIObject uiObject)
			{
				((Entity)uiObject).GetComponent<UICommonItem>().SetItem(itemList[i].ConfigId, itemList[i].Nums);
			}).Coroutine();
		}
	}
