			int count = 0;
			switch (itemConfig.Type)
			{
			case 10:
			{
				BeastConfig beastConfig = ConfigSingleton<BeastConfigCategory>.Instance.Get(itemConfig.UseEffParams.GetValueOrDefault(0, 0));
