			self._TopStar.CloneAll(count, null).Coroutine();
			self._IsCore.SetActive(active: false);
			if (itemConfig.UseEff == 7)
			{
				HeroConfig heroConfig = ConfigSingleton<HeroConfigCategory>.Instance.Get(itemConfig.Id);
				self._IsCore.SetActive(heroConfig.IsCore);
			}
		}

