		private static void OnClickAdd(this UICommonMoneyItem self)
		{
			if (self.Config == null)
			{
				return;
			}
			if (self.Config.JumpParam == null)
			{
				int[] obtainWays = self.Config.ObtainWays;
				if (obtainWays != null && obtainWays.Length != 0)
				{
					long itemNumsByItemId = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().GetItemNumsByItemId(self.Config.Id);
					UICommonHelper.ShowItemTip(new ItemStruct
					{
						ConfigId = self.Config.Id,
						Nums = itemNumsByItemId
					});
				}
				else
				{
					Log.Error("没有配置对应跳转参数! 也没有获取途径！");
				}
			}
			else
			{
				UIJumpHelper.To(self.Config.JumpParam.Id).Coroutine();
			}
		}

		public static void SetNums(this UICommonMoneyItem self, long nums)
		{
			if (self.Config != null)
			{
				if (self.Config.Id == 25)
				{
					int maxTicket = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<RiverMapModule>().Config.MaxTicket;
					self._TxtNum.SetText(TextHelper.FormatItemNums(nums) + "/" + maxTicket);
				}
				else
				{
					self._TxtNum.SetText(TextHelper.FormatItemNums(nums));
				}
				self.RefreshTimer();
			}
		}

		public static void SetEventRefreshEnable(this UICommonMoneyItem self, bool enable)
		{
			self.IsRefreshEnable = enable;
		}

		public static void RefreshNums(this UICommonMoneyItem self)
		{
			long itemNumsByItemId = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().GetItemNumsByItemId(self.Config.Id);
			self.SetNums(itemNumsByItemId);
		}

		public static void SetData(this UICommonMoneyItem self, int itemId)
		{
			self.Config = ConfigSingleton<ItemConfigCategory>.Instance.GetFromAll(itemId);
			self._ImgIcon.SetTexture($"uitex_icon_item_{UIItemHelper.GetItemIconIdByItemId(itemId)}").Coroutine();
			self._BtnAdd.SetActive(self.Config.ObtainWays != null && self.Config.ObtainWays.Length != 0);
			self.RefreshNums();
		}

		private static void RefreshTimer(this UICommonMoneyItem self)
		{
			self.ClearTimer();
			if (self.Config != null)
			{
				long leftTime = 0L;
				string empty = string.Empty;
				if (self.Config.Id == 25)
				{
					leftTime = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<RiverMapModule>().GetTicketRefreshTime();
				}
				self.SetTimeText(empty, leftTime);
			}
		}

		private static void SetTimeText(this UICommonMoneyItem self, string content, long leftTime)
		{
			if (leftTime <= 0)
			{
				self.ClearTimer();
				return;
			}
			self._TxtTime.SetText((content == string.Empty) ? TextHelper.TimeFormatHourMinSec(leftTime) : string.Format(content, TextHelper.TimeFormatHourMinSec(leftTime)));
			self.Timer = self.NewTimer(1000L, delegate
			{
				if (leftTime <= 0)
				{
					self._TxtTime.SetText(string.Empty);
					self.ClearTimer();
				}
				else
				{
					leftTime -= 1000L;
					self._TxtTime.SetText((content == string.Empty) ? TextHelper.TimeFormatHourMinSec(leftTime) : string.Format(content, TextHelper.TimeFormatHourMinSec(leftTime)));
				}
			}, repeat: true);
		}

		private static void ClearTimer(this UICommonMoneyItem self)
		{
			if (self.Timer > 0)
			{
				self.RemoveTimer(ref self.Timer);
			}
		}
	}
