		private static void UpdateView(this UICommonShowDecoratePanel self)
		{
			bool active = false;
			((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>();
			if (self.ItemId > 8000 && self.ItemId < 9000)
			{
				((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<HeroModule>();
				self._DecorateBg.SetTexture("ui_grxx_scene_02").Coroutine();
			}
			self._HaveTag.SetActive(active);
		}
	}
