		{
			protected override void Awake(UICommonSimpleRankItem self)
			{
				UIObject uIObject = self.UIObject;
				_ = self.UIObject.Transform;
				self._NumSp = uIObject.Find("_NumSp");
				self._NumText = uIObject.Find("_NumText");
				self._PlayerName = uIObject.Find("_PlayerName");
				UIEventDispatcherComponent.Instance.Register(self);
			}
		}

		private class __DestroySystem : DestroySystem<UICommonSimpleRankItem>
		{
			protected override void Destroy(UICommonSimpleRankItem self)
			{
				UIEventDispatcherComponent.Instance.UnRegister(self);
				self._NumSp = null;
				self._NumText = null;
				self._PlayerName = null;
				((DisposeObject)self.UIObject).Dispose();
			}
		}

		public static void SetData(this UICommonSimpleRankItem self, RankInfo rankInfo)
		{
			string text = string.Empty;
			switch (rankInfo.RankNo)
			{
			case 1:
				text = "ui_wjly_sign_01";
				break;
			case 2:
				text = "ui_wjly_sign_02";
				break;
			case 3:
				text = "ui_wjly_sign_03";
				break;
			}
			bool flag = string.IsNullOrEmpty(text);
			self._NumText.SetActive(flag);
			self._NumSp.SetActive(!flag);
			if (flag)
			{
				self._NumText.SetText($"{rankInfo.RankNo}");
			}
			else
			{
				self._NumSp.SetSprite(text).Coroutine();
			}
			if (rankInfo.RankNo == 0)
			{
				self._NumText.SetText("无");
				self._PlayerName.SetText("<color=white>" + rankInfo.Name + "</color>");
			}
			else
			{
				self._PlayerName.SetText($"<color=white>{rankInfo.Name}</color>\n<color=#5dfa49>第{rankInfo.Value}层</color>");
			}
		}
	}
