			self.CellUpdateMySelfItem = null;
			self.OnClickRank = null;
		}

		private static void OnCellUpdate(this UICommonSimpleRank self, UIScrollListCell cell)
		{
			self.CellUpdateCallback?.Invoke(cell);
			int index = cell.Index;
			if (self.rankInfoList.Count == index + 1)
			{
				self.CellUpdateMySelfItem?.Invoke(self._SelfNode);
			}
		}

		public static void SetData(this UICommonSimpleRank self, List<RankInfo> rankInfos)
		{
			self.rankInfoList = rankInfos;
			self._RankList.SetData(self.rankInfoList.Count);
			self._EmptyText.SetActive(rankInfos.Count == 0);
			self._SelfNode.SetActive(rankInfos.Count != 0);
		}

		public static void AddCellUpdate(this UICommonSimpleRank self, Action<UIScrollListCell> cellUpdate)
		{
			self.CellUpdateCallback = (Action<UIScrollListCell>)Delegate.Combine(self.CellUpdateCallback, cellUpdate);
		}

		public static void AddCellMySelfItem(this UICommonSimpleRank self, Action<UIObject> cellUpdate)
		{
			self.CellUpdateMySelfItem = (Action<UIObject>)Delegate.Combine(self.CellUpdateMySelfItem, cellUpdate);
		}

		public static void AddOnClickRank(this UICommonSimpleRank self, Action callback)
		{
			self.OnClickRank = (Action)Delegate.Combine(self.OnClickRank, callback);
		}

		private static void OnClickRankButton(this UICommonSimpleRank self)
		{
			self.OnClickRank?.Invoke();
		}
	}
