		{
		}

		[UIMethod]
		public static void OnShow(UICommonSkillTip self, (UIObject parentUIObject, int skillId) showArgs)
		{
			((Entity)self).AddComponent<UICommonAdapter, UIObject, UIObject>(showArgs.parentUIObject, self.UIObject, false);
			self.SetData(showArgs.skillId);
		}

		private static void SetData(this UICommonSkillTip self, int skillId, bool isLock = true)
		{
			SkillLevel skillLevel = new SkillLevel(skillId);
			if (skillLevel.IsPassiveSkill)
			{
				if (ConfigSingleton<PassiveSkillLevelConfigCategory>.Instance.Contain(skillId))
				{
					PassiveSkillLevelConfig passiveSkillLevelConfig = ConfigSingleton<PassiveSkillLevelConfigCategory>.Instance.Get(skillId);
					self._SkillName.SetText(passiveSkillLevelConfig.Name);
					int[] array = passiveSkillLevelConfig.SkillTag ?? new int[0];
					self._SkillTag1.SetActive(array.Length >= 2);
					self._SkillTag2.SetActive(array.Length >= 2);
					if (array.Length != 0 && ConfigSingleton<SkillTagConfigCategory>.Instance.Contain(array[0]))
					{
						SkillTagConfig skillTagConfig = ConfigSingleton<SkillTagConfigCategory>.Instance.Get(array[0]);
						self._SkillTag1.SetRawTexture(skillTagConfig.Icon).Coroutine();
						self._SkillTag1Text.SetText(skillTagConfig.Name);
					}
					if (array.Length > 1 && ConfigSingleton<SkillTagConfigCategory>.Instance.Contain(array[1]))
					{
						SkillTagConfig skillTagConfig = ConfigSingleton<SkillTagConfigCategory>.Instance.Get(array[1]);
						self._SkillTag2.SetRawTexture(skillTagConfig.Icon).Coroutine();
						self._SkillTag2Text.SetText(skillTagConfig.Name);
					}
					self._TimeImage.SetActive(active: false);
					self._SkillDesc.SetText(passiveSkillLevelConfig.Desc);
				}
			}
			else if (skillLevel.IsActiveSkill && ConfigSingleton<ActiveSkillLevelConfigCategory>.Instance.Contain(skillId))
			{
				ActiveSkillLevelConfig activeSkillLevelConfig = ConfigSingleton<ActiveSkillLevelConfigCategory>.Instance.Get(skillId);
				self._SkillName.SetText(activeSkillLevelConfig.Name);
				int[] array2 = activeSkillLevelConfig.SkillTag ?? new int[0];
				self._SkillTag1.SetActive(array2.Length >= 2);
				self._SkillTag2.SetActive(array2.Length >= 2);
				if (array2.Length != 0 && ConfigSingleton<SkillTagConfigCategory>.Instance.Contain(array2[0]))
				{
					SkillTagConfig skillTagConfig2 = ConfigSingleton<SkillTagConfigCategory>.Instance.Get(array2[0]);
					self._SkillTag1.SetRawTexture(skillTagConfig2.Icon).Coroutine();
					self._SkillTag1Text.SetText(skillTagConfig2.Name);
				}
				if (array2.Length > 1 && ConfigSingleton<SkillTagConfigCategory>.Instance.Contain(array2[1]))
				{
					SkillTagConfig skillTagConfig2 = ConfigSingleton<SkillTagConfigCategory>.Instance.Get(array2[1]);
					self._SkillTag2.SetRawTexture(skillTagConfig2.Icon).Coroutine();
					self._SkillTag2Text.SetText(skillTagConfig2.Name);
				}
				self._SkillDesc.SetText(activeSkillLevelConfig.Desc);
				self._TimeImage.SetActive(active: true);
				self._TimeText.SetText(Language.Format(2, 120, activeSkillLevelConfig.CD / 1000));
			}
		}
	}
