	public static class UIItemHelper
	{
		public static string GetItemNameWithColor(int itemId)
		{
			ItemConfig itemConfig = ET.ItemHelper.GetItemConfig(itemId);
			return TextHelper.FormatQuality(itemConfig.Name, itemConfig.Quality, null);
		}

		public static string ItemNumsFormat(long nums)
		{
			if (nums < 100000)
			{
				return nums.ToString();
			}
			if (nums < 1000000000)
			{
				return $"{nums / 10000}万";
			}
			return $"{nums / 100000000}亿";
		}

		public static int GetItemTabTypeByItemId(int itemId)
		{
			int result = 0;
			if (ItemHelper.CheckGemStoneConfigContainKey(itemId))
			{
				result = ItemHelper.GetGemStoneConfigByItemId(itemId)?.TabType ?? 0;
			}
			else if (ItemHelper.CheckEquipConfigContainKey(itemId))
			{
				result = ItemHelper.GetEquipConfigByItemId(itemId)?.TabType ?? 0;
			}
			else if (ItemHelper.CheckItemConfigContainKey(itemId))
			{
				result = ItemHelper.GetItemConfigByItemId(itemId)?.TabType ?? 0;
			}
			return result;
		}

		public static bool CanComposable(BagItemInfo bagItemInfo)
		{
			ItemConfig itemConfigByItemId = ItemHelper.GetItemConfigByItemId(bagItemInfo.ConfigId);
			if (itemConfigByItemId == null)
			{
				return false;
			}
			if (itemConfigByItemId.IsComposable)
			{
				return bagItemInfo.Nums >= itemConfigByItemId.ComposeCost;
			}
			return false;
		}

		public static int GetItemIconIdByItemId(int configId)
		{
			return ET.ItemHelper.GetItemConfig(configId)?.Icon ?? 0;
		}

		public static string GetIcon(int configId)
		{
			int num = GetItemIconIdByItemId(configId);
			if (num == 0)
			{
				num = 1;
			}
			return $"uitex_icon_item_{num}";
		}

		public static bool IsShowDetail(this ItemConfig config)
		{
			int useEff = config.UseEff;
			if (useEff == 3 || useEff == 1)
			{
				int valueOrDefault = config.UseEffParams.GetValueOrDefault(0, 0);
				return ConfigSingleton<DropShowConfigCategory>.Instance.Contain(valueOrDefault);
			}
			return false;
		}
	}
