		private static void SetupTag(this UIMonsterSkillTips self, UIObject uiTagBg, UIObject uiTagText, int tagId)
		{
			SkillTagConfig skillTagConfig = ConfigSingleton<SkillTagConfigCategory>.Instance.Get(tagId);
			string spriteBySkillTag = SkillHelper.GetSpriteBySkillTag(skillTagConfig.Type);
			uiTagBg.SetSprite(spriteBySkillTag).Coroutine();
			uiTagText.SetText(skillTagConfig.Name);
		}

		[UIMethod]
		public static void OnAwake(this UIMonsterSkillTips self)
		{
			((Entity)(object)self).EnableDataBind();
			self._UICommonPower.UIObject.SetActive(active: false);
			self.InitBind();
		}

		private static void InitBind(this UIMonsterSkillTips self)
		{
			((Entity)(object)self).BindData("MonsterId", delegate(int _, int newValue)
			{
				MonsterConfig monsterConfig = ConfigSingleton<MonsterConfigCategory>.Instance.Get(newValue);
				UnitConfig unitConfig = ConfigSingleton<UnitConfigCategory>.Instance.Get(monsterConfig.UnitId);
				self._Icon.SetRawTexture($"uitex_unit_icon_{unitConfig.Icon}").Coroutine();
				self._BossName.SetText(unitConfig.Name);
				self._BossLevel.SetText(Language.Format(2, 224, monsterConfig.Level));
				self.ShowSkillList(unitConfig.Skills);
			});
			((Entity)(object)self).BindData("SkillLevel", delegate(SkillLevel _, SkillLevel newValue)
			{
				string name;
				string desc;
				int[] skillTag;
				if (newValue.IsPassiveSkill)
				{
					PassiveSkillLevelConfig passiveSkillLevelConfig = ConfigSingleton<PassiveSkillLevelConfigCategory>.Instance.Get(newValue.SkillLevelId);
					name = passiveSkillLevelConfig.Name;
					desc = passiveSkillLevelConfig.Desc;
					skillTag = passiveSkillLevelConfig.SkillTag;
					self._ActiveSkill.SetActive(active: false);
					self._PassiveSkill.SetActive(active: true);
				}
				else
				{
					ActiveSkillLevelConfig activeSkillLevelConfig = ConfigSingleton<ActiveSkillLevelConfigCategory>.Instance.Get(newValue.SkillLevelId);
					name = activeSkillLevelConfig.Name;
					desc = activeSkillLevelConfig.Desc;
					skillTag = activeSkillLevelConfig.SkillTag;
					self._ActiveSkill.SetActive(active: true);
					self._PassiveSkill.SetActive(active: false);
					self._TimeText.SetText(Language.Format(2, 298, ((float)activeSkillLevelConfig.CD / 1000f).ToString("0.##")));
				}
				self._BossSkillName.SetText(name);
				self._SkillDesText.SetText(desc);
				if (skillTag != null && skillTag.Length >= 1)
				{
					self._SkillTab1.SetActive(active: true);
					self.SetupTag(self._SkillTab1, self._SkillTab1Text, skillTag[0]);
				}
				else
				{
					self._SkillTab1.SetActive(active: false);
				}
				if (skillTag != null && skillTag.Length >= 2)
				{
					self._SkillTab2.SetActive(active: true);
					self.SetupTag(self._SkillTab2, self._SkillTab2Text, skillTag[1]);
				}
				else
				{
					self._SkillTab2.SetActive(active: false);
				}
			});
		}

		private static void ShowSkillList(this UIMonsterSkillTips self, int[] skills)
		{
			if (skills == null || skills.Length == 0)
			{
				self._SkillList.SetActive(active: false);
				return;
			}
			List<SkillLevel> list = new List<SkillLevel>();
			foreach (int skillLevelId in skills)
			{
				list.Add(new SkillLevel(skillLevelId));
			}
			list.Sort((SkillLevel a, SkillLevel b) => a.SkillIndex - b.SkillIndex);
			self.SelectItem = 0;
			self.SkillLevel = list[0];
			self._SkillList.SetActive(active: true);
			self._UICommonMonsterSkillItem.UIObject.CloneAll(list, delegate(int index, SkillLevel skillLevel, UIObject item)
			{
				UICommonMonsterSkillItem skillItem = ((Entity)item).GetComponent<UICommonMonsterSkillItem>();
				skillItem.BindSelected((Entity)(object)self, "SelectItem", delegate(int _, int newValue)
				{
					skillItem.Selected = newValue == index;
				}, () => self.SelectItem);
				skillItem.SetData(skillLevel);
				skillItem.SetClickCallback(delegate
				{
					self.OnClickItem(index, skillLevel);
				});
			}).Coroutine();
		}

		private static void OnClickItem(this UIMonsterSkillTips self, int index, SkillLevel skillLevel)
		{
			self.SelectItem = index;
			self.SkillLevel = skillLevel;
		}

		public static void SetData(this UIMonsterSkillTips self, int monsterId)
		{
			self.MonsterId = monsterId;
		}
	}
