		[UIMethod]
		private static void OnAwake(this UIViewFormationTeamItem self)
		{
			self._UIScrollList.Handler.onCreate += self.OnCellCreate;
			self._UIScrollList.Handler.onUpdate += self.OnCellUpdate;
			self._UIScrollList.SetPrefabNameAction(self.GetCellPrefabName);
			self._UIScrollList.SpaceY = -5f;
			self._UIScrollList.SetData(0);
		}

		private static void OnCellCreate(this UIViewFormationTeamItem self, UIScrollListCell cell)
		{
			if (cell.Index >= self.Heros.Count)
			{
				((Entity)cell.UIObject).GetComponent<UICommonAddBtn>().AddClickHandler(self.ModifyFormation);
			}
		}

		private static void ModifyFormation(this UIViewFormationTeamItem self)
		{
			self.OnClickAddBtn?.Invoke();
		}

		private static string GetCellPrefabName(this UIViewFormationTeamItem self, int index)
		{
			if (index < self.Heros.Count)
			{
				return "UIViewFormationHeroHead";
			}
			return "UICommonAddBtn";
		}

		private static void OnCellUpdate(this UIViewFormationTeamItem self, UIScrollListCell cell)
		{
			int index = cell.Index;
			if (index < self.Heros.Count)
			{
				Hero item = self.Heros[index].Item2;
				((Entity)cell.UIObject).GetComponent<UIViewFormationHeroHead>().SetData(item);
			}
		}

		public static void SetAddBtnCallBack(this UIViewFormationTeamItem self, Action callBack)
		{
			self.OnClickAddBtn = callBack;
		}

		public static void RefreshFormation(this UIViewFormationTeamItem self)
		{
			Player player = ((Entity)(object)self).LocalPlayer();
			Formation formation = ((Entity)player).GetComponent<FormationModule>().GetFormation(self.FormationId);
			self._UICommonPower.SetPower(formation.GetPower());
			self.Heros.Clear();
			foreach (var (item, heroId) in formation.PosHero)
			{
				Hero heroByUid = player.GetHeroByUid(heroId);
				if (heroByUid != null && heroByUid.IsActive)
				{
					self.Heros.Add((item, heroByUid));
				}
			}
			self.Heros.Sort(((int, Hero) a, (int, Hero) b) => a.Item1 - b.Item1);
			FormationConfig formationConfig = ConfigSingleton<FormationConfigCategory>.Instance.Get(self.FormationId);
			self._UIScrollList.SetData(0);
			self._UIScrollList.SetData(formationConfig.Max);
		}

		public static void SetData(this UIViewFormationTeamItem self, string teamName, int formationId)
		{
			self.FormationId = formationId;
			self._TeamName.SetText(teamName);
			self.RefreshFormation();
		}
	}
	[RedPointHandler(RedPointType.Dup_Daily)]
	public class DailyDupRedPointHandler : ARedPointHandler
	{
		public override int GetCount(Scene scene, params int[] parameters)
		{
			Player player = ((Entity)scene).GetComponent<LocalPlayerComponent>().Player;
			if (player == null)
			{
				return 0;
			}
			foreach (var (num2, _) in ConfigSingleton<DailyDupConfigCategory>.Instance.GetAll())
			{
				DailyDupModule component = ((Entity)player).GetComponent<DailyDupModule>();
				component.DailyDupCheckDict.TryGetValue(num2, out var value);
				if (value <= 0 && component.IsCanChallenge(num2) == 0)
				{
					return 1;
				}
			}
			return 0;
		}
	}
