		private static void UpdateAutoChallengeButton(this UIDailyDupPanel self)
		{
			FuncConfig funcConfig = ConfigSingleton<FuncConfigCategory>.Instance.Get(4103);
			bool flag = ((Entity)(object)self).LocalPlayer().CheckAllConds(funcConfig.OpenConds);
			self._AutoChallengeBg.SetActive(flag);
			if (!flag)
			{
				return;
			}
			bool active = false;
			DailyDupModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<DailyDupModule>();
			foreach (int dupType in self.DupTypes)
			{
				int dailyDupState = component.GetDailyDupState(dupType);
