				if (self._ChallengeNextButton.IsActive())
				{
					self._Power.UIObject.SetActive(active: true);
					long power = ((Entity)(object)self).LocalPlayer().GetPower();
					long recPower = ConfigSingleton<GuildDupStarLevelConfigCategory>.Instance.Get(self.Result.Dup.Level + 1).RecPower;
					self._Power.SetPowerWithType(recPower, (power >= recPower) ? 1 : 2);
				}
				return;
			case DupType.RiverMapBox:
				self._Power.UIObject.SetActive(active: false);
				self._ChallengeNextButton.SetActive(active: false);
