		private static async void OnMopUpButtonClick(this UIDailyMopUpItem self)
		{
			DailyDupModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<DailyDupModule>();
			int currentLevel = component.GetCurrentLevel(self.DupType);
			if (currentLevel == 0)
			{
				return;
			}
			switch (component.GetDailyDupState((int)self.DupType))
			{
			case 1:
				if (component.HasExceedLevelPower(self.DupType, currentLevel + 1))
				{
					DailyDupLevelConfig dailyDupLevelConfig = ConfigSingleton<DailyDupLevelConfigCategory>.Instance.Get((int)self.DupType * 10000 + currentLevel + 1);
					if (UICommonHelper.IsVailTodayLocalData("DailyDup_Challenge_Tips_AllType"))
					{
						OkAction();
						break;
					}
					UICommonHelper.ShowConfirmPanel(new ConfirmPanelOptions
					{
						Message = "当前战力已经超过" + self.DupConfig.Name + "：" + dailyDupLevelConfig.Name + ",是否继续扫荡",
						OkAction = OkAction,
						ConfirmKey = $"DailyDup_Challenge_Tips_Type{(int)self.DupType}",
						NoConfirmTillTime = TimeHelper.EndTimeOfDay(TimeHelper.Now(), 18000000L)
					});
				}
				else
				{
					UIGameMsgHelper.FloatMsgByError(await ((Entity)(object)self).LocalPlayer().DupMopUp(self.DupType));
				}
				break;
			case 2:
			case 3:
			{
				DailyDupConfig dailyDupConfig = ConfigSingleton<DailyDupConfigCategory>.Instance.Get((int)self.DupType);
				UIPrivilegeHelper.BuyCount(SceneHelper.DomainScene((Entity)(object)self), PrivilegeHelper.GetPrivilegeBuy(self.DupType), dailyDupConfig.PriceType, delegate
				{
					UIObject.FindUIObjectOfType<UIDailyMopUpPanel>()?.UpdateView();
				});
				break;
			}
			}
			async void OkAction()
			{
				UIGameMsgHelper.FloatMsgByError(await ((Entity)(object)self).LocalPlayer().DupMopUp(self.DupType));
			}
		}
	}
