		public static async void OnClickMopUpOkAction(this UIDailyMopUpPanel self)
		{
			if (self.DupFightIds.Count == 0)
			{
				return;
			}
			object obj = default(object);
			foreach (KeyValuePair<int, int> item in self.DupCostDic)
			{
				int key = item.Key;
				int value = item.Value;
				if (((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().GetItemNumsByItemId(key) < value)
				{
					ItemConfig costItemConfig = ConfigSingleton<ItemConfigCategory>.Instance.Get(key);
					ETTask val = Singleton<TimerComponent>.Instance.WaitAsync(100L, (ETCancellationToken)null).GetAwaiter();
					if (!val.IsCompleted)
					{
						await val;
						val = (ETTask)obj;
					}
					val.GetResult();
					UICommonHelper.ShowConfirmPanel(new ConfirmPanelOptions
					{
						Message = Language.Format(2, 319, costItemConfig.Name),
						OkAction = delegate
						{
							UIManager.Instance.Show<UIActivityPanel, (int, int)>((27, 14001)).Coroutine();
						},
						ConfirmKey = "daily_mop_up_buy",
						NoConfirmTillTime = TimeHelper.EndTimeOfDay(TimeHelper.Now(), 18000000L)
					});
					return;
				}
			}
			List<DupMopUpInfo> list = new List<DupMopUpInfo>(self.DupFightIds.Count);
			foreach (int dupFightId in self.DupFightIds)
			{
				int currentLevel = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<DailyDupModule>().GetCurrentLevel((DupType)dupFightId);
				if (currentLevel != 0)
				{
					list.Add(new DupMopUpInfo
					{
						dupType = (DupType)dupFightId,
						args = new DupMopUpArgs
						{
							Level = currentLevel,
							Nums = 1
						}
					});
				}
			}
			int num = await ((Entity)(object)self).LocalPlayer().OneClickMopUpDup(list);
			if (num == 0)
			{
				self.UpdateView();
			}
			UIGameMsgHelper.FloatMsgByError(num);
		}

		private static void OnMopUpButtonClick(this UIDailyMopUpPanel self)
		{
			self.DupBuyIds.Clear();
			self.DupFightIds.Clear();
			self.DupCostDic.Clear();
			bool flag = false;
			bool flag2 = false;
			DailyDupModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<DailyDupModule>();
			foreach (int dupType in self.DupTypes)
			{
				int dailyDupState = component.GetDailyDupState(dupType);
				if (dailyDupState == 1)
				{
					flag = true;
					self.DupFightIds.Add(dupType);
				}
				if (dailyDupState == 2)
				{
					flag2 = true;
					self.DupBuyIds.Add(dupType);
					self.DupFightIds.Add(dupType);
				}
			}
			if (flag)
			{
				self.DupFightIds = self.DupFightIds.Except(self.DupBuyIds).ToList();
				flag2 = false;
			}
			if (!(flag | flag2))
			{
				return;
			}
			if (flag2)
			{
				StringBuilder stringBuilder = new StringBuilder();
				stringBuilder.Append("是否消耗");
				foreach (int dupBuyId in self.DupBuyIds)
				{
					DailyDupConfig dailyDupConfig = ConfigSingleton<DailyDupConfigCategory>.Instance.Get(dupBuyId);
					int privilegeTotalCount = component.GetPrivilegeTotalCount((DupType)dupBuyId);
					int buyedCount = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<PrivilegeModule>().GetBuyedCount(dailyDupConfig.PriceType);
					if (buyedCount < privilegeTotalCount)
					{
						PriceConfig priceConfig = ConfigSingleton<PriceConfigCategory>.Instance.Get(dailyDupConfig.PriceType, buyedCount + 1);
						if (priceConfig.Price != null)
						{
							self.DupCostDic.TryAdd(priceConfig.Price.Id, 0);
							self.DupCostDic[priceConfig.Price.Id] = self.DupCostDic.GetValue(priceConfig.Price.Id) + priceConfig.Price.Nums;
						}
					}
				}
				foreach (KeyValuePair<int, int> item in self.DupCostDic)
				{
					int key = item.Key;
					int value = item.Value;
					ItemConfig itemConfig = ConfigSingleton<ItemConfigCategory>.Instance.Get(key);
					stringBuilder.AppendFormat($"<color=#3f7745>{value}</color>{itemConfig.Name}", Array.Empty<object>());
				}
				stringBuilder.AppendLine("，购买并扫荡1次");
				for (int i = 0; i < self.DupBuyIds.Count; i++)
				{
					int id = self.DupBuyIds[i];
					DailyDupConfig dailyDupConfig2 = ConfigSingleton<DailyDupConfigCategory>.Instance.Get(id);
					stringBuilder.Append((i != self.DupBuyIds.Count - 1) ? (dailyDupConfig2.Name + "、") : (dailyDupConfig2.Name + "。"));
				}
				UICommonHelper.ShowConfirmPanel(new ConfirmPanelOptions
				{
					Message = stringBuilder.ToString(),
					OkAction = self.OnClickMopUpOkAction,
					ConfirmKey = "DailyDup_Buy_Count_Tips",
					NoConfirmTillTime = TimeHelper.EndTimeOfDay(TimeHelper.Now(), 18000000L)
				});
				return;
			}
			StringBuilder stringBuilder2 = new StringBuilder();
			foreach (int dupFightId in self.DupFightIds)
			{
				int currentLevel = component.GetCurrentLevel((DupType)dupFightId);
				DailyDupConfig dailyDupConfig3 = ConfigSingleton<DailyDupConfigCategory>.Instance.Get(dupFightId);
				if (component.HasExceedLevelPower((DupType)dupFightId, currentLevel + 1) && !UICommonHelper.IsVailTodayLocalData($"DailyDup_Challenge_Tips_Type{dupFightId}"))
				{
					if (stringBuilder2.Length == 0)
					{
						stringBuilder2.Append("当前战力已经超过");
					}
					if (ConfigSingleton<DailyDupLevelConfigCategory>.Instance.Get(dupFightId * 10000 + currentLevel + 1) != null)
					{
						stringBuilder2.AppendFormat("<color=#0db64d>[" + dailyDupConfig3.Name + "] </color>", Array.Empty<object>());
					}
				}
			}
			if (stringBuilder2.Length == 0)
			{
				self.OnClickMopUpOkAction();
				return;
			}
			stringBuilder2.Append("，是否继续扫荡");
			UICommonHelper.ShowConfirmPanel(new ConfirmPanelOptions
			{
				Message = stringBuilder2.ToString(),
				OkAction = self.OnClickMopUpOkAction,
				ConfirmKey = "DailyDup_Challenge_Tips_AllType",
				NoConfirmTillTime = TimeHelper.EndTimeOfDay(TimeHelper.Now(), 18000000L)
			});
		}
	}
