		private static void UpdateView(this UIDestinedTalentSkillPanel self)
		{
			PracticeDestinedTalentConfig practiceDestinedTalentConfig = ConfigSingleton<PracticeDestinedTalentConfigCategory>.Instance.Get(self.ConfigId);
			if (practiceDestinedTalentConfig.Skill <= 0)
			{
				return;
			}
			PracticeModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<PracticeModule>();
			int talentLevel = component.GetTalentLevel(self.ConfigId);
			SkillLevel skillLevel = new SkillLevel(practiceDestinedTalentConfig.Skill, (talentLevel == 0) ? 1 : talentLevel);
			self._SkillText.SetText(skillLevel.Description());
			self._Popup.SetTitle(skillLevel.Name());
			if (component.IsTalentMax(self.ConfigId))
			{
				self._CostText.SetActive(active: false);
				self._MaxLevel.SetActive(active: true);
				self._ActiveButton.SetActive(active: false);
				self._UpButton.SetActive(active: false);
			}
			else
			{
				self._CostText.SetActive(active: true);
				self._MaxLevel.SetActive(active: false);
				self._ActiveButton.SetActive(talentLevel == 0);
				self._UpButton.SetActive(talentLevel != 0);
				int num = component.IsCanUpTalent(practiceDestinedTalentConfig.Id);
				self._ActiveButton.SetGray(num != 0);
				self._UpButton.SetGray(num != 0);
				if (component.IsCondMeet(practiceDestinedTalentConfig.NodeId))
				{
					self._CostText.SetText($"消耗点数：{practiceDestinedTalentConfig.Cost}");
				}
				else if (practiceDestinedTalentConfig.Conds[0] == 1)
				{
					self._CostText.SetText($"前置天命未达到{practiceDestinedTalentConfig.Conds[1]}级({component.GetCondNum(practiceDestinedTalentConfig.NodeId, practiceDestinedTalentConfig.Conds)}/{practiceDestinedTalentConfig.Conds[1]})");
				}
				else if (practiceDestinedTalentConfig.Conds[0] == 2)
				{
					self._CostText.SetText($"前置天命总等级未达到{practiceDestinedTalentConfig.Conds[1]}级({component.GetCondNum(practiceDestinedTalentConfig.NodeId, practiceDestinedTalentConfig.Conds)}/{practiceDestinedTalentConfig.Conds[1]})");
				}
			}
			self._TalentItem.SetData(practiceDestinedTalentConfig);
		}

