		private static void ShowStat(this UIDestinedTalentStatPanel self)
		{
			PracticeDestinedTalentConfig config = ConfigSingleton<PracticeDestinedTalentConfigCategory>.Instance.Get(self.ConfigId);
			self._StatText.SetActive(active: false);
			PracticeModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<PracticeModule>();
			int level = component.GetTalentLevel(self.ConfigId);
			self._StatText.CloneAll(config.Stat.Length, delegate(int i, UIObject o)
			{
				Stat stat = config.Stat[i];
				string text = TextHelper.FormatStatValue(stat.Type, stat.Value * level);
				string text2 = TextHelper.FormatStatValue(stat.Type, stat.Value);
				if (self.IsUp)
				{
					o.SetText(stat.GetName() + ":" + text + "<color=#0db64d>+" + text2 + "</color>");
				}
				else
				{
					o.SetText(stat.GetName() + ":" + text);
				}
			}).Coroutine();
		}

