		public static void SetData(this UIDirectBuyCard self, int _actId, int _typeId)
		{
			self.ActId = _actId;
			self.TypeId = _typeId;
			DirectBuyGiftActivityConfig directBuyGiftActivityConfig = ConfigSingleton<DirectBuyGiftActivityConfigCategory>.Instance.Get(_typeId);
			if (directBuyGiftActivityConfig == null)
			{
				Log.Error("缺少DirectBuyGiftActivityConfig");
				return;
			}
			self._BgImg.SetRawTexture(directBuyGiftActivityConfig.BgImage).Coroutine();
			self._NameText.SetText(directBuyGiftActivityConfig.GitName);
			bool flag = directBuyGiftActivityConfig.LoopDay > 0;
			self._Timer.UIObject.SetActive(flag);
			self.OnSetTimer(flag, directBuyGiftActivityConfig.LoopDay, directBuyGiftActivityConfig.LoopCount);
			self.OnSetGiftConfigData();
		}

		private static void OnSetGiftConfigData(this UIDirectBuyCard self)
		{
			Dictionary<int, DirectBuyGiftConfig> dictionary = ConfigSingleton<DirectBuyGiftConfigCategory>.Instance.GetDictionary(self.TypeId);
			if (dictionary == null)
			{
				Log.Error("缺少DirectBuyGiftConfig,该商品类型是否配置了？" + self.TypeId);
				return;
			}
			ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId);
			if (activityData == null)
			{
				Log.Error("缺少activityData,活动是否没有配全？");
				return;
			}
			DirectBuyGiftModule component = ((Entity)activityData).GetComponent<DirectBuyGiftModule>();
			Dictionary<int, int> giftState = component.GetGiftState();
			Dictionary<int, int> rewardGift = component.GetRewardGift();
			bool flag = false;
			bool flag2 = false;
			foreach (DirectBuyGiftConfig value in dictionary.Values)
			{
				if (rewardGift != null && rewardGift.ContainsKey(value.Id) && rewardGift[value.Id] != 0)
				{
					self.ConfigId = value.Id;
					flag = true;
					break;
				}
			}
			if (flag)
			{
				self._HotImg.SetActive(active: false);
				self._BuyBtn.SetTexture("ui_common_btn_36").Coroutine();
			}
			else
			{
				foreach (DirectBuyGiftConfig value2 in dictionary.Values)
				{
					if (giftState == null)
					{
						self.ConfigId = value2.Id;
						flag2 = true;
						break;
					}
					if (giftState.ContainsKey(value2.Id) && value2.LimitNum - giftState[value2.Id] > 0)
					{
						self.ConfigId = value2.Id;
						flag2 = true;
						break;
					}
					if (!giftState.ContainsKey(value2.Id))
					{
						self.ConfigId = value2.Id;
						flag2 = true;
						break;
					}
				}
				if (flag2)
				{
					self._BuyBtn.SetTexture("ui_common_btn_03").Coroutine();
				}
				else
				{
					self._HotImg.SetActive(active: false);
					self.ConfigId = dictionary.Values.Last().Id;
					self._BuyBtn.SetTexture("ui_common_btn_11").Coroutine();
				}
			}
			DirectBuyGiftActivityConfig directBuyGiftActivityConfig = ConfigSingleton<DirectBuyGiftActivityConfigCategory>.Instance.Get(self.TypeId);
			self._HotImg.SetActive((!flag & flag2) && directBuyGiftActivityConfig.Hot);
			self._BuyBtn.SetRedPoint(RedPointType.Activity, self.ActId, self.ConfigId).Coroutine();
			DirectBuyGiftConfig directBuyGiftConfig = ConfigSingleton<DirectBuyGiftConfigCategory>.Instance.Get(self.ConfigId);
			self._DiscountImg.SetActive(directBuyGiftConfig.Discount > 0);
			self._DiscountText.SetText(directBuyGiftConfig.Discount + "%");
			self._RewardList.SetData(ConfigSingleton<DirectBuyGiftConfigCategory>.Instance.Get(self.ConfigId).Item);
			int num = 0;
			if (giftState != null && giftState.ContainsKey(self.ConfigId))
			{
				num = giftState[self.ConfigId];
			}
			int num2 = directBuyGiftConfig.LimitNum - num;
			if (num2 <= 0)
			{
				num2 = 0;
			}
			if (directBuyGiftActivityConfig.LoopCount > 0)
			{
				self._RestrictText.SetText(Language.Format(4, 751, num2));
			}
			else
			{
				self._RestrictText.SetText(Language.Format(4, 764, num2));
			}
			((Behaviour)self._BuyText.GameObject.GetComponent<SuperOutline>()).enabled = true;
			if (flag)
			{
				self._BuyText.SetText(Language.Get(4, 726));
			}
			else if (flag2)
			{
				PayConfig payConfig = ConfigSingleton<PayConfigCategory>.Instance.Get(directBuyGiftConfig.PayId);
				if (payConfig == null)
				{
					Log.Error("商店id没找到，配置是否错误？");
					return;
				}
				self._BuyText.SetText(Language.Format(4, 744, payConfig.Price / 100));
			}
			else if (self.Superclock)
			{
				self._BuyBtn.SetTexture("ui_common_btn_11").Coroutine();
				PayConfig payConfig2 = ConfigSingleton<PayConfigCategory>.Instance.Get(directBuyGiftConfig.PayId);
				if (payConfig2 == null)
				{
					Log.Error("商店id没找到，配置是否错误？");
					return;
				}
				self._BuyText.SetText(Language.Format(4, 744, payConfig2.Price / 100));
			}
			else
			{
				self._BuyText.SetText(Language.Get(4, 752));
				((Behaviour)self._BuyText.GameObject.GetComponent<SuperOutline>()).enabled = false;
			}
		}

		private static void OnSetTimer(this UIDirectBuyCard self, bool _show, int _day, int _loop)
		{
			self.Superclock = false;
			if (!_show)
			{
				return;
			}
			ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId);
			if (activityData == null)
			{
				return;
			}
			Dictionary<int, long> dictionary = new Dictionary<int, long>();
			for (int i = 1; i <= _loop; i++)
			{
				long value = ((i != 1) ? dictionary[i - 1] : activityData.StartTime);
				dictionary.Add(i, value);
			}
			long num = TimeHelper.ServerNow();
			long num2 = (long)_day * 86400000L;
			for (int j = 1; j <= dictionary.Count; j++)
			{
				if (dictionary.ContainsKey(j) && num >= dictionary[j] && num <= dictionary[j] + num2)
