			self._DiscountImg.SetActive(num2 > 0);
			self._DiscountText.SetText(directBuyGiftConfig.Discount + "%");
			self._AllText.SetText(Language.Format(4, 744, num3));
			bool flag2 = giftState.ContainsKey(num2);
			bool flag3 = giftState.ContainsKey(key);
			self.UIObject.SetRedPoint(RedPointType.Activity, self.ActId).Coroutine();
			self.UIObject.RedPoint.SetOffset(new Vector2(100f, 0f));
			if (!flag3)
			{
				self._TimeText.SetText(Language.Get(4, 763));
			}
			else
			{
