			{
				self._ShopList.SetData(self.Lists.Count);
			}
		}

		private static void OnCellUpdate(this UIDirectBuyEveryDayGiftPanel self, UIScrollListCell cell)
		{
			int index = cell.Index;
			if (index < self.Lists.Count)
			{
				((Entity)cell.UIObject).GetComponent<UIDirectBuyEveryDayGiftCard>().SetData(self.ActId, self.Lists[index]);
			}
		}

		private static void OnSetTimer(this UIDirectBuyEveryDayGiftPanel self)
		{
			self.ShowTime = self.EndTime - TimeHelper.ServerNow();
			if (self.ShowTime <= 0)
			{
				self.InitPanel();
				self._TimeText.SetText("已结束");
				return;
			}
			long num = self.ShowTime / 1000;
			long num2 = num / 86400;
			long num3 = num % 86400 / 3600;
			long num4 = num % 3600 / 60;
			long num5 = num % 60;
			UIHelper.SetText(str: (num2 <= 0) ? $"{num3:D2}:{num4:D2}:{num5:D2}" : string.Format("{0}天 {1:D2}:{2:D2}:{3:D2}", new object[4] { num2, num3, num4, num5 }), self: self._TimeText);
		}

		private static int GetTyepId(this UIDirectBuyEveryDayGiftPanel self)
		{
			int num = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId).CurLoopCount;
			Dictionary<int, DirectBuyGiftEverydayTypeConfig> dictionary = ConfigSingleton<DirectBuyGiftEverydayTypeConfigCategory>.Instance.GetDictionary(self.ActId);
			if (num >= dictionary.Count)
			{
				num = dictionary.Count;
			}
			int result = 0;
			if (dictionary.ContainsKey(num) && ConfigSingleton<DirectBuyGiftConfigCategory>.Instance.GetAll(dictionary[num].Type) != null)
			{
				return dictionary[num].Type;
			}
			Log.Error("看下DirectBuyGiftEverydayTypeConfig，没有天数：" + num);
			return result;
		}

