		private static void OnClickSeletItem(this UIDirectBuySelectCard self, int index)
		{
			if (self.ConfigId == 0)
			{
				return;
			}
			ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId);
			if (activityData == null)
			{
				Log.Error("缺少activityData,活动是否没有配全？");
				return;
			}
			DirectBuySelectGiftModule component = ((Entity)activityData).GetComponent<DirectBuySelectGiftModule>();
			if (component == null)
			{
				Log.Error("活动是否没有配全？");
			}
			else
			{
				if (component.IsGetOneGift(self.ConfigId))
				{
					return;
				}
				if (!ConfigSingleton<DirectBuySelectBoxGiftConfigCategory>.Instance.GetDictionary(self.ConfigId).ContainsKey(index))
				{
					Log.Error("配置是否没有配全？");
					return;
				}
				UIManager.Instance.Show<UIDirectBuySelectBoxView, (int, int, int, Action<int, int>)>((self.ActId, self.ConfigId, index, delegate(int boxIndex, int itemIndex)
				{
					self.OnConfirmationSelect(boxIndex + 1, itemIndex);
				})).Coroutine();
			}
		}

		private static void OnConfirmationSelect(this UIDirectBuySelectCard self, int ConfigId)
		{
			DirectBuySelectBoxGiftConfig directBuySelectBoxGiftConfig = ConfigSingleton<DirectBuySelectBoxGiftConfigCategory>.Instance.Get(ConfigId);
			int num = 0;
			ET.ConfigBeans.Item[] selectItem = directBuySelectBoxGiftConfig.SelectItem;
			foreach (ET.ConfigBeans.Item value in selectItem)
			{
				self.Lists[num] = value;
				self.changeLists[num] = true;
				num++;
			}
			self._List.SetData(self.Lists.Count);
		}

