		{
			int index = cell.Index;
			if (index < self.Lists.Count)
			{
				((Entity)cell.UIObject).GetComponent<UIDirectBuySelectGiftItem>().SetDate(self.Lists[index], self.changeLists[index], self.ConfigId, index + 1, self.ActId);
			}
		}
	}
