		public static void SetChangeData(this UIDirectBuyThemeGiftPanel self)
		{
			Dictionary<int, DirectBuyGiftConfig> dictionary = ConfigSingleton<DirectBuyGiftConfigCategory>.Instance.GetDictionary(self.TypeId);
			if (dictionary == null)
			{
				Log.Error("缺少DirectBuyGiftConfig,该商品类型是否配置了？" + self.TypeId);
				return;
			}
			ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId);
			if (activityData == null)
			{
				Log.Error("缺少activityData,活动是否没有配全？");
				return;
			}
			DirectBuyThemeGiftModule component = ((Entity)activityData).GetComponent<DirectBuyThemeGiftModule>();
			Dictionary<int, int> giftState = component.GetGiftState();
			int rewardGift = component.GetRewardGift();
			bool flag = false;
			bool flag2 = false;
			foreach (DirectBuyGiftConfig value in dictionary.Values)
			{
				if (rewardGift == value.Id)
				{
					self.ConfigId = value.Id;
					flag = true;
					break;
				}
			}
			if (flag)
			{
				self._BuyBtn.SetTexture("ui_common_btn_14").Coroutine();
			}
			else
			{
				foreach (DirectBuyGiftConfig value2 in dictionary.Values)
				{
					if (giftState == null)
					{
						self.ConfigId = value2.Id;
						flag2 = true;
						break;
					}
					if (giftState.ContainsKey(value2.Id) && value2.LimitNum - giftState[value2.Id] > 0)
					{
						self.ConfigId = value2.Id;
						flag2 = true;
						break;
					}
					if (!giftState.ContainsKey(value2.Id))
					{
						self.ConfigId = value2.Id;
						flag2 = true;
						break;
					}
				}
				if (flag2)
				{
					self._BuyBtn.SetTexture("ui_common_btn_13").Coroutine();
				}
				else
				{
					self.ConfigId = dictionary.Values.Last().Id;
					self._BuyBtn.SetTexture("ui_common_btn_12").Coroutine();
				}
			}
			self._BuyBtn.SetRedPoint(RedPointType.Activity, self.ActId).Coroutine();
			DirectBuyGiftActivityConfig directBuyGiftActivityConfig = ConfigSingleton<DirectBuyGiftActivityConfigCategory>.Instance.Get(self.TypeId);
			self._BgImg.SetRawTexture(directBuyGiftActivityConfig.BgImage).Coroutine();
			self._BoxImg.SetTexture(directBuyGiftActivityConfig.BoxImage).Coroutine();
			self._TextImg.SetTexture(directBuyGiftActivityConfig.TextImage, nativeSize: true).Coroutine();
			DirectBuyGiftConfig directBuyGiftConfig = ConfigSingleton<DirectBuyGiftConfigCategory>.Instance.Get(self.ConfigId);
			self._DiscountImg.SetActive(directBuyGiftConfig.Discount > 0);
			self._DiscountText.SetText(directBuyGiftConfig.Discount + "%");
			ET.ConfigBeans.Item[] item = ConfigSingleton<DirectBuyGiftConfigCategory>.Instance.Get(self.ConfigId).Item;
			if (item.Length <= 5)
			{
				self._RewardList.UIObject.Transform.SetSizeWithCurrentAnchors((Axis)0, 160f * (float)item.Length + 52f);
			}
			else
			{
				self._RewardList.UIObject.Transform.SetSizeWithCurrentAnchors((Axis)0, 852f);
			}
			self._RewardList.SetData(item);
			int num = 0;
			if (giftState != null && giftState.ContainsKey(self.ConfigId))
			{
				num = giftState[self.ConfigId];
			}
			int num2 = directBuyGiftConfig.LimitNum - num;
			if (num2 <= 0)
			{
				num2 = 0;
			}
			self._RestrictText.SetText(Language.Format(4, 751, num2));
			((Behaviour)self._BuyText.GameObject.GetComponent<SuperOutline>()).enabled = true;
			if (flag)
			{
				self._BuyText.SetText(Language.Get(4, 726));
			}
			else if (flag2)
			{
				PayConfig payConfig = ConfigSingleton<PayConfigCategory>.Instance.Get(directBuyGiftConfig.PayId);
				if (payConfig == null)
				{
					Log.Error("商店id没找到，配置是否错误？");
					return;
				}
				self._BuyText.SetText(Language.Format(4, 744, payConfig.Price / 100));
			}
			else
			{
				self._BuyText.SetText(Language.Get(4, 727));
				((Behaviour)self._BuyText.GameObject.GetComponent<SuperOutline>()).enabled = false;
			}
