	public static class UIDressHelper
	{
		public static string GetFashionNameWithColor(int fashionId, out bool outline)
		{
			FashionConfig fashionConfig = ConfigSingleton<FashionConfigCategory>.Instance.Get(fashionId);
			int quality = fashionConfig.Quality;
			string name = fashionConfig.Name;
			switch (quality)
			{
			case 7:
				outline = true;
				return "<color=#ffffff>" + name + "</color>";
			case 6:
				outline = false;
				return "<color=#cd2727>" + name + "</color>";
			case 5:
				outline = false;
				return "<color=#c76b39>" + name + "</color>";
			case 4:
				outline = false;
				return "<color=#9a45d5>" + name + "</color>";
			default:
				outline = false;
				return "<color=#3f7fd3>" + name + "</color>";
			}
		}
	}
