		[UIMethod]
		private static void OnShow(this UIDressPanel self, (int, int dressId) args)
		{
			FashionConfig fashionConfig = ConfigSingleton<FashionConfigCategory>.Instance.Get(args.dressId);
			int subId = -1;
			switch (fashionConfig.Type)
			{
			case 1:
				subId = 37001;
				break;
			case 6:
				subId = 37003;
				break;
			case 7:
				subId = 37002;
				break;
			case 2:
				subId = 37007;
				break;
			case 3:
				subId = 37006;
				break;
			case 4:
				subId = 37005;
				break;
			case 5:
				subId = 37004;
				break;
			}
			self.Tabs.First((UITabInfo t) => t.FuncId == subId).SetArgs(new UIDressSubPanelShowArgs
			{
				DressId = args.dressId,
				DressType = fashionConfig.Type
			});
			((Entity)self).GetComponent<UICommonTab>().SetTabs(self.Tabs, subId).Coroutine();
			self.InitView();
		}

		private static void InitView(this UIDressPanel self)
		{
			self.UpdateAttrInfoBtn();
