		private static void OnAttInfoClick(this UIDressPanel self)
		{
			DressModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<DressModule>();
			StatList statList = new StatList();
			component.UpdateStat(statList);
			UIManager.Instance.Show<UIDressAttBonusInfoPanel, (StatList, List<DressSyncInfo>)>((statList, component.GetSyncInfos())).Coroutine();
		}

		public static void RefreshView(this UIDressPanel self)
		{
			RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.DressSuit);
			self.UpdateAttrInfoBtn();
			((Entity)self).GetComponent<UICommonTab>().SetTabs(self.Tabs).Coroutine();
		}

		public static void OnClickItem(this UIDressPanel self, int dressType, int dressId)
		{
			self.SelectDressId = dressId;
			self.OnClickShow();
		}

		private static void OnClickShow(this UIDressPanel self)
		{
			bool flag = false;
			FashionConfig fashionConfig = ConfigSingleton<FashionConfigCategory>.Instance.Get(self.SelectDressId);
			switch (fashionConfig.Type)
			{
			case 1:
				flag = self.ModelInfo.ModelId != fashionConfig.ModelId;
				if (flag)
				{
					self.ModelInfo.SetModel(fashionConfig.ModelId);
				}
				self.SetModel(flag);
				break;
			case 6:
				flag = self.ModelInfo.WeaponModelId != fashionConfig.ModelId;
				if (self.ModelInfo.WeaponModelId != fashionConfig.ModelId)
				{
					self.ModelInfo.SetWeapon(fashionConfig.ModelId);
				}
				self.SetModel(flag);
				break;
			case 7:
				flag = self.ModelInfo.ChapModelId != fashionConfig.ModelId;
				if (self.ModelInfo.ChapModelId != fashionConfig.ModelId)
				{
					self.ModelInfo.SetCape(fashionConfig.ModelId);
				}
				self.SetModel(flag);
				break;
			case 2:
				self.HeadId = fashionConfig.ModelId;
				self.SetHead();
				break;
			case 3:
				self.HeadFrameId = fashionConfig.ModelId;
				self.SetHead();
				break;
			}
			self.SetAttInfo();
		}

		private static void SetModel(this UIDressPanel self, bool isChange = true)
		{
			if (isChange)
			{
				self._UICommonModelPanel.ShowHighModel(self.ModelInfo, isDrag: true).Coroutine();
			}
			self._UICommonModelPanel.UIObject.SetActive(active: true);
			self._UICommonHead.UIObject.SetActive(active: false);
		}

		private static void SetHead(this UIDressPanel self)
		{
			self._UICommonModelPanel.UIObject.SetActive(active: false);
			self._UICommonHead.UIObject.SetActive(active: true);
			self._UICommonHead.SetData(self.HeadId, self.HeadFrameId, ((Entity)((Entity)(object)self).LocalPlayer()).Id, isEasyLook: false);
		}

		private static void UpdateAttrInfoBtn(this UIDressPanel self)
