		private static void SetAttInfo(this UIDressPanel self)
		{
			int star = ((Entity)(object)self).LocalPlayer().GetDressById(self.SelectDressId)?.Star ?? 0;
			FashionPowerConfig fashionPowerConfig = ConfigSingleton<FashionPowerConfigCategory>.Instance.Get(self.SelectDressId, star);
			self.AttStrings.Clear();
			self._UIAttScrollList.SetActive(active: false);
			self._NoneAtt.SetActive(active: false);
			if (fashionPowerConfig == null || fashionPowerConfig.Stats == null)
			{
				self._NoneAtt.SetActive(active: true);
				return;
			}
			Stat[] stats = fashionPowerConfig.Stats;
			for (int i = 0; i < stats.Length; i++)
			{
				string item = TextHelper.FormatStat(stats[i], "<color=#5dfa49>+{0}</color>");
				self.AttStrings.Add(item);
			}
			self._UIAttScrollList.SetActive(active: true);
			self._AttText.CloneAll(self.AttStrings, delegate(int index, string name, UIObject obj)
			{
				obj.SetText(self.AttStrings[index]);
			}).Coroutine();
			self._AttText.SetActive(active: false);
			LayoutRebuilder.ForceRebuildLayoutImmediate(self._UIAttScrollList.Transform);
		}
	}
