		[UIMethod]
		private static void OnShow(this UIDressSuitInfoPanel self, UIShowArgs showArgs)
		{
			foreach (FashionSuitConfig item in ConfigSingleton<FashionSuitConfigCategory>.Instance.GetList())
			{
				if (((Entity)(object)self).LocalPlayer().CheckAllConds(item.OpenConds))
				{
					self.SuidIds.Add(item.Id);
				}
			}
			if (self.SuidIds.Count == 0)
			{
				Log.Error("没有可展示的套装");
				return;
			}
			self.SuidIds.Sort(delegate(int a, int b)
			{
				FashionSuitConfig fashionSuitConfig = ConfigSingleton<FashionSuitConfigCategory>.Instance.Get(a);
				FashionSuitConfig fashionSuitConfig2 = ConfigSingleton<FashionSuitConfigCategory>.Instance.Get(b);
				return (fashionSuitConfig.Sort != fashionSuitConfig2.Sort) ? fashionSuitConfig.Sort.CompareTo(fashionSuitConfig2.Sort) : a.CompareTo(b);
			});
			self.SelectSuitId = self.SuidIds[0];
			self.UpdateData();
			self.UpdateView();
		}

		private static void UpdateData(this UIDressSuitInfoPanel self)
		{
			self.DressIds = ConfigSingleton<FashionConfigCategory>.Instance.GetSuitIdList(self.SelectSuitId);
		}

		private static void UpdateView(this UIDressSuitInfoPanel self)
		{
			self.UpdateChangeButton();
			self.UpdateModel();
			self.UpdateSuitItem();
			self.UpdateSuitInfo();
			self.UpdateSuitListItem();
			self.UpdateBg();
		}

		private static bool IsWearSameSuit(this UIDressSuitInfoPanel self)
		{
			DressModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<DressModule>();
			Dress isOnDress = component.GetIsOnDress(6);
			if (((isOnDress == null) ? ConfigSingleton<FashionConfigCategory>.Instance.Get(DressHelper.GetDefaultId(6)) : isOnDress.Config).SuitId != self.SelectSuitId)
			{
				return false;
			}
			Dress isOnDress2 = component.GetIsOnDress(7);
			if (((isOnDress2 == null) ? ConfigSingleton<FashionConfigCategory>.Instance.Get(DressHelper.GetDefaultId(7)) : isOnDress2.Config).SuitId != self.SelectSuitId)
			{
				return false;
			}
			Dress isOnDress3 = component.GetIsOnDress(1);
			return ((isOnDress3 == null) ? ConfigSingleton<FashionConfigCategory>.Instance.Get(DressHelper.GetDefaultId(1)) : isOnDress3.Config).SuitId == self.SelectSuitId;
		}

