		private static void UpdateModel(this UIDressSuitInfoPanel self)
		{
			foreach (int dressId in self.DressIds)
			{
				FashionConfig fashionConfig = ConfigSingleton<FashionConfigCategory>.Instance.Get(dressId);
				if (fashionConfig.Type == 1)
				{
					self.ModelInfo.SetModel(fashionConfig.ModelId);
				}
				if (fashionConfig.Type == 6)
				{
					self.ModelInfo.SetWeapon(fashionConfig.ModelId);
				}
				if (fashionConfig.Type == 7)
				{
					self.ModelInfo.SetCape(fashionConfig.ModelId);
				}
			}
			self._UICommonModelPanel.ShowHighModel(self.ModelInfo, isDrag: true).Coroutine();
		}

