		}

		private static void UpdateSuitListItem(this UIDressSuitInfoPanel self)
		{
			self._UIScrollList.SetData(self.SuidIds.Count);
		}

		private static void UpdateSuitInfo(this UIDressSuitInfoPanel self)
		{
			FashionSuitConfig fashionSuitConfig = ConfigSingleton<FashionSuitConfigCategory>.Instance.Get(self.SelectSuitId);
			FashionConfig fashionConfig = ConfigSingleton<FashionConfigCategory>.Instance.Get(fashionSuitConfig.Head);
			FashionConfig fashionConfig2 = ConfigSingleton<FashionConfigCategory>.Instance.Get(fashionSuitConfig.AvatarFrame);
			if (fashionConfig == null && fashionConfig2 == null)
			{
				self._HeadGo.SetActive(active: false);
			}
			else
			{
				self._HeadGo.SetActive(active: true);
				self._UICommonHead.SetData(fashionConfig.ModelId, fashionConfig2.ModelId, 0L);
				self._UICommonHead.SetDisableClick(disable: true);
			}
			using StatList statList = StatList.Create();
			statList.AddRange(fashionSuitConfig.Stats);
			bool flag = DressHelper.IsActiveDressSuit(((Entity)(object)self).LocalPlayer(), fashionSuitConfig.Id);
			for (int i = 0; i < self.CommonAttrs.Count; i++)
			{
				UIObject self2 = self.CommonAttrs[i];
				bool flag2 = i < statList.Count;
				self2.SetActive(flag2);
				if (flag2)
				{
					StatStruct stat = statList[i];
					self2.SetGray(!flag);
					self2.Find("Name").SetText(stat.GetName());
					self2.Find("Value").SetText(stat.GetValueText());
				}
			}
			using PowerCalc powerCalc = PowerCalc.Create();
			foreach (Hero commonFormationHero in ((Entity)(object)self).LocalPlayer().GetCommonFormationHeroes())
			{
				Dictionary<ushort, long> rawStats = commonFormationHero.GetRawStats();
				foreach (StatStruct item in statList)
				{
					if (item.IsBasStat())
					{
						powerCalc.AddStat(new StatStruct
						{
							Type = item.Type,
							Value = item.Value
						});
					}
					else
					{
						ushort basType = item.GetBasType();
						long valueOrDefault = rawStats.GetValueOrDefault(basType);
						powerCalc.AddStat(new StatStruct
						{
							Type = basType,
							Value = StatHelper.CalcPctAddValue(valueOrDefault, item.Value)
						});
					}
				}
			}
			self._UICommonPower.SetPower(powerCalc.Power);
			UIObject skillShowButton = self._SkillShowButton;
			string[] skillShow = fashionSuitConfig.SkillShow;
			skillShowButton.SetActive(skillShow != null && skillShow.Length > 0);
		}

		private static void OnClickSuitListItem(this UIDressSuitInfoPanel self, int index)
		{
			int num = self.SuidIds[index];
			if (self.SelectSuitId != num)
			{
				self.SelectSuitId = num;
				self.UpdateData();
				self.UpdateView();
			}
		}

