		{
		}

		private static async void OnClickChangeButton(this UIDressSuitInfoPanel self)
		{
			DressSuitModule module = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<DressSuitModule>();
			if (module.ActiveSuits.Contains(self.SelectSuitId))
			{
				if (self.IsWearSameSuit())
				{
					UIGameMsgHelper.FloatMsg("已是当前套装，无需替换");
					return;
				}
				List<int> suitIdList = ConfigSingleton<FashionConfigCategory>.Instance.GetSuitIdList(self.SelectSuitId);
				if (suitIdList == null)
				{
					return;
				}
				DressModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<DressModule>();
				Dictionary<int, int> dictionary = new Dictionary<int, int>();
				foreach (int item in suitIdList)
				{
					FashionConfig fashionConfig = ConfigSingleton<FashionConfigCategory>.Instance.Get(item);
					if (fashionConfig != null && component.CurrentDresses.GetValueOrDefault(fashionConfig.Type) != item)
					{
						dictionary[fashionConfig.Type] = item;
					}
				}
				await component.ReqUseDressAsync(dictionary);
				UIGameMsgHelper.FloatMsg("换装成功");
				self.UpdateChangeButton();
			}
			else if (DressHelper.IsActiveDressSuit(((Entity)(object)self).LocalPlayer(), self.SelectSuitId))
			{
				IResponse response = await ((Entity)(object)self).LocalPlayer().Call(new C2L_RequestActiveDressSuit
				{
					SuitId = self.SelectSuitId
				});
				if (response.Error != 0)
				{
					UIGameMsgHelper.FloatMsgByError(response.Error);
					return;
				}
				module.ActiveSuits.Add(self.SelectSuitId);
				RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.DressSuit, self.SelectSuitId);
				RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.DressSuit);
				RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.Dress);
				((Entity)(object)self).LocalPlayer().UpdateTeamStats(StatBagType.DressSuit);
				self.UpdateSuitListItem();
				self.UpdateChangeButton();
				self.UpdateSuitInfo();
			}
		}
	}
