			self.InitView();
		}

		private static void InitView(this UIDressSuitSkillShowPanel self)
		{
			self.InitSkill();
			self.OnClickSkillItem(0);
			self.UpdateButton();
		}

		private static void UpdateButton(this UIDressSuitSkillShowPanel self)
		{
			bool flag = DressHelper.IsActiveDressSuit(((Entity)(object)self).LocalPlayer(), self.SuitId);
			self._Button.SetActive(!flag);
		}

		private static void OnCellUpdate(this UIDressSuitSkillShowPanel self, UIScrollListCell cell)
		{
			UIDressSuitSkillItem component = ((Entity)cell.UIObject).GetComponent<UIDressSuitSkillItem>();
			int configId = self.SkillConfigIdList[cell.Index];
			component.SetData(configId, self.SelectIndex == cell.Index);
		}

		private static void OnCellCreate(this UIDressSuitSkillShowPanel self, UIScrollListCell cell)
		{
			((Entity)cell.UIObject).GetComponent<UIDressSuitSkillItem>().AddSkillClickHandler(delegate
			{
				self.OnClickSkillItem(cell.Index);
			});
		}

		private static void InitSkill(this UIDressSuitSkillShowPanel self)
		{
			self.SkillConfigIdList.Clear();
			for (int i = 1; i <= ConfigSingleton<PracticeSkillConfigCategory>.Instance.GetAll().Count; i++)
			{
				self.SkillConfigIdList.Add(i);
			}
			self.SelectIndex = -1;
		}

		private static void OnClickSkillItem(this UIDressSuitSkillShowPanel self, int Index)
		{
			if (self.SelectIndex != Index)
			{
				self.SelectIndex = Index;
				self.UpdateSkill();
			}
		}

		private static void UpdateSkill(this UIDressSuitSkillShowPanel self)
		{
			self._UISkillScroll.SetData(self.SkillConfigIdList.Count);
			FashionSuitConfig fashionSuitConfig = ConfigSingleton<FashionSuitConfigCategory>.Instance.Get(self.SuitId);
			self._VideoPlay.GameObject.GetComponent<VideoPlayer>().Stop();
			self._VideoPlay.SetVideoPlayer(fashionSuitConfig.SkillShow[self.SelectIndex]).OnCompleted((Action)delegate
			{
				self._VideoPlay.GameObject.GetComponent<VideoPlayer>().Play();
			});
		}
	}
