		private static void InitPanel(this UITeamDupTXCMPanel self)
		{
			self.BossList.Clear();
			foreach (int key in ConfigSingleton<DupTXCMConfigCategory>.Instance.GetAll().Keys)
			{
				self.BossList.Add(key);
			}
			self._BossScrollList.SetData(self.BossList.Count);
			int defalutIndex = self.GetDefalutIndex();
			self.SetSelectByIndex(defalutIndex);
			self._BossScrollList.MovePanelToItemIndex((defalutIndex - 2 >= 0) ? (defalutIndex - 2) : 0);
		}

		private static int GetDefalutIndex(this UITeamDupTXCMPanel self)
		{
			int result = 0;
			for (int i = 0; i < self.BossList.Count; i++)
			{
				DupTXCMConfig dupTXCMConfig = ConfigSingleton<DupTXCMConfigCategory>.Instance.Get(self.BossList[i]);
				if (!((Entity)(object)self).LocalPlayer().CheckAllConds(dupTXCMConfig.Conds))
				{
					break;
				}
				result = i;
			}
			return result;
		}

