		private static void OnStartClick(this UITeamDupTXCMPanel self)
		{
			if (self.CurrentIndex >= 0)
			{
				DupTXCMConfig dupTXCMConfig = ConfigSingleton<DupTXCMConfigCategory>.Instance.Get(self.BossList[self.CurrentIndex]);
				if (!((Entity)(object)self).LocalPlayer().CheckAllConds(dupTXCMConfig.Conds))
				{
					UIGameMsgHelper.FloatMsg(((Entity)(object)self).LocalPlayer().GetCondText(dupTXCMConfig.Conds));
				}
				else if (((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<TeamDupModule>().GetLeftCount() <= 0)
				{
					UIGameMsgHelper.FloatMsgByError(204401);
				}
				else
				{
					UIManager.Instance.Show<UITeamDupMatchPanel, int>(self.BossList[self.CurrentIndex]).Coroutine();
				}
			}
		}

