		{
			self._MonsterSkillTipsBg.SetActive(active: true);
			int id = self.BossList[self.CurrentIndex];
			DupTXCMConfig dupTXCMConfig = ConfigSingleton<DupTXCMConfigCategory>.Instance.Get(id);
			self._UIMonsterSkillTips.SetData(dupTXCMConfig.BossId);
		}

		private static void OnRewardBoxClick(this UITeamDupTXCMPanel self)
		{
			TeamDupModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<TeamDupModule>();
			if (component.IsCanGetBox() == 0)
			{
				component.ReqGetBoxReward();
				return;
			}
			self._RewardGroup.SetActive(active: true);
			DupTXCMBoxConfig dupTXCMBoxConfig = ConfigSingleton<DupTXCMBoxConfigCategory>.Instance.Get(component.BoxId);
			DropShowConfig dropConfig = ConfigSingleton<DropShowConfigCategory>.Instance.Get(dupTXCMBoxConfig.DropId);
			self._RewardItem.UIObject.CloneAll(dropConfig.Items.Length, delegate(int i, UIObject o)
			{
				((Entity)o).GetComponent<UICommonItem>().SetItem(dropConfig.Items[i].Id, dropConfig.Items[i].Nums);
			}).Coroutine();
		}

		private static void OnCellUpdate(this UITeamDupTXCMPanel self, UIScrollListCell cell)
		{
			int index = cell.Index;
			UITeamDupTXCMItem component = ((Entity)cell.UIObject).GetComponent<UITeamDupTXCMItem>();
			component.SetData(self.BossList[index]);
			component.Selected(index == self.CurrentIndex);
		}

