		}

		public static void SetData(this UIEndlessBuffItem self, int configId, int index)
		{
			self.ConfigId = configId;
			self.Index = index;
			EndlessBuffGroupConfig endlessBuffGroupConfig = ConfigSingleton<EndlessBuffGroupConfigCategory>.Instance.Get(configId);
			BuffConfig buffConfig = ConfigSingleton<BuffConfigCategory>.Instance.Get(endlessBuffGroupConfig.BuffId);
			self._NameText.SetText(buffConfig.Name);
			self._DescText.SetText(buffConfig.Desc);
			self._Icon.SetRawTexture("uitex_buff_" + buffConfig.Icon).Coroutine();
			self._BG.SetRawTexture($"ui_wjly_level_{buffConfig.Level}").Coroutine();
			if (((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VipModule>().GetLevel() >= endlessBuffGroupConfig.VipConds)
			{
				self._LockGroup.SetActive(active: false);
				self._BlockImage.SetActive(active: false);
			}
			else
			{
				self._LockGroup.SetActive(active: true);
				self._BlockImage.SetActive(active: true);
				self._LockText.SetText($"至尊{endlessBuffGroupConfig.VipConds}专属");
			}
		}

		private static void OnSelectClick(this UIEndlessBuffItem self)
		{
			EndlessBuffGroupConfig endlessBuffGroupConfig = ConfigSingleton<EndlessBuffGroupConfigCategory>.Instance.Get(self.ConfigId);
			VipModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VipModule>();
			if (endlessBuffGroupConfig.VipConds > component.GetLevel())
			{
				UIGameMsgHelper.FloatMsg(Language.Format(5, 1, endlessBuffGroupConfig.VipConds));
			}
			else
			{
				UIObject.FindUIObjectOfType<UIEndlessBuffPanel>().AddBuffByIndex(self.Index);
			}
		}
	}
