		public static List<int> GetBuffs(this UIEndlessBuffPanel self, int[] BuffGroups)
		{
			List<int> list = new List<int>();
			foreach (int num in BuffGroups)
			{
				List<BuffConfig> buffsByGroup = self.GetBuffsByGroup(num);
				if (buffsByGroup.Count > 0)
				{
					list.Add(RandomGenerator.RandomArray<BuffConfig>(buffsByGroup).Id);
				}
			}
			return list;
		}

		public static List<BuffConfig> GetBuffsByGroup(this UIEndlessBuffPanel self, int group)
		{
			List<BuffConfig> list = new List<BuffConfig>();
			foreach (var (_, buffConfig2) in ConfigSingleton<BuffConfigCategory>.Instance.GetAll())
			{
				if (buffConfig2.Group == group)
				{
					list.Add(buffConfig2);
				}
			}
			return list;
		}
	}
