		public static void UpdateRankReward(this UIEndlessPanel self)
		{
			EndlessModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<EndlessModule>();
			if (component.RankRewardId > 0 && !component.IsGetedRankReward)
			{
				self._RankRewardButton.SetActive(active: true);
				self._RankTextButton.SetActive(active: false);
				self._RankList.UIObject.SetActive(active: false);
				self._RankText.SetText("昨天排行奖励");
				using ItemList itemList = ItemList.Create();
				itemList.AddRange(ConfigSingleton<EndlessPurgatoryRewardConfigCategory>.Instance.Get(component.RankRewardId).Reward);
				self._RankReward.SetData(itemList);
				self._YestDayRankText.SetText($"昨日排名:{component.YesterdayRank}");
				self._YestDayRankText.SetActive(active: true);
				self._RankReward.UIObject.SetActive(active: true);
			}
			else
			{
				self._RankRewardButton.SetActive(active: false);
				self._RankTextButton.SetActive(active: true);
				self._RankList.UIObject.SetActive(active: true);
				self._RankText.SetText("炼狱排行榜");
				self._YestDayRankText.SetActive(active: false);
				self._RankReward.UIObject.SetActive(active: false);
			}
			self._RankTextButton.SetRedPoint(RedPointType.Dup_Endless, 3).Coroutine();
		}

