		}

		private static void UpdateDayReward(this UIEndlessPanel self)
		{
			EndlessModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<EndlessModule>();
			self._EmptyText.SetActive(component.GetPassId() <= 0);
			self._DayReward.SetActive(component.GetPassId() > 0);
			if (self._DayReward.IsActive())
			{
				EndlessPurgatoryDupLevelConfig endlessPurgatoryDupLevelConfig = ConfigSingleton<EndlessPurgatoryDupLevelConfigCategory>.Instance.Get(component.GetPassId());
				using ItemList itemList = ItemList.Create();
				if (component.DayRewardId == component.GetPassId())
				{
					itemList.AddRange(endlessPurgatoryDupLevelConfig.DayReward);
					self._RecordText.SetText($"通关记录:{endlessPurgatoryDupLevelConfig.Layer}层 {endlessPurgatoryDupLevelConfig.Wave}关");
				}
				else
				{
					if (component.DayRewardId > 0)
					{
						EndlessPurgatoryDupLevelConfig endlessPurgatoryDupLevelConfig2 = ConfigSingleton<EndlessPurgatoryDupLevelConfigCategory>.Instance.Get(component.DayRewardId);
						itemList.AddRange(endlessPurgatoryDupLevelConfig2.DayReward, -1);
					}
					itemList.AddRange(endlessPurgatoryDupLevelConfig.DayReward);
					itemList.Clean();
					if (itemList.Count > 0)
					{
						self._RecordText.SetText("<color=#0DB64D>点击可领取</color>");
					}
					else
					{
						int num = 1;
						while (true)
						{
							if (!ConfigSingleton<EndlessPurgatoryDupLevelConfigCategory>.Instance.Contain(num + component.DayRewardId))
							{
								endlessPurgatoryDupLevelConfig = ConfigSingleton<EndlessPurgatoryDupLevelConfigCategory>.Instance.Get(component.DayRewardId);
								break;
							}
							EndlessPurgatoryDupLevelConfig endlessPurgatoryDupLevelConfig3 = ConfigSingleton<EndlessPurgatoryDupLevelConfigCategory>.Instance.Get(num + component.DayRewardId);
							itemList.AddRange(endlessPurgatoryDupLevelConfig3.DayReward);
							itemList.Clean();
							if (itemList.Count > 0)
							{
								endlessPurgatoryDupLevelConfig = endlessPurgatoryDupLevelConfig3;
								break;
							}
							EndlessPurgatoryDupLevelConfig endlessPurgatoryDupLevelConfig4 = ConfigSingleton<EndlessPurgatoryDupLevelConfigCategory>.Instance.Get(component.DayRewardId);
							itemList.AddRange(endlessPurgatoryDupLevelConfig4.DayReward, -1);
							num++;
						}
						itemList.AddRange(endlessPurgatoryDupLevelConfig.DayReward);
						self._RecordText.SetText($"通关记录:{endlessPurgatoryDupLevelConfig.Layer}层 {endlessPurgatoryDupLevelConfig.Wave}关");
					}
				}
				self._DayRewardList.SetData(itemList);
			}
			self._DayContent.SetRedPoint(RedPointType.Dup_Endless, 1).Coroutine();
			self._DayEffect.SetActive(RedPointHelper.GetCount(SceneHelper.DomainScene((Entity)(object)self), RedPointType.Dup_Endless, 1) > 0);
			RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.Dup_Endless);
			RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.Dup);
		}

		private static void UpdatePassReward(this UIEndlessPanel self)
		{
			EndlessModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<EndlessModule>();
			int nextPassId = component.GetNextPassId();
			if (nextPassId == 0)
			{
				return;
			}
			EndlessPurgatoryDupLevelConfig endlessPurgatoryDupLevelConfig = ConfigSingleton<EndlessPurgatoryDupLevelConfigCategory>.Instance.Get(nextPassId);
			self._FirstPassText.SetText($"首通（{endlessPurgatoryDupLevelConfig.Layer}层 {endlessPurgatoryDupLevelConfig.Wave}关）");
			using ItemList itemList = ItemList.Create();
			itemList.AddRange(endlessPurgatoryDupLevelConfig.PassReward);
			self._PassRewardList.SetData(itemList);
			int gapLevel = EndlessHelper.GetGapLevel(component.CurrentId, nextPassId);
			self._ConditionText.SetText(Language.Format(2, 192, gapLevel));
			self._PassContent.SetRedPoint(RedPointType.Dup_Endless, 2).Coroutine();
			self._PassEffect.SetActive(RedPointHelper.GetCount(SceneHelper.DomainScene((Entity)(object)self), RedPointType.Dup_Endless, 2) > 0);
		}

