		private static void OnCellUpdate(this UIEndlessRewardPart self, UIScrollListCell cell)
		{
			int index = cell.Index;
			if (index < self.RewardConfigList.Count)
			{
				((Entity)cell.UIObject).GetComponent<UIEndlessRewardItem>().SetData(self.RewardConfigList[index], index);
			}
		}

		public static void SetData(this UIEndlessRewardPart self, int myRank)
		{
			self.RewardConfigList.Clear();
			if (myRank > 0 && myRank < 4)
			{
				self._TxtPlayerRank.SetActive(active: false);
				self._ImgPlayerRank.SetSprite($"ui_rank_sign_0{myRank}").Coroutine();
			}
			else
			{
				self._TxtPlayerRank.SetActive(active: true);
				self._ImgPlayerRank.SetActive(active: false);
				self._TxtPlayerRank.SetText((myRank == 0) ? Language.Get(2, 204) : myRank.ToString());
			}
			for (int i = 1; i < 100; i++)
			{
				if (!ConfigSingleton<EndlessPurgatoryRewardConfigCategory>.Instance.Contain(i))
				{
					continue;
				}
				EndlessPurgatoryRewardConfig endlessPurgatoryRewardConfig = ConfigSingleton<EndlessPurgatoryRewardConfigCategory>.Instance.Get(i);
				if (myRank >= endlessPurgatoryRewardConfig.LeftRank && myRank <= endlessPurgatoryRewardConfig.RightRank)
				{
					using ItemList itemList = ItemList.Create();
					itemList.AddRange(endlessPurgatoryRewardConfig.Reward);
					self._UIPlayerRewardScroll.SetData(itemList);
				}
				self.RewardConfigList.Add(endlessPurgatoryRewardConfig);
			}
			self._UIRewardScroll.SetData(self.RewardConfigList.Count);
		}
	}
