				self.OnSetEveryDay();
			}
		}

		private static void OnClickFirstPassRewardButton(this UIEndlessShowRewardPanel self)
		{
			if (1 != self.SelectTab)
			{
				self.SelectTab = 1;
				self._DayRewardButton.SetUIObjectChildShow(self.SelectTab == 0);
				self._FirstPassRewardButton.SetUIObjectChildShow(1 == self.SelectTab);
				self._UIRewardMask.SetActive(active: true);
