		public static void UpdateView(this UIEveryDaySignPanel self)
		{
			ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId);
			if (activityData == null)
			{
				return;
			}
			self._TipText.SetText(Language.Get(4, 742));
			EveryDaySignModule component = ((Entity)activityData).GetComponent<EveryDaySignModule>();
			if (component.IsPrivilege())
			{
				self._ActivityBtnMask.SetActive(active: true);
				self._ActivityText.SetText("已激活");
			}
			else
			{
				self._ActivityBtnMask.SetActive(active: false);
				self._ActivityText.SetText("激活终生卡");
			}
			int loop = component.GetLoop();
			self.Lists.Clear();
			int num = -1;
			int mark = component.GetMark();
			bool flag = component.IsPrivilege();
			SortedDictionary<int, EveryDaySignConfig> dictionary = ConfigSingleton<EveryDaySignConfigCategory>.Instance.GetDictionary(self.ActId);
			int count = component.Count;
			self._SignText.SetText(count.ToString() ?? "");
			foreach (EveryDaySignConfig value in dictionary.Values)
			{
				if (value.Round != loop)
				{
					continue;
				}
				self.Lists.Add(value);
				if (num == -1)
				{
					if (flag && !component.IsRewardDayPrivilegeFlag(value.Day) && component.IsLoginFlag(value.Day))
					{
						num = value.Day;
					}
					if (!component.IsRewardDayFlag(value.Day) && component.IsLoginFlag(value.Day))
					{
						num = value.Day;
					}
					if (value.Day == mark)
					{
						num = value.Day;
					}
				}
			}
			self._UIScrollList.SetData(self.Lists.Count);
			if (num > 0)
			{
				self._UIScrollList.MovePanelToItemIndex(num - 1);
			}
			RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.Activity, self.ActId);
		}

