		public static void SetData(this UIExchangeShopFullFutures self, int actId, int future)
		{
			self.ActId = actId;
			self.Future = future;
			ExchangeShopConfig exchangeShopConfig = ConfigSingleton<ExchangeShopConfigCategory>.Instance.Get(self.ActId);
			if (string.IsNullOrEmpty(exchangeShopConfig.Background))
			{
				self._MainBg.SetActive(active: false);
				self._Bg.SetActive(active: false);
			}
			else
			{
				self._MainBg.SetActive(active: true);
				self._Bg.SetActive(active: true);
				self._MainBg.SetSprite(exchangeShopConfig.Background).Coroutine();
			}
			self.OnRefreshData(self.ActId);
		}

		public static void OnRefreshData(this UIExchangeShopFullFutures self, int actId)
		{
			if (self.ActId != actId || self.ActId == 0)
			{
				return;
			}
			self.List.Clear();
			Dictionary<int, ExchangeShopItemConfig> dictionary = ConfigSingleton<ExchangeShopItemConfigCategory>.Instance.GetDictionary(self.ActId);
			if (dictionary == null)
			{
				Log.Error($"ExchangeShopItemConfig中没有{self.ActId}相关数据");
				return;
			}
			foreach (ExchangeShopItemConfig value in dictionary.Values)
			{
				if (value.Futures == self.Future)
				{
					self.List.Add(value);
				}
			}
			int id = self.List.First().CostPrice.Id;
			ItemConfig itemConfig = ConfigSingleton<ItemConfigCategory>.Instance.Get(id);
			self._CostIcon.SetRawTexture($"uitex_icon_item_{itemConfig.Icon}").Coroutine();
			long itemNumsByItemId = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().GetItemNumsByItemId(id);
			self._CostNum.SetText($"{itemNumsByItemId}");
			self._CostAdd.SetRedPoint(RedPointType.Activity, self.ActId, 2, self.Future).Coroutine();
			int num = (int)Math.Ceiling((float)self.List.Count / 3f);
			float num2 = 255.01f * (float)num + self._List.SpaceY * (float)num;
			self._List.UIObject.Transform.SetSizeWithCurrentAnchors((Axis)1, num2);
			if (self._Bg.IsActive())
			{
				self._Bg.Transform.SetSizeWithCurrentAnchors((Axis)1, num2 + 61f + 20f);
			}
			self.UIObject.Transform.SetSizeWithCurrentAnchors((Axis)1, num2 + 58.764f + 20f);
			self._List.SetData(self.List.Count);
			self.OnRefreshRed(self.ActId, self.Future);
		}

