		public static void SetData(this UIExchangeShopFutures self, int actId, int future)
		{
			self.ActId = actId;
			self.Future = future;
			ExchangeShopConfig exchangeShopConfig = ConfigSingleton<ExchangeShopConfigCategory>.Instance.Get(self.ActId);
			if (string.IsNullOrEmpty(exchangeShopConfig.Background))
			{
				self._MainBg.SetActive(active: false);
				self._Bg.SetActive(active: false);
			}
			else
			{
				self._MainBg.SetActive(active: true);
				self._Bg.SetActive(active: true);
