		{
			if (future != self.Future || self.ActId != actId)
			{
				return;
			}
			ExchangeShopModule component = ((Entity)ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId)).GetComponent<ExchangeShopModule>();
			Dictionary<int, ExchangeShopItemConfig> dictionary = ConfigSingleton<ExchangeShopItemConfigCategory>.Instance.GetDictionary(self.ActId);
			if (dictionary == null)
			{
				Log.Error($"ExchangeShopItemConfig没有这个活动的数据啊{self.ActId}");
				return;
			}
			Dictionary<int, int> dictionary2 = new Dictionary<int, int>();
			foreach (ExchangeShopItemConfig value in dictionary.Values)
			{
				if (value.Futures == self.Future && value.ActId == self.ActId)
				{
					dictionary2.Add(value.Id, LocalData.GetInt(component.GetName(value.ActId, value.GiftRewards.Id, self.Future)));
				}
			}
			bool active = false;
			foreach (int value2 in dictionary2.Values)
			{
				if (value2 == 0)
				{
					active = true;
					break;
				}
			}
			self._IsRed.SetActive(active);
		}

