		public static void SetData(this UIExchangeShopGiftItem self, ExchangeShopGiftConfig config)
		{
			self.ActId = config.ActId;
			self.Config = config;
			self._BgImg.SetSprite(self.Config.GiftPic).Coroutine();
			self._NameText.SetText(self.Config.GiftName);
			self._Red.UIObject.SetActive(active: false);
			ExchangeShopModule component = ((Entity)ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId)).GetComponent<ExchangeShopModule>();
			self._RestrictText.SetActive(self.Config.GiftType != 3);
			self._HotImg.SetActive(self.Config.Logo == 1);
			self._DiscountImg.SetActive(self.Config.Discount > 0);
			self._DiscountText.SetText($"{self.Config.Discount}%");
			int item = component.IsBuy(self.Config.Id).Item2;
			self._RestrictText.SetText((self.Config.RefreshType == 1) ? Language.Format(4, 828, self.Config.BuyLimitNum - item) : Language.Format(4, 764, self.Config.BuyLimitNum - item));
			if (self.Config.GiftType == 3)
			{
				self._BuyText.SetText(Language.Format(2, 500));
			}
			else
			{
				PayConfig payConfig = ConfigSingleton<PayConfigCategory>.Instance.Get(self.Config.PayId);
				if (payConfig == null)
				{
					Debug.LogError((object)"商店id没找到，配置是否错误？");
				}
				self._BuyText.SetText(Language.Format(4, 744, payConfig.Price / 100));
			}
			List<ET.ConfigBeans.Item> list = new List<ET.ConfigBeans.Item>();
			list.AddRange(self.Config.GiftRewards);
			IOrderedEnumerable<ET.ConfigBeans.Item> orderedEnumerable = from o in list
				orderby ItemHelper.GetItemQualityByItemId(o.Id) descending, o.Id
				select o;
			int num = 0;
			ET.ConfigBeans.Item[] array = new ET.ConfigBeans.Item[orderedEnumerable.Count()];
			foreach (ET.ConfigBeans.Item item2 in orderedEnumerable)
			{
				array[num] = item2;
				num++;
			}
			using ItemList itemList = ItemList.Create();
			itemList.AddRange(array);
			self._UICommonGridReward.SetData(itemList);
			self.OnRefreshConfigData();
		}

		private static void OnRefreshConfigData(this UIExchangeShopGiftItem self)
		{
			ExchangeShopModule component = ((Entity)ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId)).GetComponent<ExchangeShopModule>();
			self._Red.UIObject.SetActive(active: false);
			int item = component.IsBuy(self.Config.Id).Item2;
			if (self.Config.GiftType == 3)
			{
				if (component.CanGet(self.Config.Id))
				{
					self._BuyBtn.SetTexture("ui_common_btn_36").Coroutine();
					self._BuyText.SetText(Language.Get(4, 726));
					self._Red.UIObject.SetActive(active: true);
				}
				else
				{
					self._BuyBtn.SetTexture("ui_common_btn_12").Coroutine();
					self._BuyText.SetText(Language.Get(4, 727));
				}
			}
			else if (component.CanGet(self.Config.Id))
			{
				self._BuyBtn.SetTexture("ui_common_btn_36").Coroutine();
				self._BuyText.SetText(Language.Get(4, 726));
				self._Red.UIObject.SetActive(active: true);
			}
			else if (item >= self.Config.BuyLimitNum)
			{
				self._BuyBtn.SetTexture("ui_common_btn_11").Coroutine();
				self._BuyText.SetText(Language.Get(4, 752));
			}
			else
			{
				self._BuyBtn.SetTexture("ui_common_btn_03").Coroutine();
				PayConfig payConfig = ConfigSingleton<PayConfigCategory>.Instance.Get(self.Config.PayId);
				self._BuyText.SetText(Language.Format(4, 744, payConfig.Price / 100));
			}
		}

