		private static UICommonBuyItemPanelOptions GetOptions(this UIExchangeShopItem self)
		{
			ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId);
			ExchangeShopModule module = ((Entity)activityData).GetComponent<ExchangeShopModule>();
			int changeNum = module.GetChangeNum(self.Config.Id);
			UICommonBuyItemPanelOptions options = new UICommonBuyItemPanelOptions(async delegate
			{
				UICommonBuyItemPanel uICommonBuyItemPanel = UIObject.FindUIObjectOfType<UICommonBuyItemPanel>();
				if (uICommonBuyItemPanel != null)
				{
					int currentNumber = uICommonBuyItemPanel.GetCurrentNumber();
					long itemNumsByItemId = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().GetItemNumsByItemId(self.Config.CostPrice.Id);
					if (self.Config.CostPrice.Nums * currentNumber > itemNumsByItemId)
					{
						UIManager.Instance.Show<UIExchangeShopGiftPanel, (int, int)>((self.ActId, self.Config.Futures)).Coroutine();
					}
					else if (await module.ReqGetDuiHuan(self.Config.Id, currentNumber) == 0)
					{
						UIManager.Instance.Remove(typeof(UICommonBuyItemPanel));
					}
				}
			});
			options.ChangeAction = delegate(IUI ui, int changeValue)
			{
				UICommonBuyItemPanel self2 = ui as UICommonBuyItemPanel;
				options.CurrentValue = changeValue;
				float num = self2.OnGetMinNumber();
				if (changeValue == (int)num)
				{
					self2.OnSetSubButtonGary();
				}
				else
				{
					self2.OnSetSubButtonNor();
				}
				if (changeValue == options.MaxValue)
				{
					self2.OnSetAddButtonGary();
				}
				else
				{
					self2.OnSetAddButtonNor();
				}
				self2.OnSetCurrText(options.CurrentValue);
				long itemNumsByItemId = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().GetItemNumsByItemId(self.Config.CostPrice.Id);
				int num2 = self.Config.CostPrice.Nums * changeValue;
				self2.OnSetMoneyText(num2);
				self2.OnSetGary(itemNumsByItemId < num2);
				self2.SetItem(self.Config.GiftRewards.Id, self.Config.GiftRewards.Nums * changeValue);
			};
			options.MaxValue = self.Config.Limit - changeNum;
			options.CurrentValue = 1;
			options.OnShowAction = delegate(IUI ui, int changeValue)
			{
				UICommonBuyItemPanel self2 = ui as UICommonBuyItemPanel;
				string itemNameByItemId = ItemHelper.GetItemNameByItemId(self.Config.GiftRewards.Id);
				self2.SetMoneyIcon(self.Config.CostPrice.Id);
				self2.SetName(itemNameByItemId);
				self2.SetMoneyList(new List<int> { self.Config.CostPrice.Id });
				self2.SetTitle(Language.Get(4, 829));
				options.ChangeAction(ui, changeValue);
			};
			return options;
		}
	}
