	[FriendOf(typeof(UIFaBaoAttrView))]
	public static class UIFaBaoAttrViewSystem
	{
		private class __AwakeSystem : AwakeSystem<UIFaBaoAttrView>
		{
			protected override void Awake(UIFaBaoAttrView self)
			{
				UIObject uIObject = self.UIObject;
				_ = self.UIObject.Transform;
				UICommonAttr4 attr = ((Entity)uIObject.Find("_AttrNode1/_Attr1")).AddComponent<UICommonAttr4>(false);
				UICommonAttr4 attr2 = ((Entity)uIObject.Find("_AttrNode2/_Attr2")).AddComponent<UICommonAttr4>(false);
				self._AttrNode1 = uIObject.Find("_AttrNode1");
				self._Attr1 = attr;
				self._NextText1 = uIObject.Find("_AttrNode1/_NextText1");
				self._AttrNode2 = uIObject.Find("_AttrNode2");
				self._Attr2 = attr2;
				self._NextText2 = uIObject.Find("_AttrNode2/_NextText2");
				UIEventDispatcherComponent.Instance.Register(self);
			}
		}

		private class __DestroySystem : DestroySystem<UIFaBaoAttrView>
		{
			protected override void Destroy(UIFaBaoAttrView self)
			{
				UIEventDispatcherComponent.Instance.UnRegister(self);
				self._AttrNode1 = null;
				self._Attr1 = null;
				self._NextText1 = null;
				self._AttrNode2 = null;
				self._Attr2 = null;
				self._NextText2 = null;
				((DisposeObject)self.UIObject).Dispose();
			}
		}

		[UIMethod]
		public static void OnAwake(this UIFaBaoAttrView self)
		{
			self.Attrs = new List<UICommonAttr4> { self._Attr1, self._Attr2 };
			self.NextValueList = new List<UIObject> { self._NextText1, self._NextText2 };
			self.AttrNode = new List<UIObject> { self._AttrNode1, self._AttrNode2 };
		}

		public static void SetData(this UIFaBaoAttrView self, StatList total, StatList nextStat = null)
		{
			for (int i = 0; i < self.Attrs.Count; i++)
			{
				UIObject uIObject = self.AttrNode[i];
				bool flag = i < total.Count;
				uIObject.SetActive(flag);
				if (flag)
				{
					UICommonAttr4 uICommonAttr = self.Attrs[i];
					UIObject self2 = self.NextValueList[i];
					StatStruct stat = total[i];
					long num = 0L;
					if (nextStat != null)
					{
						num = nextStat[i].Value;
					}
					long num2 = stat.Value - num;
					long num3 = num - num2;
					uICommonAttr.SetData(stat.Type, stat.GetName(), string.Empty);
					uICommonAttr.UpdateValue(stat.Type, num2);
					self2.SetActive(num3 > 0);
					if (num3 > 0)
					{
						self2.SetText("+" + TextHelper.FormatStatValue(stat.Type, num3));
					}
					LayoutRebuilder.ForceRebuildLayoutImmediate(uICommonAttr.UIObject.Transform);
					LayoutRebuilder.ForceRebuildLayoutImmediate(uIObject.Transform);
				}
			}
			LayoutRebuilder.ForceRebuildLayoutImmediate(self.UIObject.Transform);
		}
	}
