		public static void SetBaseInfo(this UIFaBaoBaseInfo self, int configId)
		{
			//IL_004c: Unknown result type (might be due to invalid IL or missing references)
			//IL_00e9: Unknown result type (might be due to invalid IL or missing references)
			//IL_00ef: Unknown result type (might be due to invalid IL or missing references)
			//IL_00f3: Unknown result type (might be due to invalid IL or missing references)
			//IL_00f9: Unknown result type (might be due to invalid IL or missing references)
			FaBaoConfig faBaoConfig = ConfigSingleton<FaBaoConfigCategory>.Instance.Get(configId);
			FaBaoQualityConfig faBaoQualityConfig = ConfigSingleton<FaBaoQualityConfigCategory>.Instance.Get(faBaoConfig.Quality);
			self._Name.SetText(faBaoConfig.Name);
			Color effectColor = default(Color);
			ColorUtility.TryParseHtmlString(faBaoQualityConfig.OutLineColor, ref effectColor);
			self._Name.GameObject.GetComponent<SuperOutline>().effectColor = effectColor;
			FaBao child = ((Entity)((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FaBaoModule>()).GetChild<FaBao>((long)configId);
			self._HeroStarArea.UIObject.SetActive(child != null);
			if (child != null)
			{
				self._HeroStarArea.SetStar(child.Star, showBackground: true);
			}
			if (!string.IsNullOrEmpty(self.EffectPath) && faBaoQualityConfig.BgEffRes != self.EffectPath)
			{
				self._BgEffectNode.RemoveEffect(self.EffectPath);
				self.EffectPath = string.Empty;
			}
			if (child != null && string.IsNullOrEmpty(self.EffectPath))
			{
				self._BgEffectNode.PlayEffect(faBaoQualityConfig.BgEffRes);
				self.EffectPath = faBaoQualityConfig.BgEffRes;
			}
		}

		public static void DoKillImageStar(this UIFaBaoBaseInfo self)
		{
			//IL_002f: Unknown result type (might be due to invalid IL or missing references)
			foreach (UIObject star in self._HeroStarArea.stars)
			{
				SuperImage component = star.Find("_ImgStar").GameObject.GetComponent<SuperImage>();
				((Graphic)component).color = Color.white;
				ShortcutExtensions.DOKill((Component)(object)component, false);
