			self._HeroStarArea.SetStar(star, showBackground: true);
			UIObject uIObject = self._HeroStarArea.GetStart(star).Find("_ImgStar");
			uIObject.SetActive(active: true);
			SuperImage component = uIObject.GameObject.GetComponent<SuperImage>();
			ShortcutExtensions.DOKill((Component)(object)component, false);
			((Graphic)component).color = new Color(1f, 1f, 1f, 0f);
			TweenSettingsExtensions.SetLoops<TweenerCore<Color, Color, ColorOptions>>(DOTweenModuleUI.DOFade((Image)(object)component, 0.8f, 1f), -1, (LoopType)1);
		}

