		private static void UpdateAttr(this UIFaBaoDetailInfoPanel self)
		{
			//IL_01cb: Unknown result type (might be due to invalid IL or missing references)
			//IL_01da: Unknown result type (might be due to invalid IL or missing references)
			self.TotalStatList.Clear();
			self.NextStatList.Clear();
			FaBao child = ((Entity)((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FaBaoModule>()).GetChild<FaBao>((long)self.FaBaoId);
			if (self.FuncId == 45003)
			{
				FaBaoLevelConfig levelConfig = FaBaoHelper.GetLevelConfig(((Entity)(object)self).LocalPlayer(), self.FaBaoId);
				int faBaoLevel = FaBaoHelper.GetFaBaoLevel(((Entity)(object)self).LocalPlayer(), self.FaBaoId);
				ConfigSingleton<FaBaoLevelConfigCategory>.Instance.GetLevelStat(self.FaBaoId, faBaoLevel, self.TotalStatList);
				FaBaoLevelConfig faBaoLevelConfig = FaBaoHelper.GetNextLevelConfig(((Entity)(object)self).LocalPlayer(), self.FaBaoId) ?? levelConfig;
				if (faBaoLevelConfig != null)
				{
					self.NextStatList.AddRange(self.TotalStatList);
					if (child == null || !child.IsMaxLevel)
					{
						self.NextStatList.AddRange(faBaoLevelConfig.BaseStats);
					}
					self.TotalStatList.AddRange(self.NextStatList);
				}
			}
			else if (self.FuncId == 45004 || self.FuncId == 45002)
			{
				FaBaoStarConfig starConfig = FaBaoHelper.GetStarConfig(((Entity)(object)self).LocalPlayer(), self.FaBaoId);
				if (starConfig != null)
				{
					self.TotalStatList.AddRange(starConfig.BaseStats);
				}
				FaBaoStarConfig faBaoStarConfig = FaBaoHelper.GetNextStarConfig(((Entity)(object)self).LocalPlayer(), self.FaBaoId) ?? starConfig;
				if (self.FuncId == 45002)
				{
					faBaoStarConfig = starConfig;
				}
				if (faBaoStarConfig != null)
				{
					self.TotalStatList.AddRange(faBaoStarConfig.BaseStats);
					self.NextStatList.AddRange(faBaoStarConfig.BaseStats);
				}
			}
			int num = 0;
			StatList totalStatList = self.TotalStatList;
			if (totalStatList != null && totalStatList.Count > 0)
			{
				num = (int)Math.Ceiling((float)self.TotalStatList.Count / 2f);
			}
			self._AttrUICommonList.SetData(num);
			self._AttrGo.Transform.sizeDelta = new Vector2(self._AttrGo.Transform.sizeDelta.x, (float)(50 * num));
		}

