		private static async void OnClickButton(this UIFaBaoDetailInfoPanel self)
		{
			switch (FaBaoHelper.CanUpByFuncId(((Entity)(object)self).LocalPlayer(), self.FaBaoId, self.FuncId))
			{
			case 200102:
			{
				ItemList itemList = new ItemList();
				switch (self.FuncId)
				{
				case 45002:
				{
					FaBaoStarConfig faBaoStarConfig = ConfigSingleton<FaBaoStarConfigCategory>.Instance.Get(self.FaBaoId, 0);
					itemList.AddRange(faBaoStarConfig.CostNum);
					break;
				}
				case 45004:
				{
					FaBaoStarConfig nextStarConfig = FaBaoHelper.GetNextStarConfig(((Entity)(object)self).LocalPlayer(), self.FaBaoId);
					itemList.AddRange(nextStarConfig.CostNum);
					break;
				}
				case 45003:
				{
					FaBaoLevelConfig levelConfig = FaBaoHelper.GetLevelConfig(((Entity)(object)self).LocalPlayer(), self.FaBaoId);
					UIGameMsgHelper.FloatMsg("升级材料不足");
					itemList.AddRange(levelConfig.CostNum);
					break;
				}
				}
				ItemModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>();
				{
					foreach (ItemStruct item in itemList)
					{
						if (!component.CheckItemNumsIsEnough(item.ConfigId, item.Nums))
						{
							UIObtainWayHelper.ShowPanelAsync(item.ConfigId, (int)item.Nums).Coroutine();
							break;
						}
					}
					break;
				}
			}
			case 0:
				if (self.FuncId == 45003)
				{
					IResponse response = await ((Entity)(object)self).LocalPlayer().Call(new C2L_RequestUpLevelFaBao
					{
						FaBaoConfigId = self.FaBaoId
					});
					if (response.Error != 0)
					{
						UIGameMsgHelper.FloatMsgByError(response.Error);
					}
					self._LevelEffect.PlayEffect("ui_fx_zhuangbeixiangqian_2");
					RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.FaBaoUpLevel, self.FaBaoId);
				}
				else if (self.FuncId == 45004)
				{
					IResponse response2 = await ((Entity)(object)self).LocalPlayer().Call(new C2L_RequestUpStarFaBao
					{
						FaBaoConfigId = self.FaBaoId
					});
					if (response2.Error != 0)
					{
						UIGameMsgHelper.FloatMsgByError(response2.Error);
					}
					RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.FaBaoUpStar, self.FaBaoId);
				}
				else if (self.FuncId == 45002)
				{
					IResponse response3 = await ((Entity)(object)self).LocalPlayer().Call(new C2L_RequestUnLockFaBao
					{
						FaBaoConfigId = self.FaBaoId
					});
					if (response3.Error != 0)
					{
						UIGameMsgHelper.FloatMsgByError(response3.Error);
					}
					RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.FaBaoInfo, self.FaBaoId);
					UIObject.FindUIObjectOfType<UIFaBaoInfoPanel>()?.InitTabInfos(45003);
					UIObject.FindUIObjectOfType<UIFaBaoListPanel>()?.UpdateView();
					break;
				}
				self.UpdateView();
				break;
			}
		}

		private static void OnAttrCellUpdate(this UIFaBaoDetailInfoPanel self, UIScrollListCell cell)
		{
			UIFaBaoAttrView component = ((Entity)cell.UIObject).GetComponent<UIFaBaoAttrView>();
			int index = cell.Index;
			int count = Math.Min(2, self.TotalStatList.Count - index * 2);
			StatList range = self.TotalStatList.GetRange(index * 2, count);
			StatList range2 = self.NextStatList.GetRange(index * 2, count);
			component.SetData(range, range2);
		}

		private static void OnSkillCellUpdate(this UIFaBaoDetailInfoPanel self, UIScrollListCell cell)
		{
			UIFaBaoSkillView component = ((Entity)cell.UIObject).GetComponent<UIFaBaoSkillView>();
			int index = cell.Index;
			int num = self.SkillIdList[index];
			UIFaBaoSkillViewSystem.SetData(currentLevel: num % 100, nextLevel: ((index < self.SkillNextIdList.Count) ? self.SkillNextIdList[index] : num) % 100, self: component, FaBaoId: self.FaBaoId, skillId: num);
		}

		private static void OnClickOwnerNode(this UIFaBaoDetailInfoPanel self)
		{
			if (self.FuncId == 45002)
			{
				FaBaoConfig faBaoConfig = ConfigSingleton<FaBaoConfigCategory>.Instance.Get(self.FaBaoId);
				if (faBaoConfig.HeroId != 0)
				{
					Hero hero = ((Entity)(object)UIManager.Instance).LocalPlayer().GetHero(faBaoConfig.HeroId);
					UIManager.Instance.Show<UIHeroMaxAttrPanel, Hero>(hero).Coroutine();
