		private static void OnClickSwitch(this UIFaBaoInfoPanel self, int direction)
		{
			List<int> list = UIObject.FindUIObjectOfType<UIFaBaoListPanel>()?.FaBaoSortIdList ?? new List<int>();
			int num = list.FindIndex((int c) => c == self.FaBaoId);
			num += direction;
			if (num >= 0 && num < list.Count)
			{
				self.FaBaoId = list[num];
				self.InitTabInfos(self.FuncId);
				self.InitView();
			}
		}

		public static void InitTabInfos(this UIFaBaoInfoPanel self, int FuncId = -1)
		{
			bool num = ((Entity)((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FaBaoModule>()).GetChild<FaBao>((long)self.FaBaoId) != null;
			if (self.TabInfos == null)
			{
				self.TabInfos = new List<UITabInfo>();
			}
			int[] array = (num ? self.ActiveTabInfos : self.UnActiveTabInfos);
			bool flag = false;
			if (self.TabInfos.Count != array.Length)
			{
				flag = true;
			}
			else if (self.TabInfos.Count > 0 && (self.TabInfos[0].GetArgs() as UIFaBaoShowArgs).FaBaoId != self.FaBaoId)
			{
				flag = true;
			}
			if (flag)
			{
				self.TabInfos.Clear();
				int[] array2 = array;
				foreach (int funcId in array2)
				{
