		private static void UpdateData(this UIFaBaoListPanel self)
		{
			Player player = ((Entity)(object)self).LocalPlayer();
			self.FaBaoSortIdList.Sort(delegate(int a, int b)
			{
				bool flag = FaBaoHelper.CanUnLock(player, a) == 0;
				bool flag2 = FaBaoHelper.CanUnLock(player, b) == 0;
				if (flag && !flag2)
				{
					return -1;
				}
				if (!flag & flag2)
				{
					return 1;
				}
				bool flag3 = FaBaoHelper.CanUp(player, a);
				bool flag4 = FaBaoHelper.CanUp(player, b);
				if (flag3 && !flag4)
				{
					return -1;
				}
				if (!flag3 & flag4)
				{
					return 1;
				}
				FaBao child = ((Entity)((Entity)player).GetComponent<FaBaoModule>()).GetChild<FaBao>((long)a);
				FaBao child2 = ((Entity)((Entity)player).GetComponent<FaBaoModule>()).GetChild<FaBao>((long)b);
				if (child != null && child2 == null)
				{
					return -1;
				}
				if (child == null && child2 != null)
				{
					return 1;
				}
				FaBaoConfig faBaoConfig = ConfigSingleton<FaBaoConfigCategory>.Instance.Get(a);
				FaBaoConfig faBaoConfig2 = ConfigSingleton<FaBaoConfigCategory>.Instance.Get(b);
				if (faBaoConfig.Quality != faBaoConfig2.Quality)
				{
					return faBaoConfig2.Quality.CompareTo(faBaoConfig.Quality);
				}
				if (faBaoConfig.HeroId != faBaoConfig2.HeroId)
				{
					return faBaoConfig2.HeroId.CompareTo(faBaoConfig.HeroId);
				}
				long power = FaBaoHelper.GetPower(player, a, FaBaoHelper.GetFaBaoLevel(player, a), FaBaoHelper.GetFaBaoStar(player, b));
				long power2 = FaBaoHelper.GetPower(player, a, FaBaoHelper.GetFaBaoLevel(player, b), FaBaoHelper.GetFaBaoStar(player, b));
				return (power != power2) ? power2.CompareTo(power) : faBaoConfig2.Id.CompareTo(faBaoConfig2.Id);
			});
		}

