		public static void OnShow(this UIFaBaoSelectHeroListPanel self, int FaBaoId)
		{
			self.HeroList = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<HeroModule>().GetHeroes(new HeroSearch
			{
				Includes = HeroInclude.All,
				SortType = HeroSortType.VibesHeroList,
				OnlyActive = true
			});
			self.FaBaoId = FaBaoId;
			self.HeroCardInfoList.Clear();
			self.UpdateData();
			self.SelectedHeroCardIndex = 0;
			for (int i = 0; i < self.HeroList.Count; i++)
			{
				if (self.HeroList[i].FaBaoList.Contains(self.FaBaoId))
				{
					self.SelectedHeroCardIndex = i;
