			self.UpdateButton();
		}

		private static void UpdateData(this UIFaBaoSelectHeroListPanel self)
		{
			Player player = ((Entity)(object)self).LocalPlayer();
			for (int i = 0; i < self.HeroList.Count; i++)
			{
				Hero hero = self.HeroList[i];
				if (i >= self.HeroCardInfoList.Count)
				{
					HeroCardInfo heroCardInfo = new HeroCardInfo
					{
						HeroId = ((Entity)hero).Id,
						ConfigId = hero.ConfigId,
						Star = hero.Star,
						Level = player.GetHeroLvById(hero.ConfigId),
						Power = hero.GetPower(),
						HeroSkinId = hero.CurrentSkin,
						HeroFaBaoIds = hero.FaBaoList
					};
					if (hero.IsRole())
					{
						heroCardInfo.Star = ((Entity)(object)self).LocalPlayer().GetPracticeLevel();
					}
					self.HeroCardInfoList.Add(heroCardInfo);
				}
				else
				{
					self.HeroCardInfoList[i].HeroFaBaoIds = hero.FaBaoList;
					self.HeroCardInfoList[i].Power = hero.GetPower();
				}
			}
		}

		private static void UpdateButton(this UIFaBaoSelectHeroListPanel self)
		{
			HeroCardInfo heroCardInfo = self.HeroCardInfoList[self.SelectedHeroCardIndex];
			self._WearingButton.SetActive(active: false);
			self._ReplaceButton.SetActive(active: false);
			self._UnLoadButton.SetActive(active: false);
			if (heroCardInfo.HeroFaBaoIds.Contains(self.FaBaoId))
			{
				self._UnLoadButton.SetActive(active: true);
			}
			else if (heroCardInfo.HeroFaBaoIds.Count < 2)
			{
				self._WearingButton.SetActive(active: true);
			}
			else if (heroCardInfo.HeroFaBaoIds.Count >= 2)
			{
				self._ReplaceButton.SetActive(active: true);
			}
		}

