		private static void OnClickSkillIcon(this UIFaBaoSkillView self)
		{
			int currentStar = self.CurrentStar;
			ItemConfig itemConfig = ConfigSingleton<ItemConfigCategory>.Instance.Get(self.FaBaoId);
			Dictionary<int, List<SkillLevel>> dictionary = new Dictionary<int, List<SkillLevel>>();
			Dictionary<int, int[]> dictionary2 = new Dictionary<int, int[]>();
			int num = 0;
			FaBaoStarConfig faBaoStarConfig = ConfigSingleton<FaBaoStarConfigCategory>.Instance.Get(self.FaBaoId, num);
			int num2 = 0;
			int item = 0;
			while (faBaoStarConfig != null)
			{
				if (self.SkillId == faBaoStarConfig.SkillIds / 100)
				{
					if (num2 != faBaoStarConfig.SkillIds)
					{
						SkillLevel item2 = new SkillLevel(faBaoStarConfig.SkillIds);
						if (item2.Level == self.SkillLevel)
						{
							item = faBaoStarConfig.Star;
						}
						dictionary.Add(faBaoStarConfig.Star, new List<SkillLevel> { item2 });
					}
					if (currentStar >= faBaoStarConfig.Star)
					{
						dictionary2.Add(faBaoStarConfig.Star, new int[1] { faBaoStarConfig.SkillIds });
					}
					num2 = faBaoStarConfig.SkillIds;
				}
				else if (self.SkillId == faBaoStarConfig.MasterSkillId / 100)
				{
					if (num2 != faBaoStarConfig.MasterSkillId)
					{
						SkillLevel item3 = new SkillLevel(faBaoStarConfig.MasterSkillId);
						if (item3.Level == self.SkillLevel)
						{
							item = faBaoStarConfig.Star;
						}
						dictionary.Add(faBaoStarConfig.Star, new List<SkillLevel> { item3 });
					}
					if (currentStar >= faBaoStarConfig.Star)
					{
						dictionary2.Add(faBaoStarConfig.Star, new int[1] { faBaoStarConfig.MasterSkillId });
					}
					num2 = faBaoStarConfig.MasterSkillId;
				}
				num++;
				faBaoStarConfig = ConfigSingleton<FaBaoStarConfigCategory>.Instance.Get(self.FaBaoId, num);
			}
			((Entity)((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FaBaoModule>()).GetChild<FaBao>((long)self.FaBaoId);
			UIManager.Instance.Show<UIHeroJewelrySkillPanel, (Dictionary<int, List<SkillLevel>>, int, int, int, Dictionary<int, int[]>)>((dictionary, item, itemConfig.Quality, 2, dictionary2)).Coroutine();
		}

		public static void SetData(this UIFaBaoSkillView self, int FaBaoId, int skillId, int currentLevel, int nextLevel)
		{
			//IL_022b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0117: Unknown result type (might be due to invalid IL or missing references)
			//IL_011c: Unknown result type (might be due to invalid IL or missing references)
			self.FaBaoId = FaBaoId;
			SkillLevel skillLevel = new SkillLevel(skillId);
			self.SkillId = skillLevel.SkillId;
			self.SkillLevel = skillLevel.Level;
			self._SkillIcon.SetRawTexture(skillLevel.Icon()).Coroutine();
			self._SkillDes.SetText(skillLevel.Description());
			string arg = skillLevel.Name();
			bool active = nextLevel > currentLevel;
			self._NextArrow.SetActive(active);
			self._NextLevel.SetActive(active);
			self._SkillName.SetText($"{arg}  <size=26>{currentLevel}级</size>");
			self._NextLevel.SetText($"{nextLevel}级");
			FaBaoStarConfig starConfig = FaBaoHelper.GetStarConfig(((Entity)(object)self).LocalPlayer(), FaBaoId);
			self.CurrentStar = starConfig.Star;
			FaBaoConfig faBaoConfig = ConfigSingleton<FaBaoConfigCategory>.Instance.Get(FaBaoId);
			bool flag = starConfig.MasterSkillId == skillId;
			self._OwnerNode.SetActive(flag);
			self._MasterFlag.SetActive(flag);
			if (flag)
			{
				self._SkillName.SetColor(Color32.op_Implicit(new Color32(byte.MaxValue, (byte)232, (byte)81, byte.MaxValue)));
				self._SkillName.SetOutlineColor("#813F22");
				HeroConfig heroConfig = ConfigSingleton<HeroConfigCategory>.Instance.Get(faBaoConfig.HeroId);
				self._OwnerText.SetText("专属：" + heroConfig.HeroName);
				FaBao child = ((Entity)((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FaBaoModule>()).GetChild<FaBao>((long)FaBaoId);
				if (child != null && child.Owner == faBaoConfig.HeroId)
				{
					self._NoActive.SetActive(active: false);
					self._OwnerText.SetText("已激活");
					self._OwnerNode.SetSprite("ui_fb_wp_02").Coroutine();
				}
				else
				{
					self._NoActive.SetActive(active: true);
					self._OwnerNode.SetSprite("ui_fab_frame05").Coroutine();
				}
				self._SkillFrame.SetSprite("ui_fb_jn_02").Coroutine();
			}
			else
			{
				self._SkillFrame.SetSprite("ui_fb_jn_01").Coroutine();
				self._NoActive.SetActive(active: false);
				self._SkillName.SetColor(Color.white);
				self._SkillName.SetOutlineColor("#263248");
			}
		}
	}
