		[UIMethod]
		private static void OnAwake(this UIFaBaoSoulDecomposePanel self)
		{
			self._DecomposeButton.AddClickHandler(self.ClickDecomposeButton);
			self._UIScrollList.Handler.onCreate += self.OnScrollCellCreate;
			self._UIScrollList.Handler.onUpdate += self.OnScrollCellUpdate;
			self._UICommonList.Handler.onUpdate += self.OnCommonCellUpdate;
			self.CheckBoxList = new List<UIObject> { self._CheckBox1, self._CheckBox2, self._CheckBox3 };
			int[] decompose = ConfigSingleton<FaBaoGlobalConfigCategory>.Instance.GetOne().Decompose;
			self.Quality = decompose.Max();
			for (int i = 0; i < self.CheckBoxList.Count; i++)
			{
				if (i >= decompose.Length)
				{
					self.CheckBoxList[i].SetActive(active: false);
					continue;
				}
				int index = i;
				self.CheckBoxList[i].GameObject.GetComponent<SuperToggle>().SetValueChangeCallback((UnityAction<bool>)delegate(bool isOn)
				{
					self.OnValueChange(index, isOn);
				});
				FaBaoQualityConfig faBaoQualityConfig = ConfigSingleton<FaBaoQualityConfigCategory>.Instance.Get(decompose[index]);
				((Text)((Component)((Transform)self.CheckBoxList[i].Transform).GetChild(1)).gameObject.GetComponent<SuperText>()).text = faBaoQualityConfig.Name;
			}
		}

		[UIMethod]
		private static void OnShow(this UIFaBaoSoulDecomposePanel self)
		{
			self.InitView();
		}

		private static void InitView(this UIFaBaoSoulDecomposePanel self)
		{
			self.UpdateData();
			self.UpdateView();
		}

		private static void UpdateData(this UIFaBaoSoulDecomposePanel self)
		{
			self.FaBaoSoulIdList = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FaBaoSoulModule>().GetSoulIdsBySearch(new FaBaoSoulSearchStruct
			{
				LoadType = 0,
				Quality = self.Quality,
				IsEquip = false,
				IsSort = false
			});
		}

		private static void UpdateView(this UIFaBaoSoulDecomposePanel self)
		{
			self._UIScrollList.SetData(self.FaBaoSoulIdList.Count);
			self.DecomposeItemList = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FaBaoSoulModule>().GetDecomposeItemList(self.SelectedIdList, IsDecompose: true);
			self._DecomposeButton.SetGray(self.DecomposeItemList.Count <= 0);
			self._UICommonList.SetData(self.DecomposeItemList.Count);
		}

		private static async void ClickDecomposeButton(this UIFaBaoSoulDecomposePanel self)
		{
			if (self.SelectedIdList.Count <= 0)
			{
				UIGameMsgHelper.FloatMsg("当前无勾选");
				return;
			}
			IResponse response = await ((Entity)(object)self).LocalPlayer().Call(new C2L_RequestDecomposeFaBaoSoul
			{
				FaBaoSoulIds = self.SelectedIdList
			});
			if (response.Error != 0)
			{
				UIGameMsgHelper.FloatMsgByError(response.Error);
				return;
			}
			self.SelectedIdList.Clear();
			self.InitView();
		}

		private static void OnScrollCellUpdate(this UIFaBaoSoulDecomposePanel self, UIScrollListCell cell)
		{
			UIFaBaoSoulItem component = ((Entity)cell.UIObject).GetComponent<UIFaBaoSoulItem>();
			long num = self.FaBaoSoulIdList[cell.Index];
			FaBaoSoul child = ((Entity)((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FaBaoSoulModule>()).GetChild<FaBaoSoul>(num);
			component.SetItem(child.ConfigId, child.Star, self.SelectedIdList.IndexOf(num) != -1, child.Level);
		}

		private static void OnScrollCellCreate(this UIFaBaoSoulDecomposePanel self, UIScrollListCell cell)
		{
			UIFaBaoSoulItem component = ((Entity)cell.UIObject).GetComponent<UIFaBaoSoulItem>();
			component._UICommonItem.UIObject.AddClickHandler(delegate
			{
				self.OnClickScrollCellItem(cell.Index);
			});
			component._UICommonItem.UIObject.AddKeepHandler(delegate
			{
				self.OnLongPressItem(cell.Index);
			});
		}

		private static void OnClickScrollCellItem(this UIFaBaoSoulDecomposePanel self, int index)
		{
			if (self._UIScrollList.GetCell(index) != null)
			{
				long item = self.FaBaoSoulIdList[index];
				if (self.SelectedIdList.Contains(item))
				{
					self.SelectedIdList.Remove(item);
				}
				else
				{
					self.SelectedIdList.Add(item);
				}
				self.UpdateView();
			}
		}

		private static void OnLongPressItem(this UIFaBaoSoulDecomposePanel self, int index)
		{
			long num = self.FaBaoSoulIdList[index];
			FaBaoSoul child = ((Entity)((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FaBaoSoulModule>()).GetChild<FaBaoSoul>(num);
			UICommonHelper.ShowItemTip(new ItemStruct
			{
				ConfigId = child.ConfigId
			});
		}

		private static void OnCommonCellUpdate(this UIFaBaoSoulDecomposePanel self, UIScrollListCell cell)
		{
			((Entity)cell.UIObject).GetComponent<UICommonItem>().SetItem(self.DecomposeItemList[cell.Index]);
		}

		private static void OnValueChange(this UIFaBaoSoulDecomposePanel self, int index, bool isOn)
		{
			int[] decompose = ConfigSingleton<FaBaoGlobalConfigCategory>.Instance.GetOne().Decompose;
			if (index >= decompose.Length)
			{
				return;
			}
			foreach (long faBaoSoulId in self.FaBaoSoulIdList)
			{
				if (((Entity)((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FaBaoSoulModule>()).GetChild<FaBaoSoul>(faBaoSoulId).ItemConfig.Quality != decompose[index])
				{
					continue;
				}
				if (isOn)
				{
					if (self.SelectedIdList.IndexOf(faBaoSoulId) == -1)
					{
						self.SelectedIdList.Add(faBaoSoulId);
					}
				}
				else
				{
					self.SelectedIdList.Remove(faBaoSoulId);
				}
			}
			self.UpdateView();
		}
	}
