		private static void ShowSkillTips(this UIFaBaoSoulDevelopInfoPanel self)
		{
			long faBaoSoulIdByPosition = self.FaBao.GetFaBaoSoulIdByPosition(self.Position);
			FaBaoSoul child = ((Entity)((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FaBaoSoulModule>()).GetChild<FaBaoSoul>(faBaoSoulIdByPosition);
			if (child.Config.SkillLevelId == 0)
			{
				return;
			}
			ItemConfig itemConfig = ConfigSingleton<ItemConfigCategory>.Instance.Get(child.ConfigId);
			int quality = itemConfig.Quality;
			Dictionary<int, List<SkillLevel>> dictionary = new Dictionary<int, List<SkillLevel>>();
			Dictionary<int, int[]> dictionary2 = new Dictionary<int, int[]>();
			List<(int, int)> qualityIds = ConfigSingleton<FaBaoSoulConfigCategory>.Instance.GetQualityIds(child.Config.SkillLevelId / 100);
			if (qualityIds == null)
			{
				return;
			}
			foreach (var item in qualityIds)
			{
				dictionary.Add(item.Item2, new List<SkillLevel>
				{
					new SkillLevel(item.Item1)
				});
				if (quality >= item.Item2)
				{
					dictionary2.Add(item.Item2, new int[1] { item.Item1 });
				}
			}
			UIManager.Instance.Show<UIHeroJewelrySkillPanel, (Dictionary<int, List<SkillLevel>>, int, int, int, Dictionary<int, int[]>)>((dictionary, quality, itemConfig.Quality, 3, dictionary2)).Coroutine();
		}

