		private static void UpdateSoulInfo(this UIFaBaoSoulDevelopInfoPanel self)
		{
			long faBaoSoulIdByPosition = self.FaBao.GetFaBaoSoulIdByPosition(self.Position);
			FaBaoSoul child = ((Entity)((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FaBaoSoulModule>()).GetChild<FaBaoSoul>(faBaoSoulIdByPosition);
			if (child == null)
			{
				return;
			}
			ItemConfig itemConfig = ConfigSingleton<ItemConfigCategory>.Instance.Get(child.ConfigId);
			self._SoulIcon.SetRawTexture($"uitex_icon_item_{itemConfig.Icon}").Coroutine();
			self._LevelText.SetText($"{child.Level}级");
			self._UpLevelInfo.SetActive(45006 == self.FuncId);
			if (45006 == self.FuncId)
			{
				bool isMaxLevel = child.IsMaxLevel;
				self._UpLevelArrow.SetActive(!isMaxLevel);
				self._NextLevelText.SetActive(!isMaxLevel);
				self._CurLevelText.SetText($"{child.Level}级");
				SuperText component = self._CurLevelText.GameObject.GetComponent<SuperText>();
				if (!isMaxLevel)
				{
					self._NextLevelText.SetText($"{Math.Min(child.Level + 1, child.NextLevelConfig.LevelUpValue)}级");
					((Text)component).alignment = (TextAnchor)5;
				}
				else
				{
					((Text)component).alignment = (TextAnchor)4;
				}
			}
			if (45007 == self.FuncId)
			{
				bool isMaxStar = child.IsMaxStar;
				self._NextUIHeroStar.UIObject.SetActive(!isMaxStar);
				self._UpStarArrow.SetActive(!isMaxStar);
				if (!isMaxStar)
				{
					self._NextUIHeroStar.SetStar(child.Star + 1, showBackground: true);
				}
			}
