			LayoutRebuilder.ForceRebuildLayoutImmediate(self._PosInfo.Transform);
			((Transform)self._SelectIcon.Transform).localPosition = ((Transform)self.PosItems[PosIndex - 1].UIObject.Transform).localPosition;
			UIObject.FindUIObjectOfType<UIFaBaoSoulDevelopPanel>()?.UpdateSelectPosition(self.Position);
