		private static async void OnClickUnloadButton(this UIFaBaoSoulItemTipsPanel self)
		{
			int Position = self.FaBaoSoul.Position;
			int num = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FaBaoSoulModule>().FaBaoChangeWearingSoul(((Entity)self.FaBaoSoul).Id, 0, Position);
			if (num != 0)
			{
				UIGameMsgHelper.FloatMsgByError(num);
				return;
			}
			L2C_ResponseWearingFaBaoSoul l2C_ResponseWearingFaBaoSoul = (L2C_ResponseWearingFaBaoSoul)(await ((Entity)(object)self).LocalPlayer().Call(new C2L_RequestWearingFaBaoSoul
			{
				FaBaoSoulId = ((Entity)self.FaBaoSoul).Id,
				FaBaoId = 0,
				Position = Position
			}));
			if (l2C_ResponseWearingFaBaoSoul.Error != 0)
			{
				UIGameMsgHelper.FloatMsgByError(l2C_ResponseWearingFaBaoSoul.Error);
				return;
			}
			UIGameMsgHelper.FloatMsg("卸下成功");
			Singleton<EventSystem>.Instance.Publish<FaBaoSoulPositionChange>(SceneHelper.DomainScene((Entity)(object)self), new FaBaoSoulPositionChange
			{
				FaBaoId = 0,
				Position = Position
			});
			UIManager.Instance.Remove(typeof(UIFaBaoSoulItemTipsPanel));
		}

		private static void OnClickSkillShow(this UIFaBaoSoulItemTipsPanel self)
		{
			ItemConfig itemConfig = ConfigSingleton<ItemConfigCategory>.Instance.Get(self.FaBaoSoul.ConfigId);
			int quality = itemConfig.Quality;
			Dictionary<int, List<SkillLevel>> dictionary = new Dictionary<int, List<SkillLevel>>();
			Dictionary<int, int[]> dictionary2 = new Dictionary<int, int[]>();
			List<(int, int)> qualityIds = ConfigSingleton<FaBaoSoulConfigCategory>.Instance.GetQualityIds(self.FaBaoSoul.Config.SkillLevelId / 100);
			if (qualityIds == null)
			{
				return;
			}
			foreach (var item in qualityIds)
			{
				dictionary.Add(item.Item2, new List<SkillLevel>
				{
					new SkillLevel(item.Item1)
				});
				if (quality >= item.Item2)
				{
					dictionary2.Add(item.Item2, new int[1] { item.Item1 });
				}
			}
			UIManager.Instance.Show<UIHeroJewelrySkillPanel, (Dictionary<int, List<SkillLevel>>, int, int, int, Dictionary<int, int[]>)>((dictionary, quality, itemConfig.Quality, 3, dictionary2)).Coroutine();
		}
