		private static void UpdateButton(this UIFaBaoSoulPanel self)
		{
			//IL_001f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0025: Unknown result type (might be due to invalid IL or missing references)
			//IL_0028: Unknown result type (might be due to invalid IL or missing references)
			//IL_002e: Unknown result type (might be due to invalid IL or missing references)
			//IL_00fc: Unknown result type (might be due to invalid IL or missing references)
			//IL_0102: Unknown result type (might be due to invalid IL or missing references)
			//IL_0105: Unknown result type (might be due to invalid IL or missing references)
			//IL_010b: Unknown result type (might be due to invalid IL or missing references)
			if (((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FaBaoSoulModule>().GetSoulCount() == 0)
			{
				self._Button.SetButtonText("前往获得");
				self.ButtonState = 1;
				return;
			}
			long num = 0L;
			List<long> soulIdList = self.FaBao.GetSoulIdList();
			int num2 = FaBaoHelper.GetFaBaoUnLockPosList(((Entity)(object)self).LocalPlayer(), self.FaBaoId)?.Count ?? 0;
			if (soulIdList != null)
			{
				if (num2 > soulIdList.Count)
				{
					num = 0L;
				}
				else
				{
					foreach (long item in soulIdList)
					{
						FaBaoSoul child = ((Entity)((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FaBaoSoulModule>()).GetChild<FaBaoSoul>(item);
						if (num == 0L)
						{
							num = child.GetPower();
						}
						num = Math.Min(num, child.GetPower());
					}
				}
			}
			self.ReplaceIds = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FaBaoSoulModule>().GetReplaceIdsByFaBao(self.FaBaoId);
			self._Button.SetButtonText("一键穿戴");
			self._Button.SetGray(self.ReplaceIds.Count <= 0);
			self.ButtonState = ((self.ReplaceIds.Count > 0) ? 2 : 3);
		}

		private static async void OnClickButton(this UIFaBaoSoulPanel self)
		{
			if (self.ButtonState.Equals(1))
			{
				UIManager.Instance.Show<UIFaBaoPanel, int>(45008).Coroutine();
			}
			else
			{
				if (self.ButtonState.Equals(3) || !self.ButtonState.Equals(2))
				{
					return;
				}
				if (self.ReplaceIds.Count == 0)
				{
					UIGameMsgHelper.FloatMsgByError(207652);
					return;
				}
				List<int> faBaoUnLockPosList = FaBaoHelper.GetFaBaoUnLockPosList(((Entity)(object)self).LocalPlayer(), self.FaBaoId);
				if (faBaoUnLockPosList == null || faBaoUnLockPosList.Count <= 0)
				{
					UIGameMsgHelper.FloatMsgByError(200035);
					return;
				}
				int count = Math.Min(faBaoUnLockPosList.Count, self.ReplaceIds.Count);
				self.ReplaceIds = self.ReplaceIds.GetRange(0, count);
				foreach (long replaceId in self.ReplaceIds)
				{
					FaBaoSoul child = ((Entity)((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FaBaoSoulModule>()).GetChild<FaBaoSoul>(replaceId);
					Log.Info($"ReplaceIds:{child.Config.LoadType}");
				}
				IResponse response = await ((Entity)(object)self).LocalPlayer().Call(new C2L_RequestOneClickWearFaBaoSoul
				{
					FaBaoId = self.FaBaoId,
					FaBaoSoulIds = self.ReplaceIds
				});
				if (response.Error != 0)
				{
					UIGameMsgHelper.FloatMsgByError(response.Error);
					return;
				}
				if (self.FaBao.Owner != 0)
				{
					((Entity)(object)self).LocalPlayer().UpdateHeroStats(self.FaBao.Owner, StatBagType.FaBao);
				}
				RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.FaBaoSoul, self.FaBaoId);
				self.UpdateView();
			}
		}

		private static void UpdateAttr(this UIFaBaoSoulPanel self)
		{
			//IL_00aa: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b9: Unknown result type (might be due to invalid IL or missing references)
			int soulCount = self.FaBao.GetSoulCount();
			self._AttrGo.SetActive(soulCount > 0);
			self._TipsText.SetActive(soulCount <= 0);
			if (soulCount > 0)
			{
				self.TotalStatList.Clear();
				self.NextStatList.Clear();
				self.FaBao.GetStatList(self.TotalStatList);
				int num = 0;
				StatList totalStatList = self.TotalStatList;
				if (totalStatList != null && totalStatList.Count > 0)
				{
					num = (int)Math.Ceiling((float)self.TotalStatList.Count / 2f);
				}
				self._AttrUICommonList.SetData(num);
				self._Content.Transform.sizeDelta = new Vector2(self._Content.Transform.sizeDelta.x, (float)(50 * num));
			}
		}

		private static void OnAttrCellUpdate(this UIFaBaoSoulPanel self, UIScrollListCell cell)
		{
			UIFaBaoAttrView component = ((Entity)cell.UIObject).GetComponent<UIFaBaoAttrView>();
			int index = cell.Index;
			int count = Math.Min(2, self.TotalStatList.Count - index * 2);
			StatList range = self.TotalStatList.GetRange(index * 2, count);
			component.SetData(range);
		}

		private static void OnClickPosItem(this UIFaBaoSoulPanel self, int PosIndex)
		{
			FaBaoPosUnLockConfig faBaoPosUnLockConfig = ConfigSingleton<FaBaoPosUnLockConfigCategory>.Instance.Get(PosIndex);
			int quality = self.FaBao.Config.Quality;
			_ = self.FaBao.Star;
			if (!self.FaBao.IsPositionUnlocked(PosIndex))
			{
				int num = faBaoPosUnLockConfig.Condition / 100;
				int num2 = faBaoPosUnLockConfig.Condition % 100;
				if (quality < num)
				{
					UIGameMsgHelper.FloatMsg(ConfigSingleton<FaBaoQualityConfigCategory>.Instance.Get(num).Name + "解锁");
				}
				else if (self.FaBao.Star < num2)
				{
					UIGameMsgHelper.FloatMsg($"{num2}星解锁");
				}
			}
			else
			{
				long faBaoSoulIdByPosition = self.FaBao.GetFaBaoSoulIdByPosition(PosIndex);
				if (((Entity)((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FaBaoSoulModule>()).GetChild<FaBaoSoul>(faBaoSoulIdByPosition) == null)
				{
					UIManager.Instance.Show<UIFaBaoSoulSwitchPanel, (int, int)>((self.FaBaoId, PosIndex)).Coroutine();
				}
				else
				{
					UIManager.Instance.Show<UIFaBaoSoulItemTipsPanel, long>(faBaoSoulIdByPosition).Coroutine();
				}
			}
		}
	}
