		public static void SetData(this UIFaBaoSoulPosItem self, int FaBaoId, long FaBaoSoulId, int Index)
		{
			FaBaoPosUnLockConfig faBaoPosUnLockConfig = ConfigSingleton<FaBaoPosUnLockConfigCategory>.Instance.Get(Index);
			FaBao child = ((Entity)((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FaBaoModule>()).GetChild<FaBao>((long)FaBaoId);
			int quality = child.Config.Quality;
			_ = child.Star;
			bool flag = !child.IsPositionUnlocked(faBaoPosUnLockConfig.Id);
			self._AddImage.SetActive(!flag);
			self._LockImage.SetActive(flag);
			self._SoulInfo.SetActive(!flag);
			self.UIObject.SetRedPoint(RedPointType.FaBaoSoulCanUp, FaBaoId, Index).Coroutine();
			if (flag)
			{
				int num = faBaoPosUnLockConfig.Condition / 100;
				int num2 = faBaoPosUnLockConfig.Condition % 100;
				if (quality < num)
				{
					FaBaoQualityConfig faBaoQualityConfig = ConfigSingleton<FaBaoQualityConfigCategory>.Instance.Get(num);
					self._UnLockText.SetText(faBaoQualityConfig.Name + "解锁");
				}
				else if (child.Star < num2)
				{
					self._UnLockText.SetText($"{num2}星解锁");
				}
				return;
			}
			FaBaoSoul child2 = ((Entity)((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FaBaoSoulModule>()).GetChild<FaBaoSoul>(FaBaoSoulId);
			self._AddImage.SetActive(child2 == null);
			self._SoulInfo.SetActive(child2 != null);
			if (child2 == null)
			{
				self._HeroStarArea.SetStar(0);
				return;
			}
			self._HeroStarArea.SetStar(child2.Star);
			ItemConfig itemConfig = ConfigSingleton<ItemConfigCategory>.Instance.Get(child2.Config.Id);
			self._Icon.SetRawTexture($"uitex_icon_item_{itemConfig.Icon}").Coroutine();
			self._LevelText.SetText($"{child2.Level}级");
		}
	}
