		[UIMethod]
		private static void OnAwake(this UIFaBaoSoulUpStarUsePanel self)
		{
			self._UIScrollList.Handler.onUpdate += self.OnCellUpdate;
			self._UIScrollList.SpaceY = 5f;
			self._Button.AddClickHandler(self.OnClickButton);
