		public static void OnClickButton(this UIFaBaoSoulUpStarUsePanel self)
		{
			UIFaBaoSoulDevelopInfoPanel[] array = UIObject.FindUIObjectsOfType<UIFaBaoSoulDevelopInfoPanel>();
			if (array != null && array.Length > 0)
			{
				UIFaBaoSoulDevelopInfoPanel[] array2 = array;
				for (int i = 0; i < array2.Length; i++)
				{
					array2[i].UpdateSelectedFaBaoIds(self.SelectedFaBaoSoulIdList);
				}
			}
			UIManager.Instance.Remove(typeof(UIFaBaoSoulUpStarUsePanel));
		}

		public static void OnUpdateSelected(this UIFaBaoSoulUpStarUsePanel self, long soulId)
		{
			if (self.SelectedFaBaoSoulIdList.Contains(soulId))
			{
				self.SelectedFaBaoSoulIdList.Remove(soulId);
			}
			else
			{
				if (self.SelectedFaBaoSoulIdList.Count >= self.MaxCount)
				{
					UIGameMsgHelper.FloatMsg("勾选材料已满足");
					return;
				}
				self.SelectedFaBaoSoulIdList.Add(soulId);
			}
			self._UIScrollList.RefreshView();
			self.UpdateContentText();
		}

		[UIMethod]
		private static void OnShow(this UIFaBaoSoulUpStarUsePanel self, (long soulId, List<long> selectSoulId) args)
		{
			FaBaoSoul child = ((Entity)((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FaBaoSoulModule>()).GetChild<FaBaoSoul>(args.soulId);
			self.SelectedFaBaoSoulIdList = args.selectSoulId.Clone();
			if (self.SelectedFaBaoSoulIdList == null)
			{
				self.SelectedFaBaoSoulIdList = new List<long>();
			}
			self.MaxCount = child.StarConfig.CostNum[0].Nums;
			self.FaBaoSoulIdList = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FaBaoSoulModule>().GetSoulIdsBySearch(new FaBaoSoulSearchStruct
			{
				FaBaoSoulConfigId = child.ConfigId,
				IsSort = true
			});
			self._UIScrollList.SetData(self.FaBaoSoulIdList.Count);
			self._ListEmpty.SetActive(self.FaBaoSoulIdList.Count <= 0);
			self.UpdateContentText();
		}

		private static void UpdateContentText(this UIFaBaoSoulUpStarUsePanel self)
		{
			int count = self.SelectedFaBaoSoulIdList.Count;
			string text = string.Format("<color={0}>{1}</color>/{2}", (self.MaxCount > count) ? "#ff3232" : "#5dfa49", count, self.MaxCount);
			self._ContenText.SetText("已选择：" + text);
		}

		private static void OnCellUpdate(this UIFaBaoSoulUpStarUsePanel self, UIScrollListCell cell)
		{
			UIFaBaoSoulSwitchItem component = ((Entity)cell.UIObject).GetComponent<UIFaBaoSoulSwitchItem>();
			long num = self.FaBaoSoulIdList[cell.Index];
			component.SetData(num, 0);
			component.SetCheckBox(self.SelectedFaBaoSoulIdList.Contains(num));
		}
	}
