		private static void UpdateFaBaoExpressInfo(this UIFaBaoSuccessPanel self)
		{
			//IL_00d4: Unknown result type (might be due to invalid IL or missing references)
			//IL_00e9: Unknown result type (might be due to invalid IL or missing references)
			//IL_00fe: Unknown result type (might be due to invalid IL or missing references)
			//IL_0108: Unknown result type (might be due to invalid IL or missing references)
			if (self.SuccessType == UISuccessType.FaBaoUnlock)
			{
				self._TitleGo.SetActive(active: true);
			}
			else
			{
				if (self.SuccessType != UISuccessType.FaBaoUpStar)
				{
					return;
				}
				self._UICommonPower.UIObject.SetActive(active: true);
				self._UICommonPower.SetPower(FaBaoHelper.GetPower(((Entity)(object)self).LocalPlayer(), self.FaBao.ConfigId, self.FaBao.Level, self.FaBao.Star));
				self._StarGo.SetActive(active: true);
				if (self.FaBao.IsMaxStar || self.FaBao.Star == 1)
				{
					self._NextArrow.SetActive(active: false);
					self._UIHeroEffectStarBefore.UIObject.SetActive(active: false);
					RectTransform component = self._UIHeroEffectStarAfter.UIObject.GameObject.GetComponent<RectTransform>();
					component.pivot = new Vector2(0.5f, 0.5f);
					component.anchorMin = new Vector2(0.5f, 0.5f);
					component.anchorMax = new Vector2(0.5f, 0.5f);
					((Transform)component).localPosition = Vector3.zero;
					if (self.FaBao.Star == 1)
					{
						self._UIHeroEffectStarAfter.SetStar(self.FaBao.Star, showBackground: false, showEffect: true);
						return;
					}
				}
				else
				{
					self._UIHeroEffectStarBefore.SetStar(self.BeforeStar, showBackground: false, showEffect: true);
				}
				self._UIHeroEffectStarAfter.SetStar(self.AfterStar, showBackground: false, showEffect: true);
			}
		}

		public static void RefreshView(this UIFaBaoSuccessPanel self)
