					else
					{
						o.Find("txtAttrValue").SetText(str2);
					}
					((Component)o.Transform).GetComponent<CanvasGroup>().alpha = 0f;
					((Component)o.Transform).gameObject.SetActive(false);
					attrItemList.Add(o);
