				foreach (UIObject item in attrItemList)
				{
					_ = item;
					int capturedIndex = num2;
					TweenSettingsExtensions.AppendCallback(val, (TweenCallback)delegate
					{
						((Component)attrItemList[capturedIndex].Transform).gameObject.SetActive(true);
					});
