					}
				}
				Sequence fadeSequence = self.DOSequence();
				for (int num3 = 0; num3 < attrItemList.Count; num3++)
				{
					UIObject uIObject = attrItemList[num3];
					TweenSettingsExtensions.Insert(fadeSequence, (float)num3 * 0.05f, (Tween)(object)DOTweenModuleUI.DOFade(((Component)uIObject.Transform).GetComponent<CanvasGroup>(), 1f, 0.3f));
