				if (faBaoStarConfig.MasterSkillId != 0)
				{
					self.BeforeSkillIdList.Add(faBaoStarConfig.MasterSkillId);
				}
				if (faBaoStarConfig2.SkillIds != 0)
				{
					self.AfterSkillIdList.Add(faBaoStarConfig2.SkillIds);
				}
				if (faBaoStarConfig2.MasterSkillId != 0)
				{
					self.AfterSkillIdList.Add(faBaoStarConfig2.MasterSkillId);
				}
				self.Sequence = val;
				int count = self.BeforeSkillIdList.Count;
				self._UICommonList.UIObject.Transform.sizeDelta = new Vector2(665f, (float)(count * 135));
				self._UICommonList.SetData(count);
