				{
					self._UnLockNode.SetActive(active: false);
				}
				else
				{
					self._UnLockNode.SetActive(active: true);
					FaBaoStarConfig faBaoStarConfig3 = ConfigSingleton<FaBaoStarConfigCategory>.Instance.Get(self.FaBao.ConfigId, 0);
					self._DesText.SetText($"已拥有该法宝，自动分解成{self.Fragment}个碎片");
