		public static void UpdateHeroCardView(this UIFormationPanel self)
		{
			self.HeroCardInfos.Clear();
			Player player = ((Entity)(object)self).LocalPlayer();
			FormationConfig config = ((Entity)self.Scene).GetComponent<FormationComponent>().GetCurrentFormation().Config;
			List<Hero> heroes = player.GetHeroes(new HeroSearch
			{
				OnlyActive = true,
				Includes = HeroInclude.All
			});
			DupComponent component = ((Entity)self.Scene).GetComponent<DupComponent>();
			if (component != null && (component.Dup.DupType == DupType.PVPTest1 || component.Dup.DupType == DupType.PVPTest2))
			{
				heroes = player.GetHeroes(new HeroSearch
				{
					OnlyActive = true,
					Includes = (HeroInclude.All | HeroInclude.TestStump)
				});
			}
			foreach (Hero item in heroes)
			{
				RoleDeployType roleDeployType = (RoleDeployType)config.RoleDeployType;
				if ((roleDeployType != RoleDeployType.Require && roleDeployType != RoleDeployType.Cannot) || item.Config.Type != 1)
				{
					self.HeroCardInfos.Add(new HeroCardInfo
					{
						HeroId = ((Entity)item).Id,
						ConfigId = item.ConfigId,
						Star = item.Star,
						Level = player.GetHeroLvById(item.ConfigId),
						Power = item.GetPower(),
						HeroSkinId = item.CurrentSkin
					});
				}
			}
			if (config.CanRent)
			{
				foreach (Hero allHero in ((Entity)player).GetComponent<HeroRentModule>().GetAllHeroes())
				{
					HeroRentInfoComponent component2 = ((Entity)allHero).GetComponent<HeroRentInfoComponent>();
					self.HeroCardInfos.Add(new HeroCardInfo
					{
						HeroId = ((Entity)allHero).Id,
						ConfigId = allHero.ConfigId,
						Star = allHero.Star,
						Level = component2.Info.HeroInfo.Level,
						Power = allHero.GetPower(),
						IsRent = true,
						HeroSkinId = allHero.CurrentSkin
					});
				}
			}
			self.HeroCardInfos.Sort(delegate(HeroCardInfo a, HeroCardInfo b)
			{
				if (a.Power != b.Power)
				{
					return b.Power.CompareTo(a.Power);
				}
				HeroConfig heroConfig = ConfigSingleton<HeroConfigCategory>.Instance.Get(a.ConfigId);
				HeroConfig heroConfig2 = ConfigSingleton<HeroConfigCategory>.Instance.Get(b.ConfigId);
				return heroConfig.Job.CompareTo(heroConfig2.Job);
			});
			self._HeroScrollList.SetData(self.HeroCardInfos.Count);
		}

