		private static void OnHeroCardUpdate(this UIFormationPanel self, UIScrollListCell cell)
		{
			FormationComponent component = ((Entity)self.Scene).GetComponent<FormationComponent>();
			HeroCardInfo heroCardInfo = self.HeroCardInfos[cell.Index];
			HeroCardOptions options = default(HeroCardOptions);
			FormationData currentFormation = component.GetCurrentFormation();
			if (currentFormation.ContainsHero(heroCardInfo.HeroId))
			{
				options.IsCheck = true;
			}
			else if (currentFormation.IsHeroSet(heroCardInfo.ConfigId))
			{
				options.IsConflict = true;
			}
			if (component.FormationCount > 1)
			{
				options.CurrentFormationNo = currentFormation.FormationNo;
				options.HeroFormationNo = component.GetHeroFormationData(heroCardInfo.HeroId)?.FormationNo ?? 0;
			}
			((Entity)cell.UIObject).GetComponent<UIHeroCardItem>().SetData(heroCardInfo, options);
		}

		private static void UnsetHero(this UIFormationPanel self, long unsetHeroId)
		{
