				heroFormationData.RemoveHero(unsetHeroId);
				RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.Hero_Formation, heroFormationData.FormationId);
				self._HeroScrollList.SetData(self.HeroCardInfos.Count);
				self.UpdateSelfUnitInfosView();
				self.RefreshRelates().Coroutine();
			}
		}

