		private static void RefreshNoFullSigns(this UIFormationPanel self)
		{
			if (self.FormationTabInfos.Count == 0)
			{
				return;
			}
			FormationComponent component = ((Entity)self.Scene).GetComponent<FormationComponent>();
			int count = ((Entity)(object)self).LocalPlayer().GetHeroes(new HeroSearch
			{
				Includes = HeroInclude.All,
				OnlyActive = true
			}).Count;
			int num = 0;
			int num2 = 0;
			foreach (FormationData item in ((Entity)component).Children.Values.Cast<FormationData>())
			{
				num2 += item.Count;
				num += item.Config.Max;
			}
			bool flag = num2 >= num || num2 >= count;
			for (int i = 0; i < self.FormationTabInfos.Count; i++)
			{
				FormationData child = ((Entity)component).GetChild<FormationData>((long)self.FormationTabInfos[i].formationId);
				((Entity)self._UIFormationTabItem.UIObject.GetCloneObject(i)).GetComponent<UIFormationTabItem>().SetNoFullSign(!child.IsFull() && !flag);
			}
		}

