		[UIMethod]
		private static void OnShow(this UIFormationRelatePanel self, List<long> heroes)
		{
			using HeroRelateBuilder heroRelateBuilder = ((Entity)(object)self).LocalPlayer().BuildRelates(heroes);
			foreach (int key in ConfigSingleton<JobConfigCategory>.Instance.GetAll().Keys)
			{
				UIObject self2 = self._UIFormationJobRelate._JobRelateWidget.Find($"Job{key}");
				self2.SetGray();
				self2.Find("Active").SetActive(active: false);
				self._UIFormationJobRelate.UIObject.Find($"Job{key}").SetGray();
			}
			foreach (int activeJob in heroRelateBuilder.GetActiveJobs())
			{
				UIObject self3 = self._UIFormationJobRelate._JobRelateWidget.Find($"Job{activeJob}");
				self3.SetGray(isGray: false);
				self3.Find("Active").SetActive(active: true);
				self._UIFormationJobRelate.UIObject.Find($"Job{activeJob}").SetGray(isGray: false);
			}
			self._UIFormationJobRelate._JobRelateWidget.Find("Active").SetActive(heroRelateBuilder.IsActiveJobRelate);
			int buff_JobRelate = ConfigSingleton<GlobalConfigCategory>.Instance.GetOne().Buff_JobRelate;
			self._UIFormationJobRelate._BuffDesc.SetText(heroRelateBuilder.IsActiveJobRelate ? ConfigSingleton<BuffConfigCategory>.Instance.Get(buff_JobRelate).Desc : ("<color=#9996a0>" + ConfigSingleton<BuffConfigCategory>.Instance.Get(buff_JobRelate).Desc + "</color>"));
			self._UIFormationJobRelate._ActiveText.SetText(heroRelateBuilder.IsActiveJobRelate ? Language.Get(1, 8) : Language.Get(1, 9));
			List<RelateInfo> list = new List<RelateInfo>(heroRelateBuilder.GetActiveRelates());
			self._HeroRelateTittle.SetActive(list.Count > 0);
			self._UIHeroRelateItem.UIObject.CloneAll(list, delegate(int _, RelateInfo info, UIObject uiObject)
