		private static void InitList(this UIFreePrizeDrawPanel self)
		{
			Dictionary<int, FreePrizeDrawConfig> dictionary = ConfigSingleton<FreePrizeDrawConfigCategory>.Instance.GetDictionary(self.ActId);
			if (dictionary == null)
			{
				Log.Error("没有 FreePrizeDrawConfig");
				return;
			}
			ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId);
			if (activityData == null)
			{
				Log.Error("缺少activityData,活动是否没有配全？");
				return;
			}
			FreePrizeDrawModule component = ((Entity)activityData).GetComponent<FreePrizeDrawModule>();
			if (component == null)
			{
				Log.Error("活动是否没有配全？");
				return;
			}
			self.Lists.Clear();
			int num = 0;
			bool flag = false;
			foreach (FreePrizeDrawConfig value in dictionary.Values)
			{
				self.Lists.Add(value.Id);
				num++;
				if (num != 3)
				{
					continue;
				}
				foreach (int list in self.Lists)
				{
					if (!component.IsGetReward(list))
					{
						flag = true;
						break;
					}
				}
				if (flag)
				{
					break;
				}
				flag = false;
				num = 0;
				self.Lists.Clear();
			}
			if (num == 0)
			{
				foreach (FreePrizeDrawConfig value2 in dictionary.Values)
				{
					if (num >= dictionary.Count - 3)
					{
						self.Lists.Add(value2.Id);
					}
					num++;
				}
			}
			self._List.SetData(self.Lists.Count);
		}

		private static void InitButtonStatus(this UIFreePrizeDrawPanel self)
		{
			Dictionary<int, FreePrizeDrawConfig> dictionary = ConfigSingleton<FreePrizeDrawConfigCategory>.Instance.GetDictionary(self.ActId);
			if (dictionary == null)
			{
				Log.Error("没有 FreePrizeDrawConfig");
				return;
			}
			ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId);
			if (activityData == null)
			{
				Log.Error("缺少activityData,活动是否没有配全？");
				return;
			}
			FreePrizeDrawModule component = ((Entity)activityData).GetComponent<FreePrizeDrawModule>();
			if (component == null)
			{
				Log.Error("活动是否没有配全？");
				return;
			}
			HeavenTowerDupModule component2 = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<HeavenTowerDupModule>();
			if (component2 == null)
			{
				Log.Error("没有HeavenTowerDupModule");
				return;
			}
			DJHeroModule component3 = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<DJHeroModule>();
			if (component3 == null)
			{
				Log.Error("没有DJHeroModule");
				return;
			}
			int num = 0;
			foreach (FreePrizeDrawConfig value in dictionary.Values)
			{
				if (component.IsGetReward(value.Id) && (value.Reward.Id == 10 || value.Reward.Id == 11))
				{
					num += value.Reward.Nums;
				}
			}
			self._AllText.SetText(num.ToString() ?? "");
			self._ThisText.SetText(Language.Format(4, 790, component3.Level, component2.GetCurrentLevel() - 1));
			SuperText component4 = self._ThisText.GameObject.GetComponent<SuperText>();
			if ((Object)(object)component4 != (Object)null)
			{
				self._ThisText.Transform.SetSizeWithCurrentAnchors((Axis)0, ((Text)component4).preferredWidth + 5f);
				self._This.Transform.SetSizeWithCurrentAnchors((Axis)0, ((Text)component4).preferredWidth + 25f);
			}
			RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.Activity, activityData.ActivityId);
		}

		private static void OnCellUpdate(this UIFreePrizeDrawPanel self, UIScrollListCell cell)
