				Log.Error("活动是否没有配全？");
				return;
			}
			foreach (int list in self.Lists)
			{
				if (component.IsCompleteTask(list) && !component.IsGetReward(list))
				{
					component.ReqGetReward(list).Coroutine();
				}
			}
		}
