		}

		public static void OnAgreeAllClick(this UIFriendApplyPanel self)
		{
			FriendModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FriendModule>();
			if (component.IsFriendFull())
			{
				UIGameMsgHelper.FloatMsg("当前列表好友已满，无法再添加");
				return;
			}
			component.ReqAgreeAllApply();
			self.ApplyList.Clear();
			self._ApplyList.SetData(0);
			self._EmptyGroup.SetActive(self.ApplyList.Count <= 0);
			UIManager.Instance.Remove(typeof(UIFriendApplyPanel));
		}

		public static void OnRefuseAllClick(this UIFriendApplyPanel self)
		{
			((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FriendModule>().ReqRefuseAllApply();
			self.ApplyList.Clear();
			self._ApplyList.SetData(0);
			self._EmptyGroup.SetActive(self.ApplyList.Count <= 0);
			UIManager.Instance.Remove(typeof(UIFriendApplyPanel));
		}

		public static void UpdateView(this UIFriendApplyPanel self)
		{
			FriendModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FriendModule>();
			self.ApplyList.Clear();
			foreach (var (item, _) in component.GetApplyDict())
			{
				self.ApplyList.Add(item);
			}
			self._EmptyGroup.SetActive(self.ApplyList.Count <= 0);
			self._AgreeAllButton.SetGray(self.ApplyList.Count <= 0);
			self._RefuseAllButton.SetGray(self.ApplyList.Count <= 0);
			self._ApplyList.SetData(self.ApplyList.Count);
		}

		private static void OnCellUpdate(this UIFriendApplyPanel self, UIScrollListCell cell)
		{
			((Entity)cell.UIObject).GetComponent<UIFriendApplyItem>().SetData(self.ApplyList[cell.Index]);
		}
	}
