		public static void OnTabClick(this UIFriendPanel self, int tabIndex)
		{
			FriendModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FriendModule>();
			if (TimeHelper.Now() - component.LastUpdateTime > 60000)
			{
				component.ReqUpdateFriendList().Coroutine();
				component.LastUpdateTime = TimeHelper.Now();
			}
			if (self.CurrentType != tabIndex)
			{
				self.CurrentType = tabIndex;
				self._FriendButton.Find("Select").SetActive(tabIndex == 1);
				self._BlackListButton.Find("Select").SetActive(tabIndex == 2);
				self._WeChatButton.Find("Select").SetActive(tabIndex == 3);
				self.UpdateList();
			}
		}

		public static void UpdateList(this UIFriendPanel self)
		{
			//IL_0034: Unknown result type (might be due to invalid IL or missing references)
			//IL_0039: Unknown result type (might be due to invalid IL or missing references)
			//IL_0155: Unknown result type (might be due to invalid IL or missing references)
			//IL_01f9: Unknown result type (might be due to invalid IL or missing references)
			FriendModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FriendModule>();
			Dictionary<long, FriendInfo> friendList = component.GetFriendList();
			Vector2 offsetMin = self._Background.Transform.offsetMin;
			self.FriendList.Clear();
			foreach (var (_, friendInfo2) in friendList)
			{
				if (self.CurrentType == 1)
				{
					if (!friendInfo2.IsBlack)
					{
						self.FriendList.Add(friendInfo2);
					}
				}
				else if (self.CurrentType == 2 && friendInfo2.IsBlack)
				{
					self.FriendList.Add(friendInfo2);
				}
			}
			self.FriendList.Sort((FriendInfo a, FriendInfo b) => self.GetFriendSort(b) - self.GetFriendSort(a));
			int friendMaxByType = component.GetFriendMaxByType(self.CurrentType);
			if (self.CurrentType == 1)
			{
				self._ApplyButton.SetActive(active: true);
				self._SearchButton.SetActive(active: true);
				offsetMin.y = 265f;
				self._Background.Transform.offsetMin = offsetMin;
				self._EmptyGroup.SetText("当前列表暂无好友");
				self._FriendNumsText.SetText($"好友数：{self.FriendList.Count}/{friendMaxByType}");
			}
			else if (self.CurrentType == 2)
			{
				self._ApplyButton.SetActive(active: false);
				self._SearchButton.SetActive(active: false);
				offsetMin.y = 130f;
				self._Background.Transform.offsetMin = offsetMin;
				self._EmptyGroup.SetText("当前暂无黑名单对象");
				self._FriendNumsText.SetText($"黑名单：{self.FriendList.Count}/{friendMaxByType}");
			}
			self._EmptyGroup.SetActive(self.FriendList.Count <= 0);
			self._FriendList.SetData(self.FriendList.Count);
		}

		private static int GetFriendSort(this UIFriendPanel self, FriendInfo info)
		{
			int result = 0;
			if (info.Info.IsOnline)
			{
				result = 10000;
			}
			return result;
		}

