		{
			((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FriendModule>().ApplyCount = 0;
			RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.Interactive_Friend);
			UIManager.Instance.Show<UIFriendApplyPanel>().Coroutine();
		}

