		{
			L2C_ResponseRecommendFriend l2C_ResponseRecommendFriend = (L2C_ResponseRecommendFriend)(await ((Entity)(object)self).LocalPlayer().Call(new C2L_RequestRecommendFriend()));
			if (l2C_ResponseRecommendFriend.Error != 0)
