	[RedPointHandler(RedPointType.FuncNotice)]
	public class FuncNoticeRedPointHandler : ARedPointHandler
	{
		public override int GetCount(Scene scene, params int[] parameters)
		{
			UIRedPointComponent component = ((Entity)scene).GetComponent<UIRedPointComponent>();
			if (component.GetRedPointCount(RedPointType.FuncNotice_1, parameters) > 0)
			{
				return 1;
			}
			if (component.GetRedPointCount(RedPointType.FuncNotice_2, parameters) > 0)
			{
				return 1;
			}
			return 0;
		}
	}
	[RedPointHandler(RedPointType.FuncNotice_1)]
	public class FuncNotice1RedPointHandler : ARedPointHandler
	{
		public override int GetCount(Scene scene, params int[] parameters)
		{
			if (!((Entity)scene).GetComponent<LocalPlayerComponent>().Player.IsFuncOpen(25))
			{
				return 0;
			}
			return FuncNoticeRedPointHelper.GetFuncNoticeRedPoint(scene, parameters);
		}
	}
	[RedPointHandler(RedPointType.FuncNotice_2)]
	public class FuncNotice2RedPointHandler : ARedPointHandler
	{
		public override int GetCount(Scene scene, params int[] parameters)
		{
			if (!((Entity)scene).GetComponent<LocalPlayerComponent>().Player.IsFuncOpen(26))
			{
				return 0;
			}
			return FuncNoticeRedPointHelper.GetFuncNoticeRedPoint(scene, parameters);
		}
	}
	public static class FuncNoticeRedPointHelper
	{
		public static int GetFuncNoticeRedPoint(Scene scene, params int[] parameters)
		{
			Player player = ((Entity)scene).GetComponent<LocalPlayerComponent>().Player;
			FuncModule component = ((Entity)player).GetComponent<FuncModule>();
			int num = ((parameters != null && parameters.Length > 0) ? parameters[0] : 0);
			if (num == 0)
			{
				foreach (FuncNoticeConfig value in ConfigSingleton<FuncNoticeConfigCategory>.Instance.GetAll().Values)
				{
					if (player.IsFuncOpen(value.Id) && !component.FuncRewards.ContainsKey(value.Id))
					{
						return 1;
					}
				}
				return 0;
			}
			if (player.IsFuncOpen(num) && !component.FuncRewards.ContainsKey(num))
			{
				return 1;
			}
			return 0;
		}
	}
