		private static void OnClickHyperLink(this UIGameBroader self, string customInfo)
		{
			string[] array = customInfo.Split('_');
			if (array.Length < 2)
			{
				return;
			}
			string text = array[0];
			if (!(text == "Activity"))
			{
				if (text == "Func")
				{
					int.TryParse(array[1], out var result);
					if (array.Length == 2)
					{
						UIJumpHelper.To(result).Coroutine();
					}
					else if (array.Length == 3)
					{
						int.TryParse(array[2], out var result2);
						UIJumpHelper.To(result, result2).Coroutine();
					}
					else if (array.Length == 4)
					{
						int.TryParse(array[2], out var result3);
						int.TryParse(array[3], out var result4);
						UIJumpHelper.To(result, result3, result4).Coroutine();
					}
				}
			}
			else
			{
				int.TryParse(array[1], out var result5);
				UIJumpHelper.ToActivity(((Entity)(object)self).LocalPlayer(), result5).Coroutine();
			}
		}
	}
