		public static void SetText(this UIGameGMPanel self, int id)
		{
			self._InputField.GameObject.GetComponent<InputField>().text = $"$additem {id},1111";
		}

		public static void SetFocus(this UIGameGMPanel self)
		{
			if (((Entity)(object)self).LocalPlayer() != null)
			{
				InputField component = self._InputField.GameObject.GetComponent<InputField>();
				if (string.IsNullOrEmpty(component.text))
				{
					((Selectable)component).Select();
					component.ActivateInputField();
				}
				else
				{
					self.OnSendClick();
					component.DeactivateInputField();
				}
			}
		}

		private static void OnSendClick(this UIGameGMPanel self)
		{
			Player player = ((Entity)(object)self).LocalPlayer();
			if (player == null)
			{
				return;
			}
			ChatModule component = ((Entity)player).GetComponent<ChatModule>();
			string text = self._InputField.GameObject.GetComponent<InputField>().text;
			self._InputField.GameObject.GetComponent<InputField>().text = string.Empty;
			if (text.ToLower().Contains("close"))
			{
				self.UIObject.SetActive(active: false);
				return;
			}
			int num = self.RecordList.IndexOf(text);
			if (num > -1)
			{
				self.RecordList.RemoveAt(num);
			}
			self.RecordList.Add(text);
			self.Index = self.RecordList.Count;
			if (text.StartsWith("$"))
			{
				if (text.ToLower().StartsWith("$settime"))
				{
					GMCommandHelper.HandleSetTimeCommand(text);
				}
				component.Send(text);
			}
			else if (text.StartsWith("!"))
			{
				GMCommandComponent.Instance.Execute(player, text);
			}
		}

		public static void OnUpClick(this UIGameGMPanel self)
		{
			long num = TimeHelper.Now();
			if (num < self.LockTime)
			{
				return;
			}
			self.LockTime = num + 200;
			if (self.RecordList.Count > 0)
			{
				self.Index--;
				if (self.Index < 0)
				{
					self.Index = 0;
				}
				string text = self.RecordList[self.Index];
				self._InputField.GameObject.GetComponent<InputField>().text = text;
			}
		}

		public static void OnDownClick(this UIGameGMPanel self)
		{
			long num = TimeHelper.Now();
			if (num < self.LockTime)
			{
				return;
			}
			self.LockTime = num + 200;
			if (self.RecordList.Count > 0)
			{
				self.Index++;
				if (self.Index >= self.RecordList.Count)
				{
					self.Index = self.RecordList.Count - 1;
				}
				string text = self.RecordList[self.Index];
				self._InputField.GameObject.GetComponent<InputField>().text = text;
			}
		}
	}
