		public static void SetData(this UITeamDupMsgPanel self, long id, string name, int configId)
		{
			self._Content.SetActive(active: true);
			self._ShowGroup.SetActive(active: false);
			self.PlayerId = id;
			self.ConfigId = configId;
			DupTXCMConfig dupTXCMConfig = ConfigSingleton<DupTXCMConfigCategory>.Instance.Get(configId);
			int stage = dupTXCMConfig.Stage;
			QualityConfig qualityConfig = ConfigSingleton<QualityConfigCategory>.Instance.Get(stage);
			self._DescText.SetText(Language.Format(5, 305, qualityConfig.Hex, dupTXCMConfig.BossName));
