		private static void CountDown(this UITeamDupMsgPanel self)
		{
			self._TimeText.SetText(Language.Format(5, 303, self.CurrentTime));
			self._CancelText.SetText(Language.Format(5, 304, self.CurrentTime));
			self.CurrentTime--;
			if (self.CurrentTime < 0)
