			self.RemoveTimer(ref self.CountDownTimer);
			UIObject.FindUIObjectOfType<UIGameMsgPanel>()?.ShowTeamDupBattle();
		}

		private static void OnCancelClick(this UITeamDupMsgPanel self)
		{
			self.RemoveTimer(ref self.CountDownTimer);
			UIObject.FindUIObjectOfType<UIGameMsgPanel>()?.ShowTeamDupBattle();
		}

