		public static void SetGemGiftData(this UIObtainGemItem self, int actId, GemStonePlanTaskConfig config, Action _callback = null)
		{
			self.UIObject.SetActive(active: true);
			self.ActId = actId;
			self.ActivityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), actId);
			self.Callback = _callback;
			self.Config = config;
			self._BgImg.SetRawTexture(config.GiftBg).Coroutine();
			self._TitleText.SetText(config.Desc);
			self._JadeIcon.SetActive(config.Type == 1);
			self._DiscountImg.SetActive(config.Discount > 0);
			self._DiscountText.SetText($"{config.Discount}%");
			self._GetText.SetText("领取");
			if (config.Type == 4)
			{
				self._GetText.SetText(Language.Format(2, 500));
			}
			else if (config.Type == 2)
			{
				PayConfig payConfig = ConfigSingleton<PayConfigCategory>.Instance.Get(config.PayId);
				if (payConfig == null)
				{
					Log.Error("商店id没找到，配置是否错误？");
				}
				self._BuyText.SetText(Language.Format(4, 744, payConfig.Price / 100));
			}
			else if (config.Type == 1)
			{
				self._JadeIcon.SetRawTexture($"uitex_icon_item_{UIItemHelper.GetItemIconIdByItemId(self.Config.GiftPrice.Id)}").Coroutine();
				self._BuyText.SetText($"{self.Config.GiftPrice.Nums}");
			}
			using ItemList itemList = ItemList.Create();
			itemList.AddRange(self.Config.RewadItems);
			self._RewardList.SetData(itemList);
			self.OnRefreshConfigData();
		}

		private static void OnRefreshConfigData(this UIObtainGemItem self)
		{
