			int gemGiftBuyNum = component.GetGemGiftBuyNum(self.Config.Id);
			bool gemGiftGetState = component.GetGemGiftGetState(self.Config.Id);
			self._GetBtn.SetActive(gemGiftGetState || self.Config.Type == 4);
			self._BuyBtn.SetActive(!gemGiftGetState && self.Config.Type != 4);
			if (!gemGiftGetState)
