					self._BuyText.GameObject.GetComponent<SuperOutline>().effectColor = new Color(0.99215686f, 0.827451f, 33f / 85f);
				}
				else
				{
					((Graphic)self._BuyText.GameObject.GetComponent<SuperText>()).color = Color.white;
					self._BuyText.GameObject.GetComponent<SuperOutline>().effectColor = effectColor;
				}
				((Behaviour)self._BuyText.GameObject.GetComponent<SuperOutline>()).enabled = true;
			}
			else
			{
				self._ReminText.SetText(Language.Format(3, 228, $"{Math.Abs(gemGiftBuyNum - self.Config.BuyCountLimit)}/{self.Config.BuyCountLimit}"));
