		private static void RefreshGfitList(this UIObtainGemStoneView self)
		{
			GemStonePlanModule component = ((Entity)self.ActivityData).GetComponent<GemStonePlanModule>();
			GemStonePlanBaseConfig gemStonePlanBaseConfig = ConfigSingleton<GemStonePlanBaseConfigCategory>.Instance.Get(self.ActivityData.ActivityId);
			Dictionary<int, GemStonePlanTaskConfig> dictionary = new Dictionary<int, GemStonePlanTaskConfig>();
			int[] gemStonePlanObtainId = gemStonePlanBaseConfig.GemStonePlanObtainId;
			int i;
			for (i = 0; i < gemStonePlanObtainId.Length; i++)
			{
				int num = gemStonePlanObtainId[i];
				dictionary.Add(num, ConfigSingleton<GemStonePlanTaskConfigCategory>.Instance.Get(num));
			}
			foreach (KeyValuePair<int, GemStonePlanTaskConfig> item in dictionary)
			{
				item.Deconstruct(out i, out var value);
				int num2 = i;
				GemStonePlanTaskConfig gemStonePlanTaskConfig = value;
				gemStonePlanTaskConfig.SortId = (component.IsBuyOut(num2) ? (50 + num2) : num2);
				self.TaskList.Add(gemStonePlanTaskConfig);
			}
			self.TaskList.Sort((GemStonePlanTaskConfig a, GemStonePlanTaskConfig b) => a.SortId - b.SortId);
			if (self.TaskList.Count <= 0)
			{
