		[UIMethod]
		public static void OnShow(this UIGodGiftDoublePanel self, int activityId)
		{
			self.ActId = activityId;
			self.OnInit();
		}

		private static void OnInit(this UIGodGiftDoublePanel self)
		{
			ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId);
			if (activityData == null)
			{
				Log.Error("缺少activityData,活动是否没有配全？");
				return;
			}
			GodGiftDoubleModule component = ((Entity)activityData).GetComponent<GodGiftDoubleModule>();
			if (component == null)
			{
				Log.Error("缺少GodGiftDoubleModule？");
				return;
			}
			self.Tab.Clear();
			int num = TimeHelper.DaysBetween(activityData.StartTime, TimeHelper.ServerNow(), 18000000L);
			Dictionary<int, GodGiftDoubleMainConfig> dictionary = ConfigSingleton<GodGiftDoubleMainConfigCategory>.Instance.GetDictionary(self.ActId);
			if (dictionary == null)
			{
				Log.Error($"{self.ActId}在GodGiftDoubleMainConfig中没有");
				return;
			}
			self.UIObject.RefreshRedPoint(RedPointType.Activity, self.ActId);
			foreach (GodGiftDoubleMainConfig value in dictionary.Values)
			{
				if (num >= value.OpenDay && num <= value.EndDay)
				{
					self.Tab.Add(value);
				}
			}
			self._Tab.SetData(self.Tab.Count);
			if (self._Tab.Count >= 3)
			{
				self._Tab.UIObject.Transform.SetSizeWithCurrentAnchors((Axis)0, 750f);
			}
			else
			{
				self._Tab.UIObject.Transform.SetSizeWithCurrentAnchors((Axis)0, (float)(292 * self._Tab.Count));
			}
			Dictionary<int, GodGiftDoubleConfig> dictionary2 = ConfigSingleton<GodGiftDoubleConfigCategory>.Instance.GetDictionary(self.ActId);
			if (dictionary2 == null)
			{
				Log.Error($"{self.ActId}在GodGiftDoubleConfig中没有");
				return;
			}
			int num2 = 0;
			int num3 = 99999;
			foreach (GodGiftDoubleMainConfig value2 in dictionary.Values)
			{
				if (num >= value2.OpenDay && num3 > value2.EndDay && num <= value2.EndDay)
				{
					num3 = value2.EndDay;
					num2 = value2.Type;
				}
			}
			List<int> list = new List<int>();
			List<int> list2 = new List<int>();
			long itemNumsByItemId = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().GetItemNumsByItemId(99);
			foreach (GodGiftDoubleConfig value3 in dictionary2.Values)
			{
				if (value3.Pay == 0 && value3.Index == 1 && !component.ISBuy(value3.Id))
				{
					list.Add(value3.Type);
				}
				if (value3.PayType == 2 && !component.ISBuy(value3.Id))
				{
					list2.Add(value3.Type);
					continue;
				}
				if (value3.Pay == 0 && value3.Index > 1 && !component.ISBuy(value3.Id - 1) && !list.Contains(value3.Type) && !list2.Contains(value3.Type))
				{
					list.Add(value3.Type);
				}
				if (value3.Pay == 1 && value3.Index > 1 && itemNumsByItemId >= value3.Pay && component.ISBuy(value3.Id - 1) && !component.ISBuy(value3.Id) && !list.Contains(value3.Type) && !list2.Contains(value3.Type))
				{
					list.Add(value3.Type);
				}
			}
			if (list.Count > 0)
			{
				int num4 = 99999;
				foreach (GodGiftDoubleMainConfig value4 in dictionary.Values)
				{
					if (list.Contains(value4.Type) && num >= value4.OpenDay && num4 > value4.EndDay && num <= value4.EndDay)
					{
						num4 = value4.EndDay;
						num2 = value4.Type;
					}
				}
			}
			int num5 = 0;
			if (num2 > 0)
			{
				using List<GodGiftDoubleMainConfig>.Enumerator enumerator3 = self.Tab.GetEnumerator();
				while (enumerator3.MoveNext() && enumerator3.Current.Type != num2)
				{
					num5++;
				}
			}
			self._Tab.MovePanelToItemIndex(num5);
			int num6 = 0;
			foreach (GodGiftDoubleMainConfig item in self.Tab)
			{
				if (num6 == num5)
				{
					self.OnClickTab(item);
					break;
				}
				num6++;
			}
		}

		private static void OnClickTab(this UIGodGiftDoublePanel self, GodGiftDoubleMainConfig cfg)
		{
			if (cfg == self.Curr)
			{
				return;
			}
			self.Curr = cfg;
			for (int i = 0; i < self._Tab.Count; i++)
			{
				UIScrollListCell cell = self._Tab.GetCell(i);
				if (cell != null)
				{
					((Entity)cell.UIObject).GetComponent<UIGodGiftDoubleItem>().OnSelect(cfg);
				}
			}
			ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId);
			GodGiftDoubleModule component = ((Entity)activityData).GetComponent<GodGiftDoubleModule>();
			self._Bg2.SetRawTexture(cfg.Bg2).Coroutine();
			self._Bg1.SetRawTexture(cfg.Bg1).Coroutine();
			self._Bg.SetRawTexture(cfg.Bg).Coroutine();
			long num = activityData.StartTime + 86400000L * (long)cfg.EndDay;
			if (num > activityData.EndTime)
			{
				num = activityData.EndTime;
			}
			self._Timer.SetDate(num);
			self._NumGroup.SetActive(cfg.Discount > 0);
			if (cfg.Discount > 0)
			{
				char[] array = cfg.Discount.ToString().ToCharArray();
				for (int j = 0; j < 4; j++)
				{
					self._NumGroup.Find("Num" + (j + 1)).SetTexture($"ui_tslb_num_{array[j]}").Coroutine();
				}
			}
			self._Tips.SetActive(component.IsShowTips(cfg.Type));
			self.List.Clear();
			int num2 = 0;
			foreach (GodGiftDoubleConfig value in ConfigSingleton<GodGiftDoubleConfigCategory>.Instance.GetDictionary(self.ActId).Values)
			{
				if (value.Type == cfg.Type)
				{
					self.List.Add(value);
					if (num2 == 0 && !component.ISBuy(value.Id))
					{
						num2 = value.Index;
					}
				}
			}
			self._List.SetData(self.List.Count);
			self._List.MovePanelToItemIndex(num2 - 1);
			self._List.RefreshView();
		}

		private static void OnTabCellUpdate(this UIGodGiftDoublePanel self, UIScrollListCell cell)
		{
			int index = cell.Index;
			((Entity)cell.UIObject).GetComponent<UIGodGiftDoubleItem>().SetData(self.Tab[index], self.OnClickTab);
		}

		private static void OnCellUpdate(this UIGodGiftDoublePanel self, UIScrollListCell cell)
		{
			int index = cell.Index;
			((Entity)cell.UIObject).GetComponent<UIGodGiftDoubleCard>().SetData(self.List[index], index);
			self.IsInit = true;
		}

		public static void Refresh(this UIGodGiftDoublePanel self)
		{
			GodGiftDoubleModule component = ((Entity)ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId)).GetComponent<GodGiftDoubleModule>();
			int num = 0;
			foreach (GodGiftDoubleConfig value in ConfigSingleton<GodGiftDoubleConfigCategory>.Instance.GetDictionary(self.ActId).Values)
			{
				if (value.Type == self.Curr.Type && num == 0 && !component.ISBuy(value.Id))
				{
					num = value.Index;
				}
			}
			self._List.RefreshView();
			self._List.MovePanelToItemIndex(num - 1);
			self._Tab.RefreshView();
			self._Tips.SetActive(!component.IsGetAll(self.Curr.Type));
		}
	}
