		public static void UpdateScore(this UIGodWillAssemblyPanel self)
		{
			GodWillAssemblyModule component = ((Entity)self.ActivityData).GetComponent<GodWillAssemblyModule>();
			ItemConfig itemConfig = ET.ItemHelper.GetItemConfig(component.GetScoreItemId());
			int score = component.Score;
			self._ScoreText.SetText(score.ToString());
			self._ScoreImage.SetRawTexture($"uitex_icon_item_{itemConfig.Icon}").Coroutine();
			int num = 0;
			List<GodWillAssemblyStageConfig> all = ConfigSingleton<GodWillAssemblyStageConfigCategory>.Instance.GetAll(self.ActivityId);
			foreach (var (index, uIObject2) in self.ScoreUIObjectDict)
			{
				((Entity)uIObject2).GetComponent<UIGodWillAssemblyScoreItem>().SetData(self.ActivityData, all[index]);
			}
			for (int i = 0; i < all.Count; i++)
			{
				if (score >= all[i].Nums)
				{
					num++;
				}
			}
			int count = all.Count;
			float num3 = (float)num * 1f / (float)count;
			float num4 = 0f;
			if (num < all.Count)
			{
				int num5 = 0;
				if (num == 0)
				{
					num5 = all[num].Nums;
					num4 = (float)score * 1f / (float)num5 / (float)count;
				}
				else
				{
					num5 = all[num].Nums - all[num - 1].Nums;
					num4 = (float)(score - all[num - 1].Nums) * 1f / (float)num5 / (float)count;
				}
			}
			((Slider)self._ScoreProgress.GameObject.GetComponent<SuperSlider>()).value = num3 + num4;
		}

