		public static void UpdateView(this UIGodWillAssemblyPanel self)
		{
			if (self.Configs == null)
			{
				self.Configs = new List<GodWillAssemblyConfig>();
			}
			self.Configs.Clear();
			Dictionary<int, GodWillAssemblyConfig> dictionary = ConfigSingleton<GodWillAssemblyConfigCategory>.Instance.GetDictionary(self.ActivityId);
			foreach (GodWillAssemblyConfig value in dictionary.Values)
			{
				if (self.Tab == value.Tab)
				{
					self.Configs.Add(value);
				}
			}
			self.Configs.Sort((GodWillAssemblyConfig a, GodWillAssemblyConfig b) => self.GetSort(a.Id) - self.GetSort(b.Id));
			self._List.SetData(self.Configs.Count);
			GodWillAssemblyModule component = ((Entity)self.ActivityData).GetComponent<GodWillAssemblyModule>();
			int num = 0;
			foreach (UIObject value2 in self.TabUIObjectDict.Values)
			{
				value2.Find("Red")?.SetActive(active: false);
			}
			foreach (GodWillAssemblyConfig value3 in dictionary.Values)
			{
				if (value3.Tab != num && component.GetTaskData(value3.Id).Status == 1)
				{
					num = value3.Tab;
					self.TabUIObjectDict[value3.Tab].Find("Red")?.SetActive(active: true);
				}
			}
		}

		public static int GetSort(this UIGodWillAssemblyPanel self, int configId)
		{
			GodWillAssemblyData taskData = ((Entity)self.ActivityData).GetComponent<GodWillAssemblyModule>().GetTaskData(configId);
			if (taskData == null)
			{
				return configId;
			}
			int num = configId;
			if (taskData.Status == 1)
			{
				num -= 10000000;
			}
			if (taskData.Status == 3)
			{
				num += 1000000;
			}
			return num;
		}

