		private static void OnClear(this UIGodWillStraightPanel self)
		{
			if (self.IsSet)
			{
				self.RemoveTimer(ref self.Timer);
			}
			self.IsSet = false;
		}

		private static void OnSetTimer(this UIGodWillStraightPanel self)
		{
			self.ShowTime = self.EndTime - TimeHelper.ServerNow();
			if (self.ShowTime <= 0)
			{
				self._TimeText.SetText("已结束");
				self.OnClear();
				return;
			}
			long num = self.ShowTime / 1000;
			long num2 = num / 86400;
			long num3 = num % 86400 / 3600;
			long num4 = num % 3600 / 60;
			long num5 = num % 60;
			UIHelper.SetText(str: (num2 <= 0) ? $"活动倒计时：{num3:D2}:{num4:D2}:{num5:D2}" : string.Format("活动倒计时：{0}天 {1:D2}:{2:D2}:{3:D2}", new object[4] { num2, num3, num4, num5 }), self: self._TimeText);
		}

