		private static void OnClickLastBtn(this UIGodWillStraightPanel self)
		{
			Dictionary<int, GodWillStraightConfig> dictionary = ConfigSingleton<GodWillStraightConfigCategory>.Instance.GetDictionary(self.ActId);
			if (dictionary == null)
			{
				Log.Error("为嘛不配置GodWillStraightConfig？？？？？");
				return;
			}
			int num = self.CurrDay - 1;
			if (num > 0)
			{
				if (!dictionary.ContainsKey(num))
				{
					Log.Error("为嘛不配置GodWillStraightConfig？？？？？");
					return;
				}
				self.CurrDay = num;
				self.OnClickItem(dictionary[num].Id);
			}
		}

		private static void OnClickNextBtn(this UIGodWillStraightPanel self)
		{
			Dictionary<int, GodWillStraightConfig> dictionary = ConfigSingleton<GodWillStraightConfigCategory>.Instance.GetDictionary(self.ActId);
			if (dictionary == null)
			{
				Log.Error("为嘛不配置GodWillStraightConfig？？？？？");
				return;
			}
			int num = self.CurrDay + 1;
			if (num <= dictionary.Count)
			{
				if (!dictionary.ContainsKey(num))
				{
					Log.Error("为嘛不配置GodWillStraightConfig？？？？？");
					return;
				}
				self.CurrDay = num;
				self.OnClickItem(dictionary[num].Id);
			}
		}

