		public static void SetData(this UIGrowthFundGameplayCard self, int actId, int configId, bool isFinally, int selectId, int maxId)
		{
			self.ActId = actId;
			self.ConfigId = configId;
			GrowthFundGameplayConfig growthFundGameplayConfig = ConfigSingleton<GrowthFundGameplayConfigCategory>.Instance.Get(configId);
			if (growthFundGameplayConfig == null)
			{
				Log.Error("在GrowthFundLevelConfig中没有id：" + configId);
				return;
			}
			ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId);
			if (activityData == null)
			{
				Log.Error("缺少activityData,活动是否没有配全？");
				return;
			}
			GrowthFundGameplayModule component = ((Entity)activityData).GetComponent<GrowthFundGameplayModule>();
			if (component == null)
			{
				Log.Error("活动是否没有配全？");
				return;
			}
			self._Line.SetActive(!isFinally);
			self._FreeItem.SetItem(growthFundGameplayConfig.FreeItem);
			self._LevelText.SetText(growthFundGameplayConfig.Need.ToString());
			if (component.WeekCardId > 0)
			{
				Dictionary<int, GrowthFundWeekCardConfig> dictionary = ConfigSingleton<GrowthFundWeekCardConfigCategory>.Instance.GetDictionary(self.ActId);
				if (dictionary == null)
				{
					Log.Error("缺少GrowthFundWeekCardPayConfig,活动是否没有配全？活动id" + self.ActId);
					return;
				}
				foreach (GrowthFundWeekCardConfig value in dictionary.Values)
				{
					if (value.CardId == component.WeekCardId && value.Level == growthFundGameplayConfig.Level)
					{
						self._SelectItem1.SetData(value.Item[0]);
						self._SelectItem2.SetData(value.Item[1]);
						break;
					}
				}
				self._SelectItem1.ClearClick();
				self._SelectItem2.ClearClick();
			}
			else
			{
				self._SelectItem1.SetData(null);
				self._SelectItem2.SetData(null);
				self._SelectItem1.ClearClick();
				self._SelectItem2.ClearClick();
				self._SelectItem1.SetClick(self.OnShowCardView);
				self._SelectItem2.SetClick(self.OnShowCardView);
			}
			float num = 0f;
			int num2 = self.ConfigId - 1;
			int num3 = self.ConfigId + 1;
			GrowthFundGameplayConfig growthFundGameplayConfig2 = null;
			if (num2 > 0)
			{
				growthFundGameplayConfig2 = ConfigSingleton<GrowthFundGameplayConfigCategory>.Instance.Get(num2);
			}
			GrowthFundGameplayConfig growthFundGameplayConfig3 = null;
			if (num3 <= maxId)
			{
				growthFundGameplayConfig3 = ConfigSingleton<GrowthFundGameplayConfigCategory>.Instance.Get(num3);
			}
			if (growthFundGameplayConfig2 == null)
			{
				num = ((component.Score >= growthFundGameplayConfig.Need) ? 0.5f : ((float)component.Score / (float)growthFundGameplayConfig.Need));
			}
			else
			{
				float num4 = growthFundGameplayConfig.Need - (growthFundGameplayConfig.Need - growthFundGameplayConfig2.Need) / 2;
				if ((float)component.Score > num4)
				{
					num = (float)component.Score / num4 * 0.5f;
					num = ((num > 0.5f) ? 0.5f : num);
				}
			}
			if (growthFundGameplayConfig3 != null)
			{
				if (growthFundGameplayConfig.Need < component.Score)
				{
					float num5 = growthFundGameplayConfig.Need + (growthFundGameplayConfig3.Need - growthFundGameplayConfig.Need) / 2;
					num += (float)component.Score / num5 * 0.5f;
				}
			}
			else if (self.ConfigId <= selectId)
			{
				num += 0.5f;
			}
			((Image)((Component)self._ExpImg.Transform).GetComponent<SuperImage>()).fillAmount = num;
			if (selectId == configId)
			{
				self._LevelImg.SetSprite("ui_jj2_frame_11").Coroutine();
			}
			else
			{
				bool flag = selectId > configId;
				self._LevelImg.SetSprite(flag ? "ui_jj2_frame_10" : "ui_jj2_frame_09").Coroutine();
			}
			bool flag2 = component.Score >= growthFundGameplayConfig.Need && component.GetConfigId < growthFundGameplayConfig.Id;
			bool flag3 = component.Score >= growthFundGameplayConfig.Need && component.GetVipConfigId < growthFundGameplayConfig.Id;
			self._Red.UIObject.SetActive(active: false);
			if (flag2)
			{
				self._GetBtn.SetTexture("ui_common_btn_24").Coroutine();
				self._GetText.SetText(Language.Get(4, 726));
				self._Red.UIObject.SetActive(active: true);
			}
			if (flag3 && !flag2)
			{
				self._GetBtn.SetTexture("ui_common_btn_25").Coroutine();
				self._GetText.SetText(Language.Get(4, 766));
				self._Red.UIObject.SetActive(component.Buy && component.WeekCardId > 0);
			}
			if (!flag2 && component.Buy && component.WeekCardId > 0 && !flag3)
			{
				self._GetBtn.SetTexture("ui_common_btn_23").Coroutine();
				self._GetText.SetText(Language.Get(4, 727));
			}
			if (growthFundGameplayConfig.Need > component.Score)
			{
				self._GetBtn.SetTexture("ui_common_btn_35").Coroutine();
				self._GetText.SetText(Language.Get(4, 767));
			}
			if (component.GetConfigId >= growthFundGameplayConfig.Id)
			{
				self._FreeItem.SetCheck();
				self._FreeItem.SetHighlight(showHighlightEffect: false);
			}
			else
			{
				self._FreeItem.SetCheck(isCheck: false);
				self._FreeItem.SetHighlight(component.Score >= growthFundGameplayConfig.Need);
			}
			self._SelectItem1.SetHighlight(component.Score >= growthFundGameplayConfig.Need);
			self._SelectItem2.SetHighlight(component.Score >= growthFundGameplayConfig.Need);
			if (component.WeekCardId > 0)
			{
				self._SelectItem1.IsLock(!component.Buy);
				self._SelectItem2.IsLock(!component.Buy);
				self._SelectItem1.SetCheck(component.Buy && component.GetVipConfigId >= growthFundGameplayConfig.Id && component.Score >= growthFundGameplayConfig.Need);
				self._SelectItem2.SetCheck(component.Buy && component.GetVipConfigId >= growthFundGameplayConfig.Id && component.Score >= growthFundGameplayConfig.Need);
				self._SelectItem1.SetHighlight(component.Buy && component.GetVipConfigId < growthFundGameplayConfig.Id && component.Score >= growthFundGameplayConfig.Need);
				self._SelectItem2.SetHighlight(component.Buy && component.GetVipConfigId < growthFundGameplayConfig.Id && component.Score >= growthFundGameplayConfig.Need);
			}
			else
			{
				self._SelectItem1.IsLock(isLock: true);
				self._SelectItem2.IsLock(isLock: true);
				self._SelectItem1.SetCheck(isCheck: false);
				self._SelectItem2.SetCheck(isCheck: false);
			}
		}

