			if (activityData == null)
			{
				Log.Error("缺少activityData,活动是否没有配全？");
				return;
			}
			GrowthFundGameplayModule component = ((Entity)activityData).GetComponent<GrowthFundGameplayModule>();
			if (component == null)
			{
				Log.Error("活动是否没有配全？");
				return;
			}
			Dictionary<int, GrowthFundGameplayConfig> dictionary = ConfigSingleton<GrowthFundGameplayConfigCategory>.Instance.GetDictionary(self.ActId);
			if (dictionary == null)
			{
				Log.Error("缺少GrowthFundGameplayConfig,活动是否没有配全？活动id" + self.ActId);
				return;
			}
			self._LockImg.SetActive(!component.Buy);
			self.Lists.Clear();
			self.SelectIndex = 0;
			self.SelectId = 0;
			foreach (GrowthFundGameplayConfig value in dictionary.Values)
			{
				if (component.Score >= value.Need)
				{
					self.SelectIndex++;
					self.SelectId = value.Id;
				}
				self.Lists.Add(value.Id);
			}
			self._RewardList.SetData(self.Lists.Count);
			self._RewardList.SetSelectIndex(self.SelectIndex);
			RectTransform content = ((Component)self._RewardList.UIObject.Transform).GetComponent<ScrollRect>().content;
			content.anchoredPosition = new Vector2(content.anchoredPosition.x, 131.52f * (float)(self.SelectIndex - 1));
		}

