				self._Red.SetActive(active: true);
				self._Box.SetActive(active: true);
				self._TimeText.SetActive(active: true);
				if (!TimeHelper.IsSameDay(component.GetFreeTime, TimeHelper.Now(), 18000000L))
				{
					self._TimeText.SetText(Language.Get(4, 763));
					self._BoxImg.SetSprite("ui_jj_sign_04").Coroutine();
				}
				else
				{
					self._Red.SetActive(active: false);
					self._BoxImg.SetSprite("ui_jj_sign_05").Coroutine();
					self.EndTime = TimeHelper.EndTimeOfDay(TimeHelper.ServerNow(), 18000000L);
					self.OnSetTimer();
					self.Timer = self.NewTimer(1000L, delegate
					{
						self.OnSetTimer();
					}, repeat: true);
				}
			}
			else
			{
