			string text = "animation_UIDirectBuyEveryDayGiftPanel1";
			if ((Object)(object)component2.GetClip(text) != (Object)null)
			{
				((Behaviour)component2).enabled = false;
				component2.Stop();
			}
			if (self._Red.IsActive() && !((Object)(object)component2.GetClip(text) == (Object)null))
			{
				((Behaviour)component2).enabled = true;
				component2[text].wrapMode = (WrapMode)2;
				component2.Play();
			}
		}

		private static void OnCellUpdate(this UIGrowthFundGameplayPanel self, UIScrollListCell cell)
		{
			int index = cell.Index;
			if (index < self.Lists.Count)
			{
				((Entity)cell.UIObject).GetComponent<UIGrowthFundGameplayCard>().SetData(self.ActId, self.Lists[index], index == self.Lists.Count - 1, self.SelectId, self.Lists[self.Lists.Count - 1]);
			}
		}

		private static void OnListCellUpdate(this UIGrowthFundGameplayPanel self, UIScrollListCell cell)
		{
			int index = cell.Index;
			if (index >= self.WeekCardList.Count)
			{
				return;
			}
			UIGrowthFundGameplayItem component = ((Entity)cell.UIObject).GetComponent<UIGrowthFundGameplayItem>();
			if (component == null)
			{
				return;
			}
			component.SetData(self.WeekCardList[index]);
			if (((Entity)ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId)).GetComponent<GrowthFundGameplayModule>().WeekCardId > 0)
			{
				component.ClearClick();
				return;
			}
			component.SetClick(delegate
			{
				UIManager.Instance.Show<UIGrowthFundWeekView, int>(self.ActId).Coroutine();
			});
		}

		private static void OnClear(this UIGrowthFundGameplayPanel self)
		{
			if (self.IsSet)
			{
				self.RemoveTimer(ref self.Timer);
			}
			self.IsSet = false;
		}

		private static void OnSetTimer(this UIGrowthFundGameplayPanel self)
		{
			self.ShowTime = self.EndTime - TimeHelper.ServerNow();
			if (self.ShowTime <= 0)
			{
				self.InitButtonStatus();
				self._TimeText.SetText("已结束");
				return;
			}
			long num = self.ShowTime / 1000;
			long num2 = num / 86400;
			long num3 = num % 86400 / 3600;
			long num4 = num % 3600 / 60;
			long num5 = num % 60;
			UIHelper.SetText(str: (num2 <= 0) ? $"{num3:D2}:{num4:D2}:{num5:D2}" : string.Format("{0}天 {1:D2}:{2:D2}:{3:D2}", new object[4] { num2, num3, num4, num5 }), self: self._TimeText);
		}

		public static void OnBuySuccess(this UIGrowthFundGameplayPanel self)
		{
			self._RewardList.SetData(self.Lists.Count);
			self.InitButtonStatus();
		}

		public static void OnGetFree(this UIGrowthFundGameplayPanel self)
		{
			self.InitButtonStatus();
		}

		public static void OnScoreChange(this UIGrowthFundGameplayPanel self)
		{
			self.OnBuySuccess();
		}

		public static void OnGetReward(this UIGrowthFundGameplayPanel self)
		{
			self._RewardList.SetData(self.Lists.Count);
		}

