		private static UIGrowthFundRewardOptions OnGetOptions(this UIGrowthFundItem self, int level)
		{
			Dictionary<int, OrderWarHeavenTowerPayConfig> actConfig = ConfigSingleton<OrderWarHeavenTowerPayConfigCategory>.Instance.GetDictionary(self.ActId);
			ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId);
			GrowthFundModule module = ((Entity)activityData).GetComponent<GrowthFundModule>();
			UIGrowthFundRewardOptions result = new UIGrowthFundRewardOptions(async delegate
			{
				if (!module.IsBuy(level))
				{
					await ((Entity)(object)self).LocalPlayer().Pay(ProductType.ActivityGrowthFund, actConfig[level].Id, self.ActId);
				}
				else if (!module.OnRefshRed())
				{
					UIGameMsgHelper.FloatMsg(Language.Get(4, 758));
				}
				else if (await module.ReqGetReward(self.ActId) == 0)
				{
					UIManager.Instance.Remove(typeof(UIGrowthFundRewardPanel));
				}
			});
			result.ActId = self.ActId;
			result.AllList = ItemList.Create();
			result.CurrentList = ItemList.Create();
			foreach (GrowthFundLevelConfig value in ConfigSingleton<GrowthFundLevelConfigCategory>.Instance.GetDictionary(self.ActId).Values)
			{
				if (self.SelectId + actConfig[2].Add >= value.Id)
				{
					if (level == 1)
					{
						if (self.SelectId >= value.Id)
						{
							result.CurrentList.Add(value.JuePinItem);
						}
					}
					else
					{
						result.CurrentList.AddRange(value.RechargeItem);
					}
				}
				if (level == 1)
				{
					result.AllList.Add(value.JuePinItem);
				}
				else
				{
					result.AllList.AddRange(value.RechargeItem);
				}
			}
			result.PayId = actConfig[level].PayId;
			result.Title = activityData.Name;
			result.TipsText1 = Language.Get(2, 279);
			result.TipsText2 = Language.Get(2, 280);
			result.Discount = actConfig[level].Discount;
			result.IsVip = module.IsBuy(level);
			return result;
		}
	}
