		private static UIGrowthFundRewardOptions OnGetOptions(this UIGrowthFundLevelCard self)
		{
			Dictionary<int, OrderWarHeavenTowerPayConfig> actConfig = ConfigSingleton<OrderWarHeavenTowerPayConfigCategory>.Instance.GetDictionary(self.ActId);
			ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId);
			GrowthFundLevelModule module = ((Entity)activityData).GetComponent<GrowthFundLevelModule>();
			UIGrowthFundRewardOptions result = new UIGrowthFundRewardOptions(async delegate
			{
				if (!module.LiberalStatus)
				{
					await ((Entity)(object)self).LocalPlayer().Pay(ProductType.GrowthFundLevel, actConfig.First().Value.Id, self.ActId);
				}
				else
				{
					Dictionary<int, GrowthFundLevelAllConfig> dictionary2 = ConfigSingleton<GrowthFundLevelAllConfigCategory>.Instance.GetDictionary(self.ActId);
					bool flag = false;
					int num2 = module.Score;
					foreach (GrowthFundLevelAllConfig value in dictionary2.Values)
					{
						if (num2 >= value.Score)
						{
							num2 -= value.Score;
							if (value.Id > module.GetConfigId)
							{
								flag = true;
								break;
							}
							if (value.Id > module.GetConfigId_VIP && module.LiberalStatus)
							{
								flag = true;
								break;
							}
						}
					}
					if (!flag)
					{
						UIGameMsgHelper.FloatMsg(Language.Get(4, 758));
					}
					else if (await module.ReqGetReward() == 0)
					{
						UIManager.Instance.Remove(typeof(UIGrowthFundRewardPanel));
					}
				}
			});
			result.ActId = self.ActId;
			result.AllList = ItemList.Create();
			result.CurrentList = ItemList.Create();
			Dictionary<int, GrowthFundLevelAllConfig> dictionary = ConfigSingleton<GrowthFundLevelAllConfigCategory>.Instance.GetDictionary(self.ActId);
			int num = module.Score;
			foreach (GrowthFundLevelAllConfig value2 in dictionary.Values)
			{
				if (value2.Id >= module.GetConfigId_VIP && num >= value2.Score)
				{
					result.CurrentList.AddRange(value2.RechargeItem);
				}
				if (num >= value2.Score)
				{
					num -= value2.Score;
				}
				result.AllList.AddRange(value2.RechargeItem);
			}
			result.PayId = actConfig.First().Value.PayId;
			result.Title = activityData.Name;
			result.TipsText1 = Language.Get(2, 279);
			result.TipsText2 = Language.Get(2, 280);
			result.Discount = actConfig.First().Value.Discount;
			result.IsVip = module.LiberalStatus;
			return result;
		}
	}
