		public static void SetData(this UIGrowthFundWeekCard self, int configId, int actId)
		{
			self.ConfigId = configId;
			self.ActId = actId;
			GrowthFundWeekCardPayConfig growthFundWeekCardPayConfig = ConfigSingleton<GrowthFundWeekCardPayConfigCategory>.Instance.Get(configId);
			if (growthFundWeekCardPayConfig == null)
			{
				Log.Error("GrowthFundWeekCardPayConfig 没有数据");
				return;
			}
			ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), actId);
			if (activityData == null)
			{
				Log.Error("缺少activityData,活动是否没有配全？");
				return;
			}
			GrowthFundGameplayModule component = ((Entity)activityData).GetComponent<GrowthFundGameplayModule>();
			if (component == null)
			{
				Log.Error("活动是否没有配全？");
				return;
			}
			PayConfig payConfig = ConfigSingleton<PayConfigCategory>.Instance.Get(growthFundWeekCardPayConfig.PayId);
			if (payConfig == null)
			{
				Log.Error("PayConfig 没有数据");
				return;
			}
			Dictionary<int, GrowthFundWeekCardConfig> dictionary = ConfigSingleton<GrowthFundWeekCardConfigCategory>.Instance.GetDictionary(actId);
			if (dictionary == null)
			{
				Log.Error("GrowthFundWeekCardConfig 没有数据");
				return;
			}
			self._DiscountImg.SetActive(growthFundWeekCardPayConfig.Discount > 0);
			self._DiscountText.SetText(growthFundWeekCardPayConfig.Discount + "%");
			self._Title.SetText(growthFundWeekCardPayConfig.Name);
			self._BuyGetList.SetData(growthFundWeekCardPayConfig.Reward);
			using (ItemList itemList = ItemList.Create())
			{
				foreach (GrowthFundWeekCardConfig value in dictionary.Values)
				{
					if (value.CardId == configId)
					{
						itemList.AddRange(value.Item);
					}
				}
				self._GetList.SetData(itemList);
			}
			self._SelectBtn.SetTexture((component.WeekCardId == configId) ? "ui_common_btn_11" : "ui_common_btn_02").Coroutine();
			self._SelectText.SetText((component.WeekCardId == configId) ? Language.Get(4, 769) : Language.Get(4, 768));
			self._BuyText.SetText(Language.Format(4, 744, payConfig.Price / 100));
		}

