			if (num > 0 && TimeHelper.ServerNow() < num)
			{
				return 0;
			}
			bool flag = false;
			ShopModule component = ((Entity)player).GetComponent<ShopModule>();
			List<int> shopItemShowByShopType = component.GetShopItemShowByShopType(7006);
			if (shopItemShowByShopType != null && shopItemShowByShopType.Count > 0)
			{
				foreach (int item in shopItemShowByShopType)
				{
					ShopGoodsConfig shopGoodsConfig = ConfigSingleton<ShopGoodsConfigCategory>.Instance.Get(item);
					if (player.CheckAllConds(shopGoodsConfig.OpenConds) && (shopGoodsConfig.LimitType <= 0 || component.GetCurrentBuyCount(item) < shopGoodsConfig.LimitBuyTime))
					{
						flag = true;
						break;
					}
				}
			}
			long itemNumsByItemId = ((Entity)player).GetComponent<ItemModule>().GetItemNumsByItemId(21);
			if (flag && itemNumsByItemId >= 30000)
			{
				return 1;
			}
			return 0;
		}
	}
