	[FriendOf(typeof(GuildDupModule))]
	[RedPointHandler(RedPointType.Guild_Dup_Boss)]
	public class GuildDupBossRedPointHandler : ARedPointHandler
	{
		private static int GetRewardCount(GuildDupModule module, GuildDupBossData data, int level = 0)
		{
			if (level == 0)
			{
				level = data.Level / 100 * 100;
				while (ConfigSingleton<GuildDupBossLevelConfigCategory>.Instance.Contain(++level) && data.IsPassLevel(level))
				{
					if (!module.IsBossLevelReward(level))
					{
						return 1;
					}
				}
				return 0;
			}
			if (!data.IsPassLevel(level) || module.IsBossLevelReward(level))
			{
				return 0;
			}
			return 1;
		}

		private static int GetFightCount(GuildDupModule module, GuildDupBossData data)
		{
			if (module.IsAllLevelPass())
			{
				return 0;
			}
			if (module.GetBossLeftFightCount() <= 0)
			{
				return 0;
			}
			return 1;
		}

		public override int GetCount(Scene scene, params int[] parameters)
		{
			Player player = ((Entity)(object)scene).LocalPlayer();
			if (!player.IsFuncOpen(6012))
			{
				return 0;
			}
			GuildDupBossComponent component = ((Entity)scene).GetComponent<GuildDupBossComponent>();
			GuildDupBossData dataByPlayer = component.GetDataByPlayer(player);
			if (!component.IsInOpenTime())
			{
				return 0;
			}
			if (dataByPlayer == null)
			{
				return 0;
			}
			GuildDupModule component2 = ((Entity)player).GetComponent<GuildDupModule>();
			if (parameters == null || parameters.Length <= 0)
			{
				if (component.IsInFightTime() && GetFightCount(component2, dataByPlayer) > 0)
				{
					return 1;
				}
				if (GetRewardCount(component2, dataByPlayer) > 0)
				{
					return 1;
				}
				if (component2.IsAllLevelPass() && component2.GetBossLeftFightCount() > 0)
				{
					return 1;
				}
				return 0;
			}
			switch (parameters[0])
			{
			case 1:
				return GetRewardCount(component2, dataByPlayer, (parameters != null && parameters.Length > 1) ? parameters[1] : 0);
			case 2:
				if (!component.IsInFightTime())
				{
					return 0;
				}
				return GetFightCount(component2, dataByPlayer);
			case 3:
				if (!component2.IsAllLevelPass() || component2.GetBossLeftFightCount() <= 0)
				{
					return 0;
				}
				return 1;
			default:
				return 0;
			}
		}
	}
