		private static void OnClickSee(this UIGuildJobAppointItem self)
		{
			UIManager.Instance.Show<UIGuildPermissionPopup>().Coroutine();
		}

		public static void SetData(this UIGuildJobAppointItem self, int job)
		{
			self.Job = job;
			GuildJobConfig jobConfig = ConfigSingleton<GuildJobConfigCategory>.Instance.Get(job);
			GuildLevelConfig maxConfig = ConfigSingleton<GuildLevelConfigCategory>.Instance.Get(ConfigSingleton<GuildLevelConfigCategory>.Instance.GetAll().Count);
			SetupUI(self, job, jobConfig);
			CreateRoleItems(self, job, maxConfig);
		}

		private static void SetupUI(UIGuildJobAppointItem self, int job, GuildJobConfig jobConfig)
		{
			string spriteName = ((job == 1) ? "ui_xm_frame_12" : "ui_xm_frame_13");
			self._ImgTitleBg.SetSprite(spriteName).Coroutine();
			self._TxtTitleName.SetText(jobConfig.JobName);
			self._RawLeaderBg.SetActive(job == 1);
			self._BtnSee.GameObject.SetActive(job == 1);
		}

		private static void CreateRoleItems(UIGuildJobAppointItem self, int job, GuildLevelConfig maxConfig)
		{
			List<GuildMemberInfo> members = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<GuildModule>().GuildInfo.Members;
			List<GuildMemberInfo> filteredMembers = FilterMembersByJob(members, job);
			self._RoleItem.UIObject.SetActive(active: false);
			int showRoleNum = GetShowRoleNum(job, maxConfig);
			self._RoleItem.UIObject.CloneAll(showRoleNum, delegate(int index, UIObject item)
			{
				GuildMemberInfo member = null;
				if (filteredMembers.Count > index)
				{
					member = filteredMembers[index];
				}
				((Entity)item).GetComponent<UIGuildJobAppointRoleItem>().SetData(member, job, index);
			}).Coroutine();
		}

		private static int GetShowRoleNum(int job, GuildLevelConfig maxConfig)
		{
			return job switch
			{
				2 => maxConfig.ViceLoaderCount, 
				3 => maxConfig.ElderCount, 
				_ => 1, 
			};
		}

		private static List<GuildMemberInfo> FilterMembersByJob(List<GuildMemberInfo> members, int job)
		{
			if (job != 4)
			{
				return members.FindAll((GuildMemberInfo x) => x.Job == job);
			}
			return members.FindAll((GuildMemberInfo x) => x.IsWarGod);
		}
	}
