		private static int GetUnlockLevel(this UIGuildJobAppointRoleItem self)
		{
			if (self.Index < 0)
			{
				return 1;
			}
			Dictionary<int, GuildLevelConfig> dictionary = ConfigSingleton<GuildLevelConfigCategory>.Instance?.GetAll();
			if (dictionary == null)
			{
				return 1;
			}
			foreach (KeyValuePair<int, GuildLevelConfig> item in dictionary)
			{
				switch (self.Job)
				{
				case 2:
					if (item.Value.ViceLoaderCount > self.Index)
					{
						return item.Value.Id;
					}
					break;
				case 3:
					if (item.Value.ElderCount > self.Index)
					{
						return item.Value.Id;
					}
					break;
				}
			}
			return 1;
		}
