			self.RefreshView();
		}

		public static void RefreshView(this UIGuildJobMemberPopup self)
		{
			List<GuildMemberInfo> members = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<GuildModule>().GuildInfo.Members;
			self.MemberList.Clear();
			if (self.Job == 4)
			{
				self.MemberList.AddRange(members.Where((GuildMemberInfo v) => !v.IsWarGod));
			}
			else
			{
				self.MemberList = members.Where((GuildMemberInfo x) => x.Job != 1 && x.Job != self.Job).ToList();
			}
			self.MemberList.Sort(delegate(GuildMemberInfo a, GuildMemberInfo b)
			{
				if (a.Job != b.Job)
				{
					return a.Job.CompareTo(b.Job);
				}
				if (a.Job == 5 && b.Job == 5 && a.IsWarGod != b.IsWarGod)
				{
					return b.IsWarGod.CompareTo(a.IsWarGod);
				}
				return (a.Contribute != b.Contribute) ? b.Contribute.CompareTo(a.Contribute) : b.PlayerInfo.Power.CompareTo(a.PlayerInfo.Power);
			});
			self._MemberScroll.SetData(self.MemberList.Count);
		}

