		public static void SetData(this UIGuildPermissionItem self, int permission, bool isTitle = false)
		{
			self._TxtTitlePower.SetText(isTitle ? Language.Get(6, 1020) : GuildHelper.GetPermissionName(permission));
			Dictionary<int, GuildJobConfig> configs = ConfigSingleton<GuildJobConfigCategory>.Instance.GetAll();
			GuildJobConfig[] array = configs.Values.ToArray();
			self._Job.CloneAll(array.Length - 1, delegate(int i, UIObject o)
			{
				int num = i + 1;
				if (isTitle)
				{
					o.Get(0).SetText(configs[num].JobName);
				}
				else
				{
					GuildOperation operation = GuildOperation.None;
					switch (permission)
					{
					case 16:
						operation = GuildOperation.Approve;
						break;
					case 32:
						operation = GuildOperation.Appoint;
						break;
					case 1:
						operation = GuildOperation.Disband;
						break;
					case 64:
						operation = GuildOperation.Kick;
						break;
					case 4:
						operation = GuildOperation.Notice;
						break;
					case 2:
						operation = GuildOperation.Rename;
						break;
					case 8:
						operation = GuildOperation.Banner;
						break;
					case 128:
						operation = GuildOperation.Transfer;
						break;
					case 256:
						operation = GuildOperation.Setting;
						break;
					case 512:
						operation = GuildOperation.ShowModel;
						break;
					}
					o.Get(0).SetActive(active: false);
					o.Get(1).SetActive(GuildHelper.ValidPermission(num, operation) == 0);
				}
			}).Coroutine();
		}
	}
