		public static void RefreshInvade(this UIGuildScenePanel self, ActivityData activityData = null)
		{
			if (!((Entity)(object)self).LocalPlayer().IsFuncOpen(6105))
			{
				return;
			}
			ActivityData activityData2 = activityData;
			if (activityData2 == null)
			{
				activityData2 = ((Entity)(object)self).LocalPlayer().GetActivityDataByType(ActivityType.GuildDupInvade);
				if (activityData2 == null)
				{
					self.RemoveTimer(ref self.InvadeTimer);
					self._BtnInvade.Find("Time").SetActive(active: false);
					return;
				}
			}
			if (activityData2.State != ActivityState.Open || !(((Entity)activityData2).GetComponent<GuildDupInvadeModule>()?.Season).HasValue)
			{
				return;
			}
			List<GuildDupInvadeRoundConfig> list = ConfigSingleton<GuildDupInvadeRoundConfigCategory>.Instance.GetList();
			long num = TimeHelper.StringTimeToLong(list[0].TriggerTime, 18000000L);
			long realEndTime = TimeHelper.StringTimeToLong(list[^1].TriggerTime, 18000000L);
			if (TimeHelper.Now() >= realEndTime || TimeHelper.Now() <= num)
			{
				self._BtnInvade.Find("Time").SetActive(active: false);
				return;
			}
			long leftTime = realEndTime - TimeHelper.Now();
			self._BtnInvade.Find("Time").SetActive(active: true);
			self._BtnInvade.Find("Time/TxtTime").SetText("<color=#e73333>" + TextHelper.TimeFormatHourMinSec(leftTime) + " 后结束</color>");
			self.InvadeTimer = self.NewTimer(1000L, delegate
			{
				leftTime = realEndTime - TimeHelper.Now();
				if (leftTime <= 0)
				{
					self._BtnInvade.Find("Time").SetActive(active: false);
					self.RemoveTimer(ref self.InvadeTimer);
				}
				else
				{
					self._BtnInvade.Find("Time/TxtTime").SetText("<color=#e73333>" + TextHelper.TimeFormatHourMinSec(leftTime) + " 后结束</color>");
				}
			}, repeat: true);
		}
	}
