		public static void SetData(this UIGuildDupStarBuffItem self, long playerId, int level)
		{
			GuildDupStarLevelConfig guildDupStarLevelConfig = ConfigSingleton<GuildDupStarLevelConfigCategory>.Instance.Get(level);
			BuffConfig buffConfig = ConfigSingleton<BuffConfigCategory>.Instance.Get(guildDupStarLevelConfig.FirstBuff);
			BuffConfig buffConfig2 = ConfigSingleton<BuffConfigCategory>.Instance.Get(guildDupStarLevelConfig.OtherBuff);
			Stat[] addStats = buffConfig.AddStats;
			Stat[] addStats2 = buffConfig2.AddStats;
			long id = ((Entity)((Entity)(object)self).LocalPlayer()).Id;
			GuildDupStarLevelInfo levelInfo = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<GuildDupModule>().GetLevelInfo(level);
			self._FirstImg.SetActive(levelInfo.FirstPassPlayerId == playerId);
			self._FirstText.SetActive(levelInfo.FirstPassPlayerId == playerId);
			GuildInfo guildInfo = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<GuildModule>().GuildInfo;
			string text = string.Empty;
			if (id == playerId)
			{
				self._UICommonHead.SetData(((Entity)(object)self).LocalPlayer());
				text = ((Entity)(object)self).LocalPlayer().GetName();
			}
			else
			{
				foreach (GuildMemberInfo member in guildInfo.Members)
				{
					if (member.PlayerInfo.Id == playerId)
					{
						self._UICommonHead.SetData(member.PlayerInfo);
						text = member.PlayerInfo.Name;
						break;
					}
				}
			}
			self._TxtName.SetText(text);
			self._CostText.SetText(Language.Format(4, 803, (levelInfo.FirstPassPlayerId == playerId) ? (addStats[0].Value / 100) : (addStats2[0].Value / 100)));
			if (string.IsNullOrEmpty(text))
			{
				self._TxtName.SetText(Language.Get(4, 831));
			}
		}
	}
