			self._List.Handler.onUpdate += self.OnCellUpdate;
			self._UICommonPopup.SetTitle(Language.Get(4, 804));
		}

		[UIMethod]
		private static void OnShow(this UIGuildDupStarBuffPanel self, int level)
		{
			self.Level = level;
			GuildDupStarLevelInfo levelInfo = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<GuildDupModule>().GetLevelInfo(level);
			GuildDupStarLevelConfig guildDupStarLevelConfig = ConfigSingleton<GuildDupStarLevelConfigCategory>.Instance.Get(level);
			(long, long) dupStarBuffValue = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<GuildDupModule>().GetDupStarBuffValue(level);
			long item = dupStarBuffValue.Item1;
			long item2 = dupStarBuffValue.Item2;
			int num = levelInfo?.PlayerIds.Count ?? 0;
			long num2 = ((num > 0) ? (item + item2 * (num - 1)) : 0);
			self._TxtBuff.SetText(Language.Format(4, 802, guildDupStarLevelConfig.Name, num, num2 / 100));
			self.Lists = new List<long>();
			if (num != 0)
			{
				self.Lists.Add(levelInfo.FirstPassPlayerId);
				foreach (long playerId in levelInfo.PlayerIds)
				{
					if (playerId != levelInfo.FirstPassPlayerId)
					{
						self.Lists.Add(playerId);
					}
				}
			}
			self._List.SetData(self.Lists.Count);
		}

		private static void OnCellUpdate(this UIGuildDupStarBuffPanel self, UIScrollListCell cell)
		{
			int index = cell.Index;
			if (index < self.Lists.Count)
			{
				((Entity)cell.UIObject).GetComponent<UIGuildDupStarBuffItem>().SetData(self.Lists[index], self.Level);
			}
		}
	}
