		private static void UpdateText(this UIGuildDupBossBuyPanel self)
		{
			Player player = ((Entity)(object)self).LocalPlayer();
			ET.ConfigBeans.Item bossBuyFightCountCost = ConfigSingleton<GuildGlobalConfigCategory>.Instance.GetOne().BossBuyFightCountCost;
			int num = self.CurBuyNums * bossBuyFightCountCost.Nums;
			string itemNameWithColor = UIItemHelper.GetItemNameWithColor(bossBuyFightCountCost.Id);
			int maxBuyNums = self.MaxBuyNums;
			bool flag = player.CheckItemNumsIsEnough(bossBuyFightCountCost.Id, num);
			string text = (flag ? TextHelper.FormatEnoughNums(num) : TextHelper.FormatNotEnoughNums(num));
			string str = Language.Format(1, 19, text, itemNameWithColor, self.CurBuyNums, maxBuyNums);
			self._Text.SetText(str);
			self._OkButton.SetGray(!flag);
		}

		private static void OnCloseButtonClick(this UIGuildDupBossBuyPanel self)
		{
			UIManager.Instance.Remove(typeof(UIGuildDupBossBuyPanel));
		}
	}
