		public static void SetData(this UIGuildDupWarIGuildInfoItem self, int actId, bool IsEnemy)
		{
			GuildWarModule activityModule = ActivityHelper.GetActivityModule<GuildWarModule>(((Entity)(object)self).LocalPlayer(), actId);
			if (activityModule == null)
			{
				return;
			}
			GuildWarGlobalConfig one = ConfigSingleton<GuildWarGlobalConfigCategory>.Instance.GetOne();
			long key;
			GuildWarNPCInfo value;
			if (IsEnemy)
			{
				if (activityModule.DefenderMatchInfo != null)
				{
					self._GuildNameText.SetText(activityModule.DefenderMatchInfo.GuildName);
					self._GuildeIconBg.SetRawTexture(ConfigSingleton<GuildFlagConfigCategory>.Instance.Get(activityModule.DefenderMatchInfo.GuildFlag).AssetsName).Coroutine();
					self._GuildeIcon.SetRawTexture(ConfigSingleton<GuildFlagConfigCategory>.Instance.Get(activityModule.DefenderMatchInfo.GuildIcon).AssetsName).Coroutine();
				}
				self._GuildFlag.SetRawTexture("ui_xmzb_frame_04").Coroutine();
				int num = one.StarHpPercent.Length * activityModule.NPCMap.Count;
				foreach (KeyValuePair<long, GuildWarNPCInfo> item in activityModule.NPCMap)
				{
					item.Deconstruct(out key, out value);
					GuildWarNPCInfo guildWarNPCInfo = value;
					num -= guildWarNPCInfo.RemainStar;
				}
				self._GuildServerText.SetText($"x{num}");
			}
			else
			{
				GuildModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<GuildModule>();
				self._GuildFlag.SetRawTexture("ui_xmzb_frame_03").Coroutine();
				self._GuildeIconBg.SetRawTexture(ConfigSingleton<GuildFlagConfigCategory>.Instance.Get(component.GuildInfo.BaseInfo.Flag).AssetsName).Coroutine();
				self._GuildeIcon.SetRawTexture(ConfigSingleton<GuildFlagConfigCategory>.Instance.Get(component.GuildInfo.BaseInfo.Icon).AssetsName).Coroutine();
				self._GuildNameText.SetText(component.GuildInfo.BaseInfo.Name);
				if (activityModule.DefenderMatchInfo.NPCMap != null)
				{
					int num2 = one.StarHpPercent.Length * activityModule.DefenderMatchInfo.NPCMap.Count;
					foreach (KeyValuePair<long, GuildWarNPCInfo> item2 in activityModule.DefenderMatchInfo.NPCMap)
					{
						item2.Deconstruct(out key, out value);
						GuildWarNPCInfo guildWarNPCInfo2 = value;
						num2 -= guildWarNPCInfo2.RemainStar;
					}
					self._GuildServerText.SetText($"x{num2}");
				}
			}
			self._VertoryImg.SetActive(active: false);
		}

		public static void ShowVectoryFlag(this UIGuildDupWarIGuildInfoItem self, string imgName, bool isShow = true)
		{
			self._VertoryImg.SetActive(isShow);
			self._VertoryImg.SetSprite(imgName).Coroutine();
		}

		public static void SetStarNum(this UIGuildDupWarIGuildInfoItem self, int starNum)
		{
			if (starNum != 0)
			{
				string text = ((Text)((Component)self._GuildServerText.Transform).GetComponent<SuperText>()).text;
				int num = int.Parse(text.Substring(1, text.Length - 1));
				self._GuildServerText.SetText($"x{num + starNum}");
			}
		}

		public static UIObject GetStarsObject(this UIGuildDupWarIGuildInfoItem self)
		{
			return self._StartImage;
		}
	}
