		public static void RefreshView(this UIGuildDupWarOpenPanel self)
		{
			GuildWarModule activityModule = ActivityHelper.GetActivityModule<GuildWarModule>(((Entity)(object)self).LocalPlayer(), self.ActId);
			Log.Info($"UIGuildDupWarOpenPanel RoundStartTime = {TimeHelper.ToDateTime(activityModule.RoundStartTime)}  " + $"   RoundEndTime ={TimeHelper.ToDateTime(activityModule.RoundEndTime)}" + $"  ActivityData starttime ={TimeHelper.ToDateTime(self.ActivityData.StartTime)}" + $"  ActivityData endtime ={TimeHelper.ToDateTime(self.ActivityData.EndTime)}" + $"  round = {activityModule.Round}" + $"  IsBye = {activityModule.IsBye}" + $"  IsByeReward = {activityModule.IsByeReward}");
			if (activityModule.IsBye && activityModule.DefenderMatchInfo == null)
			{
				if (activityModule.Round == 5)
				{
					self.ShowRoundOver();
					self.OpenTime = activityModule.ActivityData.EndTime;
				}
				else if (!activityModule.IsByeReward)
				{
					self.ActivityLunKong();
					self.OpenTime = activityModule.RoundEndTime;
				}
				else
				{
					self.ShowRoundOver();
					self.OpenTime = activityModule.ActivityData.EndTime;
				}
				if (self.CountDownTimerTop <= 0)
				{
					self.CountDownTimerTop = self.NewTimer(1000L, self.CountDownTop, repeat: true);
					self.CountDownTop();
				}
				return;
			}
			if (TimeHelper.Now() >= self.ActivityData.StartTime)
			{
				switch (activityModule.Round)
				{
				case 0:
					self._OpenTipsText.SetText(Language.Get(3, 204));
					self.ActivityWatting();
					break;
				case 5:
					self.ActivityWatting();
					self._OpenTipsText.SetText(Language.Get(3, 232));
					self._OpenTimer.SetActive(active: false);
					break;
				case 1:
					self.ActivityMatching();
					break;
				case 2:
					if (activityModule.DefenderMatchInfo == null)
					{
						Log.Warning($"轮次：{2} matchInfo is null");
						self._OpenTipsText.SetText(Language.Get(3, 204));
						self.ActivityWatting();
					}
					else
					{
						self.ShowOpenWarAni();
						self.ActivityPrepare();
					}
					break;
				case 3:
					if (activityModule.NPCMap == null || activityModule.DefenderMatchInfo == null || activityModule.NPCMap == null)
					{
						self.ShowPassBattleInfo();
						break;
					}
					self.ShowOpenWarAni();
					self.ShowBattleView();
					break;
				case 4:
					self._OpenTipsText.SetText(Language.Get(3, 215));
					self.ActivityWatting();
					break;
				}
				if (activityModule.Round == 0 || activityModule.Round == 5 || activityModule.Round == 4 || (activityModule.Round == 3 && (activityModule.NPCMap == null || activityModule.DefenderMatchInfo == null || activityModule.NPCMap == null)))
				{
					self.OpenTime = self.ActivityData.EndTime;
				}
				else if (activityModule.Round == 1 || activityModule.Round == 2)
				{
					self.OpenTime = activityModule.RoundEndTime;
				}
				else
				{
					self.OpenTime = activityModule.RoundStartTime;
				}
				if (activityModule.DefenderMatchInfo == null && activityModule.Round == 2)
				{
					self.OpenTime = self.ActivityData.EndTime;
				}
			}
			else
			{
				self.ActivityWatting();
				self._OpenTipsText.SetActive(active: false);
				self._OpenText.SetText(Language.Get(3, 230));
				self.OpenTime = self.ActivityData.StartTime;
			}
			if (self.CountDownTimerTop <= 0)
			{
				self.CountDownTimerTop = self.NewTimer(1000L, self.CountDownTop, repeat: true);
				self.CountDownTop();
			}
		}

