		public static void UpdateView(this UIGuildDupWarRankStatePanel self)
		{
			self.Configs = ConfigSingleton<GuildWarLevelConfigCategory>.Instance.GetList();
			GuildWarModule component = ((Entity)((Entity)(object)self).LocalPlayer().GetActivityDataByType(ActivityType.GuildWar)).GetComponent<GuildWarModule>();
			GuildWarLevelConfig guildWarLevelConfigByScore = component.GetGuildWarLevelConfigByScore(component.Score);
			DanStarConfig danConfig = ConfigSingleton<DanStarConfigCategory>.Instance.Get(guildWarLevelConfigByScore.LevelId);
			if (danConfig != null)
			{
				int num = self.Configs.FindIndex((GuildWarLevelConfig x) => x.LevelId == danConfig.Id);
				self._StageList.SetData(self.Configs.Count);
				self._StageList.MovePanelToItemIndex(math.max(0, num - 1));
			}
		}

		public static void OnUpdateCell(this UIGuildDupWarRankStatePanel self, UIScrollListCell cell)
		{
			int index = cell.Index;
			((Entity)cell.UIObject).GetComponent<UIGuildDupWarRankStateItem>().SetData(self.Configs[index]);
		}
	}
