		[UIMethod]
		private static void OnShow(this UIGuildDupWarResultPanel self, ActivityData activityData)
		{
			self.ActId = activityData.ActivityId;
			GuildWarModule activityModule = ActivityHelper.GetActivityModule<GuildWarModule>(((Entity)(object)self).LocalPlayer(), self.ActId);
			GuildWarLevelConfig guildWarLevelConfigByScore = activityModule.GetGuildWarLevelConfigByScore(activityModule.Score);
			if (ConfigSingleton<DanStarConfigCategory>.Instance.Get(guildWarLevelConfigByScore.LevelId) != null)
			{
				string text = ((activityModule.RoundScore > 0) ? "#5dfa49" : "#e73333");
				string text2 = ((activityModule.RoundScore >= 0) ? $"+{activityModule.RoundScore}" : $"{activityModule.RoundScore}");
				self._ScoreText.SetText("段位积分：<color=" + text + ">" + text2 + "</color>");
				self._OkText.SetText("确 认");
				ET.ConfigBeans.Item[] rewards = (activityModule.IsWinner ? guildWarLevelConfigByScore.WinAwards : guildWarLevelConfigByScore.LoseAwards);
				self._RewardList.SetData(rewards);
				self.RefreshDan();
			}
		}

		private static void RefreshDan(this UIGuildDupWarResultPanel self)
		{
			GuildWarModule activityModule = ActivityHelper.GetActivityModule<GuildWarModule>(((Entity)(object)self).LocalPlayer(), self.ActId);
			self.OldScore = activityModule.Score - activityModule.RoundScore;
			Log.Info($"RefreshDan GuildWarResult  = {activityModule.Score}  ==old = {self.OldScore}");
			GuildWarLevelConfig guildWarLevelConfigByScore = activityModule.GetGuildWarLevelConfigByScore(activityModule.Score);
			DanStarConfig danStarConfig = ConfigSingleton<DanStarConfigCategory>.Instance.Get(guildWarLevelConfigByScore.LevelId);
			GuildWarLevelConfig guildWarLevelConfigByScore2 = activityModule.GetGuildWarLevelConfigByScore(self.OldScore);
			DanStarConfig danStarConfig2 = ConfigSingleton<DanStarConfigCategory>.Instance.Get(guildWarLevelConfigByScore2.LevelId);
			if (danStarConfig.Dan > danStarConfig2.Dan)
			{
				self.ShowChangeDanAni();
				return;
			}
			self.ShowSliderValue(activityModule.Score);
			self._Level.ShowDanAni(guildWarLevelConfigByScore.LevelId, danStarConfig2.Dan, delegate
			{
			}, isShowBone: false);
		}

		private static void ShowChangeDanAni(this UIGuildDupWarResultPanel self)
		{
			//IL_00ea: Unknown result type (might be due to invalid IL or missing references)
			//IL_00f4: Expected O, but got Unknown
			//IL_0105: Unknown result type (might be due to invalid IL or missing references)
			//IL_010f: Expected O, but got Unknown
			//IL_0116: Unknown result type (might be due to invalid IL or missing references)
			//IL_0120: Expected O, but got Unknown
			GuildWarModule module = ActivityHelper.GetActivityModule<GuildWarModule>(((Entity)(object)self).LocalPlayer(), self.ActId);
			self.ShowSliderValue(self.OldScore);
			GuildWarLevelConfig levelConfig = module.GetGuildWarLevelConfigByScore(module.Score);
			GuildWarLevelConfig OldLevelConfig = module.GetGuildWarLevelConfigByScore(self.OldScore);
			DanStarConfig oldDanConfig = ConfigSingleton<DanStarConfigCategory>.Instance.Get(OldLevelConfig.LevelId);
			GuildWarLevelConfig preOldLevelConfig = null;
			if (OldLevelConfig.Id > 1)
			{
				preOldLevelConfig = ConfigSingleton<GuildWarLevelConfigCategory>.Instance.Get(OldLevelConfig.Id - 1);
			}
			TweenSettingsExtensions.OnComplete<Sequence>(TweenSettingsExtensions.AppendCallback(TweenSettingsExtensions.AppendInterval(TweenSettingsExtensions.AppendCallback(TweenSettingsExtensions.AppendInterval(self.UIObject.DOSequence(), 0.1f), (TweenCallback)delegate
			{
				int num = preOldLevelConfig?.Score ?? 0;
				self.ShowSliderAni(self.OldScore - OldLevelConfig.Score, OldLevelConfig.Score - num, OldLevelConfig.Score - num);
			}), 1f), (TweenCallback)delegate
			{
				self._Level.ShowDanAni(levelConfig.LevelId, oldDanConfig.Dan, delegate
				{
				});
			}), (TweenCallback)delegate
			{
				self.ShowSliderValue(module.Score);
			});
		}

		private static void ShowSliderValue(this UIGuildDupWarResultPanel self, int score)
		{
			GuildWarModule activityModule = ActivityHelper.GetActivityModule<GuildWarModule>(((Entity)(object)self).LocalPlayer(), self.ActId);
			GuildWarLevelConfig guildWarLevelConfigByScore = activityModule.GetGuildWarLevelConfigByScore(score);
			DanStarConfig danStarConfig = ConfigSingleton<DanStarConfigCategory>.Instance.Get(guildWarLevelConfigByScore.LevelId);
			self._StageText.SetText(danStarConfig.Name);
			GuildWarLevelConfig guildWarLevelConfig = ConfigSingleton<GuildWarLevelConfigCategory>.Instance.GetAll().Last().Value;
			if (ConfigSingleton<GuildWarLevelConfigCategory>.Instance.Contain(guildWarLevelConfigByScore.Id + 1))
			{
				guildWarLevelConfig = ConfigSingleton<GuildWarLevelConfigCategory>.Instance.Get(guildWarLevelConfigByScore.Id + 1);
			}
			SuperSlider component = ((Component)self._ScorePro.Transform).GetComponent<SuperSlider>();
			if (guildWarLevelConfig == guildWarLevelConfigByScore)
			{
				GuildWarLevelConfig guildWarLevelConfig2 = ConfigSingleton<GuildWarLevelConfigCategory>.Instance.Get(guildWarLevelConfigByScore.Id - 1);
				int num = guildWarLevelConfig.Score - guildWarLevelConfig2.Score;
				self._ScoreProText.SetText($"{score - guildWarLevelConfigByScore.Score + num}/{num}");
				((Slider)component).value = (float)(score - guildWarLevelConfigByScore.Score + num) * 1f / (float)num;
			}
			else
			{
				self._ScoreProText.SetText($"{score - guildWarLevelConfigByScore.Score}/{guildWarLevelConfig.Score - guildWarLevelConfigByScore.Score}");
				((Slider)component).value = (float)(score - guildWarLevelConfigByScore.Score) * 1f / (float)(guildWarLevelConfig.Score - guildWarLevelConfigByScore.Score);
			}
			Log.Info($"ShowSliderValue  === {activityModule.Score}    slider.value = {((Slider)component).value}");
		}

		private static void ShowSliderAni(this UIGuildDupWarResultPanel self, int startValue, int endValue, int sliderMax)
		{
			//IL_008f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0099: Expected O, but got Unknown
			GuildWarModule module = ActivityHelper.GetActivityModule<GuildWarModule>(((Entity)(object)self).LocalPlayer(), self.ActId);
			SuperSlider slider = self._ScorePro.GameObject.GetComponent<SuperSlider>();
			TweenSettingsExtensions.OnComplete<Tweener>(TweenSettingsExtensions.SetEase<Tweener>(DOVirtual.Float((float)startValue, (float)endValue, 0.5f, (TweenCallback<float>)delegate(float value)
			{
				Log.Info(string.Format("value:{0}  value == {1}  sliderMax == {2}   sliderValue == {3}", new object[4]
				{
					startValue,
					value,
					endValue,
					value * 1f / (float)sliderMax
				}));
				((Slider)slider).value = value * 1f / (float)sliderMax;
			}), (Ease)1), (TweenCallback)delegate
			{
				GuildWarLevelConfig guildWarLevelConfigByScore = module.GetGuildWarLevelConfigByScore(module.Score);
				GuildWarLevelConfig guildWarLevelConfig = null;
				if (guildWarLevelConfigByScore.Id > 1)
				{
					guildWarLevelConfig = ConfigSingleton<GuildWarLevelConfigCategory>.Instance.Get(guildWarLevelConfigByScore.Id - 1);
				}
				int num = module.Score - guildWarLevelConfigByScore.Score;
				if (endValue != num)
				{
					DanStarConfig danStarConfig = ConfigSingleton<DanStarConfigCategory>.Instance.Get(guildWarLevelConfigByScore.LevelId);
					self._StageText.SetText(danStarConfig.Name);
					self.ShowSliderAni(0, num, guildWarLevelConfigByScore.Score - guildWarLevelConfig.Score);
				}
			});
		}
	}
