		[UIMethod]
		private static void OnShow(this UIGuildDupWarShowRewardPanel self, int actId)
		{
			self.ActId = actId;
			GuildWarModule activityModule = ActivityHelper.GetActivityModule<GuildWarModule>(((Entity)(object)self).LocalPlayer(), self.ActId);
			if (activityModule == null)
			{
				return;
			}
			GuildWarLevelConfig guildWarLevelConfigByScore = activityModule.GetGuildWarLevelConfigByScore(activityModule.Score);
			DanStarConfig danStarConfig = ConfigSingleton<DanStarConfigCategory>.Instance.Get(guildWarLevelConfigByScore.LevelId);
			if (danStarConfig == null)
			{
				return;
			}
			self.GuildDan = danStarConfig.Dan;
			self.GuildStar = danStarConfig.Star;
			foreach (KeyValuePair<int, DanStarConfig> item in ConfigSingleton<DanStarConfigCategory>.Instance.GetAll())
			{
				var (id, danStarConfig3) = item;
				if (danStarConfig3.Dan == self.GuildDan && danStarConfig3.Star == self.GuildStar)
				{
					List<GuildWarLevelConfig> list = ConfigSingleton<GuildWarLevelConfigCategory>.Instance.GetAll().Values.ToList();
					self.DanStarConfig = list.Find((GuildWarLevelConfig x) => x.LevelId == id);
					break;
				}
			}
			self.DanStarLastConfig = self.GetLastConfig();
