	public static class UISceneAdapterHelper
	{
		public static void SetCameraSize(Camera camera, float OriginCameraSize, float DestinCameraSize)
		{
			float num = DestinCameraSize - OriginCameraSize;
			float num2 = 0.5622189f;
			float num3 = 0.45f;
			float num4 = float.Parse(Screen.width.ToString()) / float.Parse(Screen.height.ToString());
			if (num4 >= num2)
			{
				camera.orthographicSize = OriginCameraSize;
				return;
			}
			if (num4 <= num3)
			{
				camera.orthographicSize = DestinCameraSize;
				return;
			}
			float num5 = num / (num2 - num3);
			camera.orthographicSize = OriginCameraSize + num5 * (num2 - num4);
		}
	}
