	[RedPointHandler(RedPointType.HeavenFight_Enter)]
	public class HeavenFightRedPointHandler : ARedPointHandler
	{
		public override int GetCount(Scene scene, params int[] parameters)
		{
			Player player = ((Entity)(object)scene).LocalPlayer();
			if (player == null)
			{
				return 0;
			}
			if (!player.CheckFuncOpen(5012, IsCheckParent: true))
			{
				return 0;
			}
			ActivityData activityByType = ((Entity)player).GetComponent<PlayerActivityComponent>().GetActivityByType(ActivityType.HeavenFight);
			if (activityByType == null)
			{
				return 0;
			}
			if (activityByType.State != ActivityState.Open)
			{
				return 0;
			}
			long localLong = player.GetLocalLong("HeavenFightRedPoint", 0L);
			if (!TimeHelper.IsSameDay(TimeHelper.Now(), localLong, 18000000L))
			{
				return 1;
			}
			UIRedPointComponent component = ((Entity)scene).GetComponent<UIRedPointComponent>();
			if (component.Handlers.TryGetValue(RedPointType.HeavenFight_Hurt, out var value) && value.GetCount(scene) > 0)
			{
				return 1;
			}
			if (component.Handlers.TryGetValue(RedPointType.HeavenFight_Platform, out var value2))
			{
				HeavenFightModule component2 = ((Entity)activityByType).GetComponent<HeavenFightModule>();
				if (component2 != null)
				{
					foreach (HeavenFightConfig platformCfgData in component2.GetPlatformCfgDataList())
					{
						if (value2.GetCount(scene, platformCfgData.PlatformId) > 0)
						{
							return 1;
						}
					}
				}
			}
			return 0;
