		}

		public static void SetData(this UIHeavenFightDamageRewardItem self, HeavenFightHarmConfig config, int ActivityId)
		{
			self.ActivityId = ActivityId;
			self.RewardId = config.Id;
			self._DamageText.SetText(config.Harm.ToString("N0"));
			self._UIScrollHorizontalList.SetData(config.Rewarditem);
			self._GetButton.SetRedPoint(RedPointType.HeavenFight_HurtReward, self.RewardId).Coroutine();
			self.State = self.GetState(config.Harm);
			self.ShowBtnView();
		}

		private static void ShowBtnView(this UIHeavenFightDamageRewardItem self)
		{
			switch (self.State)
			{
			case HeavenFightRewardState.HasGet:
				self._GetButton.SetActive(active: false);
				self._AlreadyGetImage.SetActive(active: true);
				break;
			case HeavenFightRewardState.HasReward:
				self._GetButton.SetActive(active: true);
				self._AlreadyGetImage.SetActive(active: false);
				self._GetButton.SetGray(isGray: false);
				self._RewardText.SetText(Language.Format(7, 4));
				break;
			default:
				self._GetButton.SetActive(active: true);
				self._AlreadyGetImage.SetActive(active: false);
				self._GetButton.SetGray();
				self._RewardText.SetText(Language.Format(7, 5));
				break;
			}
		}

		private static HeavenFightRewardState GetState(this UIHeavenFightDamageRewardItem self, long damage)
		{
			HeavenFightModule activityModule = ActivityHelper.GetActivityModule<HeavenFightModule>(((Entity)(object)self).LocalPlayer(), self.ActivityId);
			if (activityModule != null)
			{
				if (activityModule.HasGetHurtReward(self.RewardId))
				{
					return HeavenFightRewardState.HasGet;
				}
				if (activityModule.HistoryMaxDamage >= damage)
				{
					return HeavenFightRewardState.HasReward;
				}
			}
			return HeavenFightRewardState.None;
		}

		private static void OnGetButtonClick(this UIHeavenFightDamageRewardItem self)
		{
			if (self.State == HeavenFightRewardState.HasReward)
			{
				self.ReqGetReward().Coroutine();
			}
			else
			{
				UIGameMsgHelper.FloatMsgByError(209007);
			}
		}

