		[UIMethod]
		public static void OnShow(this UIHeavenFightDamageRewardPanel self, int ActivityId)
		{
			self.ActivityId = ActivityId;
			self.UpdateView();
		}

		public static void UpdateView(this UIHeavenFightDamageRewardPanel self)
		{
			HeavenFightModule activityModule = ActivityHelper.GetActivityModule<HeavenFightModule>(((Entity)(object)self).LocalPlayer(), self.ActivityId);
			if (activityModule != null)
			{
				long historyMaxDamage = activityModule.HistoryMaxDamage;
				self.ShowHurtView(activityModule, historyMaxDamage);
				self.ShowRewardView(activityModule, historyMaxDamage);
			}
		}

		private static void ShowRewardView(this UIHeavenFightDamageRewardPanel self, HeavenFightModule module, long HistoryMaxDamage)
		{
			self.HarmCfgList = module.GetHarmCfgList();
			int num = self.HarmCfgList.Count;
			for (int i = 0; i < self.HarmCfgList.Count; i++)
			{
				if (self.HarmCfgList[i].Harm > HistoryMaxDamage)
				{
					num = i;
					break;
				}
			}
			self.ShowCount = Math.Min(num + ConfigSingleton<GlobalConfigCategory>.Instance.GetOne().HeavenFightHurtShow, self.HarmCfgList.Count);
			self._UIScrollList.SetData(self.ShowCount);
			self._None.SetActive(self.ShowCount <= 0);
			if (self.ShowCount > 0 && num > 0)
			{
				self._UIScrollList.MovePanelToItemIndex(num);
			}
		}

		private static void ShowHurtView(this UIHeavenFightDamageRewardPanel self, HeavenFightModule module, long HistoryMaxDamage)
		{
			int num = 0;
			num = ((HistoryMaxDamage == 0L) ? 1 : ((int)Math.Log10(HistoryMaxDamage) + 1));
			string format = Language.Get(7, 9);
			UIHelper.SetText(str: (num < 15) ? string.Format(format, HistoryMaxDamage.ToString("N0")) : string.Format(format, TextHelper.FormatDamage(HistoryMaxDamage)), self: self._DamageText);
		}

		private static void OnCellUpdate(this UIHeavenFightDamageRewardPanel self, UIScrollListCell cell)
		{
			int index = cell.Index;
			if (index < self.ShowCount)
			{
				((Entity)cell.UIObject).GetComponent<UIHeavenFightDamageRewardItem>().SetData(self.HarmCfgList[index], self.ActivityId);
			}
		}
	}
