		[UIMethod]
		public static void OnShow(this UIHeavenFightPanel self, UIShowArgs args)
		{
			ActivityData activityDataByType = ((Entity)(object)self).LocalPlayer().GetActivityDataByType(ActivityType.HeavenFight);
			if (activityDataByType != null)
			{
				self._DemageButton.SetRedPoint(RedPointType.HeavenFight_Hurt).Coroutine();
				self.ActivityId = activityDataByType.ActivityId;
				ActivityHelper.GetActivityModule<HeavenFightModule>(((Entity)(object)self).LocalPlayer(), self.ActivityId)?.RequestHeavenFightShowTips();
				self.UpdateView();
			}
		}

