		public static void OnDestroy(this UIHeavenFightPanel self)
		{
			self.StopCountTimer();
		}

		private static void UpdateReadRedPoint(this UIHeavenFightPanel self)
		{
			((Entity)(object)self).LocalPlayer().SetLocalLong("HeavenFightRedPoint", TimeHelper.Now());
			RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.HeavenFight_Enter);
			RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.BattleGroundEnter);
			RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.HeavenlyCourt);
		}

		private static void UpdateView(this UIHeavenFightPanel self)
		{
			HeavenFightModule activityModule = ActivityHelper.GetActivityModule<HeavenFightModule>(((Entity)(object)self).LocalPlayer(), self.ActivityId);
			if (activityModule == null)
			{
				return;
			}
			foreach (HeavenFightConfig platformCfgData in activityModule.GetPlatformCfgDataList())
			{
				if (self.UIPlayerItems.Count >= platformCfgData.PlatformId)
				{
					HeavenFightPlatformInfo platformInfo = activityModule.GetPlatformInfo(platformCfgData.PlatformId);
					HeavenFightData warData = self.GetWarData(activityModule, platformCfgData, platformInfo);
					warData.SrcType = 1;
					self.UIPlayerItems[platformCfgData.PlatformId - 1]?.SetData(warData, self.ActivityId);
				}
			}
			self.StartLeftTime(activityModule);
		}

		private static void StartLeftTime(this UIHeavenFightPanel self, HeavenFightModule module)
		{
			self.StopCountTimer();
			self.CountDownTimer = self.NewTimer(1000L, UpdateLeftTimeText, repeat: true);
			UpdateLeftTimeText();
			void UpdateLeftTimeText()
			{
				self._UITimeCountDownBox.SetText(UIActivityHelper.GetCountDownText(module.ActivityData));
			}
		}

		private static void StopCountTimer(this UIHeavenFightPanel self)
		{
			if (self.CountDownTimer > 0)
			{
				self.RemoveTimer(ref self.CountDownTimer);
			}
		}

		private static HeavenFightData GetWarData(this UIHeavenFightPanel self, HeavenFightModule module, HeavenFightConfig config, HeavenFightPlatformInfo platformInfo)
		{
			HeavenFightData heavenFightData = new HeavenFightData();
			heavenFightData.TitleId = config.TitleId;
			heavenFightData.PlatformId = config.PlatformId;
			if (platformInfo != null && !platformInfo.IsBoss)
			{
				HeavenFightOpponentInfo opponentInfo = platformInfo.OpponentInfo;
				heavenFightData.isPlayer = true;
				heavenFightData.PlayerId = opponentInfo.PlayerId;
				heavenFightData.PlayerName = opponentInfo.PlayerName;
				heavenFightData.Power = opponentInfo.Power;
				heavenFightData.ModelId = opponentInfo.ModelId;
				heavenFightData.CapeId = opponentInfo.CapeId;
				heavenFightData.WeaponId = opponentInfo.WeaponId;
				heavenFightData.GuardCount = opponentInfo.GuardCount;
				heavenFightData.heros = opponentInfo.formationInfo?.Heroes;
				heavenFightData.OpponentId = opponentInfo.PlayerId;
				HeavenFightBossConfig bossCfg = module.GetBossCfg(config.PlatformId, config.DifficultyId);
				heavenFightData.DifficultyId = bossCfg.Stage;
				if (((Entity)((Entity)(object)self).LocalPlayer()).Id == opponentInfo.PlayerId)
				{
					heavenFightData.Head = bossCfg.Head;
					heavenFightData.Detail = bossCfg.Desc;
					heavenFightData.BossPower = bossCfg.RecommendFighting;
					heavenFightData.BossName = bossCfg.BossName;
					heavenFightData.OpponentId = bossCfg.MonsterId[0];
				}
			}
			else
			{
				HeavenFightBossConfig bossCfg2 = module.GetBossCfg(config.PlatformId, config.DifficultyId);
				heavenFightData.isPlayer = false;
				heavenFightData.PlayerId = bossCfg2.MonsterId[0];
				heavenFightData.PlayerName = bossCfg2.BossName;
				heavenFightData.Head = bossCfg2.Head;
				heavenFightData.ModelId = bossCfg2.ModelId;
				heavenFightData.Power = bossCfg2.RecommendFighting;
				heavenFightData.BossPower = bossCfg2.RecommendFighting;
				heavenFightData.Detail = bossCfg2.Desc;
				heavenFightData.DifficultyId = bossCfg2.Stage;
				heavenFightData.BossName = bossCfg2.BossName;
				heavenFightData.OpponentId = bossCfg2.MonsterId[0];
			}
			return heavenFightData;
		}

