		[UIMethod]
		private static void OnShow(this UIHeavenFightSuccessContent self, (int, long) args)
		{
			self._DamageText.SetText(TextHelper.FormatDamage(args.Item2));
			self._UIAttScrollList.SetActive(active: false);
			ActivityData activityDataByType = ((Entity)(object)self).LocalPlayer().GetActivityDataByType(ActivityType.HeavenFight);
			if (activityDataByType == null)
			{
				return;
			}
			HeavenFightModule activityModule = ActivityHelper.GetActivityModule<HeavenFightModule>(((Entity)(object)self).LocalPlayer(), activityDataByType.ActivityId);
			if (activityModule == null)
			{
				return;
			}
			self._RecordImage.SetActive(args.Item2 == activityModule.HistoryMaxDamage && args.Item2 > activityModule.LastMaxDamage);
			HeavenFightConfig platformCfgData = activityModule.GetPlatformCfgData(args.Item1);
			if (platformCfgData == null)
			{
				return;
			}
			HeavenFightBossConfig bossCfg = activityModule.GetBossCfg(args.Item1, platformCfgData.DifficultyId);
			if (bossCfg != null)
			{
				List<string> attStrings = new List<string>();
				Stat[] addStat = bossCfg.AddStat;
				for (int i = 0; i < addStat.Length; i++)
				{
					string item = TextHelper.FormatStat(addStat[i], "<color=#5dfa49>+{0}</color>");
					attStrings.Add(item);
				}
				self._UIAttScrollList.SetActive(active: true);
				self._AttText.CloneAll(attStrings, delegate(int index, string name, UIObject obj)
				{
					obj.SetText(attStrings[index]);
				}).Coroutine();
				self._AttText.SetActive(active: false);
				LayoutRebuilder.ForceRebuildLayoutImmediate(self._UIAttScrollList.Transform);
			}
		}

