		{
			HeavenTowerDupModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<HeavenTowerDupModule>();
			int num = component.GetNextReachId();
			if (num == 0)
			{
				num = component.GetedReachId;
			}
			self.nextReachId = num;
			Dictionary<int, HeavenTowerDupLevelConfig> all = ConfigSingleton<HeavenTowerDupLevelConfigCategory>.Instance.GetAll();
			self.Lists.Clear();
			int num2 = 0;
			int num3 = 0;
			foreach (HeavenTowerDupLevelConfig value in all.Values)
			{
				if (value.ReachDropId > 0)
				{
					self.Lists.Add(value);
					if (value.Id == num)
					{
						num3 = num2;
					}
					num2++;
				}
			}
			self._UIRewardScroll.SetData(self.Lists.Count);
			self._UIRewardScroll.MovePanelToItemIndex((num3 > 0) ? (num3 - 1) : num3);
		}

