	{
		public override int GetCount(Scene scene, params int[] parameters)
		{
			Player player = ((Entity)scene).GetComponent<LocalPlayerComponent>().Player;
			if (player == null || !player.IsFuncOpen(2))
			{
				return 0;
			}
			UIRedPointComponent component = ((Entity)scene).GetComponent<UIRedPointComponent>();
			foreach (Hero hero in player.GetHeroes())
			{
				if (!hero.IsActive && hero.CanActive())
				{
					return 1;
				}
				if (hero.IsActive && hero.IsFormation() && component.Handlers.TryGetValue(RedPointType.Hero_Card, out var value) && value.GetRedPointCount(scene, hero.ConfigId) > 0)
				{
					return 1;
				}
			}
			if (component.Handlers.TryGetValue(RedPointType.Hero_Manual, out var value2) && value2.GetRedPointCount(scene) > 0)
			{
				return 1;
			}
			if (component.Handlers.TryGetValue(RedPointType.Hero_Relate, out var value3) && value3.GetRedPointCount(scene) > 0)
			{
				return 1;
			}
			if (component.Handlers.TryGetValue(RedPointType.Hero_Formation, out var value4) && value4.GetRedPointCount(scene) > 0)
			{
				return 1;
