	[RedPointHandler(RedPointType.Hero_Formation)]
	public class HeroFormationRedPointHandler : ARedPointHandler
	{
		public override int GetCount(Scene scene, params int[] parameters)
		{
			Player player = ((Entity)(object)scene).LocalPlayer();
			int valueOrDefault = parameters.GetValueOrDefault(0, 0);
			if (valueOrDefault == 0)
			{
				Formation commonFormation = player.GetCommonFormation();
				if (commonFormation.PosHero.Count >= commonFormation.Config.Max)
				{
					return 0;
				}
				if (commonFormation.PosHero.Count < player.GetHeroes(new HeroSearch
				{
					Includes = HeroInclude.All,
					OnlyActive = true
				}).Count)
				{
					return 1;
				}
				return 0;
			}
			FormationComponent component = ((Entity)((Entity)(object)scene).GetCurrentScene()).GetComponent<FormationComponent>();
			if (component == null || component.CurrentFormationId != valueOrDefault)
			{
				if (!FormationHelper.IsAnyVacantPosition(player, valueOrDefault))
				{
					return 0;
				}
				return 1;
			}
			if (!component.IsAnyVacantPosition())
			{
				return 0;
			}
			return 1;
		}
	}
