		public static void RefreshView(this UIHeroAddStarPanel self, Hero hero)
		{
			self.Hero = hero;
			var (currentStats, diffStats) = self.Hero.GetNextStarStatsChange();
			self.UpdateAttributes(currentStats, diffStats);
			self.UpdateBasicInfo();
			self.UpdateSkillInfo();
			HeroStarConfig heroStarConfig = null;
			HeroStarConfig heroStarConfig2 = null;
			HeroStarConfigCategory instance = ConfigSingleton<HeroStarConfigCategory>.Instance;
			int num = 1;
			while (true)
			{
				int id = hero.ConfigId * 100 + num;
				if (!instance.Contain(id))
				{
					break;
				}
				HeroStarConfig heroStarConfig3 = instance.Get(id);
				if (heroStarConfig3.SpecialSkill > 0)
				{
					if (heroStarConfig3.Star <= hero.Star)
					{
						heroStarConfig = heroStarConfig3;
					}
					else if (heroStarConfig2 == null)
					{
						heroStarConfig2 = heroStarConfig3;
					}
				}
				num++;
			}
			if (heroStarConfig2 != null)
			{
				HeroSkillData data = new HeroSkillData
				{
					SkillLevel = new SkillLevel(heroStarConfig2.SpecialSkill),
					UnlockStar = heroStarConfig2.Star
				};
				self._UIHeroSkill.SetData(self.Hero, data, showLock: true);
				self._UIHeroSkill.UIObject.SetActive(active: true);
			}
			else if (heroStarConfig != null)
			{
				HeroSkillData data2 = new HeroSkillData
				{
					SkillLevel = new SkillLevel(heroStarConfig.SpecialSkill),
					UnlockStar = heroStarConfig.Star
				};
				self._UIHeroSkill.SetData(self.Hero, data2, showLock: false);
				self._UIHeroSkill.UIObject.SetActive(active: true);
			}
			self._UIHeroSkill.UIObject.SetActive(active: false);
			self._BtnUpStar.SetRedPoint(RedPointType.Hero_Star, self.Hero.ConfigId).Coroutine();
		}

