		private static void UpdateAttributes(this UIHeroAddStarPanel self, List<Stat> currentStats, List<Stat> diffStats)
		{
			if (currentStats == null)
			{
				self._AttrItem.CloneAll(0, null).Coroutine();
				return;
			}
			StatList currentList = StatList.Create();
			try
			{
				currentList.AddRange(currentStats);
				using StatList statList = StatList.Create();
				if (diffStats != null)
				{
