				}
				self._AttrItem.CloneAll(currentList.Count, delegate(int i, UIObject o)
				{
					StatStruct stat = currentList[i];
					string text = "<color=#9C9DAC>" + stat.GetName() + "</color>";
					if (self.Hero.IsMaxStar || diffStats == null)
					{
						o.Find("CurValue").SetText(text);
						o.Find("AddValue").SetText("+" + stat.GetValueText());
					}
					else
					{
						Stat stat2 = diffStats.FirstOrDefault((Stat s) => s.Type == stat.Type);
						o.Find("CurValue").SetText(text + ": <color=#ffffff>" + TextHelper.FormatStatValue(stat.Type, stat.Value) + "</color>");
						if (stat2 != null)
						{
							o.Find("AddValue").SetText("+" + TextHelper.FormatStatValue(stat2.Type, stat2.Value));
						}
						else
						{
							o.Find("AddValue").SetText("+0");
						}
					}
				}).Coroutine();
			}
			finally
			{
				if (currentList != null)
				{
					((IDisposable)currentList).Dispose();
				}
			}
		}

