			HeroSkillData nextStarSkillChange = self.Hero.GetNextStarSkillChange();
			if (nextStarSkillChange == null)
			{
				self._Skill.SetActive(active: false);
				self._SliderPanel.Transform.anchoredPosition = Vector2.zero;
				((Component)self._SliderPanel.Transform).GetComponent<RectTransform>().sizeDelta = new Vector2(500f, 40f);
				return;
			}
			self._TxtSkillName.SetText(nextStarSkillChange.SkillLevel.Name());
