	public static class UIHeroHelper
	{
		public static string GetSmallIcon(int iconId)
		{
			return $"uitex_hero_image_{iconId}";
		}

		public static string GetHeaderIcon(int iconId)
		{
			return $"uitex_head_{iconId}";
		}

		public static int GetIconId(Hero hero)
		{
			if (ConfigSingleton<HeroSkinConfigCategory>.Instance.Contain(hero.CurrentSkin))
			{
				return ConfigSingleton<HeroSkinConfigCategory>.Instance.Get(hero.CurrentSkin).IconId;
			}
			return hero.ConfigId;
		}

		public static string GetSmallIcon(Hero hero)
		{
			if (ConfigSingleton<HeroSkinConfigCategory>.Instance.Contain(hero.CurrentSkin))
			{
				return GetSmallIcon(ConfigSingleton<HeroSkinConfigCategory>.Instance.Get(hero.CurrentSkin).IconId);
			}
			return GetSmallIcon(hero.ConfigId);
		}

		public static string GetSmallIcon(HeroInfo heroInfo)
		{
			if (ConfigSingleton<HeroSkinConfigCategory>.Instance.Contain(heroInfo.SkinInfo?.SkinId ?? 0))
			{
				return GetSmallIcon(ConfigSingleton<HeroSkinConfigCategory>.Instance.Get(heroInfo.SkinInfo.SkinId).IconId);
			}
			return GetSmallIcon(heroInfo.ConfigId);
		}

		public static string GetSmallIcon(HeroCommonInfo heroCommonInfo)
		{
			if (ConfigSingleton<HeroSkinConfigCategory>.Instance.Contain(heroCommonInfo.SkinInfo?.SkinId ?? 0))
			{
				return GetSmallIcon(ConfigSingleton<HeroSkinConfigCategory>.Instance.Get(heroCommonInfo.SkinInfo.SkinId).IconId);
			}
			return GetSmallIcon(heroCommonInfo.ConfigId);
		}

		public static string GetSmallIcon(HeroCardInfo heroCardInfo)
		{
			int heroSkinId = heroCardInfo.HeroSkinId;
			if (ConfigSingleton<HeroSkinConfigCategory>.Instance.Contain(heroSkinId))
			{
				return GetSmallIcon(ConfigSingleton<HeroSkinConfigCategory>.Instance.Get(heroSkinId).IconId);
			}
			return GetSmallIcon(heroCardInfo.ConfigId);
		}

		public static string GetLongIcon(int iconId)
		{
			return $"uitex_hero_image_long_{iconId}";
		}

		public static string GetLongIcon(Hero hero)
		{
			if (ConfigSingleton<HeroSkinConfigCategory>.Instance.Contain(hero.CurrentSkin))
			{
				return GetLongIcon(ConfigSingleton<HeroSkinConfigCategory>.Instance.Get(hero.CurrentSkin).IconId);
			}
			return GetLongIcon(hero.ConfigId);
		}

		public static string GetHeroNameIcon(int iconId)
		{
			return $"uitex_icon_heroName_{iconId}";
		}

		public static string GetHeroName(int HeroId)
		{
			HeroConfig heroConfig = ConfigSingleton<HeroConfigCategory>.Instance.Get(HeroId);
			if (heroConfig == null)
			{
				return string.Empty;
			}
			if (heroConfig.Type == 1)
			{
				return "主角";
			}
			return heroConfig.HeroName;
		}

		public static string GetHeroNameIcon(Hero hero)
		{
			if (ConfigSingleton<HeroSkinConfigCategory>.Instance.Contain(hero.CurrentSkin))
			{
				return GetHeroNameIcon(ConfigSingleton<HeroSkinConfigCategory>.Instance.Get(hero.CurrentSkin).IconId);
			}
			return GetHeroNameIcon(hero.Config.Id);
		}

		public static int GetHeroShowModelId(this Hero hero)
		{
			if (ConfigSingleton<HeroSkinConfigCategory>.Instance.Contain(hero.CurrentSkin))
			{
				return ConfigSingleton<HeroSkinConfigCategory>.Instance.Get(hero.CurrentSkin).SpineModelId;
			}
			return hero.Config.ModelId;
		}

		public static string GetHeroModelBg(this Hero hero)
		{
			return GetHeroModelBg(hero.GetHeroShowModelId());
		}

		public static string GetHeroModelBg(int modelId, string defaultBg = "ui_hero_bg")
		{
			ModelConfig modelConfig = ConfigSingleton<ModelConfigCategory>.Instance.Get(modelId);
			if ((modelConfig != null) & !string.IsNullOrEmpty(modelConfig.ModelBg))
			{
				return modelConfig.ModelBg;
			}
			return defaultBg;
		}
	}
