		[UIMethod]
		public static void OnShow(this UIHeroMaxAttrPanel self, HeroCommonInfo heroCommonInfo)
		{
			self._TxtTitle.SetText("属性信息");
			HeroConfig heroConfig = ConfigSingleton<HeroConfigCategory>.Instance.Get(heroCommonInfo.ConfigId);
			self._HeroTagName.SetText(TextHelper.FormatQuality(heroConfig.HeroName, heroConfig.HeroQuality, null));
			HeroCardInfo info = new HeroCardInfo
			{
				ConfigId = heroCommonInfo.ConfigId,
				Star = heroCommonInfo.Star,
				Level = heroCommonInfo.Level
			};
			self._UIHeroCardItem.SetData(info);
			self._UIHeroSkillWidget.SetData(heroCommonInfo);
			using StatList statList = StatList.Create();
			Dictionary<ushort, long> stats = heroCommonInfo.Stats;
			foreach (var (num3, num4) in stats)
			{
				long value = num4;
				if (StatHelper.IsBasStat(num3))
				{
					long valueOrDefault = stats.GetValueOrDefault(StatHelper.GetPctType(num3));
					value = StatHelper.CalcFinalValue(num4, valueOrDefault);
				}
				statList.Add(new StatStruct
				{
					Type = num3,
					Value = value
				});
			}
			Dictionary<int, StatViewInfo> statViewInfos = TextHelper.GetStatViewInfos(statList);
			self._UICommonPower.SetPower(heroCommonInfo.Power);
			self._UIHeroAttrWidget.SetData(statViewInfos);
		}

