		public static void RefreshViewByConfigId(this UIHeroMaxAttrPanel self, int configId, int star = 0)
		{
			HeroConfig heroConfig = ConfigSingleton<HeroConfigCategory>.Instance.Get(configId);
			self._HeroTagName.SetText(TextHelper.FormatQuality(heroConfig.HeroName, heroConfig.HeroQuality, null));
			HeroCardInfo info = new HeroCardInfo
			{
				ConfigId = configId,
				Star = star,
				Level = 1
			};
			self._UIHeroCardItem.SetData(info);
			self._UIHeroSkillWidget.SetDataById(configId, star, showLock: false);
			int id = configId * 100 + star;
			using StatList statList = StatList.Create();
			HeroStarConfig heroStarConfig = ConfigSingleton<HeroStarConfigCategory>.Instance.Get(id);
			statList.AddRange(heroStarConfig.BaseStats);
			statList.AddRange(heroStarConfig.PercentStats);
			PowerCalc powerCalc = PowerCalc.Create();
			powerCalc.AddStats(statList);
			powerCalc.AddSkills(heroStarConfig.SkillIds);
			self._UICommonPower.SetPower(powerCalc.Power);
			Dictionary<int, StatViewInfo> statViewInfos = TextHelper.GetStatViewInfos(statList);
			self._UIHeroAttrWidget.SetData(statViewInfos);
		}

		public static void RefreshView(this UIHeroMaxAttrPanel self)
		{
			self._HeroTagName.SetText(TextHelper.FormatQuality(self.Hero.Config.HeroName, self.Hero.Config.HeroQuality, null));
			HeroCardInfo info = new HeroCardInfo
			{
				ConfigId = self.Hero.ConfigId,
				Star = ((!self.IsShowMaxStar()) ? self.Hero.Star : self.Hero.MaxStar),
				Level = self.Hero.GetLevel()
			};
			self._UIHeroCardItem.SetData(info);
			self._UIHeroSkillWidget.SetData(self.Hero, self.IsShowMaxStar(), showLock: false);
			using StatList statList = StatList.Create();
			if (!self.IsShowMaxStar())
			{
				int num = self.Hero.ConfigId * 100 + self.Hero.Star;
				Dictionary<ushort, long> finalStats = self.Hero.GetFinalStats();
				foreach (var (num4, num5) in finalStats)
				{
					long value = num5;
					if (StatHelper.IsBasStat(num4))
					{
						long valueOrDefault = finalStats.GetValueOrDefault(StatHelper.GetPctType(num4));
						value = StatHelper.CalcFinalValue(num5, valueOrDefault);
					}
					statList.Add(new StatStruct
					{
						Type = num4,
						Value = value
					});
				}
				self._UICommonPower.SetPower(self.Hero.GetPower());
			}
			else
			{
				Stat[] stats = self.Hero.Config.Stats;
				statList.AddRange(stats);
				int num = self.Hero.ConfigId * 100 + self.Hero.MaxStar;
				HeroStarConfig heroStarConfig = ConfigSingleton<HeroStarConfigCategory>.Instance.Get(num);
				Stat[] baseStats = heroStarConfig.BaseStats;
				foreach (Stat stat in baseStats)
				{
					Stat stat2 = heroStarConfig.PercentStats.FirstOrDefault((Stat s) => s.Type == StatHelper.GetPctType(stat.Type));
					if (stat2 != null)
					{
						long value2 = StatHelper.CalcFinalValue(stat.Value, stat2.Value);
						statList.Add(new StatStruct
						{
							Type = stat.Type,
							Value = value2
						});
					}
					else
					{
						statList.Add(stat);
					}
				}
				statList.AddRange(heroStarConfig.PercentStats);
				PowerCalc powerCalc = PowerCalc.Create();
				powerCalc.AddStats(statList);
				powerCalc.AddSkills(heroStarConfig.SkillIds);
				self._UICommonPower.SetPower(powerCalc.Power);
			}
			Dictionary<int, StatViewInfo> statViewInfos = TextHelper.GetStatViewInfos(statList);
			self._UIHeroAttrWidget.SetData(statViewInfos);
		}
	}
