		[UIMethod]
		public static void OnAwake(this UIHeroPanel self)
		{
			//IL_0125: Unknown result type (might be due to invalid IL or missing references)
			self._UICommonHeroPanelBottom.SetClickCallback(self.OnTabClick);
			self._BtnLeft.SetActive(active: false);
			self._BtnRight.SetActive(active: false);
			self._BtnLeft.AddClickHandler(delegate
			{
				self.OnClickSwitch(-1);
			});
			self._BtnRight.AddClickHandler(delegate
			{
				self.OnClickSwitch(1);
			});
			self._BtnNextHero.AddClickHandler(delegate
			{
				self.OnClickNextHero();
			});
			self._BtnPriviewRelate.AddClickHandler(self.OnClickPriviewRelate);
			((Component)self._BtnExchange.Transform).GetComponent<SuperToggle>().SetValueChangeCallback((UnityAction<bool>)OnClickExchange);
			((Entity)self._UICommonHeroPanelBottom.CommonTab).AddComponent<RedPointNavigation, RedPointNavigationDirection>(RedPointNavigationDirection.LeftRight, false).SetPosition(new Vector2(0f, 80f));
		}

		[UIMethod]
		public static void OnShow(this UIHeroPanel self, (Hero hero, bool fromList, int funcId) showArgs)
		{
			(self.Hero, self.FromList, _) = showArgs;
			self.InitTabInfos();
			if (showArgs.funcId > 0)
			{
				if (self.Hero.IsActive)
				{
					self.TabInfos = self.ActiveTabInfos;
					self._UICommonHeroPanelBottom.SetTabs(self.TabInfos, showArgs.funcId);
				}
				else
				{
					self.TabInfos = self.NoneTabInfos;
					self._UICommonHeroPanelBottom.SetTabs(self.TabInfos, 0);
				}
			}
			else
			{
				self.TabInfos = (self.Hero.IsActive ? self.ActiveTabInfos : self.NoneTabInfos);
				self._UICommonHeroPanelBottom.SetTabs(self.TabInfos);
			}
			self.RefreshView(changeModel: true);
		}

		[UIMethod]
		public static void OnDestroy(this UIHeroPanel self)
		{
			UIObject.FindUIObjectOfType<UIHeroListPanel>()?.RefreshView(force: true);
		}

		public static void OnClickPriviewRelate(this UIHeroPanel self)
		{
			UIManager.Instance.Show<UIHeroRelatePreviewPopup, Hero>(self.Hero).Coroutine();
		}

		private static void OnClickNextHero(this UIHeroPanel self)
		{
			if (self.NextHeroIndex >= 0)
			{
				self.CurIndex = self.NextHeroIndex;
				self.ToHero();
			}
		}

		private static void InitTabInfos(this UIHeroPanel self)
		{
			UIHeroPanel uIHeroPanel = self;
			if (uIHeroPanel.NoneTabInfos == null)
			{
				uIHeroPanel.NoneTabInfos = new UITabInfo[1] { UITabInfo.CreateWithFunc(2006).SetArgs(GetShowArgs(self)) };
			}
			uIHeroPanel = self;
			if (uIHeroPanel.ActiveTabInfos == null)
			{
				uIHeroPanel.ActiveTabInfos = new UITabInfo[4]
				{
					UITabInfo.CreateWithFunc(2000).SetArgs(GetShowArgs(self)).SetRedPoint(RedPointType.Hero_Skin, self.Hero.ConfigId),
					UITabInfo.CreateWithFunc(2001).SetArgs(GetShowArgs(self)).SetRedPoint(RedPointType.Hero_Star, self.Hero.ConfigId),
					UITabInfo.CreateWithFunc(2003).SetArgs(GetShowArgs(self)).SetRedPoint(RedPointType.Hero_Jewelry, self.Hero.ConfigId),
					UITabInfo.CreateWithFunc(2002).SetArgs(GetShowArgs(self)).SetRedPoint(RedPointType.Hero_Talent, self.Hero.ConfigId)
				};
			}
		}

		private static void OnClickExchange(this UIHeroPanel self, bool isOn)
		{
			if (((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().GetItemNumsByItemId(self.Hero.Config.Universal) == 0L)
			{
				((Component)self._BtnExchange.Transform).GetComponent<SuperToggle>().SetSelectWithoutNotify(false);
				UIObtainWayHelper.ShowPanelAsync(self.Hero.Config.Universal).Coroutine();
				UIGameMsgHelper.FloatLanguage(6, 2003);
				return;
			}
			if (isOn)
			{
				UIGameMsgHelper.FloatLanguage(6, 2005);
			}
			UIObject.FindUIObjectOfType<UIHeroAddStarPanel>()?.SetUseFragment(isOn);
		}

		private static void OnTabClick(this UIHeroPanel self, int index, UIObject showPanel)
		{
			if (self.TabInfos[index].TabIdType == UITabIdType.Func)
			{
				self.CurrentFuncId = self.TabInfos[index].FuncId;
			}
			self.CurShowPanel = showPanel;
			ShowUniverse(self);
			UIObject curShowPanel = self.CurShowPanel;
			if (curShowPanel != null)
			{
				((Entity)curShowPanel).GetComponent<UIHeroSummonPanel>()?.RefreshView(self.Hero);
			}
			UIObject curShowPanel2 = self.CurShowPanel;
			if (curShowPanel2 != null)
			{
				((Entity)curShowPanel2).GetComponent<UIHeroInfoPanel>()?.RefreshView(self.Hero);
			}
			UIObject curShowPanel3 = self.CurShowPanel;
			if (curShowPanel3 != null)
			{
				((Entity)curShowPanel3).GetComponent<UIHeroAddStarPanel>()?.RefreshView(self.Hero);
			}
			UIObject curShowPanel4 = self.CurShowPanel;
			if (curShowPanel4 != null)
			{
				((Entity)curShowPanel4).GetComponent<UIHeroJewelryPanel>()?.RefreshView(self.Hero);
			}
			UIObject curShowPanel5 = self.CurShowPanel;
			if (curShowPanel5 != null)
			{
				((Entity)curShowPanel5).GetComponent<UIHeroTalentPanel>()?.RefreshView(self.Hero);
			}
			self.NextHeroIndex = -1;
			self.FindNextHero();
			self._BtnNextHero.SetActive(self.NextHeroIndex >= 0);
		}

		public static void OnChangeHero(this UIHeroPanel self, int heroId)
		{
			int num = self.HeroCardList.FindIndex((Hero hero) => hero.ConfigId == heroId);
			self.OnClickSwitch(num - self.CurIndex);
		}

		private static void OnClickSwitch(this UIHeroPanel self, int direction)
		{
			self.CurIndex += direction;
			self.ToHero();
		}

		private static void ToHero(this UIHeroPanel self)
		{
			self._BtnLeft.SetActive(self.CurIndex > 0);
			self._BtnRight.SetActive(self.CurIndex < self.HeroCardList.Count - 1);
			self.Hero = self.HeroCardList[self.CurIndex];
			self.TabInfos = (self.Hero.IsActive ? self.ActiveTabInfos : self.NoneTabInfos);
			UITabInfo[] tabInfos = self.TabInfos;
			for (int i = 0; i < tabInfos.Length; i++)
			{
				tabInfos[i].SetArgs(GetShowArgs(self));
			}
			self.RefreshRedPoint();
			self._UIHeroPositionAttr.SetData(self.Hero.ConfigId);
			self._UICommonModelPanel.ShowHighModel(self.Hero.GetHeroShowModelId()).Coroutine();
			self._Bg.SetRawTexture(self.Hero.GetHeroModelBg()).Coroutine();
			self._UICommonHeroPanelBottom.SetTabs(self.TabInfos);
			self._UICommonPower.SetPower(self.Hero.GetPower());
			self._UIHeroNameWidget.SetData(self.Hero);
			self.ResetUniversal();
			self.FindNextHero();
			self.SetRelateInfo();
			self._UIHeroRolesPart.SetData(self.Hero.Config.HeroRoles);
			self._UIHeroRolesPart.UIObject.SetActive(self.CurrentFuncId != 2003);
		}

		public static void RefreshView(this UIHeroPanel self, bool changeModel = false, bool playPower = true)
		{
			if (self.FromList)
			{
				self.HeroCardList = UIObject.FindUIObjectOfType<UIHeroListPanel>().HeroCardList;
				self.CurIndex = self.HeroCardList.FindIndex((Hero h) => ((Entity)h).Id == ((Entity)self.Hero).Id);
				self._BtnLeft.SetActive(self.CurIndex > 0);
				self._BtnRight.SetActive(self.CurIndex < self.HeroCardList.Count - 1);
			}
			if (changeModel)
			{
				self._UICommonModelPanel.ShowHighModel(self.Hero.GetHeroShowModelId()).Coroutine();
				self._Bg.SetRawTexture(self.Hero.GetHeroModelBg()).Coroutine();
			}
			ShowUniverse(self);
			self._UIHeroPositionAttr.SetData(self.Hero.ConfigId);
			self._UICommonPower.SetPower(self.Hero.GetPower(), playPower);
			self._UIHeroNameWidget.SetData(self.Hero);
			self.SetRelateInfo();
			self._UIHeroRolesPart.SetData(self.Hero.Config.HeroRoles);
			self._UIHeroRolesPart.UIObject.SetActive(self.CurrentFuncId != 2003);
			if (self.Hero.IsActive)
			{
				UIObject.FindUIObjectOfType<UIHeroListPanel>()?.RefreshView();
				self._UICommonHeroPanelBottom.SetTabs(self.TabInfos);
			}
		}

		public static void JewelryShow(this UIHeroPanel self, bool isShow)
		{
			if (!((Entity)self).IsDisposed)
			{
				if (isShow)
				{
					self._UIHeroNameWidget.Hide();
					self._UIHeroRolesPart.Hide();
					self._Relate.SetActive(active: false);
				}
				else
				{
					self._UIHeroNameWidget.UIObject.SetActive(active: true);
					self._UIHeroRolesPart.UIObject.SetActive(active: true);
					self._Relate.SetActive(active: true);
				}
			}
		}

		public static void ResetUniversal(this UIHeroPanel self)
		{
			((Component)self._BtnExchange.Transform).GetComponent<SuperToggle>().SetSelectWithoutNotify(false);
			UIObject.FindUIObjectOfType<UIHeroAddStarPanel>()?.SetUseFragment(isUse: false);
		}

		private static void RefreshRedPoint(this UIHeroPanel self)
		{
			self.TabInfos = (self.Hero.IsActive ? self.ActiveTabInfos : self.NoneTabInfos);
			UITabInfo[] tabInfos = self.TabInfos;
			foreach (UITabInfo uITabInfo in tabInfos)
			{
				if (uITabInfo.FuncId == 2001)
				{
					uITabInfo.SetRedPoint(RedPointType.Hero_Star, self.Hero.ConfigId);
				}
				else if (uITabInfo.FuncId == 2003)
				{
					uITabInfo.SetRedPoint(RedPointType.Hero_Jewelry, self.Hero.ConfigId);
				}
				else if (uITabInfo.FuncId == 2002)
				{
					uITabInfo.SetRedPoint(RedPointType.Hero_Talent, self.Hero.ConfigId);
				}
			}
		}

		private static UIHeroShowArgs GetShowArgs(UIHeroPanel self)
		{
			return new UIHeroShowArgs
			{
				Hero = self.Hero
			};
		}

		private static void ShowUniverse(UIHeroPanel self)
		{
			bool flag = self.CurrentFuncId == 2001 && self.Hero.Config.Universal > 0 && self.Hero.IsActive && !self.Hero.IsMaxStar;
			self._BtnExchange.SetActive(flag);
			if (flag)
			{
				ItemConfig itemConfig = ConfigSingleton<ItemConfigCategory>.Instance.Get(self.Hero.Config.Universal);
				self._RawWan.SetRawTexture($"uitex_icon_item_{itemConfig.Icon}", nativeSize: true).Coroutine();
				long itemNumsByItemId = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().GetItemNumsByItemId(self.Hero.Config.Universal);
				self._TxtWanNum.SetText(((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().GetItemNumsByItemId(self.Hero.Config.Universal).ToString());
				if (!self.Hero.CanUpStar((int)itemNumsByItemId))
				{
					self.ResetUniversal();
				}
			}
		}

		private static void FindNextHero(this UIHeroPanel self)
		{
			List<int> list = new List<int>();
			for (int i = 0; i < self.HeroCardList.Count; i++)
			{
				Hero hero = self.HeroCardList[i];
				if (hero.IsActive && self.Hero.ConfigId != hero.ConfigId)
				{
					Enum.TryParse<RedPointType>(ConfigSingleton<FuncConfigCategory>.Instance.Get(self.CurrentFuncId).RedPointType, out var result);
					if (RedPointHelper.GetCount(SceneHelper.DomainScene((Entity)(object)self), result, hero.ConfigId) > 0)
					{
						list.Add(i);
					}
				}
			}
			self.NextHeroIndex = -1;
			if (list.Count == 0)
			{
				return;
			}
			for (int j = 0; j < list.Count; j++)
			{
				if (list[j] > self.CurIndex)
				{
					self.NextHeroIndex = list[j];
					break;
				}
			}
			if (self.NextHeroIndex == -1)
			{
				self.NextHeroIndex = list[0];
			}
			if (self.NextHeroIndex >= 0)
			{
				self._UINextHeroHead.SetData(self.HeroCardList[self.NextHeroIndex].ConfigId, showBG: false);
			}
		}

		private static void SetRelateInfo(this UIHeroPanel self)
		{
			List<RelateInfo> heroRelateInfo = self.Hero.GetHeroRelateInfo();
			self._Relate.SetActive(active: false);
			if (heroRelateInfo != null && heroRelateInfo.Count > 0)
			{
				RelateInfo showRelate = heroRelateInfo.FirstOrDefault((RelateInfo info) => info.RelateId == self.Hero.Config.ShowRelate);
				if (showRelate != null)
				{
					self._UICommonIcon.UIObject.SetActive(active: false);
					self._UICommonIcon.UIObject.CloneAll(showRelate.Config.Heros.Length, delegate(int index, UIObject item)
					{
