		[UIMethod]
		public static void OnAwake(this UIHeroRelatePreviewItem self)
		{
			self._BtnLook.AddClickHandler(self.OnClickLook);
		}

		public static void OnClickLook(this UIHeroRelatePreviewItem self)
		{
			UIManager.Instance.Show<UIHeroRelateInfoPanel, RelateInfo>(self.RelateInfo).Coroutine();
		}

		public static void SetData(this UIHeroRelatePreviewItem self, RelateInfo relateInfo)
		{
			self.RelateInfo = relateInfo;
			self._TxtName.SetText(relateInfo.Config.Name);
			string textureName = (relateInfo.IsActive ? "ui_hero3_frame_11" : "ui_hero3_frame_12");
			self._RawBg.SetRawTexture(textureName).Coroutine();
			SkillLevel skillLevel = new SkillLevel(relateInfo.StarConfig.Skill);
			self._TxtSkillDesc.SetText(skillLevel.Description());
			self._UIHeroStar.SetStar(relateInfo.Star);
			self._UIHeroStar.SetPivot(0f, 0.5f);
			string text = (skillLevel.IsPassiveSkill ? ConfigSingleton<PassiveSkillLevelConfigCategory>.Instance.Get(skillLevel.SkillLevelId).Icon.ToString() : ConfigSingleton<ActiveSkillLevelConfigCategory>.Instance.Get(skillLevel.SkillLevelId).Icon.ToString());
			self._RawSkillIcon.SetRawTexture("uitex_icon_skill_" + text).Coroutine();
			self._TxtSkillLevel.SetText($"Lv.{skillLevel.Level}");
			self._UIHeroCardItem.UIObject.SetActive(active: false);
			self._UIHeroCardItem.UIObject.CloneAll(relateInfo.Config.Heros.Length, delegate(int index, UIObject item)
			{
				int configId = relateInfo.Config.Heros[index];
				Hero hero = ((Entity)(object)self).LocalPlayer().GetHero(configId);
				((Entity)item).GetComponent<UIHeroCardItem>().SetData(new HeroCardInfo
				{
					ConfigId = configId,
					Level = hero.GetLevel(),
					Star = hero.Star
				}, check: false, !hero.IsActive);
			}).Coroutine();
			self._TxtRecommend.SetText(relateInfo.Config.SuggestDup);
		}
	}
