		[UIMethod]
		public static void OnAwake(this UIHeroSkillItem self)
		{
			self._SkillImage.AddClickHandler(self.OnClickSkill);
		}

		public static void OnClickSkill(this UIHeroSkillItem self)
		{
			if (self.CanClick)
			{
				if (self.ClickCallback != null)
				{
					self.ClickCallback();
					return;
				}
				UIHeroSkillArgs args = new UIHeroSkillArgs
				{
					Hero = self.Hero,
					SkillId = self.SkillData.SkillLevel.SkillLevelId,
					UIObject = self.UIObject
				};
				UIManager.Instance.Show<UIHeroSkillTips, UIHeroSkillArgs>(args).Coroutine();
				self.SetTglSelect(isSelect: true);
			}
		}

		public static void SetDataById(this UIHeroSkillItem self, int heroConfigId, HeroSkillData data, int star, bool showLock)
		{
			if (data == null)
			{
				return;
			}
			self.UIObject.SetActive(active: true);
			if (ConfigSingleton<HeroConfigCategory>.Instance.Get(heroConfigId) != null)
			{
				bool isUnlock = star >= data.UnlockStar;
				if (!showLock)
				{
					isUnlock = true;
				}
				SetCommonData(self, data, isUnlock, data.SkillLevel.Level);
				self.SetSkillIcon(data.SkillLevel);
				self.CanClick = true;
			}
		}

		public static void SetData(this UIHeroSkillItem self, HeroCommonInfo heroCommonInfo, HeroSkillData data, bool showLock)
		{
			if (heroCommonInfo != null && data != null)
			{
				self.UIObject.SetActive(active: true);
				bool isUnlock = data.IsUnlocked;
				if (!showLock)
				{
					isUnlock = true;
				}
				SetCommonData(self, data, isUnlock, data.SkillLevel.Level);
				self.SetSkillIcon(data.SkillLevel);
				self.CanClick = false;
			}
		}

		public static void SetData(this UIHeroSkillItem self, Hero hero, HeroSkillData data, bool showLock)
		{
			if (hero != null && data != null)
			{
				self.UIObject.SetActive(active: true);
				self.Hero = hero;
				bool isUnlock = hero.Star >= data.UnlockStar;
				if (!showLock)
				{
					isUnlock = true;
				}
				SetCommonData(self, data, isUnlock, data.SkillLevel.Level);
				self.SetSkillIcon(data.SkillLevel);
				self.CanClick = true;
			}
		}

		public static void SetSkillIcon(this UIHeroSkillItem self, SkillLevel skill)
		{
			self._LeftTopImage.SetActive(active: false);
			self._SkillImage.SetTexture(skill.Icon()).Coroutine();
			SkillIconTag skillIconTag = skill.IconTag();
			if (skillIconTag != SkillIconTag.None)
			{
				string spriteName = ((skillIconTag == SkillIconTag.NormalTag) ? "ui_hero_front_05" : "ui_hero_front_04");
				self._LeftTopImage.SetSprite(spriteName).Coroutine();
				self._LeftTopImage.SetActive(active: true);
			}
			self._SkillLevelText.SetText(string.Format(ConfigSingleton<Lang3Category>.Instance.Get(106).Text, skill.Level));
			self._LevelLock.SetActive(active: false);
		}

		private static void SetCommonData(UIHeroSkillItem self, HeroSkillData data, bool isUnlock, int skillLevel)
		{
			self.SkillData = data;
			self.SkillType = data.SkillLevel.SkillIndex;
			self._Lock.SetActive(!isUnlock);
			self._LevelLock.SetActive(!isUnlock);
			self._SkillLevel.SetActive(isUnlock && skillLevel > 0);
			self._SkillLevelText.SetText(string.Format(ConfigSingleton<Lang3Category>.Instance.Get(106).Text, skillLevel));
			self._LevelLockText.SetText($"{data.UnlockStar}星解锁");
			self._SkillImage.SetGray(!isUnlock);
		}

		public static void SetClickCallback(this UIHeroSkillItem self, Action clickAction)
		{
			self.ClickCallback = clickAction;
			self.CanClick = true;
		}

		public static void SetTglSelect(this UIHeroSkillItem self, bool isSelect)
		{
			self._GoSelect.SetActive(isSelect);
		}
	}
