				var (flag, skillLevelId, _) = CheckSkillChanges(starConfig, lastStarConfig);
				if (flag)
				{
					SkillLevel skillLevel = new SkillLevel(skillLevelId);
					string text = (skillLevel.IsPassiveSkill ? ConfigSingleton<PassiveSkillLevelConfigCategory>.Instance.Get(skillLevel.SkillLevelId).Icon.ToString() : ConfigSingleton<ActiveSkillLevelConfigCategory>.Instance.Get(skillLevel.SkillLevelId).Icon.ToString());
					self._RawSkillIcon.SetRawTexture("uitex_icon_skill_" + text).Coroutine();
					self._TxtSkillName.SetText(skillLevel.Name());
					self._TxtCurLv.SetText($"等级 {skillLevel.Level - 1}");
					self._TxtNextLv.SetText($"等级 {skillLevel.Level}");
					self._TxtSkillDesc.SetText(skillLevel.Description());
					((Transform)self._SkillIcon.Transform).localScale = Vector3.one * 2f;
					Vector3 skillInfoStartPos = ((Transform)self._SkillInfo.Transform).localPosition;
					((Transform)self._SkillInfo.Transform).localPosition = skillInfoStartPos + Vector3.left * 200f;
					((Component)self._SkillInfo.Transform).GetComponent<CanvasGroup>().alpha = 0f;
					TweenSettingsExtensions.InsertCallback(val, 1.5f, (TweenCallback)delegate
					{
						//IL_002b: Unknown result type (might be due to invalid IL or missing references)
						//IL_0058: Unknown result type (might be due to invalid IL or missing references)
						self._SkillGroup.SetActive(active: true);
						TweenSettingsExtensions.SetEase<TweenerCore<Vector3, Vector3, VectorOptions>>(ShortcutExtensions.DOScale((Transform)(object)self._SkillIcon.Transform, Vector3.one, 0.2f), (Ease)27);
						TweenSettingsExtensions.SetEase<TweenerCore<Vector3, Vector3, VectorOptions>>(ShortcutExtensions.DOLocalMove((Transform)(object)self._SkillInfo.Transform, skillInfoStartPos, 0.2f, false), (Ease)6);
						DOTweenModuleUI.DOFade(((Component)self._SkillInfo.Transform).GetComponent<CanvasGroup>(), 1f, 0.2f);
					});
				}
				else
				{
					self._SkillGroup.SetActive(active: false);
				}
				TweenExtensions.Play<Sequence>(val);
			}
			finally
			{
				if (stats != null)
				{
					((IDisposable)stats).Dispose();
				}
			}
		}

		private static (bool changed, int skillId, bool isNew) CheckSkillChanges(HeroStarConfig currentStarConfig, HeroStarConfig lastStarConfig)
		{
			if (currentStarConfig.ShowSkill != 0)
			{
				return (changed: true, skillId: currentStarConfig.ShowSkill, isNew: false);
			}
			int[] skillIds = currentStarConfig.SkillIds;
			int[] array = lastStarConfig?.SkillIds;
			if (skillIds == null)
			{
				return (changed: false, skillId: 0, isNew: false);
			}
			if (array == null)
			{
				int num = skillIds.FirstOrDefault((int s) => s != 0);
				if (num == 0)
				{
					return (changed: false, skillId: 0, isNew: false);
				}
				return (changed: true, skillId: num, isNew: true);
			}
			int[] array2 = skillIds;
			foreach (int num3 in array2)
			{
				if (num3 != 0 && !array.Contains(num3))
				{
					return (changed: true, skillId: num3, isNew: true);
				}
			}
			array2 = skillIds;
			foreach (int num4 in array2)
			{
				if (num4 != 0)
				{
					SkillLevel currentLevel = new SkillLevel(num4);
					int num5 = array.FirstOrDefault((int s) => s != 0 && new SkillLevel(s).SkillId == currentLevel.SkillId);
					if (num5 != 0 && new SkillLevel(num5).Level < currentLevel.Level)
					{
						return (changed: true, skillId: num4, isNew: false);
					}
				}
			}
			return (changed: false, skillId: 0, isNew: false);
		}
	}
