			if (self.CurStar == star && self.showBackground == showBackground)
			{
				return;
			}
			self.showBackground = showBackground;
			self.CurStar = star;
			int num = ((star <= 5) ? 5 : ((star - 1) % 5 + 1));
			if (!showBackground)
			{
				num = ((star < 5) ? star : ((star - 1) % 5 + 1));
			}
			bool flag = !showBackground && num <= 0;
			if (self.InitShowStar)
			{
				self.UIObject.GameObject.SetActive(!flag);
			}
			self.stars.Clear();
			self._Star.CloneAll(num, delegate(int i, UIObject item)
