					item.SetActive(active: true);
					item.Find("_ImgBg").SetActive(active: false);
					item.Find("_ImgStar").SetSprite($"ui_hero_sign_{num2:D2}").Coroutine();
					item.Find("_ImgStar").SetActive(active: true);
				}
			}).Coroutine();
