			self._Job.SetActive(active: true);
			self._Icon.SetActive(active: true);
			self._HeroLevel.SetActive(active: true);
			self._Check.SetActive(active: true);
			self._Mask.SetActive(active: true);
			self._HeroLevel.SetActive(active: true);
			self._PracticeName.SetActive(active: false);
			self._StarBar.SetActive(active: true);
			self.HeroCardInfo = info;
			HeroConfig heroConfig = ConfigSingleton<HeroConfigCategory>.Instance.Get(info.ConfigId);
			self._Job.SetSprite($"ui_herocard_job_{heroConfig.Job}").Coroutine();
			bool num = heroConfig.Type == 1;
			int num2 = ((!num) ? heroConfig.HeroQuality : ConfigSingleton<PracticeConfigCategory>.Instance.Get(info.Star).Quality);
			self._Bg.SetRawTexture($"ui_common_card_bg_small_{num2}").Coroutine();
			self._JobFrame.SetSprite($"ui_herocard_jobframe_{num2}").Coroutine();
			self._Fg.SetRawTexture($"ui_common_card_mask_small_{num2}").Coroutine();
			self._IsCore.SetActive(heroConfig.IsCore);
			if (num)
			{
				self._StarBar.SetActive(active: false);
			}
			else
			{
				self._StarBar.SetActive(active: true);
				int num3 = (info.Star - 1) / 5;
				foreach (UIObject starObject in self.StarObjects)
				{
					starObject.Find("StarFG").SetSprite($"ui_hero_sign_0{num3 + 2}", nativeSize: true).Coroutine();
				}
				if (info.Star <= 5)
				{
					for (int i = 0; i < 5; i++)
					{
						UIObject self2 = self.StarObjects[i];
						self2.SetActive(active: true);
						self2.Find("StarBG").SetActive(active: true);
						self2.Find("StarFG").SetActive(info.Star > i);
					}
				}
				else
				{
					for (int j = 0; j < 5; j++)
					{
						int num4 = j + num3 * 5;
						UIObject self3 = self.StarObjects[j];
						self3.SetActive(info.Star > num4);
						self3.Find("StarBG").SetActive(active: false);
						self3.Find("StarFG").SetActive(active: true);
					}
				}
			}
			self._HeroLevel.SetText(info.Level.ToString());
			self._Icon.SetRawTexture(UIHeroHelper.GetSmallIcon(self.HeroCardInfo)).Coroutine();
			self._Check.SetActive(check && inTeamIndex == 0);
			self._TeamCheck.SetActive(inTeamIndex == currentTeamIndex);
			self._OtherTeam.SetActive(inTeamIndex > 0);
			if (currentTeamIndex == inTeamIndex)
