		public static void SetEmptyData(this UIHeroCardItem self, int quality)
		{
			self._Bg.SetRawTexture($"ui_common_card_bg_small_{quality}").Coroutine();
			self._Fg.SetRawTexture($"ui_common_card_mask_small_{quality}").Coroutine();
			self._JobFrame.SetActive(active: false);
			self._Job.SetActive(active: false);
			self._Icon.SetActive(active: false);
			self._HeroLevel.SetActive(active: false);
			self._Check.SetActive(active: false);
			self._Mask.SetActive(active: false);
			self._HeroLevel.SetActive(active: false);
			self._Rent.SetActive(active: false);
			self._IsCore.SetActive(active: false);
