		private static void ShowHeroInfoPanel(this UIHeroCardItem self)
		{
			if (self.ClickEnable)
			{
				if (self.PreviewHeroInfo != null)
				{
					UIManager.Instance.Show<UIHeroMaxAttrPanel, HeroCommonInfo>(self.PreviewHeroInfo).Coroutine();
					return;
				}
				Hero hero = ((Entity)(object)self).LocalPlayer().GetHero(self.HeroCardInfo.ConfigId);
				UIManager.Instance.Show<UIHeroMaxAttrPanel, Hero>(hero).Coroutine();
			}
		}

		public static void SetLevel(this UIHeroCardItem self)
		{
			int level = self.HeroCardInfo.Level;
			self._HeroLevel.SetText(level + "<size=18>级</size>");
			self._HeroName.SetActive(active: false);
			self._HeroLevel.SetActive(active: true);
		}

		public static void SetName(this UIHeroCardItem self)
		{
			ItemConfig itemConfig = ConfigSingleton<ItemConfigCategory>.Instance.Get(self.HeroCardInfo.ConfigId);
			self._HeroName.SetText(itemConfig.Name);
			self._HeroName.SetActive(active: true);
			self._HeroLevel.SetActive(active: false);
		}
	}
