		private static void RefreshWeaponSkill(UIHeroJewelryInfoPanel self, int star)
		{
			SetTitle(self, self._SuitAttrGroup, "专属技能");
			self._ItemGroup.SetActive(active: false);
			self._SuitSkillGroup.SetActive(active: true);
			JewelryStarConfig jewelryStarConfig = ((star == 0) ? ConfigSingleton<JewelryStarConfigCategory>.Instance.Get(self.JewelryId * 100) : ConfigSingleton<JewelryStarConfigCategory>.Instance.Get(self.JewelryId * 100 + star));
			int num = star + 1;
			int id = self.JewelryId * 100 + num;
			List<JewelryStarConfig> list = new List<JewelryStarConfig> { jewelryStarConfig };
			if (ConfigSingleton<JewelryStarConfigCategory>.Instance.Contain(id))
			{
				list.Add(ConfigSingleton<JewelryStarConfigCategory>.Instance.Get(id));
			}
			if (jewelryStarConfig.SkillId == null || jewelryStarConfig.SkillId.Length == 0)
			{
				self._SuitSkillGroup.SetActive(active: false);
				return;
			}
			SkillLevel skillLevel = new SkillLevel(jewelryStarConfig.SkillId[0]);
			self._UIHeroJewelrySkillItem.SetData(self.Config.Quality, skillLevel);
			self._TxtSkillName.SetText(skillLevel.Name());
			string color = self.Config.Quality switch
			{
				4 => "#71359c", 
				5 => "#c45c23", 
				6 => "#ad2b2b", 
				_ => "#ffffff", 
			};
			self._TxtSkillName.SetOutlineColor(color);
			bool flag = self.Hero.IsJewelryActive(self.JewelryId);
			self._TxtSkillDesc.SetText(skillLevel.Description());
			self._TxtSkillDesc.SetActive(flag);
			self._ImgSkillNameBg.SetSprite("ui_zwss_frame_" + self.Config.Quality).Coroutine();
			self._ImgSkillNameBg.SetActive(active: true);
			var (flag2, jewelryStarConfig2) = self.Hero.GetJewelryNextSkillConfig(self.JewelryId);
			if (!flag2)
			{
				self._TxtSkillLock.SetActive(active: false);
			}
			else if (!flag)
			{
				if (self.JewelryId % 10 != 0)
				{
					self._TxtSkillLock.SetText("[套装激活]:" + skillLevel.Description());
				}
				else
				{
					self._TxtSkillLock.SetText("[激活解锁]:" + skillLevel.Description());
				}
			}
			else
			{
				SkillLevel skillLevel2 = new SkillLevel(jewelryStarConfig2.SkillId[0]);
				self._TxtSkillLock.SetActive(active: true);
				if (self.JewelryId % 10 != 0)
				{
					self._TxtSkillLock.SetText($"[套装{jewelryStarConfig2.Id % 100}星]:{skillLevel2.Description()}");
				}
				else
				{
					self._TxtSkillLock.SetText($"[{jewelryStarConfig2.Id % 100}星解锁]:{skillLevel2.Description()}");
				}
			}
			_ = jewelryStarConfig.Id % 100;
			self._SkillLevel.SetActive((skillLevel.Level > 0) & flag);
			self._SkillLevelText.SetText($"等级:{skillLevel.Level}");
			self._SkillLevel.Transform.SetSizeWithCurrentAnchors((Axis)0, ((Text)self._SkillLevelText.GameObject.GetComponent<SuperText>()).preferredWidth + 15f);
		}

		private static void RefreshSuitInfo(UIHeroJewelryInfoPanel self, List<JewelryGroupConfig> activeSuitConfigs)
		{
			List<JewelryGroupConfig> allSuit = self.Hero.GetAllSuit();
			if (allSuit.Count == 0)
			{
				self._SuitAttrGroup.SetActive(active: false);
				return;
			}
			self._SuitAttrGroup.SetActive(active: true);
			self._ItemGroup.SetActive(active: true);
			bool flag = false;
			bool flag2 = false;
			List<JewelryGroupConfig> list = new List<JewelryGroupConfig>();
			if (activeSuitConfigs.Count > 0)
			{
				list.Add(activeSuitConfigs[^1]);
				int num = allSuit.IndexOf(activeSuitConfigs[^1]) + 1;
				if (num < allSuit.Count)
				{
					list.Add(allSuit[num]);
				}
				else
				{
					flag2 = true;
				}
			}
			else if (self.Hero.GetAllSuit().Count > 0)
			{
				list.Add(self.Hero.GetAllSuit()[0]);
				flag = true;
			}
			JewelryGroupConfig jewelryGroupConfig = list[0];
			SkillLevel skillLevel = new SkillLevel(jewelryGroupConfig.JewelySkill[0]);
			self._UIHeroJewelrySkillItem.SetData(self.Config.Quality, skillLevel);
			self._TxtSkillName.SetText(skillLevel.Name());
			self._TxtSkillDesc.SetText(skillLevel.Description());
			self._ImgSkillNameBg.SetSprite("ui_zwss_frame_" + self.Config.Quality).Coroutine();
			self._ImgSkillNameBg.SetActive(active: true);
			self.Hero.IsJewelryActive(self.JewelryId);
			self._TxtSkillDesc.SetActive(!flag);
			if (flag2)
			{
				self._TxtSkillLock.SetActive(active: false);
			}
			else if (flag)
			{
				if (self.JewelryId % 10 != 0)
				{
					self._TxtSkillLock.SetText("[套装激活]:" + skillLevel.Description());
				}
				else
				{
					self._TxtSkillLock.SetText("[激活解锁]:" + skillLevel.Description());
				}
			}
			else if (list.Count > 1)
			{
				JewelryGroupConfig jewelryGroupConfig2 = list[1];
				SkillLevel skillLevel2 = new SkillLevel(jewelryGroupConfig2.JewelySkill[0]);
				int num2 = jewelryGroupConfig2.JewelyIds.First();
				self._TxtSkillLock.SetActive(active: true);
				if (self.JewelryId % 10 != 0)
				{
					self._TxtSkillLock.SetText($"[套装{num2 % 100}星]:{skillLevel2.Description()}");
				}
				else
				{
					self._TxtSkillLock.SetText($"[{num2 % 100}星解锁]:{skillLevel2.Description()}");
				}
			}
			_ = jewelryGroupConfig.JewelyIds.First() % 100;
			self._SkillLevel.SetActive(skillLevel.Level > 0 && !flag);
			self._SkillLevelText.SetText($"等级:{skillLevel.Level}");
			self._SkillLevel.Transform.SetSizeWithCurrentAnchors((Axis)0, ((Text)self._SkillLevelText.GameObject.GetComponent<SuperText>()).preferredWidth + 15f);
			JewelryGroupConfig suitConfig = ((activeSuitConfigs.Count > 0) ? activeSuitConfigs[^1] : allSuit[0]);
			int activeCount = 0;
			int minStar = 999;
			self._UIHeroJewelryItem2.UIObject.CloneAll(suitConfig.JewelyIds.Length, delegate(int i, UIObject item)
			{
				int num3 = suitConfig.JewelyIds[i] / 100;
				bool flag3 = self.Hero.IsJewelryActive(num3);
				activeCount = (flag3 ? (activeCount + 1) : activeCount);
				int jewelryStar = self.Hero.GetJewelryStar(num3);
				if (jewelryStar < minStar)
				{
					minStar = jewelryStar;
				}
				((Entity)item).GetComponent<UIHeroJewelryItem>().SetData(num3, jewelryStar, flag3, 1);
			}).Coroutine();
			if (activeCount != suitConfig.JewelyIds.Length)
			{
				SetTitle(self, self._SuitAttrGroup, $"神饰套装 <color=#17bf17>{activeCount}/{suitConfig.JewelyIds.Length}</color>");
			}
			else
			{
				SetTitle(self, self._SuitAttrGroup, $"神饰套装·{minStar}星");
			}
		}

		private static void SetTitle(UIHeroJewelryInfoPanel self, UIObject group, string title)
		{
			group.Find("Title/Text").SetText(title);
		}
	}
