			UIManager.Instance.Show<UIHeroManualTotalAttr, UIAttrShowArgs>(new UIAttrShowArgs
			{
				stats = manualStats.ToArray(),
				funcId = 2005
			}).Coroutine();
		}

		public static void RefreshView(this UIHeroManualPanel self)
		{
			HeroModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<HeroModule>();
			self.HeroList = component.GetHeroes(new HeroSearch
			{
				Includes = HeroInclude.Hero,
				SortType = HeroSortType.Manual
			});
			self._UIScrollList.SetData(self.HeroList.Count);
			if (self.HeroId > 0)
			{
				self.Select = self.HeroList.FindIndex((Hero hero2) => hero2.ConfigId == self.HeroId);
				self._UIScrollList.MovePanelToItemIndex(self.Select);
			}
			else if (self.Select < 0)
			{
				for (int num = 0; num < self.HeroList.Count; num++)
				{
					Hero hero = self.HeroList[num];
					if (hero.IsActive && hero.ManualCanLvUp)
					{
						self.Select = num;
						break;
					}
				}
				self._UIScrollList.MovePanelToItemIndex(self.Select);
			}
			int manualTotalLv = component.ManualTotalLv;
			self._TxtLevel.SetText("图鉴等级:" + manualTotalLv);
			int num2 = 0;
			ManualLevelConfig manualLevelConfig = null;
			if (manualTotalLv > 0)
			{
				num2 = component.ManualTotalExp;
				manualLevelConfig = ConfigSingleton<ManualLevelConfigCategory>.Instance.Get(manualTotalLv);
			}
			if (ConfigSingleton<ManualLevelConfigCategory>.Instance.Contain(manualTotalLv + 1))
			{
				int num3 = ConfigSingleton<ManualLevelConfigCategory>.Instance.Get(manualTotalLv + 1).Exp - (manualLevelConfig?.Exp ?? 0);
				num2 = component.ManualTotalExp - (manualLevelConfig?.Exp ?? 0);
				((Slider)((Component)self._Slider.Transform).GetComponent<SuperSlider>()).value = Mathf.Clamp01((float)num2 / (float)num3);
				self._TxtSlider.SetText($"{num2}/{num3}");
			}
			else
			{
				((Slider)((Component)self._Slider.Transform).GetComponent<SuperSlider>()).value = 1f;
				self._TxtSlider.SetText("满级");
			}
			PowerCalc powerCalc = PowerCalc.Create();
			foreach (Hero hero2 in self.HeroList)
			{
				if (hero2.IsActive && hero2.ManualIsActive)
				{
					int id = hero2.ConfigId * 100 + hero2.ManualLv;
					if (ConfigSingleton<ManualHeroConfigCategory>.Instance.Contain(id))
					{
						ManualHeroConfig manualHeroConfig = ConfigSingleton<ManualHeroConfigCategory>.Instance.Get(id);
						powerCalc.AddStats(manualHeroConfig.Stats);
					}
				}
			}
			if (component.ManualRewardMap != null)
			{
				for (int num4 = 0; num4 <= manualTotalLv; num4++)
				{
					if (ConfigSingleton<ManualLevelConfigCategory>.Instance.Contain(num4))
					{
						ManualLevelConfig manualLevelConfig2 = ConfigSingleton<ManualLevelConfigCategory>.Instance.Get(num4);
						if (manualLevelConfig2?.Stats != null && component.ManualRewardMap.ContainsKey(num4))
						{
							powerCalc.AddStats(manualLevelConfig2.Stats);
						}
					}
				}
			}
			self._UICommonPower.SetPower(powerCalc.Power);
			self.RefreshAwardRedPoint();
		}

		public static void RefreshAwardRedPoint(this UIHeroManualPanel self)
		{
			self._BtnBox.SetRedPoint(RedPointType.Hero_Manual_Box).Coroutine();
		}

		private static void OnCellUpdate(this UIHeroManualPanel self, UIScrollListCell cell)
		{
			if (cell != null && cell.Index < self.HeroList.Count)
			{
				((Entity)cell.UIObject).GetComponent<UIHeroCard>()?.SetData(self.HeroList[cell.Index], cell.Index, isManual: true);
			}
		}
	}
