		private static void OnClickChangeBtn(this UIHeroRecommendItem self)
		{
			RoleInfoModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<RoleInfoModule>();
			Log.Info($"roleInfoModule nowPower = {component.Power}");
			self.posHero?.Clear();
			HeroRecFormationConfig heroRecFormationConfig = ConfigSingleton<HeroRecFormationConfigCategory>.Instance.Get(self.HeroRecFormation.Id);
			for (int i = 0; i < heroRecFormationConfig.HeroIds.Length; i++)
			{
				Hero hero = ((Entity)(object)self).LocalPlayer().GetHero(heroRecFormationConfig.HeroIds[i]);
				if (hero != null && hero.IsActive)
				{
					FormationTemplateConfig formationTemplateConfig = ConfigSingleton<FormationTemplateConfigCategory>.Instance.Get(heroRecFormationConfig.Position);
					self.posHero.Add(formationTemplateConfig.PosIds[i], ((Entity)hero).Id);
				}
			}
			if (self.posHero.Count != heroRecFormationConfig.HeroIds.Length)
			{
				UIGameMsgHelper.FloatMsgByError(206605);
				return;
			}
			long num = 0L;
			foreach (var (_, heroId) in self.posHero)
			{
				Hero heroByUid = ((Entity)(object)self).LocalPlayer().GetHeroByUid(heroId);
				if (heroByUid != null && heroByUid.IsActive)
				{
					num += heroByUid.GetPower();
