				RelateStarConfig relateStarConfig = ConfigSingleton<RelateStarConfigCategory>.Instance.Get(self.RelateInfo.RelateId * 100 + num);
				self.StarConfigs.Add(ConfigSingleton<RelateStarConfigCategory>.Instance.Get(self.RelateInfo.RelateId * 100 + num));
				if (self.RelateInfo.IsActive && self.RelateInfo.Star == relateStarConfig.RelateStar)
				{
					num2 = num;
				}
			}
			self._UISkillScrollList.SetData(self.StarConfigs.Count);
			self._UISkillScrollList.MovePanelToItemIndex(num2 - 1);
		}

