		public static void SetData(this UIHeroRelateInfoSkillItem self, RelateInfo info, RelateStarConfig starConfig)
		{
			//IL_023a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0240: Unknown result type (might be due to invalid IL or missing references)
			//IL_0244: Unknown result type (might be due to invalid IL or missing references)
			//IL_024a: Unknown result type (might be due to invalid IL or missing references)
			bool flag = info.IsActive && info.Star == starConfig.RelateStar;
			string arg = (flag ? "#b06e42" : "#ab9e7f");
			self._TxtTitle.SetText($"<color={arg}>羁绊神将达到</color><color=#2c9d3c>{starConfig.NeedStar}星</color>");
			int num = 0;
			int[] heros = info.Config.Heros;
			foreach (int configId in heros)
			{
				Hero hero = ((Entity)(object)self).LocalPlayer().GetHero(configId);
				if (hero.Star >= starConfig.NeedStar && hero.IsActive)
				{
					num++;
				}
			}
			string str = (flag ? "<color=#2c9d3c>已激活</color>" : $"<color=#ab9e7f>({num}/{info.Config.Heros.Length})</color>");
			self._IsActive.SetText(str);
			using StatList statList = StatList.Create();
			statList.AddRange(starConfig.Stats);
			string text = string.Empty;
			for (int j = 0; j < statList.Count; j++)
			{
				text = text + statList[j].GetName() + "+" + statList[j].GetValueText() + " ";
				if (j < statList.Count - 1)
				{
					text += ",";
				}
			}
			self._TxtAttr.SetText(text);
			SkillLevel skillLevel = new SkillLevel(starConfig.Skill);
			self._TxtSkill.SetText(skillLevel.Description());
			self._UIHeroSkill.SetSkillIcon(skillLevel);
			self._UIHeroStar.SetPivot(1f, 0f);
			self._UIHeroStar.SetStar(starConfig.RelateStar);
			self._UIHeroStar.SetSpace((starConfig.RelateStar % 5 == 0) ? (-12) : 0);
			self._ImgBg.SetSprite(flag ? "ui_tj_frame_18_gv" : "ui_tj_frame_06_gv").Coroutine();
			if (flag && ((Entity)(object)self).LocalPlayer().GetLocalInt(info.RelateId.ToString()) != info.Star)
			{
				self.UIObject.PlayEffect("ui_fx_jibanjihuo");
				((Entity)(object)self).LocalPlayer().SetLocalInt(info.RelateId.ToString(), info.Star);
			}
		}
	}
