			self._TxtName.SetText(config.Name);
			self._UIHeroStar.SetStar(info.Star);
			self._UIHeroCardItem.UIObject.CloneAll(config.Heros.Length, delegate(int index, UIObject o)
			{
				bool flag = self.RelateInfo.ActiveHeroes.TryGetValue(config.Heros[index], out var value);
