			}).Coroutine();
			SkillLevel skillLevel = new SkillLevel(info.StarConfig.Skill);
			self._RawSkillIcon.SetRawTexture(skillLevel.Icon()).Coroutine();
			self._TxtSkillLevel.SetText("等级 " + skillLevel.Level);
