		public static void RefreshView(this UIHeroRelatePanel self)
		{
			self.RelateInfos = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<HeroModule>().GetRelateInfos();
			self._UIScrollList.SetData(self.RelateInfos.Count);
			if (self.RelateId > 0)
			{
				int index = self.RelateInfos.FindIndex((RelateInfo x) => x.RelateId == self.RelateId);
				self._UIScrollList.MovePanelToItemIndex(index);
			}
			else
			{
				if (self.HeroId > 0)
				{
					int num = 0;
					num = self.RelateInfos.FindIndex((RelateInfo x) => x.Config.Heros.Contains(self.HeroId));
					self._UIScrollList.MovePanelToItemIndex(num);
				}
				self._UIScrollList.MovePanelToItemIndex(0);
			}
			PowerCalc power = PowerCalc.Create();
			self.RelateInfos.ForEach(delegate(RelateInfo x)
			{
				if (x.IsActive)
				{
					power.AddStats(x.StarConfig.Stats);
					power.AddSkill(x.StarConfig.Skill);
				}
			});
			self._UICommonPower.SetPower(power.Power);
		}

