		{
			UIObject uIObject = cell.UIObject;
			UIHeroRelateItemSystem.SetData(info: self.RelateInfos[cell.Index], self: ((Entity)uIObject).GetComponent<UIHeroRelateItem>());
		}
	}
	[RedPointHandler(RedPointType.Hero_Skin)]
	public class HeroSkinRedPointHandler : ARedPointHandler
	{
		public override int GetCount(Scene scene, params int[] parameters)
		{
			Player player = ((Entity)(object)scene).LocalPlayer();
			if (!player.IsFuncOpen(2008))
			{
				return 0;
			}
			int num = ((parameters != null && parameters.Length > 0) ? parameters[0] : 0);
			int num2 = ((parameters != null && parameters.Length >= 2) ? parameters[1] : 0);
			if (num == 0)
			{
				return 0;
			}
			Hero hero = player.GetHero(num);
			if (hero == null || !hero.IsActive)
			{
				return 0;
			}
			HeroSkinModule component = ((Entity)player).GetComponent<HeroSkinModule>();
			List<HeroSkinConfig> listByHeroId = UIHeroSkinHelper.GetListByHeroId(num, player);
			int result = 0;
			foreach (HeroSkinConfig item in listByHeroId)
			{
				HeroSkinStarEnum heroSkinStarStatues = component.GetHeroSkinStarStatues(item.Id);
				if ((num2 == 0 || num2 == item.Id) && (heroSkinStarStatues == HeroSkinStarEnum.CanActive || heroSkinStarStatues == HeroSkinStarEnum.CanUpStar))
				{
					return 1;
				}
			}
			return result;
		}
	}
