		public static void UpdateList(this UIHeroSkinAttrInfo self, int heroId)
		{
			HeroSkinModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<HeroSkinModule>();
			HashSet<int> heroSkinListByHeroId = component.GetHeroSkinListByHeroId(heroId);
			if (heroSkinListByHeroId == null)
			{
				self._UICommonEmpty.SetActive(active: true);
				self._UIScrollList.UIObject.SetActive(active: false);
				return;
			}
			self.StatStructList.Clear();
			foreach (int item in heroSkinListByHeroId)
			{
				HeroSkin child = ((Entity)component).GetChild<HeroSkin>((long)item);
				if (child != null)
				{
					HeroSkinStarConfig starConfig = child.GetStarConfig();
					if (starConfig != null)
					{
						self.StatStructList.AddRange(starConfig.BaseStats);
					}
				}
			}
			if (self.StatStructList.Count <= 0)
			{
				self._UICommonEmpty.SetActive(active: true);
				self._UIScrollList.SetData(0);
			}
			else
			{
				self._UICommonEmpty.SetActive(active: false);
				self._UIScrollList.UIObject.SetActive(active: true);
				self._UIScrollList.SetData(self.StatStructList.Count);
			}
		}

		private static void OnCellUpdate(this UIHeroSkinAttrInfo self, UIScrollListCell cell)
		{
			int index = cell.Index;
			if (index < self.StatStructList.Count)
			{
				StatStruct stat = self.StatStructList[index];
				((Entity)cell.UIObject).GetComponent<UICommonAttr3>().SetData(stat.Type, stat.GetName(), stat.GetValueText());
			}
		}
	}
