			UIObject.FindUIObjectOfType<UIHeroSkinPanel>()?.UpdateView(self.SkinCardId);
		}

		public static void SetData(this UIHeroSkinCard self, HeroSkinConfig heroSkinConfig, bool Select)
		{
			//IL_01a6: Unknown result type (might be due to invalid IL or missing references)
			//IL_0185: Unknown result type (might be due to invalid IL or missing references)
			self.SkinCardId = heroSkinConfig.Id;
			((Entity)(object)self).LocalPlayer().GetHero(heroSkinConfig.HeroId);
			self._HeroSkinName.SetText(heroSkinConfig.SkinName);
			self._Icon.SetRawTexture(UIHeroHelper.GetSmallIcon(heroSkinConfig.IconId)).Coroutine();
			self._Bg.SetRawTexture($"ui_common_card_bg_small_{heroSkinConfig.SkinQuality}").Coroutine();
			self._Fg.SetRawTexture($"ui_common_card_mask_small_{heroSkinConfig.SkinQuality}").Coroutine();
			HeroSkinModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<HeroSkinModule>();
			bool flag = component.HasHeroSkinByHeroId(heroSkinConfig.HeroId, heroSkinConfig.Id);
			self._HaveState.SetActive(component.GetHeroSkinStatues(heroSkinConfig.Id) == HerSkinEnum.Wearing);
			self._ChoiceBox.SetActive(Select);
			self._Mask.SetActive(!flag);
			HeroSkinStarEnum heroSkinStarStatues = component.GetHeroSkinStarStatues(heroSkinConfig.Id);
			self._CanActive.SetActive(active: true);
			HeroSkin child = ((Entity)component).GetChild<HeroSkin>((long)heroSkinConfig.Id);
			HeroSkinStarConfig heroSkinStarConfig = ((child == null) ? HeroSkinHelper.GetSkinStarConfig(heroSkinConfig.Id, 0) : child.GetStarConfig());
			int num = heroSkinStarConfig?.Star ?? 0;
			self._Star.UIObject.SetActive(num > 0);
			if (num > 0)
			{
				self._Star.SetStar(heroSkinStarConfig.Star, showBackground: true);
				self._HeroSkinName.Transform.anchoredPosition = new Vector2(0f, -39f);
			}
			else
			{
				self._HeroSkinName.Transform.anchoredPosition = new Vector2(0f, -75f);
			}
			switch (heroSkinStarStatues)
			{
			case HeroSkinStarEnum.CanActive:
				self._activeText.SetText("激活");
				break;
			case HeroSkinStarEnum.CanUpStar:
				self._activeText.SetText("升星");
				break;
			default:
				self._CanActive.SetActive(active: false);
				break;
			}
		}
	}
	public static class UIHeroSkinHelper
	{
		public static List<HeroSkinConfig> GetListByHeroId(int HeroId, Player player)
		{
			List<HeroSkinConfig> list = new List<HeroSkinConfig>();
			foreach (HeroSkinConfig item in ConfigSingleton<HeroSkinConfigCategory>.Instance.GetListByHeroId(HeroId))
			{
				if (player.CheckAllConds(item.OpenConds))
				{
					list.Add(item);
				}
			}
			return list;
		}
