		private static void InitData(this UIHeroSkinPanel self, int heroId)
		{
			List<Hero> source = UIObject.FindUIObjectOfType<UIHeroListPanel>()?.HeroCardList ?? new List<Hero>();
			self.HeroCardList.Clear();
			foreach (Hero item in from HeroCard in source
				let heroSkinIdList = UIHeroSkinHelper.GetListByHeroId(HeroCard.ConfigId, ((Entity)(object)self).LocalPlayer())
				where heroSkinIdList.Count > 1
				select HeroCard)
			{
				if (item.IsActive)
				{
					self.HeroCardList.Add(item);
				}
			}
			self.CurrentIndex = self.HeroCardList.FindIndex((Hero heroCard) => heroCard.ConfigId == heroId);
			self.ModelId = 0;
		}

		private static void InitView(this UIHeroSkinPanel self)
		{
			int heroCurSkin = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<HeroSkinModule>().GetHeroCurSkin(self.Hero.ConfigId);
			self.UpdateView(heroCurSkin);
		}

