			self.HeroSkinConfigList = UIHeroSkinHelper.GetListByHeroId(self.Hero.ConfigId, ((Entity)(object)self).LocalPlayer());
			self.SelectHeroSkinId = heroSkinId;
			int num = Math.Min(self.HeroSkinConfigList.Count, 3);
			float num2 = (float)(148 * num) + self._UIScrollList.SpaceX * (float)(num - 1);
			Vector2 sizeDelta = ((Component)self._UIScrollList.ScrollRect).GetComponent<RectTransform>().sizeDelta;
			((Component)self._UIScrollList.ScrollRect).GetComponent<RectTransform>().sizeDelta = new Vector2(num2, sizeDelta.y);
			self._UIScrollList.SetData(self.HeroSkinConfigList.Count);
			self.UpdateData();
