		public static void UpdateStarGroup(this UIHeroSkinPanel self)
		{
			HeroSkinModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<HeroSkinModule>();
			HeroSkin child = ((Entity)component).GetChild<HeroSkin>((long)self.SelectHeroSkinId);
			HeroSkinStarConfig heroSkinStarConfig = ((child == null) ? HeroSkinHelper.GetSkinStarConfig(self.SelectHeroSkinId, 0) : child.GetStarConfig());
			if (self.StarStatues == HeroSkinStarEnum.CanUpStar)
			{
				self._StarGroup.SetActive(active: true);
				if (component.IsMaxStar(self.SelectHeroSkinId))
				{
					self._GoCurStar.SetActive(active: false);
					self._Arrow.SetActive(active: false);
					self._NextStar.SetStar(child.Star);
				}
				else
				{
					self._GoCurStar.SetActive(active: true);
					self._Arrow.SetActive(active: true);
					self._CurStar.SetStar(heroSkinStarConfig.Star, showBackground: true);
					self._NextStar.SetStar(heroSkinStarConfig.Star + 1, showBackground: true);
				}
			}
			else
			{
				self._StarGroup.SetActive(active: false);
			}
		}

