					Stat stat = heroSkinStarConfig.BaseStats[i];
					StatStruct stat2 = self.StatStructList[i];
					self.CommonAttrList[i].SetData(stat2.Type, stat2.GetName(), stat2.GetValueText());
					self.CommonAttrList[i].UpdateValue(stat.Type, stat.Value);
				}
				else
				{
					self.CommonAttrList[i].UIObject.SetActive(active: false);
				}
			}
			if (self.StarStatues == HeroSkinStarEnum.CanUpStar && heroSkinStarConfig2 != null)
			{
				self._ActiveText.SetText("升星预览");
				((HorizontalOrVerticalLayoutGroup)self._Line1.GameObject.GetComponent<HorizontalLayoutGroup>()).spacing = 10f;
				((HorizontalOrVerticalLayoutGroup)self._Line2.GameObject.GetComponent<HorizontalLayoutGroup>()).spacing = 10f;
				self._Bg.Transform.sizeDelta = new Vector2(self._Bg.Transform.sizeDelta.x, self.InitBgHeight);
				self.StatStructList.Clear();
				self.StatStructList.AddRange(heroSkinStarConfig2.BaseStats);
				for (int j = 0; j < self.CommonAttrList.Count; j++)
				{
					if (j < heroSkinStarConfig2.BaseStats.Length)
					{
						self.NextStarValueTextList[j].SetActive(active: true);
						self.CommonAttrList[j].UIObject.SetActive(active: true);
						Stat stat3 = heroSkinStarConfig.BaseStats[j];
						StatStruct stat4 = self.StatStructList[j];
						self.CommonAttrList[j].SetData(stat4.Type, stat4.GetName(), stat4.GetValueText());
						self.CommonAttrList[j].UpdateValue(stat3.Type, stat3.Value);
						Stat stat5 = heroSkinStarConfig2.BaseStats[j];
						string text = TextHelper.FormatStatValue(stat5.Type, stat5.Value - stat3.Value);
						self.NextStarValueTextList[j].SetText("+" + text);
					}
					else
					{
						self.CommonAttrList[j].UIObject.SetActive(active: false);
						self.NextStarValueTextList[j].SetActive(active: false);
					}
				}
			}
			else
			{
				((HorizontalOrVerticalLayoutGroup)self._Line1.GameObject.GetComponent<HorizontalLayoutGroup>()).spacing = 100f;
				((HorizontalOrVerticalLayoutGroup)self._Line2.GameObject.GetComponent<HorizontalLayoutGroup>()).spacing = 100f;
				self._Bg.Transform.sizeDelta = new Vector2(self._Bg.Transform.sizeDelta.x, self.InitBgHeight - 45f);
				foreach (UIObject nextStarValueText in self.NextStarValueTextList)
				{
					nextStarValueText.SetActive(active: false);
				}
				Color color = default(Color);
				for (int k = 0; k < self.CommonAttrList.Count; k++)
				{
					ColorUtility.TryParseHtmlString((self.StarStatues == HeroSkinStarEnum.CanActive) ? "#0DB64D" : "#54505E", ref color);
					self.CommonAttrList[k]._Value.SetColor(color);
				}
			}
			LayoutRebuilder.ForceRebuildLayoutImmediate(((Component)self._Line1.Transform).GetComponent<RectTransform>());
			LayoutRebuilder.ForceRebuildLayoutImmediate(((Component)self._Line2.Transform).GetComponent<RectTransform>());
		}

