		public static async void OnClickConfirmButton(this UIHeroSkinPanel self)
		{
			HeroSkinModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<HeroSkinModule>();
			switch (component.GetHeroSkinStarStatues(self.SelectHeroSkinId))
			{
			case HeroSkinStarEnum.None:
			{
				HeroSkinStarConfig skinStarConfig = HeroSkinHelper.GetSkinStarConfig(self.SelectHeroSkinId, 0);
				if (skinStarConfig != null)
				{
					UIObtainWayHelper.ShowPanelAsync(skinStarConfig.CostNum[0].Id).Coroutine();
				}
				return;
			}
			case HeroSkinStarEnum.CanActive:
			case HeroSkinStarEnum.CanUpStar:
			{
				L2C_ResponseHeroSkinUpStar l2C_ResponseHeroSkinUpStar = (L2C_ResponseHeroSkinUpStar)(await ((Entity)(object)self).LocalPlayer().Call(new C2L_RequestHeroSkinUpStar
				{
					HeroSkinId = self.SelectHeroSkinId
				}));
				if (l2C_ResponseHeroSkinUpStar.Error != 0)
				{
					UIGameMsgHelper.FloatMsgByError(l2C_ResponseHeroSkinUpStar.Error);
				}
				return;
			}
			}
			if (component.GetHeroSkinStatues(self.SelectHeroSkinId) == HerSkinEnum.Active)
			{
				L2C_ResponseHeroSkinWearing l2C_ResponseHeroSkinWearing = (L2C_ResponseHeroSkinWearing)(await ((Entity)(object)self).LocalPlayer().Call(new C2L_RequestHeroSkinWearing
				{
