		public static bool CanActive(this UIHeroTalentNodeItem self, Hero hero, TalentNodeInfo talentData)
		{
			if (hero.TalentPoint <= 0)
			{
				return false;
			}
			if (hero.TalentIsActive(talentData.TalentData.NodeId))
			{
				return false;
			}
			int num = talentData.TalentData.NodeId / 100;
			if (hero.HasActiveTalentInLayer(num))
			{
				return false;
			}
			if (num != 1 && !hero.TalentParentIsActive(talentData.TalentData.Id))
			{
				return false;
			}
			return true;
		}
	}
