			self._ImgBg.SetSprite(spriteName, nativeSize: true).Coroutine();
			self._ImgIcon.SetRawTexture(info.Icon, nativeSize: true).Coroutine();
			if (info.Stat == null || info.Stat.Length == 0)
			{
				return;
			}
			self._NodeType.SetActive(info.Stat[0].Scope > 10);
			if (info.Stat[0].Scope > 0)
			{
				if (info.Stat[0].Scope == 10)
				{
					self._NodeType.SetSprite("ui_heroTalent_frame_09").Coroutine();
					self._NodeType.SetActive(active: true);
					self._TxtType.SetText("全");
				}
				else
				{
					self._NodeType.SetSprite("ui_heroTalent_frame_08").Coroutine();
					self._NodeType.SetActive(active: true);
					self._TxtType.SetText("职");
				}
			}
		}
	}
