		private static List<ImmortalOfficialDupBattleRecordInfo> SortRecordsOptimized(this UIImmortalOfficialBattleRecordPanel self, List<ImmortalOfficialDupBattleRecordInfo> records)
		{
			if (records == null || records.Count <= 1)
			{
				return records?.OrderByDescending((ImmortalOfficialDupBattleRecordInfo r) => r.Damage).ToList() ?? new List<ImmortalOfficialDupBattleRecordInfo>();
			}
			List<ImmortalOfficialDupBattleRecordInfo> list = records.OrderByDescending((ImmortalOfficialDupBattleRecordInfo r) => r.Damage).Take(2).ToList();
			List<ImmortalOfficialDupBattleRecordInfo> second = (from r in records.Except(list)
				orderby r.RecordTime descending
				select r).ToList();
			return list.Concat(second).ToList();
		}

		private static async void InitView(this UIImmortalOfficialBattleRecordPanel self)
		{
			L2C_ResponseImmortalOfficialDupBattleRecordInfo l2C_ResponseImmortalOfficialDupBattleRecordInfo = (L2C_ResponseImmortalOfficialDupBattleRecordInfo)(await ((Entity)(object)self).LocalPlayer().Call(new C2L_RequestImmortalOfficialDupBattleRecordInfo
			{
				ActivityId = self.ActivityId
			}));
			if (l2C_ResponseImmortalOfficialDupBattleRecordInfo.Error == 0)
			{
				self.RecordInfos = l2C_ResponseImmortalOfficialDupBattleRecordInfo.RecordInfoList ?? new List<ImmortalOfficialDupBattleRecordInfo>();
				self.NewRecordTime = 0L;
				foreach (ImmortalOfficialDupBattleRecordInfo recordInfo in self.RecordInfos)
				{
					if (self.NewRecordTime == 0L)
					{
						self.NewRecordTime = recordInfo.RecordTime;
					}
					self.NewRecordTime = Math.Max(self.NewRecordTime, recordInfo.RecordTime);
				}
				self.RecordInfos = self.SortRecordsOptimized(self.RecordInfos);
				self._UIScrollList.SetData(Math.Min(self.RecordInfos.Count, 20));
				self._EmptyImage.SetActive(self.RecordInfos.Count == 0);
			}
			else
			{
				self._UIScrollList.SetData(0);
				self._EmptyImage.SetActive(active: true);
			}
		}

		private static void onCellUpdate(this UIImmortalOfficialBattleRecordPanel self, UIScrollListCell cell)
		{
			UIImmortalOfficialBattleRecordItem component = ((Entity)cell.UIObject).GetComponent<UIImmortalOfficialBattleRecordItem>();
			int index = cell.Index;
			if (index < self.RecordInfos.Count)
