				component.SetData(immortalOfficialDupBattleRecordInfo, self.NewRecordTime == immortalOfficialDupBattleRecordInfo.RecordTime, activityModule.Damage.Contains(immortalOfficialDupBattleRecordInfo.Damage));
			}
		}
