				bool flag = index != 1;
				self._RankNode.SetActive(index == 1);
				self._RewardNode.SetActive(index != 1);
				if (num && !self.InitRankList)
				{
					self.InitRankList = true;
					self._RankList.SetData(self.RankList.Count);
				}
				if (flag && !self.InitRewardList)
				{
					self.InitRewardList = true;
					List<ImmortalOfficialConfig> list = ConfigSingleton<ImmortalOfficialConfigCategory>.Instance.GetList();
