		[UIMethod]
		private static void OnShow(this UIImmortalOfficialDupSuccessContent self, (int activityId, long damage, bool IsNew) args)
		{
			long item = args.damage;
			ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), args.activityId);
			if (activityData.ActivityType == ActivityType.CrossWorldBoss)
			{
				CrossWorldBossModule activityModule = ActivityHelper.GetActivityModule<CrossWorldBossModule>(((Entity)(object)self).LocalPlayer(), args.activityId);
				((Entity)(object)activityModule).DirectPublish<bool>("EventChallengeFinish");
				self._newRecord.SetActive(activityModule?.IsNewRecord(item) ?? false);
			}
			else if (activityData.ActivityType == ActivityType.WorldBoss)
			{
				WorldBossModule activityModule2 = ActivityHelper.GetActivityModule<WorldBossModule>(((Entity)(object)self).LocalPlayer(), args.activityId);
				((Entity)(object)activityModule2).DirectPublish<bool>("EventChallengeFinish");
				self._newRecord.SetActive(activityModule2?.IsNewRecord(item) ?? false);
			}
			else
			{
				self._newRecord.SetActive(args.IsNew);
