		private static void UpdateScore(this UIImmortalOfficialPanel self)
		{
			ConfigSingleton<ImmortalOfficialConfigCategory>.Instance.GetList();
			ImmortalOfficialModule activityModule = ActivityHelper.GetActivityModule<ImmortalOfficialModule>(((Entity)(object)self).LocalPlayer(), self.ActivityId);
			int currentLevel = activityModule.GetCurrentLevel();
			int beforeStageLevel = activityModule.BeforeStageLevel;
			int num = currentLevel;
			if (beforeStageLevel != 0 && beforeStageLevel < currentLevel)
			{
				num = beforeStageLevel;
			}
			float value = ((float)(num - 1) * 1f * 192f + 157f) / (float)self.ScoreProgressWidth;
			((Slider)self._ScoreProgress.GameObject.GetComponent<SuperSlider>()).value = value;
			foreach (KeyValuePair<int, UIObject> item in self.ScoreUIObjectDict)
			{
				((Entity)item.Value).GetComponent<UIImmortalOfficialScoreItem>()._Effect.SetActive(item.Key == num - 1);
			}
		}

