		private static async void OnClickChallengeButton(this UIImmortalOfficialPanel self)
		{
			switch (ActivityHelper.GetActivityModule<ImmortalOfficialModule>(((Entity)(object)self).LocalPlayer(), self.ActivityId).GetCurrRoundState())
			{
			case 3:
				UIGameMsgHelper.FloatMsg("活动结算中");
				break;
			case 1:
				UIGameMsgHelper.FloatMsg(Language.Get(2, 652));
				break;
			case 2:
			{
				int num = await ((Entity)(object)self).LocalPlayer().DupFight(DupType.ImmortalOfficial, new DupFightArgs
				{
					Level = self.ActivityId
				});
				if (num != 0)
				{
					UIGameMsgHelper.FloatMsgByError(num);
				}
				break;
			}
			}
		}

		public static void OnCellUpdate(this UIImmortalOfficialPanel self, UIScrollListCell cell)
		{
			int index = cell.Index;
			if (index == 0)
			{
				int count = Math.Min(3, self.RankList.Count);
				((Entity)cell.UIObject).GetComponent<UIImmortalOfficialStageTopRankItem>().SetData(self.RankList.GetRange(0, count), self.ActivityId);
				return;
			}
			int num = 3 + 5 * (index - 1);
			List<RankInfo> list = new List<RankInfo>();
			for (int i = 0; i < 5; i++)
			{
				int num2 = num + i;
				if (num2 < self.RankList.Count)
				{
					list.Add(self.RankList[num2]);
				}
			}
			UIImmortalOfficialStageRankItem component = ((Entity)cell.UIObject).GetComponent<UIImmortalOfficialStageRankItem>();
			int num3 = 3 + 5 * index;
			ImmortalOfficialConfig curStageConfig = ActivityHelper.GetActivityModule<ImmortalOfficialModule>(((Entity)(object)self).LocalPlayer(), self.ActivityId).GetCurStageConfig();
			int val = ((num3 <= self.RankList.Count) ? 5 : Math.Max(0, self.RankList.Count - num));
			int val2 = ((num3 <= curStageConfig.Limitation) ? 5 : Math.Max(0, curStageConfig.Limitation - num));
			val = Math.Max(val, val2);
			component.SetData(list, val, self.ActivityId);
		}

