				self._RewardTipsMask.SetActive(active: true);
				Vector3 screenPosition = UIManager.Instance.UICamera.WorldToScreenPoint(((Transform)self._ShowPoint.Transform).position);
				self._UICommonRewardTips.SetData(activityModule.GetCurStageConfig().DailyReward, 0, screenPosition);
