			L2C_ResponseImmortalOfficialDupDailyRewardBox l2C_ResponseImmortalOfficialDupDailyRewardBox = (L2C_ResponseImmortalOfficialDupDailyRewardBox)(await ((Entity)(object)self).LocalPlayer().Call(new C2L_RequestImmortalOfficialDupDailyRewardBox
			{
				ActivityId = self.ActivityId
