		public static void SetData(this UIImmortalOfficialRankItem self, RankInfo rankInfo, int activityId)
		{
			//IL_00e1: Unknown result type (might be due to invalid IL or missing references)
			self._UICommonHead.SetData(new PlayerCommonInfo
			{
				Id = rankInfo.Id,
				DressInfo = rankInfo.DressInfo
			});
			int rankNo = rankInfo.RankNo;
			bool flag = rankNo > 0 && rankNo <= 3;
			self._RankImage.SetActive(flag);
			self._RankText.SetActive(!flag);
			ImmortalOfficialModule activityModule = ActivityHelper.GetActivityModule<ImmortalOfficialModule>(((Entity)(object)self).LocalPlayer(), activityId);
			List<long> crossStagePlayerIdList = activityModule.GetCrossStagePlayerIdList();
			if (flag)
			{
				self._RankImage.SetSprite($"ui_jjc2_sign_0{rankInfo.RankNo}", nativeSize: true).Coroutine();
			}
			else if (crossStagePlayerIdList.Contains(rankInfo.Id))
			{
				self._RankText.SetText("-");
			}
			else
			{
				self._RankText.SetText($"{rankInfo.RankNo}");
			}
			UIHelper.SetText(str: TextHelper.FormatZone(new UIDStruct(rankInfo.Id).Zone) + "\n" + rankInfo.Name, self: self._Name);
			if (crossStagePlayerIdList.Contains(rankInfo.Id))
			{
				self._DamageText.SetText("已通关");
			}
			else
			{
				self._DamageText.SetText(TextHelper.FormatDamage(rankInfo.Value));
			}
			int playerState = activityModule.GetPlayerState(rankInfo.Id);
			if (playerState <= 0)
			{
				self._StageImage.SetActive(active: false);
				return;
			}
			self._StageImage.SetActive(active: true);
			self._StageImage.SetSprite($"ui_xgwd_front_0{playerState}", nativeSize: true).Coroutine();
		}
	}
