		public static void SetData(this UIJadeBankItem self, int index, JadeBankConfig config, int actId, Action _callback = null)
		{
			self.ActId = actId;
			self._callback = _callback;
			self.config = config;
			self._BgImg.SetRawTexture(config.BgImage).Coroutine();
			self._ShopImg.SetSprite(config.IconName).Coroutine();
			self._DiscountImg.SetActive(config.ReturnPecenty > 0);
			self._DiscountText.SetText($"{config.ReturnPecenty + 100}%");
			self._JadeCostNumText.SetText($"投入：{config.StorageMax.Nums}");
			self._JadeCostIcon.SetRawTexture($"uitex_icon_item_{config.StorageMax.Id}").Coroutine();
			self._TimeText.SetText($"{self.config.StorageTime * 1000 / 86400000}");
			int num = config.StorageMax.Nums + config.StorageMax.Nums * config.ReturnPecenty / 100;
			self._JadeGetNumText.SetText($"{num}");
			self._JadeGetIcon.SetRawTexture($"uitex_icon_item_{config.StorageMax.Id}").Coroutine();
			self._DesText.SetText(Language.Get(3, 218));
			if (config.CardType > 1)
			{
				self._VipImage.SetRawTexture(config.OpenTipBg).Coroutine();
				self._VipDesText.SetText(config.OpenCondition);
			}
			if (self.config.CardType == 1)
			{
				self._VipTip.SetActive(active: false);
			}
			if (self.config.CardType == 2)
			{
				bool flag = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<InvestModule>().IsBuyCard(self.config.CardId);
				self._VipTip.SetActive(!flag);
				self._StorageText.SetText((!flag) ? Language.Get(3, 180) : Language.Get(3, 182));
			}
			else if (self.config.CardType == 3)
			{
				bool flag2 = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<PrivilegeModule>().GetValue(PrivilegeType.RaffleExchange) <= 0;
				self._VipTip.SetActive(flag2);
				self._StorageText.SetText(flag2 ? Language.Get(3, 181) : Language.Get(3, 182));
			}
			self.OnRefreshConfigData();
		}

		public static void OnRefreshConfigData(this UIJadeBankItem self)
		{
			JadebankModule component = ((Entity)ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId)).GetComponent<JadebankModule>();
			self.StorageTime = component.GetStorageIime(self.config.Id);
			Log.Info($"OnRefreshConfigData =StorageTime= {self.StorageTime}   id = {self.config.Id}");
			if (self.StorageTime > 0)
			{
				self._StorageBtn.SetActive(active: false);
				self._RemindTime.SetActive(active: true);
				self._VipTip.SetActive(active: false);
				long num = self.StorageTime + self.config.StorageTime * 1000;
				if (TimeHelper.Now() <= num && self.CountDownTimer <= 0)
				{
					self.CountDownTimer = self.NewTimer(1000L, self.CountDown, repeat: true);
					self.CountDown();
				}
				if (TimeHelper.Now() > num || component.GetInterestCount(self.config.Id) > 0)
				{
					self.RemoveTimer(ref self.CountDownTimer);
					self.TimeToEndTime();
				}
				else
				{
					self._StorageIngBtn.SetActive(active: true);
					self._GetBtn.SetActive(active: false);
				}
			}
			else
			{
				self._StorageIngBtn.SetActive(active: false);
				self._GetBtn.SetActive(active: false);
				self._RemindTime.SetActive(active: false);
				self._StorageBtn.SetActive(active: true);
				self._StorageBtn.SetRedPoint(RedPointType.Activity, self.ActId, self.config.Id, 2).Coroutine();
			}
		}

		private static void TimeToEndTime(this UIJadeBankItem self)
		{
			self._GetBtn.SetActive(active: true);
			self._StorageIngBtn.SetActive(active: false);
			self._GetBtn.SetRedPoint(RedPointType.Activity, self.ActId, self.config.Id, 1).Coroutine();
			self._CountTimeText.SetText(Language.Get(3, 144));
		}

		private static void CountDown(this UIJadeBankItem self)
		{
			long num = self.StorageTime + self.config.StorageTime * 1000;
			long num2 = 0L;
			num2 = ((num >= TimeHelper.EndTimeOfDay(TimeHelper.Now(), 18000000L)) ? (TimeHelper.EndTimeOfDay(TimeHelper.Now(), 18000000L) - TimeHelper.Now()) : (num - TimeHelper.Now()));
			string str = TimeSpan.FromSeconds((double)(num2 / 1000)).ToString("hh\\:mm\\:ss");
			self._CountTimeText.SetText(str);
		}

