		[UIMethod]
		public static void OnDestroy(this UIJadeBankStoragePanel self)
		{
			self.Options.CancelAction = null;
			self.Options.OkAction = null;
			self.Options = default(ConfirmSliderPanelOptions);
		}

		[UIMethod]
		public static void OnShow(this UIJadeBankStoragePanel self, TruntableDefine define)
		{
			self.ActId = define.activityId;
			self.Config = ConfigSingleton<JadeBankConfigCategory>.Instance.Get(define.Index);
			self._CommonBg.SetTitle(self.Config.StorageName);
			int num = (int)((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().GetItemNumsByItemId(self.Config.StorageMax.Id);
			self.Options = default(ConfirmSliderPanelOptions);
			self.Options.MinValue = self.Config.StorageMin / 100;
			self.Options.MaxValue = self.Config.StorageMax.Nums / 100;
			if (num >= self.Config.StorageMax.Nums)
			{
				self.Options.StartValue = self.Options.MaxValue;
			}
			else if (num <= self.Config.StorageMin)
			{
				self.Options.StartValue = self.Options.MinValue;
			}
			else
			{
				self.Options.StartValue = num / 100;
			}
			((Slider)self.SuperSlider).minValue = self.Options.MinValue;
			((Slider)self.SuperSlider).maxValue = self.Options.MaxValue;
			((Slider)self.SuperSlider).value = self.Options.StartValue;
			((InputField)self.SuperInputField).SetTextWithoutNotify((self.Options.StartValue * 100).ToString());
			self._JadeIcon.SetRawTexture($"uitex_icon_item_{self.Config.StorageMax.Id}").Coroutine();
			self._AllJadeIcon.SetRawTexture($"uitex_icon_item_{self.Config.StorageMax.Id}").Coroutine();
			self._DayJadeIcon.SetRawTexture($"uitex_icon_item_{self.Config.StorageMax.Id}").Coroutine();
			self.RefreshJadeNum((int)((Slider)self.SuperSlider).value * 100);
			UIGuideHelper.TryGuide(SceneHelper.DomainScene((Entity)(object)self), "UIJadeBankStoragePanel");
		}

		private static void RefreshJadeNum(this UIJadeBankStoragePanel self, int JadeNum)
		{
			if (self.Config.StorageTime * 1000 / 86400000 == 0L)
			{
				Log.Info("配置StorageTime 不足一天");
				return;
			}
			float num = (float)JadeNum * (float)self.Config.ReturnPecenty / 100f + (float)JadeNum;
			float num2 = (float)self.Config.StorageTime * 1000f / 86400000f;
			self._DayText.SetText($"{Mathf.Round(num / num2)}");
			self._AllJadeText.SetText($"{num}");
		}

