		private static void OnSliderValueChanged(this UIJadeBankStoragePanel self, float value)
		{
			int num = (int)value * 100;
			if (value <= 0f)
			{
				((Slider)self.SuperSlider).SetValueWithoutNotify(1f);
				return;
			}
			self.CurrentValue = (int)value;
			self.Options.SliderAction?.Invoke(self, num);
			((InputField)self.SuperInputField).SetTextWithoutNotify(num.ToString());
			self.UpdateUI();
			self.RefreshJadeNum(num);
		}

		private static void OnClickChange(this UIJadeBankStoragePanel self, int value)
		{
			self.CurrentValue += value;
			if (self.CurrentValue + value < self.Options.MinValue)
			{
				self.CurrentValue = self.Options.MinValue;
			}
			else if (self.CurrentValue + value > self.Options.MaxValue)
			{
				self.CurrentValue = self.Options.MaxValue;
			}
			((Slider)self.SuperSlider).value = self.CurrentValue;
		}

		private static void OnInputNumChanged(this UIJadeBankStoragePanel self, string value)
		{
		}

		public static void SetOKText(this UIJadeBankStoragePanel self, string text)
		{
			self._OkText.SetText(text);
		}

		public static void SetCancelText(this UIJadeBankStoragePanel self, string text)
		{
			self._CancelText.SetText(text);
		}

		public static void SetMessage(this UIJadeBankStoragePanel self, string text)
		{
			self._MessageText.SetText(text);
		}

		private static void UpdateUI(this UIJadeBankStoragePanel self)
		{
			self._AddButton.SetSprite((self.CurrentValue >= self.Options.MaxValue) ? "ui_bag_btn_06" : "ui_bag_btn_07", nativeSize: true).Coroutine();
			self._SubButton.SetSprite((self.CurrentValue <= self.Options.MinValue || (self.Options.MinValue == 0 && self.CurrentValue == 1)) ? "ui_bag_btn_06" : "ui_bag_btn_07", nativeSize: true).Coroutine();
			bool isGray = self.CurrentValue < self.Options.MinValue || !((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().CheckItemNumsIsEnough(new ItemStruct
			{
				ConfigId = self.Config.StorageMax.Id,
				Nums = self.CurrentValue * 100
			}) || self.CurrentValue > self.Options.MaxValue;
			self._StorageButton.SetGray(isGray);
		}
	}
