			self._RewardList.SetData(self.ActivityData.BaseInfo.Items.ToArray());
			int modelId = ConfigSingleton<FashionConfigCategory>.Instance.Get(10018).ModelId;
			int modelId2 = ConfigSingleton<FashionConfigCategory>.Instance.Get(60018).ModelId;
