		}

		private static void UpdateView(this UIKingWarActivityPanel2 self)
		{
			(int state, long time) round = ((Entity)self.ActivityData).GetComponent<KingWarActivityModule>().GetRound();
			int item = round.state;
			long item2 = round.time;
			self.State = item;
			self.TargetTime = item2;
			self._DescTime2.SetText("");
			if (((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<KingWarModule>().Stage == 2)
			{
				self.StopTime();
				self._DescTime2.SetText("活动已结束");
				self._DescTime.SetText("");
				self._TimeText.SetText("");
				return;
			}
			switch (item)
			{
			case 1:
				self._DescTime.SetText("敬请期待:");
				break;
			case 2:
				self._DescTime.SetText("活动进行中");
				break;
			case 3:
				self._DescTime2.SetText("活动已结束");
				self._DescTime.SetText("");
				self._TimeText.SetText("");
				return;
			}
			self.StartTime();
			switch (TimeHelper.DaysBetween(TimeHelper.Now(), self.ActivityData.StartTime, 0L))
			{
			case 1:
				self._DescText.SetText("今天 " + Language.Get(5, 1709));
				break;
			case 2:
				self._DescText.SetText("明天 " + Language.Get(5, 1709));
				break;
			default:
			{
				DateTime dateTime = TimeHelper.ToDateTime(self.ActivityData.StartTime);
				self._DescText.SetText(dateTime.ToString("MM月dd日 ") + Language.Get(5, 1709));
				break;
			}
			}
		}

		private static void StartTime(this UIKingWarActivityPanel2 self)
		{
			self.StopTime();
			self.OnTimeUpdate();
			self.TimeId = self.NewTimer(1000L, self.OnTimeUpdate, repeat: true);
		}

		private static void StopTime(this UIKingWarActivityPanel2 self)
		{
			if (self.TimeId > 0)
			{
				self.RemoveTimer(ref self.TimeId);
			}
		}

		private static void OnTimeUpdate(this UIKingWarActivityPanel2 self)
		{
			long num = TimeHelper.Now();
			if (self.TargetTime <= num)
			{
				self.UpdateView();
				return;
			}
			long num2 = self.TargetTime - num;
			TimeSpan timeSpan = TimeSpan.FromSeconds((float)num2 / 1000f);
			string text = ((num2 < 86400000) ? timeSpan.ToString("hh\\:mm\\:ss") : timeSpan.ToString(Language.Get(2, 312)));
			self._TimeText.SetText(text ?? "");
		}
	}
