			{
				self._SelectImage.SetActive(component.MainUnit == kingWarUnit.Unit);
			}
		}

		public static void StartTime(this UIKingWarHandleItem self)
		{
			if (self.TimeId <= 0)
			{
				self.TimeId = self.NewTimer(1000L, self.OnTimeUpdate, repeat: true);
				self.OnTimeUpdate();
			}
		}

		private static void StopTime(this UIKingWarHandleItem self)
