		private static void OnGoClick(this UIKingWarHandleItem self)
		{
			Player player = ((Entity)(object)self).LocalPlayer();
			KingWarModule component = ((Entity)player).GetComponent<KingWarModule>();
			KingWarComponent component2 = ((Entity)((Entity)(object)self).GetCurrentScene()).GetComponent<KingWarComponent>();
			if (component2 == null)
			{
				return;
			}
			KingWarUnit kingWarUnit = component2.GetKingWarUnit(((Entity)player).Id, self.KingWarUnitId);
			long num = TimeHelper.Now();
			if (kingWarUnit.CoolTime > num)
			{
				UIGameMsgHelper.FloatMsg("队伍调整中，无法出征");
				return;
			}
			if (kingWarUnit.BuildId == self.TargetId)
			{
				int playerNum = component2.GetPlayerNum(self.TargetId, (kingWarUnit.CampId != 1) ? 1 : 2);
				KingWarBuild child = ((Entity)component2).GetChild<KingWarBuild>((long)self.TargetId);
				if (kingWarUnit.CampId == 1)
				{
					if (playerNum <= 0 && child.Hp <= 0)
					{
						UIGameMsgHelper.FloatMsg("已在当前位置");
						return;
					}
				}
				else if (playerNum <= 0)
				{
					UIGameMsgHelper.FloatMsg("已在当前位置");
					return;
				}
			}
			component.ReqMoveToMonster(self.FormationId, self.TargetId).Coroutine();
			self._StateText.SetActive(active: true);
			self._GoButton.SetActive(active: false);
		}
	}
