		public static void UpdateButton(this UIKingWarHeadGroupBar self)
		{
			int configId = self.ConfigId;
			KingWarComponent component = ((Entity)((Entity)(object)self).GetSceneByLayer(SceneLayer.War)).GetComponent<KingWarComponent>();
			KingWarMonsterConfig kingWarMonsterConfig = ConfigSingleton<KingWarMonsterConfigCategory>.Instance.Get(configId);
			self._GotoBtn.SetActive(component.Stage >= kingWarMonsterConfig.Stage);
		}

		public static void Update(this UIKingWarHeadGroupBar self, KingWarBuildComponent buildComponent)
		{
			self.ConfigId = buildComponent.ConfigId;
			int configId = self.ConfigId;
			KingWarComponent component = ((Entity)((Entity)(object)self).GetSceneByLayer(SceneLayer.War)).GetComponent<KingWarComponent>();
			KingWarMonsterConfig kingWarMonsterConfig = ConfigSingleton<KingWarMonsterConfigCategory>.Instance.Get(configId);
			self._GotoBtn.SetActive(component.Stage >= kingWarMonsterConfig.Stage);
			int playerNum = component.GetPlayerNum(configId, 1);
			if (playerNum > 0)
			{
				List<KingWarUnit> playerUnits = component.GetPlayerUnits(configId, 1);
				for (int i = 0; i < self.AttackUnits.Count; i++)
				{
					UIKingWarHeadBar uIKingWarHeadBar = self.AttackUnits[i];
					KingWarUnit kingWarUnit = ((playerUnits.Count > i) ? playerUnits[i] : null);
					uIKingWarHeadBar.UIObject.SetActive(kingWarUnit != null);
					if (kingWarUnit != null)
					{
						uIKingWarHeadBar.SetData(kingWarUnit);
					}
				}
				self._AttackAddImage.SetActive(playerNum > self.AttackUnits.Count);
				self._AttackNumText.SetText($"{playerNum}");
				self._AttackContent.SetActive(active: true);
			}
			else
			{
				self._AttackContent.SetActive(active: false);
			}
			int playerNum2 = component.GetPlayerNum(configId, 2);
			if (playerNum2 > 0)
			{
				List<KingWarUnit> playerUnits2 = component.GetPlayerUnits(configId, 2);
				for (int j = 0; j < self.DefendUnits.Count; j++)
				{
					UIKingWarHeadBar uIKingWarHeadBar2 = self.DefendUnits[j];
					KingWarUnit kingWarUnit2 = ((playerUnits2.Count > j) ? playerUnits2[j] : null);
					uIKingWarHeadBar2.UIObject.SetActive(kingWarUnit2 != null);
					if (kingWarUnit2 != null)
					{
						uIKingWarHeadBar2.SetData(kingWarUnit2);
					}
				}
				self._DefendAddImage.SetActive(playerNum2 > self.DefendUnits.Count);
				self._DefendContent.SetActive(active: true);
				self._DefendNumText.SetText($"{playerNum2}");
			}
			else
			{
				self._DefendContent.SetActive(active: false);
			}
		}
	}
