		private static void UpdateLock(this UIKingWarMainPanel self)
		{
			self.MonsterHeads.Clear();
			Scene currentScene = ((Entity)(object)self).GetCurrentScene();
			KingWarComponent kingWarComponent = ((Entity)currentScene).GetComponent<KingWarComponent>();
			if (kingWarComponent == null)
			{
				return;
			}
			int stage = kingWarComponent.Stage;
			self._MonsterHead.SetActive(active: false);
			switch (stage)
			{
			case 1:
				self.CurMonsterId = kingWarComponent.KingWarMonsterIds[1];
				self._MonsterHead.CloneAll(1, delegate(int i, UIObject o)
				{
					KingWarMonsterConfig kingWarMonsterConfig = ConfigSingleton<KingWarMonsterConfigCategory>.Instance.Get(kingWarComponent.KingWarMonsterIds[1]);
					o.Find("Select").SetActive(active: false);
					o.Find("Icon").SetRawTexture(kingWarMonsterConfig.Head).Coroutine();
					self.MonsterHeads.Add(o);
				}).Coroutine();
				break;
			case 2:
				self._MonsterHead.CloneAll(3, delegate(int i, UIObject o)
				{
					int temp = i;
					KingWarMonsterConfig kingWarMonsterConfig = ConfigSingleton<KingWarMonsterConfigCategory>.Instance.Get(self.GetConfigIdByIndex(i));
					o.Find("Select").SetActive(active: false);
					o.Find("Icon").SetRawTexture(kingWarMonsterConfig.Head).Coroutine();
					o.AddClickHandler(delegate
					{
						self.OnMonsterHeadClick(temp);
					});
					self.MonsterHeads.Add(o);
				}).Coroutine();
				self.OnMonsterHeadClick(0);
				break;
			}
		}

		private static int GetConfigIdByIndex(this UIKingWarMainPanel self, int index)
		{
			KingWarComponent component = ((Entity)((Entity)(object)self).GetCurrentScene()).GetComponent<KingWarComponent>();
			return index switch
			{
				0 => component.KingWarMonsterIds[4], 
				1 => component.KingWarMonsterIds[2], 
				2 => component.KingWarMonsterIds[3], 
				_ => component.KingWarMonsterIds[4], 
			};
		}

		private static void OnMonsterHeadClick(this UIKingWarMainPanel self, int index)
		{
			for (int i = 0; i < self.MonsterHeads.Count; i++)
			{
				self.MonsterHeads[i].Find("Select").SetActive(index == i);
				if (index == i)
				{
					self.CurMonsterId = self.GetConfigIdByIndex(i);
				}
			}
		}

		private static void StartTime(this UIKingWarMainPanel self)
		{
			if (self.AttackTimeId <= 0)
			{
				self.AttackTimeId = self.NewTimer(1000L, self.OnTimeUpdate, repeat: true);
				self.OnTimeUpdate();
			}
		}

		private static void StopTime(this UIKingWarMainPanel self)
		{
			if (self.AttackTimeId > 0)
			{
				self.RemoveTimer(ref self.AttackTimeId);
			}
		}

		private static void OnTimeUpdate(this UIKingWarMainPanel self)
		{
			long num = TimeHelper.Now();
			if (num > self.AttackCDTime)
			{
				self.StopTime();
				self._TimeText.SetActive(active: false);
				self._HandleButton.SetGray(isGray: false);
				KingWarModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<KingWarModule>();
				component.IsBattled = false;
				component.IsDead = false;
			}
			else
			{
				string text = TimeSpan.FromSeconds((double)((self.AttackCDTime - num) / 1000)).ToString("mm\\:ss");
				self._TimeText.SetActive(active: true);
				self._TimeText.SetText("（" + text + "）");
				self._HandleButton.SetGray();
			}
		}

