		private static void InitPanel(this UIKingWarPanel self)
		{
			self._DescText1.SetText("");
			self.ActivityData = ((Entity)(object)self).LocalPlayer().GetActivityDataByType(ActivityType.KingWar);
			if (self.ActivityData == null)
			{
				self._DescText.SetActive(active: false);
			}
			switch (TimeHelper.DaysBetween(TimeHelper.Now(), self.ActivityData.StartTime, 0L))
			{
			case 1:
				self._DescText2.SetText("今天 " + Language.Get(5, 1709));
				break;
			case 2:
				self._DescText2.SetText("明天 " + Language.Get(5, 1709));
				break;
			default:
			{
				DateTime dateTime = TimeHelper.ToDateTime(self.ActivityData.StartTime);
				self._DescText2.SetText(dateTime.ToString("MM月dd日 ") + Language.Get(5, 1709));
				break;
			}
			}
			self.UpdateTime();
			self.ReqKingWarData().Coroutine();
			self.ReqBarrageInfo().Coroutine();
