		public static void SetSelfData(this UIKingWarRankItem self, int rank, long value)
		{
			//IL_0125: Unknown result type (might be due to invalid IL or missing references)
			if (rank == 0)
			{
				self._Content.SetActive(active: false);
				self._UnRankText.SetActive(active: true);
				return;
			}
			self._Content.SetActive(active: true);
			self._UnRankText.SetActive(active: false);
			self._RankImage.SetActive(rank <= 3);
			self._RankText.SetActive(rank > 3);
			if (self._RankText.IsActive())
			{
				self._RankText.SetText($"{rank}");
			}
			if (self._RankImage.IsActive())
			{
				self._RankImage.SetSprite($"ui_xmgw2_sign_0{rank + 1}").Coroutine();
			}
			int points = ConfigSingleton<KingWarGlobalConfigCategory>.Instance.GetOne().points;
			self._ValueText.SetText(TextHelper.FormatDamage(value / points));
			RankConfig rankConfig = ConfigSingleton<RankConfigCategory>.Instance.Get(self.RankType);
			if (rankConfig.IsGuildRank)
			{
				self._NameText.SetText(((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<GuildModule>().GetName());
			}
			else if (rankConfig.IsZoneRank)
			{
				self._NameText.SetText($"S.{new UIDStruct(((Entity)((Entity)(object)self).LocalPlayer()).Id).Zone}");
			}
			else
			{
				self._NameText.SetText(((Entity)(object)self).LocalPlayer().GetName());
			}
		}

		public static void SetData(this UIKingWarRankItem self, RankInfo rankInfo)
		{
			int rankNo = rankInfo.RankNo;
			if (rankNo == 0)
			{
				self._Content.SetActive(active: false);
				self._UnRankText.SetActive(active: true);
				return;
			}
			self._Content.SetActive(active: true);
			self._UnRankText.SetActive(active: false);
			RankConfig rankConfig = ConfigSingleton<RankConfigCategory>.Instance.Get(self.RankType);
			if (rankConfig.IsGuildRank)
			{
				self._NameText.SetText(rankInfo.GuildInfo.Name);
			}
			else if (rankConfig.IsZoneRank)
			{
				self._NameText.SetText($"S.{rankInfo.Id}");
			}
			else
			{
				self._NameText.SetText(rankInfo.Name);
			}
			self._RankImage.SetActive(rankInfo.RankNo <= 3);
			self._RankText.SetActive(rankInfo.RankNo > 3);
			if (self._RankText.IsActive())
			{
				self._RankText.SetText($"{rankInfo.RankNo}");
			}
			if (self._RankImage.IsActive())
			{
				self._RankImage.SetSprite($"ui_xmgw2_sign_0{rankNo + 1}").Coroutine();
			}
			int points = ConfigSingleton<KingWarGlobalConfigCategory>.Instance.GetOne().points;
			self._ValueText.SetText(TextHelper.FormatDamage(rankInfo.Value / points));
		}
	}
