		[UIMethod]
		public static void OnShow(this UIKingWarResultPanel self)
		{
			self.Stage = 1;
			Player player = ((Entity)(object)self).LocalPlayer();
			KingWarResult kingWarResult = ((Entity)player).GetComponent<KingWarModule>().KingWarResult;
			int season = kingWarResult.Season;
			int points = ConfigSingleton<KingWarGlobalConfigCategory>.Instance.GetOne().points;
			self._PersonHead.SetData(player, showPracticeLevel: false);
			self._PersonNameText.SetText(player.GetName());
			self._PersonBuildText.SetText((kingWarResult.BuildHurt / points).ToString());
			self._PersonEnemyText.SetText((kingWarResult.EnemyHurt / points).ToString());
			self._PersonMonsterText.SetText((kingWarResult.MonsterHurt / points).ToString());
			KingWarRewardConfig rewardConfig = KingWarHelper.GetRewardConfig(season, 1, kingWarResult.Rank);
			self._PersonRewardList.ShowDrop(rewardConfig?.DayReward ?? 0);
			self._GuildBuildText.SetText((kingWarResult.GuildBuildHurt / points).ToString());
			self._GuildEnemyText.SetText((kingWarResult.GuildEnemyHurt / points).ToString());
			self._GuildMonsterText.SetText((kingWarResult.GuildMonsterHurt / points).ToString());
			self._GuildRankText.SetText(kingWarResult.GuildRankNo.ToString());
			long num = kingWarResult.GuildBuildHurt + kingWarResult.GuildEnemyHurt + kingWarResult.GuildMonsterHurt;
			self._GuildText.SetText(TextHelper.FormatDamage(num / points));
			GuildModule component = ((Entity)player).GetComponent<GuildModule>();
			self._UICommonGuildIcon.SetData(component.GuildInfo.BaseInfo.GuildId, component.GuildInfo.BaseInfo.Flag, component.GuildInfo.BaseInfo.Icon);
			self._GuildNameText.SetText(component.GetName());
			self._MvpHead.SetData(kingWarResult.MvpInfo);
			self._MvpNameText.SetText(kingWarResult.MvpInfo.Name);
			self._MvpHurtText.SetText((kingWarResult.MvpHurt / points).ToString());
			self._MvpGuildName.SetText(kingWarResult.MvpGuildName);
			int skinModelId = kingWarResult.MvpInfo.DressInfo.GetSkinModelId((byte)kingWarResult.MvpInfo.Sex);
			int weaponModelId = kingWarResult.MvpInfo.DressInfo.GetWeaponModelId((byte)kingWarResult.MvpInfo.Sex);
			int capeModelId = kingWarResult.MvpInfo.DressInfo.GetCapeModelId((byte)kingWarResult.MvpInfo.Sex);
			self._UICommonModelPanel.ShowHighModel(new UIModelInfo(skinModelId, weaponModelId, capeModelId)
			{
				AnimName = "ShowIdle"
			}).Coroutine();
			self.ShowStage();
