	[RedPointHandler(RedPointType.Ladder)]
	public class LadderRedPointHandler : ARedPointHandler
	{
		public override int GetCount(Scene scene, params int[] parameters)
		{
			Player player = ((Entity)(object)scene).LocalPlayer();
			if (player == null)
			{
				return 0;
			}
			if (!player.CheckFuncOpen(5008, IsCheckParent: true))
			{
				return 0;
			}
			ActivityData activityByType = ((Entity)player).GetComponent<PlayerActivityComponent>().GetActivityByType(ActivityType.Ladder);
			if (activityByType == null)
			{
				return 0;
			}
			if (activityByType.State != ActivityState.Open)
			{
				return 0;
			}
			LadderActivityModule component = ((Entity)activityByType).GetComponent<LadderActivityModule>();
			bool flag = component.IsCanLadderFight();
			int num = ((parameters != null && parameters.Length > 0) ? parameters[0] : 0);
			if (num == -1)
			{
				if (!flag)
				{
					return 0;
				}
				if (!component.IsReadRedPoint)
				{
					return 1;
				}
				return 0;
			}
			LadderBoxRewardConfig ladderBoxRewardConfig = ConfigSingleton<LadderBoxRewardConfigCategory>.Instance.Get(component.BoxId);
			if (num == -2)
			{
				if (component.IsBoxGet)
				{
					return 0;
				}
				if (component.WinCount < ladderBoxRewardConfig.BattleNums)
				{
					return 0;
				}
				return 1;
			}
			if (component.WinCount >= ladderBoxRewardConfig.BattleNums && !component.IsBoxGet)
			{
				return 1;
			}
			if (flag && !component.IsReadRedPoint)
			{
				return 1;
			}
			return 0;
		}
	}
