		private static void StartTime(this UILadderActivityPanel self)
		{
			if (self.TimeId <= 0)
			{
				self.TimeId = self.NewTimer(1000L, self.OnTimeUpdate, repeat: true);
				self.OnTimeUpdate();
			}
		}

		private static void StopTime(this UILadderActivityPanel self)
		{
			if (self.TimeId > 0)
			{
				self.RemoveTimer(ref self.TimeId);
			}
		}

		private static void OnTimeUpdate(this UILadderActivityPanel self)
		{
			long num = TimeHelper.Now();
			if (self.TargetTime <= num)
			{
				self._TimeText.SetText("");
				self.UpdateView();
				return;
			}
			long num2 = self.TargetTime - num;
			TimeSpan timeSpan = TimeSpan.FromSeconds((float)num2 / 1000f);
			string text = ((num2 < 86400000) ? timeSpan.ToString("hh\\:mm\\:ss") : timeSpan.ToString(Language.Get(2, 312)));
			self._TimeText.SetText(text ?? "");
		}

		private static void UpdateView(this UILadderActivityPanel self)
		{
			ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActivityId);
			long num = TimeHelper.Now();
			long startTime = activityData.StartTime;
			long endTime = activityData.EndTime;
			self._DescTime.SetText(Language.Get(5, (startTime > num) ? 1602 : 1603));
			LadderActivityModule component = ((Entity)activityData).GetComponent<LadderActivityModule>();
			int nextRoundId = self.GetNextRoundId();
			int ladderRoundId = component.GetLadderRoundId();
			if (ConfigSingleton<LadderRoundConfigCategory>.Instance.Contain(ladderRoundId))
			{
				self.LadderState = ConfigSingleton<LadderRoundConfigCategory>.Instance.Get(ladderRoundId)?.State ?? 1;
			}
			else
			{
				self.LadderState = 1;
			}
			if (nextRoundId <= 0)
			{
				self._DescTime.SetText(Language.Get(5, 1602));
				self.TargetTime = ((startTime > num) ? startTime : endTime);
			}
			else
			{
				if (self.LadderState == 3)
				{
					self._DescTime.SetText(Language.Get(5, 1603));
				}
				else
				{
					self._DescTime.SetText(Language.Get(5, 1604));
				}
				self.TargetTime = component.GetLadderRoundTime(nextRoundId);
			}
			self._LookButton.SetGray(!component.IsCanLadderFight());
			self.StartTime();
		}

		public static int GetNextRoundId(this UILadderActivityPanel self)
		{
			ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActivityId);
			LadderActivityModule component = ((Entity)activityData).GetComponent<LadderActivityModule>();
			long num = activityData.StartTime;
			long endTime = activityData.EndTime;
			long num2 = TimeHelper.Now();
			if (num2 < num)
			{
				return 0;
			}
			if (endTime < num2)
			{
				return 0;
			}
			List<LadderRoundConfig> list = ConfigSingleton<LadderRoundConfigCategory>.Instance.GetList();
			int ladderState = component.GetLadderState();
			int num3 = 0;
			for (int i = 0; i < list.Count; i++)
			{
				LadderRoundConfig ladderRoundConfig = list[i];
				num += ladderRoundConfig.RoundTime;
				if (num > num2 && ladderRoundConfig.State == 3)
				{
					num3 = ladderRoundConfig.Id;
					break;
				}
			}
			if (ladderState != 3)
			{
				num3--;
			}
			return num3;
		}

		private static void OnLookClick(this UILadderActivityPanel self)
		{
			if (self.LadderState == 2 || self.LadderState == 3)
			{
				UIJumpHelper.To(5008).Coroutine();
				UIManager.Instance.Remove(self.UIObject);
			}
			else
			{
				UIGameMsgHelper.FloatMsgByError(207206);
