	public static class UILadderHelper
	{
		public static List<LadderRewardConfig> GetRewardConfigs(int season, int type)
		{
			List<LadderRewardConfig> list = null;
			for (int i = season * 1000 + type * 100 + 1; ConfigSingleton<LadderRewardConfigCategory>.Instance.Contain(i); i++)
			{
				LadderRewardConfig item = ConfigSingleton<LadderRewardConfigCategory>.Instance.Get(i);
				if (list == null)
				{
					list = new List<LadderRewardConfig>();
				}
				list.Add(item);
			}
			return list;
		}
	}
