		public static void ReMatch(this UILadderMatchPanel self)
		{
			self._SelfItem.SetData(((Entity)(object)self).LocalPlayer(), self.ActivityId);
			self.CurMatchInfo = null;
			self.MaxCount = ConfigSingleton<GlobalConfigCategory>.Instance.GetOne().LadderMatchTime;
			self.MatchTime = RandomGenerator.RandomNumber(0, self.MaxCount - 10);
			self.TimeStep = 0;
			if (self.TimeId <= 0)
			{
				self.TimeId = self.NewTimer(1000L, self.OnUpdateTime, repeat: true);
				self.OnUpdateTime();
			}
		}

		private static void OnUpdateTime(this UILadderMatchPanel self)
		{
			if (self.MaxCount <= 0)
			{
				self.RemoveTimer(ref self.TimeId);
			}
			self._TimeText.SetText(string.Format("匹配时间：00:{0}", (self.MaxCount < 10) ? ("0" + self.MaxCount) : ((object)self.MaxCount)));
			self.MaxCount--;
			if (self.CurMatchInfo != null)
			{
				self.ReadlyFight().Coroutine();
				self.RemoveTimer(ref self.TimeId);
				return;
			}
			if (self.MatchInterval == self.TimeStep)
			{
				ActivityHelper.GetActivityModule<LadderActivityModule>(((Entity)(object)self).LocalPlayer(), self.ActivityId).ReqStartMatch();
				self.TimeStep = 0;
			}
			self._MatchItem.PlayMatchEffect();
			self.TimeStep++;
		}

