		private static void OnContinueClick(this UILadderResultPanel self)
		{
			if (((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<PrivilegeModule>().GetLadder1AutoPlayCount() <= 0)
			{
				((Toggle)self._ContinueButton.GameObject.GetComponent<SuperToggle>()).isOn = false;
				UICommonHelper.ShowConfirmPanel(new ConfirmPanelOptions
				{
					Title = Language.Get(4, 718),
					Message = "开通月卡后激活此功能",
					NoConfirmTillNextLogin = false,
					OkAction = delegate
					{
						UIGameMsgHelper.FloatMsg("解锁月卡后可享受连续匹配");
						if (((Entity)(object)self).LocalPlayer().IsFuncOpen(46))
						{
							UIJumpHelper.To(46).Coroutine();
						}
					}
				});
			}
			else
