		[UIMethod]
		public static void OnShow(this UILadderTopActivityPanel self, int activityId)
		{
			self.ActivityId = activityId;
			UICommonHorizontalRewardSystem.SetData(rewards: (self.ActivityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), activityId)).BaseInfo.Items?.ToArray(), self: self._RewardList);
			self._RewardList.SetSpaceX(0);
			self.UpdateView();
		}

		private static void OnTimeUpdate(this UILadderTopActivityPanel self)
		{
			var (num, text) = UILadderTopHelper.GetActivityTimeDesc(SceneHelper.DomainScene((Entity)(object)self));
			if (num <= 0)
			{
				self.RemoveTimer(ref self.TimeId);
			}
			self._TimeText.SetText(text ?? "");
		}

		private static void UpdateView(this UILadderTopActivityPanel self)
		{
			self.RemoveTimer(ref self.TimeId);
			self.OnTimeUpdate();
			self.TimeId = self.NewTimer(1000L, self.OnTimeUpdate, repeat: true);
			string text = TimeHelper.ToDateTime(self.ActivityData.StartTime).ToString("MM月dd日 ");
			string text2 = TimeHelper.ToDateTime(self.ActivityData.EndTime).ToString("MM月dd日 ");
			string text3 = text + "-" + text2;
			self._TxtTime.SetLanguage(6, 4431, text3);
			CrossType crossType = self.ActivityData.CrossType;
			int num = 0;
			switch (crossType)
			{
			case CrossType.SmallLink:
				num = 32;
				break;
			case CrossType.BigLink:
				num = 16;
				break;
			}
			self._TxtGetRank.SetLanguage(6, 4430, num);
		}

		private static void OnLookClick(this UILadderTopActivityPanel self)
		{
			UIJumpHelper.To(5011).Coroutine();
			UIManager.Instance.Remove(self.UIObject);
		}

