		[UIMethod]
		public static void OnShow(this UILadderTopAwardsPopup self, int args)
		{
			ActivityData activityDataByType = ((Entity)(object)self).LocalPlayer().GetActivityDataByType(ActivityType.LadderTop);
			if (activityDataByType != null)
			{
				int curLoopCount = activityDataByType.CurLoopCount;
				List<LadderTopRankAward> seasonAwards = ConfigSingleton<LadderTopStageAwardsConfigCategory>.Instance.GetSeasonAwards(curLoopCount);
				self._UIScrollList.SetData(seasonAwards.Count);
				self._UICommonPopup.SetTitle("奖励预览");
			}
