		private static void OnCellUpdate(this UILadderTopAwardsPopup self, UIScrollListCell cell)
		{
			int season = ((Entity)(object)self).LocalPlayer().GetActivityDataByType(ActivityType.LadderTop)?.CurLoopCount ?? 1;
			List<LadderTopRankAward> seasonAwards = ConfigSingleton<LadderTopStageAwardsConfigCategory>.Instance.GetSeasonAwards(season);
			if (cell.Index < seasonAwards.Count)
			{
				LadderTopRankAward award = seasonAwards[cell.Index];
				((Entity)cell.UIObject).GetComponent<UILadderTopAwardsItem>().SetData(award, cell.Index);
			}
		}
	}
