		public static void RefreshUI(this UILadderTopGambleBetWidget self)
		{
			ActivityData activityDataByType = ((Entity)(object)self).LocalPlayer().GetActivityDataByType(ActivityType.LadderTop);
			self.ActivityId = ((Entity)activityDataByType).Id;
			LadderTopModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<LadderTopModule>();
			self.BetData = component.BetData;
			LadderTopNodeInfo nodeByNodeId = component.GetNodeByNodeId(self.BetData.NodeId);
			if (nodeByNodeId == null)
			{
				Log.Error("LadderTopModule 中没有找到当前服务器节点信息");
				return;
			}
			long roundTime = component.RoundEndTime;
			LadderTopRoundConfig ladderTopRoundConfig = ConfigSingleton<LadderTopRoundConfigCategory>.Instance.Get(component.Round);
			long leftTime;
			if (ladderTopRoundConfig != null)
			{
				if (ladderTopRoundConfig.State == 1)
				{
					leftTime = roundTime - TimeHelper.ServerNow();
					if (leftTime > 0)
					{
						self.RemoveTimer(ref self.TimeId);
					}
					OnTimeUpdate();
					self.TimeId = self.NewTimer(1000L, OnTimeUpdate, repeat: true);
				}
				else
				{
					self._TxtTime.SetText("本轮竞猜已结束");
				}
			}
			else
			{
				self._TxtTime.SetText("活动已结束");
			}
			string text = UILadderTopHelper.FromToScheduleName(nodeByNodeId.Schedule, isTo: false);
			self._TxtCurRound.SetText("当前竞猜：" + text);
			LadderTopNodeInfo nodeByNodeId2 = component.GetNodeByNodeId(nodeByNodeId.LeftChildId);
			LadderTopNodeInfo nodeByNodeId3 = component.GetNodeByNodeId(nodeByNodeId.RightChildId);
			PlayerCommonInfo playerInfo = nodeByNodeId2.PlayerInfo;
			PlayerCommonInfo playerInfo2 = nodeByNodeId3.PlayerInfo;
			UIObject uiObject = self._Players.Find("1");
			UIObject uiObject2 = self._Players.Find("2");
			self.SetPlayerInfo(uiObject, playerInfo);
			self.SetPlayerInfo(uiObject2, playerInfo2);
			self.SetCost();
			void OnTimeUpdate()
			{
				leftTime = roundTime - TimeHelper.ServerNow();
				if (leftTime <= 0)
				{
					self._TxtTime.SetText("本轮竞猜已结束");
					UIManager.Instance.Remove(typeof(UILadderTopGamblePopup));
					self.RemoveTimer(ref self.TimeId);
				}
				else
				{
					string text2 = ((leftTime > 600000) ? "#5BF947" : "#FF0000");
					string text3 = ((leftTime > 86400000) ? (TextHelper.TimeFormatDays(leftTime) + TextHelper.TimeFormatHourMinSec(leftTime)) : TextHelper.TimeFormatHourMinSec(leftTime));
					self._TxtTime.SetText("<color=" + text2 + ">" + text3 + "后结束竞猜</color>");
				}
			}
		}

