		public static void CheckResultPanelShown(Scene scene, int activityId)
		{
			try
			{
				if (!((Entity)(object)scene).LocalPlayer().IsFuncOpen(5011))
				{
					return;
				}
				LadderTopModule component = ((Entity)((Entity)(object)scene).LocalPlayer()).GetComponent<LadderTopModule>();
				if (component == null)
				{
					Log.Debug($"LadderTop CheckResultPanelShown: LadderTopModule not found for activity {activityId}");
					return;
				}
				long champion = component.GetChampion();
				if (champion == 0L)
				{
					Log.Debug($"LadderTop CheckResultPanelShown: No champion yet for activity {activityId}");
					return;
				}
				ActivityData activityDataByType = ((Entity)(object)scene).LocalPlayer().GetActivityDataByType(ActivityType.LadderTop);
				string key = string.Format("{0}_{1}", "LadderTopResultPanelShown", activityDataByType?.CurLoopCount ?? 0);
				if (((Entity)(object)scene).LocalPlayer().GetLocalLong(key, 0L) == champion)
				{
					Log.Debug($"LadderTop CheckResultPanelShown: Result panel already shown for champion {champion} in loop {activityDataByType?.CurLoopCount ?? 0}");
				}
				else if (UIObject.FindUIObjectOfType<UILadderTopPanel>() != null)
				{
					Log.Info($"LadderTop CheckResultPanelShown: Showing result panel - LadderTopPanel is open, champion: {champion}");
					UIManager.Instance.Show<UILadderTopResultPanel, int>(activityId).Coroutine();
				}
				else if (UIManager.Instance.Get<UIMainPanel>() == null)
				{
					Log.Debug("LadderTop CheckResultPanelShown: MainPanel not open, delaying result panel show");
				}
				else
				{
					Log.Info($"LadderTop CheckResultPanelShown: Showing result panel from main interface, champion: {champion}");
					UIManager.Instance.Show<UILadderTopResultPanel, int>(activityId).Coroutine();
				}
			}
			catch (Exception arg)
			{
				Log.Error($"LadderTop CheckResultPanelShown error: {arg}");
			}
		}

		public static bool CheckMainUIShow(Scene scene)
		{
			try
			{
				Player player = ((Entity)(object)scene).LocalPlayer();
				if (player == null || !player.IsFuncOpen(5011))
				{
					return false;
				}
				ActivityData activityDataByType = player.GetActivityDataByType(ActivityType.LadderTop);
				if (activityDataByType == null)
				{
					Log.Debug("CheckMainUIShow: No LadderTop activity data found");
					return false;
				}
				LadderTopModule component = ((Entity)((Entity)(object)scene).LocalPlayer()).GetComponent<LadderTopModule>();
				if (component == null)
				{
					return false;
				}
				long champion = component.GetChampion();
				if (champion == 0L)
				{
					Log.Debug($"CheckMainUIShow: No champion yet for activity {activityDataByType.ActivityId}");
					return false;
				}
				string key = string.Format("{0}_{1}", "LadderTopResultPanelShown", activityDataByType?.CurLoopCount ?? 0);
				if (player.GetLocalLong(key, 0L) == champion)
				{
					Log.Debug($"CheckMainUIShow: Result panel already shown for champion {champion} in loop {activityDataByType?.CurLoopCount ?? 0}");
					return false;
				}
				if (UIManager.Instance.Get<UIMainPanel>() != null)
				{
					Log.Info($"CheckMainUIShow: Showing result panel for champion {champion}");
					UIManager.Instance.Show<UILadderTopResultPanel, int>(activityDataByType.ActivityId).Coroutine();
					return true;
				}
				return false;
			}
			catch (Exception arg)
			{
				Log.Error($"CheckMainUIShow error: {arg}");
				return false;
			}
		}

		public static string GetScheduleName(int schedule, bool ignoreFinals = false)
		{
			switch (schedule)
			{
			case 1:
				if (!ignoreFinals)
				{
					return Language.Get(6, 4411);
				}
				return Language.Get(6, 4421);
			case 2:
				if (!ignoreFinals)
				{
					return Language.Get(6, 4412);
				}
				return Language.Get(6, 4422);
			case 3:
				if (!ignoreFinals)
				{
					return Language.Get(6, 4413);
				}
				return Language.Get(6, 4423);
			case 4:
				if (!ignoreFinals)
				{
					return Language.Get(6, 4414);
				}
				return Language.Get(6, 4424);
			case 5:
				if (!ignoreFinals)
				{
					return Language.Get(6, 4415);
				}
				return Language.Get(6, 4425);
			case 6:
				if (!ignoreFinals)
				{
					return Language.Get(6, 4416);
				}
				return Language.Get(6, 4426);
			case 7:
				if (!ignoreFinals)
				{
					return Language.Get(6, 4417);
				}
				return Language.Get(6, 4427);
			default:
				return "";
			}
		}

		public static string FromToScheduleName(int schedule, bool isTo = true, bool ignoreFinals = true)
		{
			int num = (isTo ? (schedule + 1) : (schedule - 1));
			if ((!isTo && num == 6) || (isTo && num == 7))
			{
				return "冠军赛";
			}
			string scheduleName = GetScheduleName(schedule, ignoreFinals);
			string scheduleName2 = GetScheduleName(num, ignoreFinals);
			if (!isTo)
			{
				return scheduleName2 + "进" + scheduleName;
			}
			return scheduleName + "进" + scheduleName2;
		}

