		public static (long, string) GetActivityTimeDesc(Scene scene, bool showLadderTop = false)
		{
			long item = 0L;
			string empty = string.Empty;
			LadderTopModule component = ((Entity)((Entity)(object)scene).LocalPlayer()).GetComponent<LadderTopModule>();
			if (component == null)
			{
				return (item, "暂未开启");
			}
			int count = ConfigSingleton<LadderTopRoundConfigCategory>.Instance.GetList().Count;
			if (component.Round > 0 && component.Round <= count)
			{
				LadderTopRoundConfig ladderTopRoundConfig = ConfigSingleton<LadderTopRoundConfigCategory>.Instance.Get(component.Round);
				if (ladderTopRoundConfig != null)
				{
					item = component.RoundEndTime - TimeHelper.ServerNow();
					empty = TextHelper.TimeFormatDaysHourMinSec(item);
					string text = FromToScheduleName(component.CurrentSchedule);
					string text2 = ((ladderTopRoundConfig.State == 1) ? "竞猜" : "战斗");
					return (item, "<color=#5BF947>" + text + text2 + "进行中：" + empty + "</color>");
				}
			}
			ActivityData activityDataByType = ((Entity)(object)scene).LocalPlayer().GetActivityDataByType(ActivityType.LadderTop);
			if (activityDataByType?.StartTime > TimeHelper.ServerNow())
			{
				item = activityDataByType.StartTime - TimeHelper.ServerNow();
				empty = TextHelper.TimeFormatDaysHourMinSec(item);
				if (!showLadderTop)
				{
					return (item, "<color=#5BF947>下次开启：" + empty + "</color>");
				}
				return (item, "<color=#5BF947>封神倒计时：" + empty + "</color>");
			}
			return (0L, "<color=#5BF947>结算中</color>");
		}

		public static bool ShouldShowFormatButton(Scene scene)
		{
			LadderTopModule component = ((Entity)((Entity)(object)scene).LocalPlayer()).GetComponent<LadderTopModule>();
			if (component == null)
			{
				return false;
			}
			if (component.CurrentSchedule >= 7)
			{
				return false;
			}
			long id = ((Entity)((Entity)(object)scene).LocalPlayer()).Id;
			if (component.GetPlayerGroupIndex(id) < 0)
			{
				return false;
			}
			bool flag = component.IsPlayerEliminated(id);
			if (!flag && component.CurrentSchedule > 0)
			{
				flag = !component.IsPlayerInSchedule(id, component.CurrentSchedule);
			}
			return !flag;
		}
	}
