					return;
				}
				ladderTopNodeInfo = component.GetNodeByNodeId(ladderTopTreeNodeData.ServerNodeId);
				if (ladderTopNodeInfo == null || ladderTopNodeInfo.BattleRecords == null || ladderTopNodeInfo.BattleRecords.Count == 0)
				{
					UIGameMsgHelper.FloatMsg("没有回放信息");
					return;
				}
			}
			if (ladderTopNodeInfo.LeftChildId <= 0 || ladderTopNodeInfo.RightChildId <= 0)
			{
				UIGameMsgHelper.FloatMsg("当前轮次轮空，无可查看战斗");
			}
			else if (ladderTopNodeInfo.LeftChildId <= 0 && ladderTopNodeInfo.RightChildId <= 0)
