		public static void Refresh(this UILadderTopPanel self)
		{
			UIObject.FindUIObjectOfType<UILadderTopFinalsPanel>()?.RefreshUI();
			UIObject.FindUIObjectOfType<UILadderTopRoundKnockoutPanel>()?.RefreshUI();
			UIObject.FindUIObjectOfType<UILadderTopRoundFinalsPanel>()?.RefreshUI();
			self.SetTimeCountDown();
		}

		private static void SetTimeCountDown(this UILadderTopPanel self)
		{
			UpdateTime();
			self.RemoveTimer();
			self.CountDownTimer = self.NewTimer(1000L, UpdateTime, repeat: true);
			void UpdateTime()
			{
				var (num, text) = UILadderTopHelper.GetActivityTimeDesc(SceneHelper.DomainScene((Entity)(object)self));
				if (num <= 0)
				{
					self._UITimeCountDownBox.SetText(text);
					self.RemoveTimer(ref self.CountDownTimer);
				}
				else
				{
					self._UITimeCountDownBox.SetText(text);
				}
			}
		}

		private static void RemoveTimer(this UILadderTopPanel self)
		{
			if (self.CountDownTimer > 0)
			{
				self.RemoveTimer(ref self.CountDownTimer);
				self.CountDownTimer = 0L;
			}
		}

		private static int GetDefaultTabIndex(this UILadderTopPanel self)
		{
			LadderTopModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<LadderTopModule>();
			if (component == null)
			{
				return 0;
			}
			if (component.Round == 0)
			{
				return 0;
			}
			if (component.GetChampion() > 0)
			{
				return 0;
			}
			int currentSchedule = component.CurrentSchedule;
			if (currentSchedule < 4)
			{
				if (currentSchedule >= 1)
				{
					return 1;
				}
				return 0;
			}
			return 2;
		}
	}
