			{
				Formation formation = self.SortedLadderTopFormations.FirstOrDefault((Formation f) => f.FormationNo == 1);
				if (formation != null)
				{
					ChangeSceneHelper.Change(SceneFactory.CreateFormationScene(SceneHelper.DomainScene((Entity)(object)self), formation.ConfigId)).Coroutine();
				}
			}
			self.Close();
		}

		public static void RefreshList(this UILadderTopTeamPopup self)
		{
			FormationModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FormationModule>();
			List<Formation> list = new List<Formation>();
			foreach (Formation sortedLadderTopFormation in self.SortedLadderTopFormations)
			{
