		[UIMethod]
		public static void OnShow(this UILegendShowObtainPanel self, (int activityId, int stage) args)
		{
			self.ActivityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), args.activityId);
			self.Stage = args.stage;
			self.UpdateView();
		}

		private static void UpdateView(this UILegendShowObtainPanel self)
		{
			self.IsLock = false;
			LegendShowBaseConfig config = ConfigSingleton<LegendShowBaseConfigCategory>.Instance.GetConfig(self.ActivityData.ActivityId, self.Stage);
			LegendShowModule component = ((Entity)self.ActivityData).GetComponent<LegendShowModule>();
			int currentStage = ((Entity)self.ActivityData).GetComponent<LegendShowModule>().GetCurrentStage();
			if (currentStage > self.Stage || currentStage == -1)
			{
				self._TimeText.SetText("阶段已结束");
				if (self.ActivityData.State == ActivityState.Wait)
				{
					self._TimeText.SetText("活动暂未开启");
				}
			}
			else
			{
				long startTime = self.ActivityData.StartTime;
				if (currentStage == self.Stage)
				{
					self.TargetTime = startTime + (long)config.Day * 86400000L;
				}
				else
				{
					self.TargetTime = startTime + (long)(config.Day - 1) * 86400000L;
					self.IsLock = true;
				}
				self.StartTime();
			}
			self._CommonPopup.SetTitle(((component.GetStageCount() > 1) ? Language.Format(3, 243, config.Day) : "") + config.StageDesc);
			self.Configs = ConfigSingleton<LegendShowConfigCategory>.Instance.GetConfigs(self.ActivityData.ActivityId, self.Stage);
			self._List.SetData(self.Configs.Count);
		}

		private static void OnUpdateCell(this UILegendShowObtainPanel self, UIScrollListCell cell)
		{
			int index = cell.Index;
			((Entity)cell.UIObject).GetComponent<UILegendShowObtainItem>().SetData(self.Configs[index]);
		}

		private static void StartTime(this UILegendShowObtainPanel self)
		{
			if (self.TimeId <= 0)
			{
				self.TimeId = self.NewTimer(1000L, self.OnTimeUpdate, repeat: true);
			}
			self.OnTimeUpdate();
		}

		private static void OnTimeUpdate(this UILegendShowObtainPanel self)
		{
			long num = TimeHelper.Now();
