		private static void SelectStage(this UILegendShowPanel self, int index)
		{
			LegendShowModule component = ((Entity)self.ActivityData).GetComponent<LegendShowModule>();
			int stageCount = component.GetStageCount();
			int currentStage = component.GetCurrentStage();
			if (component.IsBetweenActivity() && stageCount > 1 && index > currentStage && index != 0 && component.IsBetweenActivity())
			{
				UIManager.Instance.Show<UILegendShowObtainPanel, (int, int)>((self.ActivityData.ActivityId, self.BaseConfigs[index].Stage)).Coroutine();
				return;
			}
			self._DateTextAllRank.SetActive(index != 0 && stageCount > 1);
			self._AllRankDes.SetText(Language.Get(3, 269));
			self._AllRankDes.SetActive(index == 0 && stageCount > 1);
			self._ZeroTipGo.SetActive(index == 0 && stageCount > 1);
			self._LegendBg.SetTop((index == 0 && stageCount > 1) ? 50 : 15);
			self.RankButtonIndex = 0;
			self.StageIndex = index;
			LegendShowBaseConfig legendShowBaseConfig = self.BaseConfigs[self.StageIndex];
			self._TitleTextAllRank.SetText(legendShowBaseConfig.StageDesc);
			self._DateText.SetText($"第{legendShowBaseConfig.Stage}天");
			if (!string.IsNullOrEmpty(legendShowBaseConfig.StageBg))
			{
				self._Bg.SetRawTexture(legendShowBaseConfig.StageBg).Coroutine();
			}
			int key;
			UIObject value;
			foreach (KeyValuePair<int, UIObject> item in self.StageObjectDict)
			{
				item.Deconstruct(out key, out value);
				int i = key;
				((Entity)value).GetComponent<UILegendShowStage1Item>().SetSelected(i, self.StageIndex, currentStage, self.ActivityData);
			}
			foreach (KeyValuePair<int, UIObject> item2 in self.RankButtonObjectDict)
			{
				item2.Deconstruct(out key, out value);
				int num = key;
				((Entity)value).GetComponent<RankButton>().SetSelected(num == self.RankButtonIndex);
			}
			if (self.StageIndex != self.StageOldIndex)
			{
				self.StageOldIndex = self.StageIndex;
				self.RankButtonOldIndex = -1;
				self.UpdateButtonView();
				self.UpdateView();
			}
		}

		private static void UpdateButtonView(this UILegendShowPanel self)
		{
			if (((Entity)self.ActivityData).GetComponent<LegendShowModule>().GetStageCount() > 1)
			{
				self._ButtonScrollView.SetActive(self.StageIndex != 0);
				self._AllRankButtons.SetActive(self.StageIndex == 0);
				LegendShowBaseConfig legendShowBaseConfig = self.BaseConfigs[self.StageIndex];
				if (self.StageIndex == 0)
				{
					self._AllRankRewardButton.SetUIObjectChildShow(self.RankButtonIndex == 0);
					self._AllRankButton.SetUIObjectChildShow(self.RankButtonIndex == 1);
					((Behaviour)((Component)self._AllRankRewardButton.Transform).GetComponent<SuperImage>()).enabled = self.RankButtonIndex != 0;
					((Behaviour)((Component)self._AllRankButton.Transform).GetComponent<SuperImage>()).enabled = self.RankButtonIndex != 1;
					self._LegendDestinContent.SetActive(active: false);
					self._UILegendSmallShowRewardPanel.UIObject.SetActive(self.RankButtonIndex == 0);
					self._UILegendSmallShowRankPanel.UIObject.SetActive(self.RankButtonIndex == 1);
					if (self.RankButtonIndex == 1)
					{
						self._UILegendSmallShowRankPanel.OnShow((activityId: self.ActivityId, stage: legendShowBaseConfig.Stage));
					}
					if (self.RankButtonIndex == 0)
					{
						self._UILegendSmallShowRewardPanel.OnShow((activityId: self.ActivityId, stage: legendShowBaseConfig.Stage));
					}
					return;
				}
				self._LegendDestinContent.SetActive(self.RankButtonIndex == 0);
				self._UILegendSmallShowRankPanel.UIObject.SetActive(self.RankButtonIndex == 2);
				self._UILegendSmallShowRewardPanel.UIObject.SetActive(self.RankButtonIndex == 1);
				if (self.RankButtonIndex == 2)
				{
					self._UILegendSmallShowRankPanel.OnShow((activityId: self.ActivityId, stage: legendShowBaseConfig.Stage));
				}
				if (self.RankButtonIndex == 1)
				{
					self._UILegendSmallShowRewardPanel.OnShow((activityId: self.ActivityId, stage: legendShowBaseConfig.Stage));
				}
			}
			else
			{
				self._UILegendSmallShowRankPanel.UIObject.SetActive(active: false);
				self._UILegendSmallShowRewardPanel.UIObject.SetActive(active: false);
				self._LegendDestinContent.SetActive(active: true);
			}
			foreach (var (num2, uIObject2) in self.RankButtonObjectDict)
			{
				((Entity)uIObject2).GetComponent<RankButton>().SetSelected(num2 == self.RankButtonIndex);
			}
		}

		public static void UpdateView(this UILegendShowPanel self)
		{
			if (self.RankButtonObjectDict.TryGetValue(0, out var value) && self.StageIndex != 0)
			{
				value.SetRedPoint(RedPointType.Activity, self.ActivityId, self.StageIndex).Coroutine();
			}
			if (self.StageObjectDict.TryGetValue(self.StageIndex, out var value2) && self.StageIndex != 0)
			{
				value2.SetRedPoint(RedPointType.Activity, self.ActivityId, self.StageIndex).Coroutine();
			}
			RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.Activity, self.ActivityId);
			if (self.BaseConfigs.Count <= 0)
			{
				return;
			}
			LegendShowModule component = ((Entity)self.ActivityData).GetComponent<LegendShowModule>();
			LegendShowBaseConfig legendShowBaseConfig = self.BaseConfigs[self.StageIndex];
			self.StageConfigs = ConfigSingleton<LegendShowStageConfigCategory>.Instance.GetStageConfigs(self.ActivityData.ActivityId, legendShowBaseConfig.Stage);
			self._StageList.SetData(self.StageConfigs.Count);
			self._StageList.MovePanelToItemIndex(component.GetRewardLevel() - 1);
			int currentStage = component.GetCurrentStage();
			self._StageText.SetText(legendShowBaseConfig.StageDesc);
			self._StageTimeText.SetText("");
			if (currentStage == legendShowBaseConfig.Stage)
			{
				long startTime = self.ActivityData.StartTime;
				self.TargetTime = startTime + (long)legendShowBaseConfig.Day * 86400000L;
				self.StartTime();
			}
			else
			{
				self.StopTime();
				self.TargetTime = 0L;
				if (currentStage < legendShowBaseConfig.Stage)
				{
					self._StageText.SetText(legendShowBaseConfig.StageDesc + "(未开始)");
				}
				else
				{
					self._StageText.SetText(legendShowBaseConfig.StageDesc + "(已结束)");
				}
			}
			self._ScoreTextNum.SetText($"{UIItemHelper.ItemNumsFormat(component.GetStageScore(legendShowBaseConfig.Stage) / 100):N0}");
			self.ReqRank().Coroutine();
		}

		private static void StartTime(this UILegendShowPanel self)
		{
			if (self.TimeId <= 0)
			{
				self.TimeId = self.NewTimer(1000L, self.OnTimeUpdate, repeat: true);
			}
			self.OnTimeUpdate();
		}

		private static void StopTime(this UILegendShowPanel self)
		{
			if (self.TimeId > 0)
			{
				self.RemoveTimer(ref self.TimeId);
			}
		}

		private static void OnTimeUpdate(this UILegendShowPanel self)
		{
			long num = TimeHelper.Now();
			LegendShowBaseConfig legendShowBaseConfig = self.BaseConfigs[self.StageIndex];
			if (self.TargetTime <= num)
			{
				self.StopTime();
				self._StageText.SetText(legendShowBaseConfig.StageDesc + "(已结束)");
				self._StageTimeText.SetText("");
			}
			else
			{
				long num2 = self.TargetTime - num;
				TimeSpan timeSpan = TimeSpan.FromSeconds((double)(num2 / 1000));
				string text = ((num2 < 86400000) ? timeSpan.ToString("hh\\:mm\\:ss") : timeSpan.ToString(Language.Get(2, 312)));
				self._StageTimeText.SetText("（" + text + "）");
			}
		}

		private static void StopWaitTime(this UILegendShowPanel self)
		{
			if (self.WaitTimeId > 0)
			{
				self.RemoveTimer(ref self.WaitTimeId);
			}
		}

		private static void OnWaitTimeUpdate(this UILegendShowPanel self)
		{
			long num = TimeHelper.Now();
			if (self.WaitTargetTime <= num)
			{
				ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActivityId);
				if (activityData.State != ActivityState.Wait)
				{
					self.ActivityData = activityData;
					self._OpenGroup.SetActive(active: true);
					self._WaitGroup.SetActive(active: false);
					self.ShowOpen();
					UIObject.FindUIObjectOfType<UIActiveRankingPanel>()?.RefreshActView();
					self.StopTime();
				}
			}
			else
			{
				long num2 = self.WaitTargetTime - num;
				TimeSpan timeSpan = TimeSpan.FromSeconds((double)(num2 / 1000));
				string text = ((num2 < 86400000) ? timeSpan.ToString("hh\\:mm\\:ss") : timeSpan.ToString(Language.Get(2, 312)));
				self._TimeText.SetText(text ?? "");
			}
		}

		public static void OnClickRewardButton(this UILegendShowPanel self)
		{
