		public static void UpdateView(this UILegendShowRankPanel self)
		{
			if (self.BaseConfigs.Count <= 0)
			{
				return;
			}
			LegendShowBaseConfig legendShowBaseConfig = self.BaseConfigs[self.StageIndex];
			self._StageText.SetText(legendShowBaseConfig.StageDesc);
			int currentStage = ((Entity)self.ActivityData).GetComponent<LegendShowModule>().GetCurrentStage();
			long startTime = self.ActivityData.StartTime;
			self.IsLock = false;
			if (self.Stage != 0 && currentStage > self.Stage)
			{
				self.StopTime();
				self._TimeText.SetText("阶段已结束");
			}
			else
			{
				if (self.Stage == 0)
				{
					LegendShowBaseConfig legendShowBaseConfig2 = self.BaseConfigs.Last();
					self.TargetTime = startTime + (long)legendShowBaseConfig2.Day * 86400000L;
				}
				else if (currentStage == self.Stage)
				{
					self.TargetTime = startTime + (long)legendShowBaseConfig.Day * 86400000L;
				}
				else
				{
					self.TargetTime = startTime + (long)(legendShowBaseConfig.Day - 1) * 86400000L;
					self.IsLock = true;
				}
				self.StartTime();
			}
			self.ReqRank().Coroutine();
		}

		private static void StartTime(this UILegendShowRankPanel self)
		{
			if (self.TimeId <= 0)
			{
				self.TimeId = self.NewTimer(1000L, self.OnTimeUpdate, repeat: true);
			}
			self.OnTimeUpdate();
		}

		private static void StopTime(this UILegendShowRankPanel self)
		{
			if (self.TimeId > 0)
			{
				self.RemoveTimer(ref self.TimeId);
			}
		}

		private static void OnTimeUpdate(this UILegendShowRankPanel self)
		{
			long num = TimeHelper.Now();
			long num2 = math.abs(self.TargetTime - num);
			TimeSpan timeSpan = TimeSpan.FromSeconds((double)(num2 / 1000));
			string text = ((num2 < 86400000) ? timeSpan.ToString("hh\\:mm\\:ss") : timeSpan.ToString(Language.Get(2, 312)));
			if (self.IsLock)
			{
				self._TimeText.SetText("开启倒计时：\n" + text);
			}
			else
			{
				self._TimeText.SetText("结算倒计时：\n" + text);
			}
		}

