		[UIMethod]
		public static void OnAwake(this UILoginPanel self)
		{
			self._SureBtn.AddClickHandler(self.SureBtn);
			self._AgeBtn.AddClickHandler(self.OnAgeBtnClick);
			self._PanelBg.AddClickHandler(self.OnBgClick);
			self._ChangeServerBtn.AddClickHandler(self.OnServerBtnClick);
			self._Account.GameObject.AddComponent<WXInputFieldAdapter>();
			self._BanhaoText.SetText(AppHelper.GetBanhao());
		}

		[UIMethod]
		public static void OnShow(this UILoginPanel self)
		{
			if (Define.IsEditor)
			{
				self._Newbie.GameObject.GetComponent<SuperToggle>().SetSelectWithoutNotify(true);
			}
			self.RefreshView();
		}

		public static void RefreshView(this UILoginPanel self, bool tryLogin = false)
		{
			LoginComponent component = ((Entity)SceneHelper.DomainScene((Entity)(object)self)).GetComponent<LoginComponent>();
			if (self.Zone == 0)
			{
				int defaultZone = component.GetDefaultZone();
				self.SetSelectServer(defaultZone);
			}
			else
			{
				self.SetSelectServer(self.Zone);
			}
			if (tryLogin && SDK.IsEnable && self.Zone > 0)
			{
				component.EnterGame(self.Zone).Coroutine();
			}
		}

		public static void Login(this UILoginPanel self)
		{
			self._Middle.SetActive(active: true);
			string text = LocalData.GetString("LastLoginAccount");
			self._Account.GameObject.GetComponent<InputField>().text = text;
		}

		public static void SetSelectServer(this UILoginPanel self, int zone)
		{
			LoginComponent component = ((Entity)SceneHelper.DomainScene((Entity)(object)self)).GetComponent<LoginComponent>();
			if (component.ServerInfos == null)
			{
				return;
			}
			ServerInfo valueOrDefault = component.ServerInfos.GetValueOrDefault(zone);
			if (valueOrDefault != null)
			{
				self.Zone = valueOrDefault.Zone;
				self._ServerName.SetText(valueOrDefault.Name);
				for (ServerStatus serverStatus = ServerStatus.Normal; serverStatus < ServerStatus.Max; serverStatus++)
				{
					self._ChangeServerBtn.Find($"State{(int)serverStatus}").SetActive(serverStatus == valueOrDefault.Status);
				}
			}
		}

		private static void OnServerBtnClick(this UILoginPanel self)
		{
			if (!((Entity)SceneHelper.DomainScene((Entity)(object)self)).GetComponent<LoginComponent>().IsLogin())
			{
				LoginHelper.Login(SceneHelper.DomainScene((Entity)(object)self));
			}
			else
			{
				UIManager.Instance.Show<UIServerPanel>().Coroutine();
			}
		}

		public static void OnBgClick(this UILoginPanel self)
		{
			self.IsJumpNewbie = ((Toggle)self._Newbie.GameObject.GetComponent<SuperToggle>()).isOn;
			self._Middle.SetActive(active: false);
			self.OnLogin().Coroutine();
		}

