		public static void OnAgeBtnClick(this UILoginPanel self)
		{
			UIManager.Instance.Show<UIAgeRemindPanel, string>("未成年一天只能玩一个小时").Coroutine();
		}

		public static void SureBtn(this UILoginPanel self)
		{
			string text = self._Account.GameObject.GetComponent<InputField>().text;
			if (string.IsNullOrEmpty(text))
			{
				UIGameMsgHelper.FloatMsg("请输入账号");
				return;
			}
			LoginComponent component = ((Entity)SceneHelper.DomainScene((Entity)(object)self)).GetComponent<LoginComponent>();
			component.Login(new LoginInfo
			{
				Account = text
			});
			component.RequestAccountInfo().Coroutine();
			self._Middle.SetActive(active: false);
		}
	}
