					else
					{
						self2.SetActive(magical.Stage - 1 == magicalStageConfig.Stage);
						self6.SetActive(magicalStageConfig.Stage >= magical.Stage);
						self5.SetText((magicalStageConfig.Stage < magical.Stage) ? skillLevel.Description() : ("<color=#737376>" + skillLevel.Description() + "（领悟后解锁）</color>"));
					}
					self4.SetText(magicalStageConfig.GradeText);
					self3.SetSprite(self.GetBg(magicalStageConfig.Quality)).Coroutine();
				}).Coroutine();
