			else
			{
				self._SkillGroup.SetActive(active: false);
				self.UIObject.Transform.SetSizeWithCurrentAnchors((Axis)1, 210f);
			}
			self._SkillImage.SetSprite(magical.StageConfig.Icon).Coroutine();
			self._ImageSkillDi.SetSprite(magical.StageConfig.IconBg).Coroutine();
			QualityConfig qualityConfig = ConfigSingleton<QualityConfigCategory>.Instance.Get(magical.StageConfig.Quality);
			self._Name.SetText("<color=#" + qualityConfig.Hex + ">" + magical.BaseConfig.Name + "·" + magical.StageConfig.GradeText + "</color>");
			UIHelper.SetText(str: new SkillLevel(magical.StageConfig.SkillId).Description(), self: self._SkillDescText);
