		[UIMethod]
		public static void OnAwake(this UIMailItem self)
		{
			self.UIObject.AddClickHandler(self.OnSelfClick);
			self._RewardList.SpaceX = 10f;
			self._RewardList.Handler.onUpdate += self.OnUpdateCell;
		}

		public static void SetData(this UIMailItem self, MailInfo mailInfo)
		{
			self.MailInfo = mailInfo;
			EmailConfig emailConfig = ConfigSingleton<EmailConfigCategory>.Instance.Get(mailInfo.ConfigId);
			if (emailConfig != null)
			{
				self._TitleText.SetText(emailConfig.Name);
			}
			else
			{
				self._TitleText.SetText(mailInfo.Title);
			}
			self._DateText.SetText(TimeHelper.ToDateTime(mailInfo.SendTime).ToString("yyyy-MM-dd"));
			self._TitleIco.SetSprite(mailInfo.IsRead ? "ui_talk_sign_08" : "ui_talk_sign_07", nativeSize: true).Coroutine();
			self._RedPoint.SetActive(active: false);
			self._RedPoint1.SetActive(active: false);
			if (mailInfo.Items == null)
			{
				self._RewardList.UIObject.SetActive(active: false);
				self._ContentText.SetActive(active: true);
				if (emailConfig != null)
				{
					List<string> texts = mailInfo.Texts;
					if (texts != null && texts.Count > 0)
					{
						object[] array = new object[mailInfo.Texts.Count];
						for (int i = 0; i < mailInfo.Texts.Count; i++)
						{
							array[i] = mailInfo.Texts[i];
						}
						self._ContentText.SetText(string.Format(emailConfig.Desc, array));
					}
					else
					{
						self._ContentText.SetText(emailConfig.Desc);
					}
				}
				else
				{
					self._ContentText.SetText(mailInfo.Content);
				}
				self._RedPoint1.SetActive(!mailInfo.IsGet);
			}
			else
			{
				self._RewardList.UIObject.SetActive(active: true);
				self._ContentText.SetActive(active: false);
				self._RewardList.SetData(mailInfo.Items.Count, updateAll: true, resetPos: true);
				self._RedPoint.SetActive(!mailInfo.IsGet);
			}
			self._GetedImage.SetActive(mailInfo.IsGet);
		}

		private static void OnUpdateCell(this UIMailItem self, UIScrollListCell cell)
		{
			int index = cell.Index;
			UICommonItem component = ((Entity)cell.UIObject).GetComponent<UICommonItem>();
			MailItem mailItem = self.MailInfo.Items[index];
			component.SetItem(mailItem.ConfigId, mailItem.Nums);
		}

		private static void OnSelfClick(this UIMailItem self)
		{
			UIManager.Instance.Show<UIMailInfoPanel, MailInfo>(self.MailInfo).Coroutine();
		}
	}
