	[RedPointHandler(RedPointType.HangupReward)]
	public class HangupRewardRedPointHandler : ARedPointHandler
	{
		public override int GetCount(Scene scene, params int[] parameters)
		{
			if (!((Entity)(object)scene).LocalPlayer().IsFuncOpen(33))
			{
				return 0;
			}
			int nextLevel = ((Entity)((Entity)(object)scene).LocalPlayer()).GetComponent<DJHeroModule>().GetNextLevel();
			int hangupRewardInterval = ConfigSingleton<DJHeroGlobalConfigCategory>.Instance.GetOne().HangupRewardInterval;
			int hangupShowLimit = ConfigSingleton<DJHeroGlobalConfigCategory>.Instance.GetOne().HangupShowLimit;
			int num = hangupRewardInterval * hangupShowLimit;
			Dictionary<int, DJHeroLevelConfig> all = ConfigSingleton<DJHeroLevelConfigCategory>.Instance.GetAll();
			int num2 = 0;
			num2 = ((nextLevel + num <= all.Count) ? (nextLevel - nextLevel % hangupRewardInterval) : (all.Count - num));
			int rewardLevel = ((Entity)((Entity)(object)scene).LocalPlayer()).GetComponent<HangupRewardModule>().GetRewardLevel();
			if (rewardLevel < num2)
			{
				num2 = rewardLevel;
			}
			if (num2 < hangupRewardInterval)
			{
				num2 = hangupRewardInterval;
			}
			for (int i = 0; i <= hangupShowLimit; i++)
			{
				int id = num2 + i * hangupRewardInterval;
				DJHeroLevelConfig dJHeroLevelConfig = ConfigSingleton<DJHeroLevelConfigCategory>.Instance.Get(id);
				if (dJHeroLevelConfig.HangupReward != null && dJHeroLevelConfig.HangupReward.Length != 0 && dJHeroLevelConfig.Id < nextLevel)
				{
					if (dJHeroLevelConfig.Id > nextLevel)
					{
						return 0;
					}
					if (nextLevel > dJHeroLevelConfig.Id && dJHeroLevelConfig.Id > rewardLevel)
					{
						return 1;
					}
				}
			}
			return 0;
		}
	}
