		public static void UpdateView(this UIMainChatPart self)
		{
			ChatInfo lastWorldChatData = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ChatModule>().GetLastWorldChatData();
			if (lastWorldChatData != null)
			{
				if (lastWorldChatData.ChatType != 3)
				{
					string text = lastWorldChatData.Text;
					if (lastWorldChatData.FaceId != 0)
					{
						EmoteConfig emoteConfig = ConfigSingleton<EmoteConfigCategory>.Instance.Get(lastWorldChatData.FaceId);
						text = "[" + emoteConfig.EmoteCode + "]";
					}
					int channel = lastWorldChatData.Channel;
					if (channel == 1 || channel == 8)
					{
						if (lastWorldChatData.ChatType == 8)
						{
							string[] array = lastWorldChatData.Text.Split("|");
							if (array.Length != 0)
							{
								int id = int.Parse(array[0]);
								ChatNoticeConfig chatNoticeConfig = ConfigSingleton<ChatNoticeConfigCategory>.Instance.Get(id);
								if (chatNoticeConfig.PrefabType == 1)
								{
									if (array.Length == 2)
									{
										self._TxtChat.SetText(Language.Format(5, 402, $"{lastWorldChatData.Sender.Name}：{string.Format(chatNoticeConfig.SendMa, array[1])}"));
									}
									else
									{
										self._TxtChat.SetText(Language.Format(5, 402, $"{lastWorldChatData.Sender.Name}：{chatNoticeConfig.SendMa}"));
									}
								}
								if (chatNoticeConfig.PrefabType == 5)
								{
									int id2 = int.Parse(array[1]);
									if (ConfigSingleton<BeastConfigCategory>.Instance.Contain(id2))
									{
										BeastConfig beastConfig = ConfigSingleton<BeastConfigCategory>.Instance.Get(id2);
										self._TxtChat.SetText(Language.Format(5, 402, $"{lastWorldChatData.Sender.Name}：{string.Format(chatNoticeConfig.SendMa, beastConfig.Name)}"));
									}
								}
							}
						}
						else
						{
							self._TxtChat.SetText(Language.Format(5, 402, $"{lastWorldChatData.Sender.Name}：{text}"));
						}
					}
					else if (lastWorldChatData.Channel == 2)
					{
						self._TxtChat.SetText(Language.Format(5, 403, $"{lastWorldChatData.Sender.Name}：{text}"));
					}
					else if (lastWorldChatData.Channel == 4)
					{
						self._TxtChat.SetText(Language.Format(5, 404, $"{text}"));
					}
				}
			}
			else
			{
				self._TxtChat.SetText("");
			}
			self.UpdateRedPoint();
		}

		public static void UpdateRedPoint(this UIMainChatPart self)
		{
			int unReadCountOfPerson = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ChatModule>().UnReadCountOfPerson;
			self._UnReadTips.SetActive(unReadCountOfPerson > 0);
			self._UnReadText.SetText($"{((unReadCountOfPerson > 99) ? 99 : unReadCountOfPerson)}");
			self._UnReadText1.SetActive(unReadCountOfPerson > 99);
		}
	}
