		public static void OnHitFace(this UIMainPanel self, MainUIHitFaceType hitFaceType)
		{
			Player player = ((Entity)(object)self).LocalPlayer();
			if (player == null)
			{
				return;
			}
			switch (hitFaceType)
			{
			case MainUIHitFaceType.OutLineHangup:
			{
				HangupRewardGlobalConfig one = ConfigSingleton<HangupRewardGlobalConfigCategory>.Instance.GetOne();
				long item = ((Entity)player).GetComponent<HangupRewardModule>().GetHangupDuration().Item1;
				bool flag = item >= one.ChangeShowMinute * 60000;
				if (flag && self.IsHangupHitFace != flag && UIManager.Instance.Get<UIRollOverMopPanel>() == null)
				{
					self.IsHangupHitFace = flag;
					UIManager.Instance.Show<UIHangupRewardPanel>().Coroutine();
				}
				break;
			}
			case MainUIHitFaceType.HangupReward:
				if (!self.IsHitFace && player.IsFuncOpen(50))
				{
					self.IsHitFace = true;
					UIManager.Instance.Show<UIHitFacePanel>().Coroutine();
				}
				break;
			case MainUIHitFaceType.HitFace:
				if (UIManager.Instance.Get<UIHitFacePanel>() != null)
				{
					UIManager.Instance.Show<UIHitFacePanel>().Coroutine();
				}
				break;
			}
		}

		public static void RefreshHangupReward(this UIMainPanel self)
		{
			Player player = ((Entity)(object)self).LocalPlayer();
			if (player == null)
			{
				return;
			}
			self._BtnHangup.SetActive(player.IsPreOpen(33) || player.IsFuncOpen(33));
			self.RemoveTimer(ref self.HangupRewardNotifyTimer);
			HangupRewardGlobalConfig one = ConfigSingleton<HangupRewardGlobalConfigCategory>.Instance.GetOne();
			long item = ((Entity)player).GetComponent<HangupRewardModule>().GetHangupDuration().Item1;
			if (item < one.NotifyMinute * 60 * 1000)
			{
				long time = one.NotifyMinute * 60 * 1000 - item;
				self.HangupRewardNotifyTimer = self.NewTimer(time, delegate
				{
					UIGameMsgHelper.FloatMsg(Language.Get(1, 124));
				});
			}
		}

		public static void RefreshView(this UIMainPanel self)
		{
			self._UIMainTopPart.Refresh();
			self._UIMainBottomRightPart.Refresh();
			self._BtnRivers.SetActive(((Entity)(object)self).LocalPlayer().IsPreOpen(21) || ((Entity)(object)self).LocalPlayer().IsFuncOpen(21));
			self._BtnRivers.SetGray(!((Entity)(object)self).LocalPlayer().IsFuncOpen(21));
			self._BtnRivers.SetRedPoint(RedPointType.RiverMap).Coroutine();
			self._BtnDrawer.SetRedPoint(RedPointType.Interactive).Coroutine();
			UIManager.Instance.Get<UIMainBottomPanel>()?.RefreshView();
		}

		public static void RefreshMainTask(this UIMainPanel self)
		{
			self._UIMainTaskPart.Refresh();
		}

		public static void RefreshHangupRed(this UIMainPanel self)
		{
			self._BtnHangup.SetRedPoint(RedPointType.HangupReward).Coroutine();
		}

		public static void StopGuideTime(this UIMainPanel self)
		{
			self.GuideTimeStep = 0;
		}

		public static UIObject GetUIObjectByFuncId(this UIMainPanel self, int funcId)
		{
			if (!ConfigSingleton<FuncConfigCategory>.Instance.Contain(funcId))
			{
				return null;
			}
			switch (funcId)
			{
			case 21:
				return self._BtnRivers;
			case 23:
			{
				UIBattleSkillPart uIBattleSkillPart = UIObject.FindUIObjectOfType<UIBattleSkillPart>();
				if (uIBattleSkillPart != null)
				{
					return uIBattleSkillPart._BtnSkill;
				}
				break;
			}
			}
			int num = funcId;
			if (funcId > 1000)
			{
				num = funcId / 1000;
			}
			FuncConfig funcConfig = ConfigSingleton<FuncConfigCategory>.Instance.Get(num);
			if (funcConfig.Area == 4)
			{
				return self._UIMainBottomRightPart.GetUIObjectByFuncId(funcId);
			}
			if (funcConfig.Area == 1)
			{
				UIMainBottomPanel uIMainBottomPanel = UIManager.Instance.Get<UIMainBottomPanel>();
				if (uIMainBottomPanel != null)
				{
					return uIMainBottomPanel.GetUIObjectByFuncId(num);
				}
			}
			if (funcConfig.Area == 2)
			{
				return self._BtnDrawer;
			}
			if (funcConfig.Area == 3)
			{
				return self._UIMainTopLeftPart.GetUIObjectByFuncId(funcId);
			}
			if (funcConfig.Area == 5)
			{
				return self._UIMainTopRightPart.GetUIObjectByFuncId(funcId);
			}
			return null;
		}
	}
