		}

		public static void OnContentClick(this UIMainTaskPart self)
		{
			long num = TimeHelper.Now();
			if (num - self.TimeCD < 200)
			{
				return;
			}
			self.TimeCD = num;
			TaskConfig taskConfig = ConfigSingleton<TaskConfigCategory>.Instance.Get(self.TaskId);
			TaskModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<TaskModule>();
			if (taskConfig.Type == 7)
			{
				self.OnGuideTaskHandler();
				return;
			}
			if (taskConfig.Type == 2)
			{
				self.OnDailyTaskHandler();
				return;
			}
			TaskData mainTask = component.GetMainTask();
			if (mainTask.Status == 2)
			{
				if (TaskHelper.IsActivityTask((TaskFinishType)taskConfig.FinishType))
				{
					ActivityData activityByType = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<PlayerActivityComponent>().GetActivityByType(TaskHelper.GetActivityType((TaskFinishType)taskConfig.FinishType));
					if (activityByType == null || activityByType.State != ActivityState.Open)
					{
						component.ReqFinishMainTask();
						return;
					}
				}
				if (taskConfig.FinishType == 145)
				{
					UIJumpHelper.To(18, new UIChatShowArgs
					{
						Content = UIChatHelper.GetRandomChatText(((Entity)(object)self).LocalPlayer())
					}).Coroutine();
					return;
				}
				if (taskConfig.FinishType == 102)
				{
					component.ReqFinishMainTask();
				}
				if (taskConfig.FinishType == 115)
				{
					component.ReqGetMainTask();
				}
				UIJumpHelper.To(taskConfig.Goto, taskConfig.JumpParam).Coroutine();
			}
			else if (mainTask.Status == 1)
			{
				component.ReqGetMainTask();
				self.RefreshFinishFX();
			}
			else
			{
				UIJumpHelper.To(17001).Coroutine();
			}
		}

		private static void OnDailyTaskHandler(this UIMainTaskPart self)
		{
			TaskModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<TaskModule>();
			TaskData taskData = component.GetTaskData(self.TaskId);
			TaskConfig taskConfig = ConfigSingleton<TaskConfigCategory>.Instance.Get(taskData.Id);
			if (taskData.Status == 2)
			{
				if (taskConfig.FinishType == 145)
				{
					UIJumpHelper.To(18, new UIChatShowArgs
					{
						Content = UIChatHelper.GetRandomChatText(((Entity)(object)self).LocalPlayer())
					}).Coroutine();
					return;
				}
				if (TaskHelper.IsActivityTask((TaskFinishType)taskConfig.FinishType))
				{
					ActivityData activityByType = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<PlayerActivityComponent>().GetActivityByType(TaskHelper.GetActivityType((TaskFinishType)taskConfig.FinishType));
					if (activityByType == null || activityByType.State != ActivityState.Open)
					{
						component.ReqFinishMainTask();
						return;
					}
				}
				if (taskConfig.FinishType == 102)
				{
					component.ReqFinishMainTask();
				}
				if (taskConfig.FinishType == 115)
				{
					component.ReqGetMainTask();
				}
				else
				{
					UIJumpHelper.To(taskConfig.Goto, taskConfig.JumpParam).Coroutine();
				}
			}
			else if (taskData.Status == 1)
			{
				UIJumpHelper.To(17002).Coroutine();
			}
		}

		private static void OnGuideTaskHandler(this UIMainTaskPart self)
		{
			TaskModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<TaskModule>();
			TaskData taskData = component.GetTaskData(self.TaskId);
			TaskConfig taskConfig = ConfigSingleton<TaskConfigCategory>.Instance.Get(taskData.Id);
			if (taskData.Status == 2)
			{
				if (taskData.IsCanFinish() == 0)
				{
					component.ReqFinishTask(self.TaskId);
