		public static void Refresh(this UIMainTaskPart self)
		{
			if (((Entity)(object)self).LocalPlayer().CheckCond(ConfigSingleton<GlobalConfigCategory>.Instance.GetOne().TaskHideCond))
			{
				self._TaskContent.SetActive(active: false);
				return;
			}
			self._TaskContent.SetActive(active: true);
