		private static void UpdateTask(this UIMainTaskPart self, TaskData taskData)
		{
			//IL_009a: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a1: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a7: Unknown result type (might be due to invalid IL or missing references)
			self.TaskId = taskData.Id;
			TaskConfig taskConfig = ConfigSingleton<TaskConfigCategory>.Instance.Get(taskData.Id);
			if (taskData.Status == 3)
			{
				self._TaskContent.SetActive(active: false);
				return;
			}
			self._TaskContent.SetActive(active: true);
			string text = null;
			if (taskData.Status != 0)
			{
				_ = taskData.Status;
				_ = 2;
			}
			if (taskData.Status == 1 || taskData.Status == 3)
			{
				text = "ui_fx_ranwusaoguang";
			}
			if (self.EffectName != text)
			{
				self._TaskContent.RemoveEffect(self.EffectName);
				self._TaskContent.PlayEffect(text, new Vector2(-144f, 0f));
			}
			self.EffectName = text;
			string arg = ((taskData.Status == 2) ? "#ff3232" : "#5dfa49");
			self._TitleText.SetText(string.Format(taskConfig.Title, Array.Empty<object>()));
			self._DescText.SetText(string.Format(taskConfig.Desc, arg, taskData.Count, taskData.MaxCount));
			if (taskConfig.DropId.GetValueOrDefault(taskData.Stage, 0) == 0)
			{
				self._RewardImage.SetActive(active: false);
				return;
			}
			DropItem[] items = ConfigSingleton<DropShowConfigCategory>.Instance.Get(taskConfig.DropId.GetValueOrDefault(taskData.Stage, 0)).Items;
			if (items != null && items.Length != 0 && items[0] != null)
			{
				self._RewardImage.SetRawTexture($"uitex_icon_item_{UIItemHelper.GetItemIconIdByItemId(items[0].Id)}").Coroutine();
				self._RewardImage.SetActive(active: true);
			}
			else
			{
				self._RewardImage.SetActive(active: false);
			}
		}

