		private static void OnFuncClose(this UIMainTopLeftPart self, int funcId)
		{
			if (!self.IsInitView)
			{
				return;
			}
			for (int i = 0; i < self.BtnInfos.Count; i++)
			{
				if (self.BtnInfos[i].type == UITabIdType.Func && self.BtnInfos[i].id == funcId)
				{
					self.BtnInfos.RemoveAt(i);
					break;
				}
			}
			self.SortBtnAndShow();
		}

		private static void OnFuncOpen(this UIMainTopLeftPart self, int funcId)
		{
			if (!self.IsInitView)
			{
				return;
			}
			FuncConfig funcConfig = ConfigSingleton<FuncConfigCategory>.Instance.Get(funcId);
			for (int i = 0; i < self.BtnInfos.Count; i++)
			{
				if (self.BtnInfos[i].type == UITabIdType.Func && self.BtnInfos[i].id == funcId)
				{
					self.BtnInfos.RemoveAt(i);
					break;
				}
			}
			self.BtnInfos.Add(new TopBtnInfo
			{
				id = funcId,
				type = UITabIdType.Func,
				IsAlwaysOn = funcConfig.AlwaysOn
			});
			self.SortBtnAndShow();
		}

		private static void OnCellUpdate(this UIMainTopLeftPart self, UIScrollListCell cell)
		{
			int index = cell.Index;
			UIObject uIObject = cell.UIObject;
			if (index < self.BtnInfos.Count)
			{
				((Entity)uIObject).GetComponent<UIMainTopLeftBtnItem>().SetData(self.BtnInfos[index]);
			}
		}

		private static void OnCellUpdate2(this UIMainTopLeftPart self, UIScrollListCell cell)
		{
			int num = cell.Index + 5;
			UIObject uIObject = cell.UIObject;
			if (num < self.BtnInfos.Count)
			{
				((Entity)uIObject).GetComponent<UIMainTopLeftBtnItem>().SetData(self.BtnInfos[num]);
			}
		}

		public static void RefreshView(this UIMainTopLeftPart self)
		{
			Player player = ((Entity)(object)self).LocalPlayer();
			if (player == null)
			{
				return;
			}
			List<int> areaFuncList = ((Entity)player).GetComponent<FuncModule>().GetAreaFuncList(FuncArea.TopLeft, checkOpen: true);
			self.BtnInfos.Clear();
			PlayerActivityComponent component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<PlayerActivityComponent>();
			foreach (int item in areaFuncList)
			{
				if ((item != 53 || (component != null && component.GetAllActivity(ActivityCenterType.ActivitySelectGift).Count != 0)) && (item != 52 || (component != null && component.GetAllActivity(ActivityCenterType.WonderfulCenter).Count != 0)))
				{
					FuncConfig funcConfig = ConfigSingleton<FuncConfigCategory>.Instance.Get(item);
					self.BtnInfos.Add(new TopBtnInfo
					{
						id = item,
						type = UITabIdType.Func,
						IsAlwaysOn = funcConfig.AlwaysOn
					});
				}
			}
			if (component != null)
			{
				foreach (ActivityData item2 in component.GetAllActivity(ActivityCenterType.MainPanel))
				{
					self.BtnInfos.Add(new TopBtnInfo
					{
						id = item2.ActivityId,
						type = UITabIdType.Activity,
						IsAlwaysOn = item2.AlwaysOn
					});
				}
			}
			self.SortBtnAndShow();
			self.IsInitView = true;
		}

		public static UIObject GetUIObjectByFuncId(this UIMainTopLeftPart self, int funcId)
		{
			if (!self.FuncIdToUIObject.TryGetValue(funcId, out var value))
			{
				return null;
			}
			return value;
		}
	}
