		private static void SortBtnAndShow(this UIMainTopRightPart self)
		{
			self.BtnInfos.Sort(delegate(TopBtnInfo a, TopBtnInfo b)
			{
				int num2 = 0;
				int value = 0;
				if (a.type == UITabIdType.Func)
				{
					num2 = ConfigSingleton<FuncConfigCategory>.Instance.Get(a.id).Sort;
				}
				else if (a.type == UITabIdType.Activity)
				{
					num2 = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), a.id).Sort;
				}
				if (b.type == UITabIdType.Func)
				{
					value = ConfigSingleton<FuncConfigCategory>.Instance.Get(b.id).Sort;
				}
				else if (b.type == UITabIdType.Activity)
				{
					value = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), b.id).Sort;
				}
				return num2.CompareTo(value);
			});
			if (!self.IsExpand)
			{
				int mainPanelShowCount = ConfigSingleton<GlobalConfigCategory>.Instance.GetOne().MainPanelShowCount;
				int num = self.BtnInfos.Count((TopBtnInfo x) => x.IsAlwaysOn);
				if (num < mainPanelShowCount)
				{
					List<TopBtnInfo> list = self.BtnInfos.Where((TopBtnInfo x) => x.IsAlwaysOn).ToList();
					list.AddRange(self.BtnInfos.Where((TopBtnInfo x) => !x.IsAlwaysOn).Take(mainPanelShowCount - num));
					self.BtnInfos = list;
				}
				else
				{
					self.BtnInfos.RemoveAll((TopBtnInfo x) => !x.IsAlwaysOn);
				}
			}
			if (self.BtnInfos.Count >= 5)
			{
				self._UIScrollList.SetData(5);
				self._UIScrollList2.SetData(self.BtnInfos.Count - 5);
				self._UIScrollList2.UIObject.SetActive(active: true);
			}
			else
			{
				self._UIScrollList.SetData(self.BtnInfos.Count);
				self._UIScrollList2.SetData(0);
				self._UIScrollList2.UIObject.SetActive(active: false);
			}
		}

