			self.UIObject.SetActive(active: true);
			self._Content.SetActive(active: true);
			self.CurrentConfigId = configId;
			self._Item.SetItem(configId, 1L);
			self._NameText.SetText(UIItemHelper.GetItemNameWithColor(configId));
			if (ItemHelper.CheckEquipConfigContainKey(configId))
			{
				self._TakeOnText.SetText("穿戴");
				self._Arow.SetActive(active: true);
			}
			else
			{
				self._TakeOnText.SetText("使用");
				self._Arow.SetActive(active: false);
			}
			self.TotalTime = 3;
			self.RemoveTimer(ref self.CountDownTimer);
			self.CountDownTimer = self.NewTimer(1000L, self.CountDown, repeat: true);
			self.CountDown();
		}

		private static void CountDown(this UINewEquipGetBar self)
		{
			self._TimeText.SetText($"{self.TotalTime}s后关闭");
			self.TotalTime--;
			if (self.TotalTime < 0)
			{
				self.RemoveTimer(ref self.CountDownTimer);
				self.ShowNext();
			}
		}

