		public static void OnPlayEffect(this UIMusicMovementFullPanel self, int configId)
		{
			MusicMovementRewardConfig musicMovementRewardConfig = ConfigSingleton<MusicMovementRewardConfigCategory>.Instance.Get(configId);
			if (musicMovementRewardConfig == null)
			{
				Debug.Log((object)"没有找到 MusicMovementRewardConfig");
				return;
			}
			Dictionary<int, MusicMovementActConfig> dictionary = ConfigSingleton<MusicMovementActConfigCategory>.Instance.GetDictionary(musicMovementRewardConfig.ActId);
			if (dictionary == null)
			{
				Log.Error("没有找到 MusicMovementActConfig");
				return;
			}
			if (!dictionary.ContainsKey(musicMovementRewardConfig.MusicId))
			{
				Log.Error("没有找到 MusicMovementActConfig");
				return;
			}
			Dictionary<int, MusicMovementCardConfig> dictionary2 = ConfigSingleton<MusicMovementCardConfigCategory>.Instance.GetDictionary(self.ActId);
			if (dictionary2 == null)
			{
				Log.Error("没有配 MusicMovementCardConfig？");
				return;
			}
			ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId);
			if (activityData == null)
			{
				Log.Error("没有找到 activityData");
				return;
			}
			if (((Entity)activityData).GetComponent<MusicMovementModule>() == null)
			{
				Log.Error("没有找到 MusicMovementModule");
				return;
			}
			List<int> list = new List<int>();
			if (musicMovementRewardConfig.Type == 1)
			{
				int num = dictionary[musicMovementRewardConfig.MusicId].Count;
				int num2 = musicMovementRewardConfig.Tap[0];
				foreach (MusicMovementCardConfig value in dictionary2.Values)
				{
					if (value.MusicId == musicMovementRewardConfig.MusicId && value.ActId == musicMovementRewardConfig.ActId && value.Index == num2)
					{
						list.Add(value.Id);
						num2++;
						num--;
					}
					if (num == 0)
					{
						break;
					}
				}
			}
			if (musicMovementRewardConfig.Type == 2)
			{
				int count = dictionary[musicMovementRewardConfig.MusicId].Count;
				int num3 = dictionary[musicMovementRewardConfig.MusicId].All / dictionary[musicMovementRewardConfig.MusicId].Count;
				int num4 = musicMovementRewardConfig.Tap[0];
				foreach (MusicMovementCardConfig value2 in dictionary2.Values)
				{
					if (value2.MusicId == musicMovementRewardConfig.MusicId && value2.ActId == musicMovementRewardConfig.ActId && value2.Index == num4)
					{
						list.Add(value2.Id);
						num3--;
						num4 += count;
					}
					if (num3 == 0)
					{
						break;
					}
				}
			}
			if (list.Count <= 0)
			{
				return;
			}
			for (int i = 0; i < self._MainList.Count; i++)
			{
				UIScrollListCell cell = self._MainList.GetCell(i);
				if (cell != null)
				{
					UIMusicMovementCard component = ((Entity)cell.UIObject).GetComponent<UIMusicMovementCard>();
					if (list.Contains(component.GetConfigId()))
					{
						component.OnPlayEff();
					}
				}
			}
		}

