		public static void OnPlayEffect(this UIMusicMovementPanel self, int configId)
		{
			MusicMovementRewardConfig musicMovementRewardConfig = ConfigSingleton<MusicMovementRewardConfigCategory>.Instance.Get(configId);
			if (musicMovementRewardConfig == null)
