				return;
			}
			Dictionary<int, MusicMovementActConfig> dictionary = ConfigSingleton<MusicMovementActConfigCategory>.Instance.GetDictionary(musicMovementRewardConfig.ActId);
			if (dictionary == null)
			{
				Log.Error("没有找到 MusicMovementActConfig");
				return;
			}
			if (!dictionary.ContainsKey(musicMovementRewardConfig.MusicId))
			{
				Log.Error("没有找到 MusicMovementActConfig");
				return;
			}
