			{
				Log.Error("没有找到 activityData");
				return;
			}
			if (((Entity)activityData).GetComponent<MusicMovementModule>() == null)
			{
				Log.Error("没有找到 MusicMovementModule");
				return;
			}
			List<int> list = new List<int>();
			if (musicMovementRewardConfig.Type == 1)
			{
				int num = dictionary[musicMovementRewardConfig.MusicId].Count;
				int num2 = musicMovementRewardConfig.Tap[0];
				foreach (MusicMovementCardConfig value in dictionary2.Values)
				{
					if (value.MusicId == musicMovementRewardConfig.MusicId && value.ActId == musicMovementRewardConfig.ActId && value.Index == num2)
					{
						list.Add(value.Id);
						num2++;
						num--;
					}
					if (num == 0)
					{
						break;
					}
				}
			}
			if (musicMovementRewardConfig.Type == 2)
			{
				int count = dictionary[musicMovementRewardConfig.MusicId].Count;
				int num3 = dictionary[musicMovementRewardConfig.MusicId].All / dictionary[musicMovementRewardConfig.MusicId].Count;
