	[RedPointHandler(RedPointType.OrderWar)]
	public class OrderWarRedPointHandler : ARedPointHandler
	{
		public override int GetCount(Scene scene, params int[] parameters)
		{
			RedPointNode node = RedPointTreeComponent.Instance.GetNode(RedPointNodeType.OrderWar);
			Dictionary<int, OrderWarActivityConfig> all = ConfigSingleton<OrderWarActivityConfigCategory>.Instance.GetAll();
			if (all == null)
			{
				node.SelfCount = 0;
				return 0;
			}
			List<int> list = all.Keys.ToList();
			int num = 0;
			foreach (int item in list)
			{
				ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)scene).LocalPlayer(), item);
				if (activityData == null || activityData.State != ActivityState.Open || !((Entity)(object)scene).LocalPlayer().CheckAllConds(activityData.Condition))
				{
					continue;
				}
				switch (activityData.ActivityType)
				{
				case ActivityType.GrowthFund:
					if (((Entity)activityData).GetComponent<GrowthFundModule>().OnRefshRed())
					{
						num++;
					}
					break;
				case ActivityType.LoginGift:
					if (((Entity)activityData).GetComponent<LoginGiftModule>().OnRefshRed())
					{
						num++;
					}
					break;
				case ActivityType.GrowthFundLevel:
					if (((Entity)activityData).GetComponent<GrowthFundLevelModule>().MainRed())
					{
						num++;
					}
					break;
				case ActivityType.OrderWarHeavenTower:
					if (((Entity)activityData).GetComponent<OrderWarHeavenTowerModule>().OnRefshRed())
					{
						num++;
					}
					break;
				case ActivityType.OrderWarRiverMap:
					if (((Entity)activityData).GetComponent<OrderWarRiverMapModule>().MainRed())
					{
						num++;
					}
					break;
				case ActivityType.OrderWarGodAnimals:
					if (((Entity)activityData).GetComponent<OrderWarGodAnimalsModule>().MainRed())
					{
						num++;
					}
					break;
				case ActivityType.OrderWarCarnival:
					if (((Entity)activityData).GetComponent<OrderWarCarnivalModule>().OnRefshRed())
					{
						num++;
					}
					break;
				}
				if (num > 0)
				{
					node.SelfCount = num;
					return num;
				}
			}
			node.SelfCount = num;
			return num;
		}
	}
