		private static UIGrowthFundRewardOptions OnGetOptions(this UIOrderWarCarnivalPanel self, int level)
		{
			ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId);
			OrderWarCarnivalModule module = ((Entity)activityData).GetComponent<OrderWarCarnivalModule>();
			List<OrderWarHeavenTowerPayConfig> all = ConfigSingleton<OrderWarHeavenTowerPayConfigCategory>.Instance.GetAll(self.ActId);
			OrderWarHeavenTowerPayConfig cfg = null;
			foreach (OrderWarHeavenTowerPayConfig item in all)
			{
				if (item.Level == module.GetGear() * 2 - level)
				{
					cfg = item;
					break;
				}
			}
			UIGrowthFundRewardOptions result = new UIGrowthFundRewardOptions(async delegate
			{
				if (!module.IsBuy(module.GetGear() * 2 - level))
				{
					await ((Entity)(object)self).LocalPlayer().Pay(ProductType.OrderWarCarnival, cfg.Id, self.ActId);
				}
				else if (!module.OnRefshRed())
				{
					UIGameMsgHelper.FloatMsg(Language.Get(4, 795));
				}
				else if (await module.ReqGetReward() == 0)
				{
					UIManager.Instance.Remove(typeof(UIGrowthFundRewardPanel));
				}
			});
			result.ActId = self.ActId;
			result.AllList = ItemList.Create();
			result.CurrentList = ItemList.Create();
			SortedDictionary<int, OrderWarCarnivalConfig> dictionary = ConfigSingleton<OrderWarCarnivalConfigCategory>.Instance.GetDictionary(self.ActId);
			int selectId = self.SelectId;
			foreach (OrderWarCarnivalConfig value in dictionary.Values)
			{
				if (selectId + cfg.Add >= value.Id)
				{
					if (level == 0)
					{
						result.CurrentList.AddRange(value.RechargeItem);
					}
					if (level == 1)
					{
						result.CurrentList.Add(value.JuepinItem);
					}
				}
				if (level == 0)
				{
					result.AllList.AddRange(value.RechargeItem);
				}
				if (level == 1)
				{
					result.AllList.Add(value.JuepinItem);
				}
			}
			result.PayId = cfg.PayId;
			result.Title = activityData.Name;
			result.TipsText1 = Language.Get(2, 279);
			result.TipsText2 = Language.Get(2, 280);
			result.Discount = cfg.Discount;
			result.IsVip = module.IsBuy(module.GetGear() * 2 - level);
			return result;
		}
	}
