		private static UIGrowthFundRewardOptions OnGetOptions(this UIOrderWarHeavenTowerItem self, int level)
		{
			ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId);
			OrderWarHeavenTowerModule module = ((Entity)activityData).GetComponent<OrderWarHeavenTowerModule>();
			List<OrderWarHeavenTowerStagePayConfig> all = ConfigSingleton<OrderWarHeavenTowerStagePayConfigCategory>.Instance.GetAll(self.ActId);
			OrderWarHeavenTowerStagePayConfig cfg = null;
			foreach (OrderWarHeavenTowerStagePayConfig item in all)
			{
				if (item.Gear == module.Stage && item.Level == module.Stage * 2 - level)
				{
					cfg = item;
					break;
				}
			}
			UIGrowthFundRewardOptions result = new UIGrowthFundRewardOptions(async delegate
			{
				if (!module.IsBuy(module.Stage * 2 - level))
				{
					await ((Entity)(object)self).LocalPlayer().Pay(ProductType.OrderWarHeavenTower, cfg.Id, self.ActId);
				}
				else if (!module.OnRefshRed())
				{
					UIGameMsgHelper.FloatMsg(Language.Get(4, 795));
				}
				else if (await module.ReqGetReward() == 0)
				{
					UIManager.Instance.Remove(typeof(UIGrowthFundRewardPanel));
				}
			});
			result.ActId = self.ActId;
			result.AllList = ItemList.Create();
			result.CurrentList = ItemList.Create();
			Dictionary<int, OrderWarHeavenTowerConfig> dictionary = ConfigSingleton<OrderWarHeavenTowerConfigCategory>.Instance.GetDictionary(self.ActId);
			int num = self.SelectId;
			if (self.SelectId == 0)
			{
				foreach (OrderWarHeavenTowerConfig value in dictionary.Values)
				{
					if (value.Gear == module.Stage)
					{
						num = value.Id - 1;
						break;
					}
				}
			}
			foreach (OrderWarHeavenTowerConfig value2 in dictionary.Values)
			{
				if (module.Stage != value2.Gear)
				{
					continue;
				}
				if (num + cfg.Add >= value2.Id)
				{
					if (level == 0)
					{
						result.CurrentList.AddRange(value2.RechargeItem);
					}
					if (level == 1)
					{
						result.CurrentList.Add(value2.JuepinItem);
					}
				}
				if (level == 0)
				{
					result.AllList.AddRange(value2.RechargeItem);
				}
				if (level == 1)
				{
					result.AllList.Add(value2.JuepinItem);
				}
			}
			result.PayId = cfg.PayId;
			result.Title = activityData.Name;
			result.TipsText1 = Language.Get(2, 279);
			result.TipsText2 = Language.Get(2, 280);
			result.Discount = cfg.Discount;
			result.IsVip = module.IsBuy(module.Stage * 2 - level);
			return result;
		}
	}
