			if (flag)
			{
				orderWarRiverMapConfig3 = ConfigSingleton<OrderWarRiverMapConfigCategory>.Instance.Get(id);
			}
			if (orderWarRiverMapConfig2 == null)
			{
				num = ((component.Score >= orderWarRiverMapConfig.Need) ? 0.5f : ((float)component.Score / (float)orderWarRiverMapConfig.Need * 0.5f));
