				{
					num = (float)component.Score / (float)orderWarRiverMapConfig.Need * 0.5f;
					num = ((num > 0.5f) ? 0.5f : num);
				}
			}
			if (orderWarRiverMapConfig3 != null)
			{
				if (component.Score > orderWarRiverMapConfig.Need)
				{
					float num4 = (float)orderWarRiverMapConfig.Need + ((float)orderWarRiverMapConfig3.Need - (float)orderWarRiverMapConfig.Need) / 2f;
					num += (float)component.Score / num4 * 0.5f;
				}
			}
