			if (num < 0.5f)
			{
				self._LevelImg.SetTexture("ui_jj_frame_08").Coroutine();
			}
			if (num >= 0.5f)
			{
				self._LevelImg.SetTexture("ui_jj_frame_06").Coroutine();
			}
			if (num >= 1f)
			{
				self._LevelImg.SetTexture("ui_jj_frame_07").Coroutine();
			}
