			self._SelectItem2.SetCheck(component.Buy && component.GetVipConfigId >= orderWarRiverMapConfig.Id && component.Score >= orderWarRiverMapConfig.Need);
			self._SelectItem1.SetHighlight(component.GetVipConfigId < orderWarRiverMapConfig.Id && component.Score >= orderWarRiverMapConfig.Need);
