		private static UIGrowthFundRewardOptions OnGetOptions(this UIOrderWarRiverMapPanel self)
		{
			OrderWarShowConfig orderWarShowConfig = ConfigSingleton<OrderWarShowConfigCategory>.Instance.Get(self.ActId);
			OrderWarHeavenTowerPayConfig actConfig = ConfigSingleton<OrderWarHeavenTowerPayConfigCategory>.Instance.Get(orderWarShowConfig.Show[0]);
			ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId);
			OrderWarRiverMapModule module = ((Entity)activityData).GetComponent<OrderWarRiverMapModule>();
			UIGrowthFundRewardOptions result = new UIGrowthFundRewardOptions(async delegate
			{
				if (!module.Buy)
				{
					await ((Entity)(object)self).LocalPlayer().Pay(ProductType.OrderWarRiverMap, actConfig.Id, self.ActId);
				}
				else if (!module.MainRed())
				{
					UIGameMsgHelper.FloatMsg(Language.Get(4, 795));
				}
				else if (await module.ReqGetReward() == 0)
				{
					UIManager.Instance.Remove(typeof(UIGrowthFundRewardPanel));
				}
			});
			result.ActId = self.ActId;
			result.AllList = ItemList.Create();
			result.CurrentList = ItemList.Create();
			foreach (OrderWarRiverMapConfig value in ConfigSingleton<OrderWarRiverMapConfigCategory>.Instance.GetDictionary(self.ActId).Values)
			{
				if (self.SelectId >= value.Id)
				{
					result.CurrentList.AddRange(value.Reward);
				}
				result.AllList.AddRange(value.Reward);
			}
			result.PayId = actConfig.PayId;
			result.Title = activityData.Name;
			result.TipsText1 = Language.Get(2, 279);
			result.TipsText2 = Language.Get(2, 280);
			result.Discount = actConfig.Discount;
			result.IsVip = module.Buy;
			return result;
		}
	}
