		public static void OnAwake(this UIOrderWarTaskView self)
		{
			self._List.SpaceY = 13f;
			self._List.Handler.onUpdate += self.OnCellUpdate;
			self._Windows.SetTitle(Language.Get(4, 770));
		}

		[UIMethod]
		public static void OnShow(this UIOrderWarTaskView self, int _actID)
		{
			self.ActId = _actID;
			Dictionary<int, OrderWarTaskConfig> dictionary = ConfigSingleton<OrderWarTaskConfigCategory>.Instance.GetDictionary(_actID);
			if (dictionary == null)
			{
				Debug.LogError((object)"GrowthFundWeekGameplayTaskConfig 没有数据");
				return;
			}
			self.Lists.Clear();
			foreach (OrderWarTaskConfig value in dictionary.Values)
			{
				self.Lists.Add(value.Id);
			}
			self._List.SetData(self.Lists.Count);
		}

		private static void OnCellUpdate(this UIOrderWarTaskView self, UIScrollListCell cell)
		{
			int index = cell.Index;
			if (index < self.Lists.Count)
			{
				((Entity)cell.UIObject).GetComponent<UIOrderWarTaskCard>().SetData(self.Lists[index]);
			}
		}
	}
