			case DayOfWeek.Monday:
				self._NowWeek.SetText("星期一");
				break;
			case DayOfWeek.Tuesday:
				self._NowWeek.SetText("星期二");
				break;
			case DayOfWeek.Wednesday:
				self._NowWeek.SetText("星期三");
				break;
			case DayOfWeek.Thursday:
				self._NowWeek.SetText("星期四");
				break;
			case DayOfWeek.Friday:
				self._NowWeek.SetText("星期五");
				break;
			case DayOfWeek.Saturday:
				self._NowWeek.SetText("星期六");
				break;
			}
