		public static void SetData(this UIOtherHeroCardItem self, HeroInfo info, bool check = false, bool mask = false, bool buttonEvent = false)
		{
			self.HeroInfo = info;
			HeroConfig heroConfig = ConfigSingleton<HeroConfigCategory>.Instance.Get(info.ConfigId);
			self._Job.SetSprite($"ui_herocard_job_{heroConfig.Job}").Coroutine();
			self._Bg.SetTexture($"ui_common_card_bg_small_{heroConfig.HeroQuality}").Coroutine();
			self._JobFrame.SetSprite($"ui_herocard_jobframe_{heroConfig.HeroQuality}").Coroutine();
			self._Fg.SetTexture($"ui_common_card_mask_small_{heroConfig.HeroQuality}").Coroutine();
			int num = (info.Star - 1) / 5;
			foreach (UIObject starObject in self.StarObjects)
			{
				starObject.Find("StarFG").SetSprite($"ui_hero_sign_0{num + 2}", nativeSize: true).Coroutine();
			}
			if (info.Star <= 5)
			{
				for (int i = 0; i < 5; i++)
				{
					UIObject self2 = self.StarObjects[i];
					self2.SetActive(active: true);
					self2.Find("StarBG").SetActive(active: true);
					self2.Find("StarFG").SetActive(info.Star > i);
				}
			}
			else
			{
				for (int j = 0; j < 5; j++)
				{
					int num2 = j + num * 5;
					UIObject self3 = self.StarObjects[j];
					self3.SetActive(info.Star > num2);
					self3.Find("StarBG").SetActive(active: false);
					self3.Find("StarFG").SetActive(active: true);
				}
			}
			self._HeroLevel.SetText(info.Level.ToString());
			self._Icon.SetRawTexture($"uitex_hero_image_{info.ConfigId}").Coroutine();
			self._Check.SetActive(check);
			if (buttonEvent)
			{
				self.UIObject.AddClickHandler(self.ShowHeroInfoPanel);
			}
		}

