		private static void OnAttInfoClick(this UIOtherPersonalInfoPanel self)
		{
			if (self.DressSyncInfos == null)
			{
				return;
			}
			StatList statList = new StatList();
			for (int i = 0; i < self.DressSyncInfos.Count; i++)
			{
				DressSyncInfo dressSyncInfo = self.DressSyncInfos[i];
				FashionPowerConfig fashionPowerConfig = ConfigSingleton<FashionPowerConfigCategory>.Instance.Get(dressSyncInfo.FashionId, dressSyncInfo.Star);
				if (fashionPowerConfig != null && fashionPowerConfig.Stats?.Length > 0)
				{
					statList.AddRange(fashionPowerConfig.Stats);
				}
			}
			UIManager.Instance.Show<UIDressAttBonusInfoPanel, (StatList, List<DressSyncInfo>)>((statList, self.DressSyncInfos)).Coroutine();
		}

		public static void UpdateAttrInfoBtn(this UIOtherPersonalInfoPanel self, List<DressSyncInfo> infos)
		{
			if (infos != null)
			{
				self.DressSyncInfos = infos;
				self._AttInfoBtn.SetActive(active: true);
				string attrInfoBtnIcon = DressHelper.getAttrInfoBtnIcon(infos);
				self._AttInfoBtn.SetTexture(attrInfoBtnIcon, nativeSize: true).Coroutine();
			}
		}
	}
