			var (serverInfo, roleInfo) = self.ServerItemInfos[cell.Index];
			if (roleInfo == null)
			{
				UIServerItem component = ((Entity)cell.UIObject).GetComponent<UIServerItem>();
				component._ServerName.SetText(serverInfo.Name ?? "");
				component._Active.SetActive(cell.IsSelected);
				component._NewSign.SetActive(serverInfo.IsNew);
			}
			else
			{
				UIServerMyItem component2 = ((Entity)cell.UIObject).GetComponent<UIServerMyItem>();
				component2._ServerName.SetText(serverInfo.Name ?? "");
				component2._Active.SetActive(cell.IsSelected);
				component2._PowerNumber.SetText(TextHelper.FormatPower(roleInfo.Power));
				component2._RoleName.SetText(roleInfo.Name);
				component2._NewSign.SetActive(serverInfo.IsNew);
			}
			UIObject uIObject = cell.UIObject;
			for (ServerStatus serverStatus = ServerStatus.Normal; serverStatus < ServerStatus.Max; serverStatus++)
			{
				uIObject.Find($"_Button/State{(int)serverStatus}").SetActive(serverStatus == serverInfo.Status);
			}
		}

		private static string GetServerItemName(this UIServerPanel self, int index)
		{
			if (self.ServerItemInfos[index].Item2 != null)
			{
				return "UIServerMyItem";
			}
			return "UIServerItem";
		}

		private static void OnCloseBtn(this UIServerPanel self)
		{
			UIManager.Instance.Remove(typeof(UIServerPanel));
		}
	}
