		public static void SetInfo(this UISingleDressItem self, DressPrefab dressPrefab)
		{
			//IL_00d7: Unknown result type (might be due to invalid IL or missing references)
			//IL_00dc: Unknown result type (might be due to invalid IL or missing references)
			//IL_00ed: Unknown result type (might be due to invalid IL or missing references)
			_ = self.UIObject.Transform;
			self.UIObject.Transform.SetSizeWithCurrentAnchors((Axis)1, 120f);
			if (ConfigSingleton<DressItemConfigCategory>.Instance.Contain(dressPrefab.Id))
			{
				DressItemConfig dressItemConfig = ConfigSingleton<DressItemConfigCategory>.Instance.Get(dressPrefab.Id);
				int idNum = self.GetIdNum(dressItemConfig.Clothes_type);
				self._Line.SetActive(dressPrefab.index != idNum - 1);
				long skinTimeByID = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<SkinModule>().GetSkinTimeByID(dressPrefab.Id);
				switch (skinTimeByID)
				{
				case -1L:
					self._Time.SetText("永久");
					break;
				default:
				{
					int num = (int)math.ceil((float)(skinTimeByID - TimeHelper.ServerNowSeconds()) / 86400f);
					self._Time.SetText(num + "天");
					break;
				}
				case 0L:
					break;
				}
				Color qualityColor = UIHelper.GetQualityColor(dressItemConfig.Quality);
				((Graphic)self._Name.GameObject.GetComponent<SuperText>()).color = qualityColor;
				self._Name.SetText(dressItemConfig.Clothes_Name);
				self._ItemImage.SetSprite(dressItemConfig.Clothes_Icon).Coroutine();
			}
		}

		public static int GetIdNum(this UISingleDressItem self, int id)
		{
			SkinModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<SkinModule>();
			int result = 0;
			switch ((SkinType)id)
			{
			case SkinType.ChatBg:
				result = component.GetChatBgDic().Count;
				break;
			case SkinType.Cloak:
				result = component.GetCloakDic().Count;
				break;
			case SkinType.Cloth:
				result = component.GetClothDic().Count;
				break;
			case SkinType.Head:
				result = component.GetHeadDic().Count;
				break;
			case SkinType.Weapon:
				result = component.GetWeaponDic().Count;
				break;
			}
			return result;
		}
	}
