		[UIMethod]
		public static void OnShow(this UIPlayPreviewPanel self, int ActivityId)
		{
			self.ActivityId = ActivityId;
			self.Module = ActivityHelper.GetActivityModule<PlayPreviewModule>(((Entity)(object)self).LocalPlayer(), self.ActivityId);
			if (self.Module == null)
			{
				self._UIScrollList.SetData(0);
				self._None.SetActive(active: true);
				return;
			}
			self.IsVoted = self.Module.IsVoted();
			self.voteDic = self.Module.GetVoteList();
			self.CfgList = self.Module.GetVoteCfgList();
			self._UIScrollList.SetData(self.CfgList.Count);
			self._None.SetActive(self.CfgList.Count <= 0);
			self.ShowTimer();
		}

		private static void ShowTimer(this UIPlayPreviewPanel self)
		{
			self.NewTimer(5000L, SendProxy, repeat: true);
			void SendProxy()
			{
				self.Module.RequestPlayPreviewList(((Entity)(object)self).LocalPlayer(), self.ActivityId);
			}
		}

		public static void UpdateView(this UIPlayPreviewPanel self)
		{
			self.voteDic = self.Module.GetVoteList();
			self._UIScrollList.RefreshView();
		}

		public static void UpdateVoteNum(this UIPlayPreviewPanel self)
		{
			self.IsVoted = self.Module.IsVoted();
			self.voteDic = self.Module.GetVoteList();
			self._UIScrollList.RefreshView();
		}

		private static void OnCellUpdate(this UIPlayPreviewPanel self, UIScrollListCell cell)
		{
			int index = cell.Index;
			if (index < self.CfgList.Count)
			{
				PlayPreviewConfig playPreviewConfig = self.CfgList[index];
				if (!self.voteDic.TryGetValue(playPreviewConfig.Id, out var value))
				{
					value = 0;
				}
				((Entity)cell.UIObject).GetComponent<UIPlayPreviewItem>().SetData(self.CfgList[index], value, self.IsVoted, self.ActivityId);
			}
		}
	}
