		public static void GetPracticeGradeAttrListInfo(this UIPracticeGradeSuccessPanel self, StatList statList, int practiceLevel, bool isAddGrade)
		{
			if (practiceLevel == 0)
			{
				practiceLevel = 1;
			}
			PracticeConfig practiceConfig = ConfigSingleton<PracticeConfigCategory>.Instance.Get(practiceLevel);
			if (practiceConfig == null)
			{
				return;
			}
			if (!isAddGrade)
			{
				using StatList statList2 = StatList.Create();
				statList2.AddRange(practiceConfig.GradeAddStats);
				VibesHelper.SetStatZero(statList, statList2);
			}
			else
			{
				statList.AddRange(practiceConfig.GradeAddStats);
			}
			for (int i = 1; i <= practiceLevel; i++)
			{
				PracticeConfig practiceConfig2 = ConfigSingleton<PracticeConfigCategory>.Instance.Get(i);
				Stat[] addStats = practiceConfig2.AddStats;
				foreach (Stat stat in addStats)
				{
					if (statList.isExist(stat.Type))
					{
						statList.Add(new StatStruct
						{
							Type = stat.Type,
							Value = stat.Value * practiceConfig2.StatLevel,
							Scope = stat.Scope
						});
					}
				}
				if (i >= practiceLevel)
				{
					continue;
				}
				addStats = practiceConfig2.GradeAddStats;
				foreach (Stat stat2 in addStats)
				{
					if (statList.isExist(stat2.Type))
					{
						statList.Add(new StatStruct
						{
							Type = stat2.Type,
							Value = stat2.Value,
							Scope = stat2.Scope
						});
					}
				}
			}
		}

