		public static string GetPracticeHtmlName(this UIPracticeGradeSuccessPanel self, int level)
		{
			if (!ConfigSingleton<PracticeConfigCategory>.Instance.Contain(level))
			{
				return "";
			}
			PracticeConfig practiceConfig = ConfigSingleton<PracticeConfigCategory>.Instance.Get(level);
			QualityConfig qualityConfig = ConfigSingleton<QualityConfigCategory>.Instance.Get(practiceConfig.Quality);
			return "<color=#" + qualityConfig.Hex + ">" + practiceConfig.Name + "</color>";
		}

		private static void UpdateView(this UIPracticeGradeSuccessPanel self)
		{
			self._LastName.SetText(self.GetPracticeHtmlName(self.LastPracticeLevel));
			self._CurName.SetText(self.GetPracticeHtmlName(self.CurPracticeLevel));
			using StatList statList = StatList.Create();
			self.GetPracticeGradeAttrListInfo(statList, self.CurPracticeLevel - 1, isAddGrade: false);
			using StatList statList2 = StatList.Create();
			self.GetPracticeGradeAttrListInfo(statList2, self.CurPracticeLevel - 1, isAddGrade: true);
			self.UIObject.DOSequence();
			for (int i = 0; i < 3; i++)
			{
				if (statList2.Count > i && self.UIGradeAttrList.Count > i && self.UIGradeAttrList[i] != null)
				{
					StatStruct statStruct = statList2[i];
					int type = statStruct.Type;
					int curValue = (int)statStruct.Value;
					string name = ConfigSingleton<StatConfigCategory>.Instance.Get(type)?.Desc;
					self.UIGradeAttrList[i].UIObject.SetActive(active: true);
					self.UIGradeAttrList[i].SetAttrAndValueInfo(name, (int)statList[i].Value, curValue);
				}
			}
			self._SkillContent.SetActive(active: false);
			if (ConfigSingleton<PracticeConfigCategory>.Instance.Contain(self.CurPracticeLevel))
			{
				PracticeConfig practiceConfig = ConfigSingleton<PracticeConfigCategory>.Instance.Get(self.CurPracticeLevel);
				if (practiceConfig.AddSkillId != 0)
				{
					self._SkillContent.SetActive(active: true);
					SkillLevel skillLevel = new SkillLevel(practiceConfig.AddSkillId);
					self._SkillLevelText.SetText(Language.Format(2, 224, skillLevel.Level));
					self._SkillIcon.SetRawTexture(skillLevel.Icon()).Coroutine();
				}
			}
		}

