			{
				return (sprite: "ui_common_btn_33", outline: "#952810", text: Language.Format(4, 744, pay.Price / 100), gray: false, show: true);
			}
			ET.ConfigBeans.Item[] daliyAwards = self.Config.DaliyAwards;
			if (daliyAwards != null && daliyAwards.Length > 0)
			{
				if (module.CanGetCardReward(self.Config.Id))
				{
					return (sprite: "ui_common_btn_37", outline: "#3f7745", text: Language.Get(6, 31), gray: false, show: true);
				}
				if (module.CanRenew(self.Config.Id))
				{
					return (sprite: "ui_common_btn_34", outline: "#a7511d", text: Language.Format(6, 76, pay.Price / 100), gray: false, show: true);
				}
				return (sprite: "ui_common_btn_37", outline: "#3f7745", text: Language.Get(6, 77), gray: true, show: true);
			}
			if (module.CanRenew(self.Config.Id))
			{
				return (sprite: "ui_common_btn_34", outline: "#a7511d", text: Language.Format(6, 76, pay.Price / 100), gray: false, show: true);
			}
			return (sprite: "ui_common_btn_33", outline: "#952810", text: "", gray: false, show: false);
		}

