		public static void CalculatePrivilegeCost(Player player, int priceType, int count, ref ItemStruct itemStruct)
		{
			int buyedCount = ((Entity)player).GetComponent<PrivilegeModule>().GetBuyedCount(priceType);
			int num = 0;
			int configId = 0;
			for (int i = 0; i < count; i++)
			{
				PriceConfig priceConfig = ConfigSingleton<PriceConfigCategory>.Instance.Get(priceType, buyedCount + i + 1);
				if (priceConfig.Price != null)
				{
					configId = priceConfig.Price.Id;
					num += priceConfig.Price.Nums;
				}
			}
			itemStruct.ConfigId = configId;
			itemStruct.Nums = num;
		}

		public static string GetPrivilegeMessage(ItemStruct itemStruct, int count, int leftCount)
		{
			string result = "";
			if (itemStruct.ConfigId != 0 && itemStruct.Nums > 0)
			{
				ItemConfig itemConfig = ConfigSingleton<ItemConfigCategory>.Instance.Get(itemStruct.ConfigId);
				result = string.Format(ConfigSingleton<Lang3Category>.Instance.Get(124).Text, itemStruct.Nums, itemConfig.Name, count);
				result = result + "\n" + string.Format(ConfigSingleton<Lang3Category>.Instance.Get(125).Text, leftCount);
			}
			return result;
		}

		public static void BuyCount(Scene scene, PrivilegeType privilegeType, int priceType, Action action = null)
		{
			Player player = ((Entity)(object)scene).LocalPlayer();
			PrivilegeModule component = ((Entity)player).GetComponent<PrivilegeModule>();
			int value = component.GetValue(privilegeType);
			int buyedCount = component.GetBuyedCount(priceType);
			int leftCount = value - buyedCount;
			int count = 0;
			string msg = "";
			ItemStruct itemStruct = default(ItemStruct);
			UICommonHelper.ShowConfirmSliderPanel(new ConfirmSliderPanelOptions
			{
				PriceType = priceType,
				Title = ConfigSingleton<Lang3Category>.Instance.Get(123).Text,
				OkButtonText = ConfigSingleton<Lang3Category>.Instance.Get(121).Text,
				CancelButtonText = ConfigSingleton<Lang3Category>.Instance.Get(122).Text,
				MaxValue = leftCount,
				SliderAction = delegate(IUI ui, int num)
				{
					count = num;
					if (num <= leftCount)
					{
						CalculatePrivilegeCost(player, priceType, num, ref itemStruct);
						msg = GetPrivilegeMessage(itemStruct, num, leftCount);
						UICommonConfirmSliderPanel self = ui as UICommonConfirmSliderPanel;
						self.SetMessage(msg);
						self.SetCost(itemStruct);
					}
					else
					{
						(ui as UICommonConfirmSliderPanel).ShowNotEnough();
					}
				},
				OkAction = delegate
				{
					if (count > leftCount)
					{
						UIGameMsgHelper.FloatMsg("购买次数不足");
					}
					else if (player.CheckItemNumsIsEnough(itemStruct))
					{
						RequestBuy(scene, count, priceType, action).Coroutine();
					}
					else
					{
						UIObtainWayHelper.ShowPanelAsync(itemStruct.ConfigId, (int)itemStruct.Nums).Coroutine();
					}
				}
			});
		}

