		private static void OnDescItemRender(this UIPrivilegeRiverMapPanel self, UIScrollListCell cell)
		{
			UIPrivilegeRiverMapItem component = ((Entity)cell.UIObject).GetComponent<UIPrivilegeRiverMapItem>();
			switch (self.AddCount)
			{
			case 0:
				component.SetData(self.DescConfigs[cell.Index], 3);
				return;
			case 1:
			{
				ET.ConfigBeans.Item[] items = ((self.Config.BuyAwards.Length != 0) ? self.Config.BuyAwards : self.Config.DaliyAwards);
				component.SetData(items, 2);
				return;
			}
			}
			if (cell.Index == 0)
			{
				component.SetData(self.Config.BuyAwards, 1);
			}
			else if (cell.Index == 1)
			{
				component.SetData(self.Config.DaliyAwards, 2);
			}
			else
			{
				component.SetData(self.DescConfigs[cell.Index - self.AddCount], 3);
			}
		}
