		[UIMethod]
		public static void OnAwake(this UIPvPEnterCell self)
		{
			self._Bg.AddClickHandler(self.OnClickItem);
			self._UICommonList.Handler.onCreate += self.OnItemUpdate;
		}

		private static void OnItemUpdate(this UIPvPEnterCell self, UIScrollListCell cell)
		{
			((Entity)cell.UIObject).GetComponent<UICommonItem>().SetItem(self.Config.Reward[cell.Index]);
		}

		public static void SetData(this UIPvPEnterCell self, SportsConfig config)
		{
			self.Config = config;
			if (ConfigSingleton<FuncConfigCategory>.Instance.Contain(config.Play))
			{
				FuncConfig funcConfig = ConfigSingleton<FuncConfigCategory>.Instance.Get(config.Play);
				if (!string.IsNullOrEmpty(funcConfig.RedPointType))
				{
					self._Bg.SetRedPoint(Enum.Parse<RedPointType>(funcConfig.RedPointType)).Coroutine();
				}
			}
			self.UIObject.SetGray(!ConfigSingleton<FuncConfigCategory>.Instance.Contain(config.Play) || !((Entity)(object)self).LocalPlayer().IsFuncOpen(config.Play));
			self.UpdateTimeText();
			UICommonList uICommonList = self._UICommonList;
			ET.ConfigBeans.Item[] reward = config.Reward;
			uICommonList.SetData((reward != null) ? reward.Length : 0);
		}

		private static void UpdateTimeText(this UIPvPEnterCell self)
		{
			if (!ConfigSingleton<FuncConfigCategory>.Instance.Contain(self.Config.Play))
			{
				self._TimeText.SetText("敬请期待");
				return;
			}
			ActivityData activityByType = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<PlayerActivityComponent>().GetActivityByType((ActivityType)self.Config.ActivityType);
			if (activityByType == null)
			{
				self._TimeText.SetText("暂未开启");
			}
			else if (!((Entity)(object)self).LocalPlayer().IsFuncOpen(self.Config.Play))
			{
				self._TimeText.SetText("暂未开启");
				if (activityByType.State == ActivityState.Wait)
				{
					long num = TimeHelper.Now();
					long startTime = activityByType.StartTime;
					if (num <= startTime)
					{
						long num2 = startTime - num;
						TimeSpan timeSpan = TimeSpan.FromSeconds((double)(num2 / 1000));
						string text = ((num2 < 86400000) ? timeSpan.ToString() : timeSpan.ToString("d'天 'hh\\:mm\\:ss"));
						self._TimeText.SetText(string.Format("<color=#FF0000>" + Language.Format(2, 654, text) + "</color>", Array.Empty<object>()));
					}
				}
			}
			else
			{
				string countDownText = UIActivityHelper.GetCountDownText(activityByType);
				self._TimeText.SetText(countDownText);
			}
		}

		private static void OnClickItem(this UIPvPEnterCell self)
		{
			if (!ConfigSingleton<FuncConfigCategory>.Instance.Contain(self.Config.Play))
			{
				UIGameMsgHelper.FloatMsg("敬请期待");
			}
			else if (!((Entity)(object)self).LocalPlayer().IsFuncOpen(self.Config.Play))
			{
				UIGameMsgHelper.FloatMsg(((Entity)(object)self).LocalPlayer().GetCondText(self.Config.Play));
			}
			else
			{
				UIJumpHelper.To(self.Config.Play).Coroutine();
			}
		}
	}
