		public static void SetData(this UIPyramidBtn self, int index, ActivityData activityData, ET.ConfigBeans.Item item, Action<int> callback = null, bool showCostRatio = false)
		{
			self.ActivityData = activityData;
			self.Callback = callback;
			self.Item = item;
			self.Count = ((index == 0) ? 1 : 10);
			bool num = index == 0;
			string spriteName = (num ? "ui_ck_btn_02" : "ui_ck_btn_01");
			string text = (num ? "#316aaf" : "#b15c1e");
			self._BtnRaffle.SetSprite(spriteName).Coroutine();
			self._TxtType.SetText("<color=" + text + ">" + Language.Format(3, 261, StringHelper.NumToCN((index == 0) ? 1 : 10)) + "</color>");
			self._TxtNum.SetText("x" + UIItemHelper.ItemNumsFormat((index == 0) ? 1 : 10));
			SetCostDisplay(self, showCostRatio);
			if (index == 0)
			{
				SetFreeCountdown(self);
			}
		}

		private static void SetCostDisplay(UIPyramidBtn self, bool showCostRatio)
		{
			if (((Entity)self.ActivityData).GetComponent<PyramidRepeatModule>().IsFreeRaffle && self.Count == 1)
			{
				self._GoCost.SetActive(active: false);
				self._TxtType.SetText("<color=#316aaf>" + Language.Get(3, 262) + "</color>");
				return;
			}
			self._GoCost.SetActive(active: true);
			ItemModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>();
			self._ImgIcon.SetRawTexture($"uitex_icon_item_{UIItemHelper.GetItemIconIdByItemId(self.Item.Id)}", nativeSize: true).Coroutine();
			if (showCostRatio)
			{
				long itemNumsByItemId = component.GetItemNumsByItemId(self.Item.Id);
				int nums = self.Item.Nums;
				string text = ((itemNumsByItemId >= nums) ? "#0db64d" : "#e73333");
				self._TxtNum.SetText("<color=" + text + ">" + UIItemHelper.ItemNumsFormat(itemNumsByItemId) + "</color>/" + UIItemHelper.ItemNumsFormat(nums));
			}
			else
			{
				self._TxtNum.SetText("x" + UIItemHelper.ItemNumsFormat(self.Item.Nums));
			}
		}

		private static void SetFreeCountdown(UIPyramidBtn self)
		{
			self.RemoveTimer(ref self.FreeCountTimer);
			self.LeftTime = TimeHelper.BeginTimeOfDay(TimeHelper.Now(), 18000000L) + 86400000 - TimeHelper.Now();
			if (self.LeftTime > 0)
			{
				PyramidRepeatModule component = ((Entity)self.ActivityData).GetComponent<PyramidRepeatModule>();
				self._Time.SetActive(!component.IsFreeRaffle);
				self.UpdateFreeCountdown(isInit: true);
				self.FreeCountTimer = self.NewTimer(1000L, delegate
				{
					self.UpdateFreeCountdown();
				}, repeat: true);
			}
		}

		private static void UpdateFreeCountdown(this UIPyramidBtn self, bool isInit = false)
		{
			self.LeftTime -= 1000L;
			if (self.LeftTime <= 0)
			{
				self.RemoveTimer(ref self.FreeCountTimer);
				self._Time.SetActive(active: false);
				self._GoCost.SetActive(active: false);
				self._TxtType.SetText("<color=#316AAF>" + Language.Get(6, 33) + "</color>");
				if (!isInit)
				{
					self.SetRedPoint().Coroutine();
				}
			}
			else
			{
				self._TxtTime.SetText(Language.Format(6, 34, TextHelper.TimeFormatHourMinSec(self.LeftTime)) ?? "");
			}
		}

