			self._Money.SetData(new int[1] { all[0].CostItem[0].Id });
			self._UITimeCountDownBox.SetActivity(self.ActivityData, 86400000L);
			self.PyramidGiftConfig = ConfigSingleton<PyramidGiftConfigCategory>.Instance.GetAll(self.ActivityData.ActivityId);
			self._FrameBg.SetRawTexture(all[0].GiftBgImg).Coroutine();
			self._BannerBg.SetRawTexture(all[0].GiftBanner, nativeSize: true).Coroutine();
			self._TtileImage.SetRawTexture(all[0].GiftTitle, nativeSize: true).Coroutine();
