		public static void RefreshData(this UIPyramidRepeatGiftPanel self)
		{
			PyramidRepeatModule component = ((Entity)self.ActivityData).GetComponent<PyramidRepeatModule>();
			List<PyramidGiftConfig> list = new List<PyramidGiftConfig>();
			foreach (PyramidGiftConfig item in self.PyramidGiftConfig)
			{
				bool valueOrDefault = component.GiftGetStateDict.GetValueOrDefault(item.Id);
				int valueOrDefault2 = component.GiftBuyNumDict.GetValueOrDefault(item.Id);
				if (!valueOrDefault && valueOrDefault2 >= item.MaxBuyCount)
				{
					list.Add(item);
				}
			}
			if (list.Count != 0)
			{
				foreach (PyramidGiftConfig item2 in list)
				{
					self.PyramidGiftConfig.Remove(item2);
				}
				list.Sort((PyramidGiftConfig x, PyramidGiftConfig y) => x.MaxBuyCount.CompareTo(y.MaxBuyCount));
				self.PyramidGiftConfig.AddRange(list);
			}
			self._ObtainList.SetData(self.PyramidGiftConfig.Count);
			RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.Activity, self.ActId, 1);
		}

