		private static void OnTitleButtonClick(this UIPyramidRepeatInfoPanel self, int index)
		{
			foreach (var (num2, self2) in self.TitleButton)
			{
				self2.Find("_ClickBg").SetActive(index == num2);
				self2.Find("_NormalBg").SetActive(index != num2);
			}
			self._RuleButtonDesText.SetText(Language.Format(3, 266, index + 1));
			PyramidRoundConfig roundConfig = ConfigSingleton<PyramidRoundConfigCategory>.Instance.Get(index + 1);
			int floorStartIndex = 0;
			foreach (PyramidRoundConfig pyramidRoundConfig in self.PyramidRoundConfigs)
			{
				if (pyramidRoundConfig.FloorId < index + 1)
				{
					floorStartIndex += pyramidRoundConfig.RaffleItems.Length;
				}
			}
			self.TrtInfoItems?.Clear();
			self._UIThreeRealmsTreasureInfoItem.UIObject.CloneAll(roundConfig.RaffleItems.Length, 1, delegate(int i, UIObject uiObject)
			{
				floorStartIndex++;
				UIThreeRealmsTreasureInfoItem component = ((Entity)uiObject).GetComponent<UIThreeRealmsTreasureInfoItem>();
				self.TrtInfoItems.Add(i, component);
				if (i < roundConfig.RaffleItems.Length)
				{
					component.SetPyramidData(roundConfig.RaffleItems[i], i, self.ActivityData, floorStartIndex);
				}
				component.UIObject.SetActive(i < roundConfig.RaffleItems.Length);
			}).Coroutine();
		}

		public static string GetRuleInfoButtonTitle(this UIPyramidRepeatInfoPanel self, int index)
		{
