			switch (index)
			{
			case 1:
				result = "壹";
				break;
			case 2:
				result = "贰";
				break;
			case 3:
				result = "叁";
				break;
			case 4:
				result = "肆";
				break;
			case 5:
				result = "伍";
				break;
			case 6:
				result = "陆";
				break;
			}
			return result;
		}
	}
