		public static void UpdateScore(this UIPyramidRepeatPanel self)
		{
			PyramidRepeatModule component = ((Entity)self.ActivityData).GetComponent<PyramidRepeatModule>();
			self._ScoreText.SetText($"{component.AllRound + 1}");
			int allRound = component.AllRound;
			int num = 0;
			foreach (var (index, uIObject2) in self.RoundRewardUIObjectDict)
			{
				((Entity)uIObject2).GetComponent<UIPyramidRepeatRoundReardItem>().SetData(self.ActivityData, self.RoundRewardConfigs[index]);
			}
			for (int i = 0; i < self.RoundRewardConfigs.Count; i++)
			{
				if (allRound >= self.RoundRewardConfigs[i].Round)
				{
					num++;
				}
			}
			int count = self.RoundRewardConfigs.Count;
			float num3 = (float)num * 1f / (float)count;
			float num4 = 0f;
			if (num < self.RoundRewardConfigs.Count)
			{
				int num5 = 0;
				if (num == 0)
				{
					num5 = self.RoundRewardConfigs[num].Round;
					num4 = (float)allRound * 1f / (float)num5 / (float)count;
				}
				else
				{
					num5 = self.RoundRewardConfigs[num].Round - self.RoundRewardConfigs[num - 1].Round;
					num4 = (float)(allRound - self.RoundRewardConfigs[num - 1].Round) * 1f / (float)num5 / (float)count;
				}
			}
			((Slider)self._ScoreProgress.GameObject.GetComponent<SuperSlider>()).value = num3 + num4;
		}

