		private static void SetRewardList(this UIGiftBuyItemPanel self)
		{
			List<ET.ConfigBeans.Item> list = new List<ET.ConfigBeans.Item>();
			for (int i = 0; i < self.CurBuyNums; i++)
			{
				ET.ConfigBeans.Item[] rewadItems = self.RaffleGiftConfig.RewadItems;
				foreach (ET.ConfigBeans.Item item in rewadItems)
				{
					list.Add(item);
				}
			}
			IOrderedEnumerable<ET.ConfigBeans.Item> orderedEnumerable = from o in list
				orderby ItemHelper.GetItemQualityByItemId(o.Id) descending, o.Id
				select o;
			int num = 0;
			ET.ConfigBeans.Item[] array = new ET.ConfigBeans.Item[orderedEnumerable.Count()];
			foreach (ET.ConfigBeans.Item item2 in orderedEnumerable)
			{
				array[num] = item2;
				num++;
			}
			using ItemList itemList = ItemList.Create();
			itemList.AddRange(array);
			self._RewardList.SetData(itemList);
		}

		private static void SetNums(this UIGiftBuyItemPanel self, int nums)
		{
			self.CurBuyNums = nums;
			self._Slider.GameObject.GetComponent<Slider>().value = nums;
			self.UpdateMoney();
		}

		private static void SubSliderValue(this UIGiftBuyItemPanel self)
		{
			if (self.CurBuyNums > 1)
			{
				self.SetNums(self.CurBuyNums - 1);
			}
		}

		private static void AddSliderValue(this UIGiftBuyItemPanel self)
		{
			if (self.CurBuyNums < self.MaxBuyNums)
			{
				self.SetNums(self.CurBuyNums + 1);
			}
		}

		public static void SetChangeValueButtonImage(this UIGiftBuyItemPanel self)
		{
			if (self.MaxBuyNums == 1)
			{
				self._SubButton.SetSprite("ui_bag_btn_06").Coroutine();
				self._AddButton.SetSprite("ui_bag_btn_06").Coroutine();
			}
			else if (self.CurBuyNums <= 1)
			{
				self._SubButton.SetSprite("ui_bag_btn_06").Coroutine();
				self._AddButton.SetSprite("ui_bag_btn_07").Coroutine();
			}
			else if (self.CurBuyNums >= self.MaxBuyNums)
			{
				self._SubButton.SetSprite("ui_bag_btn_07").Coroutine();
				self._AddButton.SetSprite("ui_bag_btn_06").Coroutine();
			}
			else
			{
				self._SubButton.SetSprite("ui_bag_btn_07").Coroutine();
				self._AddButton.SetSprite("ui_bag_btn_07").Coroutine();
			}
		}

		public static void OnSlideValueChange(this UIGiftBuyItemPanel self, float value)
		{
			if (((Component)self._Slider.Transform).GetComponent<Slider>().value < 1f)
			{
				self.SetNums(1);
				return;
			}
			self.CurBuyNums = (int)math.ceil(value);
			self.SetNums(self.CurBuyNums);
			self._ItemNumber.SetText(self.CurBuyNums.ToString());
			self.SetChangeValueButtonImage();
			self.UpdateMoney();
		}

