		public static void UpdateMoney(this UIGiftBuyItemPanel self)
		{
			ItemModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>();
			if (self.RaffleGiftConfig.Type == 1)
			{
				int num = self.RaffleGiftConfig.GiftPrice.Nums * self.CurBuyNums;
				bool flag = component.CheckItemNumsIsEnough(self.RaffleGiftConfig.GiftPrice.Id, num);
				self._MoneyNumsText.SetText(flag ? num.ToString() : $"<color=#de0008>{num}</color>");
				((Behaviour)self._MoneyNumsText.GameObject.GetComponent<SuperOutline>()).enabled = flag;
				self._UICommonMoneyPart.SetData(new int[1] { self.RaffleGiftConfig.GiftPrice.Id });
			}
			else if (self.RaffleGiftConfig.Type == 2)
			{
				PayConfig payConfig = ConfigSingleton<PayConfigCategory>.Instance.Get(self.RaffleGiftConfig.PayId);
				self._MoneyNumsText.SetText(Language.Format(4, 744, payConfig.Price / 100 * self.CurBuyNums));
			}
			self.SetRewardList();
		}

		public static void UpdateSlider(this UIGiftBuyItemPanel self, int oldCurBuyNums)
		{
			self.CurBuyNums = oldCurBuyNums;
			int num = 0;
			int num2 = 0;
			int raffleGiftBuyNum = self.Raffle.GetRaffleGiftBuyNum(self.RaffleGiftConfig.Id);
			if (raffleGiftBuyNum >= self.RaffleGiftConfig.BuyCountLimit)
			{
				self.OnCloseButtonClick();
				return;
			}
			if (self.RaffleGiftConfig.Type == 1)
			{
				num = (int)((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().GetItemNumsByItemId(self.RaffleGiftConfig.GiftPrice.Id);
				num2 = ((num != 0) ? (num / self.RaffleGiftConfig.GiftPrice.Nums) : 0);
				if (num2 > self.RaffleGiftConfig.BuyCountLimit - raffleGiftBuyNum)
				{
					self.MaxBuyNums = self.RaffleGiftConfig.BuyCountLimit - raffleGiftBuyNum;
				}
				else
				{
					self.MaxBuyNums = num2;
				}
			}
			if (self.RaffleGiftConfig.Type == 2)
			{
				self.MaxBuyNums = self.RaffleGiftConfig.BuyCountLimit - raffleGiftBuyNum;
			}
			if (self.MaxBuyNums == 0)
			{
				self.MaxBuyNums = 1;
			}
			Slider component = self._Slider.GameObject.GetComponent<Slider>();
			component.minValue = 0f;
			component.maxValue = self.MaxBuyNums;
			self.SetNums(self.CurBuyNums);
			self.SetRewardList();
		}

		private static void OnCloseButtonClick(this UIGiftBuyItemPanel self)
		{
			UIManager.Instance.Remove(typeof(UIGiftBuyItemPanel));
		}
