	public static class UIGiftHelper
	{
		public static void ShowGiftBuyPanel(Raffle raffle, ProductType productType, int goodsId, Action<int, int> callback = null)
		{
			if (productType == ProductType.RaffleGift)
			{
				UIManager.Instance.Show<UIGiftBuyItemPanel, (Raffle, ProductType, int, Action<int, int>)>((raffle, productType, goodsId, callback)).Coroutine();
			}
		}

		public static void ShowGemStoneGiftBuyPanel(int ActId, ProductType productType, int goodsId, Action<int, int> callback = null)
		{
			if (productType == ProductType.GemStonePlanGift)
			{
				UIManager.Instance.Show<UIGemStoneGiftBuyItemPanel, (int, ProductType, int, Action<int, int>)>((ActId, productType, goodsId, callback)).Coroutine();
			}
			if (productType == ProductType.GemStoneThemeGift)
			{
				UIManager.Instance.Show<UIGemStoneThemeGiftBuyItemPanel, (int, ProductType, int, Action<int, int>)>((ActId, productType, goodsId, callback)).Coroutine();
			}
			if (productType == ProductType.ActiveRanking)
			{
				UIManager.Instance.Show<UIActiveRankingGiftCountPopPanel, (int, ProductType, int, Action<int, int>)>((ActId, productType, goodsId, callback)).Coroutine();
			}
			if (productType == ProductType.TreatureHouseGift)
			{
				UIManager.Instance.Show<UITreasureHouseBuyItemPanel, (int, ProductType, int, Action<int, int>)>((ActId, productType, goodsId, callback)).Coroutine();
			}
			if (productType == ProductType.Pyramid)
			{
				UIManager.Instance.Show<UIPyramidRepeatGiftPopPanel, (int, ProductType, int, Action<int, int>)>((ActId, productType, goodsId, callback)).Coroutine();
			}
		}
	}
