		private static void OnClickCost(this UIRaffleBtn self)
		{
			ET.ConfigBeans.Item cost = self.Choose.GetCost();
			UICommonHelper.ShowItemTip(new ItemStruct
			{
				ConfigId = cost.Id,
				Nums = cost.Nums
			});
		}

		public static void SetData(this UIRaffleBtn self, Raffle raffle, RaffleChoose choose, Action<int> callback = null, bool showCostRatio = false)
		{
			self.CallBack = callback;
			self.Raffle = raffle;
			self.Choose = choose;
			RaffleChooseConfig config = choose.Config;
			bool num = config.RaffleNum == 1;
			string spriteName = (num ? "ui_ck_btn_02" : "ui_ck_btn_01");
			string text = (num ? "#316aaf" : "#b15c1e");
			self._BtnRaffle.SetSprite(spriteName).Coroutine();
			self._TxtType.SetText("<color=" + text + ">" + Language.Format(6, 35, StringHelper.NumToCN(config.RaffleNum)) + "</color>");
			if (((Entity)self.Raffle).Id == 4)
			{
				self._TxtType.SetText("<color=" + text + ">" + Language.Format(6, 78, StringHelper.NumToCN(config.RaffleNum)) + "</color>");
			}
			else if (((Entity)self.Raffle).Id == 5)
			{
				self._TxtType.SetText("<color=" + text + ">" + Language.Format(6, 79, StringHelper.NumToCN(config.RaffleNum)) + "</color>");
			}
			self._TxtNum.SetText("x" + UIItemHelper.ItemNumsFormat(config.RaffleNum));
			SetCostDisplay(self, showCostRatio);
			SetFreeCountdown(self);
		}

		private static void SetCostDisplay(UIRaffleBtn self, bool showCostRatio)
		{
			if (self.Choose.IsFree())
			{
				self._GoCost.SetActive(active: false);
				self._TxtType.SetText("<color=#316aaf>" + Language.Get(6, 33) + "</color>");
				if (((Entity)self.Raffle).Id == 4)
				{
					self._TxtType.SetText("<color=#316aaf>" + Language.Get(3, 244) + "</color>");
				}
				else if (((Entity)self.Raffle).Id == 5)
				{
					self._TxtType.SetText("<color=#316aaf>" + Language.Get(3, 245) + "</color>");
				}
				return;
			}
			self._GoCost.SetActive(active: true);
			ItemModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>();
			ET.ConfigBeans.Item cost = self.Choose.GetCost();
			self._ImgIcon.SetRawTexture($"uitex_icon_item_{UIItemHelper.GetItemIconIdByItemId(cost.Id)}", nativeSize: true).Coroutine();
			if (showCostRatio)
			{
				long itemNumsByItemId = component.GetItemNumsByItemId(cost.Id);
				int nums = cost.Nums;
				string text = ((itemNumsByItemId >= nums) ? "#0db64d" : "#e73333");
				self._TxtNum.SetText("<color=" + text + ">" + UIItemHelper.ItemNumsFormat(itemNumsByItemId) + "</color>/" + UIItemHelper.ItemNumsFormat(nums));
			}
			else
			{
				self._TxtNum.SetText("x" + UIItemHelper.ItemNumsFormat(cost.Nums));
			}
		}

		private static void SetFreeCountdown(UIRaffleBtn self)
		{
			self.RemoveTimer(ref self.FreeCountTimer);
			self._Time.SetActive(active: false);
			if (!self.Choose.IsFree() && (self.Choose.IsFree() || self.Choose.Config.RaffleNum != 1))
			{
				return;
			}
			self.LeftTime = self.Raffle.GetFreeCDTime();
			if (self.LeftTime > 0)
			{
				self._Time.SetActive(active: true);
				self.UpdateFreeCountdown(isInit: true);
				self.FreeCountTimer = self.NewTimer(1000L, delegate
				{
					self.UpdateFreeCountdown();
				}, repeat: true);
			}
		}

		private static void UpdateFreeCountdown(this UIRaffleBtn self, bool isInit = false)
		{
			self.LeftTime -= 1000L;
			if (self.LeftTime <= 0)
			{
				self.RemoveTimer(ref self.FreeCountTimer);
				self._Time.SetActive(active: false);
				self._GoCost.SetActive(active: false);
				self._TxtType.SetText("<color=#316AAF>" + Language.Get(6, 33) + "</color>");
				if (!isInit)
				{
					self.SetRedPoint().Coroutine();
				}
			}
			else
			{
				self._Time.SetActive(active: true);
				self._TxtTime.SetText(Language.Format(6, 34, TextHelper.TimeFormatHourMinSec(self.LeftTime)) ?? "");
			}
		}

