		public static bool IsRedCard(this UIRaffleCard self)
		{
			if (!ConfigSingleton<RaffleQuelityConfigCategory>.Instance.Contain(self.RaffleItem.ItemId))
			{
				return false;
			}
			return ConfigSingleton<RaffleQuelityConfigCategory>.Instance.Get(self.RaffleItem.ItemId).Quality >= 6;
		}

		public static NewHeroShowInfo GetNewHeroInfoIfNew(this UIRaffleCard self)
		{
			if (self.RaffleItem.IsNew != 1)
			{
				return null;
			}
			ItemConfig itemConfig = ConfigSingleton<ItemConfigCategory>.Instance.Get(self.RaffleItem.ItemId);
			int num = 0;
			if (itemConfig.UseEff == 7)
			{
				num = itemConfig.UseEffParams[0];
			}
			if (num == 0)
			{
				return null;
			}
			return new NewHeroShowInfo
			{
				HeroId = num,
				IsNew = true
			};
		}

		public static string GetEffectNameByQuality(this UIRaffleCard self)
		{
			ItemConfig itemConfig = ConfigSingleton<ItemConfigCategory>.Instance.Get(self.RaffleItem.ItemId);
			if (!ConfigSingleton<RaffleQuelityConfigCategory>.Instance.Contain(itemConfig.Id))
			{
				Log.Error($"抽卡特效异常，没有配置对应抽卡品质！ -> ItemId = {itemConfig.Id}");
				return "";
			}
			return ConfigSingleton<RaffleQuelityConfigCategory>.Instance.Get(itemConfig.Id).Quality switch
			{
				6 => "hong", 
				5 => "cheng", 
				4 => "zi", 
				_ => "", 
			};
		}

