				self.OnSelectItem = ((Entity)cell.UIObject).GetComponent<UIRaffleExchangeItem>();
			}
		}

		public static void OnClick(this UIRaffleExchangePanel self, UIRaffleExchangeItem item, RaffleExchangeItem exchangeItem)
		{
			if (self.ExchangeItem == exchangeItem)
			{
				UICommonHelper.ShowItemTip(new ItemStruct
				{
					ConfigId = exchangeItem.Id,
					Nums = exchangeItem.Num
				});
				return;
			}
			if (self.OnSelectItem != null)
			{
				self.OnSelectItem.SetSelect();
			}
			self.ExchangeItem = exchangeItem;
			self.OnSelectItem = item;
			self.OnSelectItem.SetSelect(isSelect: true);
			SuperSlider component = ((Component)self._Slider.Transform).GetComponent<SuperSlider>();
			((Slider)component).maxValue = self.GetMaxExchangeNum();
			self.UpdateExchangeNum((int)((Slider)component).maxValue);
		}

		public static void SetExchangeInfo(this UIRaffleExchangePanel self)
		{
			if (self.ExchangeItem != null)
			{
				((InputField)((Component)self._InputNum.Transform).GetComponent<SuperInputField>()).SetTextWithoutNotify(self.ExchangeNum.ToString());
				self._BtnSub.SetSprite((self.ExchangeNum == 1) ? "ui_bag_btn_06" : "ui_bag_btn_07").Coroutine();
				self._BtnAdd.SetSprite((self.ExchangeNum == 99) ? "ui_bag_btn_06" : "ui_bag_btn_07").Coroutine();
				self.IsActivePrivilege = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<PrivilegeModule>().GetValue(PrivilegeType.RaffleExchange) > 0;
				self._TxtPrivilege.SetActive(!self.IsActivePrivilege);
				self._TxtPrivilege.SetText(Language.Get(6, 38));
				self._GoSlider.SetActive(active: false);
				self._BtnBuy.Find("Text").SetText(self.IsActivePrivilege ? Language.Get(6, 4205) : Language.Get(6, 4204));
				long score = self.Raffle.GetScore();
				self._RawIcon.SetRawTexture($"uitex_icon_item_{UIItemHelper.GetItemIconIdByItemId(self.ExchangeItem.Cost.Id)}").Coroutine();
				self.ExchangeNum = 1;
				int num = self.ExchangeItem.Cost.Nums * self.ExchangeNum;
				string arg = ((score >= num) ? "#0db64d" : "#e73333");
				self._TxtScore.SetText($"<color=#54505e><color={arg}>{score}</color>/{num}</color>");
				self._BtnBuy.SetGray(score < num);
				self._UIHeroCardItem.UIObject.SetActive(active: true);
				Hero hero = ((Entity)(object)self).LocalPlayer().GetHero(self.ExchangeItem.Id);
				self._UIHeroCardItem.SetData(new HeroCardInfo
				{
					ConfigId = self.ExchangeItem.Id,
					Star = hero.Star,
					Level = hero.GetLevel()
				});
				self._UIHeroCardItem.SetName();
				self._GoAdd.SetActive(active: false);
			}
		}
	}
