		private static void RefreshView(this UIRaffleGiftPanel self, int GiftDataFuncId)
		{
			foreach (KeyValuePair<int, List<Raffle>> raffle in ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<RaffleModule>().Raffles)
			{
				raffle.Deconstruct(out var _, out var value);
				foreach (Raffle item in value)
				{
					if (item.Config.GiftDataFuncId == GiftDataFuncId)
					{
						self.Raffle = item;
						break;
					}
				}
			}
			self._ZwPersonBg.SetActive(((Entity)self.Raffle).Id == 4 || ((Entity)self.Raffle).Id == 1 || ((Entity)self.Raffle).Id == 2);
			self._TgPersonBg.SetActive(((Entity)self.Raffle).Id == 5);
			self._ZwPersonBg.SetActive(((Entity)self.Raffle).Id == 3);
			if (((Entity)self.Raffle).Id == 4)
			{
				self._ZwPersonBg.SetRawTexture("ui_zw_frame_01", nativeSize: true).Coroutine();
				self._TtileImage.SetRawTexture("ui_zw_front_04").Coroutine();
			}
			else if (((Entity)self.Raffle).Id == 5)
			{
				self._TgPersonBg.SetRawTexture("ui_tg_frame_10", nativeSize: true).Coroutine();
				self._TtileImage.SetRawTexture("ui_tg_front_01").Coroutine();
			}
			else if (((Entity)self.Raffle).Id == 3)
			{
				self._ZwPersonBg.SetRawTexture("ui_ss_sign_18", nativeSize: true).Coroutine();
				self._TtileImage.SetRawTexture("ui_ss_front_03").Coroutine();
			}
			else if (((Entity)self.Raffle).Id == 6)
			{
				self._ZwPersonBg.SetRawTexture("ui_lieh_cj_frame_01", nativeSize: true).Coroutine();
				self._TtileImage.SetRawTexture("ui_lieh_cj_frame_02").Coroutine();
			}
			if (((Entity)self.Raffle).Id == 2 || ((Entity)self.Raffle).Id == 1)
			{
				self._ZwPersonBg.SetRawTexture("ui_ck_frame_22", nativeSize: true).Coroutine();
				self._TtileImage.SetRawTexture("ui_ck_front_10").Coroutine();
			}
			self.RefreshData();
		}

		public static void RefreshData(this UIRaffleGiftPanel self)
		{
			if (self.Raffle == null)
			{
				Log.Info("self Raffle is null");
				return;
			}
			UIObject.FindUIObjectOfType<UIRaffleZhuanWuPanel>()?.RefreshRedPoint();
			UIObject.FindUIObjectOfType<UIRaffleTianGangPanel>()?.RefreshRedPoint();
			UIObject.FindUIObjectOfType<UIRaffleHeroPanel>()?.RefreshRedPoint();
			UIManager.Instance.Get<UIRafflePanel>()?.RefreshView();
			RaffleGiftState raffleGiftState = self.Raffle.GetRaffleGiftState();
			self.GiftConfigs?.Clear();
			int[] giftDataId = self.Raffle.Config.GiftDataId;
			foreach (int id in giftDataId)
			{
				RaffleGiftConfig raffleGiftConfig = ConfigSingleton<RaffleGiftConfigCategory>.Instance.Get(id);
				if (raffleGiftConfig != null)
				{
					self.GiftConfigs.Add(raffleGiftConfig);
				}
			}
			if (raffleGiftState == null)
			{
				if (self.GiftConfigs.Count != 0)
				{
					self._ObtainList.SetData(self.GiftConfigs.Count);
				}
				return;
			}
			List<RaffleGiftConfig> list = new List<RaffleGiftConfig>();
			foreach (RaffleGiftConfig giftConfig in self.GiftConfigs)
			{
				if (raffleGiftState.GiftBuyTimeState != null && raffleGiftState.GiftBuyTimeState.TryGetValue(giftConfig.Id, out var value) && value >= giftConfig.BuyCountLimit && !self.Raffle.GetRaffleGiftGetState(giftConfig.Id))
				{
					list.Add(giftConfig);
				}
			}
			if (list.Count != 0)
			{
				foreach (RaffleGiftConfig item in list)
				{
					self.GiftConfigs.Remove(item);
				}
				list.Sort((RaffleGiftConfig x, RaffleGiftConfig y) => x.BuyCountLimit.CompareTo(y.BuyCountLimit));
				self.GiftConfigs.AddRange(list);
			}
			if (self.GiftConfigs.Count != 0)
			{
				self._ObtainList.SetData(self.GiftConfigs.Count);
			}
		}

		private static void ClickCloseButton(this UIRaffleGiftPanel self)
		{
			if (((Entity)self.Raffle).Id == 4)
			{
				UIObject.FindUIObjectOfType<UIRaffleZhuanWuPanel>()?.RefreshRedPoint();
			}
			else if (((Entity)self.Raffle).Id == 5)
			{
				UIObject.FindUIObjectOfType<UIRaffleTianGangPanel>()?.RefreshRedPoint();
			}
			else if (((Entity)self.Raffle).Id == 3)
			{
				UIObject.FindUIObjectOfType<UIBeastBagPanel>()?.RefreshRedPoint();
				UIObject.FindUIObjectOfType<UIBeastBagPanel>()?.OnSetGiftActive();
			}
			else if (((Entity)self.Raffle).Id == 1 || ((Entity)self.Raffle).Id == 2)
			{
				UIObject.FindUIObjectOfType<UIRaffleHeroPanel>()?.RefreshRedPoint();
			}
			else if (((Entity)self.Raffle).Id == 6)
			{
				UIObject.FindUIObjectOfType<UIFaBaoSoulRaffleInfoPanel>()?.RefreshRedPoint();
			}
			((DisposeObject)self.UIObject).Dispose();
		}

