		public static void RefreshView(this UIRafflePanel self, int funcId = 0, bool force = false)
		{
			Dictionary<int, List<Raffle>> raffleInfo = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<RaffleModule>().GetRaffleInfo(RaffleViewType.Raffle);
			if (raffleInfo == null)
			{
				return;
			}
			List<int> list = raffleInfo.Keys.ToList();
			for (int num = self.Raffles.Count - 1; num >= 0; num--)
			{
				if (!list.Contains(self.Raffles[num].FuncId))
				{
					self.Raffles.RemoveAt(num);
				}
			}
			for (int i = 0; i < list.Count; i++)
			{
				int tabKey = list[i];
				UITabInfo uITabInfo = self.Raffles.FirstOrDefault((UITabInfo t) => t.FuncId == tabKey);
				if (uITabInfo != null)
				{
					uITabInfo.SetArgs(new UIRaffleShowArgs
					{
						Raffles = raffleInfo[tabKey]
					});
					continue;
				}
				UITabInfo item = UITabInfo.CreateWithFunc(tabKey).SetArgs(new UIRaffleShowArgs
				{
					Raffles = raffleInfo[tabKey]
				}).SetIcon($"ui_ck_normal_{tabKey}")
					.SetIsOnIcon($"ui_ck_select_{tabKey}")
					.SetRedPointArgs(tabKey);
				self.Raffles.Add(item);
			}
			if (self.EnterFirst && !force)
			{
				self.EnterFirst = false;
				if (self.Raffles.Count > 0 && RedPointHelper.GetCount(SceneHelper.DomainScene((Entity)(object)self), RedPointType.Raffle, self.Raffles[0].FuncId) > 0)
				{
					((Entity)self).GetComponent<UICommonTab>().SetTabs(self.Raffles.ToArray(), 16).Coroutine();
				}
				else if (RedPointHelper.GetCount(SceneHelper.DomainScene((Entity)(object)self), RedPointType.RaffleZw) > 0)
				{
					((Entity)self).GetComponent<UICommonTab>().SetTabs(self.Raffles.ToArray(), 35).Coroutine();
				}
				else if (self.Raffles.Count > 2 && RedPointHelper.GetCount(SceneHelper.DomainScene((Entity)(object)self), RedPointType.Raffle, self.Raffles[2].FuncId) > 0)
				{
					((Entity)self).GetComponent<UICommonTab>().SetTabs(self.Raffles.ToArray(), 36).Coroutine();
				}
				else
				{
					((Entity)self).GetComponent<UICommonTab>().SetTabs(self.Raffles.ToArray(), 16).Coroutine();
				}
			}
			else
			{
				((Entity)self).GetComponent<UICommonTab>().SetTabs(self.Raffles.ToArray(), funcId).Coroutine();
			}
		}

