			List<RaffleChoose> showChooses = self.Raffle.GetShowChooses();
			self._UIRaffleBtn.UIObject.CloneAll(showChooses, delegate(int i, RaffleChoose choose, UIObject uiObj)
			{
				((Object)uiObj.GameObject).name = $"_UIRaffleBtn{i}";
