				self.UIRaffleBtnsDic.Add(choose.Config.RaffleNum, component);
			}).Coroutine();
			UIGuideHelper.ExecuteGuide(SceneHelper.DomainScene((Entity)(object)self), 103);
			UIGuideHelper.TryGuide(SceneHelper.DomainScene((Entity)(object)self), "UIRaffleTianGangPanel");
