		private static void SetZwItemInfo(this UIRaffleTianGangPanel self)
		{
			if (self.isLotteryEnd)
			{
				return;
			}
			self.UIRaffleTgItemIcons?.Clear();
			self.WrapItemList?.Clear();
			RaffleQuelityItemConfig raffleQuelityItemConfig = ConfigSingleton<RaffleQuelityItemConfigCategory>.Instance.Get(self.Raffle.Config.RaffleItemId[0]);
			new List<int>();
			self.WrapItemList.AddRange(self.Raffle.GetRaffleItems());
			if (self.RaffleZwConfig != null)
			{
				foreach (KeyValuePair<int, UIRaffleBtn> item2 in self.UIRaffleBtnsDic)
				{
					item2.Deconstruct(out var _, out var value);
					value.SetRaffleConfig(self.RaffleZwConfig);
				}
				for (int i = 0; i < raffleQuelityItemConfig.ItemPosition.Length; i++)
				{
					if (i < self.RaffleZwConfig.RaffleItems.Length)
					{
						self.WrapItemList.Insert(raffleQuelityItemConfig.ItemPosition[i], self.RaffleZwConfig.RaffleItems[i]);
					}
				}
			}
			else
			{
				WrapItem item = new WrapItem();
				for (int j = 0; j < raffleQuelityItemConfig.ItemPosition.Length; j++)
				{
					self.WrapItemList.Insert(raffleQuelityItemConfig.ItemPosition[j], item);
				}
			}
			List<DropItem> list = new List<DropItem>();
			foreach (WrapItem wrapItem in self.WrapItemList)
			{
				DropItem dropItem = new DropItem();
				if (wrapItem.Id == 0)
				{
					list.Add(dropItem);
					continue;
				}
				DropShowConfig dropShowConfig = ConfigSingleton<DropShowConfigCategory>.Instance.Get(wrapItem.Id);
				if (dropShowConfig != null && dropShowConfig.Items != null)
				{
					dropItem.Id = dropShowConfig.Items[0].Id;
					dropItem.Nums = dropShowConfig.Items[0].Nums;
					dropItem.Odds = wrapItem.Weight;
					list.Add(dropItem);
				}
			}
			self._UIRaffleTgItemIcon.UIObject.CloneAll(list, delegate(int num, DropItem Item, UIObject uiObj)
			{
				((Object)uiObj.GameObject).name = $"UIRaffleTgItemIcon{num}";
				if (num < self.Positions.Count)
				{
					UIRaffleTgItemIcon component = ((Entity)uiObj).GetComponent<UIRaffleTgItemIcon>();
					component.SetData(num, self.Raffle, Item, self.Positions[num], self.OnItemClickForge);
					self.UIRaffleTgItemIcons.Add(num, component);
				}
			}).Coroutine();
		}

		public static void SetTgInfo(this UIRaffleTianGangPanel self, RaffleZwConfig item = null)
		{
			if (item != null)
			{
				self.RaffleZwConfig = item;
			}
			self._UnSelectZwBgBtn.SetRedPoint(RedPointType.Raffle_TgUnSelect).Coroutine();
			self._UnSelectZwBgBtn.SetActive(self.RaffleZwConfig == null);
			self._UICommonICentertem.UIObject.SetActive(self.RaffleZwConfig != null);
			if (self.RaffleZwConfig != null && ConfigSingleton<ItemConfigCategory>.Instance.Contain(self.RaffleZwConfig.ZwTgId))
			{
				ItemConfig itemConfig = ConfigSingleton<ItemConfigCategory>.Instance.Get(self.RaffleZwConfig.ZwTgId);
				self._TitleText.SetText(itemConfig.Name ?? "");
				self._UICommonICentertem.SetItem(self.RaffleZwConfig.ZwTgId, 0L);
				self.SetTXText();
			}
			self.SetZwItemInfo();
			self.RefreshRedPoint();
		}

		private static void SetTXText(this UIRaffleTianGangPanel self)
		{
			if (self.RaffleZwConfig == null)
			{
				self._TxCount.SetText("0");
				self._TxText.SetText(Language.Get(3, 160));
				return;
			}
			self._TxCount.SetActive(active: true);
			if (self.Raffle.ForgeTgNums >= self.RaffleZwConfig.ForgeNum - 1)
			{
				self._TxCount.SetActive(active: false);
				self._TxText.SetText(Language.Get(3, 161));
			}
			else
			{
				self._TxCount.SetText($"{self.RaffleZwConfig.ForgeNum - self.Raffle.ForgeTgNums}");
				self._TxText.SetText(Language.Get(3, 160));
			}
		}

		private static void ShowReward(this UIRaffleTianGangPanel self, List<RaffleItem> raffleItems)
		{
			using ItemList itemList = ItemList.Create();
			foreach (RaffleItem raffleItem in raffleItems)
			{
				itemList.Add(new ItemStruct
				{
					ConfigId = raffleItem.ItemId,
					Nums = raffleItem.Num
				});
			}
			Singleton<EventSystem>.Instance.Publish<AddItems>(SceneHelper.DomainScene((Entity)(object)self), new AddItems
			{
				ItemList = itemList,
				Reason = 171
			});
			self.isLotteryEnd = false;
			self.SetTXText();
			foreach (KeyValuePair<int, UIRaffleBtn> item in self.UIRaffleBtnsDic)
			{
				item.Deconstruct(out var _, out var value);
				value.SetLotterying(isLottery: false);
			}
			self.RefreshView();
		}

		private static void PlayRaffleTgAni(this UIRaffleTianGangPanel self, int index)
		{
			int key;
			UIRaffleBtn value;
			if (index == 206502)
			{
				self.RefreshView();
				self.OnItemClickForge();
				foreach (KeyValuePair<int, UIRaffleBtn> item in self.UIRaffleBtnsDic)
				{
					item.Deconstruct(out key, out value);
					value.SetLotterying(isLottery: false);
				}
				self.isLotteryEnd = false;
			}
			else
			{
				if (self.isLotteryEnd)
				{
					return;
				}
				foreach (KeyValuePair<int, UIRaffleBtn> item2 in self.UIRaffleBtnsDic)
				{
					item2.Deconstruct(out key, out value);
					value.SetLotterying(isLottery: true);
				}
				self.UIRaffleBtnsDic.TryGetValue(index, out var value2);
				List<RaffleItem> raffleItems = value2.GetRaffleItems();
				List<int> raffleDropIds = value2.GetRaffleDropIds();
				if (raffleDropIds == null || raffleDropIds.Count == 0)
				{
					return;
				}
				List<int> list = new List<int>();
				for (int i = 0; i < raffleDropIds.Count; i++)
				{
					for (int j = 0; j < self.WrapItemList.Count; j++)
					{
						if (self.WrapItemList[j].Id == raffleDropIds[i])
						{
							list.Add(j);
							break;
						}
					}
				}
				if (((Entity)(object)self).LocalPlayer().GetLocalBool("RaffleTianGangJumpAnim"))
				{
					self.ShowReward(raffleItems);
					return;
				}
				self.DoTgAni(list, delegate
				{
					self.ShowReward(raffleItems);
				}).Coroutine();
			}
		}

