		private static int GetMaxExchangeNum(this UIRaffleZwExchangePanel self)
		{
			if (self.ExchangeItem == null)
			{
				return 0;
			}
			long num = self.Raffle.GetScore() / self.ExchangeItem.Cost.Nums;
			if (num != 0L)
