			}
			return 1;
		}

		public static void OnInputChange(this UIRaffleZwExchangePanel self, string value)
		{
			if (string.IsNullOrEmpty(value) || !int.TryParse(value, out var result))
			{
				self.UpdateExchangeNum(1);
				return;
			}
			int maxExchangeNum = self.GetMaxExchangeNum();
			result = ((maxExchangeNum <= 0) ? 1 : math.clamp(result, 1, maxExchangeNum));
			self.UpdateExchangeNum(result);
		}

		private static void OnClickChangeNum(this UIRaffleZwExchangePanel self, int num)
		{
			int maxExchangeNum = self.GetMaxExchangeNum();
			if (maxExchangeNum <= 0)
			{
				self.UpdateExchangeNum(1);
				return;
			}
			int num2 = math.clamp(self.ExchangeNum + num, 1, maxExchangeNum);
			self.UpdateExchangeNum(num2);
		}

		private static void UpdateExchangeNum(this UIRaffleZwExchangePanel self, int num, bool updateSlider = true)
		{
			int maxExchangeNum = self.GetMaxExchangeNum();
			num = math.clamp(num, 1, maxExchangeNum);
			self.ExchangeNum = ((maxExchangeNum <= 0) ? 1 : num);
			((Slider)((Component)self._Slider.Transform).GetComponent<SuperSlider>()).SetValueWithoutNotify((float)self.ExchangeNum);
			self.SetSelectData(self.ExchangeItem);
