		private static void InitData(this UIRaffleZwNewExchangePanel self)
		{
			RaffleExhcangeConfig exchangeConfig = self.Raffle.ExchangeConfig;
			if (exchangeConfig == null)
			{
				((DisposeObject)self.UIObject).Dispose();
				return;
			}
			self.ExchangeZwIds = new List<RaffleExchangeItem>();
			self.ExchangeGodDecorateIds = new List<RaffleExchangeItem>();
			int[] itemIds = exchangeConfig.ItemIds;
			foreach (int zWtGId in itemIds)
			{
				RaffleZwConfig raffleZwConfig = self.Raffle.GetRaffleZwConfig(zWtGId);
				if (raffleZwConfig != null)
				{
					RaffleExchangeItem item = new RaffleExchangeItem
					{
						Id = raffleZwConfig.ZwTgId,
						Cost = raffleZwConfig.Cost,
						Num = 1,
						Level = raffleZwConfig.Level
					};
					if (raffleZwConfig.Type == 1)
					{
						self.ExchangeZwIds.Add(item);
					}
					if (raffleZwConfig.Type == 3)
					{
						self.ExchangeGodDecorateIds.Add(item);
					}
				}
			}
			self.ExchangeZwIds.Sort((RaffleExchangeItem a, RaffleExchangeItem b) => (a.Level != b.Level) ? b.Level.CompareTo(a.Level) : b.Id.CompareTo(a.Id));
			self.ExchangeGodDecorateIds.Sort((RaffleExchangeItem a, RaffleExchangeItem b) => (a.Level != b.Level) ? b.Level.CompareTo(a.Level) : b.Id.CompareTo(a.Id));
		}

		private static void setData(this UIRaffleZwNewExchangePanel self)
		{
			if (self.CheckRedItemId != 0)
			{
				self.InitSelectItem(self.SelectTab);
			}
			else if (self.Raffle.ZwExchangeId > 0)
			{
				self.InitSelectItem(0);
			}
			else if (self.Raffle.GodDecorateExchangeId > 0)
			{
				self.InitSelectItem(1);
			}
			else
			{
				self.InitSelectItem(0);
			}
			self.SetDictData(self.ExchangeZwIds, 0);
			self.SetDictData(self.ExchangeGodDecorateIds, 1);
			self.SetSelectData(self.ExchangeItem);
			((Slider)self.Slider).maxValue = self.GetMaxExchangeNum();
			self.UpdateExchangeNum((int)((Slider)self.Slider).maxValue);
		}

