			self.SelecltIndex = -1;
			RaffleExchangeItem exchangeItem = new RaffleExchangeItem();
			if (indexx == 0)
			{
				foreach (RaffleExchangeItem exchangeZwId in self.ExchangeZwIds)
				{
					num++;
					if (self.Raffle.ZwExchangeId == exchangeZwId.Id && self.CacheZwItem == null)
					{
						self.SelecltIndex = num;
						exchangeItem = exchangeZwId;
						break;
					}
					if (self.CacheZwItem != null && self.CacheZwItem.Id == exchangeZwId.Id)
					{
						self.SelecltIndex = num;
						exchangeItem = exchangeZwId;
						break;
