		private static string GetEffectNameByQuality(UIObject cardUIObj, ItemConfig itemConfig)
		{
			if (!ConfigSingleton<RaffleQuelityConfigCategory>.Instance.Contain(itemConfig.Id))
			{
				Log.Error($"抽卡特效异常，没有配置对应抽卡品质！ -> ItemId = {itemConfig.Id}");
				return "";
			}
			return ConfigSingleton<RaffleQuelityConfigCategory>.Instance.Get(itemConfig.Id).Quality switch
			{
				6 => "hong", 
				5 => "cheng", 
				4 => "zi", 
				_ => "", 
			};
		}

