		private static void UpdateModelView(this UICommonTopPlayer self, UICommonModelPanel model, UIObject nameTxt, int rankType, RankInfo rankInfo, int configId)
		{
			//IL_0049: Unknown result type (might be due to invalid IL or missing references)
			//IL_004e: Unknown result type (might be due to invalid IL or missing references)
			if (rankInfo != null)
			{
				nameTxt.SetText(rankInfo.Name);
				model.UIObject.SetActive(active: true);
				if (48 == rankType)
				{
					int beastModelId = self.GetBeastModelId(rankInfo);
					UIModelInfo uIModelInfo = self.GenModelInfo(0, beastModelId, 0, 0);
					uIModelInfo.Rotation = new Vector3(0f, 0f, 0f);
					SetModel(model, uIModelInfo, 0.45f, -48f, 14f).Coroutine();
					return;
				}
				int num = self.GetHeroSkinModelId(rankInfo);
				if (num == 0)
				{
					num = ConfigSingleton<HeroConfigCategory>.Instance.Get(configId).UnitId;
				}
				SetModel(model, self.GenModelInfo(0, num, 0, 0)).Coroutine();
			}
			else
			{
				nameTxt.SetText(Language.Get(2, 206));
				model.UIObject.SetActive(active: false);
			}
		}

