		private static void RefreshMySelfInfo(this UIRankPanel2 self, int rank, long value, long extValue, bool showGuild, bool showPower, bool showHeroIcon, bool powerUseValue)
		{
			if (rank > 3 || rank == 0)
			{
				self._PlayerRankImage.GameObject.SetActive(false);
				RankConfig rankConfig = ConfigSingleton<RankConfigCategory>.Instance.Get(self.CurrentRankType);
				if (rank < rankConfig.LimitCount && rank != 0)
				{
					self._PlayerRankText.SetActive(active: true);
					self._PlayerRankDescText.SetActive(active: false);
					self._PlayerRankText.SetText(rank.ToString());
				}
				else
				{
					self._PlayerRankText.SetActive(active: false);
					self._PlayerRankDescText.SetActive(active: true);
					self._PlayerRankDescText.SetText(Language.Get(2, 159));
				}
			}
			else
			{
				self._PlayerRankImage.GameObject.SetActive(true);
				self._PlayerRankText.SetActive(active: false);
				self._PlayerRankDescText.SetActive(active: false);
				self._PlayerRankImage.SetSprite($"ui_jjc2_sign_0{rank}", nativeSize: true).Coroutine();
			}
			self._PlayerUICommonHead.UIObject.SetActive(!showGuild);
			self._PlayerUICommonGuildIcon.UIObject.SetActive(showGuild);
			Player player = ((Entity)(object)self).LocalPlayer();
			if (showPower)
			{
				self._PlayerUICommonPower.UIObject.SetActive(active: true);
				self._PlayerExtValueText.SetActive(active: false);
				if (powerUseValue && rank == 0)
				{
					value = player.GetPower();
				}
				self._PlayerUICommonPower.SetPower(value);
			}
			else
			{
				self._PlayerUICommonPower.UIObject.SetActive(active: false);
				self._PlayerExtValueText.SetActive(active: true);
				self._PlayerExtValueText.SetText(UIRankHelper.GetValueText(self.CurrentRankType, value));
				if (self.CurrentRankType == 2 && value == 0L)
				{
					BattleGroundModule activityModuleByType = ((Entity)(object)self).LocalPlayer().GetActivityModuleByType<BattleGroundModule>(ActivityType.BattleGround);
					if (activityModuleByType == null)
					{
						return;
					}
					self._PlayerExtValueText.SetText(UIRankHelper.GetValueText(self.CurrentRankType, activityModuleByType.Score));
				}
			}
			if (showGuild)
			{
				GuildModule component = ((Entity)player).GetComponent<GuildModule>();
				if (component.GuildId == 0L)
				{
					self._PlayerUICommonGuildIcon.UIObject.SetActive(active: false);
					self._PlayerGuildName.SetActive(active: false);
					self._PlayerName.SetActive(active: false);
					self._PlayerName2.SetActive(active: false);
					self._PlayerRankImage.GameObject.SetActive(false);
					self._PlayerRankText.SetActive(active: false);
					self._PlayerRankDescText.SetActive(active: true);
					self._PlayerExtValueText.SetActive(active: false);
					self._PlayerUICommonPower.UIObject.SetActive(active: false);
					self._PlayerRankDescText.SetText(Language.Get(2, 294));
				}
				else
				{
					self._PlayerGuildName.SetActive(active: false);
					self._PlayerName.SetActive(active: false);
					self._PlayerName2.SetActive(active: true);
					self._PlayerName2.SetText(component.GetName());
					self._PlayerUICommonGuildIcon.SetData(component.GuildId, component.GetFlag(), component.GetIcon());
				}
				return;
			}
			self._PlayerGuildName.SetActive(active: true);
			self._PlayerName.SetActive(active: true);
			self._PlayerName2.SetActive(active: false);
			if (showHeroIcon)
			{
				self._PlayerName.SetActive(extValue > 0);
				self._PlayerGuildName.SetActive(extValue > 0);
				self._PlayerUICommonHead.UIObject.SetActive(extValue > 0);
				self._PlayerUICommonPower.UIObject.SetActive(extValue > 0);
				if (extValue <= 0)
				{
					return;
				}
				self._PlayerGuildName.SetText(player.GetName());
				(int high, int low) tuple = RankRewardHelper.Split(extValue);
				int item = tuple.high;
				int item2 = tuple.low;
				int headFrame = player.GetHeadFrame();
				int num = 0;
				if (self.CurrentRankType == 48)
				{
					self._PlayerUICommonHead.SetStar(item, showStar: false);
					BeastConfig beastConfig = ConfigSingleton<BeastConfigCategory>.Instance.Get(item2);
					if (beastConfig != null)
					{
						num = beastConfig.Icon;
						self._PlayerName.SetText(beastConfig.Name);
						self._PlayerUICommonHead.SetData(isBeast: true, num, headFrame, ((Entity)player).Id);
					}
				}
				else
				{
					HeroConfig heroConfig = ConfigSingleton<HeroConfigCategory>.Instance.Get(item2);
					self._PlayerName.SetText(heroConfig.HeroName);
					num = UIHeroHelper.GetIconId(((Entity)(object)self).LocalPlayer().GetHero(item2));
					self._PlayerUICommonHead.SetData(num, headFrame, ((Entity)player).Id);
					self._PlayerUICommonHead.SetStar(item);
				}
			}
			else
			{
				self._PlayerName.SetText(player.GetName());
				string name = ((Entity)player).GetComponent<GuildModule>().GetName();
				name = (string.IsNullOrEmpty(name) ? Language.Get(2, 294) : name);
				self._PlayerGuildName.SetText(name);
				int head = player.GetHead();
				int headFrame2 = player.GetHeadFrame();
				self._PlayerUICommonHead.SetData(head, headFrame2, ((Entity)player).Id, isEasyLook: false);
				self._PlayerUICommonHead.SetPracticeLevel(player.GetPracticeLevel());
			}
		}

		private static bool PowerUseValue(this UIRankPanel2 self)
		{
			return true;
		}

		private static bool ShowGuild(this UIRankPanel2 self)
		{
			return self.CurrentRankType == 8;
		}

		private static bool ShowHeroIcon(this UIRankPanel2 self)
		{
			if (self.CurrentRankType != 18 && self.CurrentRankType != 19 && self.CurrentRankType != 20)
			{
				return self.CurrentRankType == 48;
			}
			return true;
		}

		private static void OnCellUpdate(this UIRankPanel2 self, UIScrollListCell cell)
		{
			int index = cell.Index;
			if (self.RankInfos != null && index < self.RankInfos.Count)
			{
				((Entity)cell.UIObject).GetComponent<UIRankItem>().SetRankType(self.CurrentRankType);
				((Entity)cell.UIObject).GetComponent<UIRankItem>().SetData(self.RankInfos[index], self.ShowGuild(), self.ShowPower(), self.ShowHeroIcon(), self.PowerUseValue());
			}
		}
