		public static void SetSelfRewardData(this UIRankPopupItem self, int rankNo, List<RankRewardConfig> rewardConfigs)
		{
			self.SetRankNo(rankNo);
			self._RankBg.SetSprite("ui_rank_frame_07_gv").Coroutine();
			self._RewardArea.SetActive(active: true);
			self._PersonalArea.SetActive(active: false);
			foreach (RankRewardConfig rewardConfig in rewardConfigs)
			{
				if (rankNo >= rewardConfig.LeftRank && rankNo <= rewardConfig.RightRank)
				{
					if (rewardConfig is LadderRewardConfig)
					{
						self._UICommonHorizontalReward.ShowDrop((rewardConfig as LadderRewardConfig).DayReward);
					}
					else
					{
						self._UICommonHorizontalReward.SetData(rewardConfig.Reward);
					}
					break;
				}
			}
		}

		public static void SetRewardData(this UIRankPopupItem self, RankRewardConfig config, int rankType)
		{
			self.RankType = rankType;
			self._RewardArea.SetActive(active: true);
			self._PersonalArea.SetActive(active: false);
			self.SetRankNo(config.LeftRank);
			if (config.LeftRank != config.RightRank)
			{
				self._RankNumText.SetText($"<color=#54505e><size=30>{config.LeftRank}-{config.RightRank}</size></color>");
			}
			if (config is LadderRewardConfig)
			{
				self._UICommonHorizontalReward.ShowDrop((config as LadderRewardConfig).DayReward);
			}
			else
			{
				self._UICommonHorizontalReward.SetData(config.Reward);
			}
		}

		public static void SetData(this UIRankPopupItem self, RankInfo info, int rankType)
		{
			self.RankType = rankType;
			self._RewardArea.SetActive(active: false);
			self._PersonalArea.SetActive(active: true);
			self._ValueText.SetText(self.GetValue(info.Value));
			RankConfig rankConfig = ConfigSingleton<RankConfigCategory>.Instance.Get(rankType);
			switch (rankConfig.UnderInfo)
			{
			case 1:
				self._UIRankRoleInfoPart.SetPowerData(info);
				break;
			case 2:
				self._UIRankRoleInfoPart.SetRoleData(info);
				break;
			}
			if (rankType == 30 || rankType == 32 || rankType == 35 || rankType == 36)
			{
				self._ValueText.SetActive(active: false);
				self._RankLadderItem.UIObject.SetActive(active: true);
				self._RankLadderItem.SetData(info.Value);
			}
			else
			{
				self._ValueText.SetActive(active: true);
				self._RankLadderItem.UIObject.SetActive(active: false);
			}
			if (rankConfig.IsGuildRank)
			{
				self._UIRankRoleInfoPart.UIObject.SetActive(active: false);
				self._UIRankGuildInfoPart.UIObject.SetActive(active: true);
				ShowGuildInfo guildInfo = info.GuildInfo;
				self._UIRankGuildInfoPart.SetData(guildInfo.Name, 0L, 0L, guildInfo.Head, guildInfo.HeadFrame, isSelf: false, info.Id);
			}
			self._ZoneContent.SetActive(active: false);
			if (rankConfig.IsZoneRank)
			{
				self._ZoneContent.SetActive(active: true);
				AncientWarZoneConfig ancientWarZoneConfig = ConfigSingleton<AncientWarZoneConfigCategory>.Instance.Get((int)info.ExtValue);
				self._ZoneContent.SetSprite(ancientWarZoneConfig.ImageName).Coroutine();
				self._ZoneText.SetText(TextHelper.FormatZone((int)info.Id));
			}
			self.SetRankNo(info.RankNo);
		}

		public static void SetSelfData(this UIRankPopupItem self, int rankType, int rank, long value, long extValue)
		{
			//IL_01dd: Unknown result type (might be due to invalid IL or missing references)
			self.RankType = rankType;
			Player player = ((Entity)(object)self).LocalPlayer();
			self.SetRankNo(rank);
			self._RewardArea.SetActive(active: false);
			self._PersonalArea.SetActive(active: true);
			self._RankBg.SetSprite("ui_rank_frame_07_gv").Coroutine();
			self._ValueText.SetText(self.GetValue(value));
			self._UIRankRoleInfoPart.UIObject.SetActive(active: false);
			self._UIRankGuildInfoPart.UIObject.SetActive(active: false);
			self._RankLadderItem.UIObject.SetActive(rankType == 30 || rankType == 32);
			RankConfig rankConfig = ConfigSingleton<RankConfigCategory>.Instance.Get(rankType);
			if (rankConfig.IsGuildRank)
			{
				self._UIRankGuildInfoPart.UIObject.SetActive(active: true);
				GuildModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<GuildModule>();
				self._UIRankGuildInfoPart.SetData(component.GetName(), component.GetPower(), component.GuildId, component.GetIcon(), component.GetFlag(), isSelf: true, component.GuildId);
				return;
			}
			self._UIRankRoleInfoPart.UIObject.SetActive(active: true);
			switch (rankConfig.UnderInfo)
			{
			case 1:
				self._UIRankRoleInfoPart.SetSelf();
				break;
			case 2:
			{
				GuildModule component2 = ((Entity)player).GetComponent<GuildModule>();
				self._UIRankRoleInfoPart.SetData(player.GetName(), component2.GetName(), ((Entity)player).Id, isSelf: true);
				break;
			}
			}
			if (rankType == 30 || rankType == 32)
			{
				self._ValueText.SetActive(active: false);
				self._RankLadderItem.UIObject.SetActive(active: true);
				self._RankLadderItem.SetData(value);
			}
			else
			{
				self._ValueText.SetActive(active: true);
				self._RankLadderItem.UIObject.SetActive(active: false);
			}
			self._ZoneContent.SetActive(active: false);
			if (rankConfig.IsZoneRank)
			{
				self._UIRankRoleInfoPart.UIObject.SetActive(active: false);
				self._ZoneContent.SetActive(active: true);
				self._ZoneText.SetText(TextHelper.FormatZone(new UIDStruct(((Entity)player).Id).Zone));
				if (ConfigSingleton<AncientWarZoneConfigCategory>.Instance.Contain((int)extValue))
				{
					AncientWarZoneConfig ancientWarZoneConfig = ConfigSingleton<AncientWarZoneConfigCategory>.Instance.Get((int)extValue);
					self._ZoneContent.SetSprite(ancientWarZoneConfig.ImageName).Coroutine();
				}
			}
		}

		private static void SetRankNo(this UIRankPopupItem self, int rankNo)
		{
			self._RankNumText.SetActive(active: false);
			self._RankIcon.SetActive(active: false);
			switch (rankNo)
			{
			case 0:
				self._RankNumText.SetActive(active: true);
				self._RankNumText.SetText("<size=24>" + Language.Get(2, 159) + "</size>");
				self._RankBg.SetSprite("ui_rank_frame_09_gv").Coroutine();
				break;
			case 1:
				self._RankIcon.SetSprite("ui_jjc2_sign_01", nativeSize: true).Coroutine();
				self._RankBg.SetSprite("ui_rank_frame_06_gv").Coroutine();
				self._RankIcon.SetActive(active: true);
				break;
			case 2:
				self._RankIcon.SetSprite("ui_jjc2_sign_02", nativeSize: true).Coroutine();
				self._RankBg.SetSprite("ui_rank_frame_05_gv").Coroutine();
				self._RankIcon.SetActive(active: true);
				break;
			case 3:
				self._RankIcon.SetActive(active: true);
				self._RankIcon.SetSprite("ui_jjc2_sign_03", nativeSize: true).Coroutine();
				self._RankBg.SetSprite("ui_rank_frame_04_gv").Coroutine();
				break;
			default:
				self._RankNumText.SetActive(active: true);
				self._RankNumText.SetText(rankNo.ToString());
				self._RankBg.SetSprite("ui_rank_frame_09_gv").Coroutine();
				break;
			}
		}

		public static string GetValue(this UIRankPopupItem self, long value)
		{
			switch (self.RankType)
			{
			case 3:
			{
				if (value == 0L)
				{
					return $"{0}层{0}关";
				}
				int layer = EndlessHelper.GetLayer((int)value);
				int level = EndlessHelper.GetLevel((int)value);
				return $"{layer}层{level}关";
			}
			case 1001:
				return TextHelper.FormatDamage(value);
			case 1002:
				return GuildDupHelper.GetStarLevelDesc((int)value);
			case 30:
			case 32:
			{
				LadderlevelConfig configByScore = LadderHelper.GetConfigByScore(value);
				return ConfigSingleton<DanStarConfigCategory>.Instance.Get(configByScore.DanId).Name;
			}
			case 12:
			case 13:
			case 14:
			case 15:
			case 33:
			case 34:
			{
				int points = ConfigSingleton<KingWarGlobalConfigCategory>.Instance.GetOne().points;
				return TextHelper.FormatDamage(value / points);
			}
			case 37:
			case 38:
				return TextHelper.FormatDamage(value);
			default:
				return value.ToString();
			}
		}

