				for (int i = 0; i < self.AchieveRewardConfigs.Count; i++)
				{
					AchieveRewardConfig achieveRewardConfig = self.AchieveRewardConfigs[i];
					self.InfoDict.TryGetValue(achieveRewardConfig.Position, out var value);
					if (value == null)
					{
						num = i - 1;
						break;
					}
				}
			}
			if (num != -1)
			{
				self._UIScrollList.SetSelectIndex(num);
				self._UIScrollList.MovePanelToItemIndex(num);
			}
		}

		private static void OnCellUpdate(this UIRankRewardSpecificsPopup self, UIScrollListCell cell)
		{
