			if (self.AchieveRewardConfigs != null && index < self.AchieveRewardConfigs.Count)
			{
				AchieveRewardConfig achieveRewardConfig = self.AchieveRewardConfigs[index];
				RankAchievementPlayerInfo value = null;
				self.InfoDict?.TryGetValue(achieveRewardConfig.Position, out value);
				((Entity)cell.UIObject).GetComponent<UIRankRewardSpecificsItem>().SetData(self.RankType, achieveRewardConfig, value, self);
			}
		}
	}
