				{
					self2.Find("playerName").SetText(Language.Get(2, 206));
					self2.Find("RawFlag").SetActive(active: false);
					continue;
				}
				UIObject uIObject = self2.Find("RawFlag");
				uIObject.GameObject.SetActive(true);
				RankInfo rankInfo = self.RankList[i];
