			long num2 = math.max(self.EndTime - num, 0L);
			if (num2 > 0)
			{
				string text = TextHelper.TimeFormatActivityStyle(num2);
				self._CountRankDownText.SetText(Language.Format(1, 24, text));
			}
			else
			{
				self.RemoveAllTimer();
			}
