		private static void SetTitle(this UIRankSubPopup self)
		{
			RankConfig rankConfig = ConfigSingleton<RankConfigCategory>.Instance.Get(self.RankType);
			if (rankConfig.TitleInfo != null)
			{
				for (int i = 0; i < rankConfig.TitleInfo.Length; i++)
				{
					self._PersonalTitle.Find((i + 1).ToString())?.SetText(rankConfig.TitleInfo[i]);
				}
			}
		}

		private static void SetReward(this UIRankSubPopup self)
		{
			self.RankRewardList = RankHelper.GetRankRewardConfigs(((Entity)(object)self).LocalPlayer(), self.RankType);
			self._ChcekButton.SetActive(self.RankRewardList.Count > 0);
			self._BottomArea.SetActive(self.RankRewardList.Count > 0);
		}

		private static void SetTime(this UIRankSubPopup self)
		{
			self.EndTime = RankHelper.GetRankEndTime(((Entity)(object)self).LocalPlayer(), self.RankType);
			if (self.EndTime > 0)
			{
				if (TimeHelper.Now() < self.EndTime)
				{
					self.NewTimer(1000L, self.UpdateTime, repeat: true);
				}
				self.UpdateTime();
			}
			else
			{
				self._CountRankDownText.SetText(string.Empty);
			}
		}

