			}
			else
			{
				UIObject.FindUIObjectOfType<UIRankPopup>()?.SetTitle(ConfigSingleton<RankConfigCategory>.Instance.Get(self.RankType).Name);
			}
			self._RankRewardText.SetText(self.IsShowRank ? Language.Get(1, 28) : Language.Get(1, 27));
			self._RewardImage.SetActive(self.IsShowRank);
			self._RankImage.SetActive(!self.IsShowRank);
			self._PersonalTitle.SetActive(self.IsShowRank);
			self._RewardTitle.SetActive(!self.IsShowRank);
			if (self.IsShowRank)
			{
				self._RankList.SetData(self.RankList.Count);
				self._RankSelfItem.SetSelfData(self.RankType, self.MyRank, self.MyValue, self.MyExtValue);
			}
