			{
				16 => RedPointNodeType.RankPower, 
				17 => RedPointNodeType.RankPlayer, 
				18 => RedPointNodeType.RankMage, 
				19 => RedPointNodeType.RankFighter, 
				20 => RedPointNodeType.RankSupport, 
				48 => RedPointNodeType.Beast, 
				8 => RedPointNodeType.RankGuild, 
				5 => RedPointNodeType.RankHeavenTower, 
				1 => RedPointNodeType.RankMainTask, 
				3 => RedPointNodeType.RankEndlessPurgatory, 
				_ => RedPointNodeType.None, 
			};
		}

		public static void SetData(this UIRankTypeItem self, RankRewardInfo rankRewardInfo, int rankCategoryType)
		{
			self.RankType = rankRewardInfo.RankType;
			self.RankCategoryType = rankCategoryType;
			bool flag = false;
			bool flag2 = false;
			bool flag3 = false;
			RankConfig rankConfig = ConfigSingleton<RankConfigCategory>.Instance.Get(rankRewardInfo.RankType);
			switch (rankRewardInfo.RankType)
			{
			case 16:
				self._LeftBg.SetSprite("ui_rank2_frame_02").Coroutine();
				flag3 = true;
				break;
			case 17:
				self._LeftBg.SetSprite("ui_rank2_frame_06").Coroutine();
				flag3 = true;
				break;
			case 18:
				flag = true;
				flag3 = true;
				self._LeftBg.SetSprite("ui_rank2_frame_05").Coroutine();
				break;
			case 19:
				flag = true;
				flag3 = true;
				self._LeftBg.SetSprite("ui_rank2_frame_03").Coroutine();
				break;
			case 20:
				flag = true;
				flag3 = true;
				self._LeftBg.SetSprite("ui_rank2_frame_04").Coroutine();
				break;
			case 48:
				flag = true;
				flag3 = true;
				self._LeftBg.SetSprite("ui_rank2_frame_18").Coroutine();
				break;
			case 8:
				flag2 = true;
				flag3 = true;
				self._LeftBg.SetSprite("ui_rank2_frame_08").Coroutine();
				break;
			case 2:
				self._LeftBg.SetSprite("ui_rank2_frame_09").Coroutine();
				break;
			case 5:
				self._LeftBg.SetSprite("ui_rank2_frame_10").Coroutine();
				break;
			case 1:
				self._LeftBg.SetSprite("ui_rank2_frame_07").Coroutine();
				break;
			case 3:
				self._LeftBg.SetSprite("ui_rank2_frame_11").Coroutine();
				break;
			case 28:
				self._LeftBg.SetSprite("ui_rank2_frame_20").Coroutine();
				break;
			}
			if (rankRewardInfo.PlayerId == 0L)
			{
				self._UICommonHead.UIObject.SetActive(active: false);
				self._DayText.SetActive(active: false);
				self._UICommonPower.UIObject.SetActive(active: false);
				self._UICommonGuildIcon.UIObject.SetActive(active: false);
				self._NotBeOn.SetActive(active: true);
				self._Name.SetText(Language.Get(2, 206));
			}
			else
			{
				self._DayText.SetActive(active: true);
				self._UICommonPower.UIObject.SetActive(active: true);
				self._NotBeOn.SetActive(active: false);
				if (flag2)
				{
					self._UICommonHead.UIObject.SetActive(active: false);
					self._UICommonGuildIcon.UIObject.SetActive(active: true);
					string str = ((rankRewardInfo.ShowGuildInfo == null) ? string.Empty : rankRewardInfo.ShowGuildInfo.Name);
					self._Name.SetText(str);
					self._UICommonGuildIcon.SetData(rankRewardInfo.PlayerId, rankRewardInfo.ShowGuildInfo.HeadFrame, rankRewardInfo.ShowGuildInfo.Head);
				}
				else
				{
					self._UICommonHead.UIObject.SetActive(active: true);
					self._UICommonGuildIcon.UIObject.SetActive(active: false);
					self._Name.SetText(rankRewardInfo.Name);
					(int high, int low) tuple = RankRewardHelper.Split(rankRewardInfo.ExtValue);
					int item = tuple.high;
					int item2 = tuple.low;
					int headFrameId = rankRewardInfo.ShowDressInfo.GetHeadFrameId((byte)rankRewardInfo.Sex);
					int num = 0;
					if (rankRewardInfo.RankType == 48)
					{
						BeastConfig beastConfig = ConfigSingleton<BeastConfigCategory>.Instance.Get(item2);
						if (beastConfig != null)
						{
							num = beastConfig.Icon;
							self._UICommonHead.SetData(isBeast: true, num, headFrameId, rankRewardInfo.PlayerId);
						}
					}
					else
					{
						num = (flag ? rankRewardInfo.ShowDressInfo.HeadId : rankRewardInfo.ShowDressInfo.GetHeadId((byte)rankRewardInfo.Sex));
						self._UICommonHead.SetData(num, headFrameId, rankRewardInfo.PlayerId);
					}
					if (flag)
					{
						self._UICommonHead.SetStar(item, rankRewardInfo.RankType != 48);
					}
					else
					{
						self._UICommonHead.SetPracticeLevel(rankRewardInfo.PracticeLevel);
					}
				}
				self._UICommonPower.SetPower(flag3 ? rankRewardInfo.Value : rankRewardInfo.Power);
				int num2 = TimeHelper.DaysBetween(rankRewardInfo.UpdateTime, TimeHelper.Now(), 18000000L);
				self._DayText.SetText(Language.Format(2, 614, num2));
			}
			self.ClearAction?.Invoke();
			self.ClearAction = null;
			if (rankConfig.AchieveRewardId != 0)
			{
				self._RewardBtn.SetActive(active: true);
				RedPointNodeType redPointNodeType = RankTypeToRedPointNodeType(rankRewardInfo.RankType);
				RedPointNode node = RedPointTreeComponent.Instance.GetNode(redPointNodeType);
				if (node != null)
				{
					UIRankTypeItem uIRankTypeItem = self;
					uIRankTypeItem.ClearAction = (Action)Delegate.Combine(uIRankTypeItem.ClearAction, ((Entity)(object)node).BindData("Count", delegate(int _, int newCount)
					{
						self._RewardRedPoint.SetActive(newCount > 0);
					}, () => node.Count));
				}
			}
			else
			{
				self._RewardBtn.SetActive(active: false);
			}
		}
	}
