			}
			self._BtnGo.SetGray(!flag);
			bool flag2 = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<PrivilegeModule>().GetValue(PrivilegeType.PassRiverMapDup) > 0;
			string str = (flag2 ? Language.Get(6, 3036) : Language.Get(6, 3035));
			self._MopUp.SetText(str);
			bool flag3 = RiverMapHelper.ShowMopUpBtn(((Entity)(object)self).LocalPlayer(), self.EventData);
			self._BtnSweep.SetActive(active: false);
			if (flag3)
