				self._BtnSweep.SetActive(active: true);
				self._SweepCostGroup.SetActive(active: true);
				if (!flag2)
				{
					UIObject self3 = self._SweepCostGroup.Find("1");
					long itemNumsByItemId2 = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().GetItemNumsByItemId(102);
					int ticket2 = self.EventData.Config.Ticket;
					string arg2 = ((itemNumsByItemId >= ticket) ? "#0db64d" : "#ff402b");
					self3.SetActive(active: true);
					self3.Find("TxtCost").SetText($"<color={arg2}>{itemNumsByItemId2}/{ticket2}</color>");
					self3.Find("RawCost").SetRawTexture($"uitex_icon_item_{UIItemHelper.GetItemIconIdByItemId(102)}").Coroutine();
				}
				UIObject self4 = self._SweepCostGroup.Find("2");
				self4.SetActive(active: true);
				self4.Find("TxtCost").SetText($"<color={arg}>{itemNumsByItemId}/{ticket}</color>");
				self4.Find("RawCost").SetRawTexture($"uitex_icon_item_{UIItemHelper.GetItemIconIdByItemId(25)}").Coroutine();
			}
			self._BtnGo.SetActive(!flag3 || !flag2);
