		private static void OnClickFight(this UIRiverMapEventDupPanel self)
		{
			if (self.EventData.MainType == 1 && self.EventData.IsExpired)
			{
				UIGameMsgHelper.FloatMsg(Language.Get(6, 41));
				return;
			}
			if (self.EventData.MainType == 3)
			{
				if (self.LeftTime > 0)
				{
					UIGameMsgHelper.FloatMsg(Language.Get(6, 42));
					return;
				}
				RiverMapEventPostConfig riverMapEventPostConfig = ConfigSingleton<RiverMapEventPostConfigCategory>.Instance.Get(self.EventData.PostId);
				if (riverMapEventPostConfig == null || !((Entity)(object)self).LocalPlayer().CheckAllConds(riverMapEventPostConfig.Conds))
				{
					UIGameMsgHelper.FloatMsg(((Entity)(object)self).LocalPlayer().GetCondText(riverMapEventPostConfig.Conds));
					return;
				}
			}
			bool flag = false;
			flag = self.EventData.MainType == 4 || ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().CheckItemNumsIsEnough(25, self.EventData.Config.Ticket);
			if (self.EventData.LastFinishTime > 0 && ConfigSingleton<RiverMapEventPostConfigCategory>.Instance.Get(self.EventData.PostId).CDTime * 1000 - (TimeHelper.Now() - self.EventData.LastFinishTime) > 0)
			{
				UIGameMsgHelper.FloatMsg(Language.Get(6, 42));
			}
			else if (!flag)
			{
				UIObtainWayHelper.ShowPanelAsync(25).Coroutine();
				UIGameMsgHelper.FloatMsg(Language.Get(6, 43));
			}
			else if (self.EventData.EventType == 1)
			{
				UIManager.Instance.Show<UIRiverMapEventAnswerPanel, RiverMapEventData>(self.EventData).Coroutine();
				((DisposeObject)self).Dispose();
			}
			else if (self.EventData.EventType == 2)
			{
				UIManager.Instance.Show<UIRiverMapEventStorePanel, RiverMapEventData>(self.EventData).Coroutine();
				((DisposeObject)self).Dispose();
			}
			else
			{
				RiverMapHandler.EventFight(SceneHelper.DomainScene((Entity)(object)self), self.EventData);
				((DisposeObject)self).Dispose();
			}
		}

