		private static void SetNormalTimer(this UIRiverMapEventItem self)
		{
			self.LeftTime = self.EventData.ExpireTime;
			if (self.LeftTime <= 0)
			{
				self._TimeText.SetActive(active: false);
				self._ImgMask.SetActive(active: false);
				return;
			}
			self._TimeText.SetActive(active: true);
			self._TimeText.SetText(TextHelper.TimeFormatHourMinSec(self.LeftTime));
			self.Timer = self.NewTimer(1000L, delegate
			{
				self.LeftTime = self.EventData.ExpireTime;
				if (self.LeftTime <= 0)
				{
					self.UIObject.SetActive(active: false);
				}
				else
				{
					self._TimeText.SetText(TextHelper.TimeFormatHourMinSec(self.LeftTime));
				}
			}, repeat: true);
		}

		private static void SetPostTimer(this UIRiverMapEventItem self)
		{
			int postId = self.EventData.PostId;
			RiverMapEventPostConfig riverMapEventPostConfig = ConfigSingleton<RiverMapEventPostConfigCategory>.Instance.Get(postId);
			if (riverMapEventPostConfig.Conds.Length != 0 && !((Entity)(object)self).LocalPlayer().CheckAllConds(riverMapEventPostConfig.Conds))
			{
				self._TimeText.SetActive(active: false);
				self._ImgMask.SetActive(active: true);
			}
			else
			{
				if (self.EventData.LastFinishTime <= 0)
				{
					return;
				}
				int postId2 = self.EventData.PostId;
				if (!ConfigSingleton<RiverMapEventPostConfigCategory>.Instance.Contain(postId2))
				{
					return;
				}
				RiverMapEventPostConfig config = ConfigSingleton<RiverMapEventPostConfigCategory>.Instance.Get(postId2);
				self._TimeText.SetActive(active: true);
				self.LeftTime = config.CDTime * 1000 - (TimeHelper.Now() - self.EventData.LastFinishTime);
				if (self.LeftTime <= 0)
				{
					self.RemoveTimer(ref self.Timer);
					self._TimeText.SetActive(active: false);
					self._ImgMask.SetActive(active: false);
					return;
				}
				self._TimeText.SetActive(active: true);
				self._ImgMask.SetActive(active: true);
				self._TimeText.SetText(TextHelper.TimeFormatMinSec(self.LeftTime));
				self.Timer = self.NewTimer(1000L, delegate
				{
					self.LeftTime = config.CDTime * 1000 - (TimeHelper.Now() - self.EventData.LastFinishTime);
					if (self.LeftTime <= 0)
					{
						self.RemoveTimer(ref self.Timer);
						self._TimeText.SetActive(active: false);
						self._ImgMask.SetActive(active: false);
					}
					else
					{
						self._TimeText.SetText(TextHelper.TimeFormatMinSec(self.LeftTime));
					}
				}, repeat: true);
			}
		}
	}
