		public static void OnClickAwardPreview(this UIRiverMapLevelInfoPanel self)
		{
			UIManager.Instance.Show<UIRiverMapAwardPreviewPanel>().Coroutine();
		}

		public static void RefreshView(this UIRiverMapLevelInfoPanel self)
		{
			RiverMapModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<RiverMapModule>();
			RiverMapLevelConfig config = ConfigSingleton<RiverMapLevelConfigCategory>.Instance.Get(self.Level);
			int count = ConfigSingleton<RiverMapLevelConfigCategory>.Instance.GetList().Count;
			self._TxtLv.SetText((self.Level - 1).ToString());
			self._TxtCurNum.SetText(config.ShowNum.ToString());
			self._TxtAwardTitle.SetLanguage(6, 3034, self.Level - 1);
			int level = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<RiverMapModule>().Level;
			self._LevelIcon.SetGray(self.Level != level);
			self._GoQualityItem.CloneAll(config.QualityRate.Length, delegate(int index, UIObject item)
			{
				UIObject self2 = item.Find("ImgBg");
				UIObject self3 = item.Find("TxtQuality");
				UIObject self4 = item.Find("TxtValue");
				UIObject self5 = item.Find("ImgQuality");
				int num = config.QualityRate[index].Values[0];
				int num2 = config.QualityRate[index].Values[1];
				if (num == 7)
				{
					self5.SetActive(active: true);
					self5.SetSprite("ui_sht_front_04").Coroutine();
					self2.SetSprite("ui_sht_frame_48_1").Coroutine();
					self3.SetActive(active: false);
					self4.SetText((float)num2 / 100f + "%");
				}
				else
				{
					self5.SetActive(active: false);
					self2.SetSprite($"ui_sht_frame_4{num + 1}_1_gv").Coroutine();
					self3.SetActive(active: true);
					self3.SetLanguage(6, 3020 + num);
					self4.SetText((float)num2 / 100f + "%");
				}
			}).Coroutine();
			self._UICommonHorizontalReward.SetData(config.RewardShow);
			self._UICommonHorizontalReward.SetSpaceX(22);
			self._UICommonHorizontalReward.SetGray(state: false);
			if (component.IsMaxLevel)
			{
				self._Exp.SetActive(active: false);
			}
			else if (self.Level == component.Level)
			{
				self._Exp.SetActive(active: true);
				self._TxtLvUpTips.SetLanguage(6, 3031, (config.Exp - component.Exp).ToString());
				self._TxtExp.SetText(component.Exp + "/" + config.Exp);
			}
			else
			{
				self._Exp.SetActive(active: false);
			}
			self._BtnNext.SetActive(self.Level < count);
			self._BtnLast.SetActive(self.Level > 1);
		}
	}
