		[UIMethod]
		private static void OnShow(this UISevenDaySignPanel self, int activityId)
		{
			if (self.ActivityData == null)
			{
				self.ActivityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), activityId);
				self.SetShowData();
				self.InitPanel();
			}
		}

		private static void SetShowData(this UISevenDaySignPanel self)
		{
			int num = TimeHelper.DaysBetween(TimeHelper.ServerNow(), self.ActivityData.StartTime, 18000000L);
			List<SevenDaySignConfig> all = ConfigSingleton<SevenDaySignConfigCategory>.Instance.GetAll(self.ActivityData.ActivityId);
			if (num > all.Count)
			{
				num = all.Count;
			}
			SevenDaySignModule component = ((Entity)self.ActivityData).GetComponent<SevenDaySignModule>();
			self._HeroIcon.SetRawTexture("ui_qiri_frame_01").Coroutine();
			self._HeroImage.SetRawTexture("hero_front_card_quality_name_6").Coroutine();
			int num2 = 0;
			foreach (SevenDaySignConfig item in all)
			{
				if (item.Day <= num && !string.IsNullOrEmpty(item.ShowStyleImg) && !component.IsItemRewardFlag(item.Day))
				{
					self._HeroName.SetText(ET.ItemHelper.GetItemConfig(item.RewadItem.Id).Name);
					self._Title.SetRawTexture(item.TitleImg, nativeSize: true).Coroutine();
					num2 = item.Id;
					break;
				}
			}
			if (num2 == 0)
			{
				foreach (SevenDaySignConfig item2 in all)
				{
					if (item2.Day >= num && !string.IsNullOrEmpty(item2.ShowStyleImg))
					{
						self._HeroName.SetText(ET.ItemHelper.GetItemConfig(item2.RewadItem.Id).Name);
						self._Title.SetRawTexture(item2.TitleImg, nativeSize: true).Coroutine();
						num2 = item2.Id;
						break;
					}
				}
			}
			UIModelInfo info = new UIModelInfo(ET.ItemHelper.GetItemConfig(ConfigSingleton<SevenDaySignConfigCategory>.Instance.Get(num2).RewadItem.Id).ShowModel)
			{
				AnimName = "ShowIdle"
			};
			self._Hero.ShowModel(info).Coroutine();
		}

		private static void OnCellUpdate(this UISevenDaySignPanel self, UIObject cell, int index)
		{
			if (self.SevenDaySignConfigs.Count > index)
			{
				SevenDaySignConfig sevenDaySignConfig = self.SevenDaySignConfigs[index];
				switch ((RewardShowStyle)sevenDaySignConfig.RewardShowStyle)
				{
				case RewardShowStyle.Large:
					((Entity)cell).GetComponent<UISevenDaySignHeroItem>().SetData(self.ActivityData, sevenDaySignConfig);
					break;
				case RewardShowStyle.Medium:
					((Entity)cell).GetComponent<UISevenDaySignJewelryItem>().SetData(self.ActivityData, sevenDaySignConfig);
					break;
				default:
					((Entity)cell).GetComponent<UISevenDaySignItemItem>().SetData(self.ActivityData, sevenDaySignConfig);
					break;
				}
			}
		}

		private static float GetPrefabWidth(this UISevenDaySignPanel self, int index)
		{
			if (index >= self.SevenDaySignConfigs.Count)
			{
				return 0f;
			}
			return (RewardShowStyle)self.SevenDaySignConfigs[index].RewardShowStyle switch
			{
				RewardShowStyle.Large => 299.0103f, 
				RewardShowStyle.Medium => 296.6066f, 
				_ => 150.0977f, 
			};
		}

		private static string GetPrefabName(this UISevenDaySignPanel self, int index)
		{
			if (index >= self.SevenDaySignConfigs.Count)
			{
				return "UISevenDaySignItemItem";
			}
			return (RewardShowStyle)self.SevenDaySignConfigs[index].RewardShowStyle switch
			{
				RewardShowStyle.Large => "UISevenDaySignHeroItem", 
				RewardShowStyle.Medium => "UISevenDaySignJewelryItem", 
				_ => "UISevenDaySignItemItem", 
			};
		}

		private static void OnCloseBtnClick(this UISevenDaySignPanel self)
		{
			UIManager.Instance.Remove(typeof(UISevenDaySignPanel));
		}

		private static void InitPanel(this UISevenDaySignPanel self)
		{
			self.SevenDaySignConfigs = ConfigSingleton<SevenDaySignConfigCategory>.Instance.GetAll(self.ActivityData.ActivityId);
			self.SevenDaySignConfigs.Sort((SevenDaySignConfig a, SevenDaySignConfig b) => a.Day - b.Day);
			self._UITileView.SetData(self.SevenDaySignConfigs.Count);
			SevenDaySignModule module = ((Entity)self.ActivityData).GetComponent<SevenDaySignModule>();
			((Entity)(object)self).BindDataWithAutoUnBind((Entity)(object)module, "ItemRewardFlag_C", delegate
			{
				self.SetShowData();
				self._GetAll.SetActive(!module.IsGetAllReward());
			}, () => module.ItemRewardFlag_C);
		}
	}
