		[UIMethod]
		public static void OnShow(this UISevenDayTargetPanel self, int activityId)
		{
			if (!self.IsInit)
			{
				self.IsInit = true;
				self.ActivityId = activityId;
				self.ActivityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), activityId);
				self._BannerImage.SetRawTexture($"ui_qrmb_bg_{self.ActivityData.ActivityId}").Coroutine();
				long num = TimeHelper.Now();
				if (self.ActivityData.StartTime >= num)
				{
					self.OnDay = -1;
				}
				else
				{
					self.OnDay = TimeHelper.DaysBetween(TimeHelper.Now(), self.ActivityData.StartTime, 18000000L);
				}
				self.InitPanel().Coroutine();
				self.InitScore();
				self.InitActivityTime();
			}
		}

