		private static int GetDefalutDay(this UISevenDayTargetPanel self)
		{
			SevenDayTargetModule component = ((Entity)self.ActivityData).GetComponent<SevenDayTargetModule>();
			if (self.OnDay == -1)
			{
				return 1;
			}
			foreach (var (num2, _) in component.TaskList)
			{
