			if (num3 > self.DayUIObjectDict.Count)
			{
				num3 = self.DayUIObjectDict.Count;
			}
			return num3;
		}

		private static int GetDefaultTab(this UISevenDayTargetPanel self)
		{
			foreach (var (num2, _) in self.TabUIObjectDict)
