		private static void SelectDay(this UISevenDayTargetPanel self, int day)
		{
			if (day > self.OnDay + 1 && self.OnDay != -1)
			{
				UIGameMsgHelper.FloatMsg("未解锁");
			}
			else
			{
				if (self.Day == day)
				{
					return;
				}
				self.Day = day;
				foreach (var (num2, self2) in self.DayUIObjectDict)
				{
					self2.Find("Select").SetActive(num2 == day);
				}
				self.SelectTab(self.GetDefaultTab());
			}
		}

		private static void UpdateRedPoint(this UISevenDayTargetPanel self)
		{
			int key;
			UIObject value;
			foreach (KeyValuePair<int, UIObject> item in self.DayUIObjectDict)
			{
				item.Deconstruct(out key, out value);
				int num = key;
