			}
			foreach (KeyValuePair<int, UIObject> item2 in self.TabUIObjectDict)
			{
				item2.Deconstruct(out key, out value);
				int num2 = key;
				value.SetRedPoint(RedPointType.Activity, self.ActivityData.ActivityId, self.Day, num2).Coroutine();
			}
		}

		private static void SelectTab(this UISevenDayTargetPanel self, int tab)
		{
			self.Tab = tab;
			foreach (var (num2, self2) in self.TabUIObjectDict)
			{
				self2.Find("Select").SetActive(num2 == tab);
			}
			self.UpdateView();
		}

		public static void UpdateViewByActivity(this UISevenDayTargetPanel self)
		{
			self.ActivityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActivityId);
			long num = TimeHelper.Now();
			if (self.ActivityData.StartTime >= num)
			{
				self.OnDay = -1;
			}
			else
			{
				self.OnDay = TimeHelper.DaysBetween(TimeHelper.Now(), self.ActivityData.StartTime, 18000000L);
			}
			foreach (var (num3, self2) in self.DayUIObjectDict)
			{
				self2.Find("Lock").SetActive(num3 > self.OnDay);
				self2.Find("LockImage").SetActive(num3 > self.OnDay);
			}
			self.UpdateView();
		}

		public static void UpdateView(this UISevenDayTargetPanel self)
		{
			self.UpdateRedPoint();
			self.UpdateScore();
			self.Configs = ConfigSingleton<SevenDayTargetConfigCategory>.Instance.GetConfigs(self.ActivityData.ActivityId, self.Day, self.Tab);
			self.Configs.Sort((SevenDayTargetConfig a, SevenDayTargetConfig b) => self.GetSort(a.Id) - self.GetSort(b.Id));
			self._List.SetData(self.Configs.Count);
		}

		public static int GetSort(this UISevenDayTargetPanel self, int configId)
		{
			SevenDayTargetData taskData = ((Entity)self.ActivityData).GetComponent<SevenDayTargetModule>().GetTaskData(configId);
			if (taskData == null)
			{
				return configId;
			}
			int num = configId;
			if (taskData.Status == 1)
			{
				num -= 10000000;
			}
			if (taskData.Status == 3)
			{
				num += 1000000;
			}
			return num;
		}

		private static void OnCellUpdate(this UISevenDayTargetPanel self, UIScrollListCell cell)
		{
			int index = cell.Index;
			((Entity)cell.UIObject).GetComponent<UISevenDayTargetItem>().SetData(self.ActivityData, self.Configs[index], self.Day, self.Tab);
		}

		private static void OnQuitClick(this UISevenDayTargetPanel self)
		{
			UIManager.Instance.Remove(self.UIObject);
		}
	}
