	{
		public override int GetCount(Scene scene, params int[] parameters)
		{
			ShopModule component = ((Entity)((Entity)(object)scene).LocalPlayer()).GetComponent<ShopModule>();
			ShopTypeConfig shopTypeConfig = ConfigSingleton<ShopTypeConfigCategory>.Instance.Get(7007);
			SubShop subShop = component.GetSubShop(7007);
			if (shopTypeConfig.RefreshPriceType != 0 && ConfigSingleton<PriceConfigCategory>.Instance.Get(shopTypeConfig.RefreshPriceType, subShop.RefreshCount + 1).Price == null)
			{
				return 1;
			}
			List<int> goodsIds = subShop.GoodsIds;
			if (goodsIds != null && goodsIds.Count > 0)
			{
				for (int i = 0; i < subShop.GoodsIds.Count; i++)
				{
					int num = subShop.GoodsIds[i];
					ShopGoodsConfig shopGoodsConfig = ConfigSingleton<ShopGoodsConfigCategory>.Instance.Get(num);
					if (shopGoodsConfig != null && shopGoodsConfig.Price == 0)
					{
						ShopBuyData orCreateBuyData = subShop.GetOrCreateBuyData(num);
						if (shopGoodsConfig.LimitType <= 0 || orCreateBuyData.BuyCount < shopGoodsConfig.LimitBuyTime)
						{
							return 1;
						}
					}
				}
			}
			return 0;
		}
	}
