			{
				UIDressSuitItem component = ((Entity)uiObj).GetComponent<UIDressSuitItem>();
				component.SetData(dressIds[i]);
				component._UICommonItem.SetClickDisabled();
			}).Coroutine();
			self.SuitStatStructList.Clear();
			self.SuitStatStructList.AddRange(fashionSuitConfig.Stats);
			self._UISuitCommonList.SetData(self.SuitStatStructList.Count);
			bool flag2 = DressHelper.IsActiveDressSuit(((Entity)(object)self).LocalPlayer(), fashionConfig.SuitId);
			self._ActiveText.SetText(flag2 ? "已激活" : "未激活");
			self._ActiveText.SetColor(flag2 ? new Color(0.61f, 1f, 0.44f) : new Color(0.66f, 0.66f, 0.66f));
			LayoutRebuilder.ForceRebuildLayoutImmediate(((Component)self._SuitBg.Transform).GetComponent<RectTransform>());
			LayoutRebuilder.ForceRebuildLayoutImmediate(((Component)self.UIObject.Transform).GetComponent<RectTransform>());
