		private static void InitBind(this UIShopPanel self)
		{
			Player player = ((Entity)(object)self).LocalPlayer();
			((Entity)player).GetComponent<ShopModule>();
			((Entity)player).GetComponent<ItemModule>();
			((Entity)(object)self).BindData("CurrentShopId", delegate(int _, int currentShopId)
			{
				ShopTypeConfig shopTypeConfig = ConfigSingleton<ShopTypeConfigCategory>.Instance.Get(currentShopId);
				self._Top3.SetActive(currentShopId == 7004);
				switch ((UIShopStyle)shopTypeConfig.Style)
				{
				case UIShopStyle.Normal:
					self._Top1.SetActive(active: true);
					self._Top2.SetActive(active: false);
					self._Top1Bg.SetRawTexture("ui_shop2_bg_05").Coroutine();
					if (!string.IsNullOrEmpty(shopTypeConfig.TitleImage))
					{
						self._TitleImage.SetRawTexture(shopTypeConfig.TitleImage, nativeSize: true).Coroutine();
					}
					break;
				case UIShopStyle.BlackMarket:
					self._Top1.SetActive(active: false);
					self._Top2.SetActive(active: true);
					self._Top2Bg.SetRawTexture("ui_shop2_bg_01").Coroutine();
					break;
				}
			}, () => self.CurrentShopId);
		}

		private static void OnTabClick(this UIShopPanel self, int index, UIObject uiObject)
