		public static void OnClickManagerButton(this UIShoppingCartView self)
		{
			self.IsManager = !self.IsManager;
			self.UpdateView();
		}

		public static void OnClickAllSelectButton(this UIShoppingCartView self)
		{
			self.IsCheckAll = !self.IsCheckAll;
			if (self.IsCheckAll)
			{
				if (self.SelectShopItemIdList.Count > 0)
				{
					self.CheckShopItemIdList = self.SelectShopItemIdList.Clone();
				}
				else
				{
					self.CheckShopItemIdList.Clear();
				}
			}
			else
			{
				self.CheckShopItemIdList.Clear();
			}
			UIObject.FindUIObjectOfType<UIShopSkinItemList>()?.OnClickBgCallBack(self.CheckShopItemIdList);
			self.UpdateView();
		}

		private static void OnCellUpdate(this UIShoppingCartView self, UIScrollListCell cell)
		{
			UIShoppingItem component = ((Entity)cell.UIObject).GetComponent<UIShoppingItem>();
			int num = self.SelectShopItemIdList[cell.Index];
			bool isOn = self.CheckShopItemIdList.Contains(num);
			component.SetData(num, isOn);
		}

		public static void OnClickItem(this UIShoppingCartView self, int goodsId)
		{
			if (self.CheckShopItemIdList.Contains(goodsId))
			{
				self.CheckShopItemIdList.Remove(goodsId);
			}
			else
			{
				self.CheckShopItemIdList.Add(goodsId);
			}
			self.IsCheckAll = self.CheckShopItemIdList.Count == self.SelectShopItemIdList.Count;
			self.UpdateView();
			UIObject.FindUIObjectOfType<UIShopSkinItemList>()?.OnClickBgCallBack(goodsId);
		}
	}
