		public static void SetTimer(this UIShopRefreshTimeText self, int shopId, Action callback)
		{
			if (self.TimerHandler > 0)
			{
				self.RemoveTimer(ref self.TimerHandler);
			}
			if (self.RefreshTimer > 0)
			{
				self.RemoveTimer(ref self.RefreshTimer);
			}
			ShopRefreshTimeType refreshTimeType = (ShopRefreshTimeType)ConfigSingleton<ShopTypeConfigCategory>.Instance.Get(shopId).RefreshTimeType;
			self.UIObject.SetActive(refreshTimeType != ShopRefreshTimeType.Never);
			switch (refreshTimeType)
			{
			case ShopRefreshTimeType.Day:
				self.TimerHandler = self.NewTimer(1000L, RefreshTimeDay, repeat: true);
				RefreshTimeDay();
				self.RefreshTimer = self.NewTimer(TimeHelper.GetDurationToEndDay(TimeHelper.Now(), 18000000L) + 3000, callback);
				break;
			case ShopRefreshTimeType.Week:
				self.TimerHandler = self.NewTimer(1000L, RefreshTimeWeek, repeat: true);
				RefreshTimeWeek();
				self.RefreshTimer = self.NewTimer(TimeHelper.GetDurationToEndWeek(TimeHelper.Now(), 18000000L) + 3000, callback);
				break;
			case ShopRefreshTimeType.Month:
				self.TimerHandler = self.NewTimer(1000L, RefreshTimeMonth, repeat: true);
				RefreshTimeMonth();
				self.RefreshTimer = self.NewTimer(TimeHelper.GetDurationToEndMonth(TimeHelper.Now(), 18000000L) + 3000, callback);
				break;
			case ShopRefreshTimeType.Year:
				self.TimerHandler = self.NewTimer(1000L, RefreshTimeYear, repeat: true);
				RefreshTimeYear();
				self.RefreshTimer = self.NewTimer(TimeHelper.GetYearEndTime() + 3000, callback);
				break;
			}
			void RefreshTimeDay()
			{
				string str = TimeSpan.FromSeconds((double)(TimeHelper.GetDurationToEndDay(TimeHelper.Now(), 18000000L) / 1000)).ToString("hh\\:mm\\:ss");
				self.UIObject.SetText(str);
			}
			void RefreshTimeMonth()
			{
				long durationToEndMonth = TimeHelper.GetDurationToEndMonth(TimeHelper.Now(), 18000000L);
				TimeSpan timeSpan = TimeSpan.FromSeconds((double)(durationToEndMonth / 1000));
				string str = ((durationToEndMonth < 86400000) ? timeSpan.ToString("hh\\:mm\\:ss") : timeSpan.ToString(Language.Get(2, 312)));
				self.UIObject.SetText(str);
			}
			void RefreshTimeWeek()
			{
				long durationToEndWeek = TimeHelper.GetDurationToEndWeek(TimeHelper.Now(), 18000000L);
				TimeSpan timeSpan = TimeSpan.FromSeconds((double)(durationToEndWeek / 1000));
				string str = ((durationToEndWeek < 86400000) ? timeSpan.ToString("hh\\:mm\\:ss") : timeSpan.ToString(Language.Get(2, 312)));
				self.UIObject.SetText(str);
			}
			void RefreshTimeYear()
			{
				long yearEndTime = TimeHelper.GetYearEndTime();
				TimeSpan timeSpan = TimeSpan.FromSeconds((double)(yearEndTime / 1000));
				string str = ((yearEndTime < 86400000) ? timeSpan.ToString("hh\\:mm\\:ss") : timeSpan.ToString(Language.Get(2, 312)));
				self.UIObject.SetText(str);
			}
		}
	}
