		private static string GetSetTextString(this UIShopSkinItemList self, int index)
		{
			if (self.AllStatStructList.Count <= index)
			{
				return string.Empty;
			}
			StatStruct stat = self.AllStatStructList[index];
			long value = self.StatStructList.GetValue(stat.Type, stat.Scope);
			long value2 = self.NextStatStructList.GetValue(stat.Type, stat.Scope);
			value2 -= value;
			string text = stat.GetName() + ":";
			if (value != 0L)
			{
				text = string.Format(text + " " + TextHelper.FormatStatValue(stat.Type, value), Array.Empty<object>());
			}
			if (value2 > 0)
			{
				text = string.Format(text + " <color=#0DB64D>+" + TextHelper.FormatStatValue(stat.Type, value2) + "</color> ", Array.Empty<object>());
			}
			return text;
		}

