		private static void UpdatePlayerAttr(this UIShopSkinItemList self)
		{
			DressModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<DressModule>();
			ItemStruct addItem = default(ItemStruct);
			foreach (int selectShopItemId in self.SelectShopItemIdList)
			{
				int useEffectId = self.GetUseEffectId(selectShopItemId);
				FashionConfig fashionConfig = ConfigSingleton<FashionConfigCategory>.Instance.Get(useEffectId);
				if (fashionConfig == null)
				{
					continue;
				}
				Dress child = ((Entity)component).GetChild<Dress>((long)fashionConfig.Id);
				int star = 0;
				FashionPowerConfig fashionPowerConfig = null;
				FashionPowerConfig fashionPowerConfig2 = null;
				ShopGoodsConfig shopGoodsConfig = ConfigSingleton<ShopGoodsConfigCategory>.Instance.Get(selectShopItemId);
				addItem.ConfigId = shopGoodsConfig.Item.Id;
				addItem.Nums = shopGoodsConfig.Item.Nums;
				if (child == null)
				{
					if (component.DressIsUnlockedOrUpStar(useEffectId, addItem))
					{
						fashionPowerConfig2 = ConfigSingleton<FashionPowerConfigCategory>.Instance.Get(fashionConfig.Id, star);
					}
				}
				else
				{
					fashionPowerConfig = ConfigSingleton<FashionPowerConfigCategory>.Instance.Get(fashionConfig.Id, child.Star);
					fashionPowerConfig2 = ((!component.DressIsUnlockedOrUpStar(useEffectId, addItem)) ? fashionPowerConfig : ConfigSingleton<FashionPowerConfigCategory>.Instance.Get(fashionConfig.Id, child.Star + 1));
				}
				if (fashionPowerConfig != null)
				{
					self.StatStructList.AddRange(fashionPowerConfig.Stats);
					self.AllStatStructList.AddRange(fashionPowerConfig.Stats);
				}
				if (fashionPowerConfig2 != null)
				{
					self.NextStatStructList.AddRange(fashionPowerConfig2.Stats);
					self.AllStatStructList.AddRange(fashionPowerConfig2.Stats);
				}
			}
		}

		private static int GetUseEffectId(this UIShopSkinItemList self, int ShipItemId)
		{
			ShopGoodsConfig shopGoodsConfig = ConfigSingleton<ShopGoodsConfigCategory>.Instance.Get(ShipItemId);
			if (shopGoodsConfig == null)
			{
				return 0;
			}
			ItemConfig itemConfig = ET.ItemHelper.GetItemConfig(shopGoodsConfig.Item.Id);
			if (itemConfig == null)
			{
				return 0;
			}
			return itemConfig.UseEffParams[0];
		}

		private static void UpdateHeroAttr(this UIShopSkinItemList self)
		{
			int useEffectId = self.GetUseEffectId(self.SelectShopItemId);
			if (ConfigSingleton<HeroSkinConfigCategory>.Instance.Get(useEffectId) == null)
			{
				return;
			}
			HeroSkinStarConfig heroSkinStarConfig = null;
			HeroSkinStarConfig heroSkinStarConfig2 = null;
			ItemStruct addItem = default(ItemStruct);
			HeroSkinModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<HeroSkinModule>();
			HeroSkin child = ((Entity)component).GetChild<HeroSkin>((long)useEffectId);
			ShopGoodsConfig shopGoodsConfig = ConfigSingleton<ShopGoodsConfigCategory>.Instance.Get(self.SelectShopItemId);
			addItem.ConfigId = shopGoodsConfig.Item.Id;
			addItem.Nums = shopGoodsConfig.Item.Nums;
			if (child == null)
			{
				if (component.HeroSkinIsUnlockedOrUpStar(useEffectId, addItem))
				{
					heroSkinStarConfig2 = HeroSkinHelper.GetSkinStarConfig(useEffectId, 0);
				}
			}
			else
			{
				heroSkinStarConfig = HeroSkinHelper.GetSkinStarConfig(useEffectId, child.Star);
				if (!((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ShopModule>().GetSubShop(7003).GetOrCreateBuyData(self.SelectShopItemId)
					.IsSellOut() && component.HeroSkinIsUnlockedOrUpStar(useEffectId, addItem))
				{
					heroSkinStarConfig2 = HeroSkinHelper.GetSkinStarConfig(useEffectId, child.Star + 1);
				}
			}
			if (heroSkinStarConfig != null)
			{
				self.StatStructList.AddRange(heroSkinStarConfig.BaseStats);
				self.AllStatStructList.AddRange(heroSkinStarConfig.BaseStats);
			}
			if (heroSkinStarConfig2 != null)
			{
				self.NextStatStructList.AddRange(heroSkinStarConfig2.BaseStats);
				self.AllStatStructList.AddRange(heroSkinStarConfig2.BaseStats);
			}
		}

		private static void UpdatePlayerModel(this UIShopSkinItemList self)
		{
			//IL_011b: Unknown result type (might be due to invalid IL or missing references)
			int modelId = ((Entity)(object)self).LocalPlayer().GetModelId();
			int weaponModelId = ((Entity)(object)self).LocalPlayer().GetWeaponModelId();
			int capeModelId = ((Entity)(object)self).LocalPlayer().GetCapeModelId();
			self.DressInfo.Fashion = modelId;
			self.DressInfo.Weapon = weaponModelId;
			self.DressInfo.Cape = capeModelId;
			foreach (int selectShopItemId in self.SelectShopItemIdList)
			{
				int useEffectId = self.GetUseEffectId(selectShopItemId);
				FashionConfig fashionConfig = ConfigSingleton<FashionConfigCategory>.Instance.Get(useEffectId);
				if (fashionConfig != null)
				{
					DressHelper.SetDress(self.DressInfo, fashionConfig.Type, fashionConfig.ModelId);
				}
			}
			self.ModelInfo.SetModel(self.DressInfo.Fashion);
			self.ModelInfo.SetWeapon(self.DressInfo.Weapon);
			self.ModelInfo.SetCape(self.DressInfo.Cape);
			self._UICommonModelPanel.ShowHighModel(self.ModelInfo, isDrag: true).Coroutine();
			self._UICommonModelPanel.SetCameraPosition(new Vector3(0f, 0f, -4.5f));
		}

		private static void UpdateHeroModel(this UIShopSkinItemList self)
		{
			if (self.GoodsIdDic.TryGetValue(self.CurrentShopId, out var value))
			{
				int num = value.IndexOf(self.SelectShopItemId);
				num = ((num >= 0) ? num : 0);
				self.OnClickSkinItem(num);
			}
		}

		public static void OnClickSkinItem(this UIShopSkinItemList self, int index)
		{
			//IL_0102: Unknown result type (might be due to invalid IL or missing references)
			//IL_00dc: Unknown result type (might be due to invalid IL or missing references)
			if (!self.GoodsIdDic.TryGetValue(self.CurrentShopId, out var value) || value.Count <= index)
			{
				return;
			}
			int shipItemId = value[index];
			int useEffectId = self.GetUseEffectId(shipItemId);
			HeroSkinConfig heroSkinConfig = ConfigSingleton<HeroSkinConfigCategory>.Instance.Get(useEffectId);
			if (heroSkinConfig != null)
			{
				if (self.SelectShopItemId == 0)
				{
					HeroConfig heroConfig = ConfigSingleton<HeroConfigCategory>.Instance.Get(heroSkinConfig.HeroId);
					self.HeroModelInfo.SetModel(heroConfig.ModelId);
				}
				else
				{
					self.HeroModelInfo.SetModel(heroSkinConfig.SpineModelId);
				}
				int[] location = heroSkinConfig.Location;
				if (location != null && location.Length == 3)
				{
					self.HeroModelInfo.Position = new Vector3((float)heroSkinConfig.Location[0] * 1f / 100f, (float)heroSkinConfig.Location[1] * 1f / 100f, (float)heroSkinConfig.Location[2] * 1f / 100f);
				}
				else
				{
					self.HeroModelInfo.Position = new Vector3(0f, 0.4f, 0f);
				}
				self._UICommonModelPanel.ShowHighModel(self.HeroModelInfo).Coroutine();
			}
		}

