	[RedPointHandler(RedPointType.Role_PracticeSkill)]
	public class PracticeSkillRedPointHandler : ARedPointHandler
	{
		public override int GetCount(Scene scene, params int[] parameters)
		{
			Player player = ((Entity)scene).GetComponent<LocalPlayerComponent>().Player;
			if (player == null)
			{
				return 0;
			}
			PracticeModule component = ((Entity)player).GetComponent<PracticeModule>();
			if (parameters == null || parameters.Length == 0)
			{
				if (!component.GetPracticeSkillRedMind())
				{
					return 0;
				}
				return 1;
			}
			int configId = parameters[0];
			if (component.IsCanUpgradeSkill(configId) != 0)
			{
				return 0;
			}
			return 1;
		}
	}
