		{
			self.ConfigId = configId;
			PracticeModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<PracticeModule>();
			int skillLevel = component.GetSkillLevel(configId);
			PracticeSkillLevelConfig skillConfig = component.GetSkillConfig(configId);
			self._SkillLevelText.SetText($"{skillConfig.Layer}重");
			self._Select.SetActive(isSelected);
			self._SkillLevel.SetActive(skillLevel != 0);
			self._Lock.SetActive(skillLevel == 0);
			self._LevelLock.SetActive(skillLevel == 0);
			self._SkillImage.SetGray(skillLevel == 0);
