			{
			case SkillIconTag.NormalTag:
				self._LeftTopImage.SetSprite("ui_xl_front_08").Coroutine();
				break;
			case SkillIconTag.UltimateTag:
				self._LeftTopImage.SetSprite("ui_xl_front_05").Coroutine();
				break;
			default:
				self._LeftTopImage.SetActive(active: false);
				break;
			}
			self._SkillImage.SetRawTexture(skillLevel2.Icon()).Coroutine();
			if (showRed)
			{
				self.UIObject.SetRedPoint(RedPointType.Role_PracticeSkill, configId).Coroutine();
			}
		}

