		private static void UpdateSkillInfo(this UISkillPanel self)
		{
			int configId = self.SkillConfigIdList[self.SelectIndex];
			PracticeModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<PracticeModule>();
			int skillLevel = component.GetSkillLevel(configId);
			PracticeSkillLevelConfig skillConfig = component.GetSkillConfig(configId);
			PracticeSkillLevelConfig nextSkillConfig = component.GetNextSkillConfig(configId);
			SkillLevel skillLevel2 = new SkillLevel(self.IsMainSkill ? skillConfig.TapSkillId : skillConfig.SkillId);
			self._SkillSimpleDesc.SetText("");
			if (skillLevel == 0)
			{
				self._SkillName.SetText(skillLevel2.Name() + " (未激活)");
				self._NextImage.SetActive(active: false);
				self._NextSkillName.SetActive(active: false);
				self._SkillDesc.SetText(skillLevel2.Description());
			}
			else if (nextSkillConfig != null && nextSkillConfig.Layer != skillConfig.Layer)
			{
				self._SkillName.SetText($"{skillLevel2.Name()}·{skillConfig.Layer}重");
				self._NextImage.SetActive(active: true);
				self._NextSkillName.SetActive(active: true);
				self._NextSkillName.SetText($"{skillLevel2.Name()}·{nextSkillConfig.Layer}重");
				SkillLevel skillLevel3 = new SkillLevel(self.IsMainSkill ? nextSkillConfig.TapSkillId : nextSkillConfig.SkillId);
				self._SkillDesc.SetText(skillLevel2.Description() ?? "");
				self._SkillSimpleDesc.SetText(skillLevel3.SimpleDesc());
			}
			else
			{
				if (nextSkillConfig == null)
				{
					self._SkillName.SetText($"{skillLevel2.Name()}·{skillConfig.Layer}重");
				}
				else
				{
					self._SkillName.SetText(string.Format("{0}·{1}重 <color=#5dfa49>({2}/{3})</color>", new object[4]
					{
						skillLevel2.Name(),
						skillConfig.Layer,
						skillConfig.level,
						PracticeHelper.GetMaxLevel(configId, skillLevel)
					}));
				}
				self._NextImage.SetActive(active: false);
				self._NextSkillName.SetActive(active: false);
				self._SkillDesc.SetText(skillLevel2.Description());
			}
			LayoutRebuilder.ForceRebuildLayoutImmediate(self._NameContent.Transform);
			self._TimeText.SetText(string.Format(ConfigSingleton<Lang2Category>.Instance.Get(120).Text, skillLevel2.CoolDown()));
			self._TimeImage.SetActive(skillLevel2.CoolDown() > 0f);
			SkillTagConfig[] tags = skillLevel2.SkillTags();
			self._TagImage.CloneAll(tags.Length, delegate(int i, UIObject o)
			{
				o.SetSprite(tags[i].Icon).Coroutine();
				o.Find("_TagName").SetText(tags[i].Name);
			}).Coroutine();
			self._ShowKillBtn.GameObject.transform.SetSiblingIndex(self._Layout.GameObject.transform.childCount - 1);
		}

		private static void UpdateCost(this UISkillPanel self)
		{
			int configId = self.SkillConfigIdList[self.SelectIndex];
			PracticeModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<PracticeModule>();
			PracticeSkillLevelConfig skillConfig = component.GetSkillConfig(configId);
			PracticeSkillLevelConfig nextSkillConfig = component.GetNextSkillConfig(configId);
			int skillLevel = component.GetSkillLevel(configId);
			self._CondText.SetActive(active: false);
			if (nextSkillConfig == null || skillLevel == 0)
			{
				self._Cost.UIObject.SetActive(active: false);
			}
			else if (!((Entity)(object)self).LocalPlayer().CheckAllConds(skillConfig.Conds))
			{
				self._Cost.UIObject.SetActive(active: false);
				self._CondText.SetActive(active: true);
				self._CondText.SetText(((Entity)(object)self).LocalPlayer().GetCondText(skillConfig.Conds));
			}
			else
			{
				self._Cost.UIObject.SetActive(active: true);
				self._Cost.SetData(skillConfig.CostId[0]);
			}
		}

		private static void UpdateStat(this UISkillPanel self)
		{
			int configId = self.SkillConfigIdList[self.SelectIndex];
			PracticeModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<PracticeModule>();
			PracticeSkillLevelConfig skillConfig = component.GetSkillConfig(configId);
			PracticeSkillLevelConfig nextSkillConfig = component.GetNextSkillConfig(configId);
			Stat[] stats = skillConfig.Stats;
			if (stats != null && stats.Length > 0)
			{
				self._StatText.SetActive(active: true);
				if (nextSkillConfig != null)
				{
					using (StatList statList = StatList.Create())
					{
						statList.AddRange(skillConfig.Stats);
						using StatList statList2 = StatList.Create();
						VibesHelper.SetStatZero(statList2, statList);
						statList2.AddRange(nextSkillConfig.Stats);
						statList2.ReduceRange(skillConfig.Stats);
						self.SetStatText(self._StatText, statList, statList2);
						return;
					}
				}
				self.SetStatText(self._StatText, skillConfig.Stats);
			}
			else
			{
				self._StatText.SetActive(active: false);
			}
		}

		private static void SetStatText(this UISkillPanel self, UIObject text, StatList statList, StatList addStatList)
		{
			string text2 = "属性：";
			for (int i = 0; i < addStatList.Count; i++)
			{
				StatStruct stat = addStatList[i];
				long value = statList.GetValue(stat.Type);
				long value2 = stat.Value;
				text2 += string.Format("<color=#c0eeff>{0}{1}</color><color=#5dfa49>{2}</color>", stat.GetName(), value, (value2 > 0) ? ("+" + stat.GetValueText()) : "");
				text2 += "  ";
			}
			text.SetText(text2);
		}

		private static void SetStatText(this UISkillPanel self, UIObject text, Stat[] stats)
		{
			string text2 = "属性：";
			foreach (Stat stat in stats)
			{
				text2 += $"<color=#c0eeff>{stat.GetName()}</color><color=#5dfa49>{stat.Value}</color>";
				text2 += "  ";
			}
			text.SetText(text2);
		}

		private static void UpdateButton(this UISkillPanel self)
		{
			//IL_015a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0160: Unknown result type (might be due to invalid IL or missing references)
			//IL_0164: Unknown result type (might be due to invalid IL or missing references)
			//IL_016a: Unknown result type (might be due to invalid IL or missing references)
			int num = self.SkillConfigIdList[self.SelectIndex];
			PracticeModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<PracticeModule>();
			PracticeSkillLevelConfig skillConfig = component.GetSkillConfig(num);
			PracticeSkillLevelConfig nextSkillConfig = component.GetNextSkillConfig(num);
			int skillLevel = component.GetSkillLevel(num);
			PracticeSkillConfig practiceSkillConfig = ConfigSingleton<PracticeSkillConfigCategory>.Instance.Get(num);
			self._ChangeButton.SetActive(practiceSkillConfig.IsShow);
			self._UpgradeButton.SetRedPoint(RedPointType.Role_PracticeSkill, num).Coroutine();
			self._MaxLevel.SetActive(active: false);
			if (nextSkillConfig == null)
			{
				self._UpgradeButton.SetActive(active: false);
