				return;
			}
			self._UpgradeText.SetText((nextSkillConfig.Layer != skillConfig.Layer) ? "突破" : "升级");
			int num2 = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<PracticeModule>().IsCanUpgradeSkill(num);
			self._UpgradeButton.SetGray(num2 != 0);
			self._UpgradeButton.RemoveEffect("ui_fx_tongyonganniu_2");
			if (nextSkillConfig.Layer != skillConfig.Layer && num2 == 0)
			{
				self._UpgradeButton.PlayEffect("ui_fx_tongyonganniu_2");
			}
		}

