		private static void OnClickShowKillBtn(this UISkillPanel self)
		{
			int num = self.SkillConfigIdList[self.SelectIndex];
			PracticeModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<PracticeModule>();
			PracticeSkillLevelConfig skillConfig = component.GetSkillConfig(num);
			int num2 = num * 10000;
			int num3 = (num + 1) * 10000;
			List<UIJewelrySkillArgs> list = new List<UIJewelrySkillArgs>();
			int skillLevel = component.GetSkillLevel(num);
			foreach (PracticeSkillLevelConfig value in ConfigSingleton<PracticeSkillLevelConfigCategory>.Instance.GetAll().Values)
			{
				if (value.Id > num2 && value.Id < num3 && value.level == 0)
				{
					SkillLevel skillLevel2 = new SkillLevel(self.IsMainSkill ? value.TapSkillId : value.SkillId);
					string desc = skillLevel2.Description();
					int level = skillLevel2.Level;
					int quality = 0;
					if (value.Conds.Length != 0 && ConfigSingleton<PracticeConfigCategory>.Instance.Contain(value.Conds[0].intValue))
					{
						quality = ConfigSingleton<PracticeConfigCategory>.Instance.Get(value.Conds[0].intValue).Quality;
					}
					list.Add(new UIJewelrySkillArgs
					{
						star = 0,
						quality = quality,
						compare = value.Layer,
						name = skillLevel2.Name() + level + "重",
						desc = desc,
						level = level,
						style = 1,
						lockText = ((value.Id > skillConfig.Id || skillLevel == 0) ? value.CondText : string.Empty)
					});
				}
				if (value.Id > num3)
				{
					break;
				}
			}
			int quality2 = 0;
			int compare = ((skillLevel > 0) ? skillConfig.Layer : 0);
			if (skillConfig.Conds.Length != 0 && ConfigSingleton<PracticeConfigCategory>.Instance.Contain(skillConfig.Conds[0].intValue))
			{
				quality2 = ConfigSingleton<PracticeConfigCategory>.Instance.Get(skillConfig.Conds[0].intValue).Quality;
			}
			UIHJewelrySkillData args = new UIHJewelrySkillData
			{
				SkillId = skillConfig.SkillId,
				SkillList = list,
				Quality = quality2,
				Compare = compare
			};
			UIManager.Instance.Show<UIHeroJewelrySkillPanel, UIHJewelrySkillData>(args).Coroutine();
		}

