		private static void ShowUpLevel(this UISkillSuccessPanel self)
		{
			PracticeModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<PracticeModule>();
			PracticeSkillLevelConfig skillConfig = component.GetSkillConfig(self.ConfigId);
			PracticeSkillLevelConfig preSkillConfig = component.GetPreSkillConfig(self.ConfigId);
			self._UpGroup.SetActive(active: true);
			SkillLevel skillLevel = new SkillLevel(skillConfig.SkillId);
			self._NameText2.SetText($"{skillLevel.Name()}·{skillConfig.Layer}重");
			self._DescText2.SetText(skillLevel.Description());
			self._SkillIcon2.SetRawTexture(skillLevel.Icon()).Coroutine();
			SkillLevel skillLevel2 = new SkillLevel(preSkillConfig.SkillId);
			self._NameText1.SetText($"{skillLevel2.Name()}·{preSkillConfig.Layer}重");
			self._SkillIcon1.SetRawTexture(skillLevel2.Icon()).Coroutine();
			UIObject.FindUIObjectOfType<UICommonSuccessPanel>().SetTitle("uitex_xl_front_07");
		}

		private static void ShowStat(this UISkillSuccessPanel self, PracticeSkillLevelConfig lastStageConfig, PracticeSkillLevelConfig stageConfig)
		{
			StatList nextStatList = StatList.Create();
			try
			{
				nextStatList.AddRange(stageConfig.Stats);
				StatList statList = StatList.Create();
				try
				{
					VibesHelper.SetStatZero(statList, nextStatList);
					if (lastStageConfig != null)
					{
						statList.AddRange(lastStageConfig.Stats);
					}
					self._AttrItem.CloneAll(math.max(statList.Count, nextStatList.Count), delegate(int i, UIObject o)
					{
						UIObject self2 = o.Find("txtStat");
						UIObject self3 = o.Find("txtAdd");
						StatStruct stat = statList[i];
						ushort type = stat.Type;
						long value = stat.Value;
						long num = nextStatList.GetValue(type) - value;
						self2.SetText($"{stat.GetName()}:{value}");
						self3.SetText($"+{((num > 0) ? num : 0)}");
					}).Coroutine();
				}
				finally
				{
					if (statList != null)
					{
						((IDisposable)statList).Dispose();
					}
				}
			}
			finally
			{
				if (nextStatList != null)
				{
					((IDisposable)nextStatList).Dispose();
				}
			}
		}
	}
