			StrongTotalPowRewardConfig strongTotalPowRewardConfig = ConfigSingleton<StrongTotalPowRewardConfigCategory>.Instance.Get(powLevel);
			self._UICommonItem.SetItem(ConfigSingleton<DropShowConfigCategory>.Instance.Get(strongTotalPowRewardConfig.Prize_Id).Items[0].Id, ConfigSingleton<DropShowConfigCategory>.Instance.Get(strongTotalPowRewardConfig.Prize_Id).Items[0].Nums);
