		private static void ShowFailPanel(this UIDupResultStrongContent self, bool isOpenPayWay)
		{
			if (self.PayWayConfig == null || !isOpenPayWay)
			{
				return;
			}
			Player player = ((Entity)(object)self).LocalPlayer();
			StrongModule component = ((Entity)player).GetComponent<StrongModule>();
			if (player.CheckCond(ConfigSingleton<GlobalConfigCategory>.Instance.GetOne().PayWayCond))
			{
				int payWayShowNum = ConfigSingleton<GlobalConfigCategory>.Instance.GetOne().PayWayShowNum1;
				if (component.IsCanFailPopup(payWayShowNum))
				{
					if (ConfigSingleton<GlobalConfigCategory>.Instance.GetOne().PayWayIntervalNum1 > component.PopupIntervalTime1)
					{
						component.PopupIntervalTime1++;
						return;
					}
					self.OpenPayWay().Coroutine();
					component.ReqFailPopup();
					component.PopupIntervalTime1 = 0L;
				}
				return;
			}
			int payWayShowNum2 = ConfigSingleton<GlobalConfigCategory>.Instance.GetOne().PayWayShowNum;
			if (component.IsCanFailPopup(payWayShowNum2))
			{
				if (ConfigSingleton<GlobalConfigCategory>.Instance.GetOne().PayWayIntervalNum > component.PopupIntervalTime)
				{
					component.PopupIntervalTime++;
					return;
				}
				self.OpenPayWay().Coroutine();
				component.ReqFailPopup();
				component.PopupIntervalTime = 0L;
			}
		}

