	public static class UIStrongHelper
	{
		public static List<StrongObtainConfig> GetObtainConfigs(Player player, int type)
		{
			List<StrongObtainConfig> list = new List<StrongObtainConfig>();
			for (int i = type * 100 + 1; ConfigSingleton<StrongObtainConfigCategory>.Instance.Contain(i); i++)
			{
				StrongObtainConfig strongObtainConfig = ConfigSingleton<StrongObtainConfigCategory>.Instance.Get(i);
				if (player.CheckAllConds(strongObtainConfig.Conds))
				{
					list.Add(strongObtainConfig);
				}
			}
			return list;
		}

		public static List<StrongObtainConfig> GetObtainTypeConfigs()
		{
			List<StrongObtainConfig> list = new List<StrongObtainConfig>();
			for (int i = 1; ConfigSingleton<StrongObtainConfigCategory>.Instance.Contain(i * 100 + 1); i++)
			{
				list.Add(ConfigSingleton<StrongObtainConfigCategory>.Instance.Get(i * 100 + 1));
			}
			return list;
		}

		public static List<StrongSubStagePowConfig> GetStrongTypeConfigs()
		{
			List<StrongSubStagePowConfig> list = new List<StrongSubStagePowConfig>();
			for (int i = 1; ConfigSingleton<StrongSubStagePowConfigCategory>.Instance.Contain(i * 10000 + 100 + 1); i++)
			{
				list.Add(ConfigSingleton<StrongSubStagePowConfigCategory>.Instance.Get(i * 10000 + 100 + 1));
			}
			return list;
		}

		public static List<StrongSubStagePowConfig> GetStrongConfigs(int type, int level)
		{
			List<StrongSubStagePowConfig> list = new List<StrongSubStagePowConfig>();
			for (int i = 1; ConfigSingleton<StrongSubStagePowConfigCategory>.Instance.Contain(type * 10000 + i * 100 + 1); i++)
			{
				StrongSubStagePowConfig strongConfig = GetStrongConfig(type, i, level);
				list.Add(strongConfig);
			}
			return list;
		}

		public static StrongSubStagePowConfig GetStrongConfig(int type, int subType, int level)
		{
			int i = type * 10000 + subType * 100 + 1;
			StrongSubStagePowConfig result = null;
			for (; ConfigSingleton<StrongSubStagePowConfigCategory>.Instance.Contain(i); i++)
			{
				StrongSubStagePowConfig strongSubStagePowConfig = ConfigSingleton<StrongSubStagePowConfigCategory>.Instance.Get(i);
				if (strongSubStagePowConfig.PracticeLevel > level)
				{
					break;
				}
				result = strongSubStagePowConfig;
			}
			return result;
		}
	}
