		public static void SetData(this UISubModuleItem self, StrongSubStagePowConfig config)
		{
			self.Config = config;
			bool flag = ((Entity)(object)self).LocalPlayer().IsFuncOpen(config.SubFuncId);
			long num = (flag ? StrongHelper.GetNums(SceneHelper.DomainScene((Entity)(object)self), config.Type, config.SubType) : 0);
			int stage = self.GetStage(num);
			StrongSubModuleGradeConfig strongSubModuleGradeConfig = ConfigSingleton<StrongSubModuleGradeConfigCategory>.Instance.Get(stage);
			self._SubUnOpen.SetActive(!flag);
			self._SubStageImage.SetActive(flag);
			self._SubStageText.SetText(strongSubModuleGradeConfig.Stage_name);
			self._SubStageImage.SetSprite(strongSubModuleGradeConfig.Stage_Icon).Coroutine();
			self._GetWayButton.SetGray(!flag);
			self._SubModuleNum.SetText("战力 " + TextHelper.FormatPower(num));
			((Component)self._Slider.Transform).GetComponent<Slider>().value = (float)num / (float)config.Stage.Last();
			self._SubModuleDes.SetText(config.SubName);
		}

		private static int GetStage(this UISubModuleItem self, long power)
		{
			if (self.Config == null)
			{
				return 1;
			}
			int[] stage = self.Config.Stage;
			for (int i = 0; i < stage.Length; i++)
			{
				if (stage[i] > power)
				{
					return i + 1;
				}
			}
			return stage.Length;
		}

		public static void OnGetWayButtonClick(this UISubModuleItem self)
		{
			int jumpId = self.Config.JumpId;
			if (jumpId != 0)
			{
				UIManager.Instance.Remove(typeof(UIStrongPanel));
				UIJumpHelper.To(jumpId).Coroutine();
			}
		}
	}
