		private static void OnSetBoxList(this UISuccessiveExpenseNewPanel self)
		{
			Dictionary<int, SuccessiveExpenseConfig> all = ConfigSingleton<SuccessiveExpenseConfigCategory>.Instance.GetAll();
			self.Lists.Clear();
			foreach (SuccessiveExpenseConfig value in all.Values)
			{
				if (!self.Lists.Contains(value.Price) && self.ActId == value.ActId)
				{
					self.Lists.Add(value.Price);
				}
				self.Supplement.TryAdd(value.Price, value.Supplement);
			}
			ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId);
			SuccessiveExpenseModule component = ((Entity)activityData).GetComponent<SuccessiveExpenseModule>();
			int num = TimeHelper.DaysBetween(activityData.StartTime, TimeHelper.ServerNow(), 18000000L);
			int num2 = -1;
			foreach (SuccessiveExpenseConfig value2 in all.Values)
			{
				if (component.GetPayNumber(value2.Id) >= value2.Price && !component.IsGetSuccExpReward(value2.Id) && num >= value2.Gear && num2 == -1)
				{
					num2 = self.Lists.IndexOf(value2.Price);
					break;
				}
			}
			if (num2 == -1)
			{
				num2 = 0;
			}
			self.CurrentSelectIndex = num2;
			self._BoxList.SetData(self.Lists.Count);
			self._BoxList.SetSelectIndex(self.CurrentSelectIndex);
			self._BoxList.MovePanelToItemIndex(self._List.CurrentSelectIndex);
			self.OnInitViewList(self.Lists[self.CurrentSelectIndex]);
			((Component)self._BoxList.UIObject.Transform).GetComponent<RectTransform>().SetSizeWithCurrentAnchors((Axis)0, (float)(self.Lists.Count * 200));
		}

		private static void OnGearCellUpdate(this UISuccessiveExpenseNewPanel self, UIScrollListCell cell)
		{
			int index = cell.Index;
			if (index < self.Lists.Count)
			{
				UIObject uIObject = cell.UIObject;
				ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId);
				if (activityData != null)
				{
					SuccessiveExpenseModule component = ((Entity)activityData).GetComponent<SuccessiveExpenseModule>();
					UISuccessiveExpenseBox component2 = ((Entity)uIObject).GetComponent<UISuccessiveExpenseBox>();
					component2.SetData(component, self.Lists[index], index, self.ActivityData);
					component2.SetSelect(cell.IsSelected);
					component2.SetRefresh(self.OnInitList);
				}
			}
		}

		private static void OnClickItem(this UISuccessiveExpenseNewPanel self, int index, bool isSelected = false)
		{
			if (!((self.CurrentSelectIndex == index) & isSelected))
			{
				self.CurrentSelectIndex = index;
				self._BoxList.SetSelectIndex(index);
				UIScrollListCell cell = self._BoxList.GetCell(index);
				if (cell != null)
				{
					((Entity)cell.UIObject).GetComponent<UISuccessiveExpenseBox>().SetSelect(cell.IsSelected);
				}
			}
		}

		private static void OnInitViewList(this UISuccessiveExpenseNewPanel self, int price)
		{
			ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId);
			SuccessiveExpenseModule component = ((Entity)activityData).GetComponent<SuccessiveExpenseModule>();
			self.ViewLists.Clear();
			Dictionary<int, SuccessiveExpenseConfig> all = ConfigSingleton<SuccessiveExpenseConfigCategory>.Instance.GetAll();
			foreach (SuccessiveExpenseConfig value in all.Values)
			{
				if (value.Price == price && self.ActId == value.ActId && !component.IsGetSuccExpReward(value.Id) && component.GetPayNumber(value.Id) >= value.Price)
				{
					self.ViewLists.Add(value.Id);
				}
			}
			foreach (SuccessiveExpenseConfig value2 in all.Values)
			{
				if (value2.Price == price && self.ActId == value2.ActId && !component.IsGetSuccExpReward(value2.Id) && !self.ViewLists.Contains(value2.Id))
				{
					self.ViewLists.Add(value2.Id);
				}
			}
			foreach (SuccessiveExpenseConfig value3 in all.Values)
			{
				if (value3.Price == price && self.ActId == value3.ActId && !self.ViewLists.Contains(value3.Id))
				{
					self.ViewLists.Add(value3.Id);
				}
			}
			self._List.SetData(self.ViewLists.Count);
			RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.Activity, self.ActId);
			bool flag = false;
			int num = TimeHelper.DaysBetween(activityData.StartTime, TimeHelper.ServerNow(), 18000000L);
			if (num > 1)
			{
				foreach (SuccessiveExpenseConfig value4 in ConfigSingleton<SuccessiveExpenseConfigCategory>.Instance.GetAll().Values)
				{
					if (value4.Gear <= num - 1 && component.GetPayNumber(value4.Id) < value4.Price)
					{
						flag = true;
						break;
					}
				}
			}
			if (flag)
			{
				flag = self.Supplement[price];
			}
			self._TipsBox.SetActive(flag);
			self._List.UIObject.SetPosY(flag ? (-75) : (-40));
			self._TipsText.SetText(Language.Format(4, 760, self.Lists[self.CurrentSelectIndex]));
		}

		private static void OnCellUpdate(this UISuccessiveExpenseNewPanel self, UIScrollListCell cell)
		{
			int index = cell.Index;
			if (index < self.ViewLists.Count)
			{
				UIObject uIObject = cell.UIObject;
				int upConfigId = 0;
				if (index - 1 >= 0)
				{
					upConfigId = self.ViewLists[index - 1];
				}
				((Entity)uIObject).GetComponent<UISuccessiveExpenseCard>().SetData(self.ActId, self.ViewLists[index], upConfigId);
			}
		}

		private static void OnInitList(this UISuccessiveExpenseNewPanel self, int index)
		{
			self._TipsText.SetText(Language.Format(4, 760, self.Lists[index]));
			self.OnClickItem(index);
			self.OnInitViewList(self.Lists[index]);
		}

