	public static class UITaskHelper
	{
		public static string GetDesc(this TaskData self)
		{
			if (self.Config == null)
			{
				return "";
			}
			TaskConfig taskConfig = self.Config as TaskConfig;
			if (taskConfig.Type != 3)
			{
				return taskConfig.Desc;
			}
			string tempDesc = taskConfig.TempDesc;
			TaskFinishType finishType = (TaskFinishType)taskConfig.FinishType;
			int[] condParam = self.GetCondParam();
			switch (finishType)
			{
			case TaskFinishType.FinishType_1001:
			{
				PracticeConfig practiceConfig = ConfigSingleton<PracticeConfigCategory>.Instance.Get(self.MaxCount);
				tempDesc = string.Format(tempDesc, practiceConfig.Name);
				break;
			}
			case TaskFinishType.FinishType_1030:
				tempDesc = string.Format(tempDesc, GetJobDesc(condParam.GetValueOrDefault(0, 0)), self.MaxCount);
				break;
			case TaskFinishType.FinishType_1031:
				tempDesc = string.Format(tempDesc, GetJobDesc(condParam.GetValueOrDefault(0, 0)), self.MaxCount);
				break;
			case TaskFinishType.FinishType_1003:
				tempDesc = string.Format(tempDesc, self.MaxCount, condParam.GetValueOrDefault(0, 0));
				break;
			case TaskFinishType.FinishType_1016:
				tempDesc = string.Format(tempDesc, self.MaxCount, condParam.GetValueOrDefault(0, 0));
				break;
			default:
				tempDesc = string.Format(tempDesc, self.MaxCount);
				break;
			}
			return tempDesc + "<color={0}>({1}/{2})</color>";
		}

		private static string GetJobDesc(int job)
		{
			JobConfig jobConfig = ConfigSingleton<JobConfigCategory>.Instance.Get(job);
			if (jobConfig != null)
			{
				return jobConfig.Name;
			}
			if (job == -1)
			{
				return "总";
			}
			return "任意";
		}
	}
