				if (TaskHelper.IsActivityTask((TaskFinishType)taskConfig.FinishType))
				{
					ActivityData activityByType = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<PlayerActivityComponent>().GetActivityByType(TaskHelper.GetActivityType((TaskFinishType)taskConfig.FinishType));
					if (activityByType == null || activityByType.State != ActivityState.Open)
