		private static void OnQuickGetClick(this UITaskMainPanel self)
		{
			((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<TaskModule>().ReqGetChapter();
		}

		private static void OnGotoButtonClick(this UITaskMainPanel self)
		{
			UITaskPanel uITaskPanel = UIManager.Instance.Get<UITaskPanel>();
			GuideComponent component = ((Entity)SceneHelper.DomainScene((Entity)(object)self)).GetComponent<GuideComponent>();
			if (component.IsGuiding)
			{
				GuideStepConfig guideStepConfig = ConfigSingleton<GuideStepConfigCategory>.Instance.Get(component.StepId);
				if (guideStepConfig.PanelName == "UIMainBottomPanel" || guideStepConfig.PanelName == "UIMainPanel")
				{
					UIManager.Instance.Remove(uITaskPanel.UIObject);
					return;
				}
			}
			TaskModule component2 = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<TaskModule>();
			TaskData mainTask = component2.GetMainTask();
			TaskConfig taskConfig = ConfigSingleton<TaskConfigCategory>.Instance.Get(mainTask.Id);
			if (TaskHelper.IsActivityTask((TaskFinishType)taskConfig.FinishType))
			{
				ActivityData activityByType = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<PlayerActivityComponent>().GetActivityByType(TaskHelper.GetActivityType((TaskFinishType)taskConfig.FinishType));
				if (activityByType == null || activityByType.State != ActivityState.Open)
				{
					component2.ReqFinishMainTask();
					return;
				}
			}
			if (taskConfig.FinishType == 102)
			{
				component2.ReqFinishMainTask();
			}
			if (taskConfig.FinishType == 115)
			{
				component2.ReqGetMainTask();
			}
			UIJumpHelper.To(taskConfig.Goto, taskConfig.JumpParam).Coroutine();
			UIManager.Instance.Remove(uITaskPanel.UIObject);
		}

		private static void OnGetButtonClick(this UITaskMainPanel self)
		{
			TaskModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<TaskModule>();
			if (component.GetMainTask().Status != 1)
			{
				UIGameMsgHelper.FloatMsgByError(201401);
			}
			else
			{
				component.ReqGetMainTask();
			}
		}

		private static void InitPanel(this UITaskMainPanel self)
		{
			self.UpdateView();
		}

		public static void UpdateView(this UITaskMainPanel self)
		{
			TaskModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<TaskModule>();
			TaskData mainTask = component.GetMainTask();
			TaskMainConfig taskMainConfig = ConfigSingleton<TaskMainConfigCategory>.Instance.Get(component.GetChatperId());
			self._BoxImage.SetSprite(taskMainConfig.IconImg).Coroutine();
			self._BoxNameImage.SetSprite(taskMainConfig.Icon).Coroutine();
			if (taskMainConfig.DropId != 0)
			{
				using ItemList itemList = ItemList.Create();
				itemList.AddRange(ConfigSingleton<DropShowConfigCategory>.Instance.Get(taskMainConfig.DropId).Items);
				self._ChapterReward.SetData(itemList);
			}
			int num = taskMainConfig.Tasks.Length;
			int chapterStep = component.GetChapterStep();
			self._ProgressExp.GameObject.GetComponent<Slider>().value = (float)chapterStep * 1f / (float)num;
			self._ProgressText.SetText($"({chapterStep}/{num})");
			self._GetGroup.SetActive(active: false);
			self._UpGroup.SetActive(active: false);
			if (mainTask.Status == 3)
			{
				self._GetGroup.SetActive(active: true);
			}
			else
			{
				self._UpGroup.SetActive(active: true);
				self._GetButton.SetActive(mainTask.Status == 1);
				self._GotoButton.SetActive(mainTask.Status != 1);
				TaskConfig taskConfig = ConfigSingleton<TaskConfigCategory>.Instance.Get(mainTask.Id);
				self._TaskTitle.SetText(taskConfig.Title);
				string arg = ((mainTask.Status == 2) ? "#0db64d" : "#ff3232");
				self._ProgressText1.SetText(string.Format(taskConfig.Desc, arg, mainTask.Count, mainTask.MaxCount));
				using ItemList itemList2 = ItemList.Create();
				int valueOrDefault = taskConfig.DropId.GetValueOrDefault(mainTask.Stage, 0);
				itemList2.AddRange(ConfigSingleton<DropShowConfigCategory>.Instance.Get(valueOrDefault).Items);
				self._TaskReward.SetData(itemList2);
			}
			self._QuickGetButton.SetActive(!component.IsGetChapter);
		}
	}
