	[RedPointHandler(RedPointType.TeamDup)]
	public class TeamDupRedPointHandler : ARedPointHandler
	{
		public override int GetCount(Scene scene, params int[] parameters)
		{
			Player player = ((Entity)(object)scene).LocalPlayer();
			if (player == null)
			{
				return 0;
			}
			if (parameters == null || parameters.Length == 0)
			{
				return GetAll(player);
			}
			return ((parameters != null && parameters.Length > 0) ? parameters[0] : 0) switch
			{
				1 => GetLeftCount(player), 
				2 => GetRewardCount(player), 
				_ => 0, 
			};
		}

		public int GetAll(Player player)
		{
			if (GetLeftCount(player) > 0)
			{
				return 1;
			}
			if (GetRewardCount(player) > 0)
			{
				return 1;
			}
			return 0;
		}

		public int GetLeftCount(Player player)
		{
			if (((Entity)player).GetComponent<TeamDupModule>().GetLeftCount() > 0)
			{
				return 1;
			}
			return 0;
		}

		public int GetRewardCount(Player player)
		{
			if (((Entity)player).GetComponent<TeamDupModule>().IsCanGetBox() == 0)
			{
				return 1;
			}
			return 0;
		}
	}
