				PracticeConfig practiceConfig = ConfigSingleton<PracticeConfigCategory>.Instance.Get(component2.GetPracticeLevel());
				component.SetQuality(practiceConfig.Quality);
				component.SetName(practiceConfig.Name);
			}
		}
