		public static void SetData(this UITeamDupResultItem self, TeamMemberResultInfo info)
		{
			if (info == null)
			{
				self.UIObject.SetActive(active: false);
				return;
			}
			self.UIObject.SetActive(active: true);
			self.IsAddFriend = false;
			self.Info = info;
			TeamMemberInfo memberInfo = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<TeamDupModule>().GetMemberInfo(info.PlayerId);
			if (memberInfo == null && info.PlayerId != ((Entity)((Entity)(object)self).LocalPlayer()).Id)
			{
				self.UIObject.SetActive(active: false);
				return;
			}
			PlayerCommonInfo playerCommonInfo = null;
			if (info.PlayerId == ((Entity)((Entity)(object)self).LocalPlayer()).Id)
			{
				self._FriendText.SetActive(active: false);
				self._AddFriendButton.SetActive(active: false);
				self._Head.SetData(((Entity)(object)self).LocalPlayer(), showPracticeLevel: false, IsShowPersonalInfo: false);
				self._NameText.SetText(((Entity)(object)self).LocalPlayer().GetName());
				self._Power.SetPower(((Entity)(object)self).LocalPlayer().GetPower());
			}
			else
			{
				playerCommonInfo = memberInfo.PlayerCommonInfo;
				bool flag = ((Entity)(object)self).LocalPlayer().IsFriend(info.PlayerId);
				self._FriendText.SetActive(flag);
				self._AddFriendButton.SetActive(!flag);
				self._Head.SetData(playerCommonInfo);
				self._NameText.SetText(playerCommonInfo.Name);
				self._Power.SetPower(playerCommonInfo.Power);
			}
			self._HurtText.SetText(TextHelper.FormatDamage(info.Damage) ?? "");
			long damage = info.Damage;
			long totalDamage = info.TotalDamage;
			((Slider)self._HurtPro.GameObject.GetComponent<SuperSlider>()).value = (float)damage * 1f / (float)totalDamage;
		}

		private static void OnAddFriendClick(this UITeamDupResultItem self)
		{
			if (self.Info != null && !self.IsAddFriend)
			{
				((Entity)(object)self).LocalPlayer().AddFriend(self.Info.PlayerId);
				self._AddFriendButton.SetGray();
				UIGameMsgHelper.FloatMsg("已发送邀请");
				self.IsAddFriend = true;
			}
		}
	}
