		public static void BeforeStartAniData(this UIThreeRealmsTreaBollItem self)
		{
			ThreeRealmsTreasureModule component = ((Entity)self.ActivityData).GetComponent<ThreeRealmsTreasureModule>();
			if (component.RerwadItem == null || !component.RerwadItem.TryGetValue(self.BigConfigId, out var value))
			{
				return;
			}
			if (value == component.LastWishPoolId)
			{
				ThreeRealmsTreasureWishPoolConfig threeRealmsTreasureWishPoolConfig = ConfigSingleton<ThreeRealmsTreasureWishPoolConfigCategory>.Instance.Get(component.LastWishPoolId);
				self._UICommonItem.SetItem(threeRealmsTreasureWishPoolConfig.RewardItems);
				self._UICommonItem.UIObject.SetActive(active: true);
				return;
			}
			ThreeRealmsTreasureSmallPoolConfig threeRealmsTreasureSmallPoolConfig = ConfigSingleton<ThreeRealmsTreasureSmallPoolConfigCategory>.Instance.Get(value);
			if (threeRealmsTreasureSmallPoolConfig != null)
			{
				if (threeRealmsTreasureSmallPoolConfig.RewardItem != null)
				{
					self._UICommonItem.SetItem(threeRealmsTreasureSmallPoolConfig.RewardItem);
					self._UICommonItem.UIObject.SetActive(active: true);
				}
				else
				{
					self._BeilvText.SetText($"x{threeRealmsTreasureSmallPoolConfig.Magnification}");
					self._BeilvText.SetActive(active: true);
				}
			}
		}

		public static void AfterDoRaffleData(this UIThreeRealmsTreaBollItem self, int bigConfigId, bool showEffect = false)
		{
			self._DajiangEff.SetActive(active: false);
			self._BaoEff.SetActive(active: false);
			ThreeRealmsTreasureModule component = ((Entity)self.ActivityData).GetComponent<ThreeRealmsTreasureModule>();
			if (component.RaffledRerwad == null || component.RerwadItem == null || !component.RaffledRerwad.TryGetValue(bigConfigId, out var value) || !component.RerwadItem.TryGetValue(value, out var value2))
			{
				return;
			}
			if (value2 == component.LastWishPoolId)
			{
				ThreeRealmsTreasureWishPoolConfig threeRealmsTreasureWishPoolConfig = ConfigSingleton<ThreeRealmsTreasureWishPoolConfigCategory>.Instance.Get(component.LastWishPoolId);
				self._UICommonItem.SetItem(threeRealmsTreasureWishPoolConfig.RewardItems);
				self._UICommonItem.UIObject.SetActive(component.RaffledRerwad.TryGetValue(bigConfigId, out var value3));
				self.Play(value3);
				self._DajiangEff.SetActive(active: true);
				self._BaoEff.SetActive(active: true);
				if (showEffect)
				{
					UIObject.FindUIObjectOfType<UIThreeRealmsTreasurePanel>()?.GetLastWishPool(bigConfigId);
				}
				return;
			}
			ThreeRealmsTreasureSmallPoolConfig threeRealmsTreasureSmallPoolConfig = ConfigSingleton<ThreeRealmsTreasureSmallPoolConfigCategory>.Instance.Get(value2);
			if (threeRealmsTreasureSmallPoolConfig.RewardItem != null)
			{
				self._UICommonItem.SetItem(threeRealmsTreasureSmallPoolConfig.RewardItem);
				self._UICommonItem.UIObject.SetActive(component.RaffledRerwad.TryGetValue(bigConfigId, out var value4));
				self.Play(value4);
				return;
			}
			self._BeilvText.SetText($"x{threeRealmsTreasureSmallPoolConfig.Magnification}");
			self._BeilvText.SetActive(component.RaffledRerwad.TryGetValue(bigConfigId, out var _));
			if (showEffect)
			{
				UIObject.FindUIObjectOfType<UIThreeRealmsTreasurePanel>()?.GetBeilv(bigConfigId);
			}
		}

		public static void Play(this UIThreeRealmsTreaBollItem self, int value)
		{
			ThreeRealmsTreasureModule component = ((Entity)self.ActivityData).GetComponent<ThreeRealmsTreasureModule>();
			if (component.RaffleProReward != null)
			{
				int valueOrDefault = component.RaffleProReward.GetValueOrDefault(value);
				if (valueOrDefault != 0)
				{
					self._UIBollBeiText.UIObject.Find("UIBollBeiBigText").SetText($"x{valueOrDefault}");
					self._UIBollBeiText.UIObject.SetActive(active: true);
					self.Animation["animation_UIThreeRealmsTreaBollItem"].time = 0f;
					self.Animation.Sample();
					self.Animation.Play("animation_UIThreeRealmsTreaBollItem");
				}
			}
		}

