		public static void SetRuleData(this UIThreeRealmsTreaPreRewardItem self, int key)
		{
			ThreeRealmsTreasureSmallPoolConfig threeRealmsTreasureSmallPoolConfig = ConfigSingleton<ThreeRealmsTreasureSmallPoolConfigCategory>.Instance.Get(key);
			if (threeRealmsTreasureSmallPoolConfig != null)
			{
				self._UICommonItem.UIObject.SetActive(active: false);
				self._BeiLv.SetActive(active: false);
				if (threeRealmsTreasureSmallPoolConfig.RewardItem != null)
				{
					self._UICommonItem.SetItem(threeRealmsTreasureSmallPoolConfig.RewardItem);
					self._UICommonItem.UIObject.SetActive(active: true);
				}
				else
				{
					self._BeilvText.SetText($"x{threeRealmsTreasureSmallPoolConfig.Magnification}");
					self._BeiLv.SetActive(active: true);
				}
			}
		}

		public static void SetPyramidRuleData(this UIThreeRealmsTreaPreRewardItem self, WrapItem wrapItem, bool IsUnSelect)
		{
			self._BeiLv.SetActive(active: false);
			self._UICommonItem.UIObject.SetActive(!IsUnSelect);
			self._Pyramid.SetActive(IsUnSelect);
			if (!IsUnSelect)
			{
				self._UICommonItem.SetItem(wrapItem.Id, wrapItem.Nums);
			}
		}

		public static void SetData(this UIThreeRealmsTreaPreRewardItem self, int actId, int bigConfigId)
		{
			self.ActId = actId;
			self.ActivityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), actId);
			self.BigConfigId = bigConfigId;
			self._BeiLvText.SetActive(active: false);
			self.ShowData();
			self.ShowOutImg();
		}

		public static void ShowData(this UIThreeRealmsTreaPreRewardItem self)
		{
			ThreeRealmsTreasureModule component = ((Entity)self.ActivityData).GetComponent<ThreeRealmsTreasureModule>();
			if (!component.RerwadItem.TryGetValue(self.BigConfigId, out var value))
			{
				return;
			}
			if (value == component.LastWishPoolId)
			{
				ThreeRealmsTreasureWishPoolConfig threeRealmsTreasureWishPoolConfig = ConfigSingleton<ThreeRealmsTreasureWishPoolConfigCategory>.Instance.Get(component.LastWishPoolId);
				self._UICommonItem.SetItem(threeRealmsTreasureWishPoolConfig.RewardItems);
				self._UICommonItem.UIObject.SetActive(active: true);
				self.ShowBeilv();
				return;
			}
			ThreeRealmsTreasureSmallPoolConfig threeRealmsTreasureSmallPoolConfig = ConfigSingleton<ThreeRealmsTreasureSmallPoolConfigCategory>.Instance.Get(value);
			if (threeRealmsTreasureSmallPoolConfig != null)
			{
				if (threeRealmsTreasureSmallPoolConfig.RewardItem != null)
				{
					self._UICommonItem.SetItem(threeRealmsTreasureSmallPoolConfig.RewardItem);
					self._UICommonItem.UIObject.SetActive(active: true);
					self.ShowBeilv();
				}
				else
				{
					self._BeilvText.SetText($"x{threeRealmsTreasureSmallPoolConfig.Magnification}");
					self._BeiLv.SetActive(active: true);
				}
			}
		}

		private static void ShowBeilv(this UIThreeRealmsTreaPreRewardItem self)
		{
			ThreeRealmsTreasureModule component = ((Entity)self.ActivityData).GetComponent<ThreeRealmsTreasureModule>();
			if (component.RaffleProReward != null)
			{
				int valueOrDefault = component.RaffleProReward.GetValueOrDefault(self.BigConfigId);
				if (valueOrDefault != 0)
				{
					self._BeiLvText.SetText($"x{valueOrDefault}");
					self._BeiLvText.SetActive(active: true);
				}
			}
		}

		public static void ShowOutImg(this UIThreeRealmsTreaPreRewardItem self)
		{
			ThreeRealmsTreasureModule component = ((Entity)self.ActivityData).GetComponent<ThreeRealmsTreasureModule>();
			if (component.RaffledRerwad != null && component.RaffledRerwad.Values.Contains(self.BigConfigId))
			{
				self._RaffleOutImg.SetActive(active: true);
			}
		}
	}
