		public static void SetPyramidData(this UIThreeRealmsTreasureInfoItem self, WrapItem wrapItem, int index, ActivityData activityData, int foorIndex)
		{
			self._Bg.SetActive((index + 1) % 2 != 0);
			RaffleItem selectRewardDict = ((Entity)activityData).GetComponent<PyramidRepeatModule>().GetSelectRewardDict(foorIndex);
			self._RateInfoText.SetText($"{(float)wrapItem.Weight / 100f}%");
			if (wrapItem.Id == 0 && selectRewardDict.ItemId == 0)
			{
				self._DesText.SetText("自选物品");
				self._UIThreeRealmsTreaPreRewardItem.SetPyramidRuleData(new WrapItem
				{
					Id = selectRewardDict.ItemId,
					Nums = (int)selectRewardDict.Num,
					Weight = selectRewardDict.Weight
				}, IsUnSelect: true);
			}
			else if (selectRewardDict.ItemId != 0)
			{
				ItemConfig itemConfig = ConfigSingleton<ItemConfigCategory>.Instance.Get(selectRewardDict.ItemId);
				self._DesText.SetText(itemConfig.Name);
				self._UIThreeRealmsTreaPreRewardItem.SetPyramidRuleData(new WrapItem
				{
					Id = selectRewardDict.ItemId,
					Nums = (int)selectRewardDict.Num,
					Weight = selectRewardDict.Weight
				}, IsUnSelect: false);
			}
			else
			{
				ItemConfig itemConfig2 = ConfigSingleton<ItemConfigCategory>.Instance.Get(wrapItem.Id);
				self._DesText.SetText(itemConfig2.Name);
				self._UIThreeRealmsTreaPreRewardItem.SetPyramidRuleData(wrapItem, IsUnSelect: false);
			}
		}
	}
