		public static void UpdateView(this UIThreeRealmsTreasurePanel self, bool isAni = false)
		{
			ThreeRealmsTreasureModule component = ((Entity)self.ActivityData).GetComponent<ThreeRealmsTreasureModule>();
			self.BigConfigs?.Clear();
			foreach (var (_, threeRealmsTreasureBigPoolConfig2) in ConfigSingleton<ThreeRealmsTreasureBigPoolConfigCategory>.Instance.GetAll())
			{
				if (threeRealmsTreasureBigPoolConfig2.ActId == self.ActId && component.GetLastWishPoolId() == threeRealmsTreasureBigPoolConfig2.WishPoolId)
				{
					self.BigConfigs.Add(threeRealmsTreasureBigPoolConfig2);
				}
			}
			self.BigConfigs.Sort((ThreeRealmsTreasureBigPoolConfig a, ThreeRealmsTreasureBigPoolConfig b) => a.Id.CompareTo(b.Id));
			self.CurrentSelectWishPoolId = component.GetLastWishPoolId();
			self.SetRedPoint().Coroutine();
			self._SelectWishView.SetActive(component.IsRaffleOut());
			self._ResetWishBtn.SetActive(!component.IsRaffleOut());
			self.SetRaffleCountText();
			if (component.IsRaffleOut())
			{
				self._WishList.SetData(0);
				self._WishList.SetData(self.WishConfigs.Count);
				ThreeRealmsTreasureWishPoolConfig config = ConfigSingleton<ThreeRealmsTreasureWishPoolConfigCategory>.Instance.Get(component.GetLastWishPoolId());
				int index = self.WishConfigs.FindIndex((ThreeRealmsTreasureWishPoolConfig m) => m.Id == config.Id);
				self._WishList.SetSelectIndex(index);
				self.ShowWishInfo(isShow: false);
				self.HideShowBollItems(show: true, showData: false, hideItem: true);
			}
			else
			{
				self.ShowWishInfo(isShow: true);
				self.ShowBollItems(isAni).Coroutine();
			}
			self._UICommonRollingPanel.SetData(self.ActId, ActivityType.ThreeRealmsTreasure, isInsertNew: true).Coroutine();
		}

