		private static void SetRaffleCountText(this UIThreeRealmsTreasurePanel self)
		{
			ThreeRealmsTreasureModule component = ((Entity)self.ActivityData).GetComponent<ThreeRealmsTreasureModule>();
			List<ThreeRealmsTreasureBoxRewardConfig> list = ConfigSingleton<ThreeRealmsTreasureBoxRewardConfigCategory>.Instance.GetAll().Values.ToList();
			int num = 0;
			for (int i = 0; i < list.Count; i++)
			{
				if (self.ActId == list[i].ActId && component.RaffleAllCount >= list[i].RaffleCount)
				{
					num = i + 1;
				}
			}
			if (num > list.Count - 1)
			{
				num = list.Count - 1;
			}
			self._RaffleCountText.SetText($"{((component.RaffleAllCount > self.MaxBoxNumber) ? self.MaxBoxNumber : component.RaffleAllCount)}/{list[num].RaffleCount}");
		}

