	[RedPointHandler(RedPointType.Role_Tiangang)]
	public class TiangangRedPointHandler : ARedPointHandler
	{
		public override int GetCount(Scene scene, params int[] parameters)
		{
			Player player = ((Entity)scene).GetComponent<LocalPlayerComponent>().Player;
			if (player == null)
			{
				return 0;
			}
			foreach (Tiangang tiangang in ((Entity)player).GetComponent<TiangangModule>().GetTiangangs())
			{
				if (tiangang.IsCanActive(player) == 0)
				{
					return 1;
				}
				if (tiangang.IsCanBreak(player) == 0)
				{
					return 1;
				}
				if (tiangang.IsCanUp(player) == 0)
				{
					return 1;
				}
				if (tiangang.IsCanLade() == 0)
				{
					return 1;
				}
			}
			return 0;
		}
	}
