		public static void UpdateView(this UITiangangPanel self)
		{
			TiangangModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<TiangangModule>();
			Tiangang item = null;
			if (self.CurrentIndex != -1)
			{
				item = self.Tiangangs[self.CurrentIndex];
			}
			self.Tiangangs = component.GetTiangangs(self.IsLadeStatus);
			self.Tiangangs.Sort(delegate(Tiangang a, Tiangang b)
			{
				int sort = a.GetSort();
				return b.GetSort() - sort;
			});
			self._List.SetData(self.Tiangangs.Count);
			if (self.CurrentIndex != -1)
			{
				int num = self.Tiangangs.IndexOf(item);
				if (num == self.CurrentIndex)
				{
					self.SelectTiangang();
				}
