		public static void InitTab(this UITiangangSuitPanel self)
		{
			TiangangModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<TiangangModule>();
			List<UITabInfo> list = new List<UITabInfo>();
			Dictionary<int, TianGangElementConfig> all = ConfigSingleton<TianGangElementConfigCategory>.Instance.GetAll();
			int selectedTabIdOrIndex = 0;
			int num = 0;
			foreach (var (num3, tianGangElementConfig2) in all)
			{
				int elementCount = component.GetElementCount(num3);
				UITabInfo uITabInfo = UITabInfo.Create($"{tianGangElementConfig2.Name}({elementCount}/{component.GetElementNextCount(num3)})");
				uITabInfo.SetArgs(num3);
				if (elementCount > num)
				{
					num = elementCount;
					selectedTabIdOrIndex = list.Count;
				}
				list.Add(uITabInfo);
			}
			self.TabInfos = list.ToArray();
			((Entity)self).GetComponent<UICommonTab>().SetTabs(self.TabInfos, selectedTabIdOrIndex).Coroutine();
		}

		public static void OnTabClick(this UITiangangSuitPanel self, int index, UIObject uiObject)
		{
			int param = self.TabInfos[index].GetArgs().Param;
			List<TianGangSuitConfig> configs = TiangangHelper.GetSuitConfigs(param);
			self._SuitItem.UIObject.CloneAll(configs.Count, delegate(int i, UIObject o)
			{
				TianGangSuitConfig config = configs[i];
				((Entity)o).GetComponent<UITiangangSuitItem>().SetData(config);
			}).Coroutine();
			TiangangModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<TiangangModule>();
			UICommonTab component2 = ((Entity)self).GetComponent<UICommonTab>();
			for (int num = 0; num < component2.TabObjects.Count; num++)
			{
				UIObject self2 = component2.TabObjects[num];
				if (num == index)
				{
					self2.SetGray(isGray: false);
					continue;
				}
				int param2 = component2.CachedTabInfos[num].GetArgs().Param;
				self2.SetGray(!component.IsActiveSkill(param2));
			}
		}
	}
