			TotalActivityConfig totalActivityConfig = dictionary.Values.Last();
			foreach (TotalActivityConfig value in dictionary.Values)
			{
				if (component.PayCount < value.Money && !component.IsGetGear(value.Gear))
				{
					totalActivityConfig = value;
					break;
				}
			}
			int[] skipID = totalActivityConfig.SkipID;
			foreach (int num in skipID)
			{
				if (num == 0)
				{
					continue;
				}
				if (num > 0)
				{
					if (((Entity)(object)self).LocalPlayer().IsFuncOpen(num))
					{
						UIJumpHelper.To(num).Coroutine();
						break;
					}
					continue;
				}
				ActivityData activityData2 = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), -num);
				if (activityData2 != null && !activityData2.IsClose() && !UITotalExpenseHelp.IsMeetActivity(((Entity)(object)self).LocalPlayer(), activityData2))
				{
					UIJumpHelper.To(num).Coroutine();
					break;
				}
			}
		}
