	public static class UITotalExpenseHelp
	{
		public static bool IsMeetActivity(Player player, ActivityData activityData)
		{
			if (activityData != null)
			{
				switch (activityData.ActivityType)
				{
				case ActivityType.WeekCard:
					return ((Entity)activityData).GetComponent<WeekCardModule>().IsBuy();
				case ActivityType.GemStonePlan:
					return ((Entity)activityData).GetComponent<GemStonePlanModule>().IsSortOutGemStonePlanGifts();
				case ActivityType.GemStoneThemeGift:
					return ((Entity)activityData).GetComponent<GemStoneThemeGiftModule>().IsSortOut();
				case ActivityType.DirectBuyGift:
					return ((Entity)activityData).GetComponent<DirectBuyGiftModule>().IsBuyOver();
				case ActivityType.GrowthFund:
					return ((Entity)activityData).GetComponent<GrowthFundModule>().IsOver();
				case ActivityType.TaskFund:
					return ((Entity)activityData).GetComponent<GrowthFundGameplayModule>().IsBuyCard();
				case ActivityType.DirectBuyThemeGift:
					return ((Entity)activityData).GetComponent<DirectBuyThemeGiftModule>().IsBuyOver();
				case ActivityType.DirectBuyEveryDayGift:
					return ((Entity)activityData).GetComponent<DirectBuyEveryDayGiftModule>().IsBuyOver();
				case ActivityType.LoginGift:
					return ((Entity)activityData).GetComponent<LoginGiftModule>().IsBuy();
				case ActivityType.DirectBuySelectGift:
					return ((Entity)activityData).GetComponent<DirectBuySelectGiftModule>().IsBuyOver();
				case ActivityType.GrowthFundLevel:
					return ((Entity)activityData).GetComponent<GrowthFundLevelModule>().LiberalStatus;
				case ActivityType.GodWillStraight:
					return ((Entity)activityData).GetComponent<GodWillStraightModule>().IsBuyOver();
				case ActivityType.RedHeroUpStar:
					return ((Entity)activityData).GetComponent<RedHeroUpStarModule>().IsBuyOver();
				case ActivityType.KismetFetter:
					return ((Entity)activityData).GetComponent<KismetFetterModule>().IsOver();
				}
			}
			return false;
		}
	}
