		public static void OnGearChange(this UITotalExpensePanel self)
		{
			int index = self._List.CurrentSelectIndex;
			if (self._List.CurrentSelectIndex >= self.Lists.Count)
			{
				index = self.Lists.Count - 1;
			}
			int id = self.Lists[index];
			if (ConfigSingleton<TotalExpenseConfigCategory>.Instance.Get(id) != null)
			{
				self.InitList();
			}
		}

		public static void InitList(this UITotalExpensePanel self)
		{
			long num = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<RechargeModule>().GetPaidTotalMoney() / 100;
			Dictionary<int, TotalExpenseConfig> dictionary = ConfigSingleton<TotalExpenseConfigCategory>.Instance.GetDictionary(self.ActId);
			int num2 = 1;
			ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId);
			if (activityData == null)
			{
				return;
			}
			TotalExpenseModule component = ((Entity)activityData).GetComponent<TotalExpenseModule>();
			foreach (TotalExpenseConfig value in dictionary.Values)
			{
				if (num >= value.Money)
				{
					num2 = value.Gear;
					if (ConfigSingleton<TotalExpenseConfigCategory>.Instance.Contain(value.Id + 1))
					{
						num2 = ConfigSingleton<TotalExpenseConfigCategory>.Instance.Get(value.Id + 1).Gear;
					}
				}
			}
			int num3 = 0;
			int num4 = 0;
			TotalExpenseConfig config = dictionary.Values.First();
			self.Lists.Clear();
			foreach (TotalExpenseConfig value2 in dictionary.Values)
			{
				num3++;
				if (value2.Gear <= num2)
				{
					self.Lists.Add(value2.Id);
				}
				if (value2.Gear > num2)
				{
					break;
				}
			}
			bool flag = false;
			for (int i = 0; i < self.Lists.Count; i++)
			{
				TotalExpenseConfig totalExpenseConfig = ConfigSingleton<TotalExpenseConfigCategory>.Instance.Get(self.Lists[i]);
				if (totalExpenseConfig != null && num >= totalExpenseConfig.Money && !component.IsGetGear(totalExpenseConfig.Id))
				{
					flag = true;
					config = totalExpenseConfig;
					num4 = i;
					break;
				}
			}
			if (!flag)
			{
				for (int j = 0; j < self.Lists.Count; j++)
				{
					TotalExpenseConfig totalExpenseConfig2 = ConfigSingleton<TotalExpenseConfigCategory>.Instance.Get(self.Lists[j]);
					if (totalExpenseConfig2 != null)
					{
						if (num < totalExpenseConfig2.Money && !component.IsGetGear(totalExpenseConfig2.Id))
						{
							flag = true;
							config = totalExpenseConfig2;
							num4 = j;
							break;
						}
						if (num >= totalExpenseConfig2.Money && component.IsGetGear(totalExpenseConfig2.Id))
						{
							config = totalExpenseConfig2;
							num4 = j;
						}
					}
				}
			}
			self.CurrentSelectIndex = ((num4 >= num3) ? (num3 - 1) : num4);
			self._List.SetData(self.Lists.Count);
			self._List.SetSelectIndex(self.CurrentSelectIndex);
			self._List.MovePanelToItemIndex(self._List.CurrentSelectIndex);
			self.OnInitPanel(config);
			self.OnInitBtn(config);
			RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.Activity, self.ActId);
		}

		public static void OnUpdataList(this UITotalExpensePanel self)
		{
			self._List.RefreshView();
		}

		public static void OnCellUpdate(this UITotalExpensePanel self, UIScrollListCell cell)
		{
			int index = cell.Index;
			if (index < self.Lists.Count)
			{
				UIObject uIObject = cell.UIObject;
				ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId);
				if (activityData != null)
				{
					TotalExpenseModule component = ((Entity)activityData).GetComponent<TotalExpenseModule>();
					UITotalExpenseItem component2 = ((Entity)uIObject).GetComponent<UITotalExpenseItem>();
					component2.SetData(component, self.Lists[index], index);
					component2.SetSelect(cell.IsSelected);
					component2.SetRefresh(self.RefreshView);
				}
			}
		}

		private static void OnInitPanel(this UITotalExpensePanel self, TotalExpenseConfig _config)
		{
			ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), _config.ActId);
			if (activityData != null && !self._TimeGroup.IsSet())
			{
				self._TimeGroup.SetDate(activityData.EndTime);
			}
			self._mainImage.SetActive(active: false);
			self._mainImage.SetRawTexture(_config.Icon).Coroutine();
			self._mainImage.SetActive(active: true);
			self._TipsImage.SetRawTexture(_config.Titlemage).Coroutine();
			for (int i = 0; i < 3; i++)
			{
				UIObject uIObject = self._Group.Find("TipsText" + (i + 1));
				if (uIObject != null)
				{
					uIObject.SetText(_config.BigItemText[i]);
					uIObject.Transform.SetSizeWithCurrentAnchors((Axis)0, ((Text)uIObject.GameObject.GetComponent<SuperText>()).preferredWidth + 3f);
				}
			}
			self._TipsBtn.SetActive(_config.HeroTips > 0);
			ET.ConfigBeans.Item[] items = ConfigSingleton<TotalExpenseConfigCategory>.Instance.Get(_config.Id).Items;
			self._RewardList.SetData(items);
			self._RewardList.UIObject.Transform.SetSizeWithCurrentAnchors((Axis)0, (float)(items.Length * 10 + items.Length * 160));
			self._TipsText1.SetText(Language.Format(4, 746, _config.Money));
			self.configId = _config.Id;
		}

		private static void OnInitBtn(this UITotalExpensePanel self, TotalExpenseConfig _config)
		{
			self._GetBtn.SetData(_config, 2);
		}

		private static void RefreshView(this UITotalExpensePanel self, TotalExpenseConfig _config, int index)
		{
			self.OnInitPanel(_config);
			self._GetBtn.SetData(_config, 2);
			self.OnClickItem(index);
		}

		private static void OnBtnClick(this UITotalExpensePanel self)
		{
			if (self.configId > 0)
			{
				TotalExpenseConfig totalExpenseConfig = ConfigSingleton<TotalExpenseConfigCategory>.Instance.Get(self.configId);
				if (totalExpenseConfig != null && totalExpenseConfig.HeroTips > 0)
				{
					UIManager.Instance.Show<UIHeroMaxAttrPanel, (int, bool)>((totalExpenseConfig.HeroTips, true)).Coroutine();
				}
			}
		}

		private static void OnClickItem(this UITotalExpensePanel self, int index, bool isSelected = true)
		{
			if (!((self.CurrentSelectIndex == index) & isSelected))
			{
				self.CurrentSelectIndex = index;
				self._List.SetSelectIndex(index);
				UIScrollListCell cell = self._List.GetCell(index);
				if (cell != null)
				{
					((Entity)cell.UIObject).GetComponent<UITotalExpenseItem>().SetSelect(cell.IsSelected);
				}
			}
		}
	}
