			if (index < self.Lists.Count)
			{
				UIObject uIObject = cell.UIObject;
				ActivityData activityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), self.ActId);
				if (activityData != null)
				{
					TotalExpenseModule component = ((Entity)activityData).GetComponent<TotalExpenseModule>();
					UITotalExpenseItem component2 = ((Entity)uIObject).GetComponent<UITotalExpenseItem>();
					component2.SetData(component, self.Lists[index], index);
					component2.SetSelect(cell.IsSelected);
					component2.SetRefresh(self.RefreshView);
				}
			}
		}

		public static void OnGearChange(this UITotalExpenseView self)
		{
			int index = self._List.CurrentSelectIndex;
			if (self._List.CurrentSelectIndex >= self.Lists.Count)
			{
				index = self.Lists.Count - 1;
			}
			int id = self.Lists[index];
			if (ConfigSingleton<TotalExpenseConfigCategory>.Instance.Get(id) != null)
			{
				self.InitList();
			}
		}

