		public static void RefreshData(this UIBoxGroupWindow self)
		{
			TreaHouseTruntableModule component = ((Entity)self.ActivityData).GetComponent<TreaHouseTruntableModule>();
			foreach (var (num2, uIObject2) in self.ActivityBoxDict)
			{
				UITruntableRewardBox component2 = ((Entity)uIObject2).GetComponent<UITruntableRewardBox>();
				if (component.GetBoxRewardState(num2))
				{
					Log.Info($"RefreshData SetGet id === {num2}");
					component2.SetGet();
				}
				else if (num2 <= component.GetBoxGetId())
				{
					component2.SetReward();
					Log.Info($"RefreshData SetReward id === {num2}");
				}
			}
			self.CulSilderNum();
		}

		private static void CulSilderNum(this UIBoxGroupWindow self)
		{
			TreaHouseTruntableModule component = ((Entity)self.ActivityData).GetComponent<TreaHouseTruntableModule>();
			if (component == null)
			{
				return;
			}
			int trunNum = component.GetTrunNum();
			Log.Info($"CulSilderNum_count ==  {trunNum}");
			TreaHouseConfig treaHouseConfig = ConfigSingleton<TreaHouseConfigCategory>.Instance.Get(self.ActivityData.ActivityId);
			List<TreaHouseTurnBoxRewardConfig> list = new List<TreaHouseTurnBoxRewardConfig>();
			int[] boxReward = treaHouseConfig.BoxReward;
			foreach (int id in boxReward)
			{
				list.Add(ConfigSingleton<TreaHouseTurnBoxRewardConfigCategory>.Instance.Get(id));
			}
			int num = 0;
			for (int j = 0; j < list.Count; j++)
			{
				if (trunNum >= list[j].DrawCount)
				{
					num++;
				}
			}
			int count = list.Count;
			float num2 = (float)num * 1f / (float)count;
			float num3 = 0f;
			if (num < list.Count)
			{
				int num4 = 0;
				if (num == 0)
				{
					num4 = list[num].DrawCount;
					num3 = (float)trunNum * 1f / (float)num4 / (float)count;
				}
				else
				{
					num4 = list[num].DrawCount - list[num - 1].DrawCount;
					num3 = (float)(trunNum - list[num - 1].DrawCount) * 1f / (float)num4 / (float)count;
				}
			}
			Log.Info(string.Format("CulSilderNum_count ==== {0} , {1} ,     value=== {2},{3}", new object[4] { trunNum, num, num2, num3 }));
			((Slider)self.Slider).value = num2 + num3;
		}

