		private static bool CheckCanCallBackSpin(this UITreaHouseTruntablePanel self)
		{
			if (self.currentJadeNum > 0 && !((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().CheckItemNumsIsEnough(99, self.currentJadeNum))
