		}

		private static bool CheckCanSpin(this UITreaHouseTruntablePanel self)
		{
			((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>();
			TreaHouseConfig treaHouseConfig = ConfigSingleton<TreaHouseConfigCategory>.Instance.Get(self.ActId);
			Dictionary<int, TreaHouseTurnConfig> dictionary = new Dictionary<int, TreaHouseTurnConfig>();
			int[] drawCost = treaHouseConfig.DrawCost;
			foreach (int num in drawCost)
			{
				dictionary.Add(num, ConfigSingleton<TreaHouseTurnConfigCategory>.Instance.Get(num));
			}
			TreaHouseTurnConfig treaHouseTurnConfig = (self.IsTen ? dictionary.Last().Value : dictionary.First().Value);
			if (self.IsShowWishCoinGift() && !self.isDrectJadeBuy && !((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().CheckItemNumsIsEnough(treaHouseTurnConfig.LotteryItem.Id, treaHouseTurnConfig.LotteryItem.Nums))
			{
				UIManager.Instance.Show<UIWishCoinGiftPanel, TruntableDefine>(new TruntableDefine
				{
					activityId = self.ActId,
					Index = (self.IsTen ? dictionary.Last().Value.Id : dictionary.First().Value.Id),
					OnClickCallback = self.OnClickCallBack,
					RefreshCallback = self.ResreshCallBack
				}).Coroutine();
				return false;
			}
			if (!((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().CheckItemNumsIsEnough(treaHouseTurnConfig.JadeItem.Id, treaHouseTurnConfig.JadeItem.Nums) && !((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().CheckItemNumsIsEnough(treaHouseTurnConfig.LotteryItem.Id, treaHouseTurnConfig.LotteryItem.Nums))
			{
				UIObtainWayHelper.ShowPanelAsync(treaHouseTurnConfig.JadeItem).Coroutine();
				return false;
			}
			if (self.isSpinning)
			{
				return false;
			}
			if (!self.isDrectJadeBuy)
			{
				if (self.IsTen)
				{
					bool num2 = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().CheckItemNumsIsEnough(treaHouseTurnConfig.LotteryItem.Id, treaHouseTurnConfig.LotteryItem.Nums);
					long itemNumsByItemId = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().GetItemNumsByItemId(treaHouseTurnConfig.LotteryItem.Id);
					if (num2)
					{
						self.currentLotteryNum = treaHouseTurnConfig.LotteryItem.Nums;
					}
					else
					{
						self.currentLotteryNum = (int)itemNumsByItemId;
					}
				}
				else if (self.IsOneCostLottery)
				{
					self.currentLotteryNum = treaHouseTurnConfig.LotteryItem.Nums;
					self.currentJadeNum = 0;
				}
				else
				{
					self.currentLotteryNum = 0;
					self.currentJadeNum = treaHouseTurnConfig.JadeItem.Nums;
				}
			}
			return true;
		}

