		private static void ShowRewardInfo(this UITreaHouseTruntablePanel self)
		{
			self.isSpinning = false;
			self.DrawNum?.Clear();
			TreaHouseTruntableModule component = ((Entity)self.ActivityData).GetComponent<TreaHouseTruntableModule>();
			using ItemList itemList = ItemList.Create();
			foreach (int rewardId in self.RewardIds)
			{
				TreaHouseTurnItemConfig treaHouseTurnItemConfig = ConfigSingleton<TreaHouseTurnItemConfigCategory>.Instance.Get(rewardId);
				if (treaHouseTurnItemConfig.Percentage != 20 && treaHouseTurnItemConfig.Percentage != 50)
				{
					itemList.Add(new ItemStruct
					{
						ConfigId = treaHouseTurnItemConfig.Item.Id,
						Nums = treaHouseTurnItemConfig.Item.Nums
					});
				}
			}
			if (component.GetJadeRewardNum() > 0)
			{
				itemList.Add(new ItemStruct
				{
					ConfigId = 99,
					Nums = component.GetJadeRewardNum()
				});
			}
			if (!((Entity)(object)self).LocalPlayer().GetLocalBool("TreaHouseTurntableAnim"))
			{
				foreach (KeyValuePair<int, UIObject> item in self.ItemPositionsDict)
				{
					item.Deconstruct(out var _, out var value);
					TruntableItem component2 = ((Entity)value).GetComponent<TruntableItem>();
					if (component2 != null)
					{
						component2.SetSelectText(ActivityType.TreaHouseTruntable, 0);
						component2.SetSelectBg(isSelect: false, ActivityType.TreaHouseTruntable);
					}
				}
			}
			if (self._UICommonRollingPanel != null)
			{
				self._UICommonRollingPanel.SetData(self.ActId, ActivityType.TreaHouseTruntable, isInsertNew: true).Coroutine();
			}
			Singleton<EventSystem>.Instance.Publish<AddItems>(SceneHelper.DomainScene((Entity)(object)self), new AddItems
			{
				ItemList = itemList,
				Reason = 134
			});
		}

