		public static void RefreshData(this UIWishCoinGiftPanel self)
		{
			TreaHouseTurnConfig treaHouseTurnConfig = ConfigSingleton<TreaHouseTurnConfigCategory>.Instance.Get(self.ConfigIndex);
			self.delLotteryNum = (int)((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().GetItemNumsByItemId(treaHouseTurnConfig.LotteryItem.Id);
			self.lotteryNum = treaHouseTurnConfig.LotteryItem.Nums - self.delLotteryNum;
			if (self.lotteryNum <= 0)
			{
				self.lotteryNum = 0;
				self.jadeNum = 0;
			}
			else
			{
				self.jadeNum = treaHouseTurnConfig.JadeItem.Nums / treaHouseTurnConfig.LotteryItem.Nums * self.lotteryNum;
			}
			self._MessageText.SetText(string.Format(treaHouseTurnConfig.WishCoinGiftDes, self.jadeNum, self.lotteryNum));
			self._BuyMoneyText.SetText($"{self.jadeNum}");
		}

		[UIMethod]
		public static void OnShow(this UIWishCoinGiftPanel self, TruntableDefine define)
		{
			self.ConfigIndex = define.Index;
			self.ActId = define.activityId;
			self.CloseCallback = define.OnClickCallback;
			self.RefreshCallback = define.RefreshCallback;
			TreaHouseTurnConfig treaHouseTurnConfig = ConfigSingleton<TreaHouseTurnConfigCategory>.Instance.Get(self.ConfigIndex);
			self._IconImage.SetRawTexture($"uitex_icon_item_{ConfigSingleton<ItemConfigCategory>.Instance.Get(treaHouseTurnConfig.JadeItem.Id).Icon}").Coroutine();
			self.RefreshData();
			self.ChangeCanBuyGift();
			self.ShowGiftData();
			((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<TreasureHouseModule>();
			self._ChoiceBox.GameObject.GetComponent<Toggle>().isOn = false;
			((UnityEvent<bool>)(object)self._ChoiceBox.GameObject.GetComponent<Toggle>().onValueChanged).AddListener((UnityAction<bool>)delegate(bool isOn)
			{
				LocalData_Confirm localData = ((Entity)(object)self).LocalPlayer().GetLocalData<LocalData_Confirm>();
				if (isOn)
				{
					localData.Confirms["WishCoinGift"] = TimeHelper.EndTimeOfDay(TimeHelper.Now(), 18000000L);
				}
				else
				{
					localData.Confirms["WishCoinGift"] = 0L;
				}
				((Entity)(object)self).LocalPlayer().SetLocalData(localData);
				self.RefreshCallback?.Invoke();
			});
		}

		public static void ShowGiftData(this UIWishCoinGiftPanel self)
		{
			//IL_00a2: Unknown result type (might be due to invalid IL or missing references)
			if (self.config == null)
			{
				return;
			}
			self._BuyIcon.SetActive(self.config.GiftType == 1);
			self._GetBuyRed.UIObject.SetActive(self.config.GiftType == 3);
			if (self.config.GiftType == 3)
			{
				self._CostButton.SetSprite("ui_common_btn_36").Coroutine();
				self._BuyText.SetText(Language.Format(2, 500));
				((Component)self._BuyText.Transform).GetComponent<SuperOutline>().effectColor = new Color(1f / 85f, 0.3019608f, 0.1764706f);
				self._DiscountText.SetText($"{self.config.Discount}%");
			}
			else if (self.config.GiftType == 1)
			{
				self._BuyText.SetText((self.config.GiftPrice != null) ? self.config.GiftPrice.Nums.ToString() : "0");
				ItemModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>();
				self._GetBuyRed.UIObject.SetActive(component.CheckItemNumsIsEnough(self.config.GiftPrice));
				self._DiscountText.SetText(Language.Format(4, 841, (float)self.config.Discount / 100f));
			}
			else
			{
				PayConfig payConfig = ConfigSingleton<PayConfigCategory>.Instance.Get(self.config.PayId);
				if (payConfig == null)
				{
					Log.Error("商店id没找到，配置是否错误？");
				}
				self._BuyText.SetText(Language.Format(4, 744, payConfig.Price / 100));
				self._DiscountText.SetText($"{self.config.Discount}%");
			}
			self._DiscountImg.SetActive(self.config.Discount > 0);
			using ItemList itemList = ItemList.Create();
			itemList.AddRange(self.config.Item);
			self._UICommonHorizontalReward.SetData(itemList);
		}

		public static void ChangeCanBuyGift(this UIWishCoinGiftPanel self)
		{
			Dictionary<int, TreasureHouseConfig> all = ConfigSingleton<TreasureHouseConfigCategory>.Instance.GetAll();
			TreasureHouseModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<TreasureHouseModule>();
			Dictionary<int, int> giftState = component.GetGiftState(self.ActId);
			if (giftState == null || giftState.Count == 0)
			{
				self.config = all.First().Value;
				return;
			}
			bool flag = component.IsSortOutGift(self.ActId);
			if (flag)
			{
				self.config = all.Last().Value;
			}
			self._CostButton.SetGray(flag);
			foreach (var (key, num3) in giftState)
			{
				if (all.TryGetValue(key, out var value) && value.ActId == self.ActId && num3 < value.BuyCountLimit)
				{
					self.config = value;
					break;
				}
			}
		}

