		private static void OnBuyBtn(this UITreasureHoueseItem self)
		{
			Dictionary<int, int> giftState = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<TreasureHouseModule>().GetGiftState(self.ActId);
			if (giftState != null && giftState.TryGetValue(self.config.Id, out var value) && value >= self.config.BuyCountLimit)
			{
				UIGameMsgHelper.FloatMsgByError(206102);
				return;
			}
			if (self.config.GiftType == 1 && !((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().CheckItemNumsIsEnough(self.config.GiftPrice.Id, self.config.GiftPrice.Nums))
			{
				UIObtainWayHelper.ShowPanelAsync(self.config.GiftPrice, self._callback).Coroutine();
				return;
			}
			if (self.config.GiftType == 3 || self.config.GiftType == 2)
			{
				self.ReqBuy(self.config.Id, 1).Coroutine();
				return;
			}
			UIGiftHelper.ShowGemStoneGiftBuyPanel(self.ActId, ProductType.TreatureHouseGift, self.config.Id, delegate(int index, int num)
			{
				self.ReqBuy(index, num).Coroutine();
			});
		}

