		public static void RefreshList(this UITreasureHousePanel self)
		{
			self.configs?.Clear();
			Dictionary<int, TreasureHouseConfig> activityGiftConfigs = ConfigSingleton<TreasureHouseConfigCategory>.Instance.GetActivityGiftConfigs(self.ActId);
			Dictionary<int, int> giftState = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<TreasureHouseModule>().GetGiftState(self.ActId);
			int key;
			if (giftState == null || giftState.Count <= 0)
			{
				foreach (KeyValuePair<int, TreasureHouseConfig> item in activityGiftConfigs)
				{
					item.Deconstruct(out key, out var value);
					TreasureHouseConfig treasureHouseConfig = value;
					if (treasureHouseConfig.ActId == self.ActId)
					{
						self.configs.Add(treasureHouseConfig);
					}
				}
				self._ShopList.SetData(self.configs.Count);
				return;
			}
			List<TreasureHouseConfig> list = new List<TreasureHouseConfig>();
			foreach (KeyValuePair<int, int> item2 in giftState)
			{
				item2.Deconstruct(out key, out var value2);
				int key2 = key;
				int num = value2;
				TreasureHouseConfig valueOrDefault = activityGiftConfigs.GetValueOrDefault(key2);
				if (valueOrDefault != null)
				{
					if (num >= valueOrDefault.BuyCountLimit)
					{
						list.Add(valueOrDefault);
					}
					else
					{
						self.configs.Add(valueOrDefault);
					}
				}
			}
			List<TreasureHouseConfig> collection = list.OrderBy((TreasureHouseConfig x) => x.Id).ToList();
			self.configs.AddRange(collection);
			if (self.configs.Count <= 0)
			{
				Log.Info("天地豪礼 暂无数据。。");
			}
			else
			{
				self._ShopList.SetData(self.configs.Count);
			}
		}
	}
