		public static void UpdateView(this UIUniverseDupMainPanel self)
		{
			Dictionary<int, ThreeRealmsExperienceConfig> all = ConfigSingleton<ThreeRealmsExperienceConfigCategory>.Instance.GetAll();
			self.dupIds.Clear();
			((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<FuncModule>();
			List<int> list = new List<int>();
			List<int> list2 = new List<int>();
			Player player = ((Entity)(object)self).LocalPlayer();
			foreach (ThreeRealmsExperienceConfig value in all.Values)
			{
				int id = value.Id;
				if (player.CheckFuncOpen(value.Play))
				{
					if (player.IsPreOpen(id))
					{
						list2.Add(id);
					}
					else if (player.IsFuncOpen(id))
					{
						list.Add(id);
					}
				}
