	[RedPointHandler(RedPointType.Dup_Universe)]
	public class UniverseDupRedPointHandler : ARedPointHandler
	{
		public override int GetCount(Scene scene, params int[] parameters)
		{
			if (((Entity)scene).GetComponent<LocalPlayerComponent>().Player == null)
			{
				return 0;
			}
			int count = RedPointHelper.GetCount(scene, RedPointType.TeamDup);
			return 0 + count + RedPointHelper.GetCount(scene, RedPointType.MultipleTeamDup);
		}
	}
