		private static void OnSelfClick(this UIVibesSkill self)
		{
			UIManager.Instance.Show<UIVibesDemonExcellentPanel, (int, int)>((self.Job, self.Position)).Coroutine();
		}

		public static void SetData(this UIVibesSkill self, int job, int part, int position)
		{
			self.Job = job;
			self.Part = part;
			self.Position = position;
			VibesDemonModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesDemonModule>();
			if (!component.IsOpen(job, position))
			{
				self.UIObject.SetActive(active: false);
				return;
			}
			self.UIObject.SetActive(active: true);
			VibesAttachDemonExcellentConfig demonPlusConfig = component.GetDemonPlusConfig(job, position);
			bool flag = component.GetTotalLevel(job, position) >= demonPlusConfig.UnLockTotalLevel;
			self._SkillLevel.SetActive(flag);
			self._Lock.SetActive(!flag);
			self._LevelLock.SetActive(!flag);
			self._LevelLockText.SetText($"{demonPlusConfig.UnLockTotalLevel}级解锁");
			int skillId = demonPlusConfig.SkillId;
			SkillLevel skillLevel = new SkillLevel(skillId);
			self._SkillImage.SetGray(!flag);
			if (skillLevel.IsPassiveSkill)
			{
				self.ShowPassiveSkill(skillLevel);
			}
			else
			{
				self.ShowActiveSkill(skillLevel);
			}
		}

		private static void ShowPassiveSkill(this UIVibesSkill self, SkillLevel skillLevel)
		{
			PassiveSkillLevelConfig passiveSkillLevelConfig = ConfigSingleton<PassiveSkillLevelConfigCategory>.Instance.Get(skillLevel.SkillLevelId);
			self._SkillLevelText.SetText($"等级 {passiveSkillLevelConfig.Level}");
			self._LeftTopImage.SetActive(active: false);
			self._SkillImage.SetRawTexture($"uitex_icon_skill_{passiveSkillLevelConfig.Icon}").Coroutine();
		}

		private static void ShowActiveSkill(this UIVibesSkill self, SkillLevel skillLevel)
		{
			ActiveSkillLevelConfig activeSkillLevelConfig = ConfigSingleton<ActiveSkillLevelConfigCategory>.Instance.Get(skillLevel.SkillLevelId);
			SkillTag tags = (SkillTag)activeSkillLevelConfig.Tags;
			int skillIndex = skillLevel.SkillIndex;
			self._SkillImage.SetTexture($"uitex_icon_skill_{activeSkillLevelConfig.Icon}").Coroutine();
			if (skillIndex == 1)
			{
				self._LeftTopImage.SetSprite("ui_hero_front_05").Coroutine();
				self._LeftTopImage.SetActive(active: true);
			}
			if (tags.HasFlag(SkillTag.Super))
			{
				self._LeftTopImage.SetSprite("ui_hero_front_04").Coroutine();
				self._LeftTopImage.SetActive(active: true);
			}
		}
	}
