		private static void InitPanel(this UIVibesSplitPanel self)
		{
			self.IsLock = false;
			self._UIEquipScroll.SpaceX = 12f;
			self._UIEquipScroll.SpaceY = 12f;
			self._UIEquipScroll.Handler.onUpdate += self.OnEquipCellUpdate;
			self._UISplitRewardScroll.SpaceX = 12f;
			self._UISplitRewardScroll.Handler.onUpdate += self.OnSplitRewardCellUpdate;
			self._OneKeySplit.AddClickHandler(self.OnClickOneKeySplit);
			self._AutoSplitCK.AddClickHandler(self.OnAutoSplitClick);
		}

		private static void LoadTextInfo(this UIVibesSplitPanel self)
		{
			self._EmptyText.SetText(Language.Get(2, 236));
			self._AutoText.SetText(Language.Get(5, (self.SplitType == 1) ? 801 : 802));
		}

		public static void UpdateView(this UIVibesSplitPanel self)
		{
			if (!self.IsLock)
			{
				if (self.SplitType == 1)
				{
					self.UpdateEquipList();
				}
				else if (self.SplitType == 2)
				{
					self.UpdateGemList();
				}
				self.IsLock = true;
			}
		}

		private static void UpdateEquipList(this UIVibesSplitPanel self)
		{
			self.ItemList.Clear();
			self.SelectList.Clear();
			List<ItemStruct> allUnWearEquipItem = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesEquipModule>().GetAllUnWearEquipItem();
			if (allUnWearEquipItem == null || allUnWearEquipItem.Count == 0)
			{
				self._Content.SetActive(active: false);
				self._EmptyImage.SetActive(active: true);
				self._UIEquipScroll.SetData(0);
				self.UpdateSplitRewardList();
				return;
			}
			self._EmptyImage.SetActive(active: false);
			self._UIEquipScroll.UIObject.SetActive(active: true);
			self.ItemList = allUnWearEquipItem;
			self.ItemList.Sort((ItemStruct a, ItemStruct b) => self.GetSort(a) - self.GetSort(b));
			self.SetEquipDefaultSelected();
			self._UIEquipScroll.SetData(self.ItemList.Count);
		}

		private static int GetSort(this UIVibesSplitPanel self, ItemStruct item)
		{
			VibesEquipModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesEquipModule>();
			EquipConfig equipConfig = ConfigSingleton<EquipConfigCategory>.Instance.Get(item.ConfigId);
			int equipId = component.GetEquipId(equipConfig.Job, equipConfig.Part);
			if (equipId == 0)
			{
				return 1;
			}
			if (component.IsBest(item.ConfigId, equipId))
			{
				return 2;
			}
			return 0;
		}

		private static void SetEquipDefaultSelected(this UIVibesSplitPanel self)
		{
			VibesEquipModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesEquipModule>();
			for (int i = 0; i < self.ItemList.Count; i++)
			{
				ItemStruct itemStruct = self.ItemList[i];
				EquipConfig equipConfig = ConfigSingleton<EquipConfigCategory>.Instance.Get(itemStruct.ConfigId);
				if (!equipConfig.IsCannotSplit)
				{
					int equipId = component.GetEquipId(equipConfig.Job, equipConfig.Part);
					if (equipId != 0 && !component.IsBest(itemStruct.ConfigId, equipId))
					{
						self.SelectList.Add(i);
					}
				}
			}
			self.UpdateSplitRewardList();
		}

		private static void UpdateGemList(this UIVibesSplitPanel self)
		{
			self.ItemList.Clear();
			self.SelectList.Clear();
			List<ItemStruct> bagGemItems = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesGemModule>().GetBagGemItems();
			if (bagGemItems == null || bagGemItems.Count == 0)
			{
				self._Content.SetActive(active: false);
				self._EmptyImage.SetActive(active: true);
				self._UIEquipScroll.SetData(0);
				self.UpdateSplitRewardList();
			}
			else
			{
				self._EmptyImage.SetActive(active: false);
				self._UIEquipScroll.UIObject.SetActive(active: true);
				self.ItemList = bagGemItems;
				self.SetGemDefalutSelected();
				self._UIEquipScroll.SetData(self.ItemList.Count);
			}
		}

		private static void SetGemDefalutSelected(this UIVibesSplitPanel self)
		{
			VibesGemModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesGemModule>();
			for (int i = 0; i < self.ItemList.Count; i++)
			{
				if (component.IsDefalutSelected(self.ItemList[i].ConfigId))
				{
					self.SelectList.Add(i);
				}
			}
			self.UpdateSplitRewardList();
		}

		private static void OnAutoSplitClick(this UIVibesSplitPanel self)
		{
			SuperToggle component = self._AutoSplitCK.GameObject.GetComponent<SuperToggle>();
			self.IsAutoSplit = ((Toggle)component).isOn;
		}

		private static void OnEquipCellUpdate(this UIVibesSplitPanel self, UIScrollListCell cell)
		{
			int index = cell.Index;
			if (index < self.ItemList.Count)
			{
				ItemStruct itemStruct = self.ItemList[index];
				int configId = itemStruct.ConfigId;
				long nums = itemStruct.Nums;
				bool flag = self.SelectList.IndexOf(index) != -1;
				((Entity)cell.UIObject).GetComponent<UIVibesSplitItem>().SetData(configId, nums, flag, index);
			}
		}

		private static void UpdateSplitRewardList(this UIVibesSplitPanel self)
		{
			self._OneKeySplit.SetGray(self.SelectList.Count == 0);
			self.SplitRewardIdList.Clear();
			if (self.SelectList.Count == 0)
			{
				self._UISplitRewardScroll.SetData(0);
				self._UISplitRewardScroll.UIObject.SetActive(active: false);
				return;
			}
			VibesEquipModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesEquipModule>();
			using ItemList itemList = ItemList.Create();
			for (int i = 0; i < self.SelectList.Count; i++)
			{
				component.VibesSplitEquipAddReward(itemList, self.ItemList[i].ConfigId, (int)self.ItemList[i].Nums);
			}
			foreach (ItemStruct item in itemList)
			{
				self.SplitRewardIdList.Add(item);
			}
			self._UISplitRewardScroll.UIObject.SetActive(self.SplitRewardIdList.Count > 0);
