		private static bool isExistBestEquip(this UIVibesSplitPanel self)
		{
			if (self.SplitType != 1)
			{
				return false;
			}
			VibesEquipModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesEquipModule>();
			foreach (int select in self.SelectList)
			{
				ItemStruct itemStruct = self.ItemList[select];
				EquipConfig equipConfig = ConfigSingleton<EquipConfigCategory>.Instance.Get(itemStruct.ConfigId);
				int equipId = component.GetEquipId(equipConfig.Job, equipConfig.Part);
				if (equipId == 0)
				{
					return true;
				}
				if (component.IsBest(itemStruct.ConfigId, equipId))
				{
					return true;
				}
			}
			return false;
		}

		private static void OnClickOneKeySplit(this UIVibesSplitPanel self)
		{
			if (self.SelectList.Count == 0)
			{
				UIGameMsgHelper.FloatMsgByError(200704);
