				UIScrollList uIHeroScroll = ((Entity)uIObject.Find("HeroPart/_UIHeroScroll")).AddComponent<UIScrollList>(false);
				UIVibesJobButton jobButton = ((Entity)uIObject.Find("_JobGroup/_JobButton1")).AddComponent<UIVibesJobButton>(false);
				UIVibesJobButton jobButton2 = ((Entity)uIObject.Find("_JobGroup/_JobButton2")).AddComponent<UIVibesJobButton>(false);
				UIVibesJobButton jobButton3 = ((Entity)uIObject.Find("_JobGroup/_JobButton3")).AddComponent<UIVibesJobButton>(false);
				self._UIHeroScroll = uIHeroScroll;
				self._JobGroup = uIObject.Find("_JobGroup");
				self._JobButton1 = jobButton;
				self._JobButton2 = jobButton2;
				self._JobButton3 = jobButton3;
