		[UIMethod]
		public static void OnAwake(this UIVibesUpPart self)
		{
			self._UIHeroScroll.SpaceX = 10f;
			self._UIHeroScroll.Handler.onUpdate += self.OnHeroCellUpdate;
			List<JobConfig> list = ConfigSingleton<JobConfigCategory>.Instance.GetAll().Values.ToList();
			for (int i = 0; i < list.Count; i++)
			{
				JobConfig jobConfig = list[i];
				UIObject uIObject = self._JobGroup.Find($"_JobButton{jobConfig.Id}");
				UIVibesJobButton component = ((Entity)uIObject).GetComponent<UIVibesJobButton>();
				self.JobButtons.Add(jobConfig.Id, component);
				component.SetData(jobConfig.Id);
				uIObject.AddClickHandler(delegate
				{
					self.OnJobTabClick(jobConfig.Id);
				});
			}
		}

		[UIMethod]
		public static void OnDestroy(this UIVibesUpPart self)
		{
			self.JobButtons.Clear();
		}

		private static void OnJobTabClick(this UIVibesUpPart self, int job)
		{
			if (self.Job != job)
			{
				self.SetSelectJob(job);
			}
		}

		private static void SetSelectJob(this UIVibesUpPart self, int job)
		{
			self.Job = job;
			foreach (var (num2, self2) in self.JobButtons)
			{
				self2.SetSelect(job == num2);
			}
			self.UpdateHeroList();
			self.BindRedPoint();
			self.OnCallBack?.Invoke();
		}

		public static void SetTabIndex(this UIVibesUpPart self, int index)
		{
			self.TabIndex = index;
			self.SetDefalutJob();
		}

		private static void SetDefalutJob(this UIVibesUpPart self)
		{
			int num = self.Job;
			if (self.TabIndex == 1)
			{
				num = self.GetEquipDefaultJob();
			}
			else if (self.TabIndex == 2)
			{
				num = self.GetGemDefaultJob();
			}
			else if (self.TabIndex == 3)
			{
				num = self.GetSoulDefaultJob();
			}
			self.SetSelectJob((num == 0) ? 1 : num);
		}

		public static void RefreshTabIndex(this UIVibesUpPart self)
		{
			if (self.TabIndex != 0 && (self.TabIndex != 2 || UIObject.FindUIObjectOfType<UIVibesGemPanel>().IsAutoSelect))
			{
				int job = self.Job;
				if (((Entity)SceneHelper.DomainScene((Entity)(object)self)).GetComponent<UIRedPointComponent>().Handlers.GetValue(self.GetRedDotPrefix()).GetCount(SceneHelper.DomainScene((Entity)(object)self), job) > 0)
				{
					self.SetSelectJob(job);
				}
				else
				{
					self.SetDefalutJob();
				}
			}
		}

		public static void RefreshRedPoint(this UIVibesUpPart self)
		{
			self.BindRedPoint();
		}

		private static int GetGemDefaultJob(this UIVibesUpPart self)
		{
			VibesGemModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesGemModule>();
			int canInlayJob = component.GetCanInlayJob();
			if (canInlayJob > 0)
			{
				return canInlayJob;
			}
			canInlayJob = component.GetCanUpJob();
			if (canInlayJob > 0)
			{
				return canInlayJob;
			}
			return self.Job;
		}

		private static int GetSoulDefaultJob(this UIVibesUpPart self)
		{
			foreach (var (num2, _) in ConfigSingleton<JobConfigCategory>.Instance.GetAll())
			{
				if (VibesHelper.IsCanSoul(((Entity)(object)self).LocalPlayer(), num2) == 0)
				{
					return num2;
				}
			}
			return self.Job;
		}

		private static int GetEquipDefaultJob(this UIVibesUpPart self)
		{
			int bestEquip = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesEquipModule>().GetBestEquip();
			if (bestEquip > 0)
			{
				return ConfigSingleton<EquipConfigCategory>.Instance.Get(bestEquip).Job;
			}
			return self.GetEnhanceDefaultJob();
		}

		private static int GetEnhanceDefaultJob(this UIVibesUpPart self)
		{
			VibesEquipModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesEquipModule>();
			if (component.IsCanPower(self.Job))
			{
				return self.Job;
			}
			foreach (int key in self.JobButtons.Keys)
			{
				if (key != self.Job && component.IsCanPower(key))
				{
					return key;
				}
			}
			return self.Job;
		}

		private static void BindRedPoint(this UIVibesUpPart self)
		{
			if (self.TabIndex == 0)
			{
				return;
			}
			RedPointType redDotPrefix = self.GetRedDotPrefix();
			if (redDotPrefix == RedPointType.None)
			{
				return;
			}
			foreach (var (num2, uIVibesJobButton2) in self.JobButtons)
			{
				uIVibesJobButton2.UIObject.SetRedPoint(redDotPrefix, num2).Coroutine();
			}
		}

		private static RedPointType GetRedDotPrefix(this UIVibesUpPart self)
		{
			return self.TabIndex switch
			{
				1 => RedPointType.Vibes_Equip, 
				2 => RedPointType.Vibes_Gem, 
				3 => RedPointType.Vibes_Soul, 
				_ => RedPointType.None, 
			};
		}

		public static void SetCallBack(this UIVibesUpPart self, Action callBack)
		{
			self.OnCallBack = callBack;
		}

		private static void UpdateHeroList(this UIVibesUpPart self)
		{
			HeroModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<HeroModule>();
			self.HeroList.Clear();
			self.HeroList = component.GetHeroes(new HeroSearch
			{
				Job = self.Job,
				Includes = HeroInclude.All,
				SortType = HeroSortType.VibesHeroList
			});
			self._UIHeroScroll.SetData(self.HeroList.Count);
		}

		private static void OnHeroCellUpdate(this UIVibesUpPart self, UIScrollListCell cell)
		{
			int index = cell.Index;
			if (self.HeroList.Count > index)
			{
				((Entity)cell.UIObject).GetComponent<UIVibesHeroItem>().SetData(self.HeroList[index]);
			}
		}
	}
