		public static void UpdatePlus(this UIVibesEquipPanel self)
		{
			VibesEquipModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesEquipModule>();
			int enhancePlusLevel = component.GetEnhancePlusLevel(self.Job);
			self._PlusStageText.SetText($"强化大师 <color=#ecd9a0>{enhancePlusLevel}阶</color>");
			VibesEquipPowerExcellentConfig vibesEquipPowerExcellentConfig = ConfigSingleton<VibesEquipPowerExcellentConfigCategory>.Instance.Get(self.Job * 100 + enhancePlusLevel);
			VibesEquipPowerExcellentConfig vibesEquipPowerExcellentConfig2 = ConfigSingleton<VibesEquipPowerExcellentConfigCategory>.Instance.Get(self.Job * 100 + enhancePlusLevel + 1);
			self._PlusButton.SetTexture(vibesEquipPowerExcellentConfig?.Icon ?? vibesEquipPowerExcellentConfig2.Icon).Coroutine();
			if (vibesEquipPowerExcellentConfig2 != null)
			{
				self._PlusProText.SetActive(active: true);
				self._PlusProText.SetText($"<color=#5dfa49>{component.GetEquipPowerTotalLevel(self.Job)}</color>/{vibesEquipPowerExcellentConfig2.TotalLevel}");
			}
			else
			{
				self._PlusProText.SetActive(active: false);
			}
		}

		private static void OnPartClick(this UIVibesEquipPanel self, int part)
		{
			Player player = ((Entity)(object)self).LocalPlayer();
			if (!player.IsPartOpen(self.Job, part))
			{
				EquipPartConfig partOpenConfig = VibesHelper.GetPartOpenConfig(self.Job, part);
				UIGameMsgHelper.FloatMsg(player.GetCondText(partOpenConfig.Cond));
				return;
			}
			VibesEquipModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesEquipModule>();
			if (component.GetEquipId(self.Job, part) == 0)
			{
				int bestEquip = component.GetBestEquip(self.Job, part);
				if (bestEquip == 0)
				{
					UIObtainWayHelper.ShowPanelAsync(ConfigSingleton<GlobalConfigCategory>.Instance.GetOne().EquipWayId).Coroutine();
				}
				else
				{
					component.ReqTakeEquip(bestEquip).Coroutine();
				}
			}
			else
			{
				self.SetPartIndex(part);
				self.UpdateView();
			}
		}

		private static void OnTimeHandler(this UIVibesEquipPanel self)
		{
			if (self.UIObject.IsActiveInHierarchy())
			{
				TaskData mainTask = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<TaskModule>().GetMainTask();
				TaskConfig taskConfig = ConfigSingleton<TaskConfigCategory>.Instance.Get(mainTask.Id);
				if ((taskConfig.FinishType == 108 || taskConfig.FinishType == 1030) && mainTask.Status == 2)
				{
					UIGuideHelper.ExecuteGuide(SceneHelper.DomainScene((Entity)(object)self), 1005);
				}
			}
		}

