		public static void SetData(this UIVibesEquipPanel self, int job)
		{
			self.Job = job;
			self._Power.SetPower(self.GetPower());
			self.UpdatePlus();
			self.UpdatePart();
			self.SetEquipDefaultPart();
			if (self.Part == -1 || self.Part == 0)
			{
				self.ClearPanel();
			}
			else
			{
				self.UpdateView();
			}
		}

		private static void SetEquipDefaultPart(this UIVibesEquipPanel self)
		{
			int num = -1;
			VibesEquipModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesEquipModule>();
			self.BestId = component.GetBestEquip(self.Job);
			if (self.BestId > 0)
			{
				self.SetPartIndex(-1);
				return;
			}
			int item = component.GetMinPowerLevel(self.Job).Item1;
			num = ((item > 0) ? item : (-1));
			self.SetPartIndex(num);
		}

		private static void SetPartIndex(this UIVibesEquipPanel self, int selectPart)
		{
			self.Part = selectPart;
			foreach (var (num2, self2) in self.EquipItems)
			{
				self2.SetSelect(selectPart == num2);
			}
		}

		private static void UpdatePart(this UIVibesEquipPanel self)
		{
			foreach (var (part, self2) in self.EquipItems)
			{
				self2.SetData(self.Job, part);
			}
		}

		private static void ClearPanel(this UIVibesEquipPanel self)
		{
			self._EmptyText.SetActive(active: true);
			self._AttrList.Clear();
			self._PowerButton.SetActive(active: false);
			self._OneKeyEquip.SetActive(active: false);
			self._Cost.UIObject.SetActive(active: false);
			self._MaxLevel.SetActive(active: false);
			self.UpdateButton();
			self.UpdateAttrList();
			self.UpdateSelectItem();
		}

		private static void UpdateView(this UIVibesEquipPanel self)
		{
			if (self.Job != 0)
			{
				if (self.Part <= 0)
				{
					self.UpdateButton();
					return;
				}
				self._EmptyText.SetActive(active: false);
				self._PowerButton.SetActive(active: false);
				self._OneKeyEquip.SetActive(active: false);
				self._Cost.UIObject.SetActive(active: false);
				self._MaxLevel.SetActive(active: false);
				self.UpdateAttrList();
				self.UpdateButton();
				self.UpdateSelectItem();
			}
		}

		public static void UpdateItem(this UIVibesEquipPanel self)
		{
			VibesEquipModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesEquipModule>();
			self.BestId = component.GetBestEquip(self.Job);
			self.UpdateRedPoint();
			self.UpdateButton();
		}

		public static void UpdateRedPoint(this UIVibesEquipPanel self)
		{
			Scene scene = SceneHelper.DomainScene((Entity)(object)self);
			foreach (var (num2, _) in self.EquipItems)
			{
				RedPointHelper.RefreshRedPoint(scene, RedPointType.Vibes_Equip, self.Job, num2);
			}
			self.UpdateButton();
		}

		private static void UpdateButton(this UIVibesEquipPanel self)
		{
			VibesEquipModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesEquipModule>();
			int equipId = component.GetEquipId(self.Job, self.Part);
			if (self.BestId > 0)
			{
				self._OneKeyEquip.SetActive(active: true);
				self._OneKeyEquip.SetGray(isGray: false);
				self._EquipRedPoint.SetActive(active: true);
				self._PowerButton.SetActive(active: false);
				self._Cost.UIObject.SetActive(active: false);
			}
			else if (equipId > 0)
			{
				int powerLevel = component.GetPowerLevel(self.Job, self.Part);
				int maxLevel = ConfigSingleton<EquipPowerConfigCategory>.Instance.GetMaxLevel(self.Job, self.Part);
				if (powerLevel >= maxLevel)
				{
					self._PowerButton.SetActive(active: false);
					self._Cost.UIObject.SetActive(active: false);
					self._MaxLevel.SetActive(active: true);
					return;
				}
				EquipPowerConfig enhanceConfig = ConfigSingleton<EquipPowerConfigCategory>.Instance.GetEnhanceConfig(self.Job, self.Part, powerLevel);
				bool flag = ((Entity)(object)self).LocalPlayer().CheckItemNumsIsEnough(enhanceConfig.Cost);
				self._PowerButton.SetActive(active: true);
				self._PowerButton.SetGray(!flag);
				self._EnhanceRedPoint.SetActive(flag);
				self.UpdateCost();
			}
			else
			{
				self._OneKeyEquip.SetActive(active: true);
				self._OneKeyEquip.SetGray();
				self._EquipRedPoint.SetActive(active: false);
			}
		}

		private static void UpdateCost(this UIVibesEquipPanel self)
		{
			self._Cost.UIObject.SetActive(active: true);
			int powerLevel = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesEquipModule>().GetPowerLevel(self.Job, self.Part);
			EquipPowerConfig enhanceConfig = ConfigSingleton<EquipPowerConfigCategory>.Instance.GetEnhanceConfig(self.Job, self.Part, powerLevel);
			self._Cost.SetData(enhanceConfig.Cost);
		}

		public static void UpdateAttrList(this UIVibesEquipPanel self)
		{
			VibesEquipModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesEquipModule>();
			if (self.Part == -1)
			{
				using (StatList statList = StatList.Create())
				{
					component.GetEquipStatList(self.Job, statList);
					using StatList statList2 = StatList.Create();
					VibesHelper.SetStatZero(statList2, statList);
					self._AttrList.SetAddData(statList, null, statList2);
					self._EmptyText.SetActive(statList.Count <= 0);
					return;
				}
			}
			int equipId = component.GetEquipId(self.Job, self.Part);
			EquipConfig equipConfig = ConfigSingleton<EquipConfigCategory>.Instance.Get(equipId);
			int enhanceLevel = VibesHelper.GetEnhanceLevel(((Entity)(object)self).LocalPlayer(), self.Job, self.Part);
			using StatList statList3 = StatList.Create();
			VibesHelper.SetEnhanceStat(statList3, self.Job, self.Part, enhanceLevel + 1);
			statList3.AddRange(equipConfig.EquipStat);
			using StatList statList4 = StatList.Create();
			VibesHelper.SetStatZero(statList4, statList3);
			VibesHelper.SetEnhanceStat(statList4, self.Job, self.Part, enhanceLevel);
			statList4.AddRange(equipConfig.EquipStat);
			self._AttrList.SetAddData(statList4, statList3);
		}

