		public static void UpdateBaseAttr(this UIVibesEquipTipsItem self)
		{
			EquipConfig equipConfig = ConfigSingleton<EquipConfigCategory>.Instance.Get(self.ConfigId);
			using StatList statList = StatList.Create();
			statList.AddRange(equipConfig.EquipStat);
			self.StatList = statList;
			self._List.SetData(self.StatList.Count);
			self._TitleText.SetText("基础属性");
			self.UpdateSize();
		}

		public static void UpdateEnhanceAttr(this UIVibesEquipTipsItem self)
		{
			//IL_00e0: Unknown result type (might be due to invalid IL or missing references)
			//IL_00e5: Unknown result type (might be due to invalid IL or missing references)
			//IL_00f3: Unknown result type (might be due to invalid IL or missing references)
			//IL_010d: Unknown result type (might be due to invalid IL or missing references)
			EquipConfig equipConfig = ConfigSingleton<EquipConfigCategory>.Instance.Get(self.ConfigId);
			VibesEquipModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesEquipModule>();
			int num = 0;
			using StatList statList = StatList.Create();
			int job = equipConfig.Job;
			for (int i = 1; i < 7; i++)
			{
				int powerLevel = component.GetPowerLevel(job, i);
				if (powerLevel != 0)
				{
					num += powerLevel;
					EquipPowerConfig enhanceConfig = ConfigSingleton<EquipPowerConfigCategory>.Instance.GetEnhanceConfig(job, i, powerLevel);
					statList.AddRange(enhanceConfig.PowerStat);
				}
			}
			self.StatList = statList;
			self._List.SetData(self.StatList.Count);
			self._TitleText.SetText($"强化属性 <color=#17bf17>+{num}</color>");
			self._TitleText.GameObject.GetComponent<ContentSizeFitter>().horizontalFit = (FitMode)2;
			self._TitleText.GameObject.GetComponent<ContentSizeFitter>().SetLayoutHorizontal();
			Vector2 sizeDelta = self._TitleText.Transform.sizeDelta;
			self._TitleLabel.Transform.SetSizeWithCurrentAnchors((Axis)0, (sizeDelta.x > 0f) ? (127f + sizeDelta.x) : 127f);
			self.UpdateSize();
		}

		public static void UpdateGemAttr(this UIVibesEquipTipsItem self)
		{
			EquipConfig equipConfig = ConfigSingleton<EquipConfigCategory>.Instance.Get(self.ConfigId);
			int job = equipConfig.Job;
			int part = equipConfig.Part;
			List<int> gemPositions = VibesHelper.GetGemPositions(job, part);
			self.Positions = gemPositions;
			self._List.SetData(self.Positions.Count);
			self._TitleText.SetText("宝石属性");
			self.UpdateSize();
		}

		public static void UpdateDemonAttr(this UIVibesEquipTipsItem self)
		{
			EquipConfig equipConfig = ConfigSingleton<EquipConfigCategory>.Instance.Get(self.ConfigId);
			using (StatList.Create())
			{
				int job = equipConfig.Job;
				self.Positions = VibesHelper.GetDemonPositions(job);
				self._List.SetData(self.Positions.Count);
				self._TitleText.SetText("附魔属性");
				self.UpdateSize();
			}
		}

		private static void UpdateSize(this UIVibesEquipTipsItem self)
		{
			int count = self._List.GetCount();
			self.UIObject.Transform.SetSizeWithCurrentAnchors((Axis)1, Mathf.Ceil((float)count / 2f) * 50f + 42f);
		}
	}
