		private static void SetData(this UIVibesEquipTipsPanel self, int configId)
		{
			EquipConfig equipConfig = ConfigSingleton<EquipConfigCategory>.Instance.Get(configId);
			if (equipConfig == null)
			{
				return;
			}
			self._Item.SetItem(configId, 1L);
			self._ItemName.SetText(UIItemHelper.GetItemNameWithColor(configId));
			self._LevelNumer.SetText($"等级：{equipConfig.Level}");
			using PowerCalc powerCalc = PowerCalc.Create();
			powerCalc.AddStats(equipConfig.EquipStat);
			self._Power.SetPower(powerCalc.Power);
			self.TipsTypeList.Clear();
			self.TipsTypeList.Add(1);
			if (((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesEquipModule>().GetEquipPowerTotalLevel(equipConfig.Job) > 0)
			{
				self.TipsTypeList.Add(2);
			}
			self.TipsTypeList.Add(3);
			self.TipsTypeList.Add(4);
			self._ScrollList.SetData(self.TipsTypeList.Count);
		}

