		public static void SetData(this UIVibesEquipTipsStat self, int type, int position)
		{
			self.Position = position;
			switch (type)
			{
			case 3:
				self.ShowGemPosition();
				break;
			case 4:
				self.ShowDemonPosition();
				break;
			}
		}

		private static void ShowGemPosition(this UIVibesEquipTipsStat self)
		{
			self._GemImage.SetActive(active: false);
			self._AttrNameText.SetActive(active: true);
			self._AttrValueText.SetActive(active: false);
			VibesGemStonePositionOpenConfig gemOpenConfig = VibesHelper.GetGemOpenConfig(self.Job, self.Part, self.Position);
			if (!((Entity)(object)self).LocalPlayer().CheckCond(gemOpenConfig.Cond))
			{
				self._AttrNameText.SetText(((Entity)(object)self).LocalPlayer().GetCondText(gemOpenConfig.Cond));
				return;
			}
			int gemLevel = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesGemModule>().GetGemLevel(self.Job, self.Part, self.Position);
			if (gemLevel == 0)
			{
				self._AttrNameText.SetText("<color=#a7a59e>暂未镶嵌</color>");
				return;
			}
			self._GemImage.SetActive(active: true);
			self._AttrValueText.SetActive(active: true);
			int gemPositionType = VibesHelper.GetGemPositionType(self.Job, self.Part, self.Position);
			GemStoneConfig gemConfig = VibesHelper.GetGemConfig(self.Job, gemPositionType, gemLevel);
			self._GemImage.SetRawTexture($"uitex_icon_item_{gemConfig.Icon}").Coroutine();
			StatConfig statConfig = ConfigSingleton<StatConfigCategory>.Instance.Get(gemConfig.AddStats[0].Type);
			self._AttrNameText.SetText(statConfig?.Desc);
			self._AttrValueText.SetText(gemConfig.AddStats[0].Value.ToString());
		}

		private static void ShowDemonPosition(this UIVibesEquipTipsStat self)
		{
			self._GemImage.SetActive(active: false);
			self._AttrNameText.SetActive(active: true);
			self._AttrValueText.SetActive(active: false);
			VibesAttachDemonPartOpenConfig demonOpenConfig = VibesHelper.GetDemonOpenConfig(self.Job, self.Position);
			if (!((Entity)(object)self).LocalPlayer().CheckCond(demonOpenConfig.Cond))
			{
				self._AttrNameText.SetText("<color=#a7a59e>" + ((Entity)(object)self).LocalPlayer().GetCondText(demonOpenConfig.Cond) + "</color>");
				return;
			}
			int demonLevel = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesDemonModule>().GetDemonLevel(self.Job, self.Part, self.Position);
			VibesAttachDemonConfig demonConfig = VibesHelper.GetDemonConfig(self.Job, self.Position, demonLevel);
			if (demonConfig.AddStat == null)
			{
				self._AttrNameText.SetText("<color=#a7a59e>附魔后解锁</color>");
				return;
			}
			self._AttrValueText.SetActive(active: true);
			StatConfig statConfig = ConfigSingleton<StatConfigCategory>.Instance.Get(demonConfig.AddStat.Type);
			self._AttrNameText.SetText(statConfig?.Desc);
			self._AttrValueText.SetText(demonConfig.AddStat.Value.ToString());
		}

		public static void SetBaseData(this UIVibesEquipTipsStat self, int job, int part)
		{
			self.Job = job;
			self.Part = part;
		}
	}
