			self._ReplaceButton.AddClickHandler(self.OnReplaceClick);
		}

		public static void SetData(this UIVibesGemBagItem self, int job, int part, int position, Item item)
		{
			self.Job = job;
			self.Part = part;
			self.Position = position;
			self.Item = item;
			self._Item.SetItem(item.ConfigId, item.Nums);
			JobConfig jobConfig = ConfigSingleton<JobConfigCategory>.Instance.Get(job);
			int num = item.ConfigId;
			if (num == jobConfig.GemId)
			{
				VibesGemStonePositionOpenConfig gemPositionConfig = VibesHelper.GetGemPositionConfig(job, part, position);
				num = VibesHelper.GetGemConfigId(job, gemPositionConfig.PositionType, 1);
			}
			GemStoneConfig gemStoneConfig = ConfigSingleton<GemStoneConfigCategory>.Instance.Get(num);
			self._NameText.SetText(UIItemHelper.GetItemNameWithColor(num));
			string text = "";
			for (int i = 0; i < gemStoneConfig.AddStats.Length; i++)
			{
				Stat stat = gemStoneConfig.AddStats[i];
				StatConfig statConfig = ConfigSingleton<StatConfigCategory>.Instance.Get(stat.Type);
				text += statConfig.Desc;
				text = text + " " + stat.Value;
				text += "\n";
			}
			self._AttrLabel.SetText(text);
			int level = gemStoneConfig.Level;
			int gemLevel = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesGemModule>().GetGemLevel(job, part, position);
			self._UpImage.SetActive(level > gemLevel);
		}

