		[UIMethod]
		public static void OnShow(this UIVibesGemBagPanel self, (int job, int part, int position) args)
		{
			self.Job = args.job;
			self.Part = args.part;
			self.Position = args.position;
			VibesGemStonePositionOpenConfig gemPositionConfig = VibesHelper.GetGemPositionConfig(self.Job, self.Part, self.Position);
			self.PositionType = gemPositionConfig.PositionType;
			self.UpdateView();
		}

		public static void UpdateView(this UIVibesGemBagPanel self)
		{
			int gemLevel = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesGemModule>().GetGemLevel(self.Job, self.Part, self.Position);
			self._EmptyText.SetActive(gemLevel == 0);
			self._SelfContent.SetActive(gemLevel != 0);
			if (gemLevel != 0)
			{
				self.UpdateSelfGem();
			}
			self.UpdateGemList();
		}

		private static void UpdateSelfGem(this UIVibesGemBagPanel self)
		{
			int gemLevel = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesGemModule>().GetGemLevel(self.Job, self.Part, self.Position);
			VibesGemStonePositionOpenConfig gemPositionConfig = VibesHelper.GetGemPositionConfig(self.Job, self.Part, self.Position);
			int gemConfigId = VibesHelper.GetGemConfigId(self.Job, gemPositionConfig.PositionType, gemLevel);
			GemStoneConfig gemStoneConfig = ConfigSingleton<GemStoneConfigCategory>.Instance.Get(gemConfigId);
			self._Item.SetItem(gemConfigId, 1L);
			self._NameText.SetText(UIItemHelper.GetItemNameWithColor(gemConfigId));
			string text = "";
			for (int i = 0; i < gemStoneConfig.AddStats.Length; i++)
			{
				Stat stat = gemStoneConfig.AddStats[i];
				StatConfig statConfig = ConfigSingleton<StatConfigCategory>.Instance.Get(stat.Type);
				text += statConfig.Desc;
				text = text + " " + stat.Value;
				text += "\n";
			}
			self._AttrLabel.SetText(text);
		}

		private static void UpdateGemList(this UIVibesGemBagPanel self)
		{
			self.Items?.Clear();
			VibesGemModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesGemModule>();
			self.Items = component.GetBagGems(self.Job, self.PositionType);
			self._GemList.SetData(self.Items.Count);
		}

		private static void OnCellUpdate(this UIVibesGemBagPanel self, UIScrollListCell cell)
		{
			((Entity)cell.UIObject).GetComponent<UIVibesGemBagItem>().SetData(self.Job, self.Part, self.Position, self.Items[cell.Index]);
		}

		private static void OnTakeOffClick(this UIVibesGemBagPanel self)
		{
			((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesGemModule>().ReqRemoveGem(self.Job, self.Part, self.Position).Coroutine();
		}
	}
