		[UIMethod]
		public static void OnAwake(this UIVibesGemPanel self)
		{
			self._RawImage.SetRawTexture("ui_gm_bg_07").Coroutine();
			self.GemPool = new Dictionary<int, Queue<UIVibesGemItem>>();
			self._SplitButton.AddClickHandler(delegate
			{
				((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesGemModule>().IsClickSplitButton = true;
				self._SplitButton.RefreshRedPoint(RedPointType.Vibes_Gem, -1);
				UIManager.Instance.Show<UIVibesSplitPanel, int>(2).Coroutine();
			});
			self._SplitButton.SetRedPoint(RedPointType.Vibes_Gem, -1).Coroutine();
			self._PlusButton.AddClickHandler(delegate
			{
				UIManager.Instance.Show<UIVibesGemPlusPanel, int>(self.Job).Coroutine();
			});
			self._OneKeyInlayButton.AddClickHandler(delegate
			{
				self.OnOneKeyInlayClick().Coroutine();
			});
			self._OneKeyUpButton.AddClickHandler(self.OnOneKeyUpClick);
			self._OneKeyUpButton.AddKeepHandler(self.OnLongPressClick);
			self._UpGradeButton.AddClickHandler(delegate
			{
				self.OnUpGradeClick().Coroutine();
			});
			self._BlessButton.AddClickHandler(delegate
			{
				self.OnBlessClick().Coroutine();
			});
			self._StageButton.AddClickHandler(self.OnStageClick);
			self._StageButton.SetRedPoint(RedPointType.Vibes_Gem, -2).Coroutine();
			self._EquipStatButton.AddClickHandler(async delegate
			{
				List<Stat> gemStats = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesGemModule>().GetGemStats(self.Job);
				UIHeroManualTotalAttrSystem.SetTitle(title: ConfigSingleton<JobConfigCategory>.Instance.Get(self.Job).Name + "宝石属性", self: await UIManager.Instance.Show<UIHeroManualTotalAttr, UIAttrShowArgs>(new UIAttrShowArgs
				{
					stats = gemStats.ToArray(),
					funcId = 3003
				}), job: self.Job);
			});
			self.GemDict.Add(1, self._GemItem1);
			self.GemDict.Add(2, self._GemItem2);
			self.GemDict.Add(3, self._GemItem3);
			self._MaxLevel.SetActive(active: false);
			self.IsAutoSelect = true;
			for (int num = 1; num < 7; num++)
			{
				int temp = num;
				UIObject uIObject = self._PartGroup.Find($"G{(num - 1) / 2 + 1}/Part{num}");
				UIVibesGemPartItem component = ((Entity)uIObject).GetComponent<UIVibesGemPartItem>();
				component.SetPart(num);
				self.PartItems.Add(num, component);
				uIObject.AddClickHandler(delegate
				{
					self.OnPartClick(temp);
				});
			}
			self._BlessBar.SetDefaultState();
			self._StatButton.AddClickHandler(self.OnStatClick);
			UIGuideHelper.TryGuide(SceneHelper.DomainScene((Entity)(object)self), "UIVibesGemPanel");
		}

		[UIMethod]
		public static void OnDestroy(this UIVibesGemPanel self)
		{
			self.GemPool.Clear();
		}

		[UIMethod]
		public static void OnEnable(this UIVibesGemPanel self)
		{
			self.IsAutoSelect = true;
		}

		private static void OnPartClick(this UIVibesGemPanel self, int part)
		{
			Player player = ((Entity)(object)self).LocalPlayer();
			if (!player.IsPartOpen(self.Job, part))
			{
				EquipPartConfig partOpenConfig = VibesHelper.GetPartOpenConfig(self.Job, part);
				UIGameMsgHelper.FloatMsg(player.GetCondText(partOpenConfig.Cond));
			}
			else
			{
				self.SetPartIndex(part);
				self.UpdateView();
			}
		}

		private static string GetBgEffect(this UIVibesGemPanel self, int job)
		{
			return job switch
			{
				1 => "ui_fx_baoshi_beijing", 
				2 => "ui_fx_baoshi_beijing_2", 
				3 => "ui_fx_baoshi_beijing_3", 
				_ => "", 
			};
		}

		private static UIVibesGemItem GetGemItem(this UIVibesGemPanel self, int positionType)
		{
			if (!self.GemPool.ContainsKey(positionType))
			{
				self.GemPool.Add(positionType, new Queue<UIVibesGemItem>());
			}
			Queue<UIVibesGemItem> value = self.GemPool.GetValue(positionType);
			if (value.Count > 0)
			{
				return value.Dequeue();
			}
			return ((Entity)self.UIObject.Find("BG/VibesGemItem" + positionType).Clone()).AddComponent<UIVibesGemItem>(false);
		}

		public static void SelectPosition(this UIVibesGemPanel self, int pos)
		{
			self.Position = pos;
			foreach (var (num2, self2) in self.GemDict)
			{
