		public static void SetDefaultPosition(this UIVibesGemPanel self)
		{
			int num = int.MaxValue;
			VibesGemModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesGemModule>();
			List<int> gemPositions = VibesHelper.GetGemPositions(self.Job, self.Part);
			self.Position = gemPositions[0];
			for (int i = 0; i < gemPositions.Count; i++)
			{
				int position = gemPositions[i];
				int gemLevel = component.GetGemLevel(self.Job, self.Part, position);
				if (!VibesHelper.IsGemLock(((Entity)(object)self).LocalPlayer(), self.Job, self.Part, position) && !VibesHelper.IsGemMax(((Entity)(object)self).LocalPlayer(), self.Job, self.Part, position) && gemLevel < num)
				{
					self.Position = position;
					num = gemLevel;
				}
			}
			self.SelectPosition(self.Position);
		}

		public static void UpdateAttrList(this UIVibesGemPanel self)
		{
			VibesGemModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesGemModule>();
			self._GemLevelText.SetText(component.GetGemTotalLevel(self.Job, self.Part).ToString());
			int gemLevel = component.GetGemLevel(self.Job, self.Part, self.Position);
			self._EmptyText.SetActive(active: false);
			if (gemLevel <= 0)
			{
				self._AttrList.SetActive(active: false);
				self._StatButton.SetActive(active: false);
				self._EmptyText.SetActive(active: true);
				return;
			}
			self._AttrList.SetActive(active: true);
			self._StatButton.SetActive(active: true);
			using (StatList.Create())
			{
				using (StatList.Create())
				{
					GemStoneConfig gemConfig = VibesHelper.GetGemConfig(self.Job, VibesHelper.GetGemPositionType(self.Job, self.Part, self.Position), gemLevel);
					GemStoneConfig gemConfig2 = VibesHelper.GetGemConfig(self.Job, VibesHelper.GetGemPositionType(self.Job, self.Part, self.Position), gemLevel + 1);
					Stat stat = gemConfig.AddStats[0];
					self._StatNameText.SetText(stat.GetName() + "：");
					self._StatValueText.SetText("+" + TextHelper.FormatStatValue(stat.Type, stat.Value));
					self._NextStatImage.SetActive(active: false);
					self._NextStatValueText.SetActive(active: false);
					if (gemConfig2 != null)
					{
						self._NextStatImage.SetActive(active: true);
						self._NextStatValueText.SetActive(active: true);
						Stat stat2 = gemConfig2.AddStats[0];
						self._NextStatValueText.SetText("+" + TextHelper.FormatStatValue(stat2.Type, stat2.Value));
					}
				}
			}
		}

