		private static void UpdateCost(this UIVibesGemPanel self)
		{
			self._MaxLevel.SetActive(active: false);
			self._Cost.UIObject.SetActive(active: false);
			self._OneKeyUpButton.SetActive(active: false);
			self._OneKeyInlayButton.SetActive(active: false);
			self._InlayRedPoint.SetActive(active: false);
			self._UpRedPoint.SetActive(active: false);
			self._UpGradeButton.SetActive(active: false);
			self._BlessGroup.SetActive(active: false);
			VibesGemModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesGemModule>();
			int gemLevel = component.GetGemLevel(self.Job, self.Part, self.Position);
			if (self.IsCanUseHammer() != 0)
			{
				self._BlessBar.SetCancelType();
			}
			int blessType = self._BlessBar.GetBlessType();
			if (blessType == 1)
			{
				self._BlessGroup.SetActive(active: true);
				self.UpdateBless();
				return;
			}
			int gemPositionType = VibesHelper.GetGemPositionType(self.Job, self.Part, self.Position);
			GemStoneConfig gemConfig = VibesHelper.GetGemConfig(self.Job, gemPositionType, gemLevel);
			if (component.GetBestGem(self.Job, self.Part) > 0)
			{
				self._InlayRedPoint.SetActive(active: true);
				self._OneKeyInlayButton.SetActive(active: true);
				return;
			}
			if (VibesHelper.GetGemConfig(self.Job, self.Position, gemLevel + 1) == null)
			{
				self.ShowMax();
				return;
			}
			ET.ConfigBeans.Item item = ((blessType == 2) ? gemConfig.UpGradeCost : gemConfig.Cost);
			bool flag = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<ItemModule>().CheckItemNumsIsEnough(item);
			if (blessType == 2)
			{
				self._UpGradeButton.SetActive(active: true);
				self._UpGradeButton.SetGray(!flag);
			}
			else
			{
				self._OneKeyUpButton.SetActive(active: true);
				self._OneKeyUpButton.SetGray(!flag);
				self._UpRedPoint.SetActive(flag);
			}
			self._Cost.UIObject.SetActive(active: true);
			self._Cost.SetData(item);
		}

