			//IL_0237: Unknown result type (might be due to invalid IL or missing references)
			VibesGemStoneExcellentConfig config = ConfigSingleton<VibesGemStoneExcellentConfigCategory>.Instance.Get(configId);
			self._IconImage.SetRawTexture(config.Icon).Coroutine();
			self._StageText.SetText($"{config.Level}阶");
			self._Title1Group.SetActive(currentLevel != config.Level);
			self._Title2Group.SetActive(currentLevel == config.Level);
			JobConfig jobConfig = ConfigSingleton<JobConfigCategory>.Instance.Get(config.Job);
			self._MaskImage.SetActive(currentLevel < config.Level);
			self._CurrentGroup.SetActive(currentLevel == config.Level);
			if (currentLevel == config.Level)
			{
				self._Title2Text.SetText($"{jobConfig.Name}宝石总等级（<color=#5dfa49>{totalLevel}</color>/{config.TotalLevel}）");
