				self._Bg.SetRawTexture("ui_gm_frame_56").Coroutine();
				self._MaskImage.SetRawTexture("ui_gm_frame_56", nativeSize: false, show: false).Coroutine();
				self._StageText.GameObject.GetComponent<SuperOutline>().effectColor = new Color(24f / 85f, 41f / 85f, 0.69803923f);
			}
			self._StatText.SetActive(active: false);
			self._StatText.CloneAll(config.AddStat.Length, delegate(int i, UIObject o)
			{
				Stat stat = config.AddStat[i];
				string text = "";
				text = ((currentLevel != config.Level) ? TextHelper.FormatStat(stat, "+{0}") : TextHelper.FormatStat(stat, "<color=#0db64d>+{0}</color>"));
				o.SetText("宝石" + text);
			}).Coroutine();
		}
