		private static void LoadTextInfo(this UIVibesGemPlusPanel self)
		{
			self._CommonBg.SetTitle("");
			JobConfig jobConfig = ConfigSingleton<JobConfigCategory>.Instance.Get(self.SelectJob);
			self._ImageJob.SetSprite("ui_common_job_s_" + jobConfig.Id).Coroutine();
			self._Title.SetText(jobConfig.Name + "宝石大师");
			self._ExcellentTipText.SetText(Language.Format(2, 125, jobConfig.Name));
		}

		private static void UpdateView(this UIVibesGemPlusPanel self)
		{
			self.StoneExcellentList.Clear();
			VibesGemModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VibesGemModule>();
			int gemStoneExcellentBeginConfigId = component.GetGemStoneExcellentBeginConfigId(self.SelectJob);
			self.TotalGemStoneLevel = component.GetGemTotalLevel(self.SelectJob);
			self.CurrentExcellentLevel = component.GetGemPlusLevel(self.SelectJob);
			for (int i = gemStoneExcellentBeginConfigId; i < gemStoneExcellentBeginConfigId + 100 && ConfigSingleton<VibesGemStoneExcellentConfigCategory>.Instance.Contain(i); i++)
			{
				self.StoneExcellentList.Add(i);
			}
			self._UIGemStoneExcellentScroll.SetData(self.StoneExcellentList.Count);
			int currentIndex = component.GetGemPlusLevel(self.SelectJob);
			int num = self.StoneExcellentList.FindIndex((int item) => ConfigSingleton<VibesGemStoneExcellentConfigCategory>.Instance.Get(item).Level == currentIndex);
			num = math.max(num - 1, 0);
			self._UIGemStoneExcellentScroll.MovePanelToItemIndex(num);
			self._Power.SetPower(component.GetGemPlusPower(self.SelectJob));
		}

		private static void OnCellUpdate(this UIVibesGemPlusPanel self, UIScrollListCell cell)
		{
			int index = cell.Index;
			if (index < self.StoneExcellentList.Count)
			{
				((Entity)cell.UIObject).GetComponent<UIVibesGemPlusItem>().SetData(self.StoneExcellentList[index], self.CurrentExcellentLevel, self.TotalGemStoneLevel);
			}
		}
	}
