		private static void InitBind(this UIVipPanel self)
		{
			Player player = ((Entity)(object)self).LocalPlayer();
			VipModule vipModule = ((Entity)player).GetComponent<VipModule>();
			RoleInfoModule roleInfoModule = ((Entity)player).GetComponent<RoleInfoModule>();
			ItemModule itemModule = ((Entity)player).GetComponent<ItemModule>();
