			{
				self._VipLevel.SetText(newLevel.ToString());
			}, () => vipModule.Level_C);
			((Entity)(object)self).BindDataWithAutoUnBind((Entity)(object)roleInfoModule, "ConsecutiveLoginDays_C", delegate(int _, int days)
			{
				int expByLoginDays = VipHelper.GetExpByLoginDays(days);
				self._Desc.SetText(Language.Format(2, 325, days, expByLoginDays));
			}, () => roleInfoModule.ConsecutiveLoginDays_C);
			SuperSlider expSlider = ((Component)self._ExpSlider.Transform).GetComponent<SuperSlider>();
			((Entity)(object)self).BindDataWithAutoUnBind((Entity)(object)itemModule, 27.ToString(), delegate(long _, long exp)
			{
				var (num, num2) = VipHelper.CalculateNeedExp(exp);
				((Slider)expSlider).minValue = 0f;
				((Slider)expSlider).maxValue = num2;
				((Slider)expSlider).value = num;
				self._ExpNumber.SetText($"{num}/{num2}");
			}, () => itemModule.GetItemNumsByItemId(27));
			((Entity)(object)self).BindDataWithAutoUnBind((Entity)(object)vipModule, "GetFreeGiftTime_C", delegate
			{
				bool flag = vipModule.IsGetGift(TimeHelper.Now());
				self._GiftIconOpen.SetActive(flag);
				self._GiftIconClose.SetActive(!flag);
			}, () => vipModule.GetFreeGiftTime_C);
			((Entity)(object)self).BindData("SelectVipConfigId", delegate(int _, int selectVipConfigId)
			{
				VipConfig vipConfig = ConfigSingleton<VipConfigCategory>.Instance.Get(selectVipConfigId);
				self._TitleText.SetText(Language.Format(2, 326, vipConfig.Level));
				self.InitPrivilegeList(selectVipConfigId);
			});
			((Entity)(object)self).BindData("SelectVipConfigId", delegate(int _, int selectVipConfigId)
			{
				self.InitVipGift(selectVipConfigId);
			});
