		public static void InitVipGift(this UIVipPanel self, int selectVipConfigId)
		{
			Player player = ((Entity)(object)self).LocalPlayer();
			VipModule component = ((Entity)player).GetComponent<VipModule>();
			ItemModule itemModule = ((Entity)player).GetComponent<ItemModule>();
			VipConfig vipConfig = ConfigSingleton<VipConfigCategory>.Instance.Get(selectVipConfigId);
			VipGift vipGift = ConfigSingleton<VipGiftCategory>.Instance.Get(vipConfig.JadeGift);
			VipGift vipGift2 = ((vipConfig.CashGift != 0) ? ConfigSingleton<VipGiftCategory>.Instance.Get(vipConfig.CashGift) : null);
			bool isLock = component.Level_C < vipConfig.Level;
			VipGiftInfo orCreateVipGiftInfo = component.GetOrCreateVipGiftInfo(vipConfig.Level);
			int num = vipGift?.GiftNum ?? 0;
			if (orCreateVipGiftInfo.JadeGiftBuyTimes < num)
			{
				SetBuyButton(vipGift, isSoldOut: false);
				self._BuyTimes.SetText(Language.Format(2, 502, orCreateVipGiftInfo.JadeGiftBuyTimes, num));
			}
			else if (vipGift2 != null)
			{
				SetBuyButton(vipGift2, orCreateVipGiftInfo.CashGiftBuyTimes >= vipGift2.GiftNum);
				self._BuyTimes.SetText(Language.Format(2, 502, orCreateVipGiftInfo.CashGiftBuyTimes, vipGift2.GiftNum));
			}
			else
			{
				SetBuyButton(vipGift, isSoldOut: true);
				self._BuyTimes.SetText(Language.Format(2, 502, orCreateVipGiftInfo.JadeGiftBuyTimes, num));
			}
			void SetBuyButton(VipGift giftConfig, bool isSoldOut)
			{
				DropShowConfig dropShowConfig = ConfigSingleton<DropShowConfigCategory>.Instance.Get(giftConfig.Gift);
				using ItemList itemList = ItemList.Create();
				itemList.AddRange(dropShowConfig.Items);
				self._UICommonHorizontalReward.SetData(itemList);
				self._UICommonHorizontalReward.RefreshContentWidth();
				self._BuyButton.SetGray(isSoldOut | isLock);
				self._BuyButton.SetSprite("ui_common_btn_03").Coroutine();
				self._BuyButton.SetRedPoint(RedPointType.Vip, 2, selectVipConfigId).Coroutine();
				self._DiscountImg.SetActive(active: false);
				if (isLock)
				{
					self._MoneyType.SetActive(active: false);
					((Behaviour)self._MoneyNumsText.GameObject.GetComponent<SuperOutline>()).enabled = true;
					self._MoneyNumsText.SetText(Language.Get(2, 503));
				}
				else if (isSoldOut)
				{
					self._MoneyType.SetActive(active: false);
					((Behaviour)self._MoneyNumsText.GameObject.GetComponent<SuperOutline>()).enabled = true;
					self._MoneyNumsText.SetText(Language.Get(2, 501));
				}
				else if (giftConfig.GiftType == 1)
				{
					if (giftConfig.GiftPrice == null)
					{
						self._MoneyType.SetActive(active: false);
						((Behaviour)self._MoneyNumsText.GameObject.GetComponent<SuperOutline>()).enabled = true;
						self._MoneyNumsText.SetText(Language.Get(2, 500));
						self._BuyButton.SetSprite("ui_common_btn_36").Coroutine();
					}
					else
					{
						self._MoneyType.SetActive(active: true);
						self._MoneyImage.SetRawTexture($"uitex_icon_item_{giftConfig.GiftPrice.Id}", nativeSize: true).Coroutine();
						int nums = giftConfig.GiftPrice.Nums;
						bool flag = itemModule.GetItemNumsByItemId(giftConfig.GiftPrice.Id) >= nums;
						self._MoneyNumsText.SetText(nums.ToString());
						self._MoneyNumsText.SetText(flag ? nums.ToString() : $"<color=#de0008>{nums}</color>");
						((Behaviour)self._MoneyNumsText.GameObject.GetComponent<SuperOutline>()).enabled = flag;
						self._DiscountImg.SetActive(giftConfig.Discount > 0);
						self._DiscountText.SetText(Language.Format(4, 841, (float)giftConfig.Discount / 100f));
					}
				}
				else
				{
					self._MoneyType.SetActive(active: false);
					long num2 = ConfigSingleton<PayConfigCategory>.Instance.Get(giftConfig.GiftCharging).Price / 100;
					self._MoneyNumsText.SetText(Language.Format(4, 744, num2));
					((Behaviour)self._MoneyNumsText.GameObject.GetComponent<SuperOutline>()).enabled = true;
					self._DiscountImg.SetActive(giftConfig.Discount > 0);
					self._DiscountText.SetText($"{giftConfig.Discount}%");
				}
			}
		}

		private static void InitPrivilegeList(this UIVipPanel self, int selectVipConfigId)
		{
			Dictionary<PrivilegeType, VipPrivilegeDescData> dictionary = new Dictionary<PrivilegeType, VipPrivilegeDescData>();
			for (int i = 1; i <= selectVipConfigId; i++)
			{
				VipConfig vipConfig = ConfigSingleton<VipConfigCategory>.Instance.Get(i);
				if (vipConfig.PrivilegeId == 0)
				{
					continue;
				}
				PrivilegeCardConfig privilegeCardConfig = ConfigSingleton<PrivilegeCardConfigCategory>.Instance.Get(vipConfig.PrivilegeId);
				for (PrivilegeType privilegeType = PrivilegeType.CLDailyCount; privilegeType < PrivilegeType.Max; privilegeType++)
				{
					int num = (int)privilegeType;
					int num2 = privilegeCardConfig.Values[num];
					if (num2 != 0)
					{
						if (!dictionary.TryGetValue(privilegeType, out var value))
						{
							value = new VipPrivilegeDescData();
							value.IsNew = i == selectVipConfigId;
							value.PrivilegeType = privilegeType;
							dictionary[privilegeType] = value;
						}
						value.Inc += num2;
					}
				}
			}
			self.PrivilegeDescDataList = dictionary.Values.ToList();
			self.PrivilegeDescDataList.Sort((VipPrivilegeDescData a, VipPrivilegeDescData b) => (a.IsNew == b.IsNew) ? (a.PrivilegeType - b.PrivilegeType) : ((b.IsNew ? 1 : 0) - (a.IsNew ? 1 : 0)));
			self._UIScrollListPrivilege.SetData(self.PrivilegeDescDataList.Count);
		}

		private static void InitVipList(this UIVipPanel self, int viewVipLevel, int currentVipLevel)
		{
			self.VipConfigIds.Clear();
			for (int i = 1; i <= viewVipLevel; i++)
			{
				self.VipConfigIds.Add(i);
			}
			self._UIScrollListVip.SetData(0);
			self._UIScrollListVip.SetData(self.VipConfigIds.Count);
			int num = self.VipConfigIds.IndexOf((currentVipLevel == 0) ? 1 : currentVipLevel);
			int num2 = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VipModule>().CanBuyRmbGift() - 1;
			self._UIScrollListVip.MovePanelToItemIndex((num2 >= 0 && !self.ISFIREST) ? num2 : num);
			self._UIScrollListVip.SetSelectIndex((num2 >= 0 && !self.ISFIREST) ? num2 : num);
		}

		private static void OnVipCellClick(this UIVipPanel self, int configId)
		{
			if (configId != 0)
			{
				self.SelectVipConfigId = configId;
			}
		}

		private static void OnVipCellUpdate(this UIVipPanel self, UIScrollListCell cell)
		{
			int index = cell.Index;
			if (index < self.VipConfigIds.Count)
			{
				VipModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<VipModule>();
				int num = self.VipConfigIds[index];
				UIVipLevelItem component2 = ((Entity)cell.UIObject).GetComponent<UIVipLevelItem>();
				component2.SetData(num, self);
				int num2 = ((component.Level_C == 0) ? 1 : component.Level_C);
				if (component.CanBuyRmbGift() - 1 >= 0 && !self.ISFIREST)
				{
					self.ISFIREST = true;
					component2.SetSelected();
				}
				else if (num == num2 && !self.ISFIREST)
				{
					component2.SetSelected();
				}
			}
		}

		private static void OnVipCellCreate(this UIVipPanel self, UIScrollListCell cell)
		{
			((Entity)cell.UIObject).GetComponent<UIVipLevelItem>().SetOnClick(self.OnVipCellClick);
		}

		private static void OnPrivilegeCellUpdate(this UIVipPanel self, UIScrollListCell cell)
		{
			int index = cell.Index;
			if (index < self.PrivilegeDescDataList.Count)
			{
				((Entity)cell.UIObject).GetComponent<UIVipPrivilegeItem>().SetData(self.PrivilegeDescDataList[index], index);
			}
		}

		public static void OnChangeVipLevel(this UIVipPanel self)
		{
			for (int i = 0; i < self._UIScrollListVip.Count; i++)
			{
				UIScrollListCell cell = self._UIScrollListVip.GetCell(i);
				if (cell != null)
				{
					((Entity)cell.UIObject).GetComponent<UIVipLevelItem>()?.OnRefresh();
				}
			}
			self.InitVipGift(self.SelectVipConfigId);
		}
	}
