	[RedPointHandler(RedPointType.VipButler)]
	public class VipButlerRedPointHandler : ARedPointHandler
	{
		public override int GetCount(Scene scene, params int[] parameters)
		{
			Player player = ((Entity)scene).GetComponent<LocalPlayerComponent>().Player;
			if (player == null)
			{
				return 0;
			}
			if (!TimeHelper.IsSameDay(player.GetLocalLong("VIPButler.ShowTime", 0L), TimeHelper.ServerNow(), 18000000L))
			{
				return 1;
			}
			return 0;
		}
	}
