				self._UITileView.SetData(self.WeekCardSubConfigs.Count);
				self._UITileView.EnableScroll(self.WeekCardSubConfigs.Count > 7);
				self.InitActivityTime();
				self.BuySuccess();
				self.GetSuccess();
			}
		}

