		public static void BuySuccess(this UIWeekCardPanel self)
		{
			WeekCardModule component = ((Entity)self.ActivityData).GetComponent<WeekCardModule>();
			self._BuyBtn.SetActive(!component.IsBuy());
			self._GetBtn.SetActive(component.CanGet());
			self._GetAllText.SetActive(component.IsGetAll());
			self.InitNextDay();
			RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.Activity, self.ActivityData.ActivityId);
		}

		public static void GetSuccess(this UIWeekCardPanel self)
		{
			WeekCardModule component = ((Entity)self.ActivityData).GetComponent<WeekCardModule>();
			self._GetBtn.SetActive(component.CanGet());
			self._GetAllText.SetActive(component.IsGetAll());
			self.InitNextDay();
			RedPointHelper.RefreshRedPoint(SceneHelper.DomainScene((Entity)(object)self), RedPointType.Activity, self.ActivityData.ActivityId);
		}

		private static void InitNextDay(this UIWeekCardPanel self)
		{
			WeekCardModule module = ((Entity)self.ActivityData).GetComponent<WeekCardModule>();
			if (module.CanGetTime() > 0)
			{
				self._GetTimer.SetActive(active: true);
				if (self.GetTimer > 0)
				{
					self.RemoveTimer(ref self.GetTimer);
				}
				self.NewTimer(1000L, SetGetTime, repeat: true);
				SetGetTime();
			}
			else
			{
				self._GetTimer.SetActive(active: false);
				if (self.GetTimer > 0)
				{
					self.RemoveTimer(ref self.GetTimer);
				}
			}
			void SetGetTime()
			{
				string str = TimeSpan.FromSeconds((float)module.CanGetTime() / 1000f).ToString("hh\\:mm\\:ss");
				self._GetTimerText.SetText(str);
			}
		}

		private static void OnCellUpdate(this UIWeekCardPanel self, UIObject cell, int index)
		{
			if (self.WeekCardSubConfigs.Count > index)
			{
				WeekCardSubConfig config = self.WeekCardSubConfigs[index];
				((Entity)cell).GetComponent<UIWeekCardItem>().SetData(self.ActivityData, config, index == self.WeekCardSubConfigs.Count - 1);
			}
		}
	}
