				}
			}
			self.SetTabs().Coroutine();
		}

		private static void InitPanel(this UIWorldBossMainPanel self, int funcId, Func<int> GetDefaultIndex = null)
		{
			self.AddAllActivity();
		}

		private static void SortTabs(this UIWorldBossMainPanel self)
		{
			self.Tabs.Sort(UITabInfoSystem.CompareTo);
		}

		private static void AddAllActivity(this UIWorldBossMainPanel self)
		{
			List<ActivityData> allActivity = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<PlayerActivityComponent>().GetAllActivity(ActivityCenterType.WorldBossPanel);
			self.Tabs.Clear();
			List<ActivityData> list = allActivity.Where((ActivityData a) => a.ActivityType == ActivityType.WorldBoss && a.State == ActivityState.Open).ToList();
			List<ActivityData> list2 = allActivity.Where((ActivityData a) => a.ActivityType == ActivityType.CrossWorldBoss && a.State == ActivityState.Open).ToList();
			if (list2.Count > 0)
			{
				list.Clear();
			}
			list.AddRange(list2);
			foreach (ActivityData item in list)
			{
				if ((item.ActivityType == ActivityType.WorldBoss) ? ActivityHelper.GetActivityModule<WorldBossModule>(((Entity)(object)self).LocalPlayer(), item.ActivityId).IsShow() : ActivityHelper.GetActivityModule<CrossWorldBossModule>(((Entity)(object)self).LocalPlayer(), item.ActivityId).IsShow())
				{
					UITabInfo uITabInfo = UITabInfo.CreateWithActivity(item.ActivityId);
					uITabInfo.SetIcon(item.GetIcon(), item.GetIconEffect());
					uITabInfo.SetSort(item.Sort);
					uITabInfo.Text = item.Name;
					Type uI = ActivityMainUIComponent.Instance.GetUI(item.ActivityType, item.BaseInfo.ActivityType, isSubView: true);
					if (uI != null)
					{
						uITabInfo.SetUIName(uI.Name);
					}
					uITabInfo.SetRedPoint(RedPointType.Activity, item.ActivityId);
					self.Tabs.Add(uITabInfo);
				}
			}
			self.SetTabs().Coroutine();
		}
	}
