		public static void SetData(this UIWorldBossMiniRankItem self, int rank, string name, long damage)
		{
			if (!string.IsNullOrEmpty(name))
			{
				name = ((name.Length > 4) ? (name.Substring(0, 4) + "...") : name);
			}
			switch (rank)
			{
			case 0:
				self._RankImage.SetActive(active: false);
				self._RankText.SetActive(active: true);
				self._RankText.SetText(Language.Get(2, 314));
				break;
			case 1:
				self._RankText.SetActive(active: false);
				self._RankImage.SetActive(active: true);
				self._RankImage.SetSprite("ui_rl_sign_06").Coroutine();
				break;
			case 2:
				self._RankText.SetActive(active: false);
				self._RankImage.SetActive(active: true);
				self._RankImage.SetSprite("ui_rl_sign_07").Coroutine();
				break;
			case 3:
				self._RankText.SetActive(active: false);
				self._RankImage.SetActive(active: true);
				self._RankImage.SetSprite("ui_rl_sign_08").Coroutine();
				break;
			default:
				self._RankImage.SetActive(active: false);
				self._RankText.SetActive(active: true);
				self._RankText.SetText(rank.ToString());
				break;
			}
			self._Name.SetText(name);
			self._Damage.SetText(TextHelper.FormatDamage(damage));
		}
	}
