		private static void RefreshOwnRank(this UIWorldBossPeronalRank self)
		{
			switch (self.ParentPanel.ShowType)
			{
			case WorldBossShowType.WorldBoss:
				switch (self.ParentPanel.TitleTag)
				{
				case 2:
				{
					WorldBossRankRewardConfig rewardConfig2 = null;
					foreach (WorldBossRankRewardConfig data in self.DataList)
					{
						if (data.RankRange.Length == 1 && data.RankRange[0] == self.MyRank)
						{
							rewardConfig2 = data;
							break;
						}
						if (data.RankRange.Length == 2 && self.MyRank >= data.RankRange[0] && self.MyRank <= data.RankRange[1])
						{
							rewardConfig2 = data;
							break;
						}
					}
					self._WorldBossOwnRankItem.SetMySelfReward(rewardConfig2, self.MyRank);
					break;
				}
				case 1:
					self._WorldBossOwnRankItem.SetMySelfRank(self.MyRank, ((Entity)self.ParentPanel.ActivityData).GetComponent<WorldBossModule>().Damage_C, showServerName: false);
					break;
				}
				break;
			case WorldBossShowType.CrossWorldBoss:
				switch (self.ParentPanel.TitleTag)
				{
				case 2:
				{
					CrossWorldBossRankRewardConfig rewardConfig = null;
					foreach (CrossWorldBossRankRewardConfig item in self.DataList2)
					{
						if (item.RankRange.Length == 1 && item.RankRange[0] == self.MyRank)
						{
							rewardConfig = item;
							break;
						}
						if (item.RankRange.Length == 2 && self.MyRank >= item.RankRange[0] && self.MyRank <= item.RankRange[1])
						{
							rewardConfig = item;
							break;
						}
					}
					self._WorldBossOwnRankItem.SetMySelfReward(rewardConfig, self.MyRank);
					break;
				}
				case 1:
					self._WorldBossOwnRankItem.SetMySelfRank(self.MyRank, ((Entity)self.ParentPanel.ActivityData).GetComponent<CrossWorldBossModule>().Damage_C, showServerName: true);
					break;
				}
				break;
			}
		}

		private static void InitBind(this UIWorldBossPeronalRank self)
		{
