		private static void OnCellUpdate(this UIWorldBossPeronalRank self, UIScrollListCell cell)
		{
			int index = cell.Index;
			UIWorldBossRankItem component = ((Entity)cell.UIObject).GetComponent<UIWorldBossRankItem>();
			switch (self.ParentPanel.TitleTag)
			{
			case 1:
				if (index < self.RankList.Count)
				{
					component.SetPersonalRank(self.RankList[index], self.ParentPanel.ShowType == WorldBossShowType.CrossWorldBoss);
				}
				break;
			case 2:
				switch (self.ParentPanel.ShowType)
				{
				case WorldBossShowType.WorldBoss:
					if (index < self.DataList.Count)
					{
						component.SetPersonalReward(self.DataList[index]);
					}
					break;
				case WorldBossShowType.CrossWorldBoss:
					if (index < self.DataList2.Count)
					{
						component.SetPersonalReward(self.DataList2[index]);
					}
					break;
				}
				break;
			}
		}

