		private static void InitEndTime(this UIWorldBossRankPanel self)
		{
			if (self.CountDownTimer > 0)
			{
				self.RemoveTimer(ref self.CountDownTimer);
			}
			self.CountDownTimer = self.NewTimer(1000L, UpdateTime, repeat: true);
			UpdateTime();
			void UpdateTime()
			{
				long num = self.ActivityData.EndTime - TimeHelper.Now();
				if (num < 0)
				{
					num = 0L;
				}
				if (num == 0L)
				{
					self.RemoveTimer(ref self.CountDownTimer);
				}
				self._UIWorldBossPeronalRank.CountDown(num);
				self._UIWorldBossGroupRank.CountDown(num);
			}
		}

