		[UIMethod]
		public static void OnAwake(this UIWorldBossRewardItem self)
		{
			self._UIScrollList.Handler.onUpdate += self.OnCellUpdate;
		}

		private static void OnCellUpdate(this UIWorldBossRewardItem self, UIScrollListCell cell)
		{
			UIWorldBossRewardCell component = ((Entity)cell.UIObject).GetComponent<UIWorldBossRewardCell>();
			ET.ConfigBeans.Item item = null;
			bool isDouble = false;
			switch (self.ShowType)
			{
			case WorldBossShowType.WorldBoss:
				item = ConfigSingleton<WorldBossHarmConfigCategory>.Instance.Get(self.ConfigId).RewardID;
				break;
			case WorldBossShowType.CrossWorldBoss:
			{
				CrossWorldBossHarmConfig crossWorldBossHarmConfig = ConfigSingleton<CrossWorldBossHarmConfigCategory>.Instance.Get(self.ConfigId);
				item = crossWorldBossHarmConfig.PreviewRewardItem;
				isDouble = item.Nums * 2 == crossWorldBossHarmConfig.RewardID.Nums;
				break;
			}
			}
			component.SetItem(item);
			component.SetDoubleTag(isDouble);
		}

		public static void SetInfo(this UIWorldBossRewardItem self, int id, WorldBossShowType showType)
		{
			string str = string.Empty;
			ET.ConfigBeans.Item item = null;
			self.ShowType = showType;
			self.ConfigId = id;
			switch (showType)
			{
			case WorldBossShowType.WorldBoss:
			{
				WorldBossHarmConfig worldBossHarmConfig = ConfigSingleton<WorldBossHarmConfigCategory>.Instance.Get(id);
				str = worldBossHarmConfig.Text;
				item = worldBossHarmConfig.RewardID;
				break;
			}
			case WorldBossShowType.CrossWorldBoss:
			{
				CrossWorldBossHarmConfig crossWorldBossHarmConfig = ConfigSingleton<CrossWorldBossHarmConfigCategory>.Instance.Get(id);
				str = crossWorldBossHarmConfig.Text;
				item = crossWorldBossHarmConfig.PreviewRewardItem;
				break;
			}
			}
			self._Text.SetText(str);
			ItemList itemList = new ItemList();
			itemList.Add(item);
			self._UIScrollList.SetData(itemList.Count);
		}
	}
