		[UIMethod]
		public static void OnShow(this UIWorldBossRewardPanel self, (int season, WorldBossShowType showType) args)
		{
			self.ShowType = args.showType;
			self.InitPanel(args.season);
		}

		private static void InitPanel(this UIWorldBossRewardPanel self, int season)
		{
			self.ShowId.Clear();
			switch (self.ShowType)
			{
			case WorldBossShowType.WorldBoss:
				foreach (WorldBossHarmConfig item in ConfigSingleton<WorldBossHarmConfigCategory>.Instance.GetBySeason(season))
				{
					self.ShowId.Add(item.Id);
				}
				break;
			case WorldBossShowType.CrossWorldBoss:
				foreach (CrossWorldBossHarmConfig item2 in ConfigSingleton<CrossWorldBossHarmConfigCategory>.Instance.GetBySeason(season))
				{
					self.ShowId.Add(item2.Id);
				}
				break;
			}
			self._UIScrollList.SetData(self.ShowId.Count);
		}

		public static void OnCellUpdate(this UIWorldBossRewardPanel self, UIScrollListCell cell)
		{
			((Entity)cell.UIObject).GetComponent<UIWorldBossRewardItem>().SetInfo(self.ShowId[cell.Index], self.ShowType);
		}
	}
