		public static void RefreshButton(this UIZeroMoneyBuyPanel self)
		{
			ZeroMoneyBuyModule component = ((Entity)self.ActivityData).GetComponent<ZeroMoneyBuyModule>();
			component.GetGiftState().TryGetValue(self.Config.Id, out var value);
			self.ZeroGiftState = value;
			self._RewardList.SetData(self.Config.RewadItems);
			self._RewardList.SetGray(self.ZeroGiftState.IsCanGetReward || self.ZeroGiftState.IsGetOutReward);
			RectTransform component2 = ((Component)self._RewardList.UIObject.Find("_ScrollView").Transform).GetComponent<RectTransform>();
			int num = ((self.Config.RewadItems.Length > 4) ? 4 : self.Config.RewadItems.Length);
			component2.SetSizeWithCurrentAnchors((Axis)0, (float)(num * 160));
			self._DiscountImg.SetActive(self.ZeroGiftState.GiftIsOpen && !self.ZeroGiftState.IsCanGetReward && !self.ZeroGiftState.IsGetOutReward);
			if (self.Config.Type == 1)
			{
				self._DiscountText.SetText(Language.Format(4, 841, (float)self.Config.Discount / 100f));
			}
			if (self.Config.Type == 2)
			{
				self._DiscountText.SetText(self.Config.Discount + "%");
			}
			self._NoBuyText.SetText(Language.Format(3, 175, (self.ZeroGiftState.GiftOpenTime - TimeHelper.BeginTimeOfDay(TimeHelper.ServerNow(), 18000000L)) / 86400000));
			self._NoBuyText.SetActive(!self.ZeroGiftState.GiftIsOpen);
			self._GetOutBtn.SetActive(self.ZeroGiftState.IsGetOutReward);
			if (self.GiftTabs.TryGetValue(self.Config.Id, out var value2))
			{
				value2.SetGetOutReward(self.ZeroGiftState.IsGetOutReward);
			}
			self._BuyBtn.SetActive(!self.ZeroGiftState.IsGetOutReward);
			if (self.ZeroGiftState.IsCanGetReward)
			{
				self._RMBText.SetActive(active: false);
				self._JadeBuy.SetActive(active: true);
				bool flag = self.ZeroGiftState.IsCanGetReward && TimeHelper.ServerNow() > TimeHelper.EndTimeOfDay(value.ReturnEndTime - 86400000, 18000000L);
				self._ReturnNumText.SetActive(self.ZeroGiftState.IsCanGetReward && self.Config.RewardRetrunType == 2 && !flag);
				if ((TimeHelper.Now() > self.ActivityData.EndTime - 86400000 || self.Config.RewardRetrunType == 1) | flag)
				{
					self._BuyText.SetText(Language.Get(3, 183));
					self._ReturnNumText.SetActive(active: false);
				}
				else
				{
					self._BuyText.SetText(Language.Get(3, 174));
				}
				self._BuyJadeText.SetText($"{component.GetReturnJadeNums(self.Config.Id)}");
				self._BuyBtn.SetGray(TimeHelper.Now() < self.ZeroGiftState.NextReturnTime);
				self._BuyBtn.SetSprite("ui_common_btn_37").Coroutine();
			}
			else
			{
				self._ReturnNumText.SetActive(active: false);
				self._BuyText.SetText(Language.Get(3, 174));
				self._BuyBtn.SetGray(!self.ZeroGiftState.GiftIsOpen);
				self._BuyBtn.SetSprite("ui_common_btn_33").Coroutine();
			}
			self._BuyText.SetActive(!self._ReturnNumText.IsActiveInHierarchy());
			string text = "";
			text = $"{self.ZeroGiftState.ReturnDayNum}/{((self.Config.RewardRetrunTime == 0L) ? 1 : (self.Config.RewardRetrunTime * 1000 / 86400000))}";
			self._ReturnNumText.SetText(Language.Format(3, 177, text) ?? "");
			self._UnOpenTimer.SetActive(!self.ZeroGiftState.GiftIsOpen || (self.ZeroGiftState.NextReturnTime > 0 && TimeHelper.Now() < self.ZeroGiftState.NextReturnTime));
			if (TimeHelper.Now() > self.ActivityData.EndTime - 86400000 && self.ZeroGiftState.IsCanGetReward)
			{
				self._UnOpenTimer.SetActive(active: false);
			}
			self._TimerText.SetText(self.ZeroGiftState.IsCanGetReward ? Language.Get(3, 172) : Language.Get(3, 171));
			if (((self.ZeroGiftState.GiftIsShow && !self.ZeroGiftState.GiftIsOpen) || self.ZeroGiftState.IsCanGetReward) && self.CountDownTimer <= 0)
			{
				self.CountDownTimer = self.NewTimer(1000L, self.CountDown, repeat: true);
				self.CountDown();
			}
			self.RefreshRed();
		}

		public static void RefreshRed(this UIZeroMoneyBuyPanel self)
		{
			foreach (KeyValuePair<int, UIZeroMoneyBuyTabButton> giftTab in self.GiftTabs)
			{
				giftTab.Deconstruct(out var _, out var value);
				value.SetRedPoint();
			}
		}

		private static void CountDown(this UIZeroMoneyBuyPanel self)
		{
			long num = (self.ZeroGiftState.IsCanGetReward ? self.ZeroGiftState.NextReturnTime : self.ZeroGiftState.GiftOpenTime) - TimeHelper.Now();
			if (num > 0)
			{
				num /= 1000;
				long num2 = num / 86400;
				long num3 = num % 86400 / 3600;
				long num4 = num % 3600 / 60;
				long num5 = num % 60;
				UIHelper.SetText(str: (num2 <= 0) ? $"{num3:D2}:{num4:D2}:{num5:D2}" : string.Format("{0}天{1:D2}:{2:D2}:{3:D2}", new object[4] { num2, num3, num4, num5 }), self: self._CountTimeText);
			}
		}

		private static void CountDownTop(this UIZeroMoneyBuyPanel self)
		{
			long num = self.ActivityData.EndTime - TimeHelper.Now();
			if (num > 0)
			{
				num /= 1000;
				long num2 = num / 86400;
				long num3 = num % 86400 / 3600;
				long num4 = num % 3600 / 60;
				long num5 = num % 60;
				UIHelper.SetText(str: (num2 <= 0) ? $"{num3:D2}:{num4:D2}:{num5:D2}" : string.Format("{0}天{1:D2}:{2:D2}:{3:D2}", new object[4] { num2, num3, num4, num5 }), self: self._CountTimeTextTop);
			}
		}

