		private static void OnClick(this UIZeroMoneyBuyTabButton self)
		{
			self.SetSelected(selected: true);
			UIObject.FindUIObjectOfType<UIZeroMoneyBuyPanel>()?.SetCurrentGiftInfo(self.Config);
		}

		public static void SetData(this UIZeroMoneyBuyTabButton self, ZeroMoneyBuyGiftConfig config, int index, int actId)
		{
			self.ActId = actId;
			self.ActivityData = ActivityHelper.GetActivityData(((Entity)(object)self).LocalPlayer(), actId);
			((Entity)self.ActivityData).GetComponent<ZeroMoneyBuyModule>().GetGiftState().TryGetValue(config.Id, out var value);
			self.UIObject.SetActive(value.GiftIsShow);
			self._SelectBg.SetRawTexture("ui_sjzs_frame_05", nativeSize: false, show: false).Coroutine();
			((Object)self.UIObject.Transform).name = "UIZeroMoneyBuyTabButton" + config.Id;
			self.Config = config;
			self._OpenGo.SetActive(value.GiftIsOpen);
			self._TabOpenBtnText.SetActive(value.GiftIsOpen);
			self._UnOpenGo.SetActive(!value.GiftIsOpen);
			self._TabUnOpenBtnText.SetActive(!value.GiftIsOpen);
			self._TabUnOpenText.SetActive(!value.GiftIsOpen);
			self._TabOpenBtnImage.SetSprite(self.Config.GiftTitleBg).Coroutine();
			self._TabUnOpenText.SetText(Language.Format(3, 170, (value.GiftOpenTime - TimeHelper.BeginTimeOfDay(TimeHelper.ServerNow(), 18000000L)) / 86400000));
			self._TabUnOpenBtnText.SetText(config.GiftTitle);
			self._TabOpenBtnText.SetText(config.GiftTitle);
			self.SetGetOutReward(value.IsGetOutReward);
		}

		public static void SetSelected(this UIZeroMoneyBuyTabButton self, bool selected)
		{
			self._SelectImage.SetActive(selected);
			self._SelectBg.SetActive(selected);
			TweenSettingsExtensions.SetEase<TweenerCore<Vector3, Vector3, VectorOptions>>(ShortcutExtensions.DOScale((Transform)(object)self.UIObject.Transform, selected ? 1f : 0.8f, 0.1f), (Ease)2);
		}

		public static void SetRedPoint(this UIZeroMoneyBuyTabButton self)
		{
			self._TabOpenBtnImage.SetRedPoint(RedPointType.Activity, self.ActId, self.Config.Id).Coroutine();
		}

		public static void SetGetOutReward(this UIZeroMoneyBuyTabButton self, bool getOutReward)
		{
			self._TabCom.SetActive(getOutReward);
		}
	}
