		public static void FinishMainTaskHandler(this GuideComponent self)
		{
			Player player = ((Entity)(object)SceneHelper.DomainScene((Entity)(object)self)).LocalPlayer();
			if (player == null)
			{
				return;
			}
			int mainTaskId = ((Entity)player).GetComponent<TaskModule>().MainTaskId;
			if (mainTaskId == 0)
			{
				return;
			}
			List<int> list = new List<int>();
			foreach (int open in self.OpenList)
			{
				GuideConfig guideConfig = ConfigSingleton<GuideConfigCategory>.Instance.Get(open);
				if (guideConfig.TriggerParams != null && guideConfig.TriggerType == 6 && int.Parse(guideConfig.TriggerParams[0]) == mainTaskId)
				{
					self.IngDict.Add(open, guideConfig.FirstStep);
					list.Add(open);
				}
			}
			foreach (int item in list)
			{
				self.OpenList.Remove(item);
			}
			self.ExecuteGuide();
		}

