				return;
			}
			List<int> list = new List<int>();
			foreach (int open in self.OpenList)
			{
				GuideConfig guideConfig = ConfigSingleton<GuideConfigCategory>.Instance.Get(open);
				if (guideConfig.TriggerParams != null && guideConfig.TriggerType == 3 && int.Parse(guideConfig.TriggerParams[0]) == mainTaskId)
				{
					self.IngDict.Add(open, guideConfig.FirstStep);
					list.Add(open);
				}
			}
			foreach (int item in list)
			{
				self.OpenList.Remove(item);
			}
			self.ExecuteGuide();
		}

		public static void NewbieHandler(this GuideComponent self, int newbieId)
		{
			if (self.OpenList.Count <= 0)
			{
				return;
			}
			List<int> list = new List<int>();
			foreach (int open in self.OpenList)
			{
				GuideConfig guideConfig = ConfigSingleton<GuideConfigCategory>.Instance.Get(open);
				if (guideConfig.TriggerType == 4 && int.Parse(guideConfig.TriggerParams[0]) == newbieId)
				{
					self.IngDict.Add(open, guideConfig.FirstStep);
					list.Add(open);
				}
			}
			foreach (int item in list)
			{
				self.OpenList.Remove(item);
			}
			self.ExecuteGuide();
		}

		public static void CheckGuide(this GuideComponent self)
		{
			if (!self.IsGuiding)
			{
				return;
			}
			int currentId = self.CurrentId;
			GuideConfig guideConfig = ConfigSingleton<GuideConfigCategory>.Instance.Get(currentId);
			if (guideConfig.TriggerType == 3)
			{
				TaskModule component = ((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<TaskModule>();
				int num = int.Parse(guideConfig.TriggerParams[0]);
				if (component.FinishTaskDict.ContainsKey(num))
				{
					self.FinishGuide(currentId);
					self.IsGuiding = false;
				}
				else if (component.MainTaskId == num && component.GetMainTask().Status == 1)
				{
					self.FinishGuide(currentId);
					self.IsGuiding = false;
				}
			}
			int num2 = self.CurrentId;
			int sort = guideConfig.Sort;
			foreach (var (num5, _) in self.IngDict)
			{
				if (num2 != num5)
				{
					GuideConfig guideConfig2 = ConfigSingleton<GuideConfigCategory>.Instance.Get(num5);
					if (guideConfig2.Sort > sort)
					{
						num2 = num5;
						sort = guideConfig2.Sort;
					}
				}
			}
			if (num2 != self.CurrentId)
			{
				self.FinishGuide(self.CurrentId);
				self.IsGuiding = false;
			}
		}

		private static void FinishGuide(this GuideComponent self, int guideId)
		{
			self.IngDict.Remove(guideId);
			if (ConfigSingleton<GuideConfigCategory>.Instance.Get(guideId).IsSave)
			{
				((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<GuideModule>().ReqSaveGuide(guideId);
				self.FinishList.Add(guideId);
			}
		}

		public static void PanelOpenHandler(this GuideComponent self, string panelName)
		{
			self.CheckGuide();
			if (self.IsGuiding)
			{
				GuideStepConfig guideStepConfig = ConfigSingleton<GuideStepConfigCategory>.Instance.Get(self.StepId);
				if (guideStepConfig.PanelName == panelName)
				{
					self.SimpleGuide(self.CurrentId, self.StepId);
					return;
				}
				IUI iUI = UIObject.FindUIObjectOfType(UIManager.Instance.UITypeName.GetKeyByValue(guideStepConfig.PanelName));
				if (iUI == null || !UIManager.Instance.IsTop(iUI, guideStepConfig.IsClose))
				{
					UIManager.Instance.Remove(typeof(UIGuidePanel));
				}
			}
			else
			{
				self.ExecuteGuide();
			}
		}

		public static void FuncOpenHandler(this GuideComponent self, int funcId)
		{
			bool flag = false;
			if (self.OpenList.Count <= 0)
			{
				return;
			}
			List<int> list = new List<int>();
			foreach (int open in self.OpenList)
			{
				GuideConfig guideConfig = ConfigSingleton<GuideConfigCategory>.Instance.Get(open);
				if (guideConfig.TriggerParams != null && guideConfig.TriggerType == 2 && int.Parse(guideConfig.TriggerParams[0]) == funcId)
				{
					flag = true;
					self.IngDict.Add(open, guideConfig.FirstStep);
					list.Add(open);
				}
			}
			if (!flag)
			{
				return;
			}
			foreach (int item in list)
			{
				self.OpenList.Remove(item);
			}
			self.ExecuteGuide();
		}

		public static void ExecuteGuide(this GuideComponent self, int id)
		{
			if (self.IsGuiding)
			{
				if (self.CurrentId == id)
				{
					self.SimpleGuide(id, self.StepId);
				}
			}
			else if (self.FinishList.IndexOf(id) < 0)
			{
				if (!self.IngDict.ContainsKey(id))
				{
					GuideConfig guideConfig = ConfigSingleton<GuideConfigCategory>.Instance.Get(id);
					self.IngDict.Add(id, guideConfig.FirstStep);
				}
				self.ExecuteGuide();
			}
		}

		public static void ExecuteGuide(this GuideComponent self)
		{
			self.CheckGuide();
			if (self.IsGuiding)
			{
				self.SimpleGuide(self.CurrentId, self.StepId);
				return;
			}
			foreach (var (id, num3) in self.IngDict)
			{
				if (ConfigSingleton<GuideStepConfigCategory>.Instance.Get(num3).PanelName == null || self.SimpleGuide(id, num3))
				{
					break;
				}
			}
		}

		public static void StopGuide(this GuideComponent self)
		{
			self.IsGuiding = false;
		}

		public static AGuideStepHandler GetHandler(this GuideComponent self, int AIId)
		{
			if (!self.StepHandlers.TryGetValue(AIId, out var value))
			{
				return null;
			}
			return value;
		}

		public static void NextGuide(this GuideComponent self)
		{
			if (self.StepId <= 0)
			{
				return;
			}
			GuideStepConfig guideStepConfig = ConfigSingleton<GuideStepConfigCategory>.Instance.Get(self.StepId);
			if (guideStepConfig.AIId != 0 && !self.StepHandlers.GetValue(guideStepConfig.AIId).IsGuideSuccess(SceneHelper.DomainScene((Entity)(object)self)))
			{
				self.SimpleGuide(self.CurrentId, self.StepId);
				return;
			}
			self.IsGuiding = false;
			int nextId = guideStepConfig.NextId;
			if (nextId == 0)
			{
				self.FinishGuide(self.CurrentId);
				self.CurrentId = 0;
				self.StepId = 0;
				self.UpdateData();
				return;
			}
			self.StepId = nextId;
			self.IngDict[self.CurrentId] = nextId;
			self.UpdateData();
			if (!guideStepConfig.DelayExecute)
			{
				guideStepConfig = ConfigSingleton<GuideStepConfigCategory>.Instance.Get(nextId);
				if (guideStepConfig.PanelName != null)
				{
					self.IsGuiding = true;
					self.SimpleGuide(self.CurrentId, self.StepId);
				}
			}
		}

		private static void UpdateData(this GuideComponent self)
		{
			if (((Entity)(object)self).LocalPlayer() != null)
			{
				((Entity)((Entity)(object)self).LocalPlayer()).GetComponent<GuideModule>().ReqStartGuide(self.CurrentId, self.StepId);
			}
		}

		public static bool SimpleGuide(this GuideComponent self, int id, int stepId)
		{
			UIManager.Instance.Remove(typeof(UIGuidePanel));
			GuideStepConfig guideStepConfig = ConfigSingleton<GuideStepConfigCategory>.Instance.Get(stepId);
			string panelName = guideStepConfig.PanelName;
			if (panelName == null)
			{
				return false;
			}
			IUI iUI = UIObject.FindUIObjectOfType(UIManager.Instance.UITypeName.GetKeyByValue(panelName));
			if (iUI == null)
			{
				return false;
			}
			if (!UIManager.Instance.IsTop(iUI, guideStepConfig.IsClose))
			{
				return false;
			}
			self.CurrentId = id;
			self.StepId = stepId;
			self.IsGuiding = true;
			self.UpdateData();
			int key = self.StepId;
			if (guideStepConfig.AIId != 0)
			{
				key = guideStepConfig.AIId;
			}
			if (self.StepHandlers.ContainsKey(key))
			{
				AGuideStepHandler value = self.StepHandlers.GetValue(key);
				switch (value.IsCan(SceneHelper.DomainScene((Entity)(object)self)))
				{
				case GuideStepStatus.Success:
					value.Handler(SceneHelper.DomainScene((Entity)(object)self)).Coroutine();
					break;
				case GuideStepStatus.Next:
					self.NextGuide();
					break;
				}
				return true;
			}
			UIManager.Instance.Show<UIGuidePanel, int>(self.StepId).Coroutine();
			return true;
		}

		public static int GetStepId(this GuideComponent self, int id)
		{
			if (self.IngDict.ContainsKey(id))
			{
				return self.IngDict.GetValue(id);
			}
			return 0;
		}

		public static void SetStepId(this GuideComponent self, int stepId)
		{
			if (stepId != 0)
			{
				self.StepId = stepId;
				self.IsGuiding = true;
			}
		}

		public static bool IsFinish(this GuideComponent self, int id)
		{
			if (self.FinishList.IndexOf(id) == -1)
			{
				return false;
			}
			return true;
		}

		public static void TestHandler(this GuideComponent self, int guideId)
		{
			self.IngDict.Clear();
			self.OpenList.Clear();
			GuideConfig guideConfig = ConfigSingleton<GuideConfigCategory>.Instance.Get(guideId);
			self.IngDict.Add(guideId, guideConfig.FirstStep);
			self.ExecuteGuide();
		}

		public static void ClearGuide(this GuideComponent self, int guideId)
		{
			if (self.IngDict.ContainsKey(guideId))
			{
				self.IngDict.Remove(guideId);
				if (guideId == self.CurrentId)
				{
					self.CurrentId = 0;
					self.StepId = 0;
					self.IsGuiding = false;
					UIManager.Instance.Remove(typeof(UIGuidePanel));
				}
			}
		}
	}
