		public static void UpdateNavigationState(this RedPointNavigation self)
		{
			if (self.RedPointIndices.Count == 0)
			{
				SetNavigationVisibility(self, showPrev: false, showNext: false);
				return;
			}
			int num = int.MaxValue;
			int num2 = int.MinValue;
			foreach (int redPointIndex in self.RedPointIndices)
			{
				num = Mathf.Min(num, redPointIndex);
				num2 = Mathf.Max(num2, redPointIndex);
			}
			self.NearestPrevRedPointIndex = -1;
			self.NearestNextRedPointIndex = -1;
			foreach (int redPointIndex2 in self.RedPointIndices)
			{
				if (redPointIndex2 < self.MinVisibleIndex && (self.NearestPrevRedPointIndex < 0 || redPointIndex2 > self.NearestPrevRedPointIndex))
				{
					self.NearestPrevRedPointIndex = redPointIndex2;
				}
				if (redPointIndex2 > self.MaxVisibleIndex && (self.NearestNextRedPointIndex < 0 || redPointIndex2 < self.NearestNextRedPointIndex))
				{
					self.NearestNextRedPointIndex = redPointIndex2;
				}
			}
			bool showPrev = self.NearestPrevRedPointIndex >= 0 && self.MinVisibleIndex > num;
			bool showNext = self.NearestNextRedPointIndex >= 0 && self.MaxVisibleIndex < num2;
			SetNavigationVisibility(self, showPrev, showNext);
		}

		private static bool IsChildFullyVisible(RectTransform child, RectTransform viewport)
		{
			if ((Object)(object)child == (Object)null || (Object)(object)viewport == (Object)null)
			{
				return false;
			}
			Vector3[] array = (Vector3[])(object)new Vector3[4];
			viewport.GetWorldCorners(array);
			Vector3[] array2 = (Vector3[])(object)new Vector3[4];
			child.GetWorldCorners(array2);
			float num = Mathf.Min(new float[4]
			{
				array[0].x,
				array[1].x,
				array[2].x,
				array[3].x
			});
			float num2 = Mathf.Max(new float[4]
			{
				array[0].x,
				array[1].x,
				array[2].x,
				array[3].x
			});
			float num3 = Mathf.Min(new float[4]
			{
				array[0].y,
				array[1].y,
				array[2].y,
				array[3].y
			});
			float num4 = Mathf.Max(new float[4]
			{
				array[0].y,
				array[1].y,
				array[2].y,
				array[3].y
			});
			float num5 = Mathf.Min(new float[4]
			{
				array2[0].x,
				array2[1].x,
				array2[2].x,
				array2[3].x
			});
			float num6 = Mathf.Max(new float[4]
			{
				array2[0].x,
				array2[1].x,
				array2[2].x,
				array2[3].x
			});
			float num7 = Mathf.Min(new float[4]
			{
				array2[0].y,
				array2[1].y,
				array2[2].y,
				array2[3].y
			});
			float num8 = Mathf.Max(new float[4]
			{
				array2[0].y,
				array2[1].y,
				array2[2].y,
				array2[3].y
			});
			ScrollRect componentInParent = ((Component)viewport).GetComponentInParent<ScrollRect>();
			if ((Object)(object)componentInParent == (Object)null)
			{
				return false;
			}
			float num9 = 0.1f;
			if (componentInParent.horizontal)
			{
				if (!componentInParent.vertical)
				{
					if (num5 >= num - num9)
					{
						return num6 <= num2 + num9;
					}
					return false;
				}
			}
			else if (componentInParent.vertical)
			{
				if (num7 >= num3 - num9)
				{
					return num8 <= num4 + num9;
				}
				return false;
			}
			return false;
		}

