		private static void ScrollToItemIndex(RedPointNavigation self, int index)
		{
			//IL_00a5: Unknown result type (might be due to invalid IL or missing references)
			//IL_00aa: Unknown result type (might be due to invalid IL or missing references)
			//IL_00be: Unknown result type (might be due to invalid IL or missing references)
			//IL_00c3: Unknown result type (might be due to invalid IL or missing references)
			//IL_0116: Unknown result type (might be due to invalid IL or missing references)
			//IL_011b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0130: Unknown result type (might be due to invalid IL or missing references)
			//IL_0135: Unknown result type (might be due to invalid IL or missing references)
			//IL_00d9: Unknown result type (might be due to invalid IL or missing references)
			//IL_0146: Unknown result type (might be due to invalid IL or missing references)
			if ((Object)(object)self.ScrollRect == (Object)null || (Object)(object)self.ScrollRect.content == (Object)null || (Object)(object)self.ScrollRect.viewport == (Object)null)
			{
				return;
			}
			if (self.UIScrollList != null)
			{
				self.UIScrollList.MovePanelToItemIndex(index);
			}
			else
			{
				if (index < 0 || index >= ((Transform)self.ScrollRect.content).childCount)
				{
					return;
				}
				Transform child = ((Transform)self.ScrollRect.content).GetChild(index);
				RectTransform val = (RectTransform)(object)((child is RectTransform) ? child : null);
				if ((Object)(object)val == (Object)null)
				{
					return;
				}
				Rect rect;
				if (self.ScrollRect.vertical)
				{
					rect = self.ScrollRect.content.rect;
					float height = ((Rect)(ref rect)).height;
					rect = self.ScrollRect.viewport.rect;
					float height2 = ((Rect)(ref rect)).height;
					if (height > height2)
					{
						float num = 1f - val.anchoredPosition.y / (height - height2);
						self.ScrollRect.verticalNormalizedPosition = Mathf.Clamp01(num);
					}
				}
				else if (self.ScrollRect.horizontal)
				{
					rect = self.ScrollRect.content.rect;
					float width = ((Rect)(ref rect)).width;
					rect = self.ScrollRect.viewport.rect;
					float width2 = ((Rect)(ref rect)).width;
					if (width > width2)
					{
						float num2 = val.anchoredPosition.x / (width - width2);
						self.ScrollRect.horizontalNormalizedPosition = Mathf.Clamp01(num2);
					}
				}
				self.NeedRefreshVisibility = true;
			}
		}

