	public static class ShortcutKeyComponentSystem
	{
		public class UpdateSystem : UpdateSystem<ShortcutKeyComponent>
		{
			protected override void Update(ShortcutKeyComponent self)
			{
				if (SDK.IsEnable)
				{
					return;
				}
				if (Input.GetKey((KeyCode)306) && Input.GetKey((KeyCode)304) && Input.GetKeyDown((KeyCode)119))
				{
					LoginHelper.Logout(SceneHelper.DomainScene((Entity)(object)self));
				}
				if (Input.GetKey((KeyCode)306) && Input.GetKey((KeyCode)304) && Input.GetKeyDown((KeyCode)116))
				{
					((Entity)(object)self).LocalPlayer().DupFight(DupType.PVPTest1).Coroutine();
				}
				if (Input.GetKey((KeyCode)306) && Input.GetKey((KeyCode)304))
				{
					Input.GetKeyDown((KeyCode)115);
				}
				if (Input.GetKey((KeyCode)271) || Input.GetKey((KeyCode)13))
				{
					UIChatInput uIChatInput = UIObject.FindUIObjectOfType<UIChatInput>();
					if (uIChatInput != null && uIChatInput.UIObject.IsActive())
					{
						uIChatInput.SetFocus();
						return;
					}
					UIGameGMPanel uIGameGMPanel = UIObject.FindUIObjectOfType<UIGameGMPanel>();
					if (uIGameGMPanel != null && uIGameGMPanel.UIObject.IsActive())
					{
						uIGameGMPanel.SetFocus();
						return;
					}
				}
				if (Input.GetKey((KeyCode)273))
				{
					UIGameGMPanel uIGameGMPanel2 = UIObject.FindUIObjectOfType<UIGameGMPanel>();
					if (uIGameGMPanel2 != null && uIGameGMPanel2.UIObject.IsActive())
					{
						uIGameGMPanel2.OnUpClick();
						return;
					}
				}
				if (Input.GetKey((KeyCode)274))
				{
					UIGameGMPanel uIGameGMPanel3 = UIObject.FindUIObjectOfType<UIGameGMPanel>();
					if (uIGameGMPanel3 != null && uIGameGMPanel3.UIObject.IsActive())
					{
						uIGameGMPanel3.OnDownClick();
						return;
					}
				}
				if (!Input.GetKeyDown((KeyCode)282) && !Input.GetKeyDown((KeyCode)283) && !Input.GetKeyDown((KeyCode)284))
				{
					return;
				}
				UIGameMsgPanel uIGameMsgPanel = UIObject.FindUIObjectOfType<UIGameMsgPanel>();
				if (uIGameMsgPanel != null)
				{
					if (Input.GetKeyDown((KeyCode)283))
					{
						uIGameMsgPanel.SetGMInput(isActive: true);
					}
					else if (Input.GetKeyDown((KeyCode)284))
					{
						uIGameMsgPanel.SetGMInput(isActive: false);
					}
					else
					{
						uIGameMsgPanel.SetGMInput();
					}
				}
			}
		}
	}
