	[SuggestTipsHandler(2)]
	public class SkillTipsHandler : ASuggestTipsHandler
	{
		public override bool IsMeet(Player player, int param1 = 0, int param2 = 0)
		{
			if (!player.IsFuncOpen(1002))
			{
				return false;
			}
			PracticeModule component = ((Entity)player).GetComponent<PracticeModule>();
			if (component.SkillLevelDict == null)
			{
				return false;
			}
			ItemModule component2 = ((Entity)player).GetComponent<ItemModule>();
			foreach (var (configId, num3) in component.SkillLevelDict)
			{
				if (num3 == 0)
				{
					continue;
				}
				int layer = PracticeHelper.GetSkillConfig(configId, num3).Layer;
				using ItemList itemList = ItemList.Create();
				int num4 = num3;
				while (true)
				{
					PracticeSkillLevelConfig skillConfig = PracticeHelper.GetSkillConfig(configId, num4);
					if (!player.CheckAllConds(skillConfig.Conds))
					{
						break;
					}
					PracticeSkillLevelConfig skillConfig2 = PracticeHelper.GetSkillConfig(configId, num4 + 1);
					if (skillConfig2 == null)
					{
						break;
					}
					itemList.AddRange(skillConfig.CostId);
					if (!component2.CheckItemNumsIsEnough(itemList))
					{
						break;
					}
					if (skillConfig2.Layer > layer)
					{
						return true;
					}
					num4++;
				}
			}
			return false;
		}
	}
